function UpdateIfLandZoneWantsSupport(tLZTeamData, iPlateau, iLandZone, iTeam, bWantDFSupport, bWantIndirectSupport)
    tLZTeamData[AiBotMap.subrefbLZWantsSupport] = (bWantDFSupport or bWantIndirectSupport)
    tLZTeamData[AiBotMap.subrefbLZWantsDFSupport] = bWantDFSupport
    tLZTeamData[AiBotMap.subrefbLZWantsIndirectSupport] = bWantIndirectSupport
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLandZonesWantingSupportByPlateau][iPlateau]) then
        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLandZonesWantingSupportByPlateau][iPlateau] = {}
    end
    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLandZonesWantingSupportByPlateau][iPlateau][iLandZone] = tLZTeamData[AiBotMap.subrefbLZWantsSupport]
end


function GetUnitPlateauAndLandZoneOverride(oUnit)
    --Return true if have changed something
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetUnitPlateauAndLandZoneOverride'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iPossiblePlateau
    local iPossibleLZ
    local iBestPlateau
    local iBestLZ
    local bFoundAlternative

    if bDebugMessages == true then LOG(sFunctionRef..': Unit position='..repru(oUnit:GetPosition())..'; Reprs of unit assigned plateau and land zone by team='..reprs(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam])..'; Unit owner='..oUnit:GetAIBrain().Nickname..'; Unit owner team='..oUnit:GetAIBrain().AiBotTeam..'; Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; TIme='..GetGameTimeSeconds()) end

    --Dont override if we are an amphibious/hover unit that is showing as on water
    local iNavPlateau
    local iNavIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition())
    if not(iNavIsland) then
        iNavPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition())
        if iNavPlateau then
            if AiBotUnitInfo.GetUnitPathingType(oUnit) == AiBotMap.refPathingTypeHover then
                if bDebugMessages == true then LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is on water and is amphibious or hover pathing, so makes sense that it doesnt have a valid land zone') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return false
            end
        end
    end

    if AiBotUtilities.IsTableEmpty(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam]) == false then
        for iTeam, tTeamPlateauAndLZ in oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam] do
            if tTeamPlateauAndLZ[2] > 0 then
                if iTeam == oUnit:GetAIBrain().AiBotTeam and AiBotUtilities.IsTableEmpty(tTeamPlateauAndLZ) == false then
                    iBestPlateau = tTeamPlateauAndLZ[1]
                    iBestLZ = tTeamPlateauAndLZ[2]
                    break
                else
                    iPossiblePlateau = tTeamPlateauAndLZ[1]
                    iPossibleLZ = tTeamPlateauAndLZ[2]
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Just considered iTeam='..iTeam..'; tTeamPlateauAndLZ='..repru(tTeamPlateauAndLZ)..'; iBestPlateau='..(iBestPlateau or 'nil')..'; iBestLZ='..(iBestLZ or 'nil')..'; iPossiblePlateau='..(iPossiblePlateau or 'nil')..'; iPossibleLZ='..(iPossibleLZ or 'nil')) end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iBestPlateau='..(iBestPlateau or 'nil')..'; iBestLZ='..(iBestLZ or 'nil')..'; iPossiblePlateau='..(iPossiblePlateau or 'nil')..'; iPossibleLZ='..(iPossibleLZ or 'nil')) end
        if iBestPlateau and iBestLZ then
            AiBotMap.AddLocationToPlateauExceptions(oUnit:GetPosition(), iBestPlateau, iBestLZ)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        elseif iPossiblePlateau and iPossibleLZ then

            AiBotMap.AddLocationToPlateauExceptions(oUnit:GetPosition(), iPossiblePlateau, iPossibleLZ)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        end
    else
        --If we look in a 2x2 box around the unit can we find a valid plateau?
        local iDistAdjust
        local tBasePosition = oUnit:GetPosition()

        for iBaseAdjust = 1, 3 do
            iDistAdjust = math.max(2, AiBotMap.iLandZoneSegmentSize) * iBaseAdjust
            local tLocationAdjust = {{-iDistAdjust,0}, {-iDistAdjust, -iDistAdjust}, {-iDistAdjust, iDistAdjust}, {0, -iDistAdjust}, {0, iDistAdjust}, {iDistAdjust, -iDistAdjust}, {iDistAdjust, 0}, {iDistAdjust,iDistAdjust}}
            if bDebugMessages == true then LOG(sFunctionRef..': Will look in a box around the unit to see if can find a valid plateau, iDistAdjust='..iDistAdjust) end
            for iEntry, tAdjustXZ in tLocationAdjust do
                iPossiblePlateau, iPossibleLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition({ tBasePosition[1] + tAdjustXZ[1], tBasePosition[2], tBasePosition[3] + tAdjustXZ[2] })
                if bDebugMessages == true then LOG(sFunctionRef..': Considering tBasePosition='..repru(tBasePosition)..'; tAdjustXZ='..repru(tAdjustXZ)..'; iPossiblePlateau='..(iPossiblePlateau or 'nil')..'; iPossibleLZ='..(iPossibleLZ or 'nil')..'; NavUtils plateau for this position='..(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, { tBasePosition[1] + tAdjustXZ[1], tBasePosition[2], tBasePosition[3] + tAdjustXZ[2] }) or 'nil')) end
                if (iPossiblePlateau or 0) > 0 and (iPossibleLZ or 0) > 0 and AiBotMap.tAllPlateaus[iPossiblePlateau][AiBotMap.subrefPlateauLandZones][iPossibleLZ] then
                    if bDebugMessages == true then LOG('Found a plateau override for oUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at position '..repru(oUnit:GetPosition())..' and tAdjustXZ='..repru(tAdjustXZ)) end
                    bFoundAlternative = true
                    AiBotMap.AddLocationToPlateauExceptions(oUnit:GetPosition(), iPossiblePlateau, iPossibleLZ)
                    break
                end
            end
            if not(bFoundAlternative) then
                --Try in a 1x1 box around the unit to see if we can find a plateau that is land pathable, and if so, see if we can path to a land zone, and if so then update to record this as the closest land zone
                iDistAdjust = 1
                tLocationAdjust = {{0,0}, {-iDistAdjust,0}, {-iDistAdjust, -iDistAdjust}, {-iDistAdjust, iDistAdjust}, {0, -iDistAdjust}, {0, iDistAdjust}, {iDistAdjust, -iDistAdjust}, {iDistAdjust, 0}, {iDistAdjust,iDistAdjust}}
                if bDebugMessages == true then LOG(sFunctionRef..': Will look in a smaller radius box around the unit to see if can find a valid plateau, iDistAdjust='..iDistAdjust) end
                for iEntry, tAdjustXZ in tLocationAdjust do
                    local tAltLocation = { tBasePosition[1] + tAdjustXZ[1], tBasePosition[2], tBasePosition[3] + tAdjustXZ[2] }
                    iPossiblePlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tAltLocation)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering tAltLocation='..repru(tAltLocation)..'; iPossiblePlateau='..(iPossiblePlateau or 'nil')..'; iPossibleLZ='..(iPossibleLZ or 'nil')..'; NavUtils land pathing label='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tAltLocation) or 'nil')..'; Is table of land zones for this plateau empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPossiblePlateau][AiBotMap.subrefPlateauLandZones]))) end
                    if (iPossiblePlateau or 0) > 0 and (NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tAltLocation) or 0) > 0 then
                        --We have a plateau, but dont have a land zone for this position even though it is pathable by land - is there a land zone for this plateau nearby that can path here?
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering nearby LZs that might be able to path here, is table of LZs empty for plateau '..iPossiblePlateau..' = '..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPossiblePlateau][AiBotMap.subrefPlateauLandZones]))) end
                        if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPossiblePlateau][AiBotMap.subrefPlateauLandZones]) == false then
                            local iClosestLZDist = 100000
                            local iClosestUnpathableLZDist = 100000
                            local iClosestUnpathableLZRef
                            local iCurLZDist
                            for iLandZone, tAltLZData in AiBotMap.tAllPlateaus[iPossiblePlateau][AiBotMap.subrefPlateauLandZones] do
                                iCurLZDist = AiBotUtilities.GetDistanceBetweenPositions(tAltLocation, AiBotMap.tAllPlateaus[iPossiblePlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMidpoint])

                                if iCurLZDist < iClosestLZDist then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Can we path from alt location to midpoint of land zone '..iLandZone..' with iCurLZDist='..iCurLZDist..'='..tostring(NavUtils.CanPathTo(AiBotMap.refPathingTypeLand, tAltLocation, AiBotMap.tAllPlateaus[iPossiblePlateau][AiBotMap.subrefPlateauLandZones][AiBotMap.subrefMidpoint]))) end
                                    if NavUtils.CanPathTo(AiBotMap.refPathingTypeLand, tAltLocation, AiBotMap.tAllPlateaus[iPossiblePlateau][AiBotMap.subrefPlateauLandZones][AiBotMap.subrefMidpoint]) then
                                        if iCurLZDist < iClosestLZDist then
                                            iClosestLZDist = iCurLZDist
                                            iPossibleLZ = iLandZone
                                        end
                                    elseif not(iPossibleLZ) and iCurLZDist < iClosestUnpathableLZDist then
                                        iClosestUnpathableLZDist = iCurLZDist
                                        iClosestUnpathableLZRef = iLandZone
                                    end
                                end
                            end
                            if not(iPossibleLZ) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Couldnt find any LZs that are actually pathable, closest unpaathable dist='..iClosestUnpathableLZDist..'; if this is within 50 then will use this') end
                                if iClosestUnpathableLZDist < 50 then
                                    iPossibleLZ = iClosestUnpathableLZRef
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': Finsihed considering alternative entries in 1x1 box, iPossiblePlateau='..(iPossiblePlateau or 'nil')..'; iPossibleLZ='..(iPossibleLZ or 'nil')..'; If couldnt find anywhere will draw this units position in red; plateau if use hover pathing='..(NavUtils.GetLabel('Hover', oUnit:GetPosition()) or 'nil'))
                        if not(iPossibleLZ) then AiBotUtilities.DrawLocation(oUnit:GetPosition(), 2) end
                    end
                    if (iPossiblePlateau or 0) > 0 and (iPossibleLZ or 0) > 0 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Identified a backup land zone override for oUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at position '..repru(oUnit:GetPosition())..' and tAdjustXZ='..repru(tAdjustXZ)..'; will add to list of exceptions, iPossibleLZ='..(iPossibleLZ or 'nil')) end
                        bFoundAlternative = true
                        AiBotMap.AddLocationToPlateauExceptions(oUnit:GetPosition(), iPossiblePlateau, iPossibleLZ)
                        break
                    end
                end
            end
            if bFoundAlternative then break end
        end

    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bFoundAlternative
end

function ConsiderAddingPlateauOverrideForUnit(oUnit)
    --If unit doesnt show as having a plateau, it isnt attached, and it is on land then have its current position assigned  to the most recent plateau
    --Note - other places will also call override, this isnt the only function
    --returns true if has added an override
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderAddingPlateauOverrideForUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local bMadeChange = false
    if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; Unit position='..repru(oUnit:GetPosition())..'; Map height='..AiBotMap.iMapWaterHeight) end
    if oUnit.IsUnitState and not(oUnit:IsUnitState('Attached')) and oUnit:GetPosition()[2] > AiBotMap.iMapWaterHeight then
        local iCurPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition())
        if bDebugMessages == true then LOG(sFunctionRef..': Unit plateau from NavUtils='..(iCurPlateau or 'nil')) end
        if (iCurPlateau or 0) <= 0 then
            bMadeChange = GetUnitPlateauAndLandZoneOverride(oUnit)
        else
            --Have a valid plateau but for some reason dont have a land zone?
            local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnit:GetPosition())
            if bDebugMessages == true then LOG(sFunctionRef..': iSegmentX-Z='..iSegmentX..'-'..iSegmentZ..'; tLandZoneBySegment[iSegmentX][iSegmentZ]='..(AiBotMap.tLandZoneBySegment[iSegmentX][iSegmentZ] or 'nil')) end
            if not(AiBotMap.tLandZoneBySegment[iSegmentX][iSegmentZ]) then
                --If units are dropped from a transport onto water then this can happen, so check that this isnt the case
                if GetTerrainHeight(oUnit:GetPosition()[1], oUnit:GetPosition()[3]) > AiBotMap.iMapWaterHeight then
                    bMadeChange = GetUnitPlateauAndLandZoneOverride(oUnit)
                    if bDebugMessages == true then LOG(sFunctionRef..': bMadeChange after checking unit plateau and LZ override='..tostring(bMadeChange)) end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Wont consider override for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' because it appears to be in a water zone') end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bMadeChange
end

function RemoveUnitFromListOfUnitsTravelingToLandZone(oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RemoveUnitFromListOfUnitsTravelingToLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oUnit[reftiPlateauAndLZToMoveTo]='..repru(oUnit[reftiPlateauAndLZToMoveTo])) end
    if oUnit[reftiPlateauAndLZToMoveTo] then
        local sUnitTableRef
        if EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout, oUnit.UnitId) then
            sUnitTableRef = AiBotMap.subrefTScoutsTravelingHere
        else
            AiBotUtilities.ErrorHandler('Need to add code for this unit category')
        end
        if sUnitTableRef then
            local iTargetPlateau = oUnit[reftiPlateauAndLZToMoveTo][1]
            local iTargetLandZone = oUnit[reftiPlateauAndLZToMoveTo][2]
            local tTravelingUnits = AiBotMap.tAllPlateaus[iTargetPlateau][AiBotMap.subrefPlateauLandZones][iTargetLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam][sUnitTableRef]
            if AiBotUtilities.IsTableEmpty(tTravelingUnits) == false then
                for iTravelUnit, oTravelUnit in tTravelingUnits do
                    if oTravelUnit == oUnit then
                        table.remove(tTravelingUnits, iTravelUnit)
                        break
                    end
                end
            end
        end
        oUnit[reftiPlateauAndLZToMoveTo] = nil
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetUnitToTravelToLandZone(oUnit, iTargetPlateau, iTargetLandZone, subrefTScoutsTravelingHere)
    --Intended for non-engineer units (engineers are handled separately)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetUnitToTravelToLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    AiBotNavy.RemoveUnitFromAnyExistingLandOrWaterZoneItWasPreviouslyTravelingTo(oUnit, subrefTScoutsTravelingHere)

    oUnit[AiBotNavy.refiWZToMoveTo] = nil
    oUnit[reftiPlateauAndLZToMoveTo] = {iTargetPlateau, iTargetLandZone}
    local tLZData = AiBotMap.tAllPlateaus[iTargetPlateau][AiBotMap.subrefPlateauLandZones][iTargetLandZone]
    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam]
    --if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; iTargetPlateau='..iTargetPlateau..'; iTargetLandZone='..iTargetLandZone..'; Is tLZData empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData))..'; Is tLZTeamData empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData))..'; Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
    if not(tLZTeamData[subrefTScoutsTravelingHere]) then tLZTeamData[subrefTScoutsTravelingHere] = {} end
    table.insert(tLZTeamData[subrefTScoutsTravelingHere], oUnit)
    if bDebugMessages == true then LOG(sFunctionRef..': About to tell unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to go to iTargetPlateau='..iTargetPlateau..'; iTargetLandZone='..iTargetLandZone..'; midpoint of LZ='..repru(tLZData[AiBotMap.subrefMidpoint])) end
    AiBotOrders.IssueTrackedMove(oUnit, tLZData[AiBotMap.subrefMidpoint], 6, false, 'TLZ'..iTargetLandZone)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateUnitPositionsAndLandZone(aiBrain, tUnits, iTeam, iRecordedPlateau, iRecordedLandZone, bUseLastKnownPosition, bAreAirUnits, tLZTeamData, bUpdateTimeOfLastEnemyPositionCheck, bAreEnemyUnits)
    --Similar to UpdateUnitPositionsAndWaterZone; Based on RemoveEntriesFromArrayAndAddToNewTableBasedOnCondition, but more complex as dont always want to add unit to a table
    --bUpdateTimeOfLastEnemyPositionCheck - if bUseLastKnownPosition is false and this is true, then updates subrefiTimeOfLastEnemyUnitPosUpdate
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateUnitPositionsAndLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iRevisedIndex = 1
    local iTableSize = table.getn(tUnits)
    local iActualPlateau, iActualLandZone
    local UpdateUnitLastKnownPosition = AiBotTeam.UpdateUnitLastKnownPosition
    local bUseActualPositionIfEnemy = false
    local bUnitIsAttached
    if bUpdateTimeOfLastEnemyPositionCheck and not(bUseLastKnownPosition) then tLZTeamData[AiBotMap.subrefiTimeOfLastEnemyUnitPosUpdate] = GetGameTimeSeconds() end
    if not(bUseLastKnownPosition) or (bUseLastKnownPosition and (tLZTeamData[AiBotMap.refiRadarCoverage] or 0) >= 70) then bUseActualPositionIfEnemy = true end
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for iRecordedPlateau='..iRecordedPlateau..' iRecordedLandZone='..iRecordedLandZone..'; bAreAirUnits='..tostring(bAreAirUnits or false)..'; bUseLastKnownPosition='..tostring(bUseLastKnownPosition or false)..'; iTableSize='..iTableSize..'; refiRadarCoverage='..(tLZTeamData[AiBotMap.refiRadarCoverage] or 0)) end

    for iOrigIndex=1, iTableSize do
        if not(tUnits[iOrigIndex]) or tUnits[iOrigIndex].Dead then
            --Remove the entry
            tUnits[iOrigIndex] = nil
        else
            --Air units - first check inside the map area (to avoid too big a load on CPU trying to locate nearby valid zones and false error messages)
            if not(bAreAirUnits) or AiBotConditions.IsLocationInMap(tUnits[iOrigIndex]:GetPosition()) then
                --Unit still valid, does it have the right plateau and land zone?
                bUnitIsAttached = tUnits[iOrigIndex]:IsUnitState('Attached')
                if bAreEnemyUnits or bUseLastKnownPosition then
                    UpdateUnitLastKnownPosition(aiBrain, tUnits[iOrigIndex], bUseActualPositionIfEnemy)
                end
                if bUseLastKnownPosition then
                    if bAreAirUnits or bUnitIsAttached then
                        iActualPlateau, iActualLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition( tUnits[iOrigIndex][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
                    else
                        iActualPlateau, iActualLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tUnits[iOrigIndex][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], true, tUnits[iOrigIndex])
                    end
                    --if bDebugMessages == true then LOG(sFunctionRef..': Are using last known position, iOrigIndex='..iOrigIndex..'; iActualPlateau='..(iActualPlateau or 'nil')..'; iActualLandZone='..(iActualLandZone or 'nil')..'; Unit='..tUnits[iOrigIndex].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tUnits[iOrigIndex])..'; bUnitIsAttached='..tostring(bUnitIsAttached)..'; bAreAirUnits='..tostring(bAreAirUnits or false)..'; Unit brain owner='..tUnits[iOrigIndex]:GetAIBrain().Nickname..'; Unit position='..repru(tUnits[iOrigIndex]:GetPosition())) end
                else
                    --Cases where can use actual position (i.e. Allied unit or special use cases where a human will likely infer an enemy unit has moved):
                    if bUnitIsAttached or bAreAirUnits then
                        iActualPlateau, iActualLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition( tUnits[iOrigIndex]:GetPosition())
                    else
                        iActualPlateau, iActualLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tUnits[iOrigIndex]:GetPosition(), true, tUnits[iOrigIndex])
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iOrigIndex='..iOrigIndex..'; iActualPlateau='..(iActualPlateau or 'nil')..'; iActualLandZone='..(iActualLandZone or 'nil')..'; Unit='..tUnits[iOrigIndex].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tUnits[iOrigIndex])..'; bUnitIsAttached='..tostring(bUnitIsAttached)..'; bAreAirUnits='..tostring(bAreAirUnits or false)..'; Unit brain owner='..tUnits[iOrigIndex]:GetAIBrain().Nickname..'; Unit position='..repru(tUnits[iOrigIndex]:GetPosition())) end
                end

                if not(iActualPlateau > 0) then
                    if not(bAreAirUnits) and not(bUnitIsAttached) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Dont have a valid actual plateau so will use the recorded plateau and land zone') end
                        iActualPlateau = iRecordedPlateau
                        iActualLandZone = iRecordedLandZone
                        --Add location to table of pathing exceptions
                        if bUseLastKnownPosition then
                            AiBotMap.AddLocationToPlateauExceptions(tUnits[iOrigIndex][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], iRecordedPlateau, iRecordedLandZone)
                        else
                            AiBotMap.AddLocationToPlateauExceptions(tUnits[iOrigIndex]:GetPosition(), iRecordedPlateau, iRecordedLandZone)
                        end
                    end
                end



                --Is the plateau and zone correct?
                if bDebugMessages == true then
                    LOG('Updating unit position for unit '..tUnits[iOrigIndex].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tUnits[iOrigIndex])..'; iRecordedPlateau='..iRecordedPlateau..'; iActualPlateau='..(iActualPlateau or 'nil')..';  iRecordedLandZone='..(iRecordedLandZone or 'nil')..'; iActualLandZone='..(iActualLandZone or 'nil')..'; Unit actual position='..repru(tUnits[iOrigIndex]:GetPosition())..'; Plateau ref using navutils of actual position='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tUnits[iOrigIndex]:GetPosition()) or 'nil')..'; Last known position='..repru(tUnits[iOrigIndex][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; Hover nav utils of unit position='..(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tUnits[iOrigIndex]:GetPosition()) or 'nil'))
                    AiBotUtilities.DrawLocation(tUnits[iOrigIndex]:GetPosition())
                end
                --If the plateau has changed, and the new one has no valid location, then update the position to the actual position (due to issue with e.g. air units where if they fly over a cliff at the point intel is lost then it causes an error when trying to add them to another zone)
                if not(iRecordedPlateau == iActualPlateau) and bUseLastKnownPosition and (iActualLandZone or 0) > 0 then
                    local tRevisedPosition = tUnits[iOrigIndex]:GetPosition()
                    tUnits[iOrigIndex][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam] = {tRevisedPosition[1], tRevisedPosition[2], tRevisedPosition[3]}
                    iActualPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tRevisedPosition)
                end
            else
                --Air unit is outside the map bounds - treat the actual plateau as the recorded plateau - i.e. just keep the air unit against this zone until it comes back inside the map
                iActualPlateau = iRecordedPlateau
                iActualLandZone = iRecordedLandZone
                if bDebugMessages == true then LOG(sFunctionRef..': Air unit outside playable area so wont change assignment, iOrigIndex='..iOrigIndex..'; iRecordedPlateau='..iRecordedPlateau..'; iActualPlateau='..(iActualPlateau or 'nil')..';  iRecordedLandZone='..(iRecordedLandZone or 'nil')..'; iActualLandZone='..(iActualLandZone or 'nil')..'; Unit actual position='..repru(tUnits[iOrigIndex]:GetPosition())..'; Plateau ref using navutils of actual position='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tUnits[iOrigIndex]:GetPosition()) or 'nil')..'; Last known position='..repru(tUnits[iOrigIndex][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; Hover nav utils of unit position='..(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tUnits[iOrigIndex]:GetPosition()) or 'nil')) end
            end
            if iRecordedPlateau == iActualPlateau and iRecordedLandZone == iActualLandZone then
                --No change needed for unit
                if (iOrigIndex ~= iRevisedIndex) then
                    tUnits[iRevisedIndex] = tUnits[iOrigIndex]
                    tUnits[iOrigIndex] = nil
                end
                iRevisedIndex = iRevisedIndex + 1
            else
                local oUnitToAdd = tUnits[iOrigIndex]
                --Want to remove the entry from this table, but then add it to the correct table
                oUnitToAdd[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam] = nil --Done here so we dont try and go through this table again when removing later on
                if iActualPlateau > 0 and iActualLandZone > 0 then
                    --AddUnitToLandZoneForBrain(aiBrain,        oUnit,      iPlateau,       iLandZone,      bIsEnemyAirUnit)
                    AiBotTeam.AddUnitToLandZoneForBrain(aiBrain, oUnitToAdd, iActualPlateau, iActualLandZone, bAreAirUnits)
                    if bDebugMessages == true then LOG('Adding unit to land zone') end
                else
                    local iWaterZone
                    if iActualPlateau > 0 then
                        local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnitToAdd:GetPosition())
                        iWaterZone = AiBotMap.tWaterZoneBySegment[iSegmentX][iSegmentZ]
                    end
                    if bDebugMessages == true then LOG('Unit water zone='..(iWaterZone or 'nil')) end
                    if iWaterZone then
                        AiBotTeam.AddUnitToWaterZoneForBrain(aiBrain, oUnitToAdd, iWaterZone, bAreAirUnits)
                    else
                        if bAreAirUnits then
                            --Get revised plateau/LZ
                            iActualPlateau, iActualLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnitToAdd:GetPosition())
                            if bDebugMessages == true then LOG(sFunctionRef..': Air unit will record in either water or land zone, iActualPlateau='..(iActualPlateau or 'nil')..'; iActualLandZone='..(iActualLandZone or 'nil')) end
                            if iActualPlateau == 0 then
                                --Water zone
                                iWaterZone = iActualLandZone
                                AiBotTeam.AddUnitToWaterZoneForBrain(aiBrain, oUnitToAdd, iWaterZone, bAreAirUnits)
                            else
                                AiBotTeam.AddUnitToLandZoneForBrain(aiBrain, oUnitToAdd, iActualPlateau, iActualLandZone, bAreAirUnits)
                            end
                        else
                            --Not sure where to record unit so call main logic
                            AiBotTeam.AssignUnitToLandZoneOrPond(aiBrain, oUnitToAdd, true)
                        end
                    end
                end

                tUnits[iOrigIndex] = nil
            end
        end
    end
    if iRevisedIndex < iTableSize then
        --table.setn(tUnits, iRevisedIndex - 1)
        for iRemovalEntry = iTableSize, iRevisedIndex, -1 do
            --if bDebugMessages == true then LOG(sFunctionRef..': removing entry '..iRemovalEntry..' from iRecordedLandZone='..iRecordedLandZone..'; Entry being removed UnitId='..(tUnits[iRemovalEntry].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tUnits[iRemovalEntry]) or 'nil')..'; iTableSize='..iTableSize..'; iRevisedIndex='..iRevisedIndex) end
            table.remove(tUnits, iRemovalEntry)
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, iRevisedIndex='..iRevisedIndex..'; Is tUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tUnits))..'; iiRecordedPlateau='..iRecordedPlateau..'; iRecordedLandZone='..iRecordedLandZone..'; GameTime='..GetGameTimeSeconds()..'; bUseLastKnownPosition='..tostring(bUseLastKnownPosition or false)..'; bUseActualPositionIfEnemy='..tostring(bUseActualPositionIfEnemy)..'; bUpdateTimeOfLastEnemyPositionCheck='..tostring(bUpdateTimeOfLastEnemyPositionCheck)) end
end

function RecordAirThreatForLandZone(tLZTeamData, iTeam, iPlateau, iLandZone)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordAirThreatForLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                                                                --GetAirThreatLevel(tUnits,                                   bEnemyUnits, bIncludeAirToAir, bIncludeGroundToAir, bIncludeAirToGround, bIncludeNonCombatAir, bIncludeAirTorpedo, bBlueprintThreat)
    tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] = AiBotUnitInfo.GetAirThreatLevel(tLZTeamData[AiBotMap.reftLZEnemyAirUnits],     true,       false,              false,              true,               false,                  false)
    tLZTeamData[AiBotMap.refiEnemyAirAAThreat] = AiBotUnitInfo.GetAirThreatLevel(tLZTeamData[AiBotMap.reftLZEnemyAirUnits],           true,       true,               false,              false,              false,                   false)
    tLZTeamData[AiBotMap.refiEnemyAirOtherThreat] = AiBotUnitInfo.GetAirThreatLevel(tLZTeamData[AiBotMap.reftLZEnemyAirUnits],        true,       false,               false,              false,              true,                   true)

    if bDebugMessages == true then LOG(sFunctionRef..': Finished updating enemy air threat values for iTeam '..iTeam..' iPlateau '..iPlateau..'; iLandZOne '..iLandZone..'; AirToGround threat='.. tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; Other air threat='..tLZTeamData[AiBotMap.refiEnemyAirOtherThreat]..'; Is table of enemy air units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]))) end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordGroundThreatForLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone)
    --Records the different types of threat for the land zone

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordGroundThreatForLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    --Track team total threat - first remove the previous entry, then add in the new entry
    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedDFThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedDFThreat] - tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]
    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedIndirectThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedIndirectThreat] - tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]
    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedMAAThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedMAAThreat] - tLZTeamData[AiBotMap.subrefLZThreatAllyMAA]
    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedGroundAAThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedGroundAAThreat] - tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at game time '..GetGameTimeSeconds()..' for iTeam='..iTeam..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
    tLZTeamData[AiBotMap.subrefThreatEnemyShield] = 0 --will change later
    --local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) then
        tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] = 0
        tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange] = nil
        tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] = 0
        tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] = nil
        tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] = 0
        tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange] = nil
        tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] = 0
        tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureIndirect] = 0
        tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] = 0
        tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] = false
        tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] = 0
    else
        local tMobileUnits = EntityCategoryFilterDown(categories.MOBILE - AiBotUnitInfo.refCategoryScathis, tLZTeamData[AiBotMap.subrefTEnemyUnits])
        local tStructures = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryScathis, tLZTeamData[AiBotMap.subrefTEnemyUnits])
        local tEnemiesExclShieldsAndFixedArti = EntityCategoryFilterDown(categories.MOBILE - AiBotUnitInfo.refCategoryMobileLandShield + categories.DIRECTFIRE, tLZTeamData[AiBotMap.subrefTEnemyUnits]) --(shield value gets added later based on the threat excl shields)
        local bHaveDangerousEnemies = false
        tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] = AiBotUnitInfo.GetCombatThreatRating(tEnemiesExclShieldsAndFixedArti, true)

        if bDebugMessages == true then
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                LOG(sFunctionRef..': Will list out every enemy unit in the zone and its threat, position, and the plateau and land zone of that position')
                for iUnit, oUnit in tLZTeamData[AiBotMap.subrefTEnemyUnits] do
                    local iUnitPlateau, iUnitZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
                    LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with % completion '..oUnit:GetFractionComplete()..' has threat '..AiBotUnitInfo.GetCombatThreatRating({ oUnit }, true)..'; AA threat='..AiBotUnitInfo.GetAirThreatLevel({ oUnit }, true, false, true, false, false, false)..'; Position='..repru(oUnit:GetPosition())..'; Dist to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])..'; iUnitPlateau='..(iUnitPlateau or 'nil')..'; iUnitZone='..(iUnitZone or 'nil'))
                end
            end
        end

        tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureIndirect] = AiBotUnitInfo.GetCombatThreatRating(tStructures, true, false, true)
        tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] = AiBotUnitInfo.GetAirThreatLevel(tLZTeamData[AiBotMap.subrefTEnemyUnits], true, false, true, false, false, false)
        tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange] = nil
        tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] = 0
        tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] = nil
        tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange] = nil
        tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] = 0
        tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] = AiBotUnitInfo.GetMassCostOfUnits(tStructures, true)
        tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] = 0

        --Increase structure value for under construction experimentals
        local tExperimentals = EntityCategoryFilterDown(categories.EXPERIMENTAL * categories.MOBILE, tLZTeamData[AiBotMap.subrefTEnemyUnits])
        if AiBotUtilities.IsTableEmpty(tExperimentals) == false then
            for iUnit, oUnit in tExperimentals do
                if oUnit:GetFractionComplete() < 1 then
                    tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] = tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * oUnit:GetFractionComplete()
                    if bDebugMessages == true then LOG(sFunctionRef..': Have under construction experimental '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' in Plateau '..iPlateau..' Zone '..iZone..'; will increase threat for this, fraction complete='..oUnit:GetFractionComplete()..'; structure threat after increase='..tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]) end
                end
            end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Plateau '..iPlateau..' LZ '..iLandZone..' has enemy units, Enemy combat total='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; Is table of enemy structures empty='..tostring(AiBotUtilities.IsTableEmpty(tStructures))..'; Is tMobileUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tMobileUnits))) end
        local iCurThreat
        if AiBotUtilities.IsTableEmpty(tMobileUnits) == false then
            for iUnit, oUnit in tMobileUnits do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; Indirect range='..(oUnit[AiBotUnitInfo.refiIndirectRange] or 'nil')..'; Combat threat rating='..AiBotUnitInfo.GetCombatThreatRating({ oUnit }, true)) end
                if (oUnit[AiBotUnitInfo.refiDFRange] > 0 or oUnit[AiBotUnitInfo.refiIndirectRange]) and oUnit:GetFractionComplete() >= 0.9 then
                    iCurThreat = AiBotUnitInfo.GetCombatThreatRating({ oUnit }, true)
                    if iCurThreat > 0 then
                        if oUnit[AiBotUnitInfo.refiDFRange] > 0 then
                            if not(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]) then tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange] = {} end
                            tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange][oUnit[AiBotUnitInfo.refiDFRange]] = (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange][oUnit[AiBotUnitInfo.refiDFRange]] or 0) + iCurThreat
                            if not(bHaveDangerousEnemies) and iCurThreat > 10 then bHaveDangerousEnemies = true end
                            tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] = tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] + iCurThreat
                        end
                        if oUnit[AiBotUnitInfo.refiIndirectRange] > 0 then
                            if not(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange]) then tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange] = {} end
                            --Units that have both DF and indirect fire range, and significant threat, unless the IF range is significantly higiher than DF, reduce the threat given (one example being ACU with mod that gives it indirectfire attack)
                            if iCurThreat > 100 and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                                if oUnit[AiBotUnitInfo.refiDFRange] + 5 > oUnit[AiBotUnitInfo.refiIndirectRange] then
                                    if iCurThreat > 1000 and oUnit[AiBotUnitInfo.refiDFRange] < 50 then
                                        iCurThreat = iCurThreat * 0.2
                                    else
                                        iCurThreat = iCurThreat * 0.3
                                    end
                                elseif oUnit[AiBotUnitInfo.refiIndirectRange] < 50 then
                                    iCurThreat = iCurThreat * 0.4
                                else
                                    iCurThreat = iCurThreat * 0.6
                                end
                            end
                            tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange][oUnit[AiBotUnitInfo.refiIndirectRange]] = (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange][oUnit[AiBotUnitInfo.refiIndirectRange]] or 0) + iCurThreat
                            tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] = tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] + iCurThreat
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Enemy mobile indirect range after updating all units='..repru(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange])..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]='..repru(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange])..'; subrefLZThreatEnemyMobileDFTotal='..(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 'nil')) end
        end
        if AiBotUtilities.IsTableEmpty(tStructures) == false then
            for iUnit, oUnit in tStructures do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; with DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')) end
                if oUnit[AiBotUnitInfo.refiDFRange] > 0 and oUnit:GetFractionComplete() >= 0.9 then
                    iCurThreat = AiBotUnitInfo.GetCombatThreatRating({ oUnit }, true)
                    if bDebugMessages == true then LOG(sFunctionRef..': Structure iCurThreat='..iCurThreat) end
                    if iCurThreat > 0 then
                        if not(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) then tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] = {} end
                        tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange][oUnit[AiBotUnitInfo.refiDFRange]] = (tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange][oUnit[AiBotUnitInfo.refiDFRange]] or 0) + iCurThreat
                        if not(bHaveDangerousEnemies) and iCurThreat > 10 then bHaveDangerousEnemies = true end
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                    tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] = tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] + iThreat
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': LZ threats by range after updating for all structures='..repru(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange])) end
        end
        tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] = bHaveDangerousEnemies

        --Increase enemy threats for shield values
        local tShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryMobileLandShield, tLZTeamData[AiBotMap.subrefTEnemyUnits])
        if AiBotUtilities.IsTableEmpty(tShields) == false then
            local iCurShield, iMaxShield
            local iThreatFactor
            for iUnit, oUnit in tShields do
                if oUnit:GetFractionComplete() >= 0.9 then
                    iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, true)
                    iThreatFactor = math.max(0.1, iCurShield /  iMaxShield)
                    tLZTeamData[AiBotMap.subrefThreatEnemyShield] = tLZTeamData[AiBotMap.subrefThreatEnemyShield] + iThreatFactor * (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
                end
            end
        end
        if (tLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) >= 50 then
            local iMaxShieldRating
            if tLZTeamData[AiBotMap.subrefThreatEnemyShield] >= 4000 then
                if AiBotUtilities.bLoudModActive then --QUIET now has logic for overlapping shields to take damage and has increased recharge times
                    iMaxShieldRating = tLZTeamData[AiBotMap.subrefThreatEnemyShield]
                else
                    iMaxShieldRating = math.min(3200 + (tLZTeamData[AiBotMap.subrefThreatEnemyShield] - 4000) * 0.4, 7000) --shields wont be able to cover everywhere, and more than one shield has lower value due to FAF anti-shield stacking
                end
            else
                iMaxShieldRating = tLZTeamData[AiBotMap.subrefThreatEnemyShield]
            end
            if AiBotUtilities.bLoudModActive then
                iMaxShieldRating = iMaxShieldRating + 0.5 * math.min(5000, tLZTeamData[AiBotMap.subrefThreatEnemyShield]) --shields are really good in LOUD
            end
            local iShieldMaxFactor = 1
            if AiBotUtilities.bQuietModActive then iShieldMaxFactor = 1.25 --Az: Static shields nerfed to FAF values in QUIET; mobile shields not; since shield threat includes both will do 1.25 as a rough approximation/allowance for there potentially being mobile shields that are good for their mass cost
            elseif AiBotUtilities.bLoudModActive then iShieldMaxFactor = 4
            end
            if not(iMaxShieldRating) then
                AiBotUtilities.ErrorHandler('Dont have a max shield rating for P'..iPlateau..'LZ'..iLandZone..'; tLZTeamData[AiBotMap.subrefThreatEnemyShield]='..(tLZTeamData[AiBotMap.subrefThreatEnemyShield] or 'nil')..'; will use gross LZ value')
                iMaxShieldRating = (tLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0)
            end
            tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] = tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] + math.max(iMaxShieldRating * 0.1, math.min(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * iShieldMaxFactor, iMaxShieldRating))
            tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureIndirect] = tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureIndirect] + math.min(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureIndirect] * iShieldMaxFactor, iMaxShieldRating)
            tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] = tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] + math.min(tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] * iShieldMaxFactor, iMaxShieldRating)
            tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] = tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] + math.min(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] * iShieldMaxFactor, iMaxShieldRating * 0.6)
            tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] = tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] + math.min(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] * iShieldMaxFactor, iMaxShieldRating * 0.6)

        end

    end

    --Include long range threats
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of long range threats empty for iLandZone='..iLandZone..'='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]))) end
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false then
        local tNearbyLongRangeThreats = {}
        local iZoneDiameter = math.max(tLZData[AiBotMap.subrefLZMaxSegX] - tLZData[AiBotMap.subrefLZMinSegX], tLZData[AiBotMap.subrefLZMaxSegZ] - tLZData[AiBotMap.subrefLZMinSegZ]) * AiBotMap.iLandZoneSegmentSize
        local iRangeThreshold = math.max(iZoneDiameter * 0.8, 60)
        for iUnit, oUnit in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
            --Only include megalith if we lack similar DF or IF range
            if AiBotUnitInfo.IsUnitValid(oUnit) and (oUnit[AiBotUnitInfo.refiCombatRange] > 70 or tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange] < oUnit[AiBotUnitInfo.refiCombatRange] or (oUnit[AiBotUnitInfo.refiCombatRange] == 70 and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] >= 100 and AiBotConditions.GetBestMobileDFRangeInZone(tLZTeamData) > oUnit[AiBotUnitInfo.refiCombatRange])) then
                if bDebugMessages == true then LOG(sFunctionRef..': Long range threat unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])..'; Unit range='..(oUnit[AiBotUnitInfo.refiCombatRange] or 0)..'; iRangeThreshold='..iRangeThreshold..'; iZoneDiameter='..iZoneDiameter) end
                if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= (oUnit[AiBotUnitInfo.refiCombatRange] or 0) + iRangeThreshold then --tried 55 but proved too small
                    table.insert(tNearbyLongRangeThreats, oUnit)
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby long range threats empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyLongRangeThreats))) end
        if AiBotUtilities.IsTableEmpty(tNearbyLongRangeThreats) then tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] = 0
        else
            tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] = AiBotUnitInfo.GetCombatThreatRating(tNearbyLongRangeThreats, true)
        end
    else
        tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] = 0
    end
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeIFThreats]) then tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeIFThreat] = 0
    else
        tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeIFThreat] = AiBotUnitInfo.GetCombatThreatRating(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeIFThreats], true)
    end


    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) then
        tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] = 0
        tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] = 0
        tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] = nil
        tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] = 0
        tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange] = nil
        tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] = nil
        tLZTeamData[AiBotMap.subrefLZThreatAllyStructureIndirect] = 0
        tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] = 0
        tLZTeamData[AiBotMap.subrefLZThreatAllyMAA] = 0
        tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange] = 0
    else
        local tMobileUnits = EntityCategoryFilterDown(categories.MOBILE, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        local tStructures = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] = AiBotUnitInfo.GetCombatThreatRating(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits], false)
        tLZTeamData[AiBotMap.subrefLZThreatAllyStructureIndirect] = AiBotUnitInfo.GetCombatThreatRating(tStructures, false, false, true)
        tLZTeamData[AiBotMap.subrefLZThreatAllyMAA] = AiBotUnitInfo.GetAirThreatLevel(tMobileUnits, false, false, true, false, false, false)
        tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] = AiBotUnitInfo.GetAirThreatLevel(tStructures, false, false, true, false, false, false) + tLZTeamData[AiBotMap.subrefLZThreatAllyMAA]

        tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] = nil
        tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange] = nil
        tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] = nil
        local iCurThreat
        if bDebugMessages == true then LOG(sFunctionRef..': Calculating threat by range for allied units, is tMobileUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tMobileUnits))..'; is tStructures empty='..tostring(AiBotUtilities.IsTableEmpty(tStructures))) end
        if AiBotUtilities.IsTableEmpty(tMobileUnits) == false then
            for iUnit, oUnit in tMobileUnits do
                if oUnit:GetFractionComplete() >= 1 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; refiDFRange='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; IndirectRange='..(oUnit[AiBotUnitInfo.refiIndirectRange] or 'nil')..'; Unit combat rating='..AiBotUnitInfo.GetCombatThreatRating({ oUnit }, false)) end
                    if oUnit[AiBotUnitInfo.refiDFRange] > 0 or oUnit[AiBotUnitInfo.refiIndirectRange] > 0 then
                        iCurThreat = AiBotUnitInfo.GetCombatThreatRating({ oUnit }, false, nil, (oUnit[AiBotUnitInfo.refiDFRange] or 0) == 0)
                        if iCurThreat > 0 then
                            if oUnit[AiBotUnitInfo.refiDFRange] > 0 then
                                if not(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange]) then tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] = {} end
                                tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange][oUnit[AiBotUnitInfo.refiDFRange]] = (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange][oUnit[AiBotUnitInfo.refiDFRange]] or 0) + iCurThreat
                            end
                            if oUnit[AiBotUnitInfo.refiIndirectRange] > 0 then
                                if not(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange]) then tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange] = {} end
                                tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange][oUnit[AiBotUnitInfo.refiIndirectRange]] = (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange][oUnit[AiBotUnitInfo.refiIndirectRange]] or 0) + iCurThreat
                            end
                        end
                    end
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tStructures) == false then
            for iUnit, oUnit in tStructures do
                if oUnit[AiBotUnitInfo.refiDFRange] > 0 and oUnit:GetFractionComplete() >= 1 then
                    iCurThreat = AiBotUnitInfo.GetCombatThreatRating({ oUnit }, true)
                    if iCurThreat > 0 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Recording PD threat of oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurThreat='..iCurThreat..'; DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; iUnit='..iUnit) end
                        if not(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) then tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] = {} end
                        tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange][oUnit[AiBotUnitInfo.refiDFRange]] = (tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange][oUnit[AiBotUnitInfo.refiDFRange]] or 0) + iCurThreat
                    end
                end
            end
        end
        --Update total DF and indirect threat
        tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] = 0
        tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] = 0
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange]) == false then
            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] do
                tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] = tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] + iThreat
            end
        end
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange]) == false then
            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange] do
                tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] = tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] + iThreat
            end
        end

        --Update combat range
        local iBestRange = 0
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                iBestRange = math.max(iBestRange, iRange)
            end
        end
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange]) == false then
            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] do
                iBestRange = math.max(iBestRange, iRange)
            end
        end
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange]) == false then
            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange] do
                iBestRange = math.max(iBestRange, iRange)
            end
        end
        tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange] = iBestRange

        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedDFThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedDFThreat] + tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]
        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedIndirectThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedIndirectThreat] + tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]
        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedMAAThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedMAAThreat] + tLZTeamData[AiBotMap.subrefLZThreatAllyMAA]
        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedGroundAAThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedGroundAAThreat] + tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]
    end

    --Add non-AiBot teammate defences
    if AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.subreftoTeammateFixedDF]) then
        local iAlliedFixedDF = 0
        for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoTeammateFixedDF] do
            iAlliedFixedDF = iAlliedFixedDF + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
        end
        tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] = tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] + iAlliedFixedDF
        if bDebugMessages == true then LOG(sFunctionRef..': Increasing combat threat for zone '..iLandZone..' for DF by '..iAlliedFixedDF) end
    end
    if AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.subreftoTeammateFixedAA]) then
        local iAlliedFixedAA = 0
        for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoTeammateFixedAA] do
            iAlliedFixedAA = iAlliedFixedAA + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
        end
        tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] = tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] + iAlliedFixedAA
        if bDebugMessages == true then LOG(sFunctionRef..': Increasing AA allied threat for zone '..iLandZone..' by '..iAlliedFixedAA) end
    end
    local bNearbyEnemies = false

    if bDebugMessages == true then LOG(sFunctionRef..': Considering if enemy units in this or adjacent LZ, is table of enemy units for this LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Adjacent LZs='..repru(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZAdjacentLandZones]))) end
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
        bNearbyEnemies = true
    else
        --, iPlateau, iLandZone
        if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZAdjacentLandZones]) == false then
            for _, iAdjLZ in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZAdjacentLandZones] do
                --NEED to flag as nearby enemies if any enemy units in the LZ, or else can cause problems where we try to attack a unit in an adjacent land zone, and then think there is no such unit due to this flag if it is only based on combat threat
                if bDebugMessages == true then LOG(sFunctionRef..': Enemy combat threat for adjacent LZ iAdjLZ='..iAdjLZ..'; threat='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal]) end
                if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]) == false then
                    bNearbyEnemies = true
                    break
                end
            end
        end
    end

    --Calculate core DF and indirect wanted just for this LZ:
    if bNearbyEnemies then
        local iEnemyStructureThreat = 0
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                iEnemyStructureThreat = iEnemyStructureThreat + iThreat
            end
        end
        tLZTeamData[AiBotMap.subrefLZIndirectThreatWanted] = iEnemyStructureThreat * 2 + tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureIndirect] * 2
        tLZTeamData[AiBotMap.subrefLZDFThreatWanted] = math.max(200, tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 2)
    else
        tLZTeamData[AiBotMap.subrefLZDFThreatWanted] = 0
        tLZTeamData[AiBotMap.subrefLZIndirectThreatWanted] = 0
    end

    --If we have no friendly combat units and enemy has combat threat, then request less MAA, or none if we have no non-MAA/scout units
    if bDebugMessages == true then LOG(sFunctionRef..': Setting the MAA level wanted for iLandZone='..iLandZone..'; tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]='..tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]..'; tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; tLZTeamData[AiBotMap.refiEnemyAirOtherThreat]='..tLZTeamData[AiBotMap.refiEnemyAirOtherThreat]..'; Is table of allied units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))..'; subrefLZSValue='..tLZTeamData[AiBotMap.subrefLZSValue]..'; subrefLZTThreatAllyCombatTotal='..tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]) end
    if tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < 11 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= math.min(1500, tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 0.9) or tLZTeamData[AiBotMap.subrefLZbCoreBase] then
        tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] = math.max(tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] * 0.65 + tLZTeamData[AiBotMap.refiEnemyAirAAThreat] * 0.15 + tLZTeamData[AiBotMap.refiEnemyAirOtherThreat] * 0.15, tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] * 0.1)
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] <= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 and tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] < 600 then
            if tLZTeamData[AiBotMap.subrefLZSValue] >= 600 or tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 1200 then
                tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] = 600
            end
        end
    elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
        local bHaveAlliedNonMAAOrScout = false
        local bHaveAlliedMAA = false
        for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] do
            if EntityCategoryContains(AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryStructure - AiBotUnitInfo.refCategoryMAA - AiBotUnitInfo.refCategoryLandScout, oUnit.UnitId) then
                bHaveAlliedNonMAAOrScout = true
                break
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMAA, oUnit.UnitId) then
                bHaveAlliedMAA = true
            end
        end -- AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryStructure - AiBotUnitInfo.refCategoryMAA - AiBotUnitInfo.refCategoryLandScout, subreftoLZOrWZAlliedUnits
        if bDebugMessages == true then LOG(sFunctionRef..': bHaveAlliedMAA='..tostring(bHaveAlliedMAA)..'; bHaveAlliedNonMAAOrScout='..tostring(bHaveAlliedNonMAAOrScout)) end
        if bHaveAlliedNonMAAOrScout or (bHaveAlliedMAA and tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0) then
            --SIgnificantly less MAA for dealing with non-air to ground threats
            if tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 then
                tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] = math.max(tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat], (tLZTeamData[AiBotMap.refiEnemyAirOtherThreat] + tLZTeamData[AiBotMap.refiEnemyAirAAThreat]) * 0.075, tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] * 0.2)
            else
                tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] = math.max((tLZTeamData[AiBotMap.refiEnemyAirOtherThreat] + tLZTeamData[AiBotMap.refiEnemyAirAAThreat]) * 0.075, tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] * 0.1)
            end
        else
            tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] = 0
        end
    else
        tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] = 0
    end

    --Increase MAA wanted if we have ACU in the LZ
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) == false then
        local tiMAAByTechForACU = {100, 400, 1000}
        if tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 then
            tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] = tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] + math.min(1600, tiMAAByTechForACU[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 2)
        else
            tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] = tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] + tiMAAByTechForACU[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finsihed recording MAA Wanted='..(tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] or 'nil')..'; will treat as 0 if less than 10') end
    if (tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] or 0) < 10 then tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] = 0 end



    --Update if have enemies in adjacent WZ
    tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] = false
    tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] = false
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
        local iAdjWZ, iPond
        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
            iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
            iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
            local tWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
            if (tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= 20 and tWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] > 0 then
                tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] = true
                tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] = true
                break
            elseif AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] = true
            end
        end
    end

    tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] = bNearbyEnemies
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]='..repru(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange])..'; bNearbyEnemies='..tostring(bNearbyEnemies)..'; Allied combat='..(tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 'nil')..'; tLZTeamData[AiBotMap.subrefLZMAAThreatWanted]='..tLZTeamData[AiBotMap.subrefLZMAAThreatWanted]..'; tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; tLZTeamData[AiBotMap.refiEnemyAirOtherThreat]='..tLZTeamData[AiBotMap.refiEnemyAirOtherThreat]) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RunFromEnemy(oUnitToRun, oEnemy, iTeam, iPlateau, iDistanceToRun)
    --NOTE: Used by waterzone logic as well for scouts to run

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RunFromEnemy'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    oUnitToRun[AiBotUnitInfo.refiTimeLastTriedRetreating] = GetGameTimeSeconds()

    local iAngleFromEnemy = AiBotUtilities.GetAngleFromAToB(oEnemy:GetPosition(), oUnitToRun:GetPosition())
    --MoveInDirection(tStart, iAngle,           iDistance, bKeepInMapBounds, bTravelUnderwater, bKeepInCampaignPlayableArea)
    local tPotentialRunPosition = AiBotUtilities.MoveInDirection(oUnitToRun:GetPosition(), iAngleFromEnemy, iDistanceToRun, false,             false,              false)
    local tNextRunPosition = AiBotUtilities.MoveInDirection(oUnitToRun:GetPosition(), iAngleFromEnemy, iDistanceToRun + math.max(8, math.min(20, iDistanceToRun)), false,             false,              false)
    local bAmphibious = EntityCategoryContains(AiBotUnitInfo.refCategoryAmphibious + categories.HOVER, oUnitToRun.UnitId)
    local iCurIsland
    function IsPositionValid(tPosition)
        if AiBotConditions.IsLocationInPlayableArea(tPosition) then
            if bAmphibious and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPosition) == iPlateau then
                return true
            elseif not(bAmphibious) then
                if not(iCurIsland) then iCurIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oUnitToRun:GetPosition()) end
                if iCurIsland == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tPosition) then
                    return true
                end

            end
        end
    end
    local bCurPositionValid = IsPositionValid(tPotentialRunPosition)
    local bNextPositionValid = IsPositionValid(tNextRunPosition)
    if bDebugMessages == true then LOG(sFunctionRef..': bCurPositionValid='..tostring(bCurPositionValid)..'; bNextPositionValid='..tostring(bNextPositionValid)) end
    if not(bCurPositionValid) or not(bNextPositionValid) then
        --Consider running slightly towards the nearest rally point
        if bDebugMessages == true then LOG(sFunctionRef..': Dont have a valid run position so will try and run to the rally point instead') end
        local iUnitPlateau, iUnitZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnitToRun:GetPosition())
        local tRallyPoint
        if (iUnitZone or 0) > 0 then
            local tLZOrWZData

            if iUnitPlateau == 0 then
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iUnitZone]][AiBotMap.subrefPondWaterZones][iUnitZone]
                tRallyPoint = AiBotNavy.GetNearestWaterRallyPoint(tLZOrWZData, iTeam, AiBotMap.tiPondByWaterZone[iUnitZone], iUnitZone)
            else
                tLZOrWZData = AiBotMap.tAllPlateaus[iUnitPlateau][AiBotMap.subrefPlateauLandZones][iUnitZone]
                tRallyPoint = GetNearestLandRallyPoint(tLZOrWZData, iTeam, iUnitPlateau, iUnitZone, 2, EntityCategoryContains(categories.HOVER + AiBotUnitInfo.refCategoryAmphibious, oUnitToRun.UnitId))
            end

        else
            --Run to the unit's brain's start position
            tRallyPoint = AiBotMap.PlayerStartPoints[oUnitToRun:GetAIBrain():GetArmyIndex()]
        end

        local iAngleToRally = AiBotUtilities.GetAngleFromAToB(tPotentialRunPosition, tRallyPoint)
        local iTurnSize = 30
        local iTurnAngleAdjust
        if AiBotUtilities.GetAngleDifference(iAngleFromEnemy + iTurnSize, iAngleToRally) <= AiBotUtilities.GetAngleDifference(iAngleFromEnemy - iTurnSize, iAngleToRally) then
            iTurnAngleAdjust = iTurnSize
        else
            iTurnAngleAdjust = -iTurnSize
        end
        tPotentialRunPosition = AiBotUtilities.MoveInDirection(oUnitToRun:GetPosition(), iAngleFromEnemy + iTurnAngleAdjust, iDistanceToRun, false,             false,              false)
        if bDebugMessages == true then LOG(sFunctionRef..': If try turning towards rally slightly is it valid? iTurnAngleAdjust='..iTurnAngleAdjust..'; Is position valid='..tostring(IsPositionValid(tPotentialRunPosition) or false)) end
        if not(IsPositionValid(tPotentialRunPosition)) then
            if bNextPositionValid then
                if bDebugMessages == true then LOG(sFunctionRef..': Next position is valid so will just try traveling there and hope its only a small detour') end
                tPotentialRunPosition = tNextRunPosition
            elseif iDistanceToRun < 7 then
                if bDebugMessages == true then LOG(sFunctionRef..': Will go to rally instead') end
                tPotentialRunPosition = {tRallyPoint[1], tRallyPoint[2], tRallyPoint[3]}
            else
                --Try shorter distance
                tPotentialRunPosition = AiBotUtilities.MoveInDirection(oUnitToRun:GetPosition(), iAngleFromEnemy + iTurnAngleAdjust * 1.6, iDistanceToRun * 0.5, false,             false,              false)
                if bDebugMessages == true then LOG(sFunctionRef..': Trying shorter dist and bigger angle, is revised tPotentialRunPosition valid='..tostring(IsPositionValid(tPotentialRunPosition) or false)) end
                if not(IsPositionValid(tPotentialRunPosition)) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Still not valid so going to rally instead') end
                    tPotentialRunPosition = {tRallyPoint[1], tRallyPoint[2], tRallyPoint[3]}
                end
            end
        end
    end



    AiBotOrders.IssueTrackedMove(oUnitToRun, tPotentialRunPosition, math.min(8, iDistanceToRun * 0.25), false, 'RunE'..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy))
    if bDebugMessages == true then LOG(sFunctionRef..': Just tried to give move order for oUnitToRun='..oUnitToRun.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToRun)..' from cur position '..repru(oUnitToRun:GetPosition())..' to position '..repru(tPotentialRunPosition)..' due to enemy '..(oEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEnemy) or 'nil')..' which is at last known position '..repru(oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; iDistanceToRun='..(iDistanceToRun or 'nil')..'; Angle to run location='..AiBotUtilities.GetAngleFromAToB(oUnitToRun:GetPosition(), tPotentialRunPosition)..'; Angle from unit ot enemy='..AiBotUtilities.GetAngleFromAToB(oUnitToRun:GetPosition(), oEnemy:GetPosition())..'; Actual last order position='..repru(oUnitToRun[AiBotOrders.reftiLastOrders][oUnitToRun[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition])..'; Unit order count='..(oUnitToRun[AiBotOrders.refiOrderCount] or 'nil')..'; GameTime='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageLandZoneScouts(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tScouts, bLandZoneContainsNonScouts)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageLandZoneScouts'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    tLZTeamData[AiBotMap.refbWantLandScout] = false
    if bDebugMessages == true then
        LOG(sFunctionRef..': Considering if we want a land scout for iPlateau '..iPlateau..'; iLandZone='..iLandZone..'; bLandZoneContainsNonScouts='..tostring(bLandZoneContainsNonScouts or false)..'; Enemy combat threat='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; Is table of land scouts traveling here empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTScoutsTravelingHere]))..'; Is table of scouts currently in this LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tScouts))..'; Time='..GetGameTimeSeconds())
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTScoutsTravelingHere]) == false then
            for iScout, oScout in tLZTeamData[AiBotMap.subrefTScoutsTravelingHere] do
                LOG(sFunctionRef..': Scout travling here oScout='..oScout.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout)..'; dist='..AiBotUtilities.GetDistanceBetweenPositions(oScout:GetPosition(), tLZData[AiBotMap.subrefMidpoint])..'; owned by ='..oScout:GetAIBrain().Nickname)
            end
        end
    end

    --Refresh list of scouts traveling here
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTScoutsTravelingHere]) == false then
        local iTableSize = table.getn(tLZTeamData[AiBotMap.subrefTScoutsTravelingHere])
        for iCurEntry = iTableSize, 1, -1 do
            if not(AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.subrefTScoutsTravelingHere][iCurEntry])) then
                table.remove(tLZTeamData[AiBotMap.subrefTScoutsTravelingHere], iCurEntry)
            end
        end
    end

    if (bLandZoneContainsNonScouts or tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 2 or (GetGameTimeSeconds() <= 420 and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 3000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] < 3)) and (tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 or tLZData[AiBotMap.subrefLZTotalSegmentCount] > 30) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTScoutsTravelingHere]) then
        --Want a land scout for htis land zone, unless we already have one traveling here; if we have available land scouts then will change this flag back to false
        if bDebugMessages == true then LOG(sFunctionRef..': Probably want scout for this zone, doing further checks, subrefbPacifistArea='..tostring(tLZData[AiBotMap.subrefbPacifistArea] or false)..'; subrefbTeamHasOmniVision='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision] or false)..'; Is midpoint in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]))..'; subrefLZbCoreBase='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase])..'; subrefTEnemyUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
        if not(tLZData[AiBotMap.subrefbPacifistArea]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision]) then
            if not(AiBotMap.bIsCampaignMap) or AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) then
                if not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                    tLZTeamData[AiBotMap.refbWantLandScout] = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; We want to get a scout for this LZ '..(iLandZone or 'nil')..' on plateau '..(iPlateau or 'nil')..' with island '..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; setting refbWantLandScout to true') end
                elseif (GetGameTimeSeconds() >= 240 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech] > 1) and tLZTeamData[AiBotMap.refiRadarCoverage] < AiBotUnitInfo.iT3RadarSize - 20 then
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts]) == false and (tLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.refiRadarCoverage] < AiBotUnitInfo.iT2RadarSize - 10) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Want scout as have priority units wanting scouts') end
                        tLZTeamData[AiBotMap.refbWantLandScout] = true
                    elseif not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData =  AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            if tAdjLZTeamData[AiBotMap.refbWantLandScout] and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts]) == false and tAdjLZTeamData [AiBotMap.refiRadarCoverage] < AiBotUnitInfo.iT2RadarSize - 20 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Adjacent zone has priority units wanting land scout so will build one here') end
                                tLZTeamData[AiBotMap.refbWantLandScout] = true
                                break
                            end
                        end
                    end
                end
            end
        end
    end

    --Do we have any land scouts that are available? if so then assign to an adjacent land zone if the adjacent zone wants scouts (exception if we have LC1 scout which we want to assign to enemy base zone if its available)
    if AiBotUtilities.IsTableEmpty(tScouts) == false then
        tLZTeamData[AiBotMap.refiTimeLastHadVisual] = GetGameTimeSeconds()
        local tAvailableScouts = {}
        local bCheckForEnemies = false
        local tEnemyUnitTablesToConsider = {}
        local bFriendlyCombatInAdjZone = false
        if AiBotUtilities.bCPUPerformanceMode then
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                table.insert(tEnemyUnitTablesToConsider, tLZTeamData[AiBotMap.reftoNearestDFEnemies])
                bCheckForEnemies = true
            end
        else
            --Check for neemies if there are any in this or adjacent land zone
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                --if tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > 0 then
                table.insert(tEnemyUnitTablesToConsider, tLZTeamData[AiBotMap.subrefTEnemyUnits])
            end

            if tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 50 then bFriendlyCombatInAdjZone = true end

            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if enemies in iAdjLZ='..iAdjLZ..'; enemy combat total='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal]) end
                    if AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal] > 0 then
                        table.insert(tEnemyUnitTablesToConsider, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits])
                    end
                    if not(bFriendlyCombatInAdjZone) and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZTThreatAllyCombatTotal] > 50 then
                        bFriendlyCombatInAdjZone = true
                    end
                end
            end
            if tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] then
                for iEntry, tPlateauAndZone in tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] do
                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[tPlateauAndZone[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndZone[2]][AiBotMap.subrefLZTeamData][iTeam]
                    if (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > 0 then
                        table.insert(tEnemyUnitTablesToConsider, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tEnemyUnitTablesToConsider) == false then bCheckForEnemies = true end
        end

        local oEnemyToRunFrom
        local oPrevEnemyToRunFrom
        local iRunThreshold --If get this close to being in range of an enemy should try to run

        if tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= math.max(5000, tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 4) then iRunThreshold = 15
        elseif tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 200 then iRunThreshold = 17
        elseif bFriendlyCombatInAdjZone then iRunThreshold = 20
        else iRunThreshold = 27
        end

        local iAttackThreshold = 35
        if bDebugMessages == true then LOG(sFunctionRef..': About to consider orders for scouts in this LZ, size of tScouts='..table.getn(tScouts)..'; bCheckForEnemies='..tostring(bCheckForEnemies)..'; Enemy combat total='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]) end
        local oEnemyToConsiderAttacking
        local iEnemyToConsiderAttackingDist
        local bConsiderAttacking = false
        local iCurDist
        local bStandAlmostStill = false
        local iActualCurDist
        local iClosestDangerousEnemy
        local oClosestDangerousEnemy
        local toEscortScouts = {}
        local bEnemyIsImmobile
        local iClosestEnemy = 1000
        local oClosestEnemy
        local iImmobileDistAdjust = math.min(iRunThreshold, 5)
        local bClosestDangerousEnemyIsImmobile
        local toNearbyEnemyGunships, bWantScoutToCloak
        for iScout, oScout in tScouts do
            if bWantScoutToCloak then bWantScoutToCloak = false end
            oEnemyToConsiderAttacking = nil
            bConsiderAttacking = false
            if not(oScout.Dead) and oScout:GetFractionComplete() == 1 then

                if bDebugMessages == true then LOG(sFunctionRef..': Considering scout '..oScout.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout)..'; bCheckForEnemies='..tostring(bCheckForEnemies)) end
                if bCheckForEnemies then
                    --Selen - if nearby enemy gunship then cloak
                    if oScout.UnitId == 'xsl0101' then
                        --Record any gunships in this and adjacent zones if not already
                        if toNearbyEnemyGunships == nil then
                            toNearbyEnemyGunships = {}
                            function CheckForEnemyGunships(tZoneTeamData)
                                if bDebugMessages == true then LOG(sFunctionRef..': Do we want to hide from air for cur zone being considered, refiEnemyAirToGroundThreat='..tZoneTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; Is table of enemy air units empty='..tostring(AiBotUtilities.IsTableEmpty(tZoneTeamData[AiBotMap.reftLZEnemyAirUnits]))) end
                                if tZoneTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 and AiBotUtilities.IsTableEmpty(tZoneTeamData[AiBotMap.reftLZEnemyAirUnits]) == false then
                                    for iAir, oAir in tZoneTeamData[AiBotMap.reftLZEnemyAirUnits] do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to cloak due to nearby gunship, oAir='..oAir.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAir)..'; Dist between scout and this='..AiBotUtilities.GetDistanceBetweenPositions(oAir:GetPosition(), oScout:GetPosition())) end
                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryGunship, oAir.UnitId) then
                                            table.insert(toNearbyEnemyGunships, oAir)
                                        end
                                    end
                                end
                            end
                            CheckForEnemyGunships(tLZTeamData)
                            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                    local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    CheckForEnemyGunships(tAdjLZTeamData, oScout)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iAjdLZ='..iAdjLZ..' for if want to run from gunships') end
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(toNearbyEnemyGunships) == false then
                            for iGunship, oGunship in toNearbyEnemyGunships do
                                if AiBotUtilities.GetDistanceBetweenPositions(oScout:GetPosition(), oGunship:GetPosition()) <= 30 + (oGunship[AiBotUnitInfo.refiCombatRange] or 20) then
                                    bWantScoutToCloak = true
                                    break
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': bWantScoutToCloak='..tostring(bWantScoutToCloak)..'; oScout[AiBotUnitInfo.refbUnitGivenCloakOrder]='..tostring(oScout[AiBotUnitInfo.refbUnitGivenCloakOrder] or false)) end
                        if bWantScoutToCloak then
                            if not(oScout[AiBotUnitInfo.refbUnitGivenCloakOrder]) then
                                AiBotUnitInfo.CloakUnit(oScout, false, true)
                            end
                        end
                    end
                    if not(bWantScoutToCloak) then
                        iClosestDangerousEnemy = 10000
                        oEnemyToRunFrom = nil
                        if (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 40 or (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0) < 30) and EntityCategoryContains(AiBotUnitInfo.refCategoryCombatScout, oScout.UnitId) and (oScout[AiBotUnitInfo.refiDFRange] or 0) >= 12 then
                            bConsiderAttacking = true
                            iEnemyToConsiderAttackingDist = 100000
                        end
                        if bDebugMessages == true and oPrevEnemyToRunFrom then LOG(sFunctionRef..': oPrevEnemyToRunFrom='..oPrevEnemyToRunFrom.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oPrevEnemyToRunFrom)..'; Dist to prev enemy='..AiBotUtilities.GetDistanceBetweenPositions(oPrevEnemyToRunFrom:GetPosition(), oScout:GetPosition())..'; Dist based on last known position='..AiBotUtilities.GetDistanceBetweenPositions(oPrevEnemyToRunFrom[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oScout:GetPosition())..'; Enemy range='..(oPrevEnemyToRunFrom[AiBotUnitInfo.refiDFRange] or 0)..'; Run threshold='..iRunThreshold..'; iLandZone='..iLandZone) end
                        if not(bConsiderAttacking) and oPrevEnemyToRunFrom and not(oPrevEnemyToRunFrom.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oPrevEnemyToRunFrom[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oScout:GetPosition()) - (oPrevEnemyToRunFrom[AiBotUnitInfo.refiDFRange] or 0) <= iRunThreshold and oPrevEnemyToRunFrom[AiBotUnitInfo.refiDFRange] <= 29 and not(EntityCategoryContains(categories.MOBILE, oPrevEnemyToRunFrom.UnitId) and not(oPrevEnemyToRunFrom:IsUnitState('Moving')) and not(oPrevEnemyToRunFrom:IsUnitState('Attacking'))) then
                            --Run from same enemy
                            oEnemyToRunFrom = oPrevEnemyToRunFrom
                        else
                            bStandAlmostStill = false
                            bClosestDangerousEnemyIsImmobile = false
                            for iUnitTable, tUnitTable in tEnemyUnitTablesToConsider do
                                for iUnit, oUnit in tUnitTable do
                                    if AiBotUnitInfo.IsUnitValid(oUnit) then

                                        if bDebugMessages == true then LOG(sFunctionRef..': Looking for enemy to run from for scout '..oScout.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout)..', considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 0)..'; Unit position='..repru(oUnit:GetPosition())..'; Unit last known position='..repru(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; Dist between last known position and scout='..AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oScout:GetPosition())..'; Actual dist using actual position='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oScout:GetPosition())..'; Is unit visible='..tostring(AiBotUnitInfo.CanSeeUnit(oScout:GetAIBrain(), oUnit))..'; Unit range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; iRunThreshold='..iRunThreshold..'; Is distance within run threshold='..tostring(AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oScout:GetPosition()) - (oUnit[AiBotUnitInfo.refiDFRange] or 0) <= iRunThreshold)..'; bConsiderAttacking='..tostring(bConsiderAttacking)..'; Unit df range='..(oUnit[AiBotUnitInfo.refiDFRange] or 0)..'; Unit build range='..(oUnit:GetBlueprint().Economy.MaxBuildDistance or 'nil')..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; iClosestEnemy='..iClosestEnemy) end
                                        if bConsiderAttacking or (((oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 or EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId))) then
                                            bEnemyIsImmobile = false
                                            if oUnit:IsUnitState('Upgrading') or oUnit:IsUnitState('BeingUpgraded') or EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) then
                                                bEnemyIsImmobile = true
                                            end
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oScout:GetPosition())
                                            if iCurDist < iClosestEnemy then
                                                iClosestEnemy = iCurDist
                                                oClosestEnemy = oUnit
                                            end
                                            --if iCurDist < iClosestFixedEnemy and
                                            if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) then
                                                iCurDist = iCurDist - (oUnit:GetBlueprint().Economy.MaxBuildDistance or 0)
                                            elseif (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                                                if EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout - AiBotUnitInfo.refCategoryCombatScout, oUnit.UnitId) and iCurDist < oUnit[AiBotUnitInfo.refiDFRange] + 2 and (not(bFriendlyCombatInAdjZone) or AiBotUnitInfo.GetUnitHealthPercent(oScout) < 0.5) then
                                                    --This means we should be far less likely to run from UEF and Aeon land scouts if we arent yet in range of them (and sometimes even if we are slightly in range)
                                                    iCurDist = iCurDist - (oUnit[AiBotUnitInfo.refiDFRange] or 0)
                                                else
                                                    iCurDist = iCurDist - (oUnit[AiBotUnitInfo.refiDFRange] or 0)
                                                end
                                                --If unit is immobile then reduce its range effective distance slightly as we will be much more aggressive in such a scenario
                                                if bEnemyIsImmobile then iCurDist = iCurDist - iImmobileDistAdjust end
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': iCurDist after adjusting for range='..iCurDist) end
                                            if iCurDist < iClosestDangerousEnemy and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout * categories.TECH3 - categories.SERAPHIM, oUnit.UnitId))  then
                                                oClosestDangerousEnemy = oUnit
                                                iClosestDangerousEnemy = iCurDist
                                                bClosestDangerousEnemyIsImmobile = bEnemyIsImmobile
                                            end
                                            if iCurDist <= iRunThreshold then
                                                oEnemyToRunFrom = oUnit
                                                if bConsiderAttacking and iCurDist >= 4 and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) and iClosestDangerousEnemy > iRunThreshold then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Decent dist until we are in range of engineer so will look to stand almost still instead of retreating') end
                                                    bStandAlmostStill = true
                                                else
                                                    bStandAlmostStill = false
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Want to run from unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' so will stop searching unless considering attacking, iClosestDangerousEnemy='..iClosestDangerousEnemy..'; iRunThreshold='..iRunThreshold..'; bConsiderAttacking='..tostring(bConsiderAttacking)) end
                                                if not(bConsiderAttacking) or (iClosestDangerousEnemy < iRunThreshold and not(bClosestDangerousEnemyIsImmobile)) then break end
                                            else
                                                --Adjust run threshold if enemy unit is moving, and facing towards us
                                                if iCurDist - 2 <= iRunThreshold and oUnit:IsUnitState('Moving') and AiBotUtilities.GetAngleDifference(AiBotUnitInfo.GetUnitFacingAngle(oUnit), AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oScout:GetPosition())) <= 15 then
                                                    oEnemyToRunFrom = oUnit
                                                    bStandAlmostStill = false
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to run as unit is facing us and still relatively close, unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' so will stop searching') end
                                                    if not(bConsiderAttacking) or iClosestDangerousEnemy < iRunThreshold then break end
                                                elseif bConsiderAttacking and ((oUnit[AiBotUnitInfo.refiDFRange] or 0) == 0 or EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout - categories.SERAPHIM, oUnit.UnitId)) and iCurDist < math.min(iAttackThreshold, iEnemyToConsiderAttackingDist, iClosestDangerousEnemy) and (not(oUnit[refoLandScoutTarget]) or iCurDist < 30) then
                                                    oEnemyToConsiderAttacking = oUnit
                                                    iEnemyToConsiderAttackingDist = iCurDist
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to consider attacking the unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' but will first check no units to run from') end
                                                else
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is too far away for us to run from it, will keep looking subject to considering if its close enough we should stand still instead, iCurDist='..iCurDist) end
                                                    if not(oEnemyToRunFrom) then
                                                        --Try to approximate case where enemy has a unit that is approaching our scout, and we are moving away, only to move back again - a human player would know to only move the scout a small bit to allow intel to catchup on the enemy unit; so will approximate that by having hte scout 'retreat' but not by much, if the enemy near
                                                        iActualCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oScout:GetPosition()) - (oUnit[AiBotUnitInfo.refiDFRange] or 0)
                                                        if iActualCurDist - 5 <= iRunThreshold and (iActualCurDist - 3.5 <= iRunThreshold or oUnit:IsUnitState('Moving'))
                                                        --If enemy has moved significantly from when we last had intel then dont run from them as we want the scout to refresh intel on that unit
                                                        and (iCurDist - iActualCurDist <= 5) then
                                                            oEnemyToRunFrom = oUnit
                                                            bStandAlmostStill = true
                                                        end
                                                    end
                                                end
                                            end

                                            --Check if about to get in range of engineer that can reclaim us - have done +8 as lower values resulted in some cases in the engineer being able to reclaim the scout
                                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) and AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oScout:GetPosition()) <= 8 + (oUnit:GetBlueprint().Economy.MaxBuildDistance or 3) then
                                            oEnemyToRunFrom = oUnit
                                            break
                                        end
                                    end
                                end
                            end
                        end
                        if bConsiderAttacking then
                            local bAttackBuildingEvenIfCloseToEnemy = false
                            if bDebugMessages == true then LOG(sFunctionRef..': bClosestDangerousEnemyIsImmobile='..tostring(bClosestDangerousEnemyIsImmobile)..'; oClosestEnemy='..(oClosestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy) or 'nil')..'; oEnemyToRunFrom='..(oEnemyToRunFrom.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToRunFrom) or 'nil')..'; iClosestDangerousEnemy='..iClosestDangerousEnemy) end
                            if bClosestDangerousEnemyIsImmobile and oClosestEnemy and oEnemyToRunFrom and not(oClosestEnemy == oEnemyToRunFrom) and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oClosestEnemy.UnitId) then
                                local iActualDistToClosestDangerousEnemy = AiBotUtilities.GetDistanceBetweenPositions(oEnemyToRunFrom:GetPosition(), oScout:GetPosition())
                                --If we move to be in range of the closest enemy building, will we be in range of the closest enemy to run from?
                                if bDebugMessages == true then LOG(sFunctionRef..': iActualDistToClosestDangerousEnemy='..iActualDistToClosestDangerousEnemy..'; iClosestEnemy='..iClosestEnemy..'; Closest enemy combat range='..(oEnemyToRunFrom[AiBotUnitInfo.refiCombatRange] or 0)..'; oEnemyToConsiderAttacking before considering if nearest unit is building='..(oEnemyToConsiderAttacking.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToConsiderAttacking) or 'nil')) end
                                if iActualDistToClosestDangerousEnemy > (oEnemyToRunFrom[AiBotUnitInfo.refiCombatRange] or 0) + 1 and iActualDistToClosestDangerousEnemy > iClosestEnemy then
                                    if not(oEnemyToConsiderAttacking == oClosestEnemy) and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryEngineer, oClosestEnemy.UnitId) and (iClosestDangerousEnemy <= iRunThreshold or not(oEnemyToConsiderAttacking)) then
                                        oEnemyToConsiderAttacking = oEnemyToConsiderAttacking
                                        if bDebugMessages == true then LOG(sFunctionRef..': Changing oEnemyToConsiderAttacking to be the nearest building to the combat scout') end
                                    end
                                    local tPotentialAttackPosition = AiBotUtilities.MoveInDirection(oClosestEnemy:GetPosition(), AiBotUtilities.GetAngleFromAToB(oClosestEnemy:GetPosition(), oScout:GetPosition()), oScout[AiBotUnitInfo.refiDFRange], true)
                                    if tPotentialAttackPosition and AiBotUtilities.GetDistanceBetweenPositions(tPotentialAttackPosition, oEnemyToRunFrom:GetPosition()) >= 1 + (oEnemyToRunFrom[AiBotUnitInfo.refiCombatRange] or 0) then
                                        bAttackBuildingEvenIfCloseToEnemy = true
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': oClosestEnemy='..oClosestEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy)..'; oEnemyToRunFrom='..oEnemyToRunFrom.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToRunFrom)..'; Dist to potential attack location from closest enemy='..AiBotUtilities.GetDistanceBetweenPositions(tPotentialAttackPosition, oEnemyToRunFrom:GetPosition())..'; bAttackBuildingEvenIfCloseToEnemy='..tostring(bAttackBuildingEvenIfCloseToEnemy)) end
                                end
                            end
                            if not(bAttackBuildingEvenIfCloseToEnemy) then
                                if iClosestDangerousEnemy - 8 <= iRunThreshold then oEnemyToConsiderAttacking = nil
                                elseif oEnemyToRunFrom and AiBotUnitInfo.GetCombatThreatRating({ oEnemyToRunFrom }, true) <= 11 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat, oEnemyToRunFrom.UnitId)) then
                                    oEnemyToConsiderAttacking = oEnemyToRunFrom
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will consider attacking unit as closest dangerous enemy is still a bit from being in our range, iClosestDangerousEnemy='..iClosestDangerousEnemy) end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Do we have a valid enemy unit to run from='..tostring(AiBotUnitInfo.IsUnitValid(oEnemyToRunFrom))..'; ENemy ID if any='..(oEnemyToRunFrom.UnitId or 'nil')..'; oEnemyToConsiderAttacking='..(oEnemyToConsiderAttacking.UnitId or 'nil')..'; iClosestDangerousEnemy='..iClosestDangerousEnemy) end
                end
                if oClosestDangerousEnemy then
                    oScout[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] = oClosestDangerousEnemy
                    if bDebugMessages == true then LOG(sFunctionRef..': setting refoClosestEnemyFromLastCloseToEnemyUnitCheck to be oClosestDangerousEnemy='..oClosestDangerousEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestDangerousEnemy)) end
                end
                if oScout.UnitId == 'xsl0101' and oEnemyToRunFrom and not(oEnemyToConsiderAttacking) and oScout[AiBotUnitInfo.refbUnitGivenCloakOrder] and not(tLZTeamData[AiBotMap.refiEnemyOmniCoverage] or 0) > 0 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Selen is cloaked so will stay cloaked instead of running') end
                    bWantScoutToCloak = true
                end
                if bWantScoutToCloak then
                    --Do nothing - already dealt with above
                elseif oEnemyToConsiderAttacking and AiBotUnitInfo.IsUnitValid(oEnemyToConsiderAttacking) then
                    tLZTeamData[AiBotMap.refbWantLandScout] = false
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemyToConsiderAttacking:GetPosition(), oScout:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': Have an enemy to attack with combat scout, oEnemyToConsiderAttacking='..oEnemyToConsiderAttacking.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToConsiderAttacking)..'; iCurDist='..iCurDist..'; oScout[AiBotUnitInfo.refbLastShotBlocked]='..tostring(oScout[AiBotUnitInfo.refbLastShotBlocked])..'; Health% of enemy to consider attacking='..AiBotUnitInfo.GetUnitHealthPercent(oEnemyToConsiderAttacking)..'; Time of last weapon event='..GetGameTimeSeconds() - (oScout[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; setting refbWantLandScout to false') end
                    if iCurDist >= 9 then
                        --Move closer if our shot is blocked and enemy isnt an engineer; also some redundancy incase our shot is blocked but isnt registering as blocked
                        if (oScout[AiBotUnitInfo.refbLastShotBlocked] or (iCurDist >= 8 and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oEnemyToConsiderAttacking.UnitId) and (AiBotUnitInfo.GetUnitHealthPercent(oEnemyToConsiderAttacking) >= 1 or oEnemyToConsiderAttacking:GetHealth() <= 10))) and (not(EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oEnemyToConsiderAttacking.UnitId)) or (iCurDist >= 5 and iCurDist > oEnemyToConsiderAttacking:GetBlueprint().Economy.MaxBuildDistance)) then
                            AiBotOrders.IssueTrackedMove(oScout, oEnemyToConsiderAttacking:GetPosition(), 4, false, 'SelSM', false)
                        else
                            AiBotOrders.IssueTrackedAttackMove(oScout, oEnemyToConsiderAttacking:GetPosition(), 4, false, 'SelSA', false)
                        end
                    else
                        --Are too close so run away temporarily
                        RunFromEnemy(oScout, oEnemyToConsiderAttacking, iTeam, iPlateau, 16)
                    end
                    oPrevEnemyToRunFrom = nil --DOnt want to bypass checking enemy units incase there is a threatening one nearby
                elseif oEnemyToRunFrom then
                    tLZTeamData[AiBotMap.refbWantLandScout] = false
                    if bDebugMessages == true then LOG(sFunctionRef..': Want scout '..oScout.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout)..' to run from oEnemyToRunFrom '..oEnemyToRunFrom.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToRunFrom)..' unless iti s a combat scout vs an engineer/mex in a low threat LZ in which case want it to attack the unit; LZ combat total='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; Scout DF range='..(oScout[AiBotUnitInfo.refiDFRange] or 'nil')..'; Do we have a combat scout='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryCombatScout, oScout.UnitId))..'; Distance to nearest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oEnemyToRunFrom:GetPosition(), oScout:GetPosition())..'; bStandAlmostStill='..tostring(bStandAlmostStill)..'; setting refbWantLandScout to false') end
                    oPrevEnemyToRunFrom = oEnemyToRunFrom
                    if bStandAlmostStill then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try and run from enemy but only a short way as want to almost stand still') end
                        RunFromEnemy(oScout, oEnemyToRunFrom, iTeam, iPlateau, 3)
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try and run from the nearest enemy') end
                        RunFromEnemy(oScout, oEnemyToRunFrom, iTeam, iPlateau, 16)
                    end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': No nearby enemy to run from, Considering if scout '..oScout.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout)..' is available; reftiPlateauAndLZToMoveTo='..repru(oScout[reftiPlateauAndLZToMoveTo])) end
                    if oScout[reftiPlateauAndLZToMoveTo] then
                        --Make scout available if its target LZ is this LZ
                        if oScout[reftiPlateauAndLZToMoveTo][2] == iLandZone and oScout[reftiPlateauAndLZToMoveTo][1] == iPlateau then
                            --Clear this unit from list of traveling units, but dont make it available as want a slight delay, so want it to be available on the next cycle
                            if bDebugMessages == true then LOG(sFunctionRef..': Scout is traveling to this land zone and is here so will clear the trackers so next cycle it is shown as available, setting refbWantLandScout to false') end
                            RemoveUnitFromListOfUnitsTravelingToLandZone(oScout)
                            tLZTeamData[AiBotMap.refbWantLandScout] = false
                        else
                            --Scout should be traveling to another land zone - if it has no orders then refresh them
                            if bDebugMessages == true then LOG(sFunctionRef..': Scout should travel to another land zone so order it to travel there') end
                            AiBotOrders.IssueTrackedMove(oScout, AiBotMap.tAllPlateaus[oScout[reftiPlateauAndLZToMoveTo][1]][AiBotMap.subrefPlateauLandZones][oScout[reftiPlateauAndLZToMoveTo][2]][AiBotMap.subrefMidpoint], 6, false, 'TLZ'..oScout[reftiPlateauAndLZToMoveTo][2])
                        end
                    elseif oScout[AiBotNavy.refiWZToMoveTo] then
                        --Scout should be traveling to another water zone - if it has no orders then refresh them
                        AiBotOrders.IssueTrackedMove(oScout, AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[oScout[AiBotNavy.refiWZToMoveTo]]][AiBotMap.subrefPondWaterZones][oScout[AiBotNavy.refiWZToMoveTo]][AiBotMap.subrefMidpoint], 6, false, 'TWZ'..oScout[AiBotNavy.refiWZToMoveTo])
                        if bDebugMessages == true then LOG(sFunctionRef..': Scout should travel to a water zone '..oScout[AiBotNavy.refiWZToMoveTo]..' so will resend the order to ensure it is still moving there') end
                    else
                        --Scout has no nearby enemies to run from, and isnt traveling to a plateau, so it should be available for use
                        if bDebugMessages == true then LOG(sFunctionRef..': Dont want to run or attack with scout and it isnt already assigned to another LZ so will aadd to table of available scouts, oScout='..oScout.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout)..'; oScout[refoLandScoutTarget]='..(oScout[refoLandScoutTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oScout[refoLandScoutTarget]) or 'nil')) end
                        if AiBotUnitInfo.GetUnitLifetimeCount(oScout) == 1 then
                            --Assign to enemy base if it is in the same island
                            local iEnemyBasePlateauOrZero, iEnemyBaseLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tLZTeamData[AiBotMap.reftClosestEnemyBase])
                            local bGoingToEnemyBase = false
                            if iEnemyBasePlateauOrZero == iPlateau and iEnemyBaseLZOrWZ then
                                local tEnemyBaseLZData = AiBotMap.tAllPlateaus[iEnemyBasePlateauOrZero][AiBotMap.subrefPlateauLandZones][iEnemyBaseLZOrWZ]
                                local tEnemyBaseLZTeamData = tEnemyBaseLZData[AiBotMap.subrefLZTeamData][iTeam]
                                if AiBotUtilities.IsTableEmpty(tEnemyBaseLZTeamData[AiBotMap.subrefTScoutsTravelingHere]) and NavUtils.GetLabel(AiBotMap.refPathingTypeLand,tLZTeamData[AiBotMap.reftClosestEnemyBase]) == tLZData[AiBotMap.subrefLZIslandRef] and (tEnemyBaseLZTeamData[AiBotMap.refbWantLandScout] or AiBotUtilities.IsTableEmpty(tEnemyBaseLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Dealing with first ever land scout so will have it prioritise enemy base for intel, iEnemyBasePlateauOrZero='..iEnemyBasePlateauOrZero..'; iEnemyBaseLZOrWZ='..iEnemyBaseLZOrWZ) end
                                    bGoingToEnemyBase = true
                                end
                            end
                            if bGoingToEnemyBase then
                                GetUnitToTravelToLandZone(oScout, iEnemyBasePlateauOrZero, iEnemyBaseLZOrWZ, AiBotMap.subrefTScoutsTravelingHere)
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Adding scout to table of available scouts; did enemy base zone want land csout='..tostring(AiBotMap.tAllPlateaus[iEnemyBasePlateauOrZero][AiBotMap.subrefPlateauLandZones][iEnemyBaseLZOrWZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refbWantLandScout] or false)..'; Was table of land scouts traveling there empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iEnemyBasePlateauOrZero][AiBotMap.subrefPlateauLandZones][iEnemyBaseLZOrWZ][AiBotMap.subrefLZTeamData][AiBotMap.subrefTScoutsTravelingHere]))) end
                                table.insert(tAvailableScouts, oScout)
                            end
                        else
                            if oScout[refoLandScoutTarget] and AiBotUnitInfo.IsUnitValid(oScout[refoLandScoutTarget]) then
                                table.insert(toEscortScouts, oScout)
                                if bDebugMessages == true then LOG(sFunctionRef..': Scout is escorting unit '..oScout[refoLandScoutTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout[refoLandScoutTarget])) end
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Will add scout to table of available scouts') end
                                table.insert(tAvailableScouts, oScout)
                            end
                        end
                    end
                end
            end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Is available scout table empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableScouts))) end

        if AiBotUtilities.IsTableEmpty(tAvailableScouts) == false then
            function AssignLandScoutToUnit(oUnitToReceiveScout)
                oUnitToReceiveScout[refoAssignedLandScout] = tAvailableScouts[1]
                tAvailableScouts[1][refoLandScoutTarget] = oUnitToReceiveScout
                table.insert(toEscortScouts, tAvailableScouts[1])
                table.remove(tAvailableScouts, 1)
                if bDebugMessages == true then LOG(sFunctionRef..': Have assigned scout to unit '..oUnitToReceiveScout.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToReceiveScout)) end
                if oUnitToReceiveScout[refbFlaggedForPriorityScout] then
                    oUnitToReceiveScout[refbFlaggedForPriorityScout] = false
                    oUnitToReceiveScout[refiTimeLastBuiltLandScoutForUnit] = nil
                    local iCurLandSubteam = oUnitToReceiveScout:GetAIBrain().AiBotLandSubteam
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tLandSubteamData[iCurLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout]) == false then
                        for iEntry, oEntry in AiBotTeam.tLandSubteamData[iCurLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout] do
                            if oEntry == oUnitToReceiveScout then
                                table.remove(AiBotTeam.tLandSubteamData[iCurLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout], iEntry)
                                break
                            end
                        end
                    end
                    --Remove from LZTeamData
                    local tUnitLZData, tUnitLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnitToReceiveScout:GetPosition(), true, iTeam)
                    if AiBotUtilities.IsTableEmpty(tUnitLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts]) == false then
                        for iEntry, oEntry in tUnitLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts] do
                            if oEntry == oUnitToReceiveScout then
                                table.remove(tUnitLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts], iEntry)
                                break
                            end
                        end
                    end
                end
            end
            --If not a core zone and have ACU in this zone that lacks a decided scout, no nearby omni, and has an upgrade with decent df range (so guncom) then assign scout to it
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) == false and not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) and tLZTeamData[AiBotMap.refiRadarCoverage] < math.min(300, math.max(200, AiBotUnitInfo.iT3RadarSize - 90)) then
                for iACU, oACU in tLZTeamData[AiBotMap.subrefAlliedACU] do
                    if not(AiBotUnitInfo.IsUnitValid(oACU[refoAssignedLandScout])) and (oACU[AiBotACU.refiUpgradeCount] or 0) > 0 and oACU[AiBotUnitInfo.refiDFRange] >= 28 then
                        AssignLandScoutToUnit(oACU)
                        if AiBotUtilities.IsTableEmpty(tAvailableScouts) then break end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished assigning to any ACU if relevant, is reftoUnitsWantingPriorityScouts empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts]))..'; is tAvailableScouts empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableScouts))) end
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts]) == false and AiBotUtilities.IsTableEmpty(tAvailableScouts) == false then
                --Do same thing with units wanting priority land scout
                for iRecorded, oRecorded in tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts] do
                    AssignLandScoutToUnit(oRecorded)
                    if AiBotUtilities.IsTableEmpty(tAvailableScouts) then break end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished assigning scouts to priority units if any, is reftoUnitsWantingPriorityScouts empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts]))..'; is tAvailableScouts empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableScouts))) end
            if AiBotUtilities.IsTableEmpty(tAvailableScouts) == false then
                --First assign any available scouts to adjacent land zones wanting scouts
                --Early game - prioritise zones with combat threat if we only have one scout available
                local bPrioritiseLandZonesWithFriendlyCombat = false
                local tFirstPlateauOrLZIfWantCombat
                if table.getn(tAvailableScouts) == 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 and (GetGameTimeSeconds() <= 360 or tLZTeamData[AiBotMap.refiRadarCoverage] <= 100) then bPrioritiseLandZonesWithFriendlyCombat = true end

                if bDebugMessages == true then LOG(sFunctionRef..': Will first allocate scouts to any adjacent land zones that want a scout. Is table of adj zones empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZAdjacentLandZones]))) end
                if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZAdjacentLandZones]) == false then
                    local bDontCheckInPlayableArea = not(AiBotMap.bIsCampaignMap)
                    for _, iAdjLZ in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZAdjacentLandZones] do
                        if bDebugMessages == true then LOG(sFunctionRef..': Consideri niAdjLZ='..iAdjLZ..'; Does this LZ want land scout='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refbWantLandScout] or false)..'; Is table of traveling scouts here empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTScoutsTravelingHere]))) end
                        local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                        if tAdjLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refbWantLandScout] and (bDontCheckInPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAdjLZData[AiBotMap.subrefMidpoint])) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will send land scout '..tAvailableScouts[1].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tAvailableScouts[1])..' to go to adjacent land zone '..iAdjLZ..' in plateau '..iPlateau) end
                            if not(tAdjLZData[AiBotMap.subrefbPacifistArea]) then
                                if not(bPrioritiseLandZonesWithFriendlyCombat) or AiBotUtilities.IsTableEmpty(tAdjLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZTAlliedCombatUnits]) == false then

                                    GetUnitToTravelToLandZone(tAvailableScouts[1], iPlateau, iAdjLZ, AiBotMap.subrefTScoutsTravelingHere)
                                    tAdjLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refbWantLandScout] = false
                                    if bDebugMessages == true then LOG(sFunctionRef..': Scout allocated to adjacent iAdjLZ='..iAdjLZ..' so flagging that zone no longer wants scouts, setting refbWantLandScout to false') end
                                    table.remove(tAvailableScouts, 1)
                                    if AiBotUtilities.IsTableEmpty(tAvailableScouts) then break end
                                else
                                    --We want to prioritise an adjacent zone wanting scouts
                                    if not(tFirstPlateauOrLZIfWantCombat) then
                                        tFirstPlateauOrLZIfWantCombat = {iPlateau, iAdjLZ}
                                    end
                                end
                            end
                        end
                    end
                    if bPrioritiseLandZonesWithFriendlyCombat and AiBotUtilities.IsTableEmpty(tAvailableScouts) == false and tFirstPlateauOrLZIfWantCombat then
                        GetUnitToTravelToLandZone(tAvailableScouts[1], tFirstPlateauOrLZIfWantCombat[1], tFirstPlateauOrLZIfWantCombat[2], AiBotMap.subrefTScoutsTravelingHere)
                        AiBotMap.tAllPlateaus[tFirstPlateauOrLZIfWantCombat[1]][AiBotMap.subrefPlateauLandZones][tFirstPlateauOrLZIfWantCombat[2]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refbWantLandScout] = false

                        if bDebugMessages == true then LOG(sFunctionRef..': Sending scout to the land zone='..tFirstPlateauOrLZIfWantCombat[2]..' so will flag it no longer wants scouts, so setting refbWantLandScout to false') end
                        table.remove(tAvailableScouts, 1)
                    end
                end
                --Now assign any remaining available scouts to adjacent water zones wanting scouts (if any)
                if AiBotUtilities.IsTableEmpty(tAvailableScouts) == false then
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                        local tAmphibiousOrHoverScouts = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAmphibious + categories.HOVER, tAvailableScouts)
                        if AiBotUtilities.IsTableEmpty(tAmphibiousOrHoverScouts) == false then
                            local iPond, iAdjWZ
                            for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                                iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                                iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
                                local tAdjWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ]
                                if tAdjWZData[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.refbWantLandScout] then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering tAmphibiousOrHoverScouts, size of table='..table.getn(tAmphibiousOrHoverScouts)) end
                                    AiBotNavy.GetUnitToTravelToWaterZone(tAmphibiousOrHoverScouts[1], iPond, iAdjWZ, AiBotMap.subrefTScoutsTravelingHere)
                                    AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam][AiBotMap.refbWantLandScout] = false
                                    local iAvailableScoutRef
                                    for iUnit, oUnit in tAvailableScouts do
                                        if oUnit == tAmphibiousOrHoverScouts[1] then
                                            iAvailableScoutRef = iUnit
                                            break
                                        end
                                    end
                                    table.remove(tAmphibiousOrHoverScouts, 1)
                                    if iAvailableScoutRef then
                                        table.remove(tAvailableScouts, iAvailableScoutRef)
                                    end
                                    if AiBotUtilities.IsTableEmpty(tAmphibiousOrHoverScouts) then
                                        break
                                    end
                                end
                            end
                        end
                    end

                    if AiBotUtilities.IsTableEmpty(tAvailableScouts) == false then
                        if bDebugMessages == true then LOG(sFunctionRef..': We still have available scouts so setting refbWantLandScout to false, value before this='..tostring(tLZTeamData[AiBotMap.refbWantLandScout])) end
                        tLZTeamData[AiBotMap.refbWantLandScout] = false
                        --Want to apply if core base, as we dont treat core bases as wanting land scouts normally, meaning if only adjacent zones are also core bases we get stuck where we think we never have any targets for land scouts on the island
                        if tLZTeamData[AiBotMap.subrefLZbCoreBase] or table.getn(tAvailableScouts) > 1 then
                            --Look for further away zones in this island wanting land scouts
                            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                                for iEntry, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                                    local tTeamTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam]
                                    if tTeamTargetLZData[AiBotMap.refbWantLandScout] then
                                        --Consider assigning to priority units wanting land scouts as a backup to normal logic
                                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts]) == false then
                                            for iCurRecorded = table.getn(tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts]), 1, -1 do
                                                local oCurRecorded = tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts][iCurRecorded]
                                                if AiBotUnitInfo.IsUnitValid(oCurRecorded) then
                                                    if AiBotUnitInfo.IsUnitValid(oCurRecorded[refoAssignedLandScout]) then --redundancy
                                                        oCurRecorded[refbFlaggedForPriorityScout] = false
                                                        oCurRecorded[refiTimeLastBuiltLandScoutForUnit] = nil
                                                        table.remove(tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts], iCurRecorded)
                                                    else
                                                        AssignLandScoutToUnit(oCurRecorded)
                                                    end
                                                end
                                            end
                                        end

                                        if bDebugMessages == true then LOG(sFunctionRef..': Getting scout '..tAvailableScouts[1].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tAvailableScouts[1])..' to go from iLandZone '..iLandZone..'; to furhter away LZ='..tPathingDetails[AiBotMap.subrefLZNumber]..'; setting refbWantLandScout to false') end
                                        GetUnitToTravelToLandZone(tAvailableScouts[1], iPlateau, tPathingDetails[AiBotMap.subrefLZNumber], AiBotMap.subrefTScoutsTravelingHere)
                                        tTeamTargetLZData[AiBotMap.refbWantLandScout] = false
                                        table.remove(tAvailableScouts, 1)
                                        if AiBotUtilities.IsTableEmpty(tAvailableScouts) then break end
                                    end
                                    --subrefLZNumber = 1 --Land zone reference number
                                    --subrefLZPath = 2 --against subrefLZPathingToOtherLandZones subtable, returns a table [x]=1,2,3...; which returns the land zone reference for each land zone that will go through on a path from these
                                    --subrefLZTravelDist = 3 --against subrefLZPathingToOtherLandZones subtable
                                end
                            end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': We only have 1 available scout, so dont want to flag that we couldnt find any land scouts') end
                        end
                        if AiBotUtilities.IsTableEmpty(tAvailableScouts) == false then
                            if table.getn(tAvailableScouts) > 1 then
                                if not(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandTimeLastFailedLandScoutByTeam][iTeam][tLZData[AiBotMap.subrefLZIslandRef]]) then
                                    if not(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandTimeLastFailedLandScoutByTeam][iTeam]) then
                                        if not(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandTimeLastFailedLandScoutByTeam]) then AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandTimeLastFailedLandScoutByTeam] = {} end
                                        AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandTimeLastFailedLandScoutByTeam][iTeam] = {}
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Have multiple available land scouts still for P'..iPlateau..'Z'..iLandZone..' at time='..GetGameTimeSeconds()..' so will record this for the island '..tLZData[AiBotMap.subrefLZIslandRef]..'; is reftoPriorityUnitsWantingLandScout empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tLandSubteamData[tAvailableScouts[1]:GetAIBrain().AiBotLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout]))) end
                                AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandTimeLastFailedLandScoutByTeam][iTeam][tLZData[AiBotMap.subrefLZIslandRef]] = GetGameTimeSeconds()
                                tLZTeamData[AiBotMap.refiSpareLandScouts] = table.getn(tAvailableScouts)
                            end
                            --If we are here then we still have available land scouts; if we have ap atrol path then patrol; if we have a mex then go here, if we have an adjcent zone go here, otherwise move randomly if we have no orders
                            for iScout, oScout in tAvailableScouts do
                                if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subreftPatrolPath]) == false then
                                    --Patrol the land zone
                                    AiBotOrders.PatrolPath(oScout, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subreftPatrolPath], false, 'SP')
                                else
                                    --Do nothing if scout is moving as maybe it landed on a segment just out of the zone it shoudl have been in
                                    if not(oScout:IsUnitState('Moving')) then
                                        AiBotOrders.UpdateRecordedOrders(oScout)
                                        if (oScout[AiBotOrders.refiOrderCount] or 0) == 0 then
                                            --Want ot get somewhere to move to as a backup
                                            if tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 then
                                                AiBotOrders.IssueTrackedMove(oScout, tLZData[AiBotMap.subrefMidpoint], 5, false, 'BackupMid')
                                            else
                                                --Do we have an adjacent LZ? If so move here
                                                if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                    GetUnitToTravelToLandZone(tAvailableScouts[1], iPlateau, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZAdjacentLandZones][1], AiBotMap.subrefTScoutsTravelingHere)
                                                else
                                                    --No adjacent LZs, and no mexes in this LZ, so just move randomly
                                                    AiBotOrders.IssueTrackedMove(oScout, AiBotUtilities.MoveInDirection(oScout:GetPosition(), math.random(1, 360), math.random(10, 30), true, false, true), 5, false, 'BackupRnd')
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(toEscortScouts) == false then
            local bRemoveAssignment = false
            for iScout, oScout in toEscortScouts do
                --If target is underwater and we are not amphibious/hover, then no longer assign
                if AiBotUnitInfo.IsUnitUnderwater(oScout[refoLandScoutTarget]) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryAmphibious + categories.HOVER, oScout.UnitId)) then
                    oScout[refoLandScoutTarget][refoAssignedLandScout] = nil
                    oScout[refoLandScoutTarget] = nil
                else
                    AiBotOrders.IssueTrackedMove(oScout, AiBotUtilities.MoveInDirection(oScout[refoLandScoutTarget]:GetPosition(), AiBotUtilities.GetAngleFromAToB(oScout[refoLandScoutTarget]:GetPosition(), oScout:GetPosition()), 8, true, false, true), 1.5, false, 'ScACU'..oScout[refoLandScoutTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout[refoLandScoutTarget]))
                end
            end
        end

    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateBestEnemyRangesForThisLandZone(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateBestEnemyRangesForThisLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    --Update best range values for enemies and allies
    local iEnemyBestMobileDFRange = 0
    local iEnemyBestStructureDFRange = 0
    local iEnemyBestMobileIndirectRange = 0

    --First get range for this land zone
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]) == false then
        for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange] do
            if iThreat > 20 then iEnemyBestMobileDFRange = math.max(iRange, iEnemyBestMobileDFRange) end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]='..repru(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange])..'; iEnemyBestMobileDFRange='..iEnemyBestMobileDFRange..'; Is table of enemy structure DF by range empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]))) end
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
        for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
            if iThreat > 20 then iEnemyBestStructureDFRange = math.max(iRange, iEnemyBestStructureDFRange) end
            if bDebugMessages == true then LOG(sFunctionRef..': iRange='..iRange..'; iThreat='..iThreat..'; iEnemyBestStructureDFRange after update='..iEnemyBestStructureDFRange) end
        end
    end
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange]) == false then
        for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange] do
            if iThreat > 20 then iEnemyBestMobileIndirectRange = math.max(iRange, iEnemyBestMobileIndirectRange) end
        end
    end
    tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] = iEnemyBestMobileDFRange
    tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] = iEnemyBestStructureDFRange
    tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] = iEnemyBestMobileIndirectRange
    if bDebugMessages == true then LOG(sFunctionRef..': End of code for iLandZone '..iLandZone..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange]='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange]) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordClosestAdjacentEnemiesAndGetBestEnemyRange(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordClosestAdjacentEnemiesAndGetBestEnemyRange'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    tLZTeamData[AiBotMap.reftoNearestDFEnemies] = {}
    tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere] = nil
    local iEnemyBestMobileDFRange = 0
    local iEnemyBestStructureDFRange = 0
    local iEnemyBestMobileIndirectRange = 0
    tLZTeamData[AiBotMap.reftoAdjacentStructuresWithHighRange] = {}

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, iTeam='..iTeam..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Enemies in this or adjacent LZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Is table of allied units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) end
    if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] or tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] then
        iEnemyBestMobileDFRange = (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0)
        iEnemyBestStructureDFRange = (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0)
        iEnemyBestMobileIndirectRange = (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] or 0)

        --Adjust the ranges to factor in adjacent land zones
        local iLowestDistUntilInRange = 10000
        local oLowestDFDistUntilInRange
        local tMidpoint = tLZData[AiBotMap.subrefMidpoint]
        local iCurDistUntilInRange
        local iEnemyPDThreshold
        --If we have friendly units in this zone, then always include units within a threshold
        local iThresholdToAlwaysIncludeInDFRange
        local iMaxDistAwayToIncludeAdjUnitInDFRange
        local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
        --local bIncludedNearestDFDueToMinRange
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            iThresholdToAlwaysIncludeInDFRange  = 0.5 * math.max(tLZData[AiBotMap.subrefLZMaxSegX] - tLZData[AiBotMap.subrefLZMinSegX], tLZData[AiBotMap.subrefLZMaxSegZ] - tLZData[AiBotMap.subrefLZMinSegZ]) * AiBotMap.iLandZoneSegmentSize
            iMaxDistAwayToIncludeAdjUnitInDFRange = iThresholdToAlwaysIncludeInDFRange + 20 --Want to include bit of an allowance as we might be managing units in the adjacent zone as well
        else
            iMaxDistAwayToIncludeAdjUnitInDFRange = 20 + 0.5 * math.max(tLZData[AiBotMap.subrefLZMaxSegX] - tLZData[AiBotMap.subrefLZMinSegX], tLZData[AiBotMap.subrefLZMaxSegZ] - tLZData[AiBotMap.subrefLZMinSegZ]) * AiBotMap.iLandZoneSegmentSize --Want to include bit of an allowance as we might be managing units in the adjacent zone as well
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Best mobile DF range for this zone only='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange]..'; Mobile structure range='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange]..'; Mobile indirect='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange]..'; Is table of adjacent LZs empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]))..'; iMaxDistAwayToIncludeAdjUnitInDFRange='..iMaxDistAwayToIncludeAdjUnitInDFRange..'; Zone X size (diameter)='..(tLZData[AiBotMap.subrefLZMaxSegX] - tLZData[AiBotMap.subrefLZMinSegX])*AiBotMap.iLandZoneSegmentSize..'; Zone Z size (diameter)='..(tLZData[AiBotMap.subrefLZMaxSegZ] - tLZData[AiBotMap.subrefLZMinSegZ]) * AiBotMap.iLandZoneSegmentSize) end
        function UpdateForAdjacentLandZone(tAltLZTeamData)
            --iEnemyBestMobileDFRange = math.max(iEnemyBestMobileDFRange, tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange])
            --iEnemyBestStructureDFRange = math.max(iEnemyBestStructureDFRange, tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange])
            --Record adjacent structures that have high (highest recorded or >=50) DF range
            if AiBotUtilities.bCPUPerformanceMode then
                iEnemyPDThreshold = 60
            else
                iEnemyPDThreshold = math.min(50, math.max(     iEnemyBestMobileDFRange,iEnemyBestStructureDFRange))
            end
            if (tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0) >= iEnemyPDThreshold and AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                local tEnemyStructures = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tAltLZTeamData[AiBotMap.subrefTEnemyUnits])
                if AiBotUtilities.IsTableEmpty(tEnemyStructures) == false then
                    for iUnit, oUnit in tEnemyStructures do
                        if (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= iEnemyPDThreshold then
                            table.insert(tLZTeamData[AiBotMap.reftoAdjacentStructuresWithHighRange], oUnit)
                        end
                    end
                end
            end
            iEnemyBestMobileIndirectRange = math.max(iEnemyBestMobileIndirectRange, tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange])
            local toNearbyExperimentalsAndDistUntilInRange = {}
            if bDebugMessages == true then LOG(sFunctionRef..': Considering adjacent LZ, Enemy mobile DF for this LZ='..tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange]..'; Mobile structure range='..tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange]..'; Mobile indirect='..tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange]..'; iThresholdToAlwaysIncludeInDFRange='..(iThresholdToAlwaysIncludeInDFRange or 'nil')) end
            if AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subrefTEnemyUnits]) == false and tAltLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 10 then
                for iUnit, oUnit in tAltLZTeamData[AiBotMap.subrefTEnemyUnits] do
                    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit[AiBotUnitInfo.refiDFRange] > 0 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout * categories.TECH1 - categories.SERAPHIM, oUnit.UnitId)) then
                        --Ignore selens that are cloaked
                        if oUnit.UnitId == 'xsl0101' and AiBotUnitInfo.GetUnitSpeed(oUnit) < 0.2 and not(AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit, false)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will ignore cloaked enemy selen') end
                        else
                            iCurDistUntilInRange = AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], tMidpoint) - oUnit[AiBotUnitInfo.refiDFRange]
                            if EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) then table.insert(toNearbyExperimentalsAndDistUntilInRange, {oUnit, iCurDistUntilInRange}) end
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' in adjacent zone and if it is close to being in range, iCurDistUntilInRange='..iCurDistUntilInRange..'; iLowestDistUntilInRange='..iLowestDistUntilInRange..'; DFRange='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; iMaxDistAwayToIncludeAdjUnitInDFRange='..iMaxDistAwayToIncludeAdjUnitInDFRange..'; Unit actual dist to this zone midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tMidpoint)) end
                            if iCurDistUntilInRange < iLowestDistUntilInRange then
                                oLowestDFDistUntilInRange = oUnit
                                iLowestDistUntilInRange = iCurDistUntilInRange
                                --if iThresholdToAlwaysIncludeInDFRange then bIncludedNearestDFDueToMinRange = iCurDistUntilInRange <= iThresholdToAlwaysIncludeInDFRange end
                            end
                            if iCurDistUntilInRange <= iMaxDistAwayToIncludeAdjUnitInDFRange then
                                if EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then
                                    if oUnit[AiBotUnitInfo.refiDFRange] > iEnemyBestMobileDFRange then iEnemyBestMobileDFRange = oUnit[AiBotUnitInfo.refiDFRange] end
                                else
                                    if oUnit[AiBotUnitInfo.refiDFRange] > iEnemyBestStructureDFRange then iEnemyBestStructureDFRange = oUnit[AiBotUnitInfo.refiDFRange] end
                                end
                                if iThresholdToAlwaysIncludeInDFRange and iCurDistUntilInRange <= iThresholdToAlwaysIncludeInDFRange then
                                    table.insert(tLZTeamData[AiBotMap.reftoNearestDFEnemies], oLowestDFDistUntilInRange)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Unit is close enough to being in range that we will include in nearest enemies') end
                                end
                            end
                        end
                    end
                end
            end
            if oLowestDFDistUntilInRange  then
                table.insert(tLZTeamData[AiBotMap.reftoNearestDFEnemies], oLowestDFDistUntilInRange)
            end
            --Include experimentals that are almost the closest unit (so our 'choose manual attack' logic works better)
            if AiBotUtilities.IsTableEmpty(toNearbyExperimentalsAndDistUntilInRange) == false then
                for iEntry, tExpSubtable in toNearbyExperimentalsAndDistUntilInRange do
                    if not(tExpSubtable[1] == oLowestDFDistUntilInRange) and tExpSubtable[2] - 20 <= math.max(5, iLowestDistUntilInRange) and (not(iThresholdToAlwaysIncludeInDFRange) or tExpSubtable[2] >= iThresholdToAlwaysIncludeInDFRange) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Adding further away experimental from adjacnet zone into table of nearest enemy DF units, Expeirmental unit='..tExpSubtable[1].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tExpSubtable[1])) end
                        table.insert(tLZTeamData[AiBotMap.reftoNearestDFEnemies], tExpSubtable[1])
                    end
                end
            end
        end
        if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
            for iEntry, iAdjLandZone in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                iLowestDistUntilInRange = 10000
                oLowestDFDistUntilInRange = nil
                UpdateForAdjacentLandZone(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLandZone][AiBotMap.subrefLZTeamData][iTeam])
            end
        end

        --Factor in non-adjacent zones that still have segments close enough to threaten this zone
        if tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] then
            for iEntry, tPlateauAndZone in tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] do
                UpdateForAdjacentLandZone(AiBotMap.tAllPlateaus[tPlateauAndZone[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndZone[2]][AiBotMap.subrefLZTeamData][iTeam])
            end
        end

        --Factor in adjacent water zones
        if bDebugMessages == true then LOG(sFunctionRef..': Is tLZData[AiBotMap.subrefAdjacentWaterZones] empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]))) end
        if tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
            local iAdjWZ, iPond, bAlreadyRecorded
            local bCheckIfRecorded = not(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]))
            for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
                local tWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjWZ='..iAdjWZ..' for iPond='..iPond..'; Enemy Combat total='..(tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..'; Is Nearest combat enemies empty='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.reftoNearestCombatEnemies]))) end
                if (tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= 20 and AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.reftoNearestCombatEnemies]) == false then
                    iEnemyBestMobileDFRange = math.max(iEnemyBestMobileDFRange, (tWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] or 0))
                    iLowestDistUntilInRange = 10000
                    oLowestDFDistUntilInRange = nil

                    for iUnit, oUnit in tWZTeamData[AiBotMap.reftoNearestCombatEnemies] do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..(oUnit:GetAIBrain().Nickname or 'nil')..' assigned to WZ='..(oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] or 'nil')..' with DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 0)) end
                        if AiBotUnitInfo.IsUnitValid(oUnit) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout, oUnit.UnitId)) then
                            iCurDistUntilInRange = AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], tMidpoint) - oUnit[AiBotUnitInfo.refiDFRange]
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurDistUntilInRange='..iCurDistUntilInRange) end
                            if iCurDistUntilInRange < iLowestDistUntilInRange then
                                oLowestDFDistUntilInRange = oUnit
                                iLowestDistUntilInRange = iCurDistUntilInRange
                            end
                            if iCurDistUntilInRange <= iMaxDistAwayToIncludeAdjUnitInDFRange and (oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] or iAdjWZ) == iAdjWZ then
                                if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to the nearestDFEnemies for this land zone '..iLandZone..' unless already recorded') end
                                bAlreadyRecorded = false
                                if bCheckIfRecorded then
                                    for iRecorded, oRecorded in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                        if oRecorded == oUnit then
                                            bAlreadyRecorded = true
                                            break
                                        end
                                    end
                                else
                                    bCheckIfRecorded = true
                                end
                                if not(bAlreadyRecorded) then
                                    table.insert(tLZTeamData[AiBotMap.reftoNearestDFEnemies], oUnit)
                                end
                            end
                        end
                    end
                    if oLowestDFDistUntilInRange and iLowestDistUntilInRange > iMaxDistAwayToIncludeAdjUnitInDFRange then --i.e. we wont have included in above logic
                        table.insert(tLZTeamData[AiBotMap.reftoNearestDFEnemies], oLowestDFDistUntilInRange)
                    end
                end
            end
        end

        --Add all units from this zone into reftoNearestDFEnemies
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] then
            for iUnit, oUnit in tLZTeamData[AiBotMap.subrefTEnemyUnits] do
                if oUnit[AiBotUnitInfo.refiDFRange] > 0 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout - categories.SERAPHIM, oUnit.UnitId)) then
                    table.insert(tLZTeamData[AiBotMap.reftoNearestDFEnemies], oUnit)
                end
            end
        end
    end

    --Record nearest enemy structure if this land zone is large enough and has no enemies (for performance reasons - dont want to risk doing this calculation on tiny zones/mini plateaus near an enemy base), and currently planned use is only for indirect fire units as a backup target
    tLZTeamData[AiBotMap.refbEnemiesInNearbyPlateau] = false
    if bDebugMessages == true then LOG(sFunctionRef..': Will check for nearby enemy structures if no enemies in this LZ, iPlateau='..iPlateau..'; iLandZOne='..iLandZone..'; Enemies in this or adj LZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Total segment count='..tLZData[AiBotMap.subrefLZTotalSegmentCount]..'; Segment size='..AiBotMap.iLandZoneSegmentSize..'; is table of other land and water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]))) end
    if not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and tLZData[AiBotMap.subrefLZTotalSegmentCount] >= 150 / AiBotMap.iLandZoneSegmentSize then
        AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData)
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
            local iClosestEnemyDist = 10000
            local oClosestEnemy
            local iCurDist
            for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iPlateauOrPond='..tSubtable[AiBotMap.subrefiPlateauOrPond]..'; Is water zone='..tostring(tSubtable[AiBotMap.subrefbIsWaterZone])..'; Distance='..tSubtable[AiBotMap.subrefiDistance]..'; iEntry='..iEntry) end
                if tSubtable[AiBotMap.subrefiDistance] >= 170 and (iEntry >= 7 or tSubtable[AiBotMap.subrefiDistance] >= 320) then break end
                if not(iPlateau == tSubtable[AiBotMap.subrefiPlateauOrPond]) and not(tSubtable[AiBotMap.subrefbIsWaterZone]) then
                    --Have a nearby land zone in a different plateau, check if there are enemy units in this LZ and (if so) if any of them are structures
                    local tAdjLZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                    if not(tAdjLZData[AiBotMap.subrefbPacifistArea]) then
                        local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                        if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                            tLZTeamData[AiBotMap.refbEnemiesInNearbyPlateau] = true
                            local tEnemyStructures = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy structures empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyStructures))) end
                            if AiBotUtilities.IsTableEmpty(tEnemyStructures) == false then
                                for iUnit, oUnit in tEnemyStructures do
                                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oUnit:GetPosition())
                                        if iCurDist <= iClosestEnemyDist then
                                            oClosestEnemy = oUnit
                                            iClosestEnemyDist = iCurDist
                                            if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurDist='..iCurDist..'; this is the closest unit for now, will cycle through any remaining') end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for enemy structure in nearby different plateau, oClosestEnemy='..(oClosestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy) or 'nli')) end
            tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere] = oClosestEnemy
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': End of code, iEnemyBestMobileDFRange='..iEnemyBestMobileDFRange..'; iEnemyBestStructureDFRange='..iEnemyBestStructureDFRange..'; iEnemyBestMobileIndirectRange='..iEnemyBestMobileIndirectRange) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iEnemyBestMobileDFRange, iEnemyBestStructureDFRange, iEnemyBestMobileIndirectRange
end

function ReviseTargetLZIfFarAway(tLZData, iTeam, iPlateau, iStartLandZone, iTargetLandZone, iMaxLZTowardsRally)
    --If we want to move to a rally point but it is more than iMaxLZTowardsRally land zones away, then go to the iMaxLZTowardsRally'th entry
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ReviseTargetLZIfFarAway'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iNewTargetLZ = iTargetLandZone
    if not(tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone]) then
        AiBotMap.ConsiderAddingTargetLandZoneToDistanceFromBaseTable(iPlateau, iStartLandZone, iTargetLandZone, tLZData[AiBotMap.subrefMidpoint])
    end
    if iMaxLZTowardsRally and tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone] then
        if bDebugMessages == true then
            LOG(sFunctionRef..': WIll consider revising the '..iMaxLZTowardsRally..' entry along the path; repru of the path='..repru(tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone]][AiBotMap.subrefLZPath])..'; Position in the path='..tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone])
            local tPath = {}
            table.insert(tPath, tLZData[AiBotMap.subrefMidpoint])
            for iEntry, iZone in tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone]][AiBotMap.subrefLZPath] do
                table.insert(tPath, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iZone][AiBotMap.subrefMidpoint])
            end
            AiBotUtilities.DrawPath(tPath)
        end
        --Change closest LZ to run to to be 2 along the path from cur LZ to the target LZ
        for iEntry, iLZPointInPath in tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone]][AiBotMap.subrefLZPath] do
            if iEntry >= iMaxLZTowardsRally then
                if bDebugMessages == true then LOG(sFunctionRef..': Were going to move to iTargetLandZone='..iTargetLandZone..' from LZ'..iStartLandZone..' but it is at least iMaxLZTowardsRally='..iMaxLZTowardsRally..' LZ away so will move to iEntry LZ which is '..iLZPointInPath..'; Total paht size='..table.getn(tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone]][AiBotMap.subrefLZPath])) end
                iNewTargetLZ = iLZPointInPath
                break
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iNewTargetLZ
end

function GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, iMaxLZTowardsRally, bAmphibiousPathing)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetNearestLandRallyPoint'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --Gets the location of the nearest rally point; if bAmphibiousPathing is true then will consider other islands, otherwise will only consider current island
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiRallyPointLandZonesByPlateau][iPlateau]) == false then
        local iCurDist
        local iClosestDist = 100000
        local iClosestLZRef
        local iBaseIsland = tLZData[AiBotMap.subrefLZIslandRef]
        local iClosestAmphibDist = 100000
        local iClosestAmphibLZRef
        local iSecondClosestDist = 100000
        local iSecondClosestLZRef

        if bDebugMessages == true then LOG(sFunctionRef..': have potential land zones to consider for plateau '..iPlateau..'; bAmphibiousPathing='..tostring(bAmphibiousPathing or false)) end
        for iEntry, iAltLZ in AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiRallyPointLandZonesByPlateau][iPlateau] do
            if bDebugMessages == true then LOG(sFunctionRef..': Looking for rally point for iPlateau '..iPlateau..'; iLandZone '..iLandZone..'; Considering iAltLZ='..iAltLZ..'; Travel distance to here='..(AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iLandZone, iAltLZ) or 'nil')) end
            if iAltLZ == iLandZone then
                if not(iClosestLZRef) then
                    iClosestLZRef = iAltLZ
                    --break
                end
            else
                if AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAltLZ][AiBotMap.subrefLZIslandRef] == iBaseIsland then
                    iCurDist = (AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iLandZone, iAltLZ) or iClosestDist + 1)  --AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAltLZ][AiBotMap.subrefMidpoint], tLZData[AiBotMap.subrefMidpoint])
                    if iCurDist < iClosestDist then
                        iSecondClosestLZRef = iClosestLZRef
                        iSecondClosestDist = iClosestDist
                        iClosestDist = iCurDist
                        iClosestLZRef = iAltLZ
                        if bDebugMessages == true then LOG(sFunctionRef..': Have a new closestLZRef that is on same island, iBaseIsland='..iBaseIsland..'; iClosestLZRef='..iClosestLZRef..'; iClosestDist='..iClosestDist) end
                    elseif iCurDist < iSecondClosestDist then
                        iSecondClosestDist = iCurDist
                        iSecondClosestLZRef = iAltLZ
                    end
                elseif bAmphibiousPathing and not(iClosestLZRef) then
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions( AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAltLZ][AiBotMap.subrefMidpoint], tLZData[AiBotMap.subrefMidpoint])
                    if iCurDist < iClosestAmphibDist then
                        iClosestAmphibDist = iCurDist
                        iClosestAmphibLZRef = iAltLZ
                        if bDebugMessages == true then LOG(sFunctionRef..': Have a new closetsAmphibLZRef, iClosestAmphibDist='..iClosestAmphibDist..'; iClosestAmphibLZRef='..iClosestAmphibLZRef) end
                    end
                end
            end
        end
        if not(iClosestLZRef) then
            if bAmphibiousPathing and iClosestAmphibLZRef then iClosestLZRef = iClosestAmphibLZRef
            else
                iClosestLZRef = iLandZone
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Dont have iClosestLZRef, bAmphibiousPathing='..tostring(bAmphibiousPathing or false)..'; iClosestAmphibLZRef='..(iClosestAmphibLZRef or 'nil')..'; iClosestLZRef after updating for amphibious or setting to cur land zone='..iClosestLZRef) end
        else
            iClosestAmphibLZRef = nil
        end
        if iClosestLZRef == iLandZone then
            --Do nothing - wont find a closer one
        else
            --Do we have a path to this rally point from the current land zone? If so move 2 along the path
            if iClosestAmphibLZRef then
                --Do nothign - will just want to go straight to the amphibious LZ
            else
                local tZonesToConsider = {iClosestLZRef}
                if iSecondClosestLZRef then table.insert(tZonesToConsider, iSecondClosestLZRef) end
                for _, iTargetLZRef in tZonesToConsider do
                    if not(tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLZRef]) then
                        AiBotMap.ConsiderAddingTargetLandZoneToDistanceFromBaseTable(iPlateau, iLandZone, iTargetLZRef, tLZData[AiBotMap.subrefMidpoint])
                        if not(tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLZRef]) then
                            AiBotUtilities.ErrorHandler('Dont have pathing recorded for iTargetLZRef='..iTargetLZRef..'; iPlateau='..iPlateau..'; iBaesLZ='..iLandZone..'; iClosestLZRef='..iClosestLZRef..' even after checking to update pathing, if logs are enabled will draw midpoint of LZ')
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': tLZData[AiBotMap.subrefMidpoint]='..repru(tLZData[AiBotMap.subrefMidpoint])..'; subrefLZTotalSegmentCount for closest LZref='..(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iTargetLZRef][AiBotMap.subrefLZTotalSegmentCount] or 'nil')..'; Will draw midpoint in red, and hten draw the base LZ in gold and the closest LZ in cyan')
                                AiBotUtilities.DrawLocation(tLZData[AiBotMap.subrefMidpoint], 2, 200)
                                AiBotMap.DrawSpecificLandZone(iPlateau, iLandZone, 4)
                                AiBotMap.DrawSpecificLandZone(iPlateau, iTargetLZRef, 6)
                            end
                        end
                    end
                end
                --Consider switching from closest to second closest if closest is dangerous and secondclosest is closer to our base;  this is to avoid scenario (covered in v113 changes) where we try moving to a LZ 2 away, and the first LZ to get there takes us closer to the enemy
                if iSecondClosestLZRef and tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iClosestLZRef] and tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iSecondClosestLZRef] then
                    local iClosestFirstZone = tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iClosestLZRef]][AiBotMap.subrefLZPath][1]
                    local tClosestFirstZoneLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestFirstZone]
                    local tClosestFirstZoneLZTeamData = tClosestFirstZoneLZData[AiBotMap.subrefLZTeamData][iTeam]
                    local iSecondClosestFirstZone = tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iSecondClosestLZRef]][AiBotMap.subrefLZPath][1]
                    local tSecondClosestFirstZoneLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iSecondClosestFirstZone]
                    local tSecondClosestFirstZoneLZTeamData = tSecondClosestFirstZoneLZData[AiBotMap.subrefLZTeamData][iTeam]
                    local iClosestGrossThreat = (tClosestFirstZoneLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
                    local iClosestNetThreat = (tClosestFirstZoneLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tClosestFirstZoneLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)
                    local iSecondClosestGrossThreat = (tSecondClosestFirstZoneLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
                    local iSecondClosestNetThreat = (tSecondClosestFirstZoneLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tSecondClosestFirstZoneLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)
                    --Include mobile DF threat in adjacent zones
                    local iAdjZoneFactor = 0.7
                    if AiBotUtilities.IsTableEmpty(tClosestFirstZoneLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tClosestFirstZoneLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            if (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > 0 then
                                iClosestGrossThreat = iClosestGrossThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) * iAdjZoneFactor
                            end
                            iClosestNetThreat = iClosestNetThreat + ((tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) - (tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0)) * 0.7
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tSecondClosestFirstZoneLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tSecondClosestFirstZoneLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            if (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > 0 then
                                iSecondClosestGrossThreat = iSecondClosestGrossThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) * iAdjZoneFactor
                            end
                            iSecondClosestNetThreat = iSecondClosestNetThreat + ((tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) - (tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0)) * iAdjZoneFactor
                        end
                    end

                    --Does the closest first zone closer to the enemy and has significantly more enemy combat threat than the second closest first zone?
                    if bDebugMessages == true then LOG(sFunctionRef..': iLandZone='..iLandZone..'; iPlateua='..iPlateau..'; First closest LZ='..iClosestFirstZone..'; Second closest first zone='..(iSecondClosestFirstZone or 'nil')..'; ClosestFirstZoneModDist%='..(tClosestFirstZoneLZTeamData[AiBotMap.refiModDistancePercent] or 'nil')..'; Second closest='..(tSecondClosestFirstZoneLZTeamData[AiBotMap.refiModDistancePercent] or 'nil')..'; Closest net combat='..iClosestGrossThreat..'; Second closest net combat='.. (iSecondClosestGrossThreat or 'nil')..'; iSecondClosestLZRef='..(iSecondClosestLZRef or 'nil')..'; iSecondClosestDist='..(iSecondClosestDist or 'nil')..'; iClosestGrossThreat='..iClosestGrossThreat..'; iSecondClosestGrossThreat='..(iSecondClosestGrossThreat or 'nil')) end
                    if iSecondClosestLZRef and tSecondClosestFirstZoneLZTeamData[AiBotMap.refiModDistancePercent] and tClosestFirstZoneLZTeamData[AiBotMap.refiModDistancePercent] > tSecondClosestFirstZoneLZTeamData[AiBotMap.refiModDistancePercent] and tClosestFirstZoneLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > (tClosestFirstZoneLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) * 0.8 and tClosestFirstZoneLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] - (tClosestFirstZoneLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) > 1.2 * ((tSecondClosestFirstZoneLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tSecondClosestFirstZoneLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Switching rally point so will treat second closest as the actual closest') end
                        iClosestLZRef = iSecondClosestLZRef
                        iClosestDist = iSecondClosestDist
                        --If second closest is lower mod dist, significantly lower gross threat, and either net threat isnt negative, or net threat negative but not massively more than gross threat, then switch
                    elseif (iClosestNetThreat > 0 and iSecondClosestNetThreat <= 0 and (iClosestNetThreat > math.min(iSecondClosestGrossThreat * 0.5, iClosestGrossThreat * 0.5))) or
                            (iSecondClosestGrossThreat * 1.25 < iClosestGrossThreat and tSecondClosestFirstZoneLZTeamData[AiBotMap.refiModDistancePercent] < tClosestFirstZoneLZTeamData[AiBotMap.refiModDistancePercent] and ((iClosestNetThreat > 0 and iClosestGrossThreat < iClosestNetThreat) or (iSecondClosestNetThreat < 0 and iClosestNetThreat < 0 and -iSecondClosestNetThreat < 3 * iSecondClosestGrossThreat and -iClosestNetThreat < 3 * iClosestGrossThreat))) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Second closest seems safer than closest so will switch') end
                        iClosestLZRef = iSecondClosestLZRef
                        iClosestDist = iSecondClosestDist
                    end
                end



                if iMaxLZTowardsRally and tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iClosestLZRef] then
                    if (iClosestDist <= 250 or iClosestAmphibDist <= 250) then iMaxLZTowardsRally = iMaxLZTowardsRally + 1 end
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': WIll consider changing to the '..iMaxLZTowardsRally..' entry along the path to get to zone '..iClosestLZRef..'; repru of the path='..repru(tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iClosestLZRef]][AiBotMap.subrefLZPath])..'; Position in the path='..tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iClosestLZRef]..'; tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef]='..repru(tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef])..'; iClosestLZRef='..iClosestLZRef..'; Full listing of repru(tAllPlateaus[iPlateau][subrefPlateauLandZones][iTargetLandZone][subrefLZPathingToOtherLandZones]='..repru(repru(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZPathingToOtherLandZones]))..'; Dist to end destination (straight line)='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZRef][AiBotMap.subrefMidpoint]))
                        local tPath = {}
                        table.insert(tPath, tLZData[AiBotMap.subrefMidpoint])
                        for iEntry, iZone in tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iClosestLZRef]][AiBotMap.subrefLZPath] do
                            table.insert(tPath, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iZone][AiBotMap.subrefMidpoint])
                            if bDebugMessages == true then LOG(sFunctionRef..': Dist from path entry iZone '..iZone..' to the target='..AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iZone][AiBotMap.subrefMidpoint], AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZRef][AiBotMap.subrefMidpoint])) end
                        end
                        AiBotUtilities.DrawPath(tPath)
                        if bDebugMessages == true then LOG(sFunctionRef..': repru of tPath if going the full path='..repru(tPath)) end
                    end
                    local tTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZRef]
                    local iAngleToTargetLZ = AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tTargetLZData[AiBotMap.subrefMidpoint])
                    local bKeepLooking
                    local iStraightLineDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tTargetLZData[AiBotMap.subrefMidpoint])
                    --Change closest LZ to run to to be 2 along the path from cur LZ to the target LZ
                    for iEntry, iLZPointInPath in tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iClosestLZRef]][AiBotMap.subrefLZPath] do
                        if iEntry >= iMaxLZTowardsRally then
                            if iLZPointInPath == iClosestLZRef then break else
                                --Consider moving to iMaxLZTowardsRally + 1 entry if not much further away; consider just going to the end point if this would be in a very different angle to the original location as well
                                local tPathLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLZPointInPath]
                                if bDebugMessages == true then LOG(sFunctionRef..': iEntry='..iEntry..'; iMaxLZTowardsRally='..iMaxLZTowardsRally..'; iLZPointInPath='..iLZPointInPath..'; iClosestDist before='..iClosestDist..'; iClosestAmphibDist before='..(iClosestAmphibDist or 'nil')..'; Angle to along path LZ='..AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tPathLZData[AiBotMap.subrefMidpoint])..'; Angle to end LZ wanted='..iAngleToTargetLZ..'; angle dif='..AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tPathLZData[AiBotMap.subrefMidpoint]), iAngleToTargetLZ)) end
                                if iEntry >= iMaxLZTowardsRally + 3 then
                                    iClosestLZRef = iLZPointInPath
                                    break
                                else
                                    bKeepLooking = false
                                    if AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tPathLZData[AiBotMap.subrefMidpoint]), iAngleToTargetLZ) >= 45 then
                                        bKeepLooking = true
                                    elseif iStraightLineDistToTarget - AiBotUtilities.GetDistanceBetweenPositions(tPathLZData[AiBotMap.subrefMidpoint], tTargetLZData[AiBotMap.subrefMidpoint]) < math.min(150, iEntry * 40) then
                                        --Quite a big angle dif, so consider moving up to 2 further along path
                                        bKeepLooking = true
                                    end
                                    if not(bKeepLooking) then
                                        iClosestLZRef = iLZPointInPath
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iMaxLZTowardsRally='..(iMaxLZTowardsRally or 'nil')..'; iClosestLZRef='..iClosestLZRef..'; Returning midpoint for closestLZRef='..repru({AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZRef][AiBotMap.subrefMidpoint][1], AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZRef][AiBotMap.subrefMidpoint][2], AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZRef][AiBotMap.subrefMidpoint][3]})) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return {AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZRef][AiBotMap.subrefMidpoint][1], AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZRef][AiBotMap.subrefMidpoint][2], AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZRef][AiBotMap.subrefMidpoint][3]}
    else
        if not(AiBotMap.bIsCampaignMap) or AiBotConditions.IsLocationInPlayableArea(AiBotMap.PlayerStartPoints[AiBotTeam.GetFirstActiveAiBotBrain(iTeam):GetArmyIndex()]) then
            --If dealing with plateau with 3+ zones then might not have set any to have a rally point
            AiBotUtilities.ErrorHandler('No rally point for P'..(iPlateau or 'nil')..' LZ'..(iLandZone or 'nil')..' for team '..iTeam..'; will return current midpoint', true)
            if bDebugMessages == true then
                LOG(sFunctionRef..': Will draw specific land zone in gold, midpoint='..repru(tLZData[AiBotMap.subrefMidpoint])..'; Closest friendly base='..repru(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.reftClosestFriendlyBase])..'; iTeam='..iTeam)
                AiBotMap.DrawSpecificLandZone(iPlateau, iLandZone, 4)
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]}
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RefreshLandRallyPoints(iTeam, iPlateau)
    --For now just has core bases and core expansion points as rally points, may adjust htis in the future
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RefreshLandRallyPoints'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    

    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiRallyPointLandZonesByPlateau]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiRallyPointLandZonesByPlateau] = {} end
    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiRallyPointLandZonesByPlateau][iPlateau] = {}
    if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones]) == false then
        local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)
        local iHighestSValue = 0
        local iLZWithHighestSValue
        local tiDangerousCoreBaseRefs = {}
        local iNetCombatValue
        local iMaxZoneCount = (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefLandZoneCount] or 0)

        for iLandZone, tLZData in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones] do
            if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) then
                if bDebugMessages == true then LOG(sFunctionRef..': considering if we want zone '..iLandZone..' in iPlateau='..iPlateau..' to be a rally point, is core base='..tostring(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase] or false)..'; is core expansion='..tostring(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZCoreExpansion] or false)..'; iMaxZoneCount='..iMaxZoneCount) end
                local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                if tLZTeamData[AiBotMap.subrefLZbCoreBase] or (tLZTeamData[AiBotMap.subrefLZSValue] >= 200 and (tLZTeamData[AiBotMap.subrefLZCoreExpansion] or (not(iLZWithHighestSValue) and tLZTeamData[AiBotMap.subrefLZSValue] >= 1000)) or (iMaxZoneCount <= 2 and (tLZTeamData[AiBotMap.subrefLZCoreExpansion] or (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0) > 0))) then
                    if tLZTeamData[AiBotMap.subrefLZSValue] >= iHighestSValue then
                        iHighestSValue = tLZTeamData[AiBotMap.subrefLZSValue]
                        iLZWithHighestSValue = iLandZone
                    end
                    --Dont have as rally if enemy has T2 arti nearby
                    if iMaxZoneCount > 1 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) and (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) == 0 then
                        iNetCombatValue = (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)
                        if iNetCombatValue < 0 or (tLZTeamData[AiBotMap.subrefLZbCoreBase] and (iNetCombatValue <= 200 or  (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) < (tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) * 1.25)) then
                            table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiRallyPointLandZonesByPlateau][iPlateau], iLandZone)
                        elseif tLZTeamData[AiBotMap.subrefLZbCoreBase] then
                            table.insert(tiDangerousCoreBaseRefs, iLandZone)
                        end
                    end
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiRallyPointLandZonesByPlateau][iPlateau]) then
            if iLZWithHighestSValue then table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiRallyPointLandZonesByPlateau][iPlateau], iLZWithHighestSValue)
            elseif AiBotUtilities.IsTableEmpty(tiDangerousCoreBaseRefs) == false then
                for iEntry, iLandZone in tiDangerousCoreBaseRefs do
                    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiRallyPointLandZonesByPlateau][iPlateau], iLandZone)
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function SendMAAToSupportLandZone(tMAAToAdvance, iPlateau, iTeam, iLZOrWZToSupport, iMAAFactorAdjust, bWaterZone, tHoverMAAToAdvance)
    --Assigns MAA to the land zone up to the level at which the LZ doesnt want more MAA support, but increases the MAA wanted by the land zone by iMAAFactorAdjust (or 1 if not specified)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SendMAAToSupportLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tAltLZOrWZData
    local tAltTeamLZOrWZData
    local tTargetPosition
    local iPond
    local iMAAThreatWanted, iAllyGroundAA
    if bWaterZone then
        iPond = AiBotMap.tiPondByWaterZone[iLZOrWZToSupport]
        tAltLZOrWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iLZOrWZToSupport]
        tAltTeamLZOrWZData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
        tTargetPosition = tAltLZOrWZData[AiBotMap.subrefMidpoint]
        iAllyGroundAA = tAltTeamLZOrWZData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]
        iMAAThreatWanted = (tAltTeamLZOrWZData[AiBotMap.subrefWZMAAThreatWanted] or 0) * (iMAAFactorAdjust or 1) - (iAllyGroundAA or 0)
    else
        tAltLZOrWZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLZOrWZToSupport]
        tAltTeamLZOrWZData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
        tTargetPosition = tAltLZOrWZData[AiBotMap.subrefMidpoint]
        iAllyGroundAA = tAltTeamLZOrWZData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]
        iMAAThreatWanted = AiBotConditions.GetNetMAAWantedForZone(tAltTeamLZOrWZData, iMAAFactorAdjust)
    end

    local tDistToTargetByRef = {}
    if not(iMAAThreatWanted) or not(iAllyGroundAA) then
        AiBotUtilities.ErrorHandler('Have nil MAA or AllyGroundAA threat for iLZOrWZToSupport='..(iLZOrWZToSupport or 'nil')..'; see log for more info')
        LOG(sFunctionRef..': MAA iTeam='..(iTeam or 'nil')..'; iPlateau='..(iPlateau or 'nil')..'; iLZOrWZToSupport='..(iLZOrWZToSupport or 'nil')..'; tAltTeamLZOrWZData[AiBotMap.subrefLZMAAThreatWanted]='..(tAltTeamLZOrWZData[AiBotMap.subrefLZMAAThreatWanted] or 'nil')..'; tAltTeamLZOrWZData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..(tAltTeamLZOrWZData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 'nil'))
    else
        for iUnit, oUnit in (tHoverMAAToAdvance or tMAAToAdvance) do
            tDistToTargetByRef[iUnit] = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tTargetPosition)
        end
        local tbRemovedMAAReferencesByRef = {}
        for iUnitRef, iDistance in AiBotUtilities.SortTableByValue(tDistToTargetByRef, false) do
            if bDebugMessages == true then LOG(sFunctionRef..': About to issue order to move for iUnitRef='..iUnitRef..'; tMAAToAdvance[iUnitRef]='..(tMAAToAdvance[iUnitRef].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tMAAToAdvance[iUnitRef]) or 'nil')..' to go to tTargetPosition='..repru(tTargetPosition)) end
            AiBotOrders.IssueTrackedMove(tMAAToAdvance[iUnitRef], tTargetPosition, 10, false, 'MVELZ'..iLZOrWZToSupport)
            iMAAThreatWanted = iMAAThreatWanted - AiBotUnitInfo.GetAirThreatLevel({ tMAAToAdvance[iUnitRef] }, false, false, true, false, false, false)
            tbRemovedMAAReferencesByRef[iUnitRef] = true
            if iMAAThreatWanted < 0 then break end
        end
        if AiBotUtilities.IsTableEmpty(tbRemovedMAAReferencesByRef) == false then
            --Remove any MAA that have given orders from tMAAToAdvance:
            if AiBotUtilities.IsTableEmpty(tHoverMAAToAdvance) then
                local iRevisedIndex = 1
                local iTableSize = table.getn(tMAAToAdvance)

                for iOrigIndex=1, iTableSize do
                    if tMAAToAdvance[iOrigIndex] then
                        if not(tbRemovedMAAReferencesByRef[iOrigIndex]) then --I.e. this should run the logic to decide whether we want to keep this entry of the table or remove it
                            --We want to keep the entry; Move the original index to be the revised index number (so if e.g. a table of 1,2,3 removed 2, then this would've resulted in the revised index being 2 (i.e. it starts at 1, then icnreases by 1 for the first valid entry); this then means we change the table index for orig index 3 to be 2
                            if (iOrigIndex ~= iRevisedIndex) then
                                tMAAToAdvance[iRevisedIndex] = tMAAToAdvance[iOrigIndex];
                                tMAAToAdvance[iOrigIndex] = nil;
                            end
                            iRevisedIndex = iRevisedIndex + 1; --i.e. this will be the position of where the next value that we keep will be located
                        else
                            tMAAToAdvance[iOrigIndex] = nil;
                        end
                    end
                end
                if iRevisedIndex < iTableSize then
                    --table.setn(tMAAToAdvance, iRevisedIndex - 1)
                    for iRemovalEntry = iTableSize, iRevisedIndex, -1 do
                        table.remove(tMAAToAdvance, iRemovalEntry)
                    end
                end
            else
                --Need to remove from both the hover MAA table, and the main MAA table
                local iRevisedIndex = 1
                local iTableSize = table.getn(tHoverMAAToAdvance)


                for iOrigIndex=1, iTableSize do
                    if tHoverMAAToAdvance[iOrigIndex] then
                        if not(tbRemovedMAAReferencesByRef[iOrigIndex]) then --I.e. this should run the logic to decide whether we want to keep this entry of the table or remove it
                            --We want to keep the entry; Move the original index to be the revised index number (so if e.g. a table of 1,2,3 removed 2, then this would've resulted in the revised index being 2 (i.e. it starts at 1, then icnreases by 1 for the first valid entry); this then means we change the table index for orig index 3 to be 2
                            if (iOrigIndex ~= iRevisedIndex) then
                                tHoverMAAToAdvance[iRevisedIndex] = tHoverMAAToAdvance[iOrigIndex];
                                tHoverMAAToAdvance[iOrigIndex] = nil;
                            end
                            iRevisedIndex = iRevisedIndex + 1; --i.e. this will be the position of where the next value that we keep will be located
                        else
                            --Want to remove the unit - also remove from the original MAA table
                            for iUnit, oUnit in tMAAToAdvance do
                                if oUnit == tHoverMAAToAdvance[iOrigIndex] then
                                    table.remove(tMAAToAdvance, iUnit)
                                    break
                                end
                            end
                            tHoverMAAToAdvance[iOrigIndex] = nil;
                        end
                    end
                end
                if iRevisedIndex < iTableSize then
                    --table.setn(tHoverMAAToAdvance, iRevisedIndex - 1)
                    for iRemovalEntry = iTableSize, iRevisedIndex, -1 do
                        table.remove(tHoverMAAToAdvance, iRemovalEntry)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function StealthUnitsInLandZone(tTeamTargetLZData, tStealthsToAssign, bAssignAllStealths, toOptionalUnitsToStealth)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'StealthUnitsInLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --local tTargetLandZone = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iTargetLandZone][AiBotMap.subrefLZTeamData][iTeam]
    local bNoUnitsWantingStealthing = true
    if AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefLZTAlliedCombatUnits]) and AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileStealth]) and AiBotUtilities.IsTableEmpty(toOptionalUnitsToStealth) then
        AiBotUtilities.ErrorHandler('Are trying to send mobile Stealths to support a land zone that has no allied combat units in it and no units wanting Stealthing')
    else
        local toUnitsWantingStealth
        if toOptionalUnitsToStealth then toUnitsWantingStealth = toOptionalUnitsToStealth
        else toUnitsWantingStealth = tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileStealth]
        end
        if AiBotUtilities.IsTableEmpty(toUnitsWantingStealth) == false then
            for iTarget, oTarget in toUnitsWantingStealth do
                if not(oTarget[refoAssignedMobileStealth]) then
                    if AiBotUtilities.IsTableEmpty(tStealthsToAssign) then
                        bNoUnitsWantingStealthing = false
                        break
                    else
                        --Assign the closest mobile Stealth
                        local iCurDist
                        local iClosestDist = 100000
                        local iClosestRef

                        for iStealth, oStealth in tStealthsToAssign do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering entry iStealth='..iStealth..'; Stealth unit='..oStealth.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStealth)) end
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oStealth:GetPosition(), oTarget:GetPosition())
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                iClosestRef = iStealth
                            end
                            break
                        end
                        tStealthsToAssign[iClosestRef][refoMobileStealthTarget] = oTarget
                        oTarget[refoAssignedMobileStealth] = tStealthsToAssign[iClosestRef]
                        MoveToStealthTarget(tStealthsToAssign[iClosestRef], tTeamTargetLZData[AiBotMap.reftClosestEnemyBase])
                        table.remove(tStealthsToAssign, iClosestRef)
                        if bDebugMessages == true then LOG(sFunctionRef..': Have just removed Stealth with iClosestRef='..iClosestRef..' from the table of tStealthsToAssign; is table empty='..tostring(AiBotUtilities.IsTableEmpty(tStealthsToAssign))..'; size of table='..table.getn(tStealthsToAssign)) end
                    end
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tStealthsToAssign) == false and bAssignAllStealths then
            bNoUnitsWantingStealthing = true
            --No units that want Stealthing - e.g. we might be telling mobile Stealths to defend here temporarily; dont assign the Stealths, instead just give them orders so they are still of some use
            if AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefLZTAlliedCombatUnits]) == false then
                for iTarget, oTarget in tTeamTargetLZData[AiBotMap.subrefLZTAlliedCombatUnits] do
                    if not(oTarget[refoAssignedMobileStealth]) then --redundancy
                        --Assign the closest mobile Stealth
                        local iCurDist
                        local iClosestDist = 100000
                        local iClosestRef

                        for iStealth, oStealth in tStealthsToAssign do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering entry iStealth='..iStealth..'; Stealth unit='..oStealth.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStealth)) end
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oStealth:GetPosition(), oTarget:GetPosition())
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                iClosestRef = iStealth
                            end
                            break
                        end
                        --Dont record the Stealth as helpin this unit, instead just have it move to the unit temporarily - so only change the variable so movetoStealthtarget works
                        tStealthsToAssign[iClosestRef][refoMobileStealthTarget] = oTarget
                        MoveToStealthTarget(tStealthsToAssign[iClosestRef], tTeamTargetLZData[AiBotMap.reftClosestEnemyBase])
                        tStealthsToAssign[iClosestRef][refoMobileStealthTarget] = nil
                        table.remove(tStealthsToAssign, iClosestRef)
                        if bDebugMessages == true then LOG(sFunctionRef..': Backup Stealth assignment - Have removed Stealth with iClosestRef='..iClosestRef..' from the table of tStealthsToAssign; is table empty='..tostring(AiBotUtilities.IsTableEmpty(tStealthsToAssign))..'; size of table='..table.getn(tStealthsToAssign)) end
                        if AiBotUtilities.IsTableEmpty(tStealthsToAssign) then break end
                    end
                end

                --Do we still have spare mobile Stealths?
                if AiBotUtilities.IsTableEmpty(tStealthsToAssign) == false then
                    --Get closest unit to enemy base and assign all remaining Stealths temporarily here
                    local iCurDist
                    local iClosestDist = 100000
                    local oClosestToEnemyBase

                    for iTarget, oTarget in tTeamTargetLZData[AiBotMap.subrefLZTAlliedCombatUnits] do
                        if AiBotUnitInfo.IsUnitValid(oTarget) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oTarget:GetPosition(), tTeamTargetLZData[AiBotMap.reftClosestEnemyBase])
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                oClosestToEnemyBase = oTarget
                            end
                        end
                    end
                    if oClosestToEnemyBase then
                        local tEnemyBase = tTeamTargetLZData[AiBotMap.reftClosestEnemyBase]
                        for iStealth, oStealth in tStealthsToAssign do
                            --Dont record the Stealth as helpin this unit, instead just have it move to the unit temporarily - so only change the variable so movetoStealthtarget works
                            if bDebugMessages == true then LOG(sFunctionRef..': About to tell Stealth '..(oStealth.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oStealth) or 'nil')..' to move towards oClosestToEnemyBase='..(oClosestToEnemyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestToEnemyBase) or 'nil')) end
                            oStealth[refoMobileStealthTarget] = oClosestToEnemyBase
                            MoveToStealthTarget(oStealth, tEnemyBase)
                            oStealth[refoMobileStealthTarget] = nil
                            if bDebugMessages == true then LOG(sFunctionRef..': Backup Stealth assignment - have told Stealth '..oStealth.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStealth)..' to go to the closest enemy in this LZ to enemy base='..oClosestToEnemyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestToEnemyBase)) end
                        end
                    elseif bDebugMessages == true then LOG(sFunctionRef..': No friendly units close to enemy base - assuming this is termpoary due to unit being destroyed')
                    end
                end
            end
        end
    end
    if bNoUnitsWantingStealthing then
        --Flag that this LZ no longer wants mobile Stealths
        tTeamTargetLZData[AiBotMap.refbLZWantsMobileStealth] = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordMobileShieldAgainstTarget(oShield, oTarget)
    oShield[refoMobileShieldTarget] = oTarget
    if EntityCategoryContains(categories.COMMAND + AiBotUnitInfo.refCategoryFatboy, oTarget.UnitId) then
        local iEnemyNovaxCount = AiBotTeam.tTeamData[oTarget:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemyNovaxCount]
        local bAssignAsExtraShield = false
        if iEnemyNovaxCount > 0 then
            local iExistingExtraShields = 0
            if AiBotConditions.IsTableOfUnitsStillValid(oTarget[reftoAdditionalAssignedMobileShields]) then
                iExistingExtraShields = table.getn(oTarget[reftoAdditionalAssignedMobileShields])
            end
            if iExistingExtraShields <= math.min(iEnemyNovaxCount, 4) and (iExistingExtraShields <= 2 or AiBotUnitInfo.GetUnitHealthPercent(oTarget) < 1) then
                bAssignAsExtraShield = true
            end
        end
        if bAssignAsExtraShield then
            if not(oTarget[reftoAdditionalAssignedMobileShields]) then oTarget[reftoAdditionalAssignedMobileShields] = {} end
            table.insert(oTarget[reftoAdditionalAssignedMobileShields], oShield)
        else
            oTarget[refoAssignedMobileShield] = oShield
        end
    else
        oTarget[refoAssignedMobileShield] = oShield
    end
end

function ClearCurrentShieldTarget(oShield)
    if oShield[refoMobileShieldTarget] then
        if AiBotUtilities.IsTableEmpty(oShield[refoMobileShieldTarget][reftoAdditionalAssignedMobileShields]) == false then
            for iCurShield = table.getn(oShield[refoMobileShieldTarget][reftoAdditionalAssignedMobileShields]), 1, -1 do
                local oCurShield = oShield[refoMobileShieldTarget][reftoAdditionalAssignedMobileShields][iCurShield]
                if oCurShield == oShield then
                    table.remove(oShield[refoMobileShieldTarget][reftoAdditionalAssignedMobileShields], iCurShield)
                end
            end
        end
        if oShield[refoMobileShieldTarget][refoAssignedMobileShield] == oShield then
            oShield[refoMobileShieldTarget][refoAssignedMobileShield] = nil
        end
        oShield[refoMobileShieldTarget] = nil
    end
end

function ShieldUnitsInLandZone(tTeamTargetLZData, tShieldsToAssign, bAssignAllShields)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ShieldUnitsInLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    --local tTargetLandZone = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iTargetLandZone][AiBotMap.subrefLZTeamData][iTeam]
    local bNoUnitsWantingShielding = true
    if AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefLZTAlliedCombatUnits]) and AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileShield]) and AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefAlliedACU]) then
        AiBotUtilities.ErrorHandler('Are trying to send mobile shields to support a land zone that has no allied combat units in it and no units wanting shielding')
    else
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of units wanting mobile shield empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileShield]))) end
        if AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileShield]) == false then
            --Prioritise t2 arti if have enemy t2 arti in zone
            function AssignClosestMobileShieldToTarget(oTarget)
                --Returns false if should abort
                if not(oTarget[refoAssignedMobileShield]) then
                    if AiBotUtilities.IsTableEmpty(tShieldsToAssign) then
                        bNoUnitsWantingShielding = false
                        return false
                    else
                        --Assign the closest mobile shield
                        local iCurDist
                        local iClosestDist = 100000
                        local iClosestRef

                        for iShield, oShield in tShieldsToAssign do
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oTarget:GetPosition())
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering entry iShield='..iShield..'; Shield unit='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; iCurDist='..iCurDist..'; iClosestDist='..iClosestDist..'; oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)) end
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                iClosestRef = iShield
                            end
                        end
                        RecordMobileShieldAgainstTarget(tShieldsToAssign[iClosestRef], oTarget)

                        MoveToShieldTarget(tShieldsToAssign[iClosestRef], tTeamTargetLZData[AiBotMap.reftClosestEnemyBase])
                        table.remove(tShieldsToAssign, iClosestRef)
                        if bDebugMessages == true then LOG(sFunctionRef..': Have just removed shield with iClosestRef='..iClosestRef..' from the table of tShieldsToAssign; is table empty='..tostring(AiBotUtilities.IsTableEmpty(tShieldsToAssign))..'; size of table='..table.getn(tShieldsToAssign)) end
                        return not(AiBotUtilities.IsTableEmpty(tShieldsToAssign))
                    end
                end
            end
            local tUnitsToPrioritiseForShielding = {}
            if AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                tUnitsToPrioritiseForShielding = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedT2Arti, tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileShield])
            end
            if AiBotConditions.IsTableOfUnitsStillValid(tTeamTargetLZData[AiBotMap.subrefAlliedACU]) then
                local iCurHealthPercent
                if not(tUnitsToPrioritiseForShielding) then tUnitsToPrioritiseForShielding = {} end
                for iACU, oACU in tTeamTargetLZData[AiBotMap.subrefAlliedACU] do
                    iCurHealthPercent = AiBotUnitInfo.GetUnitHealthPercent(oACU)
                    if iCurHealthPercent <= 0.6 or (iCurHealthPercent <= 0.98 and GetGameTimeSeconds() - (oACU[AiBotACU.refiTimeLastWantedToRun] or -100) <= 5) or AiBotTeam.tTeamData[oACU:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemyNovaxCount] > 0 then
                        table.insert(tUnitsToPrioritiseForShielding, oACU)
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tUnitsToPrioritiseForShielding) == false then
                for iTarget, oTarget in tUnitsToPrioritiseForShielding do
                    if not(oTarget.Dead) then
                        if AssignClosestMobileShieldToTarget(oTarget) == false then break end
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileShield]) == false and AiBotUtilities.IsTableEmpty(tShieldsToAssign) == false then
                for iTarget, oTarget in tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileShield] do
                    if not(oTarget.Dead) then
                        if AssignClosestMobileShieldToTarget(oTarget) == false then break end
                    end
                end
            end
        end
        if (AiBotUtilities.IsTableEmpty(tShieldsToAssign) == false or AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefAlliedACU]) == false) and bAssignAllShields then
            bNoUnitsWantingShielding = true
            --No units that want shielding - e.g. we might be telling mobile shields to defend here temporarily; dont assign the shields, instead just give them orders so they are still of some use
            local tPotentialShieldTargets = {}
            if tTeamTargetLZData[AiBotMap.subrefLZTAlliedCombatUnits] then tPotentialShieldTargets = tTeamTargetLZData[AiBotMap.subrefLZTAlliedCombatUnits] end
            if AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefAlliedACU]) == false then
                for iACU, oACU in tTeamTargetLZData[AiBotMap.subrefAlliedACU] do
                    table.insert(tPotentialShieldTargets, oACU)
                end
            end

            if AiBotUtilities.IsTableEmpty(tPotentialShieldTargets) == false then
                for iTarget, oTarget in tPotentialShieldTargets do
                    if not(oTarget[refoAssignedMobileShield]) then --redundancy
                        --Assign the closest mobile shield
                        local iCurDist
                        local iClosestDist = 100000
                        local iClosestRef

                        for iShield, oShield in tShieldsToAssign do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering entry iShield='..iShield..'; Shield unit='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)) end
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oTarget:GetPosition())
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                iClosestRef = iShield
                            end
                            break
                        end
                        if iClosestRef then
                            --Dont record the shield as helpin this unit, instead just have it move to the unit temporarily - so only change the variable so movetoshieldtarget works
                            tShieldsToAssign[iClosestRef][refoMobileShieldTarget] = oTarget
                            MoveToShieldTarget(tShieldsToAssign[iClosestRef], tTeamTargetLZData[AiBotMap.reftClosestEnemyBase])
                            tShieldsToAssign[iClosestRef][refoMobileShieldTarget] = nil
                            table.remove(tShieldsToAssign, iClosestRef)
                            if bDebugMessages == true then LOG(sFunctionRef..': Backup shield assignment - Have removed shield with iClosestRef='..iClosestRef..' from the table of tShieldsToAssign; is table empty='..tostring(AiBotUtilities.IsTableEmpty(tShieldsToAssign))..'; size of table='..table.getn(tShieldsToAssign)) end
                            if AiBotUtilities.IsTableEmpty(tShieldsToAssign) then break end
                        else
                            tShieldsToAssign = {}
                        end
                    end
                end

                --Do we still have spare mobile shields?
                if AiBotUtilities.IsTableEmpty(tShieldsToAssign) == false then
                    --Get closest unit to enemy base and assign all remaining shields temporarily here
                    local iCurDist
                    local iClosestDist = 100000
                    local oClosestToEnemyBase

                    for iTarget, oTarget in tPotentialShieldTargets do
                        if AiBotUnitInfo.IsUnitValid(oTarget) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oTarget:GetPosition(), tTeamTargetLZData[AiBotMap.reftClosestEnemyBase])
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                oClosestToEnemyBase = oTarget
                            end
                        end
                    end
                    if oClosestToEnemyBase then
                        local tEnemyBase = tTeamTargetLZData[AiBotMap.reftClosestEnemyBase]
                        for iShield, oShield in tShieldsToAssign do
                            --Dont record the shield as helpin this unit, instead just have it move to the unit temporarily - so only change the variable so movetoshieldtarget works
                            if bDebugMessages == true then LOG(sFunctionRef..': About to tell shield '..(oShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oShield) or 'nil')..' to move towards oClosestToEnemyBase='..(oClosestToEnemyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestToEnemyBase) or 'nil')) end
                            oShield[refoMobileShieldTarget] = oClosestToEnemyBase
                            MoveToShieldTarget(oShield, tEnemyBase)
                            oShield[refoMobileShieldTarget] = nil
                            if bDebugMessages == true then LOG(sFunctionRef..': Backup shield assignment - have told shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..' to go to the closest enemy in this LZ to enemy base='..oClosestToEnemyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestToEnemyBase)) end
                        end
                    elseif bDebugMessages == true then LOG(sFunctionRef..': No friendly units close to enemy base - assuming this is termpoary due to unit being destroyed')
                    end
                end
            end
        end
    end
    if bNoUnitsWantingShielding then
        --Flag that this LZ no longer wants mobile shields
        tTeamTargetLZData[AiBotMap.refbLZWantsMobileShield] = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MoveToShieldTarget(oShield, tEnemyBase, tOptionalShieldLZTeamData, tOptionalEnemyDFUnits, tOptionalRallyPoint)
    --If tOptionalShieldLZTeamData is specified, then will check if safe to try and shield the unit

    if EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oShield.UnitId) then AiBotUtilities.ErrorHandler('Fatboy is being given orders as though it is a shielded unit') end
    local bMoveToUnit = true
    if tOptionalShieldLZTeamData and tOptionalEnemyDFUnits and tOptionalRallyPoint and (tOptionalShieldLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) >= 180 then
        local iDistToShieldTarget = AiBotUtilities.GetDistanceBetweenPositions(oShield[refoMobileShieldTarget]:GetPosition(), oShield:GetPosition())
        if iDistToShieldTarget >= 50 then
            local tShieldTargetLZData, tShieldTargetLZTeamData = AiBotMap.GetLandOrWaterZoneData(oShield[refoMobileShieldTarget]:GetPosition(), true, oShield:GetAIBrain().AiBotTeam)
            if not(tShieldTargetLZTeamData ==  tOptionalShieldLZTeamData) then
                if AiBotUtilities.GetDistanceBetweenPositions(oShield[refoMobileShieldTarget]:GetPosition(), tOptionalRallyPoint) >= AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), tOptionalRallyPoint) then
                    --Are we almost in range of an enemy unit in this zone?
                    if AiBotUtilities.IsTableEmpty(tOptionalEnemyDFUnits) == false then
                        if AiBotConditions.CloseToEnemyUnit(oShield:GetPosition(), tOptionalEnemyDFUnits, 5, oShield:GetAIBrain().AiBotTeam, true) then
                            --LOG('MoveToShieldTarget: Shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..' is in a dangerous zone and target '..oShield[refoMobileShieldTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield[refoMobileShieldTarget])..' is far away so will retreat; Does shield have active micro='..tostring(oShield[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Closest friendly base='..repru(tOptionalShieldLZTeamData[AiBotMap.reftClosestFriendlyBase]))
                            --AiBotUtilities.DrawLocation(oShield:GetPosition())
                            bMoveToUnit = false
                            --IssueTrackedMove(oUnit, tOrderPosition,                       iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc,                                                                                       bOverrideMicroOrder)
                            AiBotOrders.IssueTrackedMove(oShield, tOptionalRallyPoint, 5, false,                'ShBl'..oShield[refoMobileShieldTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield[refoMobileShieldTarget]), false)
                        end
                    end

                end
            end
        end

    end
    if bMoveToUnit then

        local oBP = oShield:GetBlueprint()
        --Decide whether to move towards the unit's target if the unit is moving (so e.g. if we are retreating we are less likely to block the retreating unit)
        local bGivenOrderForRetreating = false
        local tTargetFirstOrder = oShield[refoMobileShieldTarget][AiBotOrders.reftiLastOrders][1]
        if tTargetFirstOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueMove then
            local iDistToEnemyBaseFromUnit = AiBotUtilities.GetDistanceBetweenPositions(oShield[refoMobileShieldTarget]:GetPosition(), tEnemyBase)
            local iDistToEnemyBaseFromMoveTarget = AiBotUtilities.GetDistanceBetweenPositions(tTargetFirstOrder[AiBotOrders.subreftOrderPosition], tEnemyBase)
            if iDistToEnemyBaseFromMoveTarget > iDistToEnemyBaseFromUnit then
                --We are likely retreating
                bGivenOrderForRetreating = true
                local iShieldRadius = oBP.Defense.Shield.ShieldSize * 0.5
                local iShieldDistanceWanted = math.max(5, oBP.Defense.Shield.ShieldSize * 0.5)
                local iTargetSpeed = (oShield[refoMobileShieldTarget]:GetBlueprint().Physics.MaxSpeed or 0)
                local iDistWithinShieldAlready = iShieldRadius - AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oShield[refoMobileShieldTarget]:GetPosition())
                if iDistWithinShieldAlready >= 1 or iTargetSpeed + 1 + iDistWithinShieldAlready >= iShieldRadius then --More than 1 inside shield range or are likely to run into shield
                    iShieldDistanceWanted = iShieldDistanceWanted + math.max(iDistWithinShieldAlready, iTargetSpeed)
                end

                AiBotOrders.IssueTrackedMove(oShield, AiBotUtilities.MoveInDirection(oShield[refoMobileShieldTarget]:GetPosition(), AiBotUtilities.GetAngleFromAToB(oShield[refoMobileShieldTarget]:GetPosition(), tTargetFirstOrder[AiBotOrders.subreftOrderPosition]), iShieldDistanceWanted, true, false, true), math.min(3, iShieldDistanceWanted - 1, iShieldRadius - 1), false, 'ShRU'..oShield[refoMobileShieldTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield[refoMobileShieldTarget]))
            end
        end
        if not(bGivenOrderForRetreating) then
            local iShieldDistanceWanted = math.max(3, oBP.Defense.Shield.ShieldSize * 0.5 - 1 - oBP.Physics.MaxSpeed - (oShield[refoMobileShieldTarget]:GetBlueprint().Physics.MaxSpeed or 0))
            AiBotOrders.IssueTrackedMove(oShield, AiBotUtilities.MoveInDirection(oShield[refoMobileShieldTarget]:GetPosition(), AiBotUtilities.GetAngleFromAToB(tEnemyBase,oShield[refoMobileShieldTarget]:GetPosition()), iShieldDistanceWanted, true, false, true), math.min(5, iShieldDistanceWanted - 1), false, 'ShU'..oShield[refoMobileShieldTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield[refoMobileShieldTarget]))
        end
    end
end

function MoveToStealthTarget(oStealth, tEnemyBase, tOptionalStealthLZTeamData, tOptionalEnemyDFUnits, tOptionalRallyPoint)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MoveToStealthTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bMoveToUnit = true
    if tOptionalStealthLZTeamData and AiBotUtilities.IsTableEmpty(tOptionalEnemyDFUnits) == false and tOptionalRallyPoint then
        --Retreat if close to enemies
        if AiBotConditions.CloseToEnemyUnit(oStealth:GetPosition(), tOptionalEnemyDFUnits, 5, oStealth:GetAIBrain().AiBotTeam, true,    nil,        nil,                                oStealth) then
            if AiBotUnitInfo.IsUnitValid(oStealth[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) then
                local iAngleToEnemy = AiBotUtilities.GetAngleFromAToB(oStealth:GetPosition(), oStealth[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())
                local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oStealth:GetPosition(), tOptionalRallyPoint)
                local tTemporaryRetreatLocation
                if AiBotUtilities.GetAngleDifference(iAngleToEnemy, iAngleToRally) <= 50 then
                    tTemporaryRetreatLocation = AiBotUtilities.MoveInDirection(oStealth:GetPosition(), iAngleToEnemy - 180, 10, true, false, AiBotMap.bIsCampaignMap)
                    if not(AiBotUtilities.IsTableEmpty(tTemporaryRetreatLocation) == false and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tTemporaryRetreatLocation) == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tOptionalRallyPoint)) then
                        --We cant reach this location so will revert to rally point
                        tTemporaryRetreatLocation = tOptionalRallyPoint
                    end
                else
                    tTemporaryRetreatLocation = tOptionalRallyPoint
                end

                if AiBotUtilities.IsTableEmpty(tTemporaryRetreatLocation) == false then
                    oStealth[AiBotUnitInfo.refiTimeLastTriedRetreating] = math.floor(GetGameTimeSeconds())
                    AiBotOrders.IssueTrackedMove(oStealth, tTemporaryRetreatLocation, 4, false, 'StealthRn')
                    bMoveToUnit = false
                end
            end
        end
    end

    if bMoveToUnit then
        if bDebugMessages == true then LOG(sFunctionRef..': oStealth[refoMobileStealthTarget]='..(oStealth[refoMobileStealthTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oStealth[refoMobileStealthTarget]) or 'nil')..'; SizeX='..(oStealth[refoMobileStealthTarget]:GetBlueprint().SizeX or 'nil')..'; SizeZ='..(oStealth[refoMobileStealthTarget]:GetBlueprint().SizeZ or 'nil')..'; SizeX if do __blueprints='..(__blueprints[oStealth[refoMobileStealthTarget].UnitId].SizeX or 'nil')) end
        local oBP = oStealth:GetBlueprint()
        local oTargetBP = oStealth[refoMobileStealthTarget]:GetBlueprint()
        --Strange bug where t3 mobile arti :GetBlueprint() had no sizex; this worked as a workaround:
        if not(oTargetBP.SizeX) then oTargetBP = __blueprints[oStealth[refoMobileStealthTarget].UnitId] end
        local iStealthDistanceWanted = math.max(8, oBP.Intel.RadarStealthFieldRadius - 1 - oBP.Physics.MaxSpeed - (oTargetBP.Physics.MaxSpeed or 0))
        local iSize = math.max(oTargetBP.SizeX, oTargetBP.SizeZ)
        if iSize >= 1 then
            iStealthDistanceWanted = iStealthDistanceWanted - math.min(1.5, iSize * 0.5)
        end

        AiBotOrders.IssueTrackedMove(oStealth, AiBotUtilities.MoveInDirection(oStealth[refoMobileStealthTarget]:GetPosition(), AiBotUtilities.GetAngleFromAToB(tEnemyBase,oStealth[refoMobileStealthTarget]:GetPosition()), iStealthDistanceWanted, true, false, true), math.min(5, iStealthDistanceWanted - 1), false, 'StU'..oStealth[refoMobileStealthTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStealth[refoMobileStealthTarget]))
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageMobileShieldsInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tMobileShields)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageMobileShieldsInLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Size of tMobileShields='..table.getn(tMobileShields)) end

    local iCurShield, iMaxShield
    local tShieldsToRetreat = {}
    local tShieldsToAssign = {}
    local tEnemyBase = tLZTeamData[AiBotMap.reftClosestEnemyBase]
    if AiBotUtilities.IsTableEmpty(tEnemyBase) then
        AiBotUtilities.ErrorHandler('Couldnt find enemy base, will try backup approach')
        local iCurDist
        local iClosestDist = 100000
        local oClosestBrain
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()])
            if iCurDist < iClosestDist then
                iClosestDist = iCurDist
                oClosestBrain = oBrain
            end
        end
        tEnemyBase = AiBotMap.PlayerStartPoints[oClosestBrain:GetArmyIndex()]
    end
    local tEnemyDFUnits
    local tRallyPoint
    if (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= 200 then
        tEnemyDFUnits = EntityCategoryFilterDown(categories.DIRECTFIRE, tLZTeamData[AiBotMap.subrefTEnemyUnits])
        tRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 1, false)
    end
    local tOriginallyAssignedMobileShields = {}
    local bRetreatShield, iDistToShieldTarget
    local bCheckForEnemiesInsideShield = false
    if tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] < math.max(200, (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 0.8) then bCheckForEnemiesInsideShield = true end
    for iUnit, oUnit in tMobileShields do
        iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, false)
        if bDebugMessages == true then
            LOG(sFunctionRef..': Considering what to do with unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurShield='..iCurShield..'; iMaxShield='..iMaxShield..'; SHield%='..iCurShield/iMaxShield..'; oUnit[AiBotUnitInfo.refbWaitForShieldToBeRestored]='..tostring(oUnit[AiBotUnitInfo.refbWaitForShieldToBeRestored] or false))
            if AiBotUnitInfo.IsUnitValid(oUnit[refoMobileShieldTarget]) then
                LOG(sFunctionRef..': Cur shield target='..oUnit[refoMobileShieldTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[refoMobileShieldTarget])..'; Dist to this='..AiBotUtilities.GetDistanceBetweenPositions(oUnit[refoMobileShieldTarget]:GetPosition(), oUnit:GetPosition())..'; Is shield close to enemy units in this LZ='..tostring(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], 10, iTeam, true, nil, nil, nil, nil, false)))
            end
        end
        if oUnit[refoMobileShieldTarget][AiBotBuilding.reftArtiTemplateRefs] and not(oUnit[AiBotUnitInfo.refbEasyBrain]) then
            --Even if shield is down/low we want to remain with the shield we are covering; we also want to be disabled if enemy has teleport
            if not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
                if not(oUnit[AiBotUnitInfo.refbShieldIsDisabled]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasTeleport] then
                    AiBotUnitInfo.DisableUnitShield(oUnit)
                end
                table.insert(tOriginallyAssignedMobileShields, oUnit)
            end
        elseif not(oUnit[AiBotUnitInfo.refbEasyBrain]) and (iCurShield < iMaxShield * 0.5 or (oUnit[AiBotUnitInfo.refbWaitForShieldToBeRestored] and iCurShield < iMaxShield * 0.9)) then
            --Retreat
            table.insert(tShieldsToRetreat, oUnit)
        elseif oUnit[refoMobileShieldTarget] and AiBotUnitInfo.IsUnitValid(oUnit[refoMobileShieldTarget]) then
            bRetreatShield = false
            if not(oUnit[AiBotUnitInfo.refbEasyBrain]) and iCurShield < iMaxShield * 0.95 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and not(EntityCategoryContains(categories.COMMAND,oUnit[refoMobileShieldTarget].UnitId)) then
                --Are we almost in range of enemy units?
                iDistToShieldTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[refoMobileShieldTarget]:GetPosition())
                if iDistToShieldTarget >= 30 or bCheckForEnemiesInsideShield then
                    --CloseToEnemyUnit(tStartPosition, tUnitsToCheck,                   iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure, bIncludeEnemyAntiNavyRange)
                    if AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], 10, iTeam, true,                      nil,                    nil,                                oUnit,                                        nil,                            false) then
                        if iDistToShieldTarget >= 30 then
                            bRetreatShield = true
                        elseif bCheckForEnemiesInsideShield and oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] and AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()) <= (oUnit:GetBlueprint().Defense.Shield.ShieldSize or 0) * 0.6 + 3 then
                            --If enemy is almost inside our shield then want to retreat to try and save the mobile shield
                            bRetreatShield = true
                        end
                    end
                end
            end
            if bRetreatShield then
                if bDebugMessages == true then LOG(sFunctionRef..': Want to retreat shield due to risk enemy has units inbetween us and the target, or enemy is about to get underneath our shield') end
                table.insert(tShieldsToRetreat, oUnit)
                oUnit[AiBotUnitInfo.refbWaitForShieldToBeRestored] = true
            else
                table.insert(tOriginallyAssignedMobileShields, oUnit)
            end
        else
            table.insert(tShieldsToAssign, oUnit)
            if oUnit[AiBotUnitInfo.refbWaitForShieldToBeRestored] then oUnit[AiBotUnitInfo.refbWaitForShieldToBeRestored] = nil end
        end
    end
    if AiBotUtilities.IsTableEmpty(tShieldsToRetreat) == false then
        local tRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2)
        local tAmphibiousRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2, true)
        if bDebugMessages == true then LOG(sFunctionRef..': Will give orders to retreat, size of tShieldsToRetreat='..table.getn(tShieldsToRetreat)) end
        for iUnit, oUnit in tShieldsToRetreat do
            if bDebugMessages == true then
                local iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, false)
                LOG(sFunctionRef..': About to tell unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to run due to a low shield. iCurShield='..(iCurShield or 'nil')..'; iMaxShield='..(iMaxShield or 'nil')..'; Unit paused='..tostring(oUnit[AiBotUnitInfo.refbPaused])..'; Are power stalling='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; Team Net energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]..'; % stored E='..oUnit:GetAIBrain():GetEconomyStoredRatio('ENERGY')..'; Gross energy='..oUnit:GetAIBrain()[import('/lua/AiBot/AI/AiBotEconomy.lua').refiGrossEnergyBaseIncome]..'; oUnit.MyShield.IsOn==nil='..tostring(oUnit.MyShield.IsOn == nil))
            end
            ClearCurrentShieldTarget(oUnit)

            if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'ASRun'..iLandZone)
            else
                AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'SRun'..iLandZone)
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(tShieldsToAssign) == false then
        --Assign available shields to units in this zone wanting shielding
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield]) == false then
            ShieldUnitsInLandZone(tLZTeamData, tShieldsToAssign)
        end
        if AiBotUtilities.IsTableEmpty(tShieldsToAssign) == false then


            --Cycle through every land zone and record priority ones to shield
            if bDebugMessages == true then LOG(sFunctionRef..': Will give orders to tShieldsToAssign, size of table='..table.getn(tShieldsToAssign)) end
            local tiClosestLZWithNearbyThreat = {}
            local iClosestLZWithNoThreat
            local iClosestLZNotWantingShieldButWithUnits
            local iClosestLZWithAnyCombatUnits
            local tiAllOtherLZWantingShields = {}
            if tLZTeamData[AiBotMap.subrefbLZWantsSupport] and not(tLZTeamData[AiBotMap.refbLZWantsMobileShield]) and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits]) == false or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) == false) then iClosestLZNotWantingShieldButWithUnits = iLandZone end
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                local bEnemyHasTeleport = AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasTeleport]
                for iEntry, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                    local tTeamTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam]
                    if bDebugMessages == true then LOG(sFunctionRef..': iLandZone='..iLandZone..'; Considering other land zone '..tPathingDetails[AiBotMap.subrefLZNumber]..'; Other land zone DF threat='..(tTeamTargetLZData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 'nil')..'; Does this zone want mobile shields='..tostring(tTeamTargetLZData[AiBotMap.refbLZWantsMobileShield] or false)..'; Does target have active GE template='..tostring(AiBotConditions.HaveActiveGameEnderTemplateLogic(tTeamTargetLZData))) end
                    if tTeamTargetLZData[AiBotMap.refbLZWantsMobileShield] then
                        if tTeamTargetLZData[AiBotMap.refiEnemyAirToGroundThreat] > 0 or tTeamTargetLZData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 40 or (bEnemyHasTeleport and AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.refbLZWantsMobileShield]) == false and AiBotConditions.HaveActiveGameEnderTemplateLogic(tTeamTargetLZData)) then
                            ShieldUnitsInLandZone(tTeamTargetLZData, tShieldsToAssign)
                            if AiBotUtilities.IsTableEmpty(tShieldsToAssign) then break end
                        else
                            if AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefTEnemyUnits]) == false or tTeamTargetLZData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                                table.insert(tiClosestLZWithNearbyThreat, tPathingDetails[AiBotMap.subrefLZNumber])
                            else
                                table.insert(tiAllOtherLZWantingShields, tPathingDetails[AiBotMap.subrefLZNumber])
                                if not(iClosestLZWithNoThreat) then iClosestLZWithNoThreat = tPathingDetails[AiBotMap.subrefLZNumber] end
                            end
                        end
                    elseif not(iClosestLZNotWantingShieldButWithUnits) then
                        if tTeamTargetLZData[AiBotMap.subrefbLZWantsSupport] and AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefLZTAlliedCombatUnits]) == false then
                            iClosestLZNotWantingShieldButWithUnits = tPathingDetails[AiBotMap.subrefLZNumber]
                        end
                        if not(iClosestLZWithAnyCombatUnits) and (AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefLZTAlliedCombatUnits]) == false or AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefAlliedACU]) == false) then
                            iClosestLZWithAnyCombatUnits = tPathingDetails[AiBotMap.subrefLZNumber]
                        end
                    end

                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished checking other zones we can path to for units wanting shielding, is tShieldsToAssign empty='..tostring(AiBotUtilities.IsTableEmpty(tShieldsToAssign))..'; Is AiBotUtilities.IsTableEmpty(tiClosestLZWithNearbyThreat) empty='..tostring(AiBotUtilities.IsTableEmpty(tiClosestLZWithNearbyThreat))) end
            if AiBotUtilities.IsTableEmpty(tShieldsToAssign) == false then
                if AiBotUtilities.IsTableEmpty(tiClosestLZWithNearbyThreat) == false then
                    for _, iTargetLZ in  tiClosestLZWithNearbyThreat do
                        local tTeamTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iTargetLZ][AiBotMap.subrefLZTeamData][iTeam]
                        ShieldUnitsInLandZone(tTeamTargetLZData, tShieldsToAssign)
                        if AiBotUtilities.IsTableEmpty(tShieldsToAssign) then break end
                    end
                end
                if AiBotUtilities.IsTableEmpty(tShieldsToAssign) == false then
                    if iClosestLZWithNoThreat then
                        local tTeamTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZWithNoThreat][AiBotMap.subrefLZTeamData][iTeam]
                        if bDebugMessages == true then LOG(sFunctionRef..': Have mobile shields to assign, closest LZ='..iClosestLZWithNoThreat..'; DOes this LZ want mobile shields='..tostring(tTeamTargetLZData[AiBotMap.refbLZWantsMobileShield] or false)..'; is table of units wanting shielding empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileShield]))) end
                        ShieldUnitsInLandZone(tTeamTargetLZData, tShieldsToAssign)
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is tShieldsToAssign empty after checking for closest LZ with no threat='..tostring(AiBotUtilities.IsTableEmpty(tShieldsToAssign))..'; iClosestLZNotWantingShieldButWithUnits='..(iClosestLZNotWantingShieldButWithUnits or 'nil')) end
                    if AiBotUtilities.IsTableEmpty(tShieldsToAssign) == false then
                        if AiBotUtilities.IsTableEmpty(tiAllOtherLZWantingShields) == false then
                            for iEntry, iZone in tiAllOtherLZWantingShields do
                                if not(iZone ==iClosestLZWithNoThreat) then
                                    local tTeamTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZWithNoThreat][AiBotMap.subrefLZTeamData][iTeam]
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have mobile shields to assign, considering zone that wants shielding, iZone='..iZone..'; DOes this LZ want mobile shields='..tostring(tTeamTargetLZData[AiBotMap.refbLZWantsMobileShield] or false)..'; is table of units wanting shielding empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileShield]))) end
                                    ShieldUnitsInLandZone(tTeamTargetLZData, tShieldsToAssign)
                                    if AiBotUtilities.IsTableEmpty(tShieldsToAssign) then break end
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tShieldsToAssign) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': Still have shields to assign after considering all zones with adjacent enemy threats, so will flag that we failed to have shield targets for plateau '..iPlateau..'; For reference, the current land zone considering this is '..iLandZone..'; Time='..GetGameTimeSeconds()) end
                            if tLZData[AiBotMap.subrefLZIslandRef] then AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastTimeNoShieldTargetsByIsland][tLZData[AiBotMap.subrefLZIslandRef]] = GetGameTimeSeconds() end
                            --Dont have any land zones that want a mobile shield, but we have mobile shields - find the closest LZ  that wants DF or IF support and has DF or IF units, and send them here; if that's this LZ, then have them go to the unit closest to the enemy in this LZ, but without assigning them
                            if iClosestLZNotWantingShieldButWithUnits or iClosestLZWithAnyCombatUnits then
                                local tTeamTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][(iClosestLZNotWantingShieldButWithUnits or iClosestLZWithAnyCombatUnits)][AiBotMap.subrefLZTeamData][iTeam]
                                if bDebugMessages == true then LOG(sFunctionRef..': Have mobile shields to assign, closest LZ with friendly combat units that wants more units='..(iClosestLZNotWantingShieldButWithUnits or 'nil')..'; iClosestLZWithAnyCombatUnits='..(iClosestLZWithAnyCombatUnits or 'nil')..'; DOes this LZ want mobile shields='..tostring(tTeamTargetLZData[AiBotMap.refbLZWantsMobileShield] or false)..'; is table of units wanting shielding empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileShield]))) end
                                ShieldUnitsInLandZone(tTeamTargetLZData, tShieldsToAssign, true)
                            end
                            if AiBotUtilities.IsTableEmpty(tShieldsToAssign) == false then
                                --cant find any land zones with friendly combat units so have nowhere to assign mobile shields; will send them all to the nearest rally point instead
                                local tRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2)
                                local tAmphibiousRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2, true)
                                for iUnit, oUnit in tShieldsToAssign do
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                                        AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'ASBckup'..iLandZone)
                                    else
                                        AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'ShBckup'..iLandZone)
                                    end
                                end

                            end
                        end

                    end
                end
            end
        end
    end

    --Do we have any units in the zone without a shield, who are closer to the nearest enemy base than our current units? If so then assign a mobile shield already assigned to one of these units
    if AiBotUtilities.IsTableEmpty(tOriginallyAssignedMobileShields) == false then
        --First consider reassigning 1 shield if there are nearby enemy DF units and we have a unit closer to them than a current defended shield target
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield]) == false then
            local bHaveACUInZoneWithNoDFEnemies = false
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.COMMAND, tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield])) == false then bHaveACUInZoneWithNoDFEnemies = true end
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false or bHaveACUInZoneWithNoDFEnemies then
                local iClosestDistToEnemy = 10000
                local oClosestUnitWantingShieldToEnemy, iCurDist
                local bIncludeIndirect = true --v89 - changed to always include
                --if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false or (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] <= 15) or (tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0) > 0 then bIncludeIndirect = true end
                --Get closest enemy DF unit to our midpoint
                local oClosestEnemyToMidpoint
                local iClosestEnemyDist = 10000
                if not(bHaveACUInZoneWithNoDFEnemies) then
                    for iUnit, oUnit in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oUnit:GetPosition())
                        if iCurDist < iClosestEnemyDist then
                            iClosestEnemyDist = iCurDist
                            oClosestEnemyToMidpoint = oUnit
                        end
                    end
                end

                if oClosestEnemyToMidpoint or bHaveACUInZoneWithNoDFEnemies then
                    local tComparisonPosition
                    if bHaveACUInZoneWithNoDFEnemies then tComparisonPosition = tLZTeamData[AiBotMap.reftClosestEnemyBase] else tComparisonPosition =  oClosestEnemyToMidpoint:GetPosition() end
                    local bWantToShieldACU = false

                    for iUnit, oUnit in tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield] do
                        if not(AiBotUnitInfo.IsUnitValid(oClosestUnitWantingShieldToEnemy[refoAssignedMobileShield])) and ((oUnit[AiBotUnitInfo.refiDFRange] or 0) > 12 or (bIncludeIndirect and (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 12)) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tComparisonPosition)
                            if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then iCurDist = iCurDist / 1000 end
                            if iCurDist < iClosestDistToEnemy then
                                iClosestDistToEnemy = iCurDist
                                oClosestUnitWantingShieldToEnemy = oUnit
                            end
                        end
                    end
                    if oClosestUnitWantingShieldToEnemy then
                        if EntityCategoryContains(categories.COMMAND, oClosestUnitWantingShieldToEnemy.UnitId) then
                            bWantToShieldACU = true
                        end
                        local iFurthestShieldedDistToEnemy = 0
                        local oFurthestShieldToEnemy

                        if not(bWantToShieldACU) then
                            --Get the closest unit being shielded already (ignoring ACUs being shielded)
                            for iShield, oShield in tOriginallyAssignedMobileShields do

                                if not(EntityCategoryContains(categories.COMMAND, oShield[refoMobileShieldTarget].UnitId)) and not(oShield[refoMobileShieldTarget][AiBotBuilding.reftArtiTemplateRefs]) then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oShield[refoMobileShieldTarget]:GetPosition(), tComparisonPosition)
                                    if iCurDist > iFurthestShieldedDistToEnemy then
                                        iFurthestShieldedDistToEnemy = iCurDist
                                        oFurthestShieldToEnemy = oShield
                                    end
                                end
                            end
                        else
                            --Want the closest shield to the ACU
                            iFurthestShieldedDistToEnemy = 10000
                            for iShield, oShield in tOriginallyAssignedMobileShields do
                                if not(EntityCategoryContains(categories.COMMAND, oShield[refoMobileShieldTarget].UnitId)) and not(oShield[refoMobileShieldTarget][AiBotBuilding.reftArtiTemplateRefs]) then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oClosestUnitWantingShieldToEnemy:GetPosition())
                                    if iCurDist <     iFurthestShieldedDistToEnemy then
                                        iFurthestShieldedDistToEnemy = iCurDist
                                        oFurthestShieldToEnemy = oShield
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to reassign furthest away shield to closest shield for P'..iPlateau..'Z'..iLandZone..', iFurthestShieldedDistToEnemy='..iFurthestShieldedDistToEnemy..'; iClosestDistToEnemy='..iClosestDistToEnemy..'; oFurthestShieldToEnemy='..(oFurthestShieldToEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFurthestShieldToEnemy) or 'nil')..'; oClosestUnitWantingShieldToEnemy='..(oClosestUnitWantingShieldToEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnitWantingShieldToEnemy) or 'nil')..'; Does closest unit have a valid assigned shield='..tostring(AiBotUnitInfo.IsUnitValid(oClosestUnitWantingShieldToEnemy[refoAssignedMobileShield]))) end
                        if oFurthestShieldToEnemy and (bWantToShieldACU or iFurthestShieldedDistToEnemy - iClosestDistToEnemy >= 3) then
                            --Switch shields
                            if bDebugMessages == true then LOG(sFunctionRef..': Will switch shields, old target='..(oFurthestShieldToEnemy[refoMobileShieldTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFurthestShieldToEnemy[refoMobileShieldTarget]) or 'nil')..'; bWantToShieldACU='..tostring(bWantToShieldACU)) end
                            ClearCurrentShieldTarget(oFurthestShieldToEnemy)
                            RecordMobileShieldAgainstTarget(oFurthestShieldToEnemy, oClosestUnitWantingShieldToEnemy)
                        end
                    end
                end
            end
        end
        --Now move all shields to their designated unit to guard
        for iShield, oShield in tOriginallyAssignedMobileShields do
            --make sure we are behind the target
            if bDebugMessages == true then LOG(sFunctionRef..': Will try and get shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..' to move behind the shield target '..oShield[refoMobileShieldTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield[refoMobileShieldTarget])..'; Shield position='..repru(oShield:GetPosition())..'; Target last order position='..repru(oShield[refoMobileShieldTarget][AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition])) end
            MoveToShieldTarget(oShield, tEnemyBase, tLZTeamData, tEnemyDFUnits, tRallyPoint)
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageMobileStealthsInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tMobileStealths, iEnemyOmniCoverage)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageMobileStealthsInLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then
        local iEnemyOmniCoverage = AiBotConditions.GetEnemyOmniCoverageOfZone(iPlateau, iLandZone, iTeam)
        LOG(sFunctionRef..': Start of code, iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Size of tMobileStealths='..table.getn(tMobileStealths)..'; iEnemyOmniCoverage='..iEnemyOmniCoverage)
    end

    local tStealthsToAssign = {}
    local tEnemyBase = tLZTeamData[AiBotMap.reftClosestEnemyBase]
    if AiBotUtilities.IsTableEmpty(tEnemyBase) then
        AiBotUtilities.ErrorHandler('Couldnt find enemy base, will try backup approach')
        local iCurDist
        local iClosestDist = 100000
        local oClosestBrain
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()])
            if iCurDist < iClosestDist then
                iClosestDist = iCurDist
                oClosestBrain = oBrain
            end
        end
        tEnemyBase = AiBotMap.PlayerStartPoints[oClosestBrain:GetArmyIndex()]
    end
    local tEnemyDFUnits = tLZTeamData[AiBotMap.reftoNearestDFEnemies]
    local tRallyPoint
    if AiBotUtilities.IsTableEmpty(tEnemyDFUnits) == false then
        tRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 1, false)
    end

    local tOriginallyAssignedMobileStealths = {}

    --If enemy has omni coverage and we dont have units wanting mobile stealth in this zone, then clear any mobile stealths
    if iEnemyOmniCoverage >= 40 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileStealth]) then
        for iUnit, oUnit in tMobileStealths do
            if oUnit[refoMobileStealthTarget] and ((oUnit[refoMobileStealthTarget][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone and oUnit[refoMobileStealthTarget][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau) or not(EntityCategoryContains(categories.COMMAND + AiBotUnitInfo.refCategoryLandExperimental, oUnit[refoMobileStealthTarget].UnitId))) then
                if oUnit[refoMobileStealthTarget][refoAssignedMobileStealth] then oUnit[refoMobileStealthTarget][refoAssignedMobileStealth] = nil end
                oUnit[refoMobileStealthTarget] = nil
            end
            table.insert(tStealthsToAssign, oUnit) --We decide whether ot run from enemies in MoveToStealthTarget
        end
    else
        for iUnit, oUnit in tMobileStealths do
            if oUnit[refoMobileStealthTarget] and AiBotUnitInfo.IsUnitValid(oUnit[refoMobileStealthTarget]) then
                table.insert(tOriginallyAssignedMobileStealths, oUnit)

            else
                table.insert(tStealthsToAssign, oUnit) --We decide whether ot run from enemies in MoveToStealthTarget
            end
        end
    end


    if AiBotUtilities.IsTableEmpty(tStealthsToAssign) == false then
        --First check none of our mobile stealth units are almost in range of an enemy that can see them
        --Stealth units in this zone first
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileStealth]) == false then
            StealthUnitsInLandZone(tLZTeamData, tStealthsToAssign)
        end
        if AiBotUtilities.IsTableEmpty(tStealthsToAssign) == false then
            --Check priority table of units wanting stealth
            local aiBrain = tStealthsToAssign[1]:GetAIBrain()
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.reftoPriorityUnitsWantingMobileStealth]) == false then
                local oClosestPriorityUnitWantingStealth
                local iClosestPriorityUnitWantingStealthDist = 250
                local iCurPriorityUnitWantingStealthDist

                for iUnit, oUnit in AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.reftoPriorityUnitsWantingMobileStealth] do
                    if not(oUnit.Dead) and not(AiBotUnitInfo.IsUnitValid(oUnit[refoAssignedMobileStealth])) and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition()) == tLZData[AiBotMap.subrefLZIslandRef] then
                        iCurPriorityUnitWantingStealthDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                        if iCurPriorityUnitWantingStealthDist < iClosestPriorityUnitWantingStealthDist then
                            local tUnitLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': Have a priority unit wanting mobile stealth, unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' tUnitLZTeamData[refiEnemyOmniCoverage]='..(tUnitLZTeamData[AiBotMap.refiEnemyOmniCoverage] or 'nil')..'; Unit assigned to P'..oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]..'Z'..oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]..'; iPlateau='..iPlateau) end
                            if (tUnitLZTeamData[AiBotMap.refiEnemyOmniCoverage] or 0) < 40 then
                                --Want to assign a mobile stealth to the closest such unit
                                iClosestPriorityUnitWantingStealthDist = iCurPriorityUnitWantingStealthDist
                                oClosestPriorityUnitWantingStealth = oUnit
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for priority units wanting stealth, oClosestPriorityUnitWantingStealth='..(oClosestPriorityUnitWantingStealth.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestPriorityUnitWantingStealth) or 'nil')) end
                if AiBotUnitInfo.IsUnitValid(oClosestPriorityUnitWantingStealth) then
                    local tTargetUnitLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][oClosestPriorityUnitWantingStealth[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZTeamData][iTeam]
                    if tTargetUnitLZTeamData then
                        --StealthUnitsInLandZone(tTeamTargetLZData, tStealthsToAssign, bAssignAllStealths, toOptionalUnitsToStealth)
                        StealthUnitsInLandZone(tTargetUnitLZTeamData, tStealthsToAssign, false, {oClosestPriorityUnitWantingStealth})
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished calling StealthUnitsInLandZone for the target unit zone='..(oClosestPriorityUnitWantingStealth[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or 'nil')) end
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tStealthsToAssign) == false then

                --Cycle through every land zone and record priority ones to Stealth
                if bDebugMessages == true then LOG(sFunctionRef..': Will give orders to tStealthsToAssign, size of table='..table.getn(tStealthsToAssign)) end
                local tiClosestLZWithNearbyThreat = {}
                local iClosestLZWithNoThreat
                local iClosestLZNotWantingStealthButWithUnits
                local iClosestLZWithAnyCombatUnits
                if tLZTeamData[AiBotMap.subrefbLZWantsSupport] and not(tLZTeamData[AiBotMap.refbLZWantsMobileStealth]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits]) == false then iClosestLZNotWantingStealthButWithUnits = iLandZone end
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                    for iEntry, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                        local tTeamTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam]
                        if tTeamTargetLZData[AiBotMap.refbLZWantsMobileStealth] then
                            if tTeamTargetLZData[AiBotMap.refiEnemyAirToGroundThreat] > 0 or tTeamTargetLZData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 40 then
                                StealthUnitsInLandZone(tTeamTargetLZData, tStealthsToAssign)
                                if AiBotUtilities.IsTableEmpty(tStealthsToAssign) then break end
                            elseif AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefTEnemyUnits]) == false or tTeamTargetLZData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                                table.insert(tiClosestLZWithNearbyThreat, tPathingDetails[AiBotMap.subrefLZNumber])
                            elseif not(iClosestLZWithNoThreat) then iClosestLZWithNoThreat = tPathingDetails[AiBotMap.subrefLZNumber]
                            end
                        elseif not(iClosestLZNotWantingStealthButWithUnits) then
                            if tTeamTargetLZData[AiBotMap.subrefbLZWantsSupport] and AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefLZTAlliedCombatUnits]) == false then iClosestLZNotWantingStealthButWithUnits = tPathingDetails[AiBotMap.subrefLZNumber] end
                            if not(iClosestLZWithAnyCombatUnits) and AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.subrefLZTAlliedCombatUnits]) == false then iClosestLZWithAnyCombatUnits = tPathingDetails[AiBotMap.subrefLZNumber] end
                        end

                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished checking other zones we can path to for units wanting Stealthing, is tStealthsToAssign empty='..tostring(AiBotUtilities.IsTableEmpty(tStealthsToAssign))..'; Is AiBotUtilities.IsTableEmpty(tiClosestLZWithNearbyThreat) empty='..tostring(AiBotUtilities.IsTableEmpty(tiClosestLZWithNearbyThreat))) end
                if AiBotUtilities.IsTableEmpty(tStealthsToAssign) == false then
                    if AiBotUtilities.IsTableEmpty(tiClosestLZWithNearbyThreat) == false then
                        for _, iTargetLZ in  tiClosestLZWithNearbyThreat do
                            local tTeamTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iTargetLZ][AiBotMap.subrefLZTeamData][iTeam]
                            StealthUnitsInLandZone(tTeamTargetLZData, tStealthsToAssign)
                            if AiBotUtilities.IsTableEmpty(tStealthsToAssign) then break end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tStealthsToAssign) == false then
                        if iClosestLZWithNoThreat then
                            local tTeamTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iClosestLZWithNoThreat][AiBotMap.subrefLZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': Have mobile Stealths to assign, closest LZ='..iClosestLZWithNoThreat..'; DOes this LZ want mobile Stealths='..tostring(tTeamTargetLZData[AiBotMap.refbLZWantsMobileStealth] or false)..'; is table of units wanting Stealthing empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileStealth]))) end
                            StealthUnitsInLandZone(tTeamTargetLZData, tStealthsToAssign)
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Is tStealthsToAssign empty after checking for closest LZ with no threat='..tostring(AiBotUtilities.IsTableEmpty(tStealthsToAssign))..'; iClosestLZNotWantingStealthButWithUnits='..(iClosestLZNotWantingStealthButWithUnits or 'nil')) end
                        if AiBotUtilities.IsTableEmpty(tStealthsToAssign) == false then
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastTimeNoStealthTargetsByPlateau][iPlateau] = GetGameTimeSeconds()
                            --Dont have any land zones that want a mobile Stealth, but we have mobile Stealths - find the closest LZ  that wants DF or IF support and has DF or IF units, and send them here; if that's this LZ, then have them go to the unit closest to the enemy in this LZ, but without assigning them
                            if iClosestLZNotWantingStealthButWithUnits or iClosestLZWithAnyCombatUnits then
                                local tTeamTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][(iClosestLZNotWantingStealthButWithUnits or iClosestLZWithAnyCombatUnits)][AiBotMap.subrefLZTeamData][iTeam]
                                if bDebugMessages == true then LOG(sFunctionRef..': Have mobile Stealths to assign, closest LZ with friendly combat units that wants more units='..(iClosestLZNotWantingStealthButWithUnits or 'nil')..'; iClosestLZWithAnyCombatUnits='..(iClosestLZWithAnyCombatUnits or 'nil')..'; DOes this LZ want mobile Stealths='..tostring(tTeamTargetLZData[AiBotMap.refbLZWantsMobileStealth] or false)..'; is table of units wanting Stealthing empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamTargetLZData[AiBotMap.reftoLZUnitsWantingMobileStealth]))) end
                                StealthUnitsInLandZone(tTeamTargetLZData, tStealthsToAssign, true)
                            end
                            if AiBotUtilities.IsTableEmpty(tStealthsToAssign) == false then
                                --No targets for mobile stealth
                                if bDebugMessages == true then LOG(sFunctionRef..': couldnt find any land zones with friendly combat units so have nowhere to assign mobile Stealths; will send them all to the nearest rally point instead') end
                                local tRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2)
                                for iUnit, oUnit in tStealthsToAssign do
                                    AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'StBckup'..iLandZone)
                                end

                            end

                        end
                    end
                end
            end
        end
    end

    if AiBotUtilities.IsTableEmpty(tOriginallyAssignedMobileStealths) == false then
        --First consider reassigning 1 Stealth if there are nearby enemy DF units and we have a unit closer to them than a current defended Stealth target
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileStealth]) == false and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
            local iClosestDistToEnemy = 10000
            local oClosestUnitWantingStealthToEnemy, iCurDist
            local bIncludeIndirect = true --v89 - changed to always include
            --if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false or (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrStealth] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrStealth] <= 15) or (tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0) > 0 then bIncludeIndirect = true end
            --Get closest enemy DF unit to our midpoint
            local oClosestEnemyToMidpoint
            local iClosestEnemyDist = 10000
            for iUnit, oUnit in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oUnit:GetPosition())
                if iCurDist < iClosestEnemyDist then
                    iClosestEnemyDist = iCurDist
                    oClosestEnemyToMidpoint = oUnit
                end
            end

            if oClosestEnemyToMidpoint then
                for iUnit, oUnit in tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileStealth] do
                    if not(AiBotUnitInfo.IsUnitValid(oUnit[refoAssignedMobileStealth])) and ((oUnit[AiBotUnitInfo.refiDFRange] or 0) > 12 or (bIncludeIndirect and (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 12)) then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestEnemyToMidpoint:GetPosition())
                        if iCurDist < iClosestDistToEnemy then
                            iClosestDistToEnemy = iCurDist
                            oClosestUnitWantingStealthToEnemy = oUnit
                        end
                    end
                end
                if oClosestUnitWantingStealthToEnemy then
                    --Get the closest unit being Stealthed already (ignoring ACUs being Stealthed)
                    local iFurthestStealthedDistToEnemy = 0
                    local oFurthestStealthToEnemy


                    for iStealth, oStealth in tOriginallyAssignedMobileStealths do

                        if not(EntityCategoryContains(categories.COMMAND + categories.EXPERIMENTAL, oStealth[refoMobileStealthTarget].UnitId)) then --never reassign an ACU or experimental mobile stealth
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oStealth[refoMobileStealthTarget]:GetPosition(), oClosestEnemyToMidpoint:GetPosition())
                            if iCurDist > iFurthestStealthedDistToEnemy then
                                iFurthestStealthedDistToEnemy = iCurDist
                                oFurthestStealthToEnemy = oStealth
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to reassign furthest away Stealth to closest Stealth for P'..iPlateau..'Z'..iLandZone..', iFurthestStealthedDistToEnemy='..iFurthestStealthedDistToEnemy..'; iClosestDistToEnemy='..iClosestDistToEnemy..'; oFurthestStealthToEnemy='..(oFurthestStealthToEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFurthestStealthToEnemy) or 'nil')..'; oClosestUnitWantingStealthToEnemy='..(oClosestUnitWantingStealthToEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnitWantingStealthToEnemy) or 'nil')) end
                    if oFurthestStealthToEnemy and iFurthestStealthedDistToEnemy - iClosestDistToEnemy >= 3 then
                        --Switch Stealths
                        if bDebugMessages == true then LOG(sFunctionRef..': Will switch Stealths, old target='..oFurthestStealthToEnemy[refoMobileStealthTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFurthestStealthToEnemy[refoMobileStealthTarget])) end
                        oFurthestStealthToEnemy[refoMobileStealthTarget][refoAssignedMobileStealth] = nil
                        oFurthestStealthToEnemy[refoMobileStealthTarget] = oClosestUnitWantingStealthToEnemy
                        oClosestUnitWantingStealthToEnemy[refoAssignedMobileStealth] = oFurthestStealthToEnemy
                    end
                end
            end
        end
        --Now move all Stealths to their designated unit to guard
        for iStealth, oStealth in tOriginallyAssignedMobileStealths do
            --make sure we are behind the target
            if bDebugMessages == true then LOG(sFunctionRef..': Will try and get Stealth '..oStealth.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStealth)..' to move behind the Stealth target '..oStealth[refoMobileStealthTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStealth[refoMobileStealthTarget])..'; Stealth position='..repru(oStealth:GetPosition())..'; Target last order position='..repru(oStealth[refoMobileStealthTarget][AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition])) end
            MoveToStealthTarget(oStealth, tEnemyBase, tLZTeamData, tEnemyDFUnits, tRallyPoint)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageMAAInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tAvailableMAA)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageMAAInLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2) --Get a LZ up to 3 land zones away to retreat to (i.e. will pick rally point and then move 2 towards it)
    local tAmphibiousRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2, true)
    local bRetreatWithAllMAA = false
    local bAttackMoveWithMAA = false

    --Consider retreating if insufficient MAA to deal with enemy air to ground threat and lack significant fixed AA in this zone
    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to retreat or attack move vs enemy air, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; Team has air control='..tostring(AiBotConditions.TeamHasAirControl(iTeam))) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 2000 and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= math.min(8000, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] * 0.25) and not(AiBotConditions.TeamHasAirControl(iTeam)) then
        local bBombersOrTransportNearby = false
        local iAdjLZEnemyGunshipThreat = 0
        local iAdjLZOurMAAThreat = (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) - (tLZTeamData[AiBotMap.subrefLZThreatAllyMAA] or 0) --Include fixedAA from this zone

        function ConsiderZoneAirAndMAAValues(tCurZoneTeamData)
            if AiBotUtilities.IsTableEmpty(tCurZoneTeamData[AiBotMap.reftLZEnemyAirUnits]) == false then
                if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryBomber + AiBotUnitInfo.refCategoryTransport, tCurZoneTeamData[AiBotMap.reftLZEnemyAirUnits])) == false then
                    bBombersOrTransportNearby = true
                else
                    iAdjLZEnemyGunshipThreat = iAdjLZEnemyGunshipThreat + (tCurZoneTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)
                end
            end
            iAdjLZOurMAAThreat = iAdjLZOurMAAThreat + tLZTeamData[AiBotMap.subrefLZThreatAllyMAA]
        end
        ConsiderZoneAirAndMAAValues(tLZTeamData)

        if not(bBombersOrTransportNearby) then
            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                ConsiderZoneAirAndMAAValues(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
                if bBombersOrTransportNearby then break end
            end
        end
        if not(bBombersOrTransportNearby) then
            if iAdjLZEnemyGunshipThreat > iAdjLZOurMAAThreat * 4 then
                tLZTeamData[AiBotMap.subrefLZTimeMAARetreatedFromGunships] = GetGameTimeSeconds()
                bRetreatWithAllMAA = true
            elseif iAdjLZEnemyGunshipThreat > math.min(iAdjLZOurMAAThreat, 8000) then
                bAttackMoveWithMAA = true
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bBombersOrTransportNearby='..tostring(bBombersOrTransportNearby)..'; iAdjLZEnemyGunshipThreat='..iAdjLZEnemyGunshipThreat..'; iAdjLZOurMAAThreat='..iAdjLZOurMAAThreat..'; bAttackMoveWithMAA='..tostring(bAttackMoveWithMAA)..'; bRetreatWithAllMAA='..tostring(bRetreatWithAllMAA)) end
    end

    --First split the MAA into those that need to run (due to being in range of DF units) and those that can advance
    local tMAAToAdvance = {}
    local toEnemiesToAvoid
    if (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0) == 0 then
        toEnemiesToAvoid = tLZTeamData[AiBotMap.reftoNearestDFEnemies]
    else
        toEnemiesToAvoid = {}
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
            for iUnit, oUnit in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                table.insert(toEnemiesToAvoid, oUnit)
            end
        end
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
            for iUnit, oUnit in tLZTeamData[AiBotMap.subrefTEnemyUnits] do
                if (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 0 and (oUnit[AiBotUnitInfo.refiDFRange] or 0) == 0 and (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) <= 100 then
                    table.insert(toEnemiesToAvoid, oUnit)
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, is table of nearest DF enemies empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; is toEnemiesToAvoid empty='..tostring(AiBotUtilities.IsTableEmpty(toEnemiesToAvoid))..'; P='..iPlateau..'; Zone='..iLandZone) end
    if AiBotUtilities.IsTableEmpty(toEnemiesToAvoid) and not(bRetreatWithAllMAA) then
        --No DF enemies so treat all MAA as being available
        tMAAToAdvance = tAvailableMAA
        if bDebugMessages == true then LOG(sFunctionRef..': No DF enemies so will consider advancing with all MAA') end
    else
        local iRunThreshold = 20
        local iIndirectRunThreshold = 6
        if tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 then
            iRunThreshold = 14
            iIndirectRunThreshold = 3
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) == false then
                iRunThreshold = 10
                iIndirectRunThreshold = 0
            end
        end
        --Increase run threshold if we dont have a significant combat force in this zone
        if tLZTeamData[AiBotMap.subrefbLZWantsDFSupport] and tLZTeamData[AiBotMap.subrefLZThreatAllyMAA] > (tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] + tLZTeamData[AiBotMap.subrefLZSValue]) * 2 and tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] < tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] then
            iRunThreshold = iRunThreshold * 2
            iIndirectRunThreshold = iIndirectRunThreshold + 2
        end

        local bMovingTowardsEnemy, iAngleToRally, iAngleToNearestUnit, bAmphibiousUnit
        local bCampaignMap = AiBotMap.bIsCampaignMap
        if bDebugMessages == true then
            LOG(sFunctionRef..': Will list out every unit in toEnemiesToAvoid')
            for iUnit, oUnit in toEnemiesToAvoid do
                LOG(sFunctionRef..': Enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit))
            end
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                    LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Is table of DF enemies empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies])))
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                        for iUnit, oUnit in tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                            LOG(sFunctionRef..': Adj LZ enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit))
                        end
                    end
                end
            end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': iRunThreshold='..iRunThreshold..'; iIndirectRunThreshold='..iIndirectRunThreshold..'; Enemy air to ground threat='..(tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 'nil')) end
        for iUnit, oUnit in tAvailableMAA do
            --Run if within 14 of being in range of enemy direct fire
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if friendly unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is in range of an enemy unit, is close to enemy='..tostring(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), toEnemiesToAvoid, iRunThreshold, iTeam, true                    , nil,                  nil,                                oUnit                                        , nil                           , nil                           , true,                             iIndirectRunThreshold))) end
            --                  CloseToEnemyUnit(tStartPosition, tUnitsToCheck,      iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure, bIncludeEnemyAntiNavyRange, bIncludeEnemyIndirectRangeIfNoDFRange, iIndirectDistThresholdOverride)
            if AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), toEnemiesToAvoid, iRunThreshold, iTeam, true                    , nil,                  nil,                                oUnit                                        , nil                           , nil                           , true,                             iIndirectRunThreshold) then
                if bDebugMessages == true then
                    LOG(sFunctionRef..': MAA '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is too close to DF enemy, iRunThreshold='..iRunThreshold..'; will run back; will list out enemy units and distance to us in a moment')
                    for iEnemy, oEnemy in toEnemiesToAvoid do
                        LOG('oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; DF r ange='..(oEnemy[AiBotUnitInfo.refiDFRange] or 'nil')..'; IF range='..(oEnemy[AiBotUnitInfo.refiIndirectRange] or 'nil')..'; Dist to this MAA unit='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; Actual distance using actual position='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEnemy:GetPosition()))
                    end
                end
                --Does moving towards the rally point take us closer to the enemy?
                bMovingTowardsEnemy = false
                bAmphibiousUnit = EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId)
                local tTempRetreatLocation
                if oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] then
                    local tCurRallyPoint
                    if bAmphibiousUnit then
                        tCurRallyPoint = tAmphibiousRallyPoint
                    else
                        tCurRallyPoint = tRallyPoint
                    end
                    iAngleToRally = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tRallyPoint)
                    iAngleToNearestUnit = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': iAngleToRally='..iAngleToRally..'; iAngleToNearestUnit='..iAngleToNearestUnit..'; Angle dif='..AiBotUtilities.GetAngleDifference(iAngleToRally, iAngleToNearestUnit)) end
                    if AiBotUtilities.GetAngleDifference(iAngleToRally, iAngleToNearestUnit) <= 60 then --tried with lower value of 45 and led to MAA moving closer to enemy
                        bMovingTowardsEnemy = true
                        --Can we move in the opposite direction to the enemy?
                        tTempRetreatLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleToNearestUnit + 180, 20, true, false, bCampaignMap)
                        if AiBotUtilities.IsTableEmpty(tTempRetreatLocation) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': Island ref for tempretreatlocation='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tTempRetreatLocation) or 'nil')..'; LZData island ref='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')) end
                            if not(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tTempRetreatLocation) == tLZData[AiBotMap.subrefLZIslandRef]) then
                                tTempRetreatLocation = nil
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': MAA will retreat, tTempRetreatLocation='..repru(tTempRetreatLocation)..'; Angle from mAA to this='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), (tTempRetreatLocation or {0,0,0}))) end
                if AiBotUtilities.IsTableEmpty(tTempRetreatLocation) == false then
                    AiBotOrders.IssueTrackedMove(oUnit, tTempRetreatLocation, 6, false, 'ORun'..iLandZone)
                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                    --IssueTrackedMove(oUnit, tOrderPosition, iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
                    AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'MAAConsA'..iLandZone)
                else
                    if bDebugMessages == true then LOG(sFunctionRef..'; Will retreat to rally point, angle to rally='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tRallyPoint)..'; Dist to rally='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint)) end
                    AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'MAAConsL'..iLandZone)
                end
                oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = GetGameTimeSeconds()
            elseif bRetreatWithAllMAA then
                if bAmphibiousUnit then
                    AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'ARun'..iLandZone)
                else
                    AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'Run'..iLandZone)
                end
                oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = GetGameTimeSeconds()
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Will treat MAA as not in danger and consider advancing with it') end
                table.insert(tMAAToAdvance, oUnit)
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of tMAAToAdvance empty='..tostring(AiBotUtilities.IsTableEmpty(tMAAToAdvance))) end


    --If enemy has air units in this zone then send the MAA to advance units towards it, but avoid enemy land units
    if AiBotUtilities.IsTableEmpty(tMAAToAdvance) == false then
        if bDebugMessages == true then LOG(sFunctionRef..': Number of MAA units to advance='..table.getn(tMAAToAdvance)..'; Is table of enemy air units for this LZ '..iLandZone..' empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]))..'; bRetreatWithAllMAA='..tostring(bRetreatWithAllMAA)) end
        local bIgnorePlayableAreaCheck = not(AiBotMap.bIsCampaignMap)
        if bRetreatWithAllMAA then
            for iUnit, oUnit in tMAAToAdvance do
                if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                    AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'MAACons2A'..iLandZone)
                else
                    AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'MAACons2L'..iLandZone)
                end
            end
        elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false then
            --Move towards the nearest enemy air unit to the LZ midpoint
            local oNearestEnemyToMidpoint
            local iClosestDist = 100000
            local iCurDist
            --Get closest enemy air unit
            for iUnit, oUnit in tLZTeamData[AiBotMap.reftLZEnemyAirUnits] do
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
                if iCurDist < iClosestDist then
                    iClosestDist = iCurDist
                    oNearestEnemyToMidpoint = oUnit
                end
            end

            --Move towards the air unit
            local tOrderPosition = oNearestEnemyToMidpoint:GetPosition()
            if bDebugMessages == true then
                LOG(sFunctionRef..': GameTime='..GetGameTimeSeconds()..' Will order every MAA to move to oNearestEnemyToMidpoint='..oNearestEnemyToMidpoint.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToMidpoint)..' at position '..repru(oNearestEnemyToMidpoint:GetPosition()))
                --AiBotUtilities.DrawLocation(tOrderPosition) --this will desync the replay so only manually enable
            end
            --local tRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2, false)

            for iUnit, oUnit in tMAAToAdvance do
                --Below is redundant so commented out, as already doing close to enemy check above
                --CloseToEnemyUnit(tStartPosition,       tUnitsToCheck,              iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure, bIncludeEnemyAntiNavyRange)
                --[[if AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], 6, iTeam, true,               nil,                        nil,                                nil,                                    nil,                                    false) then
                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tRallyPoint, 7, false, 'MmaAR' )
                else--]]
                if bAttackMoveWithMAA then
                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tOrderPosition, 7, false, 'MNAm')
                else
                    AiBotOrders.IssueTrackedMove(oUnit, tOrderPosition, 7, false, 'MNA')
                end
                --end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will do reprs of orders of the first unit in tMAAToAdvance, '..tMAAToAdvance[1].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tMAAToAdvance[1])..': '..reprs(tMAAToAdvance[1][AiBotOrders.reftiLastOrders])) end

        else
            --Enemy doesnt have any air units, so consider if there are other land zones we want to support with MAA
            local tLZToReinforceModDistance = {}
            local iCurModDist
            local bSignificantAdjacentDanger = false
            local iMinCombatIfSignifDanger = 0
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                --If there are enemies in an adjacent LZ, then be more cautious with where to send MAA
                if tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > 0 or tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeIFThreat] > 0 then
                    bSignificantAdjacentDanger = true
                    iMinCombatIfSignifDanger = math.max(2000, (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] + tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeIFThreat]) * 0.5)
                elseif tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                    local iEnemyThreat = math.max(0, (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0))
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            iEnemyThreat = iEnemyThreat + math.max(0, (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tAdjLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0))
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iEnemyThreat (i.e. net adjacent combat threat)='..iEnemyThreat..'; This zone ally MAA='..tLZTeamData[AiBotMap.subrefLZThreatAllyMAA]) end
                    if iEnemyThreat > math.min(800, (tLZTeamData[AiBotMap.subrefLZThreatAllyMAA] or 0) * 0.04) then
                        bSignificantAdjacentDanger = true
                        iMinCombatIfSignifDanger = math.min(iEnemyThreat * 0.2, (tLZTeamData[AiBotMap.subrefLZThreatAllyMAA] or 0) * 0.1, 800)
                    end
                end

                if bDebugMessages == true then LOG(sFunctionRef..': About to consider all other adjacent land zones to iLandZone '..iLandZone..', reprs of tLZData[AiBotMap.subrefLZPathingToOtherLandZones]='..reprs(tLZData[AiBotMap.subrefLZPathingToOtherLandZones])..'; Size of tMAAToAdvance='..table.getn(tMAAToAdvance)..'; bSignificantAdjacentDanger='..tostring(bSignificantAdjacentDanger)..'; iMinCombatIfSignifDanger='..iMinCombatIfSignifDanger) end

                for iEntry, tPathDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                    local tAltTeamLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam]
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to send MAA to assist alt LZ '..tPathDetails[AiBotMap.subrefLZNumber]..'; tAltTeamLZData[AiBotMap.subrefLZMAAThreatWanted]='..tAltTeamLZData[AiBotMap.subrefLZMAAThreatWanted]..'; tAltTeamLZData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..tAltTeamLZData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; subrefLZThreatAllyMAA='..tAltTeamLZData[AiBotMap.subrefLZThreatAllyMAA]..'; Air to ground threat in this alt LZ='..tAltTeamLZData[AiBotMap.refiEnemyAirToGroundThreat]..'; GetNetMAAWantedForZone='..AiBotConditions.GetNetMAAWantedForZone(tAltTeamLZData)) end
                    if bIgnorePlayableAreaCheck or AiBotConditions.IsLocationInPlayableArea(tAltTeamLZData[AiBotMap.subrefMidpoint]) then
                        if tAltTeamLZData[AiBotMap.subrefLZMAAThreatWanted] > tAltTeamLZData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or (tAltTeamLZData[AiBotMap.subrefLZMAAThreatWanted] > tAltTeamLZData[AiBotMap.subrefLZThreatAllyMAA] and AiBotConditions.GetNetMAAWantedForZone(tAltTeamLZData) > 0) then
                            if not(bSignificantAdjacentDanger) or (tLZTeamData[AiBotMap.subrefLZSValue] > 30 or tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] > math.min(iMinCombatIfSignifDanger, tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal])) then
                                iCurModDist = tPathDetails[AiBotMap.subrefLZTravelDist]
                                if tAltTeamLZData[AiBotMap.refiEnemyAirToGroundThreat] > 0 then
                                    iCurModDist = iCurModDist - 200
                                    if tAltTeamLZData[AiBotMap.subrefLZTThreatAllyCombatTotal] > 0 then iCurModDist = iCurModDist - 35 end
                                elseif (tAltTeamLZData[AiBotMap.refiEnemyAirOtherThreat] + tLZTeamData[AiBotMap.refiEnemyAirAAThreat]) > 45 then iCurModDist = iCurModDist - 100
                                end
                                if AiBotUtilities.IsTableEmpty(tAltTeamLZData[AiBotMap.subreftoLZOrWZAlliedUnits]) then iCurModDist = iCurModDist + 100 end
                                if tAltTeamLZData[AiBotMap.subrefTThreatEnemyCombatTotal] > 6 then
                                    iCurModDist = iCurModDist + 50
                                    if tAltTeamLZData[AiBotMap.subrefLZTThreatAllyCombatTotal] == 0 then
                                        iCurModDist = iCurModDist + 150
                                    elseif tAltTeamLZData[AiBotMap.subrefTThreatEnemyCombatTotal] > tAltTeamLZData[AiBotMap.subrefLZTThreatAllyCombatTotal] then
                                        iCurModDist = iCurModDist + 75
                                    end
                                    --tAltTeamLZData[AiBotMap.subrefTThreatEnemyCombatTotal] > subrefLZTThreatAllyCombatTotal
                                end
                                tLZToReinforceModDistance[tPathDetails[AiBotMap.subrefLZNumber]] = iCurModDist
                            end
                        end
                    end
                end
                if AiBotUtilities.IsTableEmpty(tLZToReinforceModDistance) == false then
                    for iLZ, iModDist in AiBotUtilities.SortTableByValue(tLZToReinforceModDistance, false) do
                        if bDebugMessages == true then LOG(sFunctionRef..': About to send MAA to support zone '..iLZ..'; iModDist='..iModDist..'; size of tMAAToAdvance='..table.getn(tMAAToAdvance)) end
                        SendMAAToSupportLandZone(tMAAToAdvance, iPlateau, iTeam, iLZ)
                        if AiBotUtilities.IsTableEmpty(tMAAToAdvance) then
                            break
                        end
                    end
                end

                if AiBotUtilities.IsTableEmpty(tMAAToAdvance) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': Still ahve MAA left over, will consider ot her zones to advance to') end
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                        for iEntry, tPathDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                            local tAltLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam]
                            if not(tAltLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure, tAltLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false and tAltLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < tAltLZTeamData[AiBotMap.subrefLZTValue] * 0.1 then
                                if bIgnorePlayableAreaCheck or AiBotConditions.IsLocationInPlayableArea(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefMidpoint]) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': sending MAA to support other LZ='..tPathDetails[AiBotMap.subrefLZNumber]..'; Size of MAA to advance before sending='..table.getn(tMAAToAdvance)) end
                                    SendMAAToSupportLandZone(tMAAToAdvance, iPlateau, iTeam, tPathDetails[AiBotMap.subrefLZNumber])
                                    if AiBotUtilities.IsTableEmpty(tMAAToAdvance) then break end
                                end
                            end
                        end
                    end
                end
            end



            --Do we have any MAA remaining after sending MAA to any LZ wanting support?
            if AiBotUtilities.IsTableEmpty(tMAAToAdvance) == false then
                --Is there an adjacent water zone that wants MAA support?
                if bDebugMessages == true then LOG(sFunctionRef..': Checking if have adjacent water zones, in which case will see if any of them want MAA; is table of adj water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]))) end
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                    local tHoverMAA = EntityCategoryFilterDown(categories.HOVER, tMAAToAdvance)
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of hover MAA empty='..tostring(AiBotUtilities.IsTableEmpty(tHoverMAA))) end
                    if AiBotUtilities.IsTableEmpty(tHoverMAA) == false then
                        local iPond, iAdjWZ
                        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                            iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                            iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
                            local tAltWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjWZ='..iAdjWZ..'; iPond='..iPond..'; MAA threat wanted='..tAltWZTeamData[AiBotMap.subrefWZMAAThreatWanted]) end
                            if tAltWZTeamData[AiBotMap.subrefWZMAAThreatWanted] > math.max(50, tAltWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]) then
                                --Only consider if either no enemy threat, or we have an allied combat threat
                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy combat total='..tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; Ally combat total='..tAltWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal]) end
                                if tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < 10 or tAltWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] > 10 then
                                    if bIgnorePlayableAreaCheck or AiBotConditions.IsLocationInPlayableArea(AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefMidpoint]) then
                                        SendMAAToSupportLandZone(tMAAToAdvance, iPlateau, iTeam, iAdjWZ, nil, true, tHoverMAA)
                                        if AiBotUtilities.IsTableEmpty(tHoverMAA) then break end
                                    end
                                end
                            end
                        end


                        --Do we still have hover MAA available and have high priority water zoens wanting MAA?
                        if AiBotUtilities.IsTableEmpty(tHoverMAA) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': Checking list of centrally flagged WZ to see if they want MAA, is table empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiWaterZonesWantingSignificantMAAByPlateau][iPlateau]))..'; repru of AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiWaterZonesWantingSignificantMAAByPlateau][iPlateau]='..repru(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiWaterZonesWantingSignificantMAAByPlateau][iPlateau])) end
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiWaterZonesWantingSignificantMAAByPlateau][iPlateau]) == false then
                                local iDistThreshold = math.max(250, AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase])) * 0.8
                                local iThresholdAdjust
                                for iAdjWZ, bWantsSupport in AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiWaterZonesWantingSignificantMAAByPlateau][iPlateau] do
                                    --If waterzone isn't too far from us then support it (based on simple straight line)
                                    iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
                                    local tAltWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ]
                                    iThresholdAdjust = 0
                                    if tAltWZData[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.subrefWZMAAThreatWanted] >= 2000 and tAltWZData[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.subrefLZTThreatAllyCombatTotal] >= 12000 then iThresholdAdjust = 100 end
                                    if bDebugMessages == true then
                                        --[[if not(iAdjWZ) then LOG('iAdjWZ is nil') end
                                        if not(iDistThreshold) then LOG('iDistThreshold is nil') end
                                        LOG('tLZData[AiBotMap.subrefMidpoint]='..repru(tLZData[AiBotMap.subrefMidpoint]))
                                        LOG('tAltWZData[AiBotMap.subrefMidpoint]='..repru(tAltWZData[AiBotMap.subrefMidpoint])..'; iAdjWZ='..iAdjWZ..'; iPond='..(iPond or 'nil'))--]]
                                        LOG(sFunctionRef..': Considering WZ further away flagged as wanting MAA, iAdjWZ='..iAdjWZ..'; iDistThreshold='..iDistThreshold..'; Dist to WZ='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tAltWZData[AiBotMap.subrefMidpoint])..'; iThresholdAdjust='..iThresholdAdjust)
                                    end
                                    if AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tAltWZData[AiBotMap.subrefMidpoint]) <= iDistThreshold + iThresholdAdjust then
                                        if bIgnorePlayableAreaCheck or AiBotConditions.IsLocationInPlayableArea(tAltWZData[AiBotMap.subrefMidpoint]) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will try and send MAA to this water zone') end
                                            SendMAAToSupportLandZone(tMAAToAdvance, iPlateau, iTeam, iAdjWZ, nil, true, tHoverMAA)
                                            if AiBotUtilities.IsTableEmpty(tHoverMAA) then break end
                                        end
                                    end
                                end
                            end
                            --Consider sending MAA to all zones (i.e. land and water, and other islands)
                            AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData)
                            if AiBotUtilities.IsTableEmpty(tHoverMAA) == false and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                                local iZoneMAAWanted
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering sending MAA to further away islands') end
                                for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                    local tAltLZOrWZData, tAltLZOrWZTeamData
                                    if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                        tAltLZOrWZData = AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                        tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                        iZoneMAAWanted = tAltLZOrWZTeamData[AiBotMap.subrefWZMAAThreatWanted]
                                    else
                                        if tSubtable[AiBotMap.subrefiPlateauOrPond] == iPlateau then
                                            tAltLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                            tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                            iZoneMAAWanted = tAltLZOrWZTeamData[AiBotMap.subrefLZMAAThreatWanted]
                                        else
                                            iZoneMAAWanted = 0
                                        end
                                    end
                                    if iZoneMAAWanted >= 5 then
                                        if bIgnorePlayableAreaCheck or AiBotConditions.IsLocationInPlayableArea(tAltLZOrWZData[AiBotMap.subrefMidpoint]) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': About to send MAA to support LZ or WZ ref='..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..'; Is water zone='..tostring(tSubtable[AiBotMap.subrefbIsWaterZone])..'; iZoneMAAWanted='..iZoneMAAWanted..'; iPlateau='..iPlateau..'; Is table of tHoverMAA empty='..tostring(AiBotUtilities.IsTableEmpty(tHoverMAA))) end
                                            SendMAAToSupportLandZone(tMAAToAdvance, iPlateau, iTeam, tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], 1.5, tSubtable[AiBotMap.subrefbIsWaterZone], tHoverMAA)
                                            if AiBotUtilities.IsTableEmpty(tHoverMAA) then break end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end


                --If sitll have MAA available, then send to existing land zones with a greater factor
                if AiBotUtilities.IsTableEmpty(tMAAToAdvance) == false then
                    local iMAALZToSupport
                    local iHighestAirValue = 0
                    local iHighestAirLZ
                    local iCurAirValue
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                        for iEntry, tPathDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering which adjacent LZ has the biggest air threat for leftover MAA, cur entry=LZ'..tPathDetails[AiBotMap.subrefLZNumber]..'; MAA threat wanted='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZMAAThreatWanted]..'; GroundAA have already='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; Enemy air to ground threat='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiEnemyAirToGroundThreat]..'; Air othre threat='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiEnemyAirOtherThreat]..'; Is table of enemy air empty for this alt LZ='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.reftLZEnemyAirUnits]))..' iHighestAirValue so far='..iHighestAirValue) end
                            if AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZMAAThreatWanted] > AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZOrWZThreatAllyGroundAA] then
                                local tAltLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam]
                                iCurAirValue = tAltLZTeamData[AiBotMap.subrefLZMAAThreatWanted] * 0.01 + tAltLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] + (tAltLZTeamData[AiBotMap.refiEnemyAirOtherThreat] + tAltLZTeamData[AiBotMap.refiEnemyAirAAThreat]) * 0.1
                                if iCurAirValue > iHighestAirValue then
                                    iHighestAirValue = iCurAirValue
                                    iHighestAirLZ = tPathDetails[AiBotMap.subrefLZNumber]
                                end
                            end
                        end
                    end
                    iMAALZToSupport = iHighestAirLZ


                    if bDebugMessages == true then LOG(sFunctionRef..': Do any adjacent zones want support? iMAALZToSupport='..(iMAALZToSupport or 'nil')) end
                    if iMAALZToSupport then
                        local tTargetPosition = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iMAALZToSupport][AiBotMap.subrefMidpoint]
                        for iUnit, oUnit in tMAAToAdvance do
                            AiBotOrders.IssueTrackedMove(oUnit, tTargetPosition, 10, false, 'MVBLZ'..iMAALZToSupport)
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tMAAToAdvance) == false then --Go back through each LZ assigning 3 times what it would normally want in MAA
                        local iFactorAdjust
                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                            if iMinCombatIfSignifDanger == 0 then iMinCombatIfSignifDanger = 10 end
                            for iEntry, tPathDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                                local tAltLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][iTeam]
                                if (not(tAltLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) or tAltLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] > iMinCombatIfSignifDanger or tAltLZTeamData[AiBotMap.subrefLZSValue] > 10) then
                                    if bIgnorePlayableAreaCheck or AiBotConditions.IsLocationInPlayableArea(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathDetails[AiBotMap.subrefLZNumber]][AiBotMap.subrefMidpoint]) then
                                        iFactorAdjust = 2
                                        if tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 then iFactorAdjust = 3 end
                                        SendMAAToSupportLandZone(tMAAToAdvance, iPlateau, iTeam, tPathDetails[AiBotMap.subrefLZNumber], iFactorAdjust)
                                    end
                                end
                            end
                        end
                    end
                end
            end

            if AiBotUtilities.IsTableEmpty(tMAAToAdvance) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Still have spare MAA, tLZData[AiBotMap.subrefLZIslandRef]='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; iPlateau='..(iPlateau or 'nil')) end
                --Only flag that we have no MAA targets for a core base if we have 10+ MAA, including T2+ MAA, with no target
                local bEnoughMAAInZone = false
                if tLZTeamData[AiBotMap.subrefLZbCoreBase] then
                    local tT2PlusMAAToAdvance = EntityCategoryFilterDown(categories.TECH2 + categories.TECH3, tMAAToAdvance)
                    if table.getn(tT2PlusMAAToAdvance) >= 8 then
                        bEnoughMAAInZone = true
                    end
                elseif tLZTeamData[AiBotMap.subrefLZCoreExpansion] then
                    if table.getn(tMAAToAdvance) >= 2 then
                        bEnoughMAAInZone = true
                    end
                else
                    bEnoughMAAInZone = true
                end
                if bEnoughMAAInZone then
                    if not(tLZData[AiBotMap.subrefLZIslandRef]) then tLZData[AiBotMap.subrefLZIslandRef] = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tLZData[AiBotMap.subrefMidpoint]) end
                    if tLZData[AiBotMap.subrefLZIslandRef] then
                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastTimeNoMAATargetsByIsland]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastTimeNoMAATargetsByIsland] = {} end
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastTimeNoMAATargetsByIsland][tLZData[AiBotMap.subrefLZIslandRef]] = GetGameTimeSeconds()
                    end
                end
                --Go to rally point instead
                for iUnit, oUnit in tMAAToAdvance do
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                        AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 10, false, 'ABRtr'..iLandZone)
                    else
                        AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 10, false, 'BRtr'..iLandZone)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageRASSACUsInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tSACUs)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageRASSACUsInLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Manages SACUs to be assigned engineer type duties (wont always be RAS SACUs - e.g. might be LOUD where we want SACUs to build experimentals
    --Gameender duty - have RAS SACUs assist with building a gameender/t3 arti/novax in the zone and associated shielding, if we have an active template
    local bProceed = true
    if bDebugMessages == true then LOG(sFunctionRef..': Start of RAS code, iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Time='..GetGameTimeSeconds()..'; Time since last wanted SACU for exp='..(GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] or 0))) end
    function BuildCategoryWithSACUs(iCategoryWanted, iOptionalFactionWanted, toSACUByFaction, iOptionalEngineerActionForTracking)
        --toSACUByFaction - only needed if iOptionalFactionWanted is specified
        --iOptionalEngineerActionForTracking - if specified, then will call trackengineer function
        local oPrimaryEngineer
        if iOptionalFactionWanted then
            oPrimaryEngineer = toSACUByFaction[iOptionalFactionWanted][1]
        else
            oPrimaryEngineer = tSACUs[1]
        end

        if oPrimaryEngineer then
            local aiBrain = oPrimaryEngineer:GetAIBrain()
            local sBlueprint, tBuildLocation = AiBotEngineer.GetBlueprintAndLocationToBuild(aiBrain, oPrimaryEngineer, iOptionalEngineerActionForTracking or AiBotEngineer.refActionBuildExperimental, iCategoryWanted, 100, nil, nil,                                false,                          nil,                nil,                                false, tLZData, tLZTeamData)

            --Update SACU table to remove any of the desired faction who can be given other orders
            if bDebugMessages == true then LOG(sFunctionRef..': sBlueprint='..(sBlueprint or 'nil')..'; tBuildLocation='..repru(tBuildLocation or {})..'; oPrimaryEngineer='..(oPrimaryEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oPrimaryEngineer) or 'nil')) end
            if sBlueprint and tBuildLocation then
                local toBuilders
                if iOptionalFactionWanted then
                    for iCurEntry = table.getn(tSACUs), 1, -1 do
                        if AiBotUnitInfo.GetUnitFaction(tSACUs[iCurEntry]) == iOptionalFactionWanted then
                            table.remove(tSACUs, iCurEntry)
                        end
                    end
                    toBuilders = toSACUByFaction[iOptionalFactionWanted]
                else
                    toBuilders = tSACUs
                end

                --Build with all the SACUs wanted
                if AiBotUtilities.IsTableEmpty(toBuilders) == false then
                    bProceed = false
                    if iOptionalFactionWanted and AiBotUtilities.IsTableEmpty(tSACUs) == false then bProceed = true end
                    for iSACU, oSACU in toBuilders do
                        local tMoveLocation = AiBotEngineer.GetLocationToMoveForConstruction(oSACU, tBuildLocation, sBlueprint, 0, false)
                        if tMoveLocation then
                            if bDebugMessages == true then LOG(sFunctionRef..': Telling oSACU '..oSACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSACU)..' to move to '..repru(tMoveLocation)..' and then build '..sBlueprint..' at location '..repru(tBuildLocation)) end
                            AiBotOrders.IssueTrackedMoveAndBuild(oSACU, tBuildLocation, sBlueprint, tMoveLocation, 1, false, 'SACUExpMBld')
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Telling engineer '..oSACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSACU)..' to build '..sBlueprint..' at build location '..repru(tBuildLocation)) end
                            AiBotOrders.IssueTrackedBuild(oSACU, tBuildLocation, sBlueprint, false, 'SACUExpBld')
                        end
                        if iOptionalEngineerActionForTracking and not(oSACU[AiBotEngineer.refiAssignedAction] == iOptionalEngineerActionForTracking) then AiBotEngineer.TrackEngineerAction(oSACU, iOptionalEngineerActionForTracking, iSACU == 1, 1, nil, nil, false) end
                        --AiBotEngineer.TrackEngineerAction(oSACU, AiBotEngineer.refActionBuildExperimental, true, 1, nil, nil, false)
                    end
                end
            end
        end
    end

    if tLZTeamData[AiBotMap.subrefbGEShieldSACU] then
        --Check if we need more shield SACUs
        local iShieldSACUsWantedPerTemplate = AiBotConditions.GetShieldSACUsWantedForGETemplate(iTeam)
        local iAdditionalShieldSACUsWanted = 0
        for iTemplate, tSubtable in tLZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
            if AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subreftoGEShieldSACUs]) then
                iAdditionalShieldSACUsWanted = iAdditionalShieldSACUsWanted + iShieldSACUsWantedPerTemplate
            else
                iAdditionalShieldSACUsWanted = iAdditionalShieldSACUsWanted + math.max(0, table.getn(tSubtable[AiBotMap.subreftoGEShieldSACUs]) - iShieldSACUsWantedPerTemplate)
            end
        end
        for iSACU = table.getn(tSACUs), 1, -1 do
            if EntityCategoryContains(categories.UEF, tSACUs[iSACU].UnitId) then
                AiBotEngineer.AssignEngineerToGameEnderTemplate(tSACUs[iSACU], tLZData, tLZTeamData, iPlateau, iLandZone)
                table.remove(tSACUs, iSACU)
                iAdditionalShieldSACUsWanted = iAdditionalShieldSACUsWanted - 1
                if iAdditionalShieldSACUsWanted <= 0 then break end
            end
        end
    end

    --If have any SACUs without RAS upgrade that could get it, then get RAS upgrade, provided no enemies in the zone (LOUD - only doe this if close to unit cap or defending against t3 arti since that will stop us building mass fabs, due to how bad ras is)
    if AiBotUtilities.IsTableEmpty(tSACUs) == false then
        if bDebugMessages == true then LOG(sFunctionRef..': Considering getting RAS if no enemies in LZ and not LOUD, tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])..'; Enemy air to ground='..(tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)..'; Unit cap level='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 'nil')..'; Defending against arti='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti])..'; Team mass%='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Team is stalling E='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) end
        if not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 and (not(AiBotUtilities.bLoudModActive) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.9 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 30 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]))) then
            local tSACUsToUpgrade = {}
            local tSACUsUpgrading = {}
            local bWantBuildPower = false
            if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.6 or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= -2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.2)) and (GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] or 0)) <= 5 or not(AiBotConditions.HaveLowPower(iTeam)) then
                bWantBuildPower = true
            end
            local sUpgradeWanted
            for iSACU = table.getn(tSACUs), 1, -1 do
                local oSACU = tSACUs[iSACU]
                if bDebugMessages == true then LOG(sFunctionRef..'; Considering iSACU='..iSACU..' in the table, oSACU='..oSACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSACU)..'; Unit state='..AiBotUnitInfo.GetUnitState(oSACU)..'; Special micro active='..tostring(oSACU[AiBotUnitInfo.refbSpecialMicroActive])..'; oSACU[AiBotACU.reftPreferredUpgrades]='..repru(oSACU[AiBotACU.reftPreferredUpgrades])..'; bWantBuildPower='..tostring(bWantBuildPower or false)) end
                if oSACU:IsUnitState('Upgrading') then
                    table.insert(tSACUsUpgrading, oSACU)
                    table.remove(tSACUs, iSACU)
                elseif oSACU[AiBotUnitInfo.refbSpecialMicroActive] and oSACU:IsUnitState('Moving') then
                    --Do nothing - e.g. SACU might be rolling off of factory, or dodging a shot
                else
                    if oSACU[AiBotACU.reftPreferredUpgrades] == nil or (bWantBuildPower and not(oSACU[AiBotACU.refbTriedAndFailedToGetBuildRateUpgrade])) then
                        sUpgradeWanted = AiBotACU.GetUpgradeForSACU(oSACU, bWantBuildPower, bWantBuildPower)
                        if bDebugMessages == true then LOG(sFunctionRef..': sUpgradeWanted='..(sUpgradeWanted or 'nil')) end
                        if sUpgradeWanted then
                            --Get upgrade wanted
                            table.insert(tSACUsToUpgrade, oSACU)
                            table.remove(tSACUs, iSACU)
                            if bWantBuildPower and (oSACU[AiBotACU.refiUpgradeCount] or 0) == 0  then bWantBuildPower = false end --i.e. better to just get bild power on 1 and assist with others, than try to get on all at the same time
                            if bDebugMessages == true then LOG(sFunctionRef..': Have added SACU to table of SACUs to upgrade, sUpgradeWanted='..sUpgradeWanted) end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of SACUs upgrading empty='..tostring(AiBotUtilities.IsTableEmpty(tSACUsUpgrading))) end
            if AiBotUtilities.IsTableEmpty(tSACUsUpgrading) == false then
                local bLeaveOneSACU = false
                local iMaxDistanceToAssist
                if ((tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] or tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD]) and GetGameTimeSeconds() - math.max((tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] or 0), tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD] or 0) <= 3) then
                    bLeaveOneSACU = true
                elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] then
                    bLeaveOneSACU = true
                    iMaxDistanceToAssist = 20
                end

                --First add any SACUsToUpgrade back to main table
                if AiBotUtilities.IsTableEmpty(tSACUsToUpgrade) == false then
                    for iSACU, oSACU in tSACUsToUpgrade do
                        table.insert(tSACUs, oSACU)
                    end
                end
                --Assist with all SACUs (or all but one)
                local oSACUToAssist = tSACUsUpgrading[1]
                bProceed = bLeaveOneSACU
                for iSACU = table.getn(tSACUs), 1, -1 do
                    local oSACU = tSACUs[iSACU]
                    if bLeaveOneSACU then
                        bLeaveOneSACU = false
                    else
                        if not(iMaxDistanceToAssist) or AiBotUtilities.GetDistanceBetweenPositions(oSACU:GetPosition(), oSACUToAssist:GetPosition()) <= iMaxDistanceToAssist then
                            if bDebugMessages == true then LOG(sFunctionRef..': Telling oSACU='..oSACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSACU)..' to assist oSACUToAssist='..oSACUToAssist.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSACUToAssist)) end
                            AiBotOrders.IssueTrackedGuard(oSACU, oSACUToAssist, false, 'SACUUpgrAs', false)
                            table.remove(tSACUs, iSACU)
                        elseif bDebugMessages == true then LOG(sFunctionRef..': iMaxDistanceToAssist='..iMaxDistanceToAssist..'; are too far from oSACU='..oSACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSACU)..'; Dist between SACUs='..AiBotUtilities.GetDistanceBetweenPositions(oSACU:GetPosition(), oSACUToAssist:GetPosition()))
                        end
                    end
                end
            elseif AiBotUtilities.IsTableEmpty(tSACUsToUpgrade) == false then
                for iSACU, oSACU in tSACUsToUpgrade do
                    if bDebugMessages == true then LOG(sFunctionRef..': Will ugprade oSACU='..oSACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSACU)..' with upgrade '..(oSACU[AiBotACU.reftPreferredUpgrades][1] or 'nil')..' unless special micro active, special micro='..tostring(oSACU[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                    if not(oSACU[AiBotUnitInfo.refbSpecialMicroActive]) then
                        AiBotOrders.IssueTrackedEnhancement(oSACU, oSACU[AiBotACU.reftPreferredUpgrades][1], false, 'SACURasUpgr')
                        break
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tSACUs) then bProceed = false end
        end
        --AiBotOrders.IssueTrackedEnhancement(oACU, sUpgradeToGet, false, 'ACUUpg')
        local bWantExperimentalAnyway = false
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 and not(AiBotConditions.HaveLowPower(iTeam)) then
            bWantExperimentalAnyway = true
        end
        if bDebugMessages == true then LOG(sFunctionRef..': About to consider if we want to get SMD or experimental due to restrictions on what can be built by engineers, bProceed='..tostring(bProceed)..'; Time since last wanted SACU for exp or engi='..(GetGameTimeSeconds() - math.max((tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] or 0), tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD] or 0))..'; bWantExperimentalAnyway='..tostring(bWantExperimentalAnyway)) end
        if bProceed and (bWantExperimentalAnyway or  ((tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] or tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD]) and GetGameTimeSeconds() - math.max((tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] or 0), tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD] or 0) <= math.max(5, (iTicksPerLandCycle-1)*0.1))) then
            local bBuildingSMD = false
            if tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD] <= math.max(5, (iTicksPerLandCycle-1)*0.1) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]) == false) then
                local iSMDBPWanted, bAssistSMD, oSMDToShield, oShieldToAssist = AiBotEngineer.GetBPToAssignToSMD(iPlateau, iLandZone, iTeam, tLZTeamData, tLZTeamData[AiBotMap.subrefLZbCoreBase], AiBotConditions.TeamHasLowMass(iTeam), AiBotConditions.HaveLowPower(iTeam))
                if bDebugMessages == true then LOG(sFunctionRef..': Deciding if want to use RAS SACUs to build SMD, iSMDBPWanted='..iSMDBPWanted..'; bAssistSMD='..tostring(bAssistSMD)..'; oSMDToShield='..(oSMDToShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oSMDToShield) or 'nil')..'; oShieldToAssist='..(oShieldToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oShieldToAssist) or 'nil')) end
                if iSMDBPWanted > 0 and AiBotConditions.GetNumberOfUnitsMeetingCategoryUnderConstructionInLandOrWaterZone(tLZTeamData, AiBotUnitInfo.refCategorySMD, true) == 0 and not(bAssistSMD) and not(oSMDToShield) and not(oShieldToAssist) then
                    bBuildingSMD = true
                    BuildCategoryWithSACUs(AiBotUnitInfo.refCategorySMD, nil, nil, AiBotEngineer.refActionBuildSMD)
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bBuildingSMD='..tostring(bBuildingSMD)..'; Time since last wanted SMD='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD] or 0)) end
            if not(bBuildingSMD) and (bWantExperimentalAnyway or tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] <= math.max(5, (iTicksPerLandCycle-1)*0.1)) then
                --First check we have no experimental level units under construction in this zone
                if bDebugMessages == true then LOG(sFunctionRef..': Number of exp under construction in LZ='..AiBotConditions.GetNumberOfUnitsMeetingCategoryUnderConstructionInLandOrWaterZone(tLZTeamData, AiBotUnitInfo.refCategoryExperimentalLevel, true)) end
                if AiBotConditions.GetNumberOfUnitsMeetingCategoryUnderConstructionInLandOrWaterZone(tLZTeamData, AiBotUnitInfo.refCategoryExperimentalLevel, true) == 0 then
                    local tbEngineersOfFactionOrNilIfAlreadyAssigned = {}
                    local aiBrain
                    local toSACUByFaction = {}
                    local iCurFaction
                    for iSACU, oSACU in tSACUs do
                        iCurFaction = AiBotUnitInfo.GetUnitFaction(oSACU)
                        tbEngineersOfFactionOrNilIfAlreadyAssigned[iCurFaction] = true
                        if not(aiBrain) then aiBrain = oSACU:GetAIBrain() end
                        if not(toSACUByFaction[iCurFaction]) then toSACUByFaction[iCurFaction] = {} end
                        table.insert(toSACUByFaction[iCurFaction], oSACU)
                    end
                    local iCategoryWanted, iFactionWanted = AiBotEngineer.DecideOnExperimentalToBuild(AiBotEngineer.refActionBuildExperimental, aiBrain, tbEngineersOfFactionOrNilIfAlreadyAssigned, tLZData, tLZTeamData, iPlateau, iLandZone)
                    if bDebugMessages == true then LOG(sFunctionRef..': is iCategoryWanted nil='..tostring(iCategoryWanted == nil)..'; is iFactionWanted nil='..tostring(iFactionWanted == nil)) end
                    if iCategoryWanted then
                        if iCategoryWanted == AiBotEngineer.refActionManageGameEnderTemplate then
                            --Need to assign unit to GETemplate
                            bProceed = false
                            for iSACU, oSACU in tSACUs do
                                AiBotEngineer.AssignEngineerToGameEnderTemplate(oSACU, tLZData, tLZTeamData, iPlateau, iLandZone)
                            end
                        else
                            BuildCategoryWithSACUs(iCategoryWanted, iFactionWanted, toSACUByFaction, AiBotEngineer.refActionBuildExperimental)
                        end
                    end
                end
            end
        end
        --Consider sending 1 SACU to water zone if havent already sent one and this is a core base and we have multiple SACUs
        if bProceed and AiBotUtilities.IsTableEmpty(tSACUs) == false then
            local iCurSACUsAssignedToWaterZones = 0
            local iCurSACUsInLandZone = table.getn(tSACUs)
            local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
            local iLandToWaterRatio = 10
            if aiBrain[AiBotOverseer.refbPrioritiseNavy] then iLandToWaterRatio = 0.5
            elseif not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) then iLandToWaterRatio = 2
            end
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoSACUsTravelingToWaterZoneFromHere]) == false then iCurSACUsAssignedToWaterZones = table.getn(tLZTeamData[AiBotMap.subreftoSACUsTravelingToWaterZoneFromHere]) end
            if iCurSACUsInLandZone > iCurSACUsAssignedToWaterZones * iLandToWaterRatio then
                if aiBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] >= 3 then
                    --Send SACUs if we are priorising navy, or if we need SACUs to build experimentals (i.e. QUIET or LOUD)
                    if aiBrain[AiBotOverseer.refbPrioritiseNavy] or ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) and (not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= math.max(3, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false))) then
                        --Do we have more than 1 SACU here?
                        if tLZTeamData[AiBotMap.subrefLZbCoreBase] and iCurSACUsInLandZone > 1 then
                            --Are weither a naval AI, or this is our 3rd+ SACU?
                            local bNavalOr3rdSACU = (aiBrain[AiBotOverseer.refbPrioritiseNavy] or iCurSACUsInLandZone >= 3)
                            if not(bNavalOr3rdSACU) then
                                for iSACU, oSACU in tSACUs do
                                    if AiBotUnitInfo.GetUnitLifetimeCount(oSACU) >= 3 then
                                        bNavalOr3rdSACU = true
                                        break
                                    end
                                end
                            end
                            if bNavalOr3rdSACU then
                                --Can we find a nearby high value water zone?
                                AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData)
                                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                                    local iMaxSearchRange = 150
                                    local iCurWaterZone
                                    if not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) or aiBrain[AiBotOverseer.refbPrioritiseNavy] then iMaxSearchRange = 300 end
                                    local bAssignedSACU = false
                                    for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                        if tSubtable[AiBotMap.subrefiDistance] > iMaxSearchRange then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Are outside the max range so wil stop searching') end
                                            break
                                        elseif tSubtable[AiBotMap.subrefbIsWaterZone] then
                                            iCurWaterZone = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]
                                            --Is this a high value pond, or a WZ that has recently tried getting exp
                                            local tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurWaterZone]][AiBotMap.subrefPondWaterZones][iCurWaterZone]
                                            local tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                            if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iCurWaterZone]] or 0) >= 14 or (tAltLZOrWZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] and GetGameTimeSeconds() - tAltLZOrWZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] <= 11) then
                                                if AiBotUtilities.IsTableEmpty(tAltLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                                    --Have a high value water zone with friendly units in it, if we have a navla factory here that has built something, then send an SACU
                                                    for iUnit, oUnit in tAltLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] do
                                                        if (oUnit[AiBotFactory.refiTotalBuildCount] or 0) >= 1 then
                                                            --Send 1 SACU here
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Will send SACU '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to go to WZ='..iCurWaterZone) end
                                                            tSACUs[1][AiBotUnitInfo.refiSACUWaterZoneTarget] = iCurWaterZone
                                                            table.remove(tSACUs, 1)
                                                            if AiBotUtilities.IsTableEmpty(tSACUs) then bProceed = false end
                                                            bAssignedSACU = true
                                                            break
                                                        end
                                                    end
                                                    if bAssignedSACU then break end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            elseif iCurSACUsAssignedToWaterZones > 0then
                for iCurEntry = table.getn(tLZTeamData[AiBotMap.subreftoSACUsTravelingToWaterZoneFromHere]), 1, -1 do
                    local oTravelingSACU = tLZTeamData[AiBotMap.subreftoSACUsTravelingToWaterZoneFromHere][iCurEntry]
                    if not(oTravelingSACU[AiBotUnitInfo.refiSACUWaterZoneTarget]) then
                        table.remove(tLZTeamData[AiBotMap.subreftoSACUsTravelingToWaterZoneFromHere], iCurEntry)
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we should proceed with considering assigning SACUs to GE template, bProceed='..tostring(bProceed)..'; Is table of active GE templates for this zone empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates]))) end
        if bProceed and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates]) == false then
            for iTemplate, tSubtable in tLZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
                if not(tSubtable[AiBotMap.subrefGEbDontNeedEngineers]) then
                    for iSACU, oSACU in tSACUs do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering SACU assignment to GE template, oSACU='..oSACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSACU)..'; oSACU[AiBotBuilding.reftArtiTemplateRefs]='..repru(oSACU[AiBotBuilding.reftArtiTemplateRefs])..'; oSACU[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oSACU[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                        if AiBotUtilities.IsTableEmpty(oSACU[AiBotBuilding.reftArtiTemplateRefs]) then
                            if not(oSACU[AiBotUnitInfo.refbSpecialMicroActive]) then
                                AiBotEngineer.AssignEngineerToGameEnderTemplate(oSACU, tLZData, tLZTeamData, iPlateau, iLandZone)
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': RAS SACUs are assigned to gameender duty for iTemplate ref='..iTemplate) end
                    bProceed = false
                    break
                end
            end
        end
    else
        bProceed = false
        --All SACUs are assigned to GE template/we have none
    end
    if bDebugMessages == true then LOG(sFunctionRef..': FInished going through if want to help active GE template, bProceed='..tostring(bProceed)) end
    if bProceed then
        --Defending against arti - if have a gameender then first consider if have part-complete shield that want to construct
        local oShieldToAssist
        local oPartCompleteGameEnderToAssist
        if bDebugMessages == true then LOG(sFunctionRef..': Is reftoUnitsForSpecialShieldProtection empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection]))..'; refbDefendAgainstArti='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or false)) end
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] then
            local tGameEndersForShielding = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGameEnder, tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection])
            if bDebugMessages == true then LOG(sFunctionRef..': Is tGameEndersForShielding empty='..tostring(AiBotUtilities.IsTableEmpty(tGameEndersForShielding))) end
            if AiBotUtilities.IsTableEmpty(tGameEndersForShielding) == false then
                local oGameEnderToCover
                local iHighestCompletionGameEnder = 0.3
                for iGameEnder, oGameEnder in tGameEndersForShielding do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering oGameEnder='..oGameEnder.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oGameEnder)..'; is reftoSpecialAssignedShields empty='..tostring(AiBotUtilities.IsTableEmpty(oGameEnder[AiBotBuilding.reftoSpecialAssignedShields]))) end
                    if not(oGameEnderToCover) and AiBotUtilities.IsTableEmpty(oGameEnder[AiBotBuilding.reftoSpecialAssignedShields]) == false then
                        oGameEnderToCover = oGameEnder
                    end
                    if not(oGameEnder.Dead) and oGameEnder:GetFractionComplete() < 1 and oGameEnder:GetFractionComplete() > iHighestCompletionGameEnder then
                        iHighestCompletionGameEnder = oGameEnder:GetFractionComplete()
                        oPartCompleteGameEnderToAssist = oGameEnder
                    end
                end

                if oGameEnderToCover then
                    --How much shielding do we have
                    local iNearestCompleteShield = 0
                    local oNearestCompleteShield
                    local iActiveShields = 0
                    local iCurShield, iMaxShield
                    for iShield, oShield in oGameEnderToCover[AiBotBuilding.reftoSpecialAssignedShields] do
                        if oShield:GetFractionComplete() < 1 and oShield:GetFractionComplete() > iNearestCompleteShield then
                            iNearestCompleteShield = oShield:GetFractionComplete()
                            oNearestCompleteShield = oShield
                        else
                            iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, true)
                            if iCurShield > 0 then iActiveShields = iActiveShields + 1 end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iActiveShields='..iActiveShields..'; iNearestCompleteShield='..iNearestCompleteShield) end
                    if iActiveShields > 1 or (iActiveShields == 1 and iNearestCompleteShield >= 0.75) then
                        --Do nothing
                    else
                        oShieldToAssist = oNearestCompleteShield
                    end
                end
            end

        end

        --Defending against arti - if have T3 arti or gameender then want to assist the shield with RAS SACUs (in addition to any engineers that are assisting it)
        local oPriorityUnitToRepairInsteadOfAssistingShield
        if not(oShieldToAssist) then
            local tPriorityUnitsToShield
            if bDebugMessages == true then LOG(sFunctionRef..': Dealing with zone '..iLandZone..'; at time '..GetGameTimeSeconds()..'; DefendAgainstArti='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti])) end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] >= 2) then
                local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                if aiBrain.GetUnitsAroundPoint then
                    tPriorityUnitsToShield = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryGameEnder, tLZData[AiBotMap.subrefMidpoint], 250, 'Ally')
                    if bDebugMessages == true then LOG(sFunctionRef..': Is tPriorityUnitsToShield empty='..tostring(AiBotUtilities.IsTableEmpty(tPriorityUnitsToShield))) end
                    if AiBotUtilities.IsTableEmpty(tPriorityUnitsToShield) then
                        tPriorityUnitsToShield = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryFixedT3Arti, tLZData[AiBotMap.subrefMidpoint], 150, 'Ally')
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of priority units to shield empty='..tostring(AiBotUtilities.IsTableEmpty(tPriorityUnitsToShield))) end
            if AiBotUtilities.IsTableEmpty(tPriorityUnitsToShield) == false then
                --Get closest of these that has a shield that is damaged
                local iCurDist
                local iClosestDist = 100000
                local iCurShield, iMaxShield
                local bAssistEvenIfNotDamaged = true
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 then bAssistEvenIfNotDamaged = false end
                for iUnit, oUnit in tPriorityUnitsToShield do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering priority unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Fraction compelte='..oUnit:GetFractionComplete()..'; Does it have a shield providing coverage='..tostring(AiBotUnitInfo.IsUnitValid(oUnit[AiBotBuilding.refoPriorityShieldProvidingCoverage]))) end
                    if not(oUnit.Dead) and oUnit:GetFractionComplete() >= 0.35 then
                        if AiBotUnitInfo.IsUnitValid(oUnit[AiBotBuilding.refoPriorityShieldProvidingCoverage]) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oUnit[AiBotBuilding.refoPriorityShieldProvidingCoverage]:GetPosition())
                            if bDebugMessages == true then LOG(sFunctionRef..': Shield='..oUnit[AiBotBuilding.refoPriorityShieldProvidingCoverage].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[AiBotBuilding.refoPriorityShieldProvidingCoverage])..'; iCurDist='..iCurDist..'; iCloestDist='..iClosestDist) end
                            if iCurDist < iClosestDist then
                                --Is the shield still active?
                                iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit[AiBotBuilding.refoPriorityShieldProvidingCoverage], true)
                                if bDebugMessages == true then LOG(sFunctionRef..': iCurShield='..iCurShield) end
                                if (iCurShield > 0 and (bAssistEvenIfNotDamaged or iCurShield < iMaxShield or GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeLastDamaged] or - 100) <= 25)) or (oUnit[AiBotBuilding.refoPriorityShieldProvidingCoverage]:GetFractionComplete() < 1 and (not(oUnit[AiBotEngineer.refbDontIncludeAsPartCompleteBuildingForConstruction]) or oUnit[AiBotBuilding.refoPriorityShieldProvidingCoverage]:GetFractionComplete() <= 0.75)) then
                                    iClosestDist = iCurDist
                                    oShieldToAssist = oUnit[AiBotBuilding.refoPriorityShieldProvidingCoverage]
                                    if iCurShield == iMaxShield and oUnit:GetFractionComplete() < 1 and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeLastDamaged] or - 100) >= 20 then
                                        oPriorityUnitToRepairInsteadOfAssistingShield = oUnit
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': oShieldToAssist='..(oShieldToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oShieldToAssist) or 'nil')) end
        if oPriorityUnitToRepairInsteadOfAssistingShield then
            for iUnit, oUnit in tSACUs do
                AiBotOrders.IssueTrackedRepair(oUnit, oPriorityUnitToRepairInsteadOfAssistingShield, false, 'RASRRep', false)
            end
        elseif oShieldToAssist then
            if bDebugMessages == true then LOG(sFunctionRef..': Have priority shield to assist') end
            if oShieldToAssist:GetFractionComplete() == 1 then
                for iUnit, oUnit in tSACUs do
                    AiBotOrders.IssueTrackedGuard(oUnit, oShieldToAssist, false, 'RASAGS', false)
                end
            else
                for iUnit, oUnit in tSACUs do
                    AiBotOrders.IssueTrackedRepair(oUnit, oShieldToAssist, false, 'RASRS', false)
                end
            end
        else
            local tUnitsToAssist = {}
            --If overflowing mass then search for under construction experimentals in the zone
            local bHaveLowPower = AiBotConditions.HaveLowPower(iTeam)
            if not(bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.65 then
                --If have under construction experimental in this zone then assist it
                local tExpInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryExperimentalLevel, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tExpInZone) == false then
                    for iExp, oExp in tExpInZone do
                        if oExp:GetFractionComplete() < 1 then
                            table.insert(tUnitsToAssist, oExp)
                        end
                    end
                end
            end
            if oPartCompleteGameEnderToAssist and not(bHaveLowPower) and AiBotUtilities.IsTableEmpty(tUnitsToAssist) then
                table.insert(tUnitsToAssist, oPartCompleteGameEnderToAssist)
            end

            --If we have a bunch of SACUs and have a game-ender to assist then focus on this instead of more SACUs
            local oGateway
            local bNotAssistingGateway = true
            local bHaveRASGateway = false
            if oPartCompleteGameEnderToAssist and AiBotUtilities.IsTableEmpty(tUnitsToAssist) == false and (oPartCompleteGameEnderToAssist:GetFractionComplete() >= 0.45 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 200 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 80 and table.getn(tSACUs) >= 4 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] * 2)) then
                --Dont consider assisting gateway
                if bDebugMessages == true then LOG(sFunctionRef..': Will prioririse assisting gameender instead of getting more SACUs') end
            else

                --If have mass stored then find the nearest quantum gatway and assist it for now, otherwise do nothing (if enemies in this LZ then will have been sent to the combat unit management already)
                --(dont do this in LOUD unless near unit cap since wont be getting RAS SACUs)
                if not(AiBotUtilities.bLoudModActive) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 1 then
                    local tQuantumGateways = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryQuantumGateway, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of quantum gateways empty='..tostring(AiBotUtilities.IsTableEmpty( tQuantumGateways))) end
                    if AiBotUtilities.IsTableEmpty( tQuantumGateways) == false then
                        for iUnit, oUnit in tQuantumGateways do
                            if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; refiTimeSinceLastFailedToGetOrder='..GetGameTimeSeconds() - (oUnit[AiBotFactory.refiTimeSinceLastFailedToGetOrder] or 0)..'; work progress='..oUnit:GetWorkProgress()) end
                            if oUnit:GetWorkProgress() > 0 or oUnit:GetFractionComplete() < 1 or not(oUnit[AiBotFactory.refiTimeSinceLastFailedToGetOrder]) or GetGameTimeSeconds() - oUnit[AiBotFactory.refiTimeSinceLastFailedToGetOrder] >= 20 then
                                oGateway = oUnit
                                if not(EntityCategoryContains(categories.SERAPHIM, oUnit.UnitId)) then
                                    bHaveRASGateway = true
                                    break
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oGateway='..(oGateway.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oGateway))..'; bHaveRASGateway='..tostring(bHaveRASGateway)) end
            if oGateway then
                if not(bHaveRASGateway) then
                    --Do we have a T3+ 'other' factory type on the team, for a non-sera faction?
                    local iLandSubteam = oGateway:GetAIBrain().AiBotLandSubteam
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of other faction types empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeOther]))..'; Reprs of this='..reprs(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeOther])) end
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeOther]) == false then
                        local bHaveNonSeraFactory = false
                        for iFaction, tSubtable in AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeOther] do
                            if not(iFaction == AiBotUnitInfo.refFactionSeraphim) and (tSubtable[3] or 0) > 0 then
                                bHaveNonSeraFactory = true
                                break
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished searching other factory types, bHaveNonSeraFactory='..tostring(bHaveNonSeraFactory or false)) end
                        if bHaveNonSeraFactory then
                            local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                            if aiBrain.GetUnitsAroundPoint then
                                local tNearbyFriendlyGateway = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryQuantumGateway - categories.SERAPHIM, tLZData[AiBotMap.subrefMidpoint], 250, 'Ally')
                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby non sera quantum gateways empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyFriendlyGateway))) end
                                if AiBotUtilities.IsTableEmpty(tNearbyFriendlyGateway) == false then
                                    for iUnit, oUnit in tNearbyFriendlyGateway do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering quantum gateway oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Terrain label='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition()) or 'nil')..'; iPlateau='..(iPlateau or 'nil')) end
                                        if oUnit:GetAIBrain().AiBotAI and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition()) == iPlateau then
                                            --Check factory is building something
                                            if oUnit:GetWorkProgress() > 0 or not(oUnit[AiBotFactory.refiTimeSinceLastFailedToGetOrder]) or GetGameTimeSeconds() - oUnit[AiBotFactory.refiTimeSinceLastFailedToGetOrder] >= 20 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Have a non sera gateway to assist instead, oGateway='..oGateway.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oGateway)) end
                                                oGateway = oUnit
                                                break
                                            elseif bDebugMessages == true then LOG(sFunctionRef..': Gateway appears idle so will keep searching')
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                if (AiBotMap.bIsCampaignMap or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.05) and not(AiBotConditions.HaveLowPower(iTeam)) and ((AiBotMap.bIsCampaignMap and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 80 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or (not(AiBotMap.bIsCampaignMap) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < math.min(100, 40 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]))) then
                    if (AiBotMap.bIsCampaignMap or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 100) and oGateway:GetAIBrain():GetCurrentUnits(AiBotUnitInfo.refCategoryRASSACU) < 50 then
                        bNotAssistingGateway = false
                        if bDebugMessages == true then LOG(sFunctionRef..': Will get every SACU to assist the gateway') end
                        table.insert(tUnitsToAssist, oGateway)
                        --[[for iUnit, oUnit in tSACUs do
                            AiBotOrders.IssueTrackedGuard(oUnit, oGateway, false, 'RASQG', false)
                        end--]]
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oGateway='..(oGateway.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oGateway) or 'nil')..'; bNotAssistingGateway='..tostring(bNotAssistingGateway)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Have low power='..tostring(AiBotConditions.HaveLowPower(iTeam))) end
            if bNotAssistingGateway then
                --If low power and have under construction pgen then assist this
                if bDebugMessages == true then LOG(sFunctionRef..': Does team have low mass='..tostring(AiBotConditions.TeamHasLowMass(iTeam))..'; Is table of engineers building experimentals empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals]))..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Time since close to unit cap='..(GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] or 0))) end
                if bHaveLowPower then
                    local tPowerInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPower * categories.TECH3, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tPowerInZone) == false then
                        for iPgen, oPgen in tPowerInZone do
                            if oPgen:GetFractionComplete() < 1 then
                                table.insert(tUnitsToAssist, oPgen)
                            end
                        end
                    end
                end
                --If building an experimental and dont have low mass then assist it
                if AiBotUtilities.IsTableEmpty(tUnitsToAssist) and (not(AiBotConditions.TeamHasLowMass(iTeam)) or (GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] or 0) <= 60)) and not(bHaveLowPower) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals]) == false then

                    local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                    if aiBrain.GetUnitsAroundPoint then
                        local tExperimentalLevelUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryExperimentalLevel, tLZData[AiBotMap.subrefMidpoint], 100, 'Ally')
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of experimental level units empty='..tostring(AiBotUtilities.IsTableEmpty( tExperimentalLevelUnits))) end
                        if AiBotUtilities.IsTableEmpty( tExperimentalLevelUnits) == false then
                            for iUnit, oUnit in tExperimentalLevelUnits do
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering nearby experimental '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete()) end
                                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() < 1 then
                                    table.insert(tUnitsToAssist, oUnit)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to table of units to assist') end
                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Do we have any units to assist? is table empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToAssist))) end
                if AiBotUtilities.IsTableEmpty(tUnitsToAssist) then
                    --If have upgrading unit then assist this
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of active upgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]))) end
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) == false then tUnitsToAssist = tLZTeamData[AiBotMap.subreftoActiveUpgrades]
                    else
                        --Assist shield if need to defend from arti
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of priority shields to assist empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist]))..'; Defending against arti='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti])) end
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist]) == false and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] >= 2) then
                            tUnitsToAssist = tLZTeamData[AiBotMap.reftPriorityShieldsToAssist]
                        else
                            --otherwise assist an air factory if we have one
                            tUnitsToAssist = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                            if bDebugMessages == true then LOG(sFunctionRef..': Setting unit to assist to be an air factory, is tUnitsToAssist empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToAssist))) end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished saerching for potential units to assist, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToAssist))) end
            if AiBotUtilities.IsTableEmpty(tUnitsToAssist) == false then
                local tStartPoint
                if oGateway then tStartPoint = oGateway:GetPosition()
                elseif AiBotUnitInfo.IsUnitValid(tSACUs[1]) then tStartPoint = tSACUs[1]:GetPosition()
                else tStartPoint = tLZData[AiBotMap.subrefMidpoint] --redundancy
                end
                local oClosestUnitToAssist = AiBotUtilities.GetNearestUnit(tUnitsToAssist, tStartPoint)
                if bDebugMessages == true then LOG(sFunctionRef..': oClosestUnitToAssist='..(oClosestUnitToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnitToAssist) or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oClosestUnitToAssist))) end
                if not(AiBotUnitInfo.IsUnitValid(oClosestUnitToAssist)) then AiBotUtilities.ErrorHandler('No unit to assist for RAS', true)
                else
                    for iUnit, oUnit in tSACUs do
                        AiBotOrders.IssueTrackedGuard(oUnit, oClosestUnitToAssist, false, 'RASAs', false)
                        if bDebugMessages == true then LOG(sFunctionRef..': Telling RAS '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to assist unit') end
                    end
                end

            else
                --Othewrise clear orders if nothing to assist
                for iUnit, oUnit in tSACUs do
                    if not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) and not(oUnit:IsUnitState('Moving')) and (oUnit:IsUnitState('Repairing') or oUnit:IsUnitState('Building') or oUnit:IsUnitState('Guarding')) then
                        AiBotOrders.IssueTrackedClearCommands(oUnit)
                    end
                end
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetNearestEnemyInOtherPlateau(iPlateau, tLZData, iTeam, bGetIndirectThreatInstead)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetNearestEnemyInOtherPlateau'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData) --redundancy
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
        local iClosestEnemyDist = 10000
        local oClosestEnemy
        local iCurDist
        local iEnemyIFThreat = 0
        local iEnemyBestRange = 0
        for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iPlateauOrPond='..tSubtable[AiBotMap.subrefiPlateauOrPond]..'; Is water zone='..tostring(tSubtable[AiBotMap.subrefbIsWaterZone])..'; Distance='..tSubtable[AiBotMap.subrefiDistance]..'; iEntry='..iEntry) end
            if tSubtable[AiBotMap.subrefiDistance] >= 170 and (iEntry >= 7 or tSubtable[AiBotMap.subrefiDistance] >= 320 or (bGetIndirectThreatInstead and tSubtable[AiBotMap.subrefiDistance] >= 200)) then break end
            if not(iPlateau == tSubtable[AiBotMap.subrefiPlateauOrPond]) and not(tSubtable[AiBotMap.subrefbIsWaterZone]) then --water zones dont track indirect fire threat, and in any event battleships and cruisers outrange t2 arti and mobile t3 arti (which is what this might be used for)
                --Have a nearby land zone in a different plateau, check if there are enemy units in this LZ and (if so) if any of them are structures
                local tAdjLZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                if not(tAdjLZData[AiBotMap.subrefbPacifistArea]) then
                    local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                        if bGetIndirectThreatInstead then
                            iEnemyIFThreat = iEnemyIFThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureIndirect] or 0) + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0)
                            iEnemyBestRange = math.max(iEnemyBestRange, (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] or 0))
                        else
                            for iUnit, oUnit in tAdjLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                if AiBotUnitInfo.IsUnitValid(oUnit) then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oUnit:GetPosition())
                                    if iCurDist <= iClosestEnemyDist then
                                        oClosestEnemy = oUnit
                                        iClosestEnemyDist = iCurDist
                                        if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurDist='..iCurDist..'; this is the closest unit for now, will cycle through any remaining') end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for enemy units in nearby different plateau, oClosestEnemy='..(oClosestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy) or 'nli')..'; iEnemyIFThreat='..iEnemyIFThreat..'; bGetIndirectThreatInstead='..tostring(bGetIndirectThreatInstead or false)) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        if bGetIndirectThreatInstead then return iEnemyIFThreat, iEnemyBestRange
        else
            return oClosestEnemy
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function BackupUnitTowardsRallyIfAvailable(oUnit, tRallyPoint, iIslandPlateauOrPondRef, sOrderDesc, bAmphibiousAndUsingPlateauRef, iDefaultDistOverride, iMaxAngleDifForMovingBackwardsOverride, bUsingPondRef)
    --iDefaultDistOverride - if specified, then doesnt require a backup dist to move back, and will use this if no backup dist is available
    --iMaxAngleDifForMovingBackwardsOverride - Overrides the maximum angle difference allowed to move backwards in a straight line for the unit instead of moving to tRallyPoint; if this is exceeded, then will try and move to the rally point instead

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'BackupUnitTowardsRallyIfAvailable'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oUnit) then
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit position='..repru(oUnit:GetPosition())..'; tRallyPoint='..repru(tRallyPoint)..'; iIslandPlateauOrPondRef='..iIslandPlateauOrPondRef..'; sOrderDesc='..sOrderDesc..'; bAmphibiousAndUsingPlateauRef='..tostring(bAmphibiousAndUsingPlateauRef)..'; iDefaultDistOverride='..(iDefaultDistOverride or 'nil')..'; iMaxAngleDifForMovingBackwardsOverride='..(iMaxAngleDifForMovingBackwardsOverride or 'nil')..'; Dist to the rally point/position to move='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint)..'; Time='..GetGameTimeSeconds()) end
        local iBackupDist = 0
        local iMaxAngleDifference = iMaxAngleDifForMovingBackwardsOverride or 35
        local bValidTowardsLocation = false
        local bContinue = true
        if oUnit[AiBotUnitInfo.refbCanKite] then
            iBackupDist = (oUnit:GetBlueprint().Physics.BackUpDistance or 0)
        end

        if iBackupDist >= 6 or iDefaultDistOverride then


            local iDistToMove
            if iDefaultDistOverride and iBackupDist >= 3 then iDistToMove = math.min(iBackupDist - 1, iDefaultDistOverride)
            elseif not(iDefaultDistOverride) then
                iDistToMove = math.min(iBackupDist - 1, 20)
                if iBackupDist >= 12 and iBackupDist < 20 then iDistToMove = iDistToMove - 1.5 end
            else iDistToMove = iDefaultDistOverride
            end
            local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tRallyPoint)
            local iCurUnitFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oUnit)
            local iMoveBackwardsAngle = iCurUnitFacingDirection - 180
            if iMoveBackwardsAngle < 0 then iMoveBackwardsAngle = iMoveBackwardsAngle + 360 end
            local tPotentialMoveLocation
            local iAngleDif = AiBotUtilities.GetAngleDifference(iAngleToRally, iMoveBackwardsAngle)
            local iAngleActuallyMoving

            if bDebugMessages == true then LOG(sFunctionRef..': Checking whether to move directly backwards, iAngleToRally='..iAngleToRally..'; iMoveBackwardsAngle='..iMoveBackwardsAngle..'; iAngleDif='..iAngleDif..'; iMaxAngleDifference='..iMaxAngleDifference..' Approx Speed (X and Z velocity times 10) = '..AiBotUnitInfo.GetUnitSpeed(oUnit)) end
            function CheckIfValidLocation()
                if bAmphibiousAndUsingPlateauRef then
                    if NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPotentialMoveLocation) == iIslandPlateauOrPondRef then
                        bValidTowardsLocation = true
                    end
                elseif not(bUsingPondRef) then
                    if NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tPotentialMoveLocation) == iIslandPlateauOrPondRef then
                        bValidTowardsLocation = true
                    end
                else
                    if NavUtils.GetLabel(AiBotMap.refPathingTypeNavy, tPotentialMoveLocation) == iIslandPlateauOrPondRef then
                        bValidTowardsLocation = true
                    end
                end
            end
            if iAngleDif >= 3 and iAngleDif <= iMaxAngleDifference then
                local iMaxAngleAdjust = math.min(iAngleDif, 5)
                if iMoveBackwardsAngle > iAngleToRally then iMaxAngleAdjust = -iMaxAngleAdjust end
                iAngleActuallyMoving = iMoveBackwardsAngle + iMaxAngleAdjust
                tPotentialMoveLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(),iAngleActuallyMoving, iDistToMove, true, false)
                CheckIfValidLocation()

            end
            --else
            if not(bValidTowardsLocation) then
                tPotentialMoveLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleToRally, iDistToMove, true, false)
                CheckIfValidLocation()
                iAngleActuallyMoving = iAngleToRally
            end
            if tPotentialMoveLocation and bValidTowardsLocation then
                --If arent already moving in this direction then stop for 1 tick, as backing up doesnt work properly otherwise
                local tLastOrder = oUnit[AiBotOrders.reftiLastOrders][1]
                if bDebugMessages == true then LOG(sFunctionRef..': iAngleToRally='..iAngleToRally..'; iDistToMove='..iDistToMove..'; bValidTowardsLocation='..tostring(bValidTowardsLocation or false)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit))
                    if tLastOrder and tLastOrder[AiBotOrders.subreftOrderPosition] then LOG(sFunctionRef..': Angle dif between destination and last move order='..AiBotUtilities.GetAngleDifference(iAngleActuallyMoving, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition]))) end
                end
                local bStopFirst = false
                if (tLastOrder and not(tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueMove)) then
                    bStopFirst = true

                elseif tLastOrder[AiBotOrders.subreftOrderPosition] then
                    local iAngleDif = AiBotUtilities.GetAngleDifference(iAngleActuallyMoving, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition]))
                    if iAngleDif > 15 then
                        bStopFirst = true
                    end
                end
                local iUnitSpeed = AiBotUnitInfo.GetUnitSpeed(oUnit)
                if bStopFirst then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will clear unit orders and wait a bit until unit is going slow enough, unit approx speed='..AiBotUnitInfo.GetUnitSpeed(oUnit)) end
                    local iTotalTimeWaited = 0
                    AiBotOrders.IssueTrackedClearCommands(oUnit)
                    while AiBotUnitInfo.IsUnitValid(oUnit) and iUnitSpeed >= 0.75 and iTotalTimeWaited <= 9 do
                        if iTotalTimeWaited == 0 then
                            AiBotOrders.UpdateUnitNameForOrder(oUnit, 'Slow4Rev')
                        end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(1)
                        iTotalTimeWaited = iTotalTimeWaited + 1
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        if bDebugMessages == true then LOG(sFunctionRef..': Speed after waiting 1 tick='..AiBotUnitInfo.GetUnitSpeed(oUnit)..'; iTotalTimeWaited in ticks='..iTotalTimeWaited) end
                    end
                    if not(AiBotUnitInfo.IsUnitValid(oUnit)) then
                        bContinue = false
                    end


                    --Ticks to wait:
                    --With no 'move 5 degrees towards rally' logic: 3 tick delay meant this only worked sometimes, and failed in one case with a fatboy; 4-7 tick delay failed initially when fatboy was moving forwards but didn't have issues after that, 8 ticks worked more reliably; velocity when 8 ticks worked: X-0.10995483398438 Y0 Z0.13614654541016; with 5 degree logic also still neededed to wait 8 ticks instead of 4 to move backwards
                    --With 5 degree logic, when velocity slowed to iTotalVelocity=0.073184967041016 was no need to wait any ticks to move ackwards
                    --Therefore will try waiting 1 tick until speed is sub-1 (speed being total velocity * 10); when did this, with a speed threshold of 1, it failed with fatboy; speed of 0.73837280273438 was ok

                end
                if bContinue then
                    if bDebugMessages == true then LOG(sFunctionRef..': tPotentialMoveLocation='..repru(tPotentialMoveLocation)..'; Unit position='..repru(oUnit:GetPosition())..'; iDistToMove='..(iDistToMove or 'nil')..'; Dist to potential move location='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tPotentialMoveLocation)..'; bStopFirst='..tostring(bStopFirst)..'; iUnitSpeed='..iUnitSpeed) end
                    AiBotOrders.IssueTrackedMove(oUnit, tPotentialMoveLocation, math.min(iDistToMove * 0.2, 5), false, sOrderDesc..'T', false)
                    --Check if we are being blocked - decided to leave out in the end as not convinced it was actually helping significantly (ignore for water)
                    if iDistToMove > 2 and iTicksPerLandCycle <= 15 and AiBotMap.GetLandZoneFromPosition(oUnit:GetPosition()) then
                        local tViaPoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(),iAngleActuallyMoving, 0.5)
                        if tViaPoint then
                            local rRectToSearch = AiBotUtilities.GetRectAroundLocation(tViaPoint, 0.5)
                            local tBlockingUnits = AiBotUtilities.GetUnitsInRect(rRectToSearch)
                            if AiBotUtilities.IsTableEmpty(tBlockingUnits) == false then
                                local iTeam = oUnit:GetAIBrain().AiBotTeam
                                local iMassThreshold = oUnit[AiBotUnitInfo.refiUnitMassCost] * 3
                                local tBlockingViaPoint
                                for iBlockingUnit, oBlockingUnit in tBlockingUnits do
                                    if not(oBlockingUnit == oUnit) and AiBotUnitInfo.IsUnitValid(oBlockingUnit) and (oBlockingUnit[AiBotUnitInfo.refiUnitMassCost] or iMassThreshold) < iMassThreshold and not(oBlockingUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
                                        local oBrain = oBlockingUnit:GetAIBrain()
                                        if oBrain.AiBotAI and oBrain.AiBotTeam == iTeam then
                                            --Move this unit the same direction
                                            if not(tBlockingViaPoint) then
                                                tBlockingViaPoint = AiBotUtilities.MoveInDirection(oBlockingUnit:GetPosition(),iAngleActuallyMoving, iDistToMove + 1)
                                            end
                                            AiBotOrders.IssueTrackedMove(oBlockingUnit, tBlockingViaPoint, 1, false, sOrderDesc..'Bl', false)
                                            AiBotMicro.TrackTemporaryUnitMicro(oBlockingUnit, 0.5, nil, true)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will also retreat blocking unit '..oBlockingUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBlockingUnit)) end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if iUnitSpeed * iTicksPerLandCycle * 0.1 > iDistToMove * 0.75 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to issue an interim move order after the first, will first wait '..math.ceil(iTicksPerLandCycle * 0.5)..' ticks') end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(math.ceil(iTicksPerLandCycle * 0.5))
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting, will issue interim order now for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            BackupUnitTowardsRallyIfAvailable(oUnit, tRallyPoint, iIslandPlateauOrPondRef, sOrderDesc, bAmphibiousAndUsingPlateauRef, iDefaultDistOverride, iMaxAngleDifForMovingBackwardsOverride, bUsingPondRef)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        end
                    end
                end
            end
        end
        if bContinue and not(bValidTowardsLocation) then
            AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 5, false, sOrderDesc..'R', false)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordDFLandZoneTarget(tCurrentLZOrWZTeamData, iPlateau, iLandOrWaterZone, iTeam, iLandZoneTarget, iAttackType, bIsWaterZone)
    --Send nil value to clear previously recorded values
    --iPlateau should be the plateau whether called by LZ or WZ
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordDFLandZoneTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bIsWaterZone then
    elseif not(iLandZoneTarget) then
        if tCurrentLZOrWZTeamData[AiBotMap.subreftiLandZoneTargetedByOurCombat] then
            local tTargetingLandZoneTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tCurrentLZOrWZTeamData[AiBotMap.subreftiLandZoneTargetedByOurCombat]][AiBotMap.subrefLZTeamData][iTeam]
            if tTargetingLandZoneTeamData then
                if bDebugMessages == true then LOG(sFunctionRef..': About to update for iPlateau='..iPlateau..'subreftiLandZoneTargetedByOurCombat='..(tCurrentLZOrWZTeamData[AiBotMap.subreftiLandZoneTargetedByOurCombat] or 'nil')..'; is tTargetingLandZoneTeamData nil='..tostring(tTargetingLandZoneTeamData == nil)) end
                if bIsWaterZone then
                    if tTargetingLandZoneTeamData[AiBotMap.subreftiLandZonesTargetingThisWithAmphibious] then
                        tTargetingLandZoneTeamData[AiBotMap.subreftiLandZonesTargetingThisWithAmphibious][iLandOrWaterZone] = nil
                    end
                else
                    if tTargetingLandZoneTeamData[AiBotMap.subreftiLandZonesTargetingThisWithOurDF] then
                        tTargetingLandZoneTeamData[AiBotMap.subreftiLandZonesTargetingThisWithOurDF][iLandOrWaterZone] = nil
                    end
                end
            else
                AiBotUtilities.ErrorHandler('invalid LZ ref, iPlateau='..(iPlateau or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; subreftiLandZoneTargetedByOurCombat='..(tCurrentLZOrWZTeamData[AiBotMap.subreftiLandZoneTargetedByOurCombat] or 'nil'))
            end
            tCurrentLZOrWZTeamData[AiBotMap.subreftiLandZoneTargetedByOurCombat] = nil
        end
    else
        tCurrentLZOrWZTeamData[AiBotMap.subreftiLandZoneTargetedByOurCombat] = iLandZoneTarget
        local tTargetingLandZoneTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZoneTarget][AiBotMap.subrefLZTeamData][iTeam]
        if bIsWaterZone then
            if not(tTargetingLandZoneTeamData[AiBotMap.subreftiWaterZonesTargetingThisWithAmphibious]) then tTargetingLandZoneTeamData[AiBotMap.subreftiWaterZonesTargetingThisWithAmphibious] = {} end
            tTargetingLandZoneTeamData[AiBotMap.subreftiWaterZonesTargetingThisWithAmphibious][iLandOrWaterZone] = iAttackType
        else
            if not(tTargetingLandZoneTeamData[AiBotMap.subreftiLandZonesTargetingThisWithOurDF]) then tTargetingLandZoneTeamData[AiBotMap.subreftiLandZonesTargetingThisWithOurDF] = {} end
            tTargetingLandZoneTeamData[AiBotMap.subreftiLandZonesTargetingThisWithOurDF][iLandOrWaterZone] = iAttackType
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageCombatUnitsInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tAvailableCombatUnits, iFriendlyBestMobileDFRange, iFriendlyBestMobileIndirectRange, bWantIndirectReinforcements, tUnavailableUnitsInThisLZ, bDelayOrdersForHover, bHaveCombatUnitsFromAdjZone)
    --Handles logic for main combat units (direct and indirect fire mobile units) that are noted as available to the land zone
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageCombatUnitsInLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then
        LOG(sFunctionRef..': start of code, iTeam='..iTeam..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Is table of available combat units empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableCombatUnits))..'; iFriendlyBestMobileDFRange='..iFriendlyBestMobileDFRange..'; iFriendlyBestMobileIndirectRange='..iFriendlyBestMobileIndirectRange..'; Are there enemy units in this or adjacent LZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; bWantIndirectReinforcements='..tostring(bWantIndirectReinforcements or false)..'; tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]='..tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]..'; subrefLZThreatAllyMobileIndirectByRange='..repru(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange])..'; subrefLZThreatAllyMobileDFByRange='..repru(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange])..'; Enemy mobile DF='..repru(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange])..'; Threat of tAvailableCombatUnits='..AiBotUnitInfo.GetCombatThreatRating(tAvailableCombatUnits, false, false, false)..'; subrefiAvailableMobileShieldThreat='..(tLZTeamData[AiBotMap.subrefiAvailableMobileShieldThreat] or 0)..'; LZ value='..tLZTeamData[AiBotMap.subrefLZTValue]..'; refiModDistancePercent='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Time='..GetGameTimeSeconds())
        for iUnit, oUnit in tAvailableCombatUnits do
            LOG(sFunctionRef..': Threat of unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'='..AiBotUnitInfo.GetCombatThreatRating({ oUnit }, false, false, false))
        end
    end

    function ProceedWithUnitOrder(oUnit, bWeOutrangeEnemy)
        if bDelayOrdersForHover and EntityCategoryContains(categories.HOVER, oUnit.UnitId) then
            if bWeOutrangeEnemy then
                if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeOfLastHoverLandCombatOrder] or -10) <= 6 then
                    return false
                end
            else
                if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeOfLastHoverLandCombatOrder] or -10) <= 8 then
                    return false
                end
            end
            oUnit[AiBotUnitInfo.refiTimeOfLastHoverLandCombatOrder] = GetGameTimeSeconds()
        end
        return true
    end
    local iCurTime = math.floor(GetGameTimeSeconds())
    function IgnoreOrderDueToStuckUnit(oUnit, tOptionalTargetConsideringAttacking)
        --tOptionalTargetConsideringAttacking - if specified, and our shot isnt blocked, then ignore being stuck
        if oUnit[AiBotUnitInfo.refbUnitStuckAlternating] then
            if not(tOptionalTargetConsideringAttacking) or oUnit[AiBotUnitInfo.refbLastShotBlocked] or AiBotUtilities.GetDistanceBetweenPositions(tOptionalTargetConsideringAttacking, oUnit:GetPosition()) > (oUnit[AiBotUnitInfo.refiCombatRange] or 0) + 3 then
                if (not(oUnit[AiBotUnitInfo.refbEasyBrain]) or EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnit.UnitId)) and oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition] and AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition], oUnit:GetPosition()) >= 15 then
                    if oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGroundAttack then
                        --We wont reach destination with a ground attack so need new orders
                        return false
                    else
                        --Do nothing - want unit to reach its destination before it gets new orders
                        if bDebugMessages == true then LOG(sFunctionRef..': Unit is stuck so will ignore orders') end
                        return true
                    end
                end
            end
        end
    end

    local bWantReinforcements = false
    local bIgnoreEnemiesInThisZone = false
    local tbAdjacentZoneEnemiesToIgnoreByZone = {}
    local bConsiderEnemiesInAtLeastOneAdjacentZone = true
    local tUnitsNearFatboyInFurtherAwayZones

    --First record the range of enemy units, and which units in adjacent zones are nearest to us:
    UpdateBestEnemyRangesForThisLandZone(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam)
    local iEnemyBestMobileDFRange, iEnemyBestStructureDFRange, iEnemyBestMobileIndirectRange = RecordClosestAdjacentEnemiesAndGetBestEnemyRange(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam)
    local tRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2) --Get a LZ up to 3 land zones away to retreat to (i.e. will pick rally point and then move 2 towards it)
    local tAmphibiousRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2, true)
    local iAngleTowardsBase = AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestFriendlyBase])
    local iDistTowardsBase = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestFriendlyBase])
    local tMoveTowardsBaseRetreatPoint = AiBotUtilities.MoveInDirection(tLZData[AiBotMap.subrefMidpoint], iAngleTowardsBase, math.min(50, iDistTowardsBase), true, false, AiBotMap.bIsCampaignMap)
    if bDebugMessages == true then LOG(sFunctionRef..': tMoveTowardsBaseRetreatPoint='..repru(tMoveTowardsBaseRetreatPoint)..'; iAngleTowardsBase='..iAngleTowardsBase..'; iDistTowardsBase from LZ midpoint='..iDistTowardsBase..'; Midpoint='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tMoveTowardsBaseRetreatPoint) or 'nil')..'; tLZData[AiBotMap.subrefLZIslandRef]='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')) end
    if tMoveTowardsBaseRetreatPoint then
        if not(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tMoveTowardsBaseRetreatPoint) == tLZData[AiBotMap.subrefLZIslandRef]) then
            tMoveTowardsBaseRetreatPoint = nil
        else
            local iAngleToRallyPoint = AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tRallyPoint)
            if bDebugMessages == true then LOG(sFunctionRef..': iAngleToRallyPoint='..iAngleToRallyPoint..'; Angle dif='..AiBotUtilities.GetAngleDifference(iAngleToRallyPoint, iAngleTowardsBase)..'; Dist between rally point and bsae='..AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, tLZTeamData[AiBotMap.reftClosestFriendlyBase])) end
            if AiBotUtilities.GetAngleDifference(iAngleToRallyPoint, iAngleTowardsBase) <= 20 then
                tMoveTowardsBaseRetreatPoint = nil
            elseif AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 20 then
                tMoveTowardsBaseRetreatPoint = nil
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': tAmphibiousRallyPoint='..repru(tAmphibiousRallyPoint)..'; tRallyPoint='..repru(tRallyPoint)) end
    local iIndirectRunFigureNormal = 10
    local iIndirectRunFigureDeployedAdjust = 15
    local iIndirectRunFigureSynchronisation = 11
    local iIndirectDistanceInsideRangeThreshold

    local oClosestFriendlyUnitToAnEnemyFirebase --For simplicity will be the closest unit to the last firebase checked (where multiple firebases)
    local iClosestFriendlyUnitToAnEnemyFirebase = 100000

    local iFirebaseThreatAdjust = 0
    local iFirebaseCloseCombatThreat = 0
    local iAdjacentFirebaseThreat = 0

    local iAvailableCombatUnitThreat = AiBotUnitInfo.GetMassCostOfUnits(tAvailableCombatUnits)
    iAvailableCombatUnitThreat = iAvailableCombatUnitThreat + math.min(iAvailableCombatUnitThreat, tLZTeamData[AiBotMap.subrefiAvailableMobileShieldThreat])



    local bHaveSignificantCombatCloserToFirebase = false
    local iClosestFirebaseDist = 100000
    local oClosestUnitFromAllFirebases
    local oNearestFirebaseUnit

    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false then
        --Is the firebase not in range of a core LZ?
        local bFirebaseInCoreLZRange = false
        local oOurNearestUnitToFirebase
        local tEnemyT2ArtiAndShields
        local iCurDist
        local iClosestDist
        local iCurFirebaseThreat
        local bIsAdjacent
        local iDistToFirebase
        local iClosestDistFromAllFirebases = 100000

        for iEntry, tPlateauAndLZ in tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange] do
            if AiBotMap.tAllPlateaus[tPlateauAndLZ[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndLZ[2]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase] then
                bFirebaseInCoreLZRange = true
                iFirebaseThreatAdjust = 0
                break
            else
                --Ignore firebase in the LZ we are already in
                if not(iLandZone == tPlateauAndLZ[2]) then
                    local tFirebaseLZData = AiBotMap.tAllPlateaus[tPlateauAndLZ[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndLZ[2]]
                    local tFirebaseLZTeamData = tFirebaseLZData[AiBotMap.subrefLZTeamData][iTeam]
                    tEnemyT2ArtiAndShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryFixedShield, tFirebaseLZTeamData[AiBotMap.subrefTEnemyUnits])
                    if AiBotUtilities.IsTableEmpty(tEnemyT2ArtiAndShields) == false then
                        iClosestDist = 100000
                        for iUnit, oUnit in tEnemyT2ArtiAndShields do
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                oNearestFirebaseUnit = oUnit
                                if iCurDist < iClosestDistFromAllFirebases then
                                    oClosestUnitFromAllFirebases = oUnit
                                end
                            end
                        end
                        iClosestDist = 100000
                        local tFirebaseMidpoint = tFirebaseLZData[AiBotMap.subrefMidpoint]
                        for iUnit, oUnit in tAvailableCombatUnits do
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tFirebaseMidpoint)
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                oOurNearestUnitToFirebase = oUnit
                                if iClosestDist < iClosestFriendlyUnitToAnEnemyFirebase then
                                    oClosestFriendlyUnitToAnEnemyFirebase = oUnit
                                    iClosestFriendlyUnitToAnEnemyFirebase = iClosestDist
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': oOurNearestUnitToFirebase='..oOurNearestUnitToFirebase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOurNearestUnitToFirebase)..'; oNearestFirebaseUnit='..oNearestFirebaseUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestFirebaseUnit)..'; Dist between them='..AiBotUtilities.GetDistanceBetweenPositions(oOurNearestUnitToFirebase:GetPosition(), oNearestFirebaseUnit:GetPosition())) end

                        if oOurNearestUnitToFirebase and oNearestFirebaseUnit then
                            iCurFirebaseThreat = 0
                            iDistToFirebase = AiBotUtilities.GetDistanceBetweenPositions(oOurNearestUnitToFirebase:GetPosition(), oNearestFirebaseUnit:GetPosition())
                            iClosestFirebaseDist = math.min(iClosestFirebaseDist, iDistToFirebase)
                            if iDistToFirebase <= 140 then
                                iCurFirebaseThreat = AiBotUnitInfo.GetMassCostOfUnits(tEnemyT2ArtiAndShields, true)
                                if iCurFirebaseThreat > 0 then
                                    iFirebaseCloseCombatThreat = tFirebaseLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] + math.min(tFirebaseLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 1.5, (tFirebaseLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0)) --combat total excludes shields and t2 arti
                                    bIsAdjacent = false
                                    if AiBotUtilities.IsTableEmpty(tFirebaseLZData[AiBotMap.subrefLZPath]) == false then

                                        --Include friendly units in LZs between here and the firebase
                                        if bDebugMessages == true then
                                            --LOG(sFunctionRef..': iLandZone='..reprs(iLandZone))
                                            --LOG(sFunctionRef..': tPlateauAndLZ[2]='..reprs(tPlateauAndLZ[2]))
                                            --LOG(sFunctionRef..': tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][tPlateauAndLZ[2]]='..reprs(tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][tPlateauAndLZ[2]]))
                                            --LOG(sFunctionRef..': pathing='..reprs(tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][tPlateauAndLZ[2]]][AiBotMap.subrefLZPath]))
                                            --LOG(sFunctionRef..': tLZData[AiBotMap.subrefLZPathingToOtherLandZones]='..reprs(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]))
                                            LOG(sFunctionRef..': Will cycle through all LZs between LZ'..reprs(iLandZone or 'nil')..' and LZ'..reprs(tPlateauAndLZ[2] or 'nil')..' and factor in friendly threat; Entry in pathing table='..reprs(tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][tPlateauAndLZ[2]] or 'nil')..'; reprs of pathing='..reprs(tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][tPlateauAndLZ[2]]][AiBotMap.subrefLZPath])..'; tLZData[AiBotMap.subrefLZPathingToOtherLandZones]='..reprs(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]))
                                        end

                                        for iEntry, iAdjacentLandZone in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                            if iAdjacentLandZone == tPlateauAndLZ[2] then
                                                bIsAdjacent = true
                                            end
                                        end
                                        for iEntry, iPathLZ in tFirebaseLZData[AiBotMap.subrefLZPath] do
                                            if not(iPathLZ == iLandZone) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Friendly LZ that will pass through to get to firebase='..iPathLZ..'; Friendly combat threat of this='..(AiBotMap.tAllPlateaus[tPlateauAndLZ[1]][AiBotMap.subrefPlateauLandZones][iPathLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZTThreatAllyCombatTotal] or 'nil')) end
                                                local tOtherFirebaseZoneTeamData = AiBotMap.tAllPlateaus[tPlateauAndLZ[1]][AiBotMap.subrefPlateauLandZones][iPathLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                iCurFirebaseThreat = iCurFirebaseThreat - (tOtherFirebaseZoneTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)
                                                iFirebaseCloseCombatThreat = iFirebaseCloseCombatThreat + (tOtherFirebaseZoneTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tOtherFirebaseZoneTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)
                                                if not(bHaveSignificantCombatCloserToFirebase) and AiBotMap.tAllPlateaus[tPlateauAndLZ[1]][AiBotMap.subrefPlateauLandZones][iPathLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZTThreatAllyCombatTotal] >= 4000 then
                                                    bHaveSignificantCombatCloserToFirebase = true
                                                end
                                            end
                                        end
                                    end
                                    if bIsAdjacent then
                                        --Track adjacent firebase threat so if we want to take this into account later we can; dont think we are double-counting this though so currently only using to affect decision on whether to automatically retreat
                                        iAdjacentFirebaseThreat = iAdjacentFirebaseThreat + math.max(iCurFirebaseThreat, 0)
                                    end
                                end
                            end
                            iFirebaseThreatAdjust = iFirebaseThreatAdjust + math.max(iCurFirebaseThreat, 0)
                        end
                    end
                else
                    iClosestFirebaseDist = 0
                end
            end
        end
    end

    --If enemy has a firebase, then retreat if we dont have enough threat to beat it and we dont have significant indirect force
    local bRunFromFirebase = false
    if bDebugMessages == true then LOG(sFunctionRef..': If enemy has nearby firebase will check if we have enough units to try and attack it, iFirebaseThreatAdjust='..iFirebaseThreatAdjust..'; bHaveSignificantCombatCloserToFirebase='..tostring(bHaveSignificantCombatCloserToFirebase or false)..'; iFirebaseCloseCombatThreat='..iFirebaseCloseCombatThreat..'; is subreftEnemyFirebasesInRange empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]))..'; is subreftoAllNearbyEnemyT2ArtiUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]))) end
    if iFirebaseThreatAdjust > 0 and not(bHaveSignificantCombatCloserToFirebase) then
        if iAvailableCombatUnitThreat < math.min(20000, iFirebaseThreatAdjust) or (iAvailableCombatUnitThreat < iFirebaseThreatAdjust * 2) then
            --Retreat by default then check if have enough threat to attack
            bRunFromFirebase = true
            --Exception if we have fatboys or megaliths in which case compare to enemy long range threat as well
            if iAvailableCombatUnitThreat >= 8000 then
                local tFriendlyExperimental = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental, tAvailableCombatUnits)
                if bDebugMessages == true then LOG(sFunctionRef..': Will consider running from firebase, is table of firendly experimentals empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyExperimental))) end
                if AiBotUtilities.IsTableEmpty(tFriendlyExperimental) == false then
                    local iLRExpThreat = 0
                    local bHaveDamagedFatboys = false
                    local bHaveFatboys = false
                    local iSRExpThreat = 0
                    local bHaveSRExpNearFirebaseUnit = false
                    for iUnit, oUnit in tFriendlyExperimental do
                        if (oUnit[AiBotUnitInfo.refiCombatRange] or 0) >= 60 then
                            local iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, false)
                            if iMaxShield > 0 then
                                bHaveFatboys = true
                                if iCurShield > 0 then
                                    iLRExpThreat = iLRExpThreat + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * iCurShield / iMaxShield
                                    if iCurShield < iMaxShield * 0.7 then bHaveDamagedFatboys = true end
                                else bHaveDamagedFatboys = true
                                end
                            else
                                iLRExpThreat = iLRExpThreat + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * AiBotUnitInfo.GetUnitHealthPercent(oUnit)
                            end
                        end
                        --Include megalith in both LR and SR threats
                        if (oUnit[AiBotUnitInfo.refiDFRange] or 0) <= 80 and not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryFatboy + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId)) then
                            iSRExpThreat = iSRExpThreat + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * AiBotUnitInfo.GetUnitHealthPercent(oUnit)
                            if not(bHaveSRExpNearFirebaseUnit) and oClosestUnitFromAllFirebases and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestUnitFromAllFirebases:GetPosition()) <= oUnit[AiBotUnitInfo.refiCombatRange] + 10 then
                                bHaveSRExpNearFirebaseUnit = true
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iLRExpThreat='..iLRExpThreat..'; iSRExpThreat='..iSRExpThreat..'; bHaveSRExpNearFirebaseUnit='..tostring(bHaveSRExpNearFirebaseUnit or false)) end
                    if bHaveSRExpNearFirebaseUnit and (iAvailableCombatUnitThreat >= iFirebaseCloseCombatThreat * 0.8 or iSRExpThreat >= 8000) then
                        bRunFromFirebase = false
                    elseif iLRExpThreat > 0 then
                        local iEnemyT2ArtiThreat = 0
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                            --Treat T2 arti as being worth twice their mass cost since we may be dealing with a fatboy
                            iEnemyT2ArtiThreat = AiBotUnitInfo.GetMassCostOfUnits(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits], true)
                            if bHaveFatboys then iEnemyT2ArtiThreat = iEnemyT2ArtiThreat * 1.25 end
                            if bHaveDamagedFatboys then iEnemyT2ArtiThreat = iEnemyT2ArtiThreat * 1.25 end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iLRExpThreat='..iLRExpThreat..'; tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]='..tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]..'; iEnemyT2ArtiThreat='..iEnemyT2ArtiThreat..'; bHaveFatboys='..tostring(bHaveFatboys or false)..'; iFirebaseCloseCombatThreat='..iFirebaseCloseCombatThreat) end
                        if iLRExpThreat > tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] + iEnemyT2ArtiThreat or (not(bHaveDamagedFatboys) and math.max(iAvailableCombatUnitThreat, iLRExpThreat) >= iFirebaseCloseCombatThreat * 2) then
                            bRunFromFirebase = false
                        end
                    end
                    if bRunFromFirebase and iSRExpThreat > 0 then
                        if iSRExpThreat > math.max(8000, iFirebaseCloseCombatThreat * 3) or ((iClosestFirebaseDist <= 80 or bHaveSignificantCombatCloserToFirebase) and iSRExpThreat >= math.max(7000, iFirebaseCloseCombatThreat * 2)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Have enough short range experimental threat to press the attack') end
                            bRunFromFirebase = false
                        end
                    end
                end
            end
            if bRunFromFirebase and iClosestFirebaseDist <= 100 then
                local tFriendlyIndirect = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryIndirect, tAvailableCombatUnits)
                if AiBotUtilities.IsTableEmpty( tFriendlyIndirect) == false then
                    local iFriendlyIndirect = table.getn(tFriendlyIndirect)
                    if bDebugMessages == true then LOG(sFunctionRef..': Friendly indirect of all tech level='..iFriendlyIndirect) end
                    if iFriendlyIndirect >= 20 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Exception to decision to run from firebase') end
                        bRunFromFirebase = false
                        --if the firebase is close to a core base or we have MMLs in this zone or other zones that have recently damaged it then consider attacking anyway
                    else
                        local tFriendlyT2PlusIndirect = EntityCategoryFilterDown(categories.ALLUNITS - categories.TECH1, tFriendlyIndirect)
                        if AiBotUtilities.IsTableEmpty(tFriendlyT2PlusIndirect) == false then
                            iFriendlyIndirect = table.getn(tFriendlyT2PlusIndirect)
                            if iFriendlyIndirect >= 2 and AiBotUnitInfo.IsUnitValid(oClosestUnitFromAllFirebases) then
                                local iFirebasePlateau, iFirebaseZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oClosestUnitFromAllFirebases:GetPosition())
                                if (iFirebaseZone or 0) > 0 and (iFirebasePlateau or 0) > 0 then
                                    --If firebase direct fire range
                                    local tFirebaseLZTeamData = AiBotMap.tAllPlateaus[iFirebasePlateau][AiBotMap.subrefPlateauLandZones][iFirebaseZone][AiBotMap.subrefLZTeamData][iTeam]
                                    --Check enemy doesnt have ravager/equivalent that makes MML bad, or (if they do) that we have lots of T3+ MML
                                    if math.max((tFirebaseLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0), tFirebaseLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0) < 60 or iFriendlyIndirect >= 15 then

                                        if bDebugMessages == true then LOG(sFunctionRef..': Time since last had MML in this zone firing near TMD or shield='..(GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -30))..'; Dist from nearest firebase unit to base='..AiBotUtilities.GetDistanceBetweenPositions(oClosestUnitFromAllFirebases:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])..'; Time since firebase zone had a shield or TMD face a missile='..(GetGameTimeSeconds() - (tFirebaseLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -30))) end
                                        --If have MMLs that have recently damaged the firebase shields or been intercepted by TMD, consider if we have enough MMLs to overwhelm the firebase
                                        if GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -30) <= 30 or GetGameTimeSeconds() - (tFirebaseLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -10) <= 30 or (oClosestUnitFromAllFirebases and AiBotUtilities.GetDistanceBetweenPositions(oClosestUnitFromAllFirebases:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 200) then
                                            local iEnemyTMDCount = 0
                                            local iEnemyT2ArtiCount = 0
                                            local iOurMMLCount = 0
                                            local iOurNonMMLCount = 0
                                            local tOurMML = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMML, tFriendlyT2PlusIndirect)
                                            if AiBotUtilities.IsTableEmpty(tOurMML) == false then
                                                iOurMMLCount = table.getn(tOurMML)
                                            end
                                            iOurNonMMLCount = iFriendlyIndirect - iOurMMLCount
                                            if AiBotUtilities.IsTableEmpty(tFirebaseLZTeamData[AiBotMap.subreftoEnemyTMD]) == false then
                                                iEnemyTMDCount = table.getn(tFirebaseLZTeamData[AiBotMap.subreftoEnemyTMD])
                                            end
                                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                                                iEnemyT2ArtiCount = table.getn(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits])
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': iEnemyTMDCount='..iEnemyTMDCount..'; iOurMMLCount='..iOurMMLCount..'; iOurNonMMLCount='..iOurNonMMLCount..'; iEnemyT2ArtiCount='..iEnemyT2ArtiCount..'; Enemy shield threat='..(tFirebaseLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0)) end
                                            if iEnemyT2ArtiCount == 0 or (iEnemyT2ArtiCount * 1.5 + (tFirebaseLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) / 1000 < (iOurNonMMLCount + math.max(0,(iOurMMLCount - iEnemyTMDCount)))) then
                                                bRunFromFirebase = false
                                                if bDebugMessages == true then LOG(sFunctionRef..': WIll try and attack firebase') end
                                            end
                                            if bRunFromFirebase and iOurMMLCount > 0 and AiBotUtilities.IsTableEmpty( tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                --Revise MML count to factor in all adjacent zones
                                                local tThisZoneMML = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMML, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                                local iAltMMLCount = 0
                                                if AiBotUtilities.IsTableEmpty(tThisZoneMML) == false then
                                                    iAltMMLCount = table.getn(tThisZoneMML)
                                                end
                                                for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                                        tThisZoneMML = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMML, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                                        if AiBotUtilities.IsTableEmpty(tThisZoneMML) == false then
                                                            iAltMMLCount = iAltMMLCount + table.getn(tThisZoneMML)
                                                        end
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': iAltMMLCount='..iAltMMLCount..'; iOurMMLCount='..iOurMMLCount..'; iEnemyT2ArtiCount='..iEnemyT2ArtiCount..'; Enemy shield threat='..(tFirebaseLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0)..'; iEnemyTMDCount='..iEnemyTMDCount) end
                                                if iAltMMLCount > iOurMMLCount then
                                                    if (iEnemyT2ArtiCount * 1.5 + (tFirebaseLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) / 1000 < (iOurNonMMLCount + math.max(0,(iAltMMLCount - iEnemyTMDCount)))) then
                                                        bRunFromFirebase = false
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Hvae enough MML to attack') end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                if bRunFromFirebase then
                    if iAvailableCombatUnitThreat >= math.max(12000, iFirebaseCloseCombatThreat * 3) or (bHaveSignificantCombatCloserToFirebase and  iAvailableCombatUnitThreat >= math.max(7000, iFirebaseCloseCombatThreat * 2)) then
                        bRunFromFirebase = false

                    end
                end
            end
        end
    end

    --Flag that we are attacking this firebase so other zones can also attack it instead of running if they are in scenario 1
    if oClosestUnitFromAllFirebases and (iFriendlyBestMobileIndirectRange or 0) > math.max(tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0, tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0) then
        local tClosestFirebaseTeamData = AiBotMap.GetLandOrWaterZoneData(oClosestUnitFromAllFirebases:GetPosition(), true, iTeam)
        if tClosestFirebaseTeamData then
            if bDebugMessages == true then LOG(sFunctionRef..': Time since we last had a zone wanting to attack this firebase zone='..(tClosestFirebaseTeamData[AiBotMap.refiTimeOfLastIndirectFirebaseAttack] or 'nil')) end
            if bRunFromFirebase == false then
                tClosestFirebaseTeamData[AiBotMap.refiTimeOfLastIndirectFirebaseAttack] = GetGameTimeSeconds()
            elseif GetGameTimeSeconds() - (tClosestFirebaseTeamData[AiBotMap.refiTimeOfLastIndirectFirebaseAttack] or -100) <= 3 then
                bRunFromFirebase = false
            end
        end
    end

    local bSuicideIntoFatboyOrACU = false
    local oClosestFatboyOrACUInIslandToSuicideInto
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) == false then
        local iCurACUDist
        local iClosestACUDist = 150 --Wont try and suicide if are further away than this
        local bSuicideIntoCurACU, bIgnoreDistanceToMidpointCheck
        for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets] do
            if AiBotUnitInfo.IsUnitValid(oACU) and not(AiBotUnitInfo.IsUnitUnderwater(oACU)) and not(oACU:IsUnitState('Attached')) then
                --Require enemy health to be < 5*our available combat threat (prev did 2x, but since 20 tanks is about 1k threat, that means we are running when enemy is at 3k health and we have 20 tanks), or sub-1k
                if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to charge into enemy ACU, ACU health='..oACU:GetHealth()..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; Dist to LZ midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint])) end
                bSuicideIntoCurACU = false
                if oACU:GetHealth() < math.max(1000, iAvailableCombatUnitThreat * 2) then
                    bSuicideIntoCurACU = true
                elseif iAvailableCombatUnitThreat >= 400 and oACU:GetHealth() < math.max(1000, iAvailableCombatUnitThreat * 5) then
                    --Check threat around enemy ACU vs our threat based on our closest available unit to the enemy ACU (so if we have a bunch of tanks nearby we will consider pushing, but if we just have 1-2 tanks we wont)
                    local toUnitsAlmostInRangeOfACU = {}
                    local toUnitsModeratelyFarAway = {}
                    local toUnitsFarAway = {}
                    local iModeratelyFarThreshold = 40
                    local oClosestAvailableCombatToACU
                    local iClosestAvailableCombatToACU = 10000
                    local iCurDistLessRange
                    for iUnit, oUnit in tAvailableCombatUnits do
                        iCurDistLessRange = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange]
                        if iCurDistLessRange < iClosestAvailableCombatToACU then
                            iClosestAvailableCombatToACU = iCurDistLessRange
                            oClosestAvailableCombatToACU = oUnit
                        end
                        if iCurDistLessRange <= 6 then
                            table.insert(toUnitsAlmostInRangeOfACU, oUnit)
                        elseif iCurDistLessRange <= iModeratelyFarThreshold then
                            table.insert(toUnitsModeratelyFarAway, oUnit)
                        else
                            table.insert(toUnitsFarAway, oUnit)
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iClosestAvailableCombatToACU='..iClosestAvailableCombatToACU..'; iModeratelyFarThreshold='..iModeratelyFarThreshold) end
                    if iClosestAvailableCombatToACU <= iModeratelyFarThreshold then
                        local iNearbyThreat = AiBotUnitInfo.GetCombatThreatRating(toUnitsAlmostInRangeOfACU, false, false)
                        local iEnemyACUThreat = AiBotUnitInfo.GetCombatThreatRating({ oACU }, true)
                        if bDebugMessages == true then LOG(sFunctionRef..': iClosestAvailableCombatToACU='..iClosestAvailableCombatToACU..'; iNearbyThreat='..iNearbyThreat..'; iEnemyACUThreat='..iEnemyACUThreat) end
                        if iNearbyThreat >= iEnemyACUThreat then
                            bSuicideIntoCurACU = true
                            bIgnoreDistanceToMidpointCheck = true
                        else
                            local iMediumThreat = AiBotUnitInfo.GetCombatThreatRating(toUnitsModeratelyFarAway, false, false)
                            if bDebugMessages == true then LOG(sFunctionRef..': iMediumThreat='..iMediumThreat) end
                            if iNearbyThreat + iMediumThreat > iEnemyACUThreat then
                                --Do detailed calculation
                                local toFriendlyNearbyCombat = {}
                                for iUnit, oUnit in toUnitsModeratelyFarAway do
                                    if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestAvailableCombatToACU:GetPosition()) <= 20 then
                                        table.insert(  toFriendlyNearbyCombat, oUnit)
                                    end
                                end
                                local iNearbyFriendlyCombatThreat = AiBotUnitInfo.GetCombatThreatRating(toFriendlyNearbyCombat, false, false)
                                if iNearbyThreat + iNearbyFriendlyCombatThreat > iEnemyACUThreat then
                                    local toNearbyEnemyThreat = {}
                                    local iDistanceThreshold = math.max(10, iClosestAvailableCombatToACU + 15)
                                    function IncludeDFEnemiesNearby(tCurLZTeamData, bCheckIfAlreadyRecorded)
                                        if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                            for iUnit, oUnit in tCurLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) - (oUnit[AiBotUnitInfo.refiDFRange] or 0) <= iDistanceThreshold
                                                        or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestAvailableCombatToACU:GetPosition()) - (oUnit[AiBotUnitInfo.refiDFRange] or 0) <= iDistanceThreshold then
                                                    if not(bCheckIfAlreadyRecorded) then
                                                        table.insert(toNearbyEnemyThreat, oUnit)
                                                    else
                                                        local bAlreadyRecorded = false
                                                        for iRecorded, oRecorded in toNearbyEnemyThreat do
                                                            if oRecorded == oUnit then
                                                                bAlreadyRecorded = true
                                                                break
                                                            end
                                                        end
                                                        if not(bAlreadyRecorded) then
                                                            table.insert(toNearbyEnemyThreat, oUnit)
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    IncludeDFEnemiesNearby(tLZTeamData)
                                    if not(oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) and oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau then
                                        local tACUTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZTeamData][iTeam]
                                        IncludeDFEnemiesNearby(tACUTeamData, not(AiBotUtilities.IsTableEmpty(toNearbyEnemyThreat)))
                                    end
                                    local iNearbyEnemyThreat = AiBotUnitInfo.GetCombatThreatRating(toNearbyEnemyThreat, true)
                                    if bDebugMessages == true then LOG(sFunctionRef..': iNearbyEnemyThreat='..iNearbyEnemyThreat..'; iNearbyFriendlyCombatThreat='..iNearbyFriendlyCombatThreat..'; iNearbyThreat='..iNearbyThreat) end
                                    if iNearbyFriendlyCombatThreat + iNearbyThreat > iNearbyEnemyThreat then
                                        bSuicideIntoCurACU = true
                                        bIgnoreDistanceToMidpointCheck = true
                                    end
                                end
                            end
                        end
                    end
                end
                if bSuicideIntoCurACU then
                    iCurACUDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                    if iCurACUDist <= iClosestACUDist then bIgnoreDistanceToMidpointCheck = true
                    elseif not(bIgnoreDistanceToMidpointCheck) then
                        --If we have enough combat units almost in range of the ACU then still suicide into it
                        local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
                        local toFriendlyUnitsNearACU = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat, oACU:GetPosition(), 35, 'Ally')
                        if bDebugMessages == true then LOG(sFunctionRef..': ACU is quite far from this zone midpoint, do we have significant combat threat near the ACU? is toFriendlyUnitsNearACU empty='..tostring(AiBotUtilities.IsTableEmpty(toFriendlyUnitsNearACU))) end
                        if AiBotUtilities.IsTableEmpty(toFriendlyUnitsNearACU) == false and AiBotUnitInfo.GetCombatThreatRating({ oACU }, true) < AiBotUnitInfo.GetCombatThreatRating(toFriendlyUnitsNearACU, false) then
                            bIgnoreDistanceToMidpointCheck = true
                        end
                    end
                    if bIgnoreDistanceToMidpointCheck and oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau then
                        oClosestFatboyOrACUInIslandToSuicideInto = oACU
                        bSuicideIntoFatboyOrACU = true
                        iClosestACUDist = iCurACUDist
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to suicide into enemy ACU') end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished considering if there is an ACU we should try and snipe, bSuicideIntoFatboyOrACU='..tostring(bSuicideIntoFatboyOrACU)..'; oClosestFatboyOrACUInIslandToSuicideInto='..(oClosestFatboyOrACUInIslandToSuicideInto.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestFatboyOrACUInIslandToSuicideInto) or 'nil')..'; Time='..GetGameTimeSeconds()) end
    end
    if not(oClosestFatboyOrACUInIslandToSuicideInto) and iAvailableCombatUnitThreat >= 5000 and iFriendlyBestMobileDFRange > 15 and tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] >= 1000 and AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) then
        local tEnemyFatboy = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFatboy, tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats])
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy fatboy empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyFatboy))) end
        if AiBotUtilities.IsTableEmpty(tEnemyFatboy) == false then
            local iClosestDistToMidpoint = 100000
            local iCurDist
            for iUnit, oUnit in tEnemyFatboy do
                if AiBotUnitInfo.IsUnitValid(oUnit) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Fatboy='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; land label='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition()) or 'nil')..'; LZ island ref='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; Dist to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])) end
                    --Add to skirmisher enemies
                    if NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition()) == tLZData[AiBotMap.subrefLZIslandRef] and oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                        if iCurDist < iClosestDistToMidpoint then
                            iClosestDistToMidpoint = iCurDist
                            oClosestFatboyOrACUInIslandToSuicideInto = oUnit
                        end
                    end
                end
            end
            if oClosestFatboyOrACUInIslandToSuicideInto then
                --Cycle through available DF units (if we have any)
                local tT3PlusDF = EntityCategoryFilterDown(categories.DIRECTFIRE - categories.TECH1 - categories.TECH2, tAvailableCombatUnits)
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of T3PlusDF units empty='..tostring(AiBotUtilities.IsTableEmpty(tT3PlusDF))) end
                if AiBotUtilities.IsTableEmpty(tT3PlusDF) == false then
                    local oClosestFriendlyDFUnitToFatboy = AiBotUtilities.GetNearestUnit(tT3PlusDF, oClosestFatboyOrACUInIslandToSuicideInto:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': oClosestFriendlyDFUnitToFatboy='..(oClosestFriendlyDFUnitToFatboy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestFriendlyDFUnitToFatboy) or 'nil')..'; oClosestFatboyOrACUInIslandToSuicideInto='..oClosestFatboyOrACUInIslandToSuicideInto.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestFatboyOrACUInIslandToSuicideInto)..'; Dist between them='..AiBotUtilities.GetDistanceBetweenPositions(oClosestFriendlyDFUnitToFatboy:GetPosition(), oClosestFatboyOrACUInIslandToSuicideInto:GetPosition())..'; oClosestFriendlyDFUnitToFatboy='..(oClosestFriendlyDFUnitToFatboy[AiBotUnitInfo.refiDFRange] or 'nil')) end
                    if oClosestFriendlyDFUnitToFatboy then
                        local iDistUntilDFReachesFatboy = AiBotUtilities.GetDistanceBetweenPositions(oClosestFriendlyDFUnitToFatboy:GetPosition(), oClosestFatboyOrACUInIslandToSuicideInto:GetPosition())
                        if iDistUntilDFReachesFatboy <= math.max(25 + iFriendlyBestMobileDFRange, 35 + (oClosestFriendlyDFUnitToFatboy[AiBotUnitInfo.refiDFRange] or 0)) then
                            --Much lower threshold if enemy has multiple fatboys or we dont have a big combat threat
                            if iDistUntilDFReachesFatboy <= 5 +  (oClosestFriendlyDFUnitToFatboy[AiBotUnitInfo.refiDFRange] or 0) or (iDistUntilDFReachesFatboy <= 60 and (oClosestFriendlyDFUnitToFatboy[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oClosestFriendlyDFUnitToFatboy)) >= 10000) then
                                bSuicideIntoFatboyOrACU = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Have a friendly T3 DF unit in range or almost in range of enemy fatboy so will suicide into it') end
                            elseif iAvailableCombatUnitThreat < 10000 or tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] >= 30000 then
                                --More refined check as either enemy has multiple fatboys or we have only a small level of threat so might struggle to chase down the fatboy
                                if bDebugMessages == true then LOG(sFunctionRef..': tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]='..tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]..'; oClosestFriendlyDFUnitToFatboy[AiBotUnitInfo.refiUnitMassCost]='..(oClosestFriendlyDFUnitToFatboy[AiBotUnitInfo.refiUnitMassCost] or 'nil')) end
                                if tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] >= 30000 then
                                    --If enemy has multiple fatboys then require T2 arti to be in range to consider suiciding into it
                                    if tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] <= 20 then
                                        --We have fired T2 arti recently, so is the fatboy in range of friendly T2 arti to the point of being able to shoot them? if so, then attack
                                        local tFixedT2Arti = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedT2Arti, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                        if AiBotUtilities.IsTableEmpty(tFixedT2Arti) == false then
                                            for iArti, oArti in tFixedT2Arti do
                                                if oArti:GetFractionComplete() == 1 and AiBotUtilities.GetDistanceBetweenPositions(oArti:GetPosition(), oClosestFatboyOrACUInIslandToSuicideInto:GetPosition()) <= oClosestFatboyOrACUInIslandToSuicideInto[AiBotUnitInfo.refiCombatRange] then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Fatboy is in combat range of friendly t2 arti so will attack') end
                                                    bSuicideIntoFatboyOrACU = true
                                                    break
                                                end
                                            end
                                        end
                                    end
                                elseif (oClosestFriendlyDFUnitToFatboy[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oClosestFriendlyDFUnitToFatboy)) >= 5000 and iDistUntilDFReachesFatboy - (oClosestFriendlyDFUnitToFatboy[AiBotUnitInfo.refiDFRange] or 0) <= 35 then
                                    bSuicideIntoFatboyOrACU = true
                                    if bDebugMessages == true then LOG(sFunctionRef..': Nearest unit close to being in range and is high value so will continue with suicide approach') end
                                else
                                    --Likely only 1 fatboy but our threat is low - only consider suiciding in if we have at least 5k in mass of units close to being in range of the fatboy
                                    local toUnitsCloseToBeingAbleToShootFatboy = {}
                                    for iUnit, oUnit in tT3PlusDF do
                                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFatboyOrACUInIslandToSuicideInto:GetPosition()) - (oUnit[AiBotUnitInfo.refiDFRange] or 0) <= 35 then
                                            table.insert(toUnitsCloseToBeingAbleToShootFatboy, oUnit)
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Mass cost of DF units almost able to shoot fatboy='.. AiBotUnitInfo.GetMassCostOfUnits(toUnitsCloseToBeingAbleToShootFatboy, false)) end
                                    if AiBotUnitInfo.GetMassCostOfUnits(toUnitsCloseToBeingAbleToShootFatboy, false) then
                                        bSuicideIntoFatboyOrACU = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': We have enough combat units in range to be able to target the fatboy') end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    local bRunFromEnemyAir = false
    if bDebugMessages == true then LOG(sFunctionRef..': Wondering if we want to run from enemy air, iFirebaseThreatAdjust='..iFirebaseThreatAdjust..'; tLZTeamData[AiBotMap.refiModDistancePercent]='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; tLZTeamData[AiBotMap.subrefLZMAAThreatWanted]='..tLZTeamData[AiBotMap.subrefLZMAAThreatWanted]..'; Have air control='..tostring(AiBotTeam.tAirSubteamData[ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].AiBotAirSubteam][AiBotTeam.refbHaveAirControl])..'; Enemy air to ground='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] or 'nil')) end
    if iFirebaseThreatAdjust == 0 and not(bSuicideIntoFatboyOrACU) and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.75 and tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] >= 50 and not(AiBotTeam.tAirSubteamData[ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].AiBotAirSubteam][AiBotTeam.refbHaveAirControl]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 400 then
        local iNetEnemyAirToGroundThreat = tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] - tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] * 2 - tLZTeamData[AiBotMap.subrefLZThreatAllyMAA] * 4
        local iNearbyMAA = (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0)
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                iNetEnemyAirToGroundThreat = iNetEnemyAirToGroundThreat + math.max(0, tAdjLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] - tAdjLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] * 2) - tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMAA] * 4
                iNearbyMAA = iNearbyMAA + (tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMAA] or 0)
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iNetEnemyAirToGroundThreat in adjacent zones='..iNetEnemyAirToGroundThreat) end
        if iNetEnemyAirToGroundThreat >= math.max(200, iAvailableCombatUnitThreat * 0.1) then
            bRunFromEnemyAir = true
            --If in enemy base/threatening enemy buildings then dont run
            local iNearbyEnemyBuildingValue = 0
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                local tNearbyEnemyBuildings = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure - AiBotUnitInfo.refCategoryPD, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                iNearbyEnemyBuildingValue = AiBotUnitInfo.GetMassCostOfUnits(tNearbyEnemyBuildings, true)
            end
            if iNearbyEnemyBuildingValue >= math.min(2000, iAvailableCombatUnitThreat * 0.2) then
                bRunFromEnemyAir = false
            end
        end
        --Be more cautious with experimental level land forces
        if bDebugMessages == true then LOG(sFunctionRef..': Run from a global enemy air to ground threat if relevant, tLZTeamData[AiBotMap.refiModDistancePercent]='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; iNearbyMAA='..iNearbyMAA..'; Far behind on air='..tostring(AiBotTeam.tAirSubteamData[ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir] or false)..'; Enemy air to ground='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; LZSvalue='..tLZTeamData[AiBotMap.subrefLZSValue]..'; Enemy structure mass='..tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]..'; Dist to closest friendly base='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestFriendlyBase])..'; iFriendlyBestMobileDFRange='..iFriendlyBestMobileDFRange) end
        if not(bRunFromEnemyAir) and tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.25 and iAvailableCombatUnitThreat >= 8000 and iNearbyMAA < 3000 and iAvailableCombatUnitThreat > iNearbyMAA * 5 and AiBotTeam.tAirSubteamData[ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > iAvailableCombatUnitThreat * 0.35 then
            --Check dont have enemies in our range, or enemies we are in range of, or high value friendly units, and we dont ahve a long range unit (that is likely a fatboy that can build its own MAA)
            if tLZTeamData[AiBotMap.subrefLZSValue] <= 3000 and tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] <= 3000 and AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 150 and iFriendlyBestMobileDFRange <= 90 then
                --Check for experimentals in this zone, and if we have any, if they are in range of any enemies (or about to be)
                local tLandExp = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental, tAvailableCombatUnits)
                if bDebugMessages == true then LOG(sFunctionRef..': Is friendly tLandExp empty='..tostring(AiBotUtilities.IsTableEmpty(tLandExp))) end
                if AiBotUtilities.IsTableEmpty(tLandExp) == false then
                    local bInRangeOfEnemyDFUnit = false
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                        local iEnemyDFRange = math.max(tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0, tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0)
                        for iExp, oExp in tLandExp do
                            if bDebugMessages == true then LOG(sFunctionRef..': Does the enemy have df units in range of our exp, based on enemy unit range='..tostring(AiBotConditions.CloseToEnemyUnit(oExp:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], 5, iTeam, true, nil, nil, nil, nil, nil))..'; Exp DF range='..(oExp[AiBotUnitInfo.refiDFRange] or 'nil')) end
                            if (oExp[AiBotUnitInfo.refiDFRange] or 0) > iEnemyDFRange then
                                if AiBotConditions.CloseToEnemyUnit(oExp:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], (oExp[AiBotUnitInfo.refiDFRange] or 0) + 5, iTeam, false, nil, nil, nil, nil, nil) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Exp is in range of enemy DF unit') end
                                    bInRangeOfEnemyDFUnit = true
                                    break
                                end
                            else
                                if AiBotConditions.CloseToEnemyUnit(oExp:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], 5, iTeam, true, nil, nil, nil, nil, nil) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy DF unit is in range of our experimental') end
                                    bInRangeOfEnemyDFUnit = true
                                    break
                                end
                            end
                        end
                    end
                    if not(bInRangeOfEnemyDFUnit) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Are too far from base without sufficient groundAA support so will retreat from enemy potential air threat') end
                        bRunFromEnemyAir = true
                    end
                end
            end
        end
    end
    local oNearestEnemyToFriendlyBase
    local bConsiderAttackingACU = false
    local toEnemyACUsNearZone --will set this later on
    function GetManualAttackTargetIfWantManualAttack(oUnit, oOptionalPrimaryTarget)
        if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack - start of code') end
        --Returns the unit, and returns true if should move towards it instead of a manual attack order (will want to move towards it if we are in range of a dangerous unit but we cant attack it yet)
        local oManualAttackTarget
        local bMoveTowardsTarget = false
        local oPreviousManualAttackTargetStillInRange --So can consider keeping current target if we cant see the intended target
        if oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack and AiBotUnitInfo.IsUnitValid(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]) and AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]:GetPosition(), oUnit:GetPosition()) - (oUnit[AiBotUnitInfo.refiDFRange] or 0) <= 0 then
            oPreviousManualAttackTargetStillInRange = oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]
        end
        if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack - Considering if want oUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to pick a target for a manual attack, unit DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 0)..'; Is table of nearby enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; Can we see nearest enemy to midpoint='..tostring(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oNearestEnemyToFriendlyBase))..'; Dist to nearest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition())..'; Is unit shot blocked='..tostring(oUnit[AiBotUnitInfo.refbLastShotBlocked] or false)..'; refiTimeOfLastUnblockedShot='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeOfLastUnblockedShot] or 0)..'; Unit DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; Mass cost='..(oUnit[AiBotUnitInfo.refiUnitMassCost] or 'nil')..'; bConsiderAttackingACU='..tostring(bConsiderAttackingACU)) end

        --Monkeylord, GC and Ythotha - prioritise enemy ACUs that we are clsoe to being in range of, unless the ACU is very powerful
        if (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 15000 and oUnit[AiBotUnitInfo.refiCombatRange] <= 64 and (oUnit[AiBotUnitInfo.refiDFRange] <= 50 or oUnit.UnitId == 'url0402') and oUnit:GetMaxHealth() >= 40000 then --IF CHANGING HERE THEN CHANGE BELOW AS WELL
            if not(oClosestFatboyOrACUInIslandToSuicideInto) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                --Consider suiciding into enemy ACU with experimentals only
                local iClosestACU
                if bConsiderAttackingACU and AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone) == false then iClosestACU = oUnit[AiBotUnitInfo.refiDFRange] + math.min(30, math.max(20, oUnit[AiBotUnitInfo.refiDFRange]))
                else iClosestACU = oUnit[AiBotUnitInfo.refiDFRange] + 14
                end
                local iCurDist
                local oClosestACUNearUnit
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
                    for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                        if AiBotUnitInfo.IsUnitValid(oACU) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition())
                            if bDebugMessages == true then LOG(sFunctionRef..': Dist to ACU owned by '..oACU:GetAIBrain().Nickname..'='..iCurDist) end
                            if iCurDist < iClosestACU and not(AiBotUnitInfo.IsUnitUnderwater(oACU)) and not(oACU:IsUnitState('Attached')) then
                                --Check this isnt a deadly ACU (i.e. 10k+ of mass upgrades)
                                if (oACU[AiBotUnitInfo.refiDFMassThreatOverride] or 0) < 10000 and not(oACU[AiBotUnitInfo.refbUnitIsCloaked]) then
                                    --Check on same plateau as us
                                    local iACUPlateau, iACUZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oACU:GetPosition())
                                    if iACUPlateau == iPlateau then
                                        iClosestACU = iCurDist
                                        oClosestACUNearUnit = oACU
                                    end
                                end
                            end
                        end
                    end
                end
                if oClosestACUNearUnit then
                    if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack Will launch micro logic to suicide into enemy ACU') end
                    --Suicide into this ACU as special micro logic (so dont get given new orders)
                    ForkThread(AiBotMicro.SuicideExperimentalIntoEnemyACU, oUnit, oClosestACUNearUnit, iClosestACU)
                    return oClosestACUNearUnit, true
                end
            end
        end

        --ACU snipe target that are in range of
        if bSuicideIntoFatboyOrACU and oClosestFatboyOrACUInIslandToSuicideInto and ((oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 or ((oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat, oUnit.UnitId))) then
            --Are we almost 5 within range of the ACU/fatboy target, and it is an ACU (as for a fatboy t might be good to get close so we are under the shield)? if so then have as manual attack target
            if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack Dist to oClosestFatboyOrACUInIslandToSuicideInto='..AiBotUtilities.GetDistanceBetweenPositions(oClosestFatboyOrACUInIslandToSuicideInto:GetPosition(), oUnit:GetPosition())..'; Combat range='..oUnit[AiBotUnitInfo.refiCombatRange]) end
            if AiBotUtilities.GetDistanceBetweenPositions(oClosestFatboyOrACUInIslandToSuicideInto:GetPosition(), oUnit:GetPosition()) < (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) - 5 then
                return oClosestFatboyOrACUInIslandToSuicideInto, false
            end
        end

        --Note - in some cases the nearest enemy unit to the midpoint may be much further away than our units, if our units are from an adjacent zone or have just entered the cur zone, therefore if dealing with an experimental friendly unit want to do more detailed check of all nearby enemy units
        if bDebugMessages == true then LOG(sFunctionRef..': Is reftoNearestDFEnemies empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; Can we see oOptionalPrimaryTarget or oNearestEnemyToFriendlyBase='..tostring(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), (oOptionalPrimaryTarget or oNearestEnemyToFriendlyBase)))) end
        if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then --and (EntityCategoryContains(categories.EXPERIMENTAL + categories.TECH3, oUnit.UnitId) or AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition()) < (oUnit[AiBotUnitInfo.refiDFRange] or 0)) then
            --Nearest enemy is inside our range, is there another high value target that we should target?
            if EntityCategoryContains(categories.TECH3 + categories.EXPERIMENTAL, oUnit.UnitId) then

                local iCategoryToSearch = AiBotUnitInfo.refCategoryLandExperimental + categories.COMMAND + AiBotUnitInfo.refCategoryDestroyer --I.e. salems on land should be attacked if we are in range of them
                --Ythotha - also consider enemy T3 land combat to try and avoid it constantly changing targets

                --Below is if wanted to generalise, however concerned about riks of overkill
                --[[
                local iCategoryToSearch = AiBotUnitInfo.refCategoryMobileDFLand + AiBotUnitInfo.refCategoryPD
                local iUnitTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnit)
                if iUnitTechLevel == 2 then
                    iCategoryToSearch = iCategoryToSearch - categories.TECH1
                elseif iUnitTechLevel == 3 then
                    iCategoryToSearch = iCategoryToSearch - categories.TECH1 - categories.TECH2
                elseif iUnitTechLevel == 4 then
                    iCategoryToSearch = iCategoryToSearch * categories.EXPERIMENTAL
                end--]]
                local tNearbyEnemiesOfCategory = EntityCategoryFilterDown(iCategoryToSearch, tLZTeamData[AiBotMap.reftoNearestDFEnemies])
                local iClosestEnemyOfCategory = 10000
                local iCurDistOfCategory
                local iCurHealth
                local iLowestHealth = 10000000
                local oEnemyWeAreInRangeOf
                local iClosestEnemyWeAreInRangeOf = 100000
                if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack - Is tNearbyEnemiesOfCategory empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyEnemiesOfCategory))) end
                if AiBotUtilities.IsTableEmpty(tNearbyEnemiesOfCategory) == false then
                    for iEnemy, oEnemy in tNearbyEnemiesOfCategory do
                        if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack - Considering oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; Is this the same as nearest enemy to midpoint='..tostring(oEnemy == oNearestEnemyToFriendlyBase)..'; Fraction complete='..oEnemy:GetFractionComplete()) end
                        if oEnemy:GetFractionComplete() == 1 then
                            iCurHealth = oEnemy:GetHealth()
                            if oUnit.MyShield.GetHealth then
                                iCurHealth = iCurHealth + oUnit.MyShield:GetHealth()
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack -  Considering if we want to manually attack enemy unit '..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; iCurHelath='..iCurHealth..'; iLowestHealth='..iLowestHealth..'; Can see unit='..tostring(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemy))..'; Distance ot unit='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition())..'; iCurHealth < iLowestHealth ='..tostring(iCurHealth < iLowestHealth )..'; Both conditions='..tostring(iCurHealth < iLowestHealth and AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemy, true))) end
                            --if iCurHealth < iLowestHealth and AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemy) then
                            iCurDistOfCategory = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition())
                            iClosestEnemyOfCategory = math.min(iClosestEnemyOfCategory, iCurDistOfCategory)
                            if iCurDistOfCategory <= oUnit[AiBotUnitInfo.refiDFRange] + 2 and iCurHealth < iLowestHealth and AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemy) then
                                iLowestHealth = iCurHealth
                                oManualAttackTarget = oEnemy
                                if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack - Setting manual attack target to this enemy') end
                            elseif iCurDistOfCategory <= (oEnemy[AiBotUnitInfo.refiDFRange] or 0) and iCurDistOfCategory < iClosestEnemyWeAreInRangeOf and (oEnemy[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oEnemy)) > 2000 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy unit can attack us and has a notable mass cost so will move towards it, time since last weapon event='..(GetGameTimeSeconds() - (oEnemy[AiBotUnitInfo.refiLastWeaponEvent] or 0))) end
                                oEnemyWeAreInRangeOf = oEnemy
                                iClosestEnemyWeAreInRangeOf = iCurDistOfCategory
                            end
                            --elseif bDebugMessages == true then LOG(sFunctionRef..': Enemy is too high health or we cant see it')
                            --end
                        end
                    end
                end

                if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack -  Finished searhcing but before overrides for oManualAttackTarget='..(oManualAttackTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oManualAttackTarget) or 'nil')) end
                if not(oManualAttackTarget) and oEnemyWeAreInRangeOf then oManualAttackTarget = oEnemyWeAreInRangeOf bMoveTowardsTarget = true end
                --non-kiting experimental specific (i.e. GC, Ythotha, Megalith) - if are in a dif zone to the assigned zone then do getunitsaroundpoint to check no enemy experimentals or ACUs almost within range
                if not(oManualAttackTarget) then
                    if not(oUnit[AiBotUnitInfo.refbCanKite]) and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                        local tNearbyEnemyExperimentals = oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandExperimental + categories.COMMAND, oUnit:GetPosition(), oUnit[AiBotUnitInfo.refiDFRange] + 2, 'Enemy')
                        if AiBotUtilities.IsTableEmpty(tNearbyEnemyExperimentals) == false then
                            for iEnemy, oEnemy in tNearbyEnemyExperimentals do
                                if oEnemy:GetFractionComplete() == 1 then
                                    iCurHealth = oEnemy:GetHealth()
                                    if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack exp backup search -  Considering if we want to manually attack enemy unit '..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; iCurHelath='..iCurHealth..'; iLowestHealth='..iLowestHealth..'; Can see unit='..tostring(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemy))..'; Distance ot unit='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition())..'; iCurHealth < iLowestHealth ='..tostring(iCurHealth < iLowestHealth )..'; Both conditions='..tostring(iCurHealth < iLowestHealth and AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemy, true))) end
                                    if iCurHealth < iLowestHealth and AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemy) then
                                        iCurDistOfCategory = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition())
                                        iClosestEnemyOfCategory = math.min(iClosestEnemyOfCategory, iCurDistOfCategory)
                                        if iCurDistOfCategory <= oUnit[AiBotUnitInfo.refiDFRange] + 2 then
                                            iLowestHealth = iCurHealth
                                            oManualAttackTarget = oEnemy
                                            bMoveTowardsTarget = false
                                            if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack exp backup search - Setting manual attack target to this enemy') end
                                        elseif bDebugMessages == true then LOG(sFunctionRef..': exp backup Enemy is too far away')
                                        end
                                    elseif bDebugMessages == true then LOG(sFunctionRef..': exp backup Enemy is too high health or we cant see it')
                                    end
                                end
                            end
                        end
                    end

                    --Consider targeting T3 land for ythotha - will do by doing attack move
                    if not(oManualAttackTarget) and iClosestEnemyOfCategory >= math.max(oUnit[AiBotUnitInfo.refiDFRange] + 10, 70) and EntityCategoryContains(AiBotUnitInfo.refCategoryYthotha, oUnit.UnitId) then
                        --If we alreayd have a target that is in range then stick with this if we are near it
                        local iCurAngleDif
                        local iClosestAngleDif = 1000
                        local iYthothaAngle = AiBotUnitInfo.GetUnitFacingAngle(oUnit)

                        local oExistingAttackTarget = oPreviousManualAttackTargetStillInRange or oUnit[AiBotOrders.reftiLastOrders][AiBotOrders.refiOrderCount][AiBotOrders.subrefoOrderUnitTarget]
                        if AiBotUnitInfo.IsUnitValid(oExistingAttackTarget) and AiBotUtilities.GetDistanceBetweenPositions(oExistingAttackTarget:GetPosition(), oUnit:GetPosition()) <= oUnit[AiBotUnitInfo.refiDFRange] + 1 then
                            --Record closest angle dif and reduce by 15 so we wont switch targets to another unit if it wouldnt be that much of an improvement
                            iClosestAngleDif = math.max(0, AiBotUtilities.GetAngleDifference(iYthothaAngle, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oExistingAttackTarget:GetPosition())) - 15)
                        end
                        if iClosestAngleDif > 30 then --i.e. 45+ angle dif since we reduce it by 15 in the above step
                            local tOtherPriorityTargets = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMobileDFLand * categories.TECH3 - AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryT3PD, tLZTeamData[AiBotMap.reftoNearestDFEnemies])
                            if bDebugMessages == true then LOG(sFunctionRef..': Is tOtherPriorityTargets empty='..tostring(AiBotUtilities.IsTableEmpty(  tOtherPriorityTargets))) end
                            if AiBotUtilities.IsTableEmpty(  tOtherPriorityTargets) == false then
                                for iEnemy, oEnemy in tOtherPriorityTargets do
                                    if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack - Considering ythotha t3 oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; Is this the same as nearest enemy to midpoint='..tostring(oEnemy == oNearestEnemyToFriendlyBase)..'; Fraction complete='..oEnemy:GetFractionComplete()..'; Unit max health='..oEnemy:GetMaxHealth()..'; Can see unit='..tostring(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemy))..'; Dist to us='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEnemy:GetPosition())..'; Angle dif='..AiBotUtilities.GetAngleDifference(iYthothaAngle, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemy:GetPosition()))..'; Closest dif='..iClosestAngleDif) end
                                    if oEnemy:GetFractionComplete() == 1 then
                                        if oEnemy:GetMaxHealth() >= 2000 and AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemy) then
                                            iCurDistOfCategory = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition())
                                            iClosestEnemyOfCategory = math.min(iClosestEnemyOfCategory, iCurDistOfCategory)
                                            if iCurDistOfCategory <= oUnit[AiBotUnitInfo.refiDFRange] then
                                                iCurAngleDif = AiBotUtilities.GetAngleDifference(iYthothaAngle, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemy:GetPosition()))
                                                if iCurAngleDif < iClosestAngleDif then
                                                    iClosestAngleDif = iCurAngleDif
                                                    oManualAttackTarget = oEnemy
                                                    bMoveTowardsTarget = false
                                                    if bDebugMessages == true then LOG(sFunctionRef..': GetManualAttackTargetIfWantManualAttack - Setting ythotha manual attack target to this enemy') end
                                                end

                                            elseif bDebugMessages == true then LOG(sFunctionRef..': Enemy is too far away for ythotha to target')
                                            end
                                        end
                                    end
                                end
                            end
                        elseif bDebugMessages == true then LOG(sFunctionRef..': Will stick with existing manual attack target')
                        end
                    end
                end
                if oManualAttackTarget then
                    --Is nearest enemy to midpoitn a better target?
                    local aiBrain = oUnit:GetAIBrain()
                    if not(oManualAttackTarget == oNearestEnemyToFriendlyBase) and EntityCategoryContains(iCategoryToSearch, oNearestEnemyToFriendlyBase.UnitId) and oNearestEnemyToFriendlyBase:GetFractionComplete() == 1 then
                        if oNearestEnemyToFriendlyBase:GetHealth() < iLowestHealth and AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition()) <= oUnit[AiBotUnitInfo.refiDFRange] + 2 then
                            if AiBotUnitInfo.CanSeeUnit(aiBrain, oNearestEnemyToFriendlyBase) then
                                oManualAttackTarget = oNearestEnemyToFriendlyBase
                                bMoveTowardsTarget = false
                            elseif oPreviousManualAttackTargetStillInRange then
                                oManualAttackTarget = oPreviousManualAttackTargetStillInRange
                                bMoveTowardsTarget = false
                            else
                                oManualAttackTarget = nil
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..':GetManualAttackTargetIfWantManualAttack - Finished checking if nearest enemy to midpoint is better target, oManualAttackTarget='..(oManualAttackTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oManualAttackTarget) or 'nil')..'; Nearest enemy to midpoint health='.. oNearestEnemyToFriendlyBase:GetHealth()) end
                    end
                    if oManualAttackTarget then
                        --Look for shields that are covering this
                        local tShieldsCoveringTarget = AiBotLogic.IsTargetUnderShield(aiBrain, oManualAttackTarget, 0, false, false, false, false, true)
                        if AiBotUtilities.IsTableEmpty(tShieldsCoveringTarget) == false then
                            local iLowestHealthShield = 1000000
                            local oLowestHealthShield, iCurShieldHealth, iMaxShieldHealth

                            for iShield, oShield in tShieldsCoveringTarget do
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering oShield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; Is valid='..tostring(AiBotUnitInfo.IsUnitValid(oShield))..'; Can see unit='..tostring( AiBotUnitInfo.CanSeeUnit(aiBrain, oShield))) end
                                if AiBotUnitInfo.IsUnitValid(oShield) and AiBotUnitInfo.CanSeeUnit(aiBrain, oShield) then
                                    iCurShieldHealth, iMaxShieldHealth = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, false)
                                    if bDebugMessages == true then LOG(sFunctionRef..': iCurShieldHealth='..iCurShieldHealth..'; iMaxShieldHealth='..iMaxShieldHealth) end
                                    if iMaxShieldHealth >= 5000 and iCurShieldHealth < iLowestHealthShield and not(AiBotUnitInfo.IsUnitUnderwater(oShield)) then
                                        oLowestHealthShield = oShield
                                        iLowestHealthShield = iCurShieldHealth
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': oLowestHealthShield='..(oLowestHealthShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oLowestHealthShield) or 'nil')) end
                            if oLowestHealthShield then
                                --Switch target to the shield
                                oManualAttackTarget = oLowestHealthShield
                                if AiBotUtilities.GetDistanceBetweenPositions(oLowestHealthShield:GetPosition(), oUnit:GetPosition()) > oUnit[AiBotUnitInfo.refiDFRange] + 4 then
                                    bMoveTowardsTarget = true
                                end
                            end
                        end
                    elseif oPreviousManualAttackTargetStillInRange then
                        oManualAttackTarget = oPreviousManualAttackTargetStillInRange
                    end
                end
            end
        end
        if not(oManualAttackTarget) and iAvailableCombatUnitThreat <= 120 and oUnit[AiBotUnitInfo.refiUnitMassCost] <= 60 and oNearestEnemyToFriendlyBase:GetHealth() >= 300 and ((oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] or 0) == 0 or oNearestEnemyToFriendlyBase:GetFractionComplete() < 0.8) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false and not(EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryRadar + categories.VOLATILE, oNearestEnemyToFriendlyBase.UnitId)) then
            --if nearest enemy has lots of health consider vulnerable nearby targets such as engineers and radar (e.g. one scenario to avoid is a LAB attack-moving at a land factory, when there is an engineer building the factory behind it)
            local tPotentiallyVulnerableEnemyUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryRadar + AiBotUnitInfo.refCategoryEngineer + categories.VOLATILE, tLZTeamData[AiBotMap.subrefTEnemyUnits])
            if bDebugMessages == true then LOG(sFunctionRef..': Considering vulnerable units as have low threat, is tPotentiallyVulnerableEnemyUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentiallyVulnerableEnemyUnits))) end
            local iClosestDist = 40
            if AiBotUtilities.IsTableEmpty(tPotentiallyVulnerableEnemyUnits) == false then
                local iCurDist
                for iEnemyUnit, oEnemyUnit in tPotentiallyVulnerableEnemyUnits do
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemyUnit:GetPosition(), oUnit:GetPosition())
                    if iCurDist < iClosestDist then
                        oManualAttackTarget = oEnemyUnit
                        iClosestDist = iCurDist
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have engineer or radar or volatile unit to target with weak DF unit such as a lab, oManualAttackTarget='..(oManualAttackTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oManualAttackTarget) or 'nil')) end
                --If closest unit is a unit under construction then a player would recognise there will be a nearby engineer even if we havent had intel of it yet
            end
            if not(oManualAttackTarget) and oNearestEnemyToFriendlyBase:GetFractionComplete() < 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oNearestEnemyToFriendlyBase.UnitId) then
                local tNearbyEngineers = oNearestEnemyToFriendlyBase:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryEngineer, oNearestEnemyToFriendlyBase:GetPosition(), 15, 'Ally')
                if bDebugMessages == true then LOG(sFunctionRef..': Is tNearbyEngineers empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyEngineers))) end
                if AiBotUtilities.IsTableEmpty(tNearbyEngineers) == false then
                    oManualAttackTarget = AiBotUtilities.GetNearestUnit(tNearbyEngineers, oUnit:GetPosition())
                end
            end

            if oManualAttackTarget then
                if iClosestDist > oUnit[AiBotUnitInfo.refiDFRange] or not(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oUnit, false)) then
                    bMoveTowardsTarget = true
                end
            end
        end
        --Blocked longer ranged non-exp but still valuable DF units (since exp already run more detailed logic above I think) - consider manual target on dangerous enemy in range of us; example that prompted this was salems ignoring enemy SACUs (nearst non-combat unit had cliff blockign shots, salems wanted to advance to enemy nearby exp that wasnt yet in range, allowing sacus to get free kill)
        if not(oManualAttackTarget) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 35 and (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) < 15000 and oUnit[AiBotUnitInfo.refiUnitMassCost] >= 400 then
            if bDebugMessages == true then LOG(sFunctionRef..': Longer ranged non-Exp DF unit - considering if it is in range of an enemy unit, in which case consider manually attacking that enemy unit') end
            local iDistToEnemy
            if AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) then
                iDistToEnemy = AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition())
                if bDebugMessages == true then LOG(sFunctionRef..': Considering refoClosestEnemyFromLastCloseToEnemyUnitCheck, iDistToEnemy='..iDistToEnemy) end
                if ((iDistToEnemy < oUnit[AiBotUnitInfo.refiCombatRange] - 10) or (iDistToEnemy < oUnit[AiBotUnitInfo.refiCombatRange] and iDistToEnemy <= 2 + (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] or 0))) and oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] > 0 and not(AiBotLogic.IsShotBlocked(oUnit, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck], false, nil)) then
                    oManualAttackTarget = oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]
                end
            end
            if not(oManualAttackTarget) and oNearestEnemyToFriendlyBase and not(oNearestEnemyToFriendlyBase == oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) then
                iDistToEnemy = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition())
                if bDebugMessages == true then LOG(sFunctionRef..': Considering oNearestEnemyToFriendlyBase, iDistToEnemy='..iDistToEnemy) end
                if ((iDistToEnemy < oUnit[AiBotUnitInfo.refiCombatRange] - 10) or (iDistToEnemy < oUnit[AiBotUnitInfo.refiCombatRange] and iDistToEnemy <= 2 + (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] or 0))) and oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] > 0 and not(AiBotLogic.IsShotBlocked(oUnit, oNearestEnemyToFriendlyBase, false, nil)) then
                    oManualAttackTarget = oNearestEnemyToFriendlyBase
                end
                if bDebugMessages == true then LOG(sFunctionRef..': oManualAttackTarget after check='..(oManualAttackTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oManualAttackTarget) or 'nil')) end
            end
        end
        --Cant see unit and its mobile and not under construction - move towards target
        if bDebugMessages == true then
            if oManualAttackTarget then
                LOG(sFunctionRef..': Extra check to make sure we can see oManualAttackTarget if we have it, before visibility check oManualAttackTarget='..(oManualAttackTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oManualAttackTarget) or 'nil')..'; CanSeeUnit='..tostring(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oManualAttackTarget, false))..'; Fraction complete='..oManualAttackTarget:GetFractionComplete()..'; is oManualAttackTarget mobile='..tostring(EntityCategoryContains(categories.MOBILE, oManualAttackTarget.UnitId))..'; bMoveTowardsTarget='..tostring(bMoveTowardsTarget))
            else
                LOG(sFunctionRef..': Dont have oManualAttackTarget')
            end
        end
        if oManualAttackTarget and not(bMoveTowardsTarget) and EntityCategoryContains(categories.MOBILE, oManualAttackTarget.UnitId) and not(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oManualAttackTarget, false)) and oManualAttackTarget:GetFractionComplete() == 1 and (not(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack) or not(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget] == oManualAttackTarget)) then
            if bDebugMessages == true then LOG(sFunctionRef..': We cant see the target we want to manually attack so will flag we want to move towards target') end
            bMoveTowardsTarget = true
        end
        return oManualAttackTarget, bMoveTowardsTarget
    end

    if tLZTeamData[AiBotMap.subreftiLandZoneTargetedByOurCombat] then RecordDFLandZoneTarget(tLZTeamData, iPlateau, iLandZone, iTeam, nil) end
    if tLZTeamData[AiBotMap.subreftiWaterZoneTargetedByOurSurfaceCombat] then AiBotNavy.RecordWaterZoneTarget(tLZTeamData, iLandZone, iTeam, false, nil) end
    if tLZTeamData[AiBotMap.subreftiWaterZoneTargetedByOurSubmersibleCombat] then AiBotNavy.RecordWaterZoneTarget(tLZTeamData, iLandZone, iTeam, true, nil) end

    local bGivenCombatUnitsOrders = false

    if bDebugMessages == true then LOG(sFunctionRef..': iFirebaseThreatAdjust='..iFirebaseThreatAdjust..'; bRunFromFirebase='..tostring(bRunFromFirebase)..'; tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]='..reprs(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange])..'; subrefiNearbyEnemyLongRangeDFThreat='..tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]..'; Enemies in adj wZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ])..'; iFirebaseCloseCombatThreat='..iFirebaseCloseCombatThreat..'; bRunFromEnemyAir='..tostring(bRunFromEnemyAir)..'; bSuicideIntoFatboyOrACU='..tostring(bSuicideIntoFatboyOrACU)) end


    --Consider retreating if dangerous enemy gunship force that our MAA are retreating from, and no enemy buildings to threaten, or friendly buildings to defend
    if not(oClosestFatboyOrACUInIslandToSuicideInto) and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.5 and tLZTeamData[AiBotMap.subrefLZTimeMAARetreatedFromGunships] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.subrefLZTimeMAARetreatedFromGunships] <= math.max(20, iTicksPerLandCycle * 0.3) and tLZTeamData[AiBotMap.subrefLZSValue] <= 1000 and not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) and (tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) == 0 then
        --Retreat all units in this zone, unless the unit is unable to kite and has enemies in its range
        bRunFromEnemyAir = true
        if bDebugMessages == true then LOG(sFunctionRef..': Will retreat due to recent gunship threat and nothing significant to defend or attack, unless we have units unable to kite that have enemies in their range') end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': bRunFromEnemyAir before checking if in range of enemy units='..tostring(bRunFromEnemyAir)) end
    if bRunFromEnemyAir then
        --Check if we want to cancel the run order e.g. if in range of enemy units                
        local bHaveNonKitingUnitsInCombat = false
        local toEnemiesToConsider
        function AddEnemiesToConsider(tEnemies)
            if AiBotUtilities.IsTableEmpty(tEnemies) == false then
                if not(toEnemiesToConsider) then toEnemiesToConsider = {} end
                for iEnemy, oEnemy in tLZTeamData[AiBotMap.subrefTEnemyUnits] do
                    if not(oEnemy.Dead) and (oEnemy[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oEnemy)) >= 30 then
                        table.insert(toEnemiesToConsider, oEnemy)
                    end
                end
            end
        end
        for iUnit, oUnit in tAvailableCombatUnits do
            if oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone and ProceedWithUnitOrder(oUnit) then
                if not(oUnit[AiBotUnitInfo.refbCanKite]) then
                    if not(toEnemiesToConsider) then
                        AddEnemiesToConsider(tLZTeamData[AiBotMap.subrefTEnemyUnits])
                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                AddEnemiesToConsider(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits])
                            end
                        end
                    end
                    --                                                                                                  CloseToEnemyUnit(tStartPosition, tUnitsToCheck,             iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure, bIncludeEnemyAntiNavyRange, bIncludeEnemyIndirectRangeIfNoDFRange, iIndirectDistThresholdOverride)
                    if toEnemiesToConsider and AiBotUtilities.IsTableEmpty(toEnemiesToConsider) == false and AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), toEnemiesToConsider, 1,              iTeam, true,                oUnit[AiBotUnitInfo.refiCombatRange], nil,                        oUnit                                   ,       nil,                            false,                      true,                                      0 ) then
                        bHaveNonKitingUnitsInCombat = true
                        break
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bHaveNonKitingUnitsInCombat='..tostring(bHaveNonKitingUnitsInCombat)) end
        if bHaveNonKitingUnitsInCombat then bRunFromEnemyAir = false end
        --[[if not(bHaveNonKitingUnitsInCombat) then
            for iUnit, oUnit in tAvailableCombatUnits do
                if oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone and ProceedWithUnitOrder(oUnit) then
                    oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                    ForkThread(BackupUnitTowardsRallyIfAvailable, oUnit, tRallyPoint, tLZData[AiBotMap.subrefLZIslandRef],'GunShR'..iLandZone)
                end
            end
        end--]]
        if bRunFromEnemyAir then
            bConsiderEnemiesInAtLeastOneAdjacentZone = false
        end
    end


    if not(bGivenCombatUnitsOrders) then

        --If we have a fatboy in our available combat units, then do getunitsaroundpoint to check for signficant threats that might not be in an adjacent zone, and then add them as direct fire units against this zone so they get incorporated into checks for nearby enemies
        local iVisibleLandCombatMassInFatboyRange = 0
        if iFriendlyBestMobileDFRange >= 90 then
            --Get fatboy closest to enemy base
            local tFriendlyFatboys = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFatboy, tAvailableCombatUnits)
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of friendly fatboys empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyFatboys))) end
            if AiBotUtilities.IsTableEmpty(tFriendlyFatboys) == false then
                local oClosestFatboyToEnemy
                if not(tFriendlyFatboys[2]) then
                    oClosestFatboyToEnemy = tFriendlyFatboys[1]
                else
                    oClosestFatboyToEnemy = AiBotUtilities.GetNearestUnit(tFriendlyFatboys, tLZTeamData[AiBotMap.reftClosestEnemyBase])
                end
                if bDebugMessages == true then LOG(sFunctionRef..': oClosestFatboyToEnemy='..oClosestFatboyToEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestFatboyToEnemy)) end
                if oClosestFatboyToEnemy then
                    local tAllDangerousCombatNearFatboy = oClosestFatboyToEnemy:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryIndirectT3 + AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryDestroyer + AiBotUnitInfo.refCategoryBattleship + AiBotUnitInfo.refCategoryBattlecruiser -AiBotUnitInfo.refCategoryLandScout, oClosestFatboyToEnemy:GetPosition(), (oClosestFatboyToEnemy[AiBotUnitInfo.refiCombatRange] or 0), 'Enemy')
                    if bDebugMessages == true then LOG(sFunctionRef..': is tAllDangerousCombatNearFatboy empty='..tostring(AiBotUtilities.IsTableEmpty(tAllDangerousCombatNearFatboy))..'; Fatboy range='..(oClosestFatboyToEnemy[AiBotUnitInfo.refiDFRange] or 0)) end
                    if AiBotUtilities.IsTableEmpty(tAllDangerousCombatNearFatboy) == false then
                        iVisibleLandCombatMassInFatboyRange = AiBotUnitInfo.GetMassCostOfUnits(tAllDangerousCombatNearFatboy, true)
                        local tbAdjacentLZ = {}
                        tUnitsNearFatboyInFurtherAwayZones = {}
                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            tbAdjacentLZ[iAdjLZ] = true
                        end
                        tbAdjacentLZ[iLandZone] = true
                        for iEnemy, oEnemy in tAllDangerousCombatNearFatboy do
                            if bDebugMessages == true and AiBotUnitInfo.IsUnitValid(oEnemy) then LOG(sFunctionRef..': Have dangerous enemy '..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..' owned by '..oEnemy:GetAIBrain().Nickname..'; Assigned plateau and LZ='..repru(oEnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam])..'; Adjacent LZs='..repru(tbAdjacentLZ)..'; Assigned WZ='..(oEnemy[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] or 'nil')..'; Dist from this enemy to closest fatboy='..AiBotUtilities.GetDistanceBetweenPositions(oClosestFatboyToEnemy:GetPosition(), oEnemy:GetPosition())..'; Fatboy range='..(oClosestFatboyToEnemy[AiBotUnitInfo.refiDFRange] or 'nil')) end
                            if not(tbAdjacentLZ[oEnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]]) or not(oEnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau) then
                                if AiBotUnitInfo.IsUnitValid(oEnemy) then
                                    if oEnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] then tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] = true
                                    elseif oEnemy[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] then tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] = true
                                    end
                                    table.insert(tLZTeamData[AiBotMap.reftoNearestDFEnemies], oEnemy)
                                    table.insert(tUnitsNearFatboyInFurtherAwayZones, oEnemy)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding enemy to table of nearest DF units and to units near fatboy in further away zones') end
                                end
                                --Sometimes the nearest enemy to our midpoint might be a dif unit, but this unit might still be closer to the fatboy, so want to include if its in range of the fatboy to be safe
                            elseif not(oEnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) and oEnemy[AiBotUnitInfo.refiUnitMassCost] >= 500 then
                                if AiBotUnitInfo.IsUnitValid(oEnemy) then
                                    table.insert(tLZTeamData[AiBotMap.reftoNearestDFEnemies], oEnemy)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Unit in adj zone, will add to table of nearest DF enemies to be safe in case it isnt already recorded (will lead to some doublecounting') end
                                end
                            end
                        end
                    end
                end
            end
        end

        --Only consider if we have a fairly large force for our tech level; in which case will only send a small part of our army to deal with the enemy
        if iAvailableCombatUnitThreat >= 300 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] then
            --Consider this zone first (no point ignoring enemies in adj zone if wont be ignoring in this zone); no cap as we will just send a smaller (but still large enough) force to deal with enemy threats if ignoring
            if iAvailableCombatUnitThreat >= tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 10 and iAvailableCombatUnitThreat >= (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] + tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]) * 6 then
                bIgnoreEnemiesInThisZone = true
                --Record which units in adjacent zones we should ignore
                bConsiderEnemiesInAtLeastOneAdjacentZone = false
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                    if (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) <= 15000 and iAvailableCombatUnitThreat >= (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 10 and iAvailableCombatUnitThreat >= (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] + (tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0)) * 6 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Ignoring iAdjLZ='..iAdjLZ..' due to it having too low a threat, enemy combat total for adj LZ='..(tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..'; iAvailableCombatUnitThreat='..(iAvailableCombatUnitThreat or 'nil')) end
                        tbAdjacentZoneEnemiesToIgnoreByZone[iAdjLZ] = true
                    else
                        bConsiderEnemiesInAtLeastOneAdjacentZone = true
                    end
                end
            end
        end

        --If enemy has units in this or adjacent LZ, then decide what to do
        if (tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) and (bSuicideIntoFatboyOrACU or not(bRunFromFirebase) and not(bRunFromEnemyAir)) then
            local tFriendlyNearbyExperimentals --used lateron if we want to assess if there is negligible neemy threat
            local iDFRangeOverrideForScenario1
            --Cloaked units - flag we want spy plane if we have any land experimentals
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if have nearby cloaked enemy units if we have a large threat, iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; Is table of cloaked enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCloakedEnemyUnits]))..'; iVisibleLandCombatMassInFatboyRange='..iVisibleLandCombatMassInFatboyRange) end
            if iAvailableCombatUnitThreat >= 10000 and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCloakedEnemyUnits]) then
                local tFriendlyLandExperimentals = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental, tAvailableCombatUnits)
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of friendly land experimentals empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyLandExperimentals))) end
                if AiBotUtilities.IsTableEmpty(tFriendlyLandExperimentals) == false then
                    local toExperimentalsNearCloakedUnit = {}
                    for iCloaked, oCloaked in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCloakedEnemyUnits] do
                        for iExperimental, oExperimental in tFriendlyLandExperimentals do
                            if bDebugMessages == true then LOG(sFunctionRef..': oExperimental='..oExperimental.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oExperimental)..'; oCloaked='..oCloaked.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oCloaked)..'; Dist from experimental to cloaked='..AiBotUtilities.GetDistanceBetweenPositions(oExperimental:GetPosition(), oCloaked:GetPosition())) end
                            if AiBotUtilities.GetDistanceBetweenPositions(oExperimental:GetPosition(), oCloaked:GetPosition()) <= 80 then
                                table.insert(toExperimentalsNearCloakedUnit, oExperimental)
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is toExperimentalsNearCloakedUnit empty='..tostring(AiBotUtilities.IsTableEmpty(toExperimentalsNearCloakedUnit))) end
                    if AiBotUtilities.IsTableEmpty(toExperimentalsNearCloakedUnit) == false then
                        for iUnit, oUnit in toExperimentalsNearCloakedUnit do
                            AiBotAir.AddUnitWantingPriorityScout(oUnit)
                        end
                    end
                end
            end

            local bEnemyHasNoDFUnits
            if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] then bEnemyHasNoDFUnits = false
            else
                bEnemyHasNoDFUnits = AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies])
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Checking for nearest enemy to midpoint, bEnemyHasNoDFUnits='..tostring(bEnemyHasNoDFUnits)..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]))) end

            toEnemyACUsNearZone = EntityCategoryFilterDown(categories.COMMAND, tLZTeamData[AiBotMap.reftoNearestDFEnemies])
            local oNearestEnemyStructureToMidpoint
            local iClosestDist = 100000
            local iClosestStructureDist = 100000
            local iCurDist
            local iEnemyBestDFRange = math.max(iEnemyBestMobileDFRange, iEnemyBestStructureDFRange)
            local bNotCloseToAdjacentPD = false
            --If enemy DF structures are in an adjacent zone then only include their range for this decision if they are near enough
            if (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0) < iEnemyBestStructureDFRange and iEnemyBestStructureDFRange > iEnemyBestMobileDFRange and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoAdjacentStructuresWithHighRange]) == false then
                --Adjacent structures are providing the best enemy DF range; would we outrange the enemy if it wasnt for these?
                if AiBotUtilities.IsTableEmpty(tAvailableCombatUnits) == false and math.max((iFriendlyBestMobileDFRange or 0), (iFriendlyBestMobileIndirectRange or 0)) > math.max(iEnemyBestMobileDFRange, (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0)) then
                    --Get enemy longer range PD in adjacent zone closest to this zone midpoint, so can see if it is almost in range of any allied units
                    local oClosestPD
                    for iUnit, oUnit in tLZTeamData[AiBotMap.reftoAdjacentStructuresWithHighRange] do
                        if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 then --redundancy
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) - oUnit[AiBotUnitInfo.refiDFRange]
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                oClosestPD = oUnit
                            end
                        end
                    end
                    bNotCloseToAdjacentPD = true
                    if oClosestPD and iClosestDist <= 200 then
                        local iThreshold = 10 --If within 10 of being in range then recognise the range on the unit
                        for iUnit, oUnit in tAvailableCombatUnits do
                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestPD:GetPosition()) - oClosestPD[AiBotUnitInfo.refiDFRange] - iThreshold <= 0 then
                                bNotCloseToAdjacentPD = false
                                break
                            end
                        end
                    end
                    if bNotCloseToAdjacentPD then
                        iEnemyBestStructureDFRange =     (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0)
                        iEnemyBestDFRange = math.max(iEnemyBestMobileDFRange, iEnemyBestStructureDFRange)
                        if bDebugMessages == true then LOG(sFunctionRef..': Closest PD is far enough away from our units that we can ignore its range when deciding what scenario we are in, oClosestPD='..(oClosestPD.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestPD) or 'nil')..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iEnemyBestDFRange after update='..iEnemyBestDFRange..'; Time='..GetGameTimeSeconds()) end
                    end
                    iClosestDist = 100000
                end

            end


            local bNearestEnemyNeedsManualAttack = false --If nearest enemy is below water with its base but still visible on the top then units wont fire at it unless given a specific attack order
            local bAreInScenario1 = false --true if are in scenario 1
            local tEnemyEngineers = {} --So can avoid getting in reclaim range, and consider targeting as a priority
            local tSkirmisherDFEnemies = {}
            local tHiddenIFEnemies --If have any IF units that we lack visibility of, will add here so we can avoid with skirmishers
            local tSkirmisherEnemyT3MobileArti = {} --for e.g. sniperbots to avoid unless they have shield coverage
            local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]

            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Going through all enemy units in this zone to determine skirmisher enemies, nearest enemy to friendly base, and nearest structure') end
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefMidpoint]) then
                    --Got an error in coop so put in below as a redundancy in case had no midpoint (but couldve been another reason)
                    AiBotUtilities.ErrorHandler('Dont have midpoint for P'..iPlateau..'Z'..iLandZone..'; will try and rerecord')
                    AiBotMap.RecordMidpointAndOtherDataForZone(iPlateau, iLandZone, tLZData)
                end
                tEnemyEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                if not(tEnemyEngineers) then tEnemyEngineers = {} end
                for iUnit, oUnit in tLZTeamData[AiBotMap.subrefTEnemyUnits] do
                    if not(bIgnoreEnemiesInThisZone) then
                        if oUnit.UnitId == 'xsl0101' and AiBotUnitInfo.GetUnitSpeed(oUnit) < 0.2 and not(AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit, false)) then
                            --Ignore selen
                        else
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], (oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam] or oUnit:GetPosition()))
                            if iCurDist < iClosestDist and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout - categories.SERAPHIM, oUnit.UnitId)) then
                                iClosestDist = iCurDist
                                oNearestEnemyToFriendlyBase = oUnit
                            end
                            if iCurDist < iClosestStructureDist and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) and oUnit:GetFractionComplete() >= 0.5 then
                                iClosestStructureDist = iCurDist
                                oNearestEnemyStructureToMidpoint = oUnit
                            end
                            if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                                table.insert(tSkirmisherDFEnemies, oUnit)
                                if bDebugMessages == true then LOG(sFunctionRef..': Recording enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with name '..(__blueprints[oUnit.UnitId].General.UnitName or 'nil')..' with DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..' against tSkirmisherDFEnemies') end
                            elseif (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 10 then
                                if oUnit[AiBotUnitInfo.refiIndirectRange] > 60 and oUnit[AiBotUnitInfo.refiIndirectRange] < 130 and EntityCategoryContains(AiBotUnitInfo.refCategoryT3MobileArtillery, oUnit.UnitId) then
                                    table.insert(tSkirmisherEnemyT3MobileArti, oUnit)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Recording enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with name '..(__blueprints[oUnit.UnitId].General.UnitName or 'nil')..' with DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..' against tSkirmisherEnemyT3MobileArti') end
                                end
                                --Also check for hidden IF enemies
                                if not(AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit, false)) then
                                    if not(tHiddenIFEnemies) then tHiddenIFEnemies = {} end
                                    table.insert(tHiddenIFEnemies, oUnit)
                                end
                            end
                        end
                    end
                end
                if not(oNearestEnemyToFriendlyBase) and AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone) == false then
                    for iACU, oACU in toEnemyACUsNearZone do
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], oACU[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
                        if iCurDist < iClosestDist then
                            iClosestDist = iCurDist
                            oNearestEnemyToFriendlyBase = oACU
                        end
                    end
                end
            end
            --More detailed check of nearby ACUs if we have an experimental, as sometimes an ACU can be in an adjacent zone near to our unit
            if AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone) and iAvailableCombatUnitThreat >= 5000 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
                for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                    if bDebugMessages == true then LOG(sFunctionRef..': ACU doublecheck, ACU brain='..oACU:GetAIBrain().Nickname..'; dist to this zone midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint])) end
                    if not(oACU.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= 150 then
                        table.insert(toEnemyACUsNearZone, oACU)
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone) == false and (iAvailableCombatUnitThreat >= 500 or (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] >= 3000)) then
                --if iEnemyBestDFRange >= 30 then
                local iMobileDFWanted = math.min(AiBotUnitInfo.GetCombatThreatRating(toEnemyACUsNearZone, true), 8000)
                if bDebugMessages == true then LOG(sFunctionRef..': Threat of enemy ACUs in zone (or nearest ACU to the zone that is in adj zone)='..AiBotUnitInfo.GetCombatThreatRating(toEnemyACUsNearZone, true)..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]) end
                if iMobileDFWanted <= 500 or iAvailableCombatUnitThreat > iMobileDFWanted then
                    --Check that the threat of our forces near the enemy ACU is high enough to handle it as well
                    local oClosestACUToMidpoint
                    local iClosestACUDist = 10000
                    for iACU, oACU in toEnemyACUsNearZone do
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], oACU[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
                        if iCurDist < iClosestACUDist then
                            iClosestACUDist = iCurDist
                            oClosestACUToMidpoint = oACU
                        end
                    end
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': oClosestACUToMidpoint='..(oClosestACUToMidpoint.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestACUToMidpoint) or 'nil'))
                        if oClosestACUToMidpoint then LOG(sFunctionRef..': ACU dist to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oClosestACUToMidpoint:GetPosition(), tLZData[AiBotMap.subrefMidpoint])) end
                    end
                    if oClosestACUToMidpoint and AiBotUtilities.GetDistanceBetweenPositions(oClosestACUToMidpoint:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= 200 then
                        --Include T1 arti in the threat calculation
                        --Get the closest friendly combat unit to this
                        iClosestACUDist = 10000
                        local oClosestCombatUnitToEnemyACU
                        for iUnit, oUnit in tAvailableCombatUnits do
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestACUToMidpoint:GetPosition())
                            if iCurDist < iClosestACUDist then
                                iClosestACUDist = iCurDist
                                oClosestCombatUnitToEnemyACU = oUnit
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': oClosestCombatUnitToEnemyACU='..(oClosestCombatUnitToEnemyACU.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestCombatUnitToEnemyACU) or 'nil')) end
                        if oClosestCombatUnitToEnemyACU then
                            local tFriendlyCombatNearACU = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat, oClosestCombatUnitToEnemyACU:GetPosition(), 40, 'Ally')
                            local iFriendlyFrontlineCombatThreat = AiBotUnitInfo.GetCombatThreatRating(tFriendlyCombatNearACU, true)
                            if iFriendlyFrontlineCombatThreat >= iMobileDFWanted then
                                --Check if enemy has significant force
                                if iFriendlyFrontlineCombatThreat >= 15000 then bConsiderAttackingACU = true
                                else
                                    local tEnemiesNearACU = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat, oClosestACUToMidpoint:GetPosition(), 35, 'Enemy')
                                    local iThreatOfEnemies = AiBotUnitInfo.GetCombatThreatRating(tEnemiesNearACU)
                                    if bDebugMessages == true then LOG(sFunctionRef..': iThreatOfEnemies using getunitsaroundpoint='..iThreatOfEnemies) end
                                    if iFriendlyFrontlineCombatThreat >= iThreatOfEnemies then
                                        if tLZTeamData[AiBotMap.refiRadarCoverage] >= 100 then
                                            bConsiderAttackingACU = true --no need for more detailed memory based check as we have good intel coverage
                                        else
                                            local tEnemyACULZData, tEnemyACULZTeamData = AiBotMap.GetLandOrWaterZoneData(oClosestACUToMidpoint:GetPosition(), true, iTeam)
                                            if AiBotUtilities.IsTableEmpty(tEnemyACULZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                --We might not have intel of enemy threat - do more detailed calculation based on enemy DF units
                                                local toNearbyOtherDFEnemies = {}
                                                --Include enemies almost in range of the enemy ACU's position
                                                for iUnit, oUnit in tEnemyACULZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                    if not(oUnit.Dead) and not(oUnit == oClosestACUToMidpoint) and oUnit[AiBotUnitInfo.refiDFRange] and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestACUToMidpoint:GetPosition()) - oUnit[AiBotUnitInfo.refiDFRange] <= 10 then
                                                        table.insert(toNearbyOtherDFEnemies, oUnit)
                                                    end
                                                end
                                                iThreatOfEnemies = AiBotUnitInfo.GetCombatThreatRating(toNearbyOtherDFEnemies) + iMobileDFWanted
                                                if bDebugMessages == true then LOG(sFunctionRef..': iThreatOfEnemies based on mroe detailed memory based check='..iThreatOfEnemies) end
                                                if iFriendlyFrontlineCombatThreat >= iThreatOfEnemies * 0.95 then
                                                    bConsiderAttackingACU = true
                                                end
                                            else
                                                bConsiderAttackingACU = true
                                            end
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iFriendlyFrontlineCombatThreat='..iFriendlyFrontlineCombatThreat..'; iClosestACUDist='..iClosestACUDist..'; oClosestCombatUnitToEnemyACU='..oClosestCombatUnitToEnemyACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestCombatUnitToEnemyACU)..'; Closest enemy ACU is owned by '..oClosestACUToMidpoint:GetAIBrain().Nickname) end
                        end
                    end
                end
                --[[else
                    bConsiderAttackingACU = true
                    if bDebugMessages == true then LOG(sFunctionRef..': iEnemyBestDFRange isnt at least 30 so will consider attacking ACU, iEnemyBestDFRange='..iEnemyBestDFRange) end
                end--]]
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished deciding if we want to try and attack enemy ACU, bConsiderAttackingACU='..tostring(bConsiderAttackingACU or false)..'; Is table of enemy ACUs near zone empty='..tostring(AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone))) end

            local bOnlyCheckForStructureOrDF = true
            if not(oNearestEnemyToFriendlyBase) then bOnlyCheckForStructureOrDF = false end



            function GetUnitToAttackNearestACUOrOverrideUnit(oUnit, oACUOverride)
                local oClosestACUToAttack
                local iClosestACU = 100000
                local iCurACUDist
                local iDistToBeInRange = 5
                if oClosestFatboyOrACUInIslandToSuicideInto and EntityCategoryContains(categories.COMMAND, oClosestFatboyOrACUInIslandToSuicideInto.UnitId) then iDistToBeInRange = 12 end
                if oACUOverride then
                    oClosestACUToAttack = oACUOverride
                    iClosestACU = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACUOverride:GetPosition())
                else
                    for iACU, oACU in toEnemyACUsNearZone do
                        iCurACUDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
                        if iCurACUDist < iClosestACU then
                            iClosestACU = iCurACUDist
                            oClosestACUToAttack = oACU
                        end
                    end
                end
                if EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oUnit.UnitId) then RecordAttackingExperimental(tLZTeamData, oUnit) end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' should do attack order on ACU or move to it, iClosestACU='..iClosestACU..'; oUnit[AiBotUnitInfo.refiDFRange]='..oUnit[AiBotUnitInfo.refiDFRange]..'; oUnit[AiBotUnitInfo.refbLastShotBlocked]='..tostring(oUnit[AiBotUnitInfo.refbLastShotBlocked] or false)..'; Do we expect shot to be blocked='..tostring(AiBotLogic.IsShotBlocked(oUnit, oClosestACUToAttack))..'; iDistToBeInRange='..iDistToBeInRange) end

                if (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 15000 and oUnit[AiBotUnitInfo.refiCombatRange] <= 64 and (oUnit[AiBotUnitInfo.refiDFRange] <= 50 or oUnit.UnitId == 'url0402') and oUnit:GetMaxHealth() >= 40000 then --IF CHANGING HERE THEN CHANGE ABOVE AS WELL
                    if bDebugMessages == true then LOG(sFunctionRef..': Will suicide experimental into ACU') end
                    ForkThread(AiBotMicro.SuicideExperimentalIntoEnemyACU, oUnit, oClosestACUToAttack, iClosestACU)
                end
                if not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
                    if (oUnit[AiBotUnitInfo.refiCombatRange] or 0) - iClosestACU >= iDistToBeInRange and (not(oUnit[AiBotUnitInfo.refbLastShotBlocked]) and (not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oUnit.UnitId)) or (oUnit[AiBotUnitInfo.refiDFRange] or 0) == 0 or not(AiBotLogic.IsShotBlocked(oUnit, oClosestACUToAttack)))) then --ACU more than 5 inside our range - attack it unless our shot is blocked
                        AiBotOrders.IssueTrackedAttack(oUnit, oClosestACUToAttack, false, 'ACUEAt', false)
                    else
                        AiBotOrders.IssueTrackedMove(oUnit, oClosestACUToAttack:GetPosition(), (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.4, false, 'ACUEMv'..iLandZone, false)
                    end
                end
            end

            function SuicideUnitIntoEnemyStructure(oUnit)
                --Consider running from nearby enemy engineers
                local bRunningFromEngi = false
                if AiBotUtilities.IsTableEmpty(tEnemyEngineers) == false and oUnit[AiBotUnitInfo.refiLastWeaponEvent] then
                    if bDebugMessages == true then LOG(sFunctionRef..': Time since unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' fired its weapon last='..GetGameTimeSeconds() -oUnit[AiBotUnitInfo.refiLastWeaponEvent]..'; Time between IF shots='..oUnit[AiBotUnitInfo.refiTimeBetweenIFShots]) end
                    if GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiLastWeaponEvent] < oUnit[AiBotUnitInfo.refiTimeBetweenIFShots] - 2.1 then
                        local oNearestEngineerToUnit = AiBotUtilities.GetNearestUnit(tEnemyEngineers, oUnit:GetPosition())
                        local iEngiBuildRange = math.max(4, (oNearestEngineerToUnit:GetBlueprint().Economy.MaxBuildDistance or 5)) + 1 --+1 to allow for unit sizes
                        local iDistToNearestEngi = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEngineerToUnit:GetPosition())
                        if bDebugMessages == true then LOG(sFunctionRef..': oNearestEngineerToUnit='..oNearestEngineerToUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEngineerToUnit)..'; iEngiBuildRange='..iEngiBuildRange..'; iDistToNearestEngi='..iDistToNearestEngi) end
                        if iDistToNearestEngi <= 3 + iEngiBuildRange then --to allow for engi to move inbetween firing
                            local iAngleFromEngiToUnit = AiBotUtilities.GetAngleFromAToB(oNearestEngineerToUnit:GetPosition(), oUnit:GetPosition())
                            local tPotentialMoveLocation = AiBotUtilities.MoveInDirection(oNearestEngineerToUnit:GetPosition(), iAngleFromEngiToUnit, iEngiBuildRange + 6, true, true, AiBotMap.bIsCampaignMap)
                            if bDebugMessages == true then LOG(sFunctionRef..': Plateau label of tPotentialMoveLocation='..(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPotentialMoveLocation) or 'nil')..'; iPlateau='..iPlateau) end
                            if tPotentialMoveLocation and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPotentialMoveLocation) == iPlateau then
                                bRunningFromEngi = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Will try and run from the engineer') end
                                AiBotOrders.IssueTrackedMove(oUnit, tPotentialMoveLocation, 1, false, 'ArtRnFrE', false)
                            end
                        end
                    end
                end
                if not(bRunningFromEngi) then
                    --Get closest unit of preferred category
                    local tBuildingsOfInterestInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                    local oUnitToAttack
                    if AiBotUtilities.IsTableEmpty(tBuildingsOfInterestInZone) == false then
                        --Get units iwthin range, and then pick the preferred one
                        local iCurValue, iValueFactor
                        local iBestValue = 0
                        for iEnemy, oEnemy in tBuildingsOfInterestInZone do
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition())
                            if iCurDist <= oUnit[AiBotUnitInfo.refiCombatRange] + 16 then
                                --Adjust value based on category
                                if EntityCategoryContains(categories.VOLATILE - AiBotUnitInfo.refCategoryT1Power, oEnemy.UnitId) then
                                    iValueFactor = 4
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oEnemy.UnitId) then
                                    iValueFactor = 1.5
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryPower - AiBotUnitInfo.refCategoryT1Power, oEnemy.UnitId) then
                                    iValueFactor = 2.1 --so a T1 mex should have more value than a T1 pgen
                                    if oEnemy:GetWorkProgress() >= 0.05 then --Reason for htis is that a human palyer will usually be able ot use intuition to target upgraidng mexes, since players typically upgrade mexes in order, and are likely to have engineers near an upgrading mex, as well as some being at T2 some at T1, but want to avoid the significant cpu load from trying to mathematically approximate such intuition
                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryT1Mex, oEnemy.UnitId) then
                                            iValueFactor = 2 + 40 * oEnemy:GetWorkProgress() --T2 mex costs roughly 25 times a t1 mex, but we are treating eco damage as worth twice as much
                                            if bDebugMessages == true then LOG(sFunctionRef..': T1 mex upgrading to t2 so greater priority, oEnemy:GetWorkProgress()='..oEnemy:GetWorkProgress()) end
                                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryT2Mex, oEnemy.UnitId) then
                                            iValueFactor = 2 + 7 * oEnemy:GetWorkProgress() --T3 mex costs 5 times t2 mex, but we are valuing eco damage at double rate
                                        else
                                            iValueFactor = 2 + 3 * oEnemy:GetWorkProgress() --e.g. support for mods with upgradable pgens
                                        end
                                    end
                                else
                                    iValueFactor = 1
                                end
                                --Reduce value if not actually in range
                                if iCurDist > oUnit[AiBotUnitInfo.refiCombatRange] then
                                    iValueFactor = iValueFactor * 0.25
                                end
                                --Reduce value if covered by shields
                                if AiBotUtilities.IsTableEmpty(oEnemy[AiBotBuilding.reftoShieldsProvidingCoverage]) == false then
                                    iValueFactor = iValueFactor * 0.05
                                end
                                --Reduce value if owned by civilian
                                if AiBotConditions.IsCivilianBrain(oEnemy:GetAIBrain()) then iValueFactor = iValueFactor * 0.05 end
                                --Reduce value if we'd have to move a bit to get in range
                                if iCurDist > oUnit[AiBotUnitInfo.refiCombatRange] + 6 then
                                    iValueFactor = iValueFactor * 0.2
                                end

                                iCurValue = iValueFactor * oEnemy:GetFractionComplete() * (oEnemy[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oEnemy))
                                --Now figure out how quickly we can kill the unit, and adjust the value by that
                                local iShotsToKill = math.floor(oEnemy:GetHealth() / (oUnit[AiBotUnitInfo.refiStrikeDamage] or 200)) + 1
                                iCurValue = iCurValue / math.max(2, iShotsToKill) --2 shots to kill min since likely we have multiple t1 arti in the zone, so want to avoid e.g. all of them trying to focus down an enemy t1 radar
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; iCurValue='..iCurValue..'; iValueFactor='..iValueFactor..'; Mass cost='..oEnemy[AiBotUnitInfo.refiUnitMassCost]..'; iShotsToKill='..iShotsToKill..'; ICurDist='..iCurDist..'; Unit combat range='..oUnit[AiBotUnitInfo.refiCombatRange]..'; Work progress='..(oEnemy:GetWorkProgress() or 'nil')..'; Fraction complete='..oEnemy:GetFractionComplete()..'; Is table of shields providing coverage empty='..tostring(AiBotUtilities.IsTableEmpty(oEnemy[AiBotBuilding.reftoShieldsProvidingCoverage]))) end
                                if iCurValue > iBestValue then
                                    iBestValue = iCurValue
                                    oUnitToAttack = oEnemy
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Finsihed considering all buildings in zone, iBestValue='..iBestValue) end
                    end
                    if not(oUnitToAttack) then oUnitToAttack = oNearestEnemyStructureToMidpoint end
                    if AiBotUtilities.GetDistanceBetweenPositions(oUnitToAttack:GetPosition(), oUnit:GetPosition()) <= oUnit[AiBotUnitInfo.refiCombatRange] + 2 then
                        AiBotOrders.IssueTrackedAttack(oUnit, oUnitToAttack, false, 'ISDrAtc'..iLandZone, false)
                    else
                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, oUnitToAttack[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], 15, false, 'IKADrMve'..iLandZone)
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': T1 arti drop or similar, oUnitToAttack='..(oUnitToAttack.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToAttack) or 'nil')) end
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to search adjacent land zones for enemies closer to the midpoint; bOnlyCheckForStructureOrDF='..tostring(bOnlyCheckForStructureOrDF)..'; oNearestEnemyToFriendlyBase='..(oNearestEnemyToFriendlyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase) or 'nil')..'; oNearestEnemyStructureToMidpoint='..(oNearestEnemyStructureToMidpoint.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyStructureToMidpoint) or 'nil')) end
            local bEnemyHasFixedShieldsInThisOrAdjacentZone = false
            if (tLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) > 0 then bEnemyHasFixedShieldsInThisOrAdjacentZone = true end

            local iModifiedHighestEnemyValue
            if iAvailableCombatUnitThreat >= 300 then
                iModifiedHighestEnemyValue = (tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) + (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) + (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0)
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                    iModifiedHighestEnemyValue = math.max(1, iModifiedHighestEnemyValue, (tAdjLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) + (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0))
                end
            end
            if iModifiedHighestEnemyValue then iModifiedHighestEnemyValue = iModifiedHighestEnemyValue * 0.75 end --dont worry about adjusting distances if have locations similar in value
            if bDebugMessages == true then LOG(sFunctionRef..': iModifiedHighestEnemyValue='..(iModifiedHighestEnemyValue or 'nil')) end
            local iDistMod
            function UpdateForUnitsInAdjacentZone(tAdjLZTeamData)
                if bDebugMessages == true then LOG(sFunctionRef..': Will update enemy engineers, skirmisher enemies, and in some casese nearest enemy unit, for units in adjacent zone') end
                if iModifiedHighestEnemyValue and iAvailableCombatUnitThreat >= 3000 and iModifiedHighestEnemyValue >= 1500 and (iModifiedHighestEnemyValue >= 5000 or (tAdjLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) < 1800) then --primarily want the logic for things like experimentals
                    iDistMod = math.max(1,3 - 2 * ((tAdjLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) + (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0)) / iModifiedHighestEnemyValue) --i.e. no adjust for highest value zone, down to x3 (i.e. +200%) distance for 0 value structure zone
                    if iDistMod == 1 then iDistMod = nil end
                else
                    iDistMod = nil
                end
                for iUnit, oUnit in tAdjLZTeamData[AiBotMap.subrefTEnemyUnits] do
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) then
                            table.insert(tEnemyEngineers, oUnit)
                        elseif oUnit.UnitId == 'xsl0101' and AiBotUnitInfo.GetUnitSpeed(oUnit) < 0.2 and not(AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit, false)) then
                            --Ignore selen that is potentially cloaked
                        elseif (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                            if not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout - categories.SERAPHIM, oUnit.UnitId)) then
                                table.insert(tSkirmisherDFEnemies, oUnit)
                                if bDebugMessages == true then LOG(sFunctionRef..': recording in tSkirmisherDFEnemies the adj zone enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with name '..(__blueprints[oUnit.UnitId].General.UnitName or 'nil')) end
                            end
                        elseif (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 10 then
                            if oUnit[AiBotUnitInfo.refiIndirectRange] > 60 and oUnit[AiBotUnitInfo.refiIndirectRange] < 130 and EntityCategoryContains(AiBotUnitInfo.refCategoryT3MobileArtillery, oUnit.UnitId) then
                                table.insert(tSkirmisherEnemyT3MobileArti, oUnit)
                                if bDebugMessages == true then LOG(sFunctionRef..': Recording adj zone enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with name '..(__blueprints[oUnit.UnitId].General.UnitName or 'nil')..' with DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..' against tSkirmisherEnemyT3MobileArti') end
                            end --we might be controlling untis in an adjacent zone that have an enemy unit/engeiner near them
                            if not(AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit, false)) then
                                if not(tHiddenIFEnemies) then tHiddenIFEnemies = {} end
                                table.insert(tHiddenIFEnemies, oUnit)
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurdist='..AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; iClosestDist='..iClosestDist..'; iClosestStructureDist='..iClosestStructureDist..'; iDistMod='..(iDistMod or 'nil')..'; bOnlyCheckForStructureOrDF='..tostring(bOnlyCheckForStructureOrDF)..'; DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; Mass cost='..(oUnit[AiBotUnitInfo.refiUnitMassCost] or 'nil')..'; iDistMod='..(iDistMod or 'nil')) end
                        if bOnlyCheckForStructureOrDF then
                            if (((oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 50) or EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId)) and oUnit:GetFractionComplete() >= 0.5 then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
                                if iDistMod and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryLandCombat * categories.EXPERIMENTAL, oUnit.UnitId)) then
                                    iCurDist = iCurDist * iDistMod
                                end
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) then
                                    if iCurDist < iClosestStructureDist then
                                        iClosestStructureDist = iCurDist
                                        oNearestEnemyStructureToMidpoint = oUnit
                                    end
                                end
                                if iCurDist < iClosestDist then
                                    iClosestDist = iCurDist
                                    oNearestEnemyToFriendlyBase = oUnit
                                    if bDebugMessages == true then LOG(sFunctionRef..': Updated oNearestEnemyToFriendlyBase for this enemy') end
                                end
                            end
                        else
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
                            if iDistMod then iCurDist = iCurDist * iDistMod end
                            if iCurDist < iClosestDist then
                                if not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout - categories.SERAPHIM, oUnit.UnitId)) then
                                    iClosestDist = iCurDist
                                    oNearestEnemyToFriendlyBase = oUnit
                                    if bDebugMessages == true then LOG(sFunctionRef..': Updating oNearestEnemyToFriendlyBase to be this unit') end
                                end
                            end
                            if iCurDist < iClosestStructureDist and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) and oUnit:GetFractionComplete() >= 0.5 then
                                iClosestStructureDist = iCurDist
                                oNearestEnemyStructureToMidpoint = oUnit
                            end
                        end
                    end
                end
                if not(bEnemyHasFixedShieldsInThisOrAdjacentZone) and (tAdjLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) > 0 then bEnemyHasFixedShieldsInThisOrAdjacentZone = true end
            end
            function GetCombatThreatFromAdjacentZone(tAdjLZTeamData, bAdjustStructureThreat)
                local iAdjCombatThreat = math.max((tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 0.5, (tAdjLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0) + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0))
                if bAdjustStructureThreat and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will reduce adjacent threat by structure threat, tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]='..repru(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange])) end
                    for iRange, iThreat in tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                        if iRange <= 65 then
                            iAdjCombatThreat = iAdjCombatThreat - iThreat * 0.8
                        end
                    end
                end
                return iAdjCombatThreat
            end
            local tbCurOrAdjacentZones = {[iLandZone]=true}
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    tbCurOrAdjacentZones[iAdjLZ] = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]))..'; tbAdjacentZoneEnemiesToIgnoreByZone='..tostring(tbAdjacentZoneEnemiesToIgnoreByZone[iAdjLZ] or false)) end
                    if not(tbAdjacentZoneEnemiesToIgnoreByZone[iAdjLZ]) then
                        if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]) == false then
                            UpdateForUnitsInAdjacentZone(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
                        end
                    end
                end
            end
            if tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] then
                for iEntry, tPlateauAndZone in tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] do
                    UpdateForUnitsInAdjacentZone(AiBotMap.tAllPlateaus[tPlateauAndZone[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndZone[2]][AiBotMap.subrefLZTeamData][iTeam])
                end
            end

            --Include long range DF enemies that arent in an adjacent zone into skirmisher enemies
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false then
                local bUpdateNearestEnemy = false
                if not(oNearestEnemyToFriendlyBase) then bUpdateNearestEnemy = true end
                for iLREnemy, oLREnemy in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if should add oLREnemy to skirmisher enemies, oLREnemy='..oLREnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLREnemy)..'; Cur assigned P='..(oLREnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or 'nil')..'Z'..(oLREnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or 'nil')) end
                    if not(oLREnemy.Dead) then --redundancy
                        if oLREnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] and(not(tbCurOrAdjacentZones[oLREnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]]) or not(oLREnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau)) then
                            table.insert(tSkirmisherDFEnemies, oLREnemy)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will add oLREnemy to tSkirmisherDFEnemies') end
                        end
                        --If enemy is close to nearestenemytofriendlybase then also update enemy range
                        if oLREnemy[AiBotUnitInfo.refiDFRange] > iEnemyBestDFRange then
                            if bUpdateNearestEnemy or (oNearestEnemyToFriendlyBase and (AiBotUtilities.GetDistanceBetweenPositions(oLREnemy:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - oLREnemy[AiBotUnitInfo.refiDFRange] <= -10 or AiBotUtilities.GetDistanceBetweenPositions(oLREnemy:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= 50)) then
                                iEnemyBestDFRange = oLREnemy[AiBotUnitInfo.refiDFRange]
                                if bUpdateNearestEnemy and oLREnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oLREnemy:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                    if iCurDist < iClosestDist then
                                        iClosestDist = iCurDist
                                        oNearestEnemyToFriendlyBase = oLREnemy
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Increasing iEnemyBestDFRange to reflect LR enemy DF unit') end
                            end
                        end
                    end
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': Do we have a valid oNearestEnemyToFriendlyBase='..tostring(AiBotUnitInfo.IsUnitValid(oNearestEnemyToFriendlyBase))..'; Are there enemies in adjacnet WZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ])..'; tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ])..'; oNearestEnemyToFriendlyBase='..(oNearestEnemyToFriendlyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase) or 'nil')) end

            if not(oNearestEnemyToFriendlyBase) and tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                --Consider adjacent water zone enemies (will only consider mobile - i.e. wont update nearest structure unless we're already considering the WZ for a nearest enemy to midpoint)
                local iCurWZ, iCurPond
                for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                    iCurWZ = tSubtable[AiBotMap.subrefAWZRef]
                    iCurPond = AiBotMap.tiPondByWaterZone[iCurWZ]
                    local tWZTeamData = AiBotMap.tPondDetails[iCurPond][AiBotMap.subrefPondWaterZones][iCurWZ][AiBotMap.subrefWZTeamData][iTeam]
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurWZ='..(iCurWZ or 'nil')..'; iCurPond='..(iCurPond or 'nil')..'; tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..(tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')) end
                    if tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > 0 or tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] > 0 then
                        for iUnit, oUnit in tWZTeamData[AiBotMap.subrefTEnemyUnits] do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to add oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; to nearest enemy to midpoint; Is it valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; Is it underwater='..tostring(AiBotUnitInfo.IsUnitUnderwater(oUnit))..'; iClosestDist='..iClosestDist) end
                            if AiBotUnitInfo.IsUnitValid(oUnit) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryHydro + AiBotUnitInfo.refCategoryLandScout, oUnit.UnitId)) then
                                --Do based on dist to zone midpoint instead of closest friendly base, since it coudl be really far away from this zone (but closer to our base)
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
                                if iCurDist < iClosestDist then
                                    iClosestDist = iCurDist
                                    oNearestEnemyToFriendlyBase = oUnit
                                end
                                --Note - below effectively means are only considering structures in water if the WZ has combat units in it and there are no enemy units on land nearby (so isn't 100% accurate)
                                if iCurDist < iClosestStructureDist and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) and oUnit:GetFractionComplete() >= 0.5 then
                                    iClosestStructureDist = iCurDist
                                    oNearestEnemyStructureToMidpoint = oUnit
                                end
                            end
                        end
                        if oNearestEnemyToFriendlyBase then
                            --Check if need manual attack order
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryAmphibious, oNearestEnemyToFriendlyBase.UnitId) then bNearestEnemyNeedsManualAttack = true end
                        end
                    end
                end
                if not(oNearestEnemyToFriendlyBase) and bSuicideIntoFatboyOrACU and oClosestFatboyOrACUInIslandToSuicideInto then oNearestEnemyToFriendlyBase = oClosestFatboyOrACUInIslandToSuicideInto end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished checking adjacent water zones for enemy units, iClosestDist='..iClosestDist..'; oNearestEnemyToFriendlyBase='..(oNearestEnemyToFriendlyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase) or 'nil')) end
            end

            if not(oNearestEnemyToFriendlyBase) and AiBotUtilities.IsTableEmpty(tUnitsNearFatboyInFurtherAwayZones) == false then
                for iUnit, oUnit in tUnitsNearFatboyInFurtherAwayZones do
                    --Do based on dist to this midpoint instead of closest friendly base since not dealing with units in this zone
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
                    if iCurDist < iClosestDist then
                        iClosestDist = iCurDist
                        oNearestEnemyToFriendlyBase = oUnit
                    end
                end
            end
            if not(oNearestEnemyToFriendlyBase) then
                if not(bIgnoreEnemiesInThisZone) or bConsiderEnemiesInAtLeastOneAdjacentZone then
                    if bDebugMessages == true then LOG(sFunctionRef..': LZ has flagged it has enemies here or in adjacent LZ but couldnt find any; iPlateau='..iPlateau..'; LZ='..iLandZone) end
                    tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] = false
                end
            end

            --Update enemy best DF range to reflect closest unit (which might be a DF unit)
            if (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) >= 10 then
                if oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] > iEnemyBestDFRange then
                    iEnemyBestDFRange = oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange]
                    --If this is in a different zone then get the best enemy ranges from that zone
                    if not(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                        local tNearestEnemyLZTeamData = AiBotMap.tAllPlateaus[oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]][AiBotMap.subrefPlateauLandZones][oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZTeamData][iTeam]
                        if tNearestEnemyLZTeamData then
                            iEnemyBestMobileDFRange = math.max(iEnemyBestMobileDFRange, (tNearestEnemyLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0))
                            iEnemyBestStructureDFRange = math.max(iEnemyBestStructureDFRange, (tNearestEnemyLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0))
                        end
                    end
                end
                if EntityCategoryContains(categories.MOBILE, oNearestEnemyToFriendlyBase.UnitId) then
                    iEnemyBestMobileDFRange = math.max(iEnemyBestMobileDFRange, oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange])
                    if oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                        local iAdjWZ = oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam]
                        local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                        if (tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] or -1) > iEnemyBestMobileDFRange then iEnemyBestMobileDFRange = tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] end
                    end
                else iEnemyBestStructureDFRange = math.max(iEnemyBestStructureDFRange, oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange])
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Updated iEnemyBestDFRange for oNearestEnemyToFriendlyBase, oNearestEnemyToFriendlyBase DF range='..(oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 'nil')..'; iEnemyBestStructureDFRange='..iEnemyBestStructureDFRange..'; iEnemyBestMobileDFRange='..iEnemyBestMobileDFRange) end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': Finished checking for nearest enemy unit, is it valid='..tostring(AiBotUnitInfo.IsUnitValid(oNearestEnemyToFriendlyBase))..'; Zone it is assigned to='..(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or 'nil')..'; Is table of enemy units in this zone empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
            local iAdjacentDistGeneralMod = math.min(tLZData[AiBotMap.subrefLZMaxSegX] - tLZData[AiBotMap.subrefLZMinSegX], tLZData[AiBotMap.subrefLZMaxSegZ] - tLZData[AiBotMap.subrefLZMinSegZ]) * AiBotMap.iLandZoneSegmentSize
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) then iAdjacentDistGeneralMod = iAdjacentDistGeneralMod + 25 end
            local iDistToClosestEnemyThreshold --If nil then will ignore this check
            local oClosestFriendlyUnitToCompareTo --If nil will ignore this check; if set, then when deciding whether to include units in adajcent zones we will assess if they are likely close enough (relative to the nearest enemy unit) to be of concern to our closest friendly unit
            local iDistToClosestFriendlyThreshold
            if oNearestEnemyToFriendlyBase then
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false and oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone then
                    iDistToClosestEnemyThreshold = 30 --Include units within 30 of being in range of the closest enemy
                elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] == 0 and not(AiBotUtilities.bCPUPerformanceMode) then
                    local iClosestFriendlyToEnemyBaseDist = 100000
                    local iCurFriendlyDist
                    for iFriendly, oFriendly in tAvailableCombatUnits do
                        iCurFriendlyDist = AiBotUtilities.GetDistanceBetweenPositions(oFriendly:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase]) - (oFriendly[AiBotUnitInfo.refiCombatRange] or 0)
                        if iCurFriendlyDist < iClosestFriendlyToEnemyBaseDist then
                            iClosestFriendlyToEnemyBaseDist = iCurFriendlyDist
                            oClosestFriendlyUnitToCompareTo = oFriendly
                        end
                    end
                    if oClosestFriendlyUnitToCompareTo then
                        iDistToClosestFriendlyThreshold = AiBotUtilities.GetDistanceBetweenPositions(oClosestFriendlyUnitToCompareTo:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - math.max((oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] or 0), (oClosestFriendlyUnitToCompareTo[AiBotUnitInfo.refiCombatRange] or 0)) + 20
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': oClosestFriendlyUnitToCompareTo='..oClosestFriendlyUnitToCompareTo.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestFriendlyUnitToCompareTo)..'; iClosestFriendlyToEnemyBaseDist='..iClosestFriendlyToEnemyBaseDist..'; iDistToClosestFriendlyThreshold=;..iDistToClosestFriendlyThreshold') end

                end
            end
            function AddUnitFromAdjacentZoneToTableIfCloseEnough(tAdjLZTeamData, tNearbyAdjacentEnemies, iAdjacentDistThreshold, iStructureFurtherDistAdjust, iAngleFromClosestFriendlyUnitToMidpoint)
                --Only include units in the threat calculation if they are close enough to this LZ, or we have a firebase threat adjust
                if tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > 10 then
                    iEnemyBestStructureDFRange = math.max(iEnemyBestStructureDFRange, (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0))
                    local tPotentialEnemyUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryPD, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                    if AiBotUtilities.IsTableEmpty(tPotentialEnemyUnits) == false then
                        local iDistUntilInRangeOfMidpointOrClosestEnemy
                        local bAdd = false
                        for iUnit, oUnit in tPotentialEnemyUnits do
                            bAdd = false
                            if oUnit:GetFractionComplete() >= 0.95 and AiBotUnitInfo.IsUnitValid(oUnit) then
                                iDistUntilInRangeOfMidpointOrClosestEnemy = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                if oNearestEnemyToFriendlyBase then iDistUntilInRangeOfMidpointOrClosestEnemy = math.min(iDistUntilInRangeOfMidpointOrClosestEnemy, AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())) end
                                iDistUntilInRangeOfMidpointOrClosestEnemy = iDistUntilInRangeOfMidpointOrClosestEnemy - math.max((oUnit[AiBotUnitInfo.refiDFRange] or 0), (oUnit[AiBotUnitInfo.refiIndirectRange] or 0))
                                if bDebugMessages == true then LOG(sFunctionRef..': AddUnitFromAdjacentZoneToTableIfCloseEnough: Deciding whether to add enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])..'; Dist to closest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())..'; DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; iDistToClosestEnemyThreshold='..(iDistToClosestEnemyThreshold or 'nil')..'; iDistUntilInRangeOfMidpointOrClosestEnemy='..iDistUntilInRangeOfMidpointOrClosestEnemy) end
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) then
                                    if iDistUntilInRangeOfMidpointOrClosestEnemy  <= iAdjacentDistThreshold + iStructureFurtherDistAdjust + iAdjacentDistGeneralMod then
                                        if iDistUntilInRangeOfMidpointOrClosestEnemy <= iAdjacentDistGeneralMod then
                                            if bDebugMessages == true then LOG(sFunctionRef..': PD is almost within its DF range of the midpoint of target zone, oUnit[AiBotUnitInfo.refiDFRange]='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; iDistUntilInRangeOfMidpointOrClosestEnemy='..iDistUntilInRangeOfMidpointOrClosestEnemy) end
                                            bAdd = true
                                        elseif iDistUntilInRangeOfMidpointOrClosestEnemy * 2 <= math.min(40, iAdjacentDistThreshold + iStructureFurtherDistAdjust) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': PD is within half of the target range even after applying structure dist adj, iAdjacentDistThreshold + iStructureFurtherDistAdjust='..iAdjacentDistThreshold + iStructureFurtherDistAdjust) end
                                            bAdd = true
                                        elseif AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint]), iAngleFromClosestFriendlyUnitToMidpoint) <= 50 then
                                            bAdd = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Angle dif is low enough that we are including PD, angle dif='..AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint]), iAngleFromClosestFriendlyUnitToMidpoint)) end
                                        end
                                    end
                                    if bAdd and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > iEnemyBestStructureDFRange then iEnemyBestStructureDFRange = oUnit[AiBotUnitInfo.refiDFRange] end

                                else
                                    if iDistUntilInRangeOfMidpointOrClosestEnemy  <= iAdjacentDistThreshold + iAdjacentDistGeneralMod then
                                        bAdd = true
                                        if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > iEnemyBestMobileDFRange then iEnemyBestMobileDFRange = oUnit[AiBotUnitInfo.refiDFRange] end
                                    end
                                end
                                if bAdd then
                                    --NOTE: Added in v226 to cover scenario where ACU in AdjZB meant our tanks wouldnt attack AdjZA (in scenario 2 position)
                                    --if this leads to skirmishers suiciding into nearby enemies then may want to refine so we figure out based on the previous cycle if we were in scenario 1, 2 or 3, and we only add this check if we were in scenarios 2 or 3
                                    if not(bAreInScenario1) and iDistToClosestEnemyThreshold and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= iDistToClosestEnemyThreshold then
                                        if bDebugMessages == true then LOG(sFunctionRef..': We are actually too far from the nearest enemy to friendly base so will ignore') end
                                        bAdd = false
                                    end
                                    if not(bAreInScenario1) and oClosestFriendlyUnitToCompareTo and bAdd then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Dist to closest friendly unit='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFriendlyUnitToCompareTo:GetPosition())..'; Unit combat range='..(oUnit[AiBotUnitInfo.refiCombatRange] or 0)..'; iDistToClosestFriendlyThreshold='..iDistToClosestFriendlyThreshold) end
                                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFriendlyUnitToCompareTo:GetPosition()) - (oUnit[AiBotUnitInfo.refiCombatRange] or 0) > iDistToClosestFriendlyThreshold then
                                            bAdd = false
                                            if bDebugMessages == true then LOG(sFunctionRef..': We are too far from the closest friendly unit with this enemy unit to consider at this stage') end
                                        end
                                    end
                                end
                                if bDebugMessages == true then
                                    LOG(sFunctionRef..': Considering whether to add enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to adjacent enemies, bAdd='..tostring(bAdd)..'; iDistUntilInRangeOfMidpointOrClosestEnemy='..iDistUntilInRangeOfMidpointOrClosestEnemy..'; iAdjacentDistGeneralMod='..iAdjacentDistGeneralMod..'; iAdjacentDistThreshold='..iAdjacentDistThreshold)
                                    LOG('threat of this unit='..AiBotUnitInfo.GetCombatThreatRating({oUnit}, true)..'; Fraction complete='..oUnit:GetFractionComplete()..'; iDistUntilInRangeOfMidpointOrClosestEnemy of midpoint='..iDistUntilInRangeOfMidpointOrClosestEnemy..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; Angle to midpoint='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])..'; iAngleFromClosestFriendlyUnitToMidpoint='..(iAngleFromClosestFriendlyUnitToMidpoint or 'nil'))
                                end
                                if bAdd then
                                    table.insert(tNearbyAdjacentEnemies, oUnit)
                                    --If this is an ACU then consider adding to table of ACUs
                                    if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then
                                        --Is it already in the table?
                                        local bAlreadyInTable = false
                                        if AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone) == false then
                                            for iACU, oACU in toEnemyACUsNearZone do
                                                if oACU == oUnit then
                                                    bAlreadyInTable = true
                                                    break
                                                end
                                            end
                                        end
                                        if not(bAlreadyInTable) then
                                            table.insert(toEnemyACUsNearZone, oUnit)
                                            if bConsiderAttackingACU then
                                                --Do we still want to do this?
                                                local iMobileDFWanted = math.min(7500, AiBotUnitInfo.GetCombatThreatRating(toEnemyACUsNearZone, true))
                                                if iMobileDFWanted <= 3000 or tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] > iMobileDFWanted then
                                                    --Will continue attacking
                                                else
                                                    bConsiderAttackingACU = false
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Have ACU in an adjacent zone that is near enough to include, iMobileDFWanted to consider attacking it='..iMobileDFWanted..'; bConsiderAttackingACU after update='..tostring(bConsiderAttackingACU)) end
                                            end
                                        end
                                    end
                                    --Also make sure the best enemy range includes any units added from adjacent zones that are close enough to be relevant (as the more general range method used isn't 100% accurate)
                                    if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > iEnemyBestDFRange then
                                        --If this exceeds our best DF range and is close to the nearest enemy to our base, then are no longer in scenario1
                                        if bAreInScenario1 and not(iDFRangeOverrideForScenario1) and (iEnemyBestDFRange <= iFriendlyBestMobileDFRange or iEnemyBestDFRange < iFriendlyBestMobileIndirectRange) and oUnit[AiBotUnitInfo.refiDFRange] >= iFriendlyBestMobileDFRange and oUnit[AiBotUnitInfo.refiDFRange] >= iFriendlyBestMobileIndirectRange and ((oUnit[AiBotUnitInfo.refiDFRange] > iFriendlyBestMobileDFRange or (oUnit[AiBotUnitInfo.refiDFRange] == iFriendlyBestMobileDFRange and oUnit[AiBotUnitInfo.refiDFRange] > iFriendlyBestMobileIndirectRange)))  then
                                            if EntityCategoryContains(categories.MOBILE, oUnit.UnitId) and (not(AiBotUnitInfo.IsUnitValid(oNearestEnemyToFriendlyBase)) or AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition()) - (oUnit[AiBotUnitInfo.refiCombatRange] - iEnemyBestDFRange) < 20 or AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oUnit:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange] < 20 + AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oNearestEnemyToFriendlyBase:GetPosition()) - iEnemyBestDFRange) then
                                                bAreInScenario1 = false
                                                if bDebugMessages == true then LOG(sFunctionRef..': Are no longer in scenario 1 as have nearby enemy that outranges (or equals and outranges IF) our best range') end
                                            elseif bDebugMessages == true then LOG(sFunctionRef..': Unit is either immobile or far enoguh away from both nearest enemy and LZMidpoint that we wont change if we are in scenario1')
                                            end
                                        end
                                        iEnemyBestDFRange = oUnit[AiBotUnitInfo.refiDFRange]
                                        if bDebugMessages == true then LOG(sFunctionRef..': Updated iEnemyBestDFRange for adjacent unit range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; bAreInScenario1='..tostring(bAreInScenario1)) end

                                    end

                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': AddUnitFromAdjacentZoneToTableIfCloseEnough - Threat of all enemy units='..AiBotUnitInfo.GetCombatThreatRating(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits], true)..'; Threat of tPotentialEnemyUnits='..AiBotUnitInfo.GetCombatThreatRating(tPotentialEnemyUnits, true)..'; Threat of tNearbyAdjacentEnemies (which includes cumulative htreat of other adj zones before this one)='..AiBotUnitInfo.GetCombatThreatRating(tNearbyAdjacentEnemies, true)) end
                end
            end

            function DoManualAttack(oUnit, oTargetToManuallyAttack, sOrderDesc)
                if oUnit.UnitId == 'xsl0401' and EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat * categories.TECH3, oTargetToManuallyAttack.UnitId) and AiBotUtilities.GetDistanceBetweenPositions(oTargetToManuallyAttack:GetPosition(), oUnit:GetPosition()) <= oUnit[AiBotUnitInfo.refiCombatRange] then
                    local tTargetLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), AiBotUnitInfo.GetUnitFacingAngle(oUnit), 6, true)
                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tTargetLocation, math.min(20, oUnit[AiBotUnitInfo.refiCombatRange]), false, sOrderDesc..'YAM', false)
                else
                    AiBotOrders.IssueTrackedAttack(oUnit, oTargetToManuallyAttack, false, sOrderDesc, false)
                end
            end

            local iEnemyNearbyCombatThreatIfRelevant
            function GetEnemyCombatThreatInAdjacentZones()
                if not(iEnemyNearbyCombatThreatIfRelevant) then
                    local iCurAndAdjCombat = math.max((tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 0.5, (tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0) + (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0))
                    if bDebugMessages == true then LOG(sFunctionRef..': Getting enemy combat threat, threat in this zone='..iCurAndAdjCombat) end

                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]))..'; Enemy combat='..(tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..'; Enemy DF Structure='..(tAdjLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0)..'; Enemy DF Mobile='..(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)) end
                            iCurAndAdjCombat = iCurAndAdjCombat + math.max((tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 0.5, (tAdjLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0) + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0))
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                        iCurAndAdjCombat = math.max(iCurAndAdjCombat, AiBotUnitInfo.GetCombatThreatRating(tLZTeamData[AiBotMap.reftoNearestDFEnemies], true))
                    end
                    iEnemyNearbyCombatThreatIfRelevant = iCurAndAdjCombat
                    if bDebugMessages == true then LOG(sFunctionRef..': Setting iEnemyNearbyCombatThreatIfRelevant=iCurAndAdjCombat='..(iCurAndAdjCombat or 'nil')) end
                end
                return iEnemyNearbyCombatThreatIfRelevant
            end
            local iEnemyCombatThreat
            local bHaveACUInTroubleAndRecentlyInCombat = nil --updated as part of CalculateNearbyEnemyCombatThreatFriendlyDFAndIfFriendlyACUInCombat, and also ProtectFriendlyACUInTroubleIfRelevant if is nil
            local bACUInCombatButProbablySafe
            local iOurDFAndT1ArtiCombatThreat
            local tbFriendlyACUsConsidered = {}
            local tOurDFAndT1ArtiUnits
            function IncreaseCombatThreatForACU(oACU, iFarAwayFactorOverride)
                if not(tbFriendlyACUsConsidered[oACU.EntityId]) and AiBotUnitInfo.IsUnitValid(oACU) then
                    tbFriendlyACUsConsidered[oACU.EntityId] = true
                    if (not(oACU:IsUnitState('Upgrading')) and GetGameTimeSeconds() - (oACU[AiBotACU.refiTimeLastWantedToRun] or -100) >= 10) or (tLZTeamData[AiBotMap.subrefLZbCoreBase] and (GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= 15)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Have ACU that isnt upgrading, and doesnt want to run, in this zone, so will include unless far behind; altenratively ACU is in core base and recently fired its weapon') end
                        local iACUFactor = 1
                        if AiBotMap.iMapSize > 256 then iACUFactor = 0.9 end
                        if iEnemyBestStructureDFRange >= 50 then iACUFactor = 0.5 end
                        local iCurACUFactor
                        iCurACUFactor = iACUFactor
                        if not(AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], (oACU[AiBotUnitInfo.refiDFRange] or 0) + 6, iTeam, false, nil, nil, oACU, nil, false)) or (oACU:IsUnitState('Building') or oACU:IsUnitState('Repairing')) then
                            --If it has been a while since the ACU last fired its gun then treat it as not being in combat
                            if bDebugMessages == true then LOG(sFunctionRef..': ACU isnt close to nearest enemy, if last weapon event more than 5s then will reduce ACU value, time since last weapon event='..GetGameTimeSeconds() - (oACU[AiBotEvents.refiLastWeaponEvent] or -100)) end
                            if GetGameTimeSeconds() - (oACU[AiBotEvents.refiLastWeaponEvent] or -100) >= 5 then
                                iCurACUFactor = iCurACUFactor * (iFarAwayFactorOverride or 0.25)
                                --Reduce even further if ACU is quite far away
                                if not(AiBotUnitInfo.IsUnitValid(oACU[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])) or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oACU[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition()) >= 15 + (oACU[AiBotUnitInfo.refiDFRange] or 0) then
                                    iCurACUFactor = iCurACUFactor * 0.3 --i.e. apply almost no value to the ACU
                                end
                            end
                        end
                        iOurDFAndT1ArtiCombatThreat = iOurDFAndT1ArtiCombatThreat + AiBotUnitInfo.GetCombatThreatRating({ oACU}, false) * iCurACUFactor
                        if bDebugMessages == true then LOG(sFunctionRef..': iACUFactor='..iACUFactor..'; iCurACUFactor='..iCurACUFactor..'; Threat of ACU='..AiBotUnitInfo.GetCombatThreatRating({ oACU }, false) * iACUFactor..'; Closest enemy unit to ACU='..(oACU[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oACU[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) or 'nil')..'; Close to enemy DF units='..tostring(AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], (oACU[AiBotUnitInfo.refiDFRange] or 0) + 6, iTeam, false)))
                            if oACU[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] then
                                LOG(sFunctionRef..': Dist form ACU to nearest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oACU[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition()))
                            end
                        end
                    end
                end
            end
            local tNearbyAdjacentEnemies = {}
            function CalculateNearbyEnemyCombatThreatFriendlyDFAndIfFriendlyACUInCombat(tAvailableUnitOverride)
                --tAvailableUnitOverride is so we can just send short range units here to calculate threat in scenario 1 to decide if we want to attack with them
                local bUpdateEnemyCombatThreat = false
                if not(iEnemyCombatThreat) then bUpdateEnemyCombatThreat = true end
                iEnemyCombatThreat = math.max((iEnemyCombatThreat or 0), tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 0.5, tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] + tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]) --we end up only including nearby enemy threats in adj zones, not all adj zone threats
                local bAdjustStructureThreat = false

                --First calculate our DF threat (recalulate if already done this, as may be dealing with SR units)
                if bDebugMessages == true then LOG(sFunctionRef..': CalculateNearbyEnemyCombatThreatFriendlyDFAndIfFriendlyACUInCombat start of code, bUpdateEnemyCombatThreat='..tostring(bUpdateEnemyCombatThreat)) end
                tOurDFAndT1ArtiUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandCombat, tAvailableUnitOverride or tAvailableCombatUnits)
                if AiBotUtilities.IsTableEmpty(tOurDFAndT1ArtiUnits) == false then
                    iOurDFAndT1ArtiCombatThreat = AiBotUnitInfo.GetCombatThreatRating(tOurDFAndT1ArtiUnits, false)
                    if not(tAvailableUnitOverride) and AiBotUtilities.IsTableEmpty(tUnavailableUnitsInThisLZ) == false then
                        local tUnavailableDFAndT1Arti = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandCombat, tUnavailableUnitsInThisLZ)
                        if AiBotUtilities.IsTableEmpty(tUnavailableDFAndT1Arti) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..'; Combat threat before including unavailable units='..iOurDFAndT1ArtiCombatThreat..'; Threat of unavailable units in this LZ='..AiBotUnitInfo.GetCombatThreatRating(tUnavailableDFAndT1Arti, false)) end
                            iOurDFAndT1ArtiCombatThreat = iOurDFAndT1ArtiCombatThreat + AiBotUnitInfo.GetCombatThreatRating(tUnavailableDFAndT1Arti, false)
                        end
                    end
                else
                    --T1DFAndT1Arti is empty
                    if bUpdateEnemyCombatThreat then --use placeholder value so we dont do lots of calculations when it doesnt really matter (and we just want a rough guide of how big a threat there is here)
                        bUpdateEnemyCombatThreat = false
                        if not(iEnemyNearbyCombatThreatIfRelevant) then GetEnemyCombatThreatInAdjacentZones() end
                        iEnemyCombatThreat = math.max(iEnemyNearbyCombatThreatIfRelevant, (iEnemyCombatThreat or 0), tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal])
                    end
                end

                if bUpdateEnemyCombatThreat then
                    if (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false then
                        --If enemy LR threat is buildings rather than mobile units then increase enemy combat threat by this, so we are less likely to engage unless confident we will win
                        local bHaveDFBuildingsInLRThreat = false
                        for iUnit, oUnit in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
                            if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) then
                                bHaveDFBuildingsInLRThreat = true
                                break
                            end
                        end
                        if bHaveDFBuildingsInLRThreat then
                            if tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > 20000 then --at very high exp counts sometimes just want to push in; also warrants more detailed calculation
                                local iLRThreat = 0
                                local toEnemyLRThreats = {}
                                local iOurDFRangeToUse = math.min(iFriendlyBestMobileDFRange, 45)
                                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false and oNearestEnemyToFriendlyBase then
                                    for iUnit, oUnit in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
                                        if not(oUnit.Dead) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= iOurDFRangeToUse then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Assessing enemy LR DF that are actually in range, considering oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with DFRange='..(oUnit[AiBotUnitInfo.refiDFRange] or 0)..'; iOurDFRangeToUse='..iOurDFRangeToUse..'; Dist until unit in range of nearest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())..'; Overall margin before DF able to shoot at our units adjusted for our and their range='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - (oUnit[AiBotUnitInfo.refiDFRange] or 0) + iOurDFRangeToUse..'; Unit threat='..AiBotUnitInfo.GetCombatThreatRating({ oUnit }, true, false)) end
                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - (oUnit[AiBotUnitInfo.refiDFRange] or 0) + iOurDFRangeToUse < 10 then --if our units get within firing range, they will almost be in range of enemy LR DF threat
                                                table.insert(toEnemyLRThreats, oUnit)
                                            end
                                        end

                                    end
                                    if AiBotUtilities.IsTableEmpty(toEnemyLRThreats) == false then
                                        iLRThreat = AiBotUnitInfo.GetCombatThreatRating(toEnemyLRThreats , true, false)
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iLRThreat before adjustments='..iLRThreat) end
                                iLRThreat = math.max(tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] * 0.2, math.min(iLRThreat, tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]))
                                if iLRThreat > 100000 then iLRThreat =  100000 + (iLRThreat - 100000) * 0.6 end
                                iEnemyCombatThreat = iEnemyCombatThreat + iLRThreat
                                if bDebugMessages == true then LOG(sFunctionRef..': iLRThreat after adjustments='..iLRThreat..'; iEnemyCombatThreat after increase='..iEnemyCombatThreat) end
                            else
                                iEnemyCombatThreat = iEnemyCombatThreat + tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Increasing enemy LR threat for long range building threat, tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]='..tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]..'; iEnemyCombatThreat after increase='..iEnemyCombatThreat) end
                        end
                    end
                    local tbZonesConsidered = {}
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        if bDebugMessages == true then LOG(sFunctionRef..': Calculating enemy threat, iFirebaseThreatAdjust='..iFirebaseThreatAdjust) end
                        if iFirebaseThreatAdjust == 0 then
                            local iAdjacentDistThreshold = 0
                            local iCurDist
                            local iMinDist = 1000
                            local oClosestFriendlyUnit
                            --If dealing with PD, then will only include as a 'close enough' threat if the dist is closer than mobile units, factoring in range

                            for iUnit, oUnit in tOurDFAndT1ArtiUnits do --have already confirmed this isnt empty earlier
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                if iCurDist > iAdjacentDistThreshold then iAdjacentDistThreshold = iCurDist end
                                if iCurDist < iMinDist then
                                    iMinDist = iCurDist
                                    oClosestFriendlyUnit = oUnit
                                end
                            end
                            local iAngleFromClosestFriendlyUnit = 0
                            if oClosestFriendlyUnit then iAngleFromClosestFriendlyUnit = AiBotUtilities.GetAngleFromAToB(oClosestFriendlyUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) end
                            iAdjacentDistThreshold = iAdjacentDistThreshold + 20
                            local iStructureUnitDistThresholdAdjust = math.max(-30, -iAdjacentDistThreshold + 15)
                            if iAdjacentDistThreshold + iStructureUnitDistThresholdAdjust > iMinDist + 10 then
                                iStructureUnitDistThresholdAdjust = iMinDist + 10 - iAdjacentDistThreshold
                            end
                            if iEnemyBestStructureDFRange >= 50 then iAdjacentDistThreshold = math.max(iAdjacentDistThreshold + math.max(0, 5 + iEnemyBestStructureDFRange - (iFriendlyBestMobileDFRange or 0)), 35) end
                            --we adjust the distsances more generally based on the current zone size, so reduce the adj dist threshold based on this
                            if iAdjacentDistThreshold > 10 then iAdjacentDistThreshold = math.max(10, iAdjacentDistThreshold - iAdjacentDistGeneralMod) end
                            bACUInCombatButProbablySafe = false
                            for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                if bHaveACUInTroubleAndRecentlyInCombat == nil then bHaveACUInTroubleAndRecentlyInCombat = false end --so we know we have considered this
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy threat in adjacent zone '..iAdjLZ..'; tbAdjacentZoneEnemiesToIgnoreByZone[iAdjLZ]='..tostring(tbAdjacentZoneEnemiesToIgnoreByZone[iAdjLZ] or false)..'; tbZonesConsidered[iAdjLZ]='..tostring(tbZonesConsidered[iAdjLZ] or false)) end
                                if not(tbAdjacentZoneEnemiesToIgnoreByZone[iAdjLZ]) and not(tbZonesConsidered[iAdjLZ]) then
                                    tbZonesConsidered[iAdjLZ] = true
                                    --If dealing with a core base or an ACU that is in combat then include friendly ACUs
                                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of allied ACUs empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefAlliedACU]))..'; tAdjLZTeamData[AiBotMap.refbACUInTrouble]='..tostring(tAdjLZTeamData[AiBotMap.refbACUInTrouble] or false)..'; Enemy mobile DF in AdjLZ='..(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)..'; Is table of enemy DF units for AdjLZ empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies]))) end
                                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefAlliedACU]) == false then
                                        if not(bHaveACUInTroubleAndRecentlyInCombat) and tAdjLZTeamData[AiBotMap.refbACUInTrouble] and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                            for iACU, oACU in tAdjLZTeamData[AiBotMap.subrefAlliedACU] do
                                                if GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= 10 then
                                                    bHaveACUInTroubleAndRecentlyInCombat = true
                                                    break
                                                end
                                            end
                                        end
                                        for iACU, oACU in tAdjLZTeamData[AiBotMap.subrefAlliedACU] do
                                            if not(oACU.Dead) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': About to consider whether to incrase threat for friendly ACU in adjacent zone') end
                                                IncreaseCombatThreatForACU(oACU, 0.1)
                                                if not(bACUInCombatButProbablySafe) and GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= 2 and AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.95 then
                                                    bACUInCombatButProbablySafe = true
                                                end
                                            end
                                        end
                                    end
                                    AddUnitFromAdjacentZoneToTableIfCloseEnough(tAdjLZTeamData, tNearbyAdjacentEnemies, iAdjacentDistThreshold, iStructureUnitDistThresholdAdjust, iAngleFromClosestFriendlyUnit)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Cumulative threat of tNearbyAdjacentEnemies after updating for iAdjLZ='..iAdjLZ..'='..AiBotUnitInfo.GetCombatThreatRating(tNearbyAdjacentEnemies, false)..'; Mass cost='..AiBotUnitInfo.GetMassCostOfUnits(tNearbyAdjacentEnemies, true)) end
                                end
                            end

                            if AiBotUtilities.IsTableEmpty(tUnitsNearFatboyInFurtherAwayZones) == false then
                                for iEnemy, oEnemy in tUnitsNearFatboyInFurtherAwayZones do
                                    table.insert(tNearbyAdjacentEnemies, oEnemy)
                                end
                            end
                            iEnemyCombatThreat = iEnemyCombatThreat + AiBotUnitInfo.GetCombatThreatRating(tNearbyAdjacentEnemies, false)
                        else
                            if tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 5000 then bAdjustStructureThreat = true end
                            for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                --Only include 20% of enemy structure threat in adjacent zones if we have high threat value
                                if not(tbAdjacentZoneEnemiesToIgnoreByZone[iAdjLZ]) then
                                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                    iEnemyCombatThreat = iEnemyCombatThreat + math.max((tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)*0.5, (tAdjLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0) + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0))
                                    if bAdjustStructureThreat and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will reduce adjacent threat by structure threat, tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]='..repru(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange])) end
                                        for iRange, iThreat in tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                                            if iRange <= 65 then
                                                iEnemyCombatThreat = iEnemyCombatThreat - iThreat * 0.8
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end

                    --Update for water zones with threats
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                        local iAdjWZ, iPond
                        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                            iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                            iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
                            local tAdjWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                            if (tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 0) > 20 then
                                iEnemyCombatThreat = iEnemyCombatThreat + math.max(0, tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] - (tAdjWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0))
                                if bDebugMessages == true then LOG(sFunctionRef..': Factoring in enemy naval threat in iAdjWZ='..iAdjWZ..'; subrefWZThreatEnemyVsSurface='..tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface]..' less subrefWZTThreatAllyCombatTotal='..(tAdjWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 'nil')) end
                            end
                        end
                    end

                    --Update for nearby plateaus with threats
                    if tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] then
                        for iEntry, tPlateauAndZone in tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] do
                            if not(tbZonesConsidered[tPlateauAndZone[2]]) or not(tPlateauAndZone[1] == iPlateau) then --redundancy, in theory shoudlnt be possible for adjacent zone to be recorded as dangerous nearby zone
                                if tPlateauAndZone[1] == iPlateau then
                                    tbZonesConsidered[tPlateauAndZone[2]] = true
                                end
                                iEnemyCombatThreat = iEnemyCombatThreat + GetCombatThreatFromAdjacentZone(AiBotMap.tAllPlateaus[tPlateauAndZone[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndZone[2]][AiBotMap.subrefLZTeamData][iTeam], bAdjustStructureThreat)
                            end
                        end
                    end
                    --If not considered the zone the nearest enemy is in then update for this
                    if oNearestEnemyToFriendlyBase and not(tbZonesConsidered[oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]]) and oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] then
                        if bDebugMessages == true then LOG(sFunctionRef..': Increasing enemy combat threat as nearest enemy isnt in a zone we have considered, iEnemyCombatThreat before adjustment='..iEnemyCombatThreat) end
                        if not(tbZonesConsidered) then tbZonesConsidered = {} end
                        tbZonesConsidered[oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]] = true
                        iEnemyCombatThreat = iEnemyCombatThreat + GetCombatThreatFromAdjacentZone(AiBotMap.tAllPlateaus[oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]][AiBotMap.subrefPlateauLandZones][oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZTeamData][iTeam], false)
                        if bDebugMessages == true then LOG(sFunctionRef..': iEnemyCombatThreat after adjustment='..iEnemyCombatThreat) end
                    end
                end
            end

            function GetAdjacentNearbyMobileDFThreatWithSameZoneTarget(iLikelyTargetZone)
                local tLikelyTargetLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLikelyTargetZone][AiBotMap.subrefLZTeamData][iTeam]
                local iAdjacentMobileDFThreat = 0
                if bDebugMessages == true then LOG(sFunctionRef..': We are likely to be targeting nearest enemy in LZ='..(iLikelyTargetZone or 'nil')..'; is subreftiLandZonesTargetingThisWithOurDF empty='..tostring(AiBotUtilities.IsTableEmpty(tLikelyTargetLZTeamData[AiBotMap.subreftiLandZonesTargetingThisWithOurDF]))) end
                if tLikelyTargetLZTeamData then
                    local tbAdjZoneUnitsInAvailableCombatUnits
                    if AiBotUtilities.IsTableEmpty(tLikelyTargetLZTeamData[AiBotMap.subreftiLandZonesTargetingThisWithOurDF]) == false and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        local tbZonesAdjacentToThis = {}
                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            tbZonesAdjacentToThis[iAdjLZ] = true
                        end
                        local bIncludeCurZoneDF = false
                        for iOtherLZ, iAttackingType in tLikelyTargetLZTeamData[AiBotMap.subreftiLandZonesTargetingThisWithOurDF] do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iOtherLZ='..iOtherLZ..'; tbZonesAdjacentToThis[iOtherLZ]='..tostring(tbZonesAdjacentToThis[iOtherLZ] or false)..'; iLikelyTargetZone='..iLikelyTargetZone) end
                            if tbZonesAdjacentToThis[iOtherLZ] and not(iLikelyTargetZone == iOtherLZ) then
                                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ][AiBotMap.subrefLZTeamData][iTeam]
                                if bDebugMessages == true then LOG(sFunctionRef..': subrefLZThreatAllyMobileDFTotal for otherLZ='..(tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 'nil')..'; OtherLZ subrefLZTValue='..(tAdjLZTeamData[AiBotMap.subrefLZTValue] or 'nil')..'; ThisLandZone subrefLZTValue='..(tLZTeamData[AiBotMap.subrefLZTValue] or 'nil')) end
                                if tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] > 0 then
                                    --Include this zone unless we think we are giving orders to its units in availablecombatunits
                                    bIncludeCurZoneDF = true
                                    if tAdjLZTeamData[AiBotMap.subrefLZTValue] < tLZTeamData[AiBotMap.subrefLZTValue] then
                                        --Higher risk we may be giving orders to units in the adjacent zone
                                        if not(tbAdjZoneUnitsInAvailableCombatUnits) then
                                            tbAdjZoneUnitsInAvailableCombatUnits = {}
                                            for iUnit, oUnit in tAvailableCombatUnits do
                                                if oUnit[refiCurrentAssignmentPlateauAndLZ][2] == iLandZone and not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then tbAdjZoneUnitsInAvailableCombatUnits[oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]] = true end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': tbAdjZoneUnitsInAvailableCombatUnits='..repru(tbAdjZoneUnitsInAvailableCombatUnits)) end
                                        if tbAdjZoneUnitsInAvailableCombatUnits[iOtherLZ] then bIncludeCurZoneDF = false end
                                    end
                                    if bIncludeCurZoneDF then

                                        if iAttackingType == AiBotMap.subrefiLZOrWZTMovingToOtherZone then
                                            --We might have units that are far away, so only include if they are relatively close to our available units, and arent skirmishers
                                            local toUnitsToInclude = {}
                                            local toPotentialUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMobileDFLand - AiBotUnitInfo.refCategorySkirmisher, tAdjLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits])
                                            if AiBotUtilities.IsTableEmpty(toPotentialUnits) == false then
                                                local iClosestFriendlyToOtherZoneDist = 10000
                                                local oClosestFriendlyToOtherZone
                                                local tOtherZoneMidpoint = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ][AiBotMap.subrefMidpoint]
                                                for iUnit, oUnit in tAvailableCombatUnits do
                                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOtherZoneMidpoint)
                                                    if iCurDist < iClosestFriendlyToOtherZoneDist then
                                                        iClosestFriendlyToOtherZoneDist = iCurDist
                                                        oClosestFriendlyToOtherZone = oUnit
                                                    end
                                                end
                                                if oClosestFriendlyToOtherZone then
                                                    for iUnit, oUnit in toPotentialUnits do
                                                        if not(oUnit.Dead) then
                                                            --Are we within 50 of being in range? then include
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Dist between units='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFriendlyToOtherZone:GetPosition())..'; CombatRange='..oUnit[AiBotUnitInfo.refiCombatRange]..'; Dist until in range='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFriendlyToOtherZone:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange]) end
                                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFriendlyToOtherZone:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange] <= 30 then
                                                                table.insert(toUnitsToInclude, oUnit)
                                                            end
                                                        end
                                                    end
                                                    if AiBotUtilities.IsTableEmpty(toUnitsToInclude) == false then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Combat threat of units that are including='..AiBotUnitInfo.GetCombatThreatRating(toUnitsToInclude, false)) end
                                                        iAdjacentMobileDFThreat = iAdjacentMobileDFThreat + AiBotUnitInfo.GetCombatThreatRating(toUnitsToInclude, false)
                                                    end
                                                end
                                            end
                                        else
                                            iAdjacentMobileDFThreat = iAdjacentMobileDFThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0)
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Including threat of friendly DF units in iOtherLZ='..iOtherLZ..', iAdjacentMobileDFThreat after this='..iAdjacentMobileDFThreat) end
                                    end
                                end
                            end
                        end
                    end
                    --Include any units already in the target zone as well
                    if tLikelyTargetLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] > 0 and not(iLikelyTargetZone == iLandZone) then
                        if not(tbAdjZoneUnitsInAvailableCombatUnits) then
                            tbAdjZoneUnitsInAvailableCombatUnits = {}
                            for iUnit, oUnit in tAvailableCombatUnits do
                                if oUnit[refiCurrentAssignmentPlateauAndLZ][2] == iLandZone and not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then tbAdjZoneUnitsInAvailableCombatUnits[oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]] = true end
                            end
                        end
                        if not(tbAdjZoneUnitsInAvailableCombatUnits[iLikelyTargetZone]) then
                            iAdjacentMobileDFThreat = iAdjacentMobileDFThreat + (tLikelyTargetLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0)
                            if bDebugMessages == true then LOG(sFunctionRef..': Including threat of friendly DF units in iLikelyTargetZone, iAdjacentMobileDFThreat after this='..iAdjacentMobileDFThreat) end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iAdjacentMobileDFThreat after including adj zones with the same targetLZ as us='..iAdjacentMobileDFThreat) end


                    --Include hover and amphibious units from an adjacent water zone
                    if AiBotUtilities.IsTableEmpty(tLikelyTargetLZTeamData[AiBotMap.subreftiWaterZonesTargetingThisWithAmphibious]) == false and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                        local tbWaterZonesAdjacentToThis = {}
                        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                            tbWaterZonesAdjacentToThis[tSubtable[AiBotMap.subrefAWZRef]] = true
                        end
                        for iOtherWZ, iAttackingType in tLikelyTargetLZTeamData[AiBotMap.subreftiWaterZonesTargetingThisWithAmphibious] do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iOtherWZ='..iOtherWZ..'; tbWaterZonesAdjacentToThis[iOtherWZ]='..tostring(tbWaterZonesAdjacentToThis[iOtherWZ] or false)..'; iLikelyTargetZone='..iLikelyTargetZone) end
                            if tbWaterZonesAdjacentToThis[iOtherWZ] then
                                local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iOtherWZ]][AiBotMap.subrefPondWaterZones][iOtherWZ][AiBotMap.subrefWZTeamData][iTeam]
                                if bDebugMessages == true then LOG(sFunctionRef..': subrefWZThreatAlliedSurface for otherLZ='..(tAdjWZTeamData[AiBotMap.subrefWZThreatAlliedSurface] or 'nil')..'; is subrefWZTAlliedCombatUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefWZTAlliedCombatUnits]))) end
                                if tAdjWZTeamData[AiBotMap.subrefWZThreatAlliedSurface] > 0 and AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefWZTAlliedCombatUnits]) == false then
                                    --Include this zone unless we think we are giving orders to its units in availablecombatunits
                                    if iAttackingType == AiBotMap.subrefiLZOrWZTMovingToOtherZone then
                                        --We might have units that are far away, so only include if they are relatively close to our available units, and arent skirmishers
                                        local toUnitsToInclude = {}
                                        local toPotentialUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAmphibiousCombat, tAdjWZTeamData[AiBotMap.subrefWZTAlliedCombatUnits])
                                        if AiBotUtilities.IsTableEmpty(toPotentialUnits) == false then
                                            local iClosestFriendlyToOtherZoneDist = 10000
                                            local oClosestFriendlyToOtherZone
                                            local tOtherZoneMidpoint = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iOtherWZ]][AiBotMap.subrefPondWaterZones][iOtherWZ][AiBotMap.subrefMidpoint]
                                            for iUnit, oUnit in tAvailableCombatUnits do
                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOtherZoneMidpoint)
                                                if iCurDist < iClosestFriendlyToOtherZoneDist then
                                                    iClosestFriendlyToOtherZoneDist = iCurDist
                                                    oClosestFriendlyToOtherZone = oUnit
                                                end
                                            end
                                            if oClosestFriendlyToOtherZone then
                                                for iUnit, oUnit in toPotentialUnits do
                                                    if not(oUnit.Dead) then
                                                        --Are we within 50 of being in range? then include
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Dist between WZ unit='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFriendlyToOtherZone:GetPosition())..'; CombatRange='..oUnit[AiBotUnitInfo.refiCombatRange]..'; Dist until in range='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFriendlyToOtherZone:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange]) end
                                                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFriendlyToOtherZone:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange] <= 30 then
                                                            table.insert(toUnitsToInclude, oUnit)
                                                        end
                                                    end
                                                end
                                                if AiBotUtilities.IsTableEmpty(toUnitsToInclude) == false then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Combat threat of units that are including='..AiBotUnitInfo.GetCombatThreatRating(toUnitsToInclude, false)) end
                                                    iAdjacentMobileDFThreat = iAdjacentMobileDFThreat + AiBotUnitInfo.GetCombatThreatRating(toUnitsToInclude, false)
                                                end
                                            end
                                        end
                                    else
                                        --Get threat of hover/amphibious units
                                        local tHoverAndAmphibiousUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAmphibiousCombat, tAdjWZTeamData[AiBotMap.subrefWZTAlliedCombatUnits])
                                        if AiBotUtilities.IsTableEmpty(tHoverAndAmphibiousUnits) == false then
                                            iAdjacentMobileDFThreat = iAdjacentMobileDFThreat + AiBotUnitInfo.GetCombatThreatRating(tHoverAndAmphibiousUnits, false, false)
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Including threat of friendly DF units in iOtherWZ='..iOtherWZ..', iAdjacentMobileDFThreat after this='..iAdjacentMobileDFThreat) end
                                end
                            end
                        end
                    end

                end
                return iAdjacentMobileDFThreat
            end

            if oNearestEnemyToFriendlyBase and AiBotConditions.IsLocationInPlayableArea(oNearestEnemyToFriendlyBase:GetPosition()) then
                if tLZTeamData[AiBotMap.subrefLZbCoreBase] then
                    --Adjust rally points for core base if nearby enemy in case we end up going closer to the enemy instead of furhter away
                    if AiBotUtilities.GetDistanceBetweenPositions(tAmphibiousRallyPoint, tLZData[AiBotMap.subrefMidpoint]) <= 5 then
                        tAmphibiousRallyPoint = AiBotUtilities.MoveInDirection(tLZData[AiBotMap.subrefMidpoint], AiBotUtilities.GetAngleFromAToB(oNearestEnemyToFriendlyBase:GetPosition(), tLZData[AiBotMap.subrefMidpoint]), 40, true, false, true)
                    end
                    if AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, tLZData[AiBotMap.subrefMidpoint]) <= 5 then
                        tRallyPoint = AiBotUtilities.MoveInDirection(tLZData[AiBotMap.subrefMidpoint], AiBotUtilities.GetAngleFromAToB(oNearestEnemyToFriendlyBase:GetPosition(), tLZData[AiBotMap.subrefMidpoint]), 40, true, false, true)
                    end
                end


                --Do we have shot blocked on non-skirmisher units, no indirect fire units, and have signficantly more threat than the enemy or are on an island beachhead? If so then move instead of attakc-moving when attacking
                local bMoveBlockedNotAttackMove = false

                if (iFriendlyBestMobileIndirectRange == 0 or tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] < tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] * 0.2 or iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 3) and (iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 1.75 or tLZTeamData[AiBotMap.refbIslandBeachhead] or (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false and iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 0.9)) then
                    bMoveBlockedNotAttackMove = true
                elseif iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 1.25 and iAvailableCombatUnitThreat >= 10000 and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] < tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] * 0.25 then
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 and not(tFriendlyNearbyExperimentals) then tFriendlyNearbyExperimentals = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental, tAvailableCombatUnits) end
                    if iFriendlyBestMobileDFRange < 65 or (iFriendlyBestMobileDFRange < 75 and AiBotUtilities.IsTableEmpty(tFriendlyNearbyExperimentals) == false) then
                        bMoveBlockedNotAttackMove = true
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished deciding whether to move units whose shot is blocked, tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]..'; Is table of nearby t2 arti empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]))..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; Adjacent zone enemy threat='..GetEnemyCombatThreatInAdjacentZones()..'; iFirebaseThreatAdjust='..iFirebaseThreatAdjust..'; iFriendlyBestMobileDFRange='..iFriendlyBestMobileDFRange) end

                local bConsiderSpecialMMLLogic = false --if this is true then will consider synchronising MML shots and adjusting who they will target from the default
                local tMMLForSynchronisation = {}
                local bOnlyRetreatIndirectIfEnemyDFAlmostInRange = false --if this is true (e.g. dealing with t2 arti and dont want T3 mobile arti to run from low level enemy threats) then indirect fire units should only run from nearest enemy if it is almost in range of them
                if iFriendlyBestMobileIndirectRange > 0 then
                    local iAvailableMMLThreat = 0
                    local tFriendlyMML = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMML, tAvailableCombatUnits)
                    if AiBotUtilities.IsTableEmpty(tFriendlyMML) == false then
                        iAvailableMMLThreat = AiBotUnitInfo.GetMassCostOfUnits(tFriendlyMML)
                    end

                    bConsiderSpecialMMLLogic = AiBotConditions.DoWeWantToSynchroniseMMLShots(iPlateau, iLandZone, tLZData, tLZTeamData, iTeam, iFriendlyBestMobileIndirectRange, iEnemyBestDFRange, iAvailableMMLThreat, oClosestUnitFromAllFirebases)
                    if iAvailableCombatUnitThreat >= 2500 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false and iFriendlyBestMobileIndirectRange >= 40 then
                        --How much available DF threat do we have?
                        local iRoughAvailableDFThreat = 0
                        for iUnit, oUnit in tAvailableCombatUnits do
                            if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat - AiBotUnitInfo.refCategorySkirmisher - AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId) then
                                iRoughAvailableDFThreat = iRoughAvailableDFThreat + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
                                if iRoughAvailableDFThreat >= 1000 then
                                    bOnlyRetreatIndirectIfEnemyDFAlmostInRange = true
                                    break
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iRoughAvailableDFThreat (to max of 1k)='..iRoughAvailableDFThreat..'; bOnlyRetreatIndirectIfEnemyDFAlmostInRange='..tostring(bOnlyRetreatIndirectIfEnemyDFAlmostInRange)) end
                    end
                end

                local bAttackWithSameRange = false
                if ((tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) == 0 or iFriendlyBestMobileDFRange >= 100) and --No long range enemy threat (i.e. t2 arti); and
                        (iFirebaseThreatAdjust == 0 or (iFriendlyBestMobileDFRange >= 100 and iFirebaseThreatAdjust < 6000 and tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 8000) or (not(bRunFromFirebase) and (iFriendlyBestMobileDFRange >= 60 or iFriendlyBestMobileIndirectRange >= 60))) and --No enemy firebase or we have large threat that should be able to overwhelm it; and
                        ((iFriendlyBestMobileDFRange or 0) > (iEnemyBestDFRange or 0) + 2 or --we outrange enemy with our direct fire, or
                                --Important to not increase more than +4 range without more complicated logic, as T1 arti need to engage T1 PD, and outrange T1 PD by 4
                                ((iFriendlyBestMobileIndirectRange or 0) >= (iEnemyBestDFRange or 0) + 4 and ((iEnemyBestStructureDFRange or 0) > 0 or (tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureIndirect] or 0) > 0 or (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] or 0) > 1.4 * (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0)))) then --we have indirect fire with better range than enemy direct fire, and the enemy has structures in this LZ such that we want to attack

                    bAreInScenario1 = true
                    if (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) > 0 or iFirebaseThreatAdjust > 0 then
                        bAttackWithSameRange = true
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Normal scenario 1 criteria satisfied, iFriendlyBestMobileDFRange='..(iFriendlyBestMobileDFRange or 'nil')..'; iEnemyBestDFRange='..(iEnemyBestDFRange or 'nil')..'; iFirebaseThreatAdjust='..(iFirebaseThreatAdjust or 'nil')..'; subrefiNearbyEnemyLongRangeDFThreat='..(tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0)..'; iFriendlyBestMobileIndirectRange='..(iFriendlyBestMobileIndirectRange or 'nil')..'; iEnemyBestStructureDFRange='..(iEnemyBestStructureDFRange or 'nil')..'; subrefLZThreatAllyMobileIndirectTotal='..(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] or 'nil')) end
                elseif iFirebaseThreatAdjust == 0 and (iFriendlyBestMobileDFRange or 0) >= math.max(10, (iEnemyBestDFRange or 0) - 3) then
                    --NOTE: THis isnt the main 'if we outrange closest enemy' logic (which is further on below)
                    local iBestEnemyLRThreatCombatRange = 0
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]) == false then
                        for iUnit, oUnit in tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] do
                            if oUnit[AiBotUnitInfo.refiCombatRange] and oUnit[AiBotUnitInfo.refiCombatRange] > iBestEnemyLRThreatCombatRange then iBestEnemyLRThreatCombatRange = oUnit[AiBotUnitInfo.refiCombatRange] end
                        end
                    end
                    if iFriendlyBestMobileDFRange < iBestEnemyLRThreatCombatRange then
                        if bDebugMessages == true then LOG(sFunctionRef..': We dont match or beat nearest enemy DF range') end
                        --If we significantly outrange the closest enemy unit then should try and kill it
                    elseif  iFriendlyBestMobileDFRange > (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) + 5 and iFriendlyBestMobileDFRange >= iEnemyBestDFRange then --e.g. gattling bots vs hoplites
                        bAreInScenario1 = true
                        bAttackWithSameRange = true
                        if bDebugMessages == true then LOG(sFunctionRef..': We significantly outrange nearest enemy unit and have equivalent DF range overall so will act as though in scenario 1') end
                    elseif not(EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oNearestEnemyToFriendlyBase.UnitId)) then --i.e. nearest enemy is a mobile enemy with (likely) the same or slightly better range than us
                        --Do we have significantly more threat than enemy at the highest range?
                        local iEnemyBestRangeDFThreat = 0
                        local iOurBestRangeDFThreat = 0
                        local iRangeThreshold = math.min(iFriendlyBestMobileDFRange, iEnemyBestDFRange)
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange]) == false then
                            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] do
                                if iRange >= iRangeThreshold then
                                    iOurBestRangeDFThreat = iThreat
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]) == false then
                            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange] do
                                if iRange >= iRangeThreshold then
                                    iEnemyBestRangeDFThreat = iThreat
                                end
                            end
                        end
                        --Consider enemy LR threat in adjacent zones if we might have enough threat
                        if iOurBestRangeDFThreat > 1.5 * iEnemyBestRangeDFThreat then
                            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]) == false then
                                        for iRange, iThreat in tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange] do
                                            if iRange >= iRangeThreshold then
                                                iEnemyBestRangeDFThreat = iEnemyBestRangeDFThreat + iThreat
                                            end
                                        end
                                    end
                                end
                            end
                            if iOurBestRangeDFThreat > 1.5 * iEnemyBestRangeDFThreat then
                                bAreInScenario1 = true
                                if bDebugMessages == true then LOG(sFunctionRef..': We have significantly more threat than enemy at the longer rnage so will act as though are in scenario 1 so we just attack with our longer ranged units, iRangeThreshold='..iRangeThreshold) end
                                iDFRangeOverrideForScenario1 = iFriendlyBestMobileDFRange
                                bAttackWithSameRange = true
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': If are in scenario 1 will consider disabling if we cant see the nearest enemy, or if it is a naval unit and we dont significantly outrange it, bAreInScenario1='..tostring(bAreInScenario1)..'; oNearestEnemyToFriendlyBase='..(oNearestEnemyToFriendlyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase) or 'nil')..'; iFirebaseThreatAdjust='..iFirebaseThreatAdjust..'; tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]='..(tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 'nil')..'; iFriendlyBestMobileDFRange='..iFriendlyBestMobileDFRange..'; iEnemyBestDFRange='..iEnemyBestDFRange..'; iFriendlyBestMobileIndirectRange='..iFriendlyBestMobileIndirectRange..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat)
                    if oNearestEnemyToFriendlyBase then LOG(sFunctionRef..': Can see oNearestEnemyToFriendlyBase='..tostring(AiBotUnitInfo.CanSeeUnit(ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]], oNearestEnemyToFriendlyBase, false))..'; tLZTeamData[AiBotMap.refiRadarCoverage]='..tLZTeamData[AiBotMap.refiRadarCoverage]) end
                end
                if bAreInScenario1 and oNearestEnemyToFriendlyBase then
                    local iUnitSegmentX, iUnitSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oNearestEnemyToFriendlyBase:GetPosition())
                    if AiBotMap.tWaterZoneBySegment[iUnitSegmentX][iUnitSegmentZ] then
                        bAreInScenario1 = false
                        local iBestRange = math.max(iFriendlyBestMobileDFRange, iFriendlyBestMobileIndirectRange)
                        local tLandPoint = AiBotUtilities.MoveInDirection(oNearestEnemyToFriendlyBase:GetPosition(), AiBotUtilities.GetAngleFromAToB(oNearestEnemyToFriendlyBase:GetPosition(), tLZData[AiBotMap.subrefMidpoint]), iBestRange, true, false, not(AiBotMap.bIsCampaignMap))
                        if tLandPoint and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLandPoint) == tLZData[AiBotMap.subrefLZIslandRef] then
                            bAreInScenario1 = true
                        else
                            --Check if we have hover units or antinavy units that outrange them
                            local tFriendlyHover = EntityCategoryFilterDown(categories.HOVER + categories.ANTINAVY, tAvailableCombatUnits)

                            if AiBotUtilities.IsTableEmpty(tFriendlyHover) == false then
                                for iHover, oHover in tFriendlyHover do
                                    if bDebugMessages == true then LOG(sFunctionRef..': oHover or antinavy='..oHover.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oHover)..' with antinavy range='.. (oHover[AiBotUnitInfo.refiAntiNavyRange] or 0)..' and DF range='..(oHover[AiBotUnitInfo.refiDFRange] or 'nil')) end
                                    if (oHover[AiBotUnitInfo.refiAntiNavyRange] or 0) > iEnemyBestDFRange or ((oHover[AiBotUnitInfo.refiDFRange] or 0) > iEnemyBestDFRange and EntityCategoryContains(categories.HOVER, oHover.UnitId)) then
                                        bAreInScenario1 = true
                                        break
                                    end
                                end
                            end
                            if not(bAreInScenario1) then
                                --Do we have units with a better range than enemy navy range? in which case change the nearest enemy to be a land unit if is one, or clear altogether so we can reinforce other zones
                                local iWaterZone = AiBotMap.tWaterZoneBySegment[iUnitSegmentX][iUnitSegmentZ]
                                local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
                                local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                                if iBestRange > tWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] then
                                    bAreInScenario1 = true
                                    --ignore navy and look for other targets
                                    if bDebugMessages == true then LOG(sFunctionRef..': clearing nearest enemy as it is a naval unit we outrange but cant reach, will look for land based targets instead') end
                                    oNearestEnemyToFriendlyBase = nil
                                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                        oNearestEnemyToFriendlyBase = AiBotUtilities.GetNearestUnit(tLZTeamData[AiBotMap.subrefTEnemyUnits], tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                        if bDebugMessages == true then LOG(sFunctionRef..': Changing oNearestEnemyToFriendlyBase to a unit in the current zone='..oNearestEnemyToFriendlyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase)) end
                                    elseif AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                            local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                            local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                            if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                                oNearestEnemyToFriendlyBase = AiBotUtilities.GetNearestUnit(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits], tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                                if bDebugMessages == true then LOG(sFunctionRef..': CHanging oNearestEnemyToFriendlyBase to a unit in iAdjLZ='..iAdjLZ..'; unit='..oNearestEnemyToFriendlyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase)) end
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': We think we are in scenario 1 but nearest enemy is in the water, checking if we can hit them if we move towards them, Island ref (if is one)='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLandPoint) or 'nil')..'; This zone island ref='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; bAreInScenario1 after checking this='..tostring(bAreInScenario1)) end

                    end
                    if bAreInScenario1 and oNearestEnemyToFriendlyBase and not(AiBotUnitInfo.CanSeeUnit(ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]], oNearestEnemyToFriendlyBase, false)) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oNearestEnemyToFriendlyBase.UnitId)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': we dont have intel of the closest enemy so dont want to be in scenario 1 afterall (unless we have friendly ACU  or land scout in this zone or the zone with the nearest enemy, and not dealing with very long range units), will flag that we lack intel, nearest enemy combat range='..(oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] or 'nil')..'; Dist between last known position and actual position='..AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; iFriendlyBestMobileIndirectRange='..iFriendlyBestMobileIndirectRange..'; iEnemyBestDFRange='..(iEnemyBestDFRange or 'nil')) end
                        bAreInScenario1 = false
                        if tLZTeamData[AiBotMap.refiRadarCoverage] < iIntelThresholdForPriorityScout then
                            tLZTeamData[AiBotMap.refiTimeLastFailedToKiteDueToScoutIntel] = GetGameTimeSeconds()
                        end
                        if AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 3 then
                            bAreInScenario1 = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Unit hasnt moved much from when we last had intel so reasonable to assume AI would infer roughly where it is') end
                        else
                            if iFriendlyBestMobileIndirectRange > (iEnemyBestDFRange or 0) then
                                local iActualDistToMidpoint = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                local iExpectedDistToMidpoint = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], tLZData[AiBotMap.subrefMidpoint])
                                if bDebugMessages == true then LOG(sFunctionRef..': iActualDistToMidpoint='..iActualDistToMidpoint..'; iExpectedDistToMidpoint='..iExpectedDistToMidpoint) end
                                if iActualDistToMidpoint >= iExpectedDistToMidpoint then
                                    bAreInScenario1 = true
                                    if bDebugMessages == true then LOG(sFunctionRef..': We have indirect fire units, and enemy isnt any closer to our midpoint than we would expect from the last known position, so a chance we can get some lucky hits on other units based on where we recalled them being since we outrange them') end
                                end
                            end
                            if not(bAreInScenario1) and oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] <= 45 then

                                local iNearestEnemyPlateau, iNearestEnemyZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oNearestEnemyToFriendlyBase:GetPosition())
                                if not(iNearestEnemyZone == iLandZone) and iNearestEnemyPlateau == iPlateau then
                                    local tNearestEnemyTeamData = AiBotMap.tAllPlateaus[iNearestEnemyPlateau][AiBotMap.subrefPlateauLandZones][iNearestEnemyZone][AiBotMap.subrefLZTeamData][iTeam]
                                    if AiBotUtilities.IsTableEmpty(tNearestEnemyTeamData[AiBotMap.subrefAlliedACU]) == false then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have friendly ACU in the same zone as nearest enemy so will actually stick to being scenario 1') end
                                        bAreInScenario1 = true
                                    end --subrefLZTAlliedCombatUnits
                                elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) == false and iNearestEnemyZone == iLandZone then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have friendly ACU in this zone which enemy is in, so will actually stick to being scenario 1') end
                                    bAreInScenario1 = true
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': bAreInScenario1 before checking for short range nearest enemy='..tostring(bAreInScenario1)..'; refiCombatRange of nearest enemy='.. oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange]..'; Do we have 24+ radar or visual range='..tostring(AiBotConditions.HaveMinimumVisualOrRadarRange(tAvailableCombatUnits, 24))) end
                                if not(bAreInScenario1) and oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] <= 20 and (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] <= 18 or AiBotConditions.HaveMinimumVisualOrRadarRange(tAvailableCombatUnits, 24)) then
                                    --Good chance we can get visual on the nearest enemy, check if are other enemies that are close to it who do have a decent combat range, and which we cant see
                                    bAreInScenario1 = true
                                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                        local iThresholdForNearbyEnemyDFRange = (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] or 0) + 3
                                        local iNearestEnemyRange = (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] or 0)
                                        if iThresholdForNearbyEnemyDFRange > 24 and not(AiBotConditions.HaveMinimumVisualOrRadarRange(tAvailableCombatUnits, iThresholdForNearbyEnemyDFRange))  then  iThresholdForNearbyEnemyDFRange = math.max(24, oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] + 5) end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Checking for longer ranged nearby enemy units, iThresholdForNearbyEnemyDFRange='..iThresholdForNearbyEnemyDFRange) end
                                        for iEnemy, oEnemy in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                            if not(oEnemy == oNearestEnemyToFriendlyBase) and (oEnemy[AiBotUnitInfo.refiDFRange] or 0) >= iThresholdForNearbyEnemyDFRange and AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - oEnemy[AiBotUnitInfo.refiDFRange] + iNearestEnemyRange <= 2 and not(AiBotUnitInfo.CanSeeUnit(aiBrain, oEnemy)) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; Dist to nearestenemytofriendlybase='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())..'; iNearestEnemyRange='..iNearestEnemyRange..'; This unit range='..oEnemy[AiBotUnitInfo.refiDFRange]..' so since cant see nearest enemy will exit scenario 1') end
                                                bAreInScenario1 = false
                                                break
                                            end
                                        end
                                    end

                                end
                            end
                        end
                    end
                end
                --If we outrange nearest enemy unit (both DF and IF), then lower the DF range requirement for units to try and kite it, and consider going into scenario 1 even if we wouldnt normally
                if oNearestEnemyToFriendlyBase and (iFriendlyBestMobileDFRange > (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) or (oNearestEnemyToFriendlyBase:IsUnitState('Upgrading') and (bAreInScenario1 or iFriendlyBestMobileIndirectRange > oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange])) or (iFriendlyBestMobileIndirectRange > iEnemyBestDFRange + 10 and iFriendlyBestMobileIndirectRange > oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] and AiBotUnitInfo.CanSeeUnit(ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]], oNearestEnemyToFriendlyBase, false)))
                        and (not(bAreInScenario1) or math.max(iFriendlyBestMobileDFRange, iFriendlyBestMobileIndirectRange) > (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) + 6) and oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau and iFirebaseThreatAdjust == 0
                        and ((oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) < iEnemyBestDFRange or (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) < iFriendlyBestMobileIndirectRange)
                then
                    --If enemy has LR threat then get range of this
                    local iBestEnemyLRThreatCombatRange = 0
                    local iEnemyRangeThreshold = (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 5)
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false then
                        for iUnit, oUnit in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
                            if oUnit[AiBotUnitInfo.refiCombatRange] and oUnit[AiBotUnitInfo.refiCombatRange] > iBestEnemyLRThreatCombatRange then iBestEnemyLRThreatCombatRange = oUnit[AiBotUnitInfo.refiCombatRange] end
                        end
                    end
                    --Get the zone the nearest enemy is in (so we can reference DF units in that zone)
                    local tNearestEnemyLZTeamData
                    if oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone then
                        tNearestEnemyLZTeamData = tLZTeamData
                    else
                        tNearestEnemyLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZTeamData][iTeam]
                    end
                    --How close is an enemy unit to being in range of the nearest enemy (i.e. negative value means it can attack our units once they get this distance away)
                    local iClosestDistLessRange = 10000
                    local iCurDistToClosestEnemy, iCurDistToFriendlyBase, iCurModDistLessRange
                    local iClosestEnemyDistToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                    if AiBotUtilities.IsTableEmpty(tNearestEnemyLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                        for iEnemy, oEnemy in tNearestEnemyLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                            --Only consider enemies that outrange the nearest enemy (since if they're the same or less range then we can kite them with the same units that can kite the nearest enemy)
                            if bDebugMessages == true then LOG(sFunctionRef..': considering how close nearby DF units are to closest enemy, factoring in their range, oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; DF range='..(oEnemy[AiBotUnitInfo.refiDFRange] or 'nil')..'; iEnemyRangeThreshold='..(iEnemyRangeThreshold or 'nil')..'; Dist between positions='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oNearestEnemyToFriendlyBase:GetPosition())..'; iClosestDistLessRange before update='..(iClosestDistLessRange or 'nil')) end
                            if (oEnemy[AiBotUnitInfo.refiDFRange] or 0) > iEnemyRangeThreshold then
                                iCurDistToClosestEnemy = AiBotUtilities.GetDistanceBetweenPositions(oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oNearestEnemyToFriendlyBase:GetPosition())
                                iCurDistToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                --Enemy unit might be say 30 to the nearest enemy, but a friendly unit attacking the nearest enemy might be less than 30 additional distance to the enemy; as a rough proxy will therefore go with 50% of this (so double the differential in dist to closest base)
                                iCurModDistLessRange = math.min(iCurDistToClosestEnemy, math.max(1, iCurDistToClosestEnemy - (oEnemy[AiBotUnitInfo.refiDFRange] or 0), (iClosestEnemyDistToFriendlyBase - iCurDistToFriendlyBase) * 2)) - oEnemy[AiBotUnitInfo.refiDFRange]
                                if iCurModDistLessRange < iClosestDistLessRange then iClosestDistLessRange = iCurModDistLessRange end
                            end
                        end
                    end
                    --Check nearby IF threats
                    if not(bAreInScenario1) and iClosestDistLessRange > 0 and AiBotUtilities.IsTableEmpty(tNearestEnemyLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                        for iEnemy, oEnemy in tNearestEnemyLZTeamData[AiBotMap.subrefTEnemyUnits] do
                            --Only consider enemies that outrange the nearest enemy (since if they're the same or less range then we can kite them with the same units that can kite the nearest enemy)
                            if bDebugMessages == true then LOG(sFunctionRef..': considering how close nearby IF units are to closest enemy, factoring in their range, oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; DF range='..(oEnemy[AiBotUnitInfo.refiDFRange] or 'nil')..'; iEnemyRangeThreshold='..(iEnemyRangeThreshold or 'nil')..'; Dist between positions='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oNearestEnemyToFriendlyBase:GetPosition())..'; iClosestDistLessRange before update='..(iClosestDistLessRange or 'nil')) end
                            if oEnemy[AiBotUnitInfo.refiIndirectRange] and oEnemy[AiBotUnitInfo.refiIndirectRange] > iEnemyRangeThreshold and oEnemy[AiBotUnitInfo.refiIndirectRange] > (oEnemy[AiBotUnitInfo.refiDFRange] or 0) then
                                iCurDistToClosestEnemy = AiBotUtilities.GetDistanceBetweenPositions(oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oNearestEnemyToFriendlyBase:GetPosition())
                                iCurDistToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                --Enemy unit might be say 30 to the nearest enemy, but a friendly unit attacking the nearest enemy might be less than 30 additional distance to the enemy; as a rough proxy will therefore go with 50% of this (so double the differential in dist to closest base)
                                iCurModDistLessRange = math.min(iCurDistToClosestEnemy, math.max(1, iCurDistToClosestEnemy - oEnemy[AiBotUnitInfo.refiCombatRange], (iClosestEnemyDistToFriendlyBase - iCurDistToFriendlyBase) * 2)) - oEnemy[AiBotUnitInfo.refiCombatRange]
                                if iCurModDistLessRange < iClosestDistLessRange then iClosestDistLessRange = iCurModDistLessRange end
                            end
                        end
                    end
                    --Check LR threats
                    if iBestEnemyLRThreatCombatRange > 0 and iBestEnemyLRThreatCombatRange + 3 >= iFriendlyBestMobileDFRange and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false then
                        for iEnemy, oEnemy in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
                            iCurDistToClosestEnemy = AiBotUtilities.GetDistanceBetweenPositions(oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oNearestEnemyToFriendlyBase:GetPosition())
                            iCurDistToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                            --Enemy unit might be say 30 to the nearest enemy, but a friendly unit attacking the nearest enemy might be less than 30 additional distance to the enemy; as a rough proxy will therefore go with 50% of this (so double the differential in dist to closest base)
                            iCurModDistLessRange = math.min(iCurDistToClosestEnemy, math.max(1, iCurDistToClosestEnemy - (oEnemy[AiBotUnitInfo.refiDFRange] or 0), (iClosestEnemyDistToFriendlyBase - iCurDistToFriendlyBase) * 2)) - oEnemy[AiBotUnitInfo.refiCombatRange]
                            if iCurModDistLessRange < iClosestDistLessRange then iClosestDistLessRange = iCurModDistLessRange end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iClosestDistLessRange after checking DF, IF and LR units='..iClosestDistLessRange) end
                    local iFriendlyDFRangeThresholdBasedOnAbove
                    if iClosestDistLessRange * -1 + 8 > (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] or 0) then
                        iFriendlyDFRangeThresholdBasedOnAbove = iClosestDistLessRange * -1 + 8
                        if bDebugMessages == true then LOG(sFunctionRef..': Updating range threshold for +8, iFriendlyDFRangeThresholdBasedOnAbove='..iFriendlyDFRangeThresholdBasedOnAbove..'; iClosestDistLessRange='..iClosestDistLessRange) end
                    else
                        iFriendlyDFRangeThresholdBasedOnAbove = (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) + 3
                        if bDebugMessages == true then LOG(sFunctionRef..': Updating range threshold for +3, iFriendlyDFRangeThresholdBasedOnAbove='..iFriendlyDFRangeThresholdBasedOnAbove..'; iClosestDistLessRange='..iClosestDistLessRange) end
                    end

                    if iDFRangeOverrideForScenario1 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Updating threshold to the lower of iDFRangeOverrideForScenario1 and iFriendlyDFRangeThresholdBasedOnAbove, iDFRangeOverrideForScenario1='..iDFRangeOverrideForScenario1..'; iFriendlyDFRangeThresholdBasedOnAbove='..iFriendlyDFRangeThresholdBasedOnAbove) end
                        iDFRangeOverrideForScenario1 = math.min(iDFRangeOverrideForScenario1, iFriendlyDFRangeThresholdBasedOnAbove)
                    elseif bAreInScenario1 and iFriendlyBestMobileDFRange > iEnemyBestDFRange + 2 then
                        iDFRangeOverrideForScenario1 = math.min(iFriendlyDFRangeThresholdBasedOnAbove, iEnemyBestDFRange + 2)
                        if bDebugMessages == true then LOG(sFunctionRef..': Are in scenario 1 so making lower of enemy range and the other values, iDFRangeOverrideForScenario1='..(iDFRangeOverrideForScenario1 or 'nil')..'; iFriendlyBestMobileDFRange='..iFriendlyBestMobileDFRange..'; iEnemyBestDFRange='..iEnemyBestDFRange) end
                    elseif bAreInScenario1 and iFriendlyBestMobileIndirectRange > iEnemyBestDFRange + 3 then
                        iDFRangeOverrideForScenario1 = math.min(iFriendlyDFRangeThresholdBasedOnAbove, iFriendlyBestMobileIndirectRange)
                    else
                        iDFRangeOverrideForScenario1 = iFriendlyDFRangeThresholdBasedOnAbove
                        --Disable scenario1 flag as althoguh we outrange the enemy it isnt by much and so we could end up in scenario where we have no units better than this
                        if iDFRangeOverrideForScenario1 > iFriendlyBestMobileIndirectRange and iDFRangeOverrideForScenario1 > iFriendlyBestMobileDFRange then
                            bAreInScenario1 = false
                            if bDebugMessages == true then LOG(sFunctionRef..': Disabling the scenario 1 flag given we dont outrange enemy by much and not by enough for the desired override') end
                        end
                    end
                    if not(bAreInScenario1) then
                        --If enemy has nearby DF or IF units that are within range of the closest enemy unit, then check that we still have units that significantly outrange these to switch to scenario 1
                        if iClosestDistLessRange < 0 and iClosestDistLessRange * -1 > math.max(iFriendlyBestMobileIndirectRange + 10, iFriendlyBestMobileDFRange + 5) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy ahs DF or IF that are too close to the nearest enemy so we cant safely attack nearest enemy') end
                        elseif iFriendlyBestMobileDFRange > iDFRangeOverrideForScenario1 then
                            bAreInScenario1 = true
                        elseif iFriendlyBestMobileIndirectRange > iDFRangeOverrideForScenario1 + 5 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Our indirectfire outranges their units so will proceed with scenario 1 logic') end
                            bAreInScenario1 = true
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished checking if we think closest enemy unit is vulnerable to a kiting attack, bAreInScenario1='..tostring(bAreInScenario1 or false)..'; iDFRangeOverrideForScenario1='..(iDFRangeOverrideForScenario1 or 'nil')..'; nearest enemy unit state='..AiBotUnitInfo.GetUnitState(oNearestEnemyToFriendlyBase)) end
                end

                function ConsiderManualAttackInsteadOfAttackMove(oUnit, oUnitTarget, tAttackMovePosition, iOrderDistanceReassess, sOrderBaseDesc)
                    --Intended where units have an attackmove range that is shorter than their main combat range
                    local bGivenManualAttack = false
                    local toPotentialTargets = {}
                    local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnitTarget:GetPosition())
                    local aiBrain = oUnit:GetAIBrain()
                    if iDistToTarget <= oUnit[AiBotUnitInfo.refiCombatRange] and iDistToTarget > oUnit[AiBotUnitInfo.refiWeaponScanRange] and AiBotUnitInfo.CanSeeUnit(aiBrain, oUnitTarget, false) then
                        table.insert(toPotentialTargets, oUnitTarget)
                    end
                    if AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and not(oUnitTarget == oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) then
                        iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())
                        if iDistToTarget <= oUnit[AiBotUnitInfo.refiCombatRange] and  iDistToTarget > oUnit[AiBotUnitInfo.refiWeaponScanRange] and AiBotUnitInfo.CanSeeUnit(aiBrain, oUnitTarget, false) then
                            table.insert(toPotentialTargets, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])
                        end
                    end
                    --Consider each unit weapon and its current target, if there is one
                    if oUnit.WeaponInstances then
                        for iWeapon, oWeapon in oUnit.WeaponInstances do
                            if oWeapon.GetCurrentTarget then
                                local oCurTarget = oWeapon:GetCurrentTarget()
                                if AiBotUnitInfo.IsUnitValid(oCurTarget) and EntityCategoryContains(categories.ALLUNITS - AiBotUnitInfo.refCategoryAllAir - AiBotUnitInfo.refCategorySubmarine, oCurTarget.UnitId) then
                                    table.insert(toPotentialTargets, oCurTarget)
                                end
                            end
                        end
                    end
                    --If we had an attack order before consider this as well
                    local oLastUnitTarget = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]][AiBotOrders.subrefoOrderUnitTarget]
                    if AiBotUnitInfo.IsUnitValid(oLastUnitTarget) then
                        iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oLastUnitTarget:GetPosition())
                        if iDistToTarget <= oUnit[AiBotUnitInfo.refiCombatRange] and  iDistToTarget > oUnit[AiBotUnitInfo.refiWeaponScanRange] and AiBotUnitInfo.CanSeeUnit(aiBrain, oLastUnitTarget, false) then
                            table.insert(toPotentialTargets, oLastUnitTarget)
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(toPotentialTargets) == false then
                        --Target the highest mass cost unit in potential targets
                        local iHighestMassCost = 30 --dont bother manual attacks for cheaper units than this
                        local oUnitToManuallyAttack
                        for iPotentialUnit, oPotentialUnit in toPotentialTargets do
                            if oPotentialUnit[AiBotUnitInfo.refiUnitMassCost] > iHighestMassCost then
                                oUnitToManuallyAttack = oPotentialUnit
                                iHighestMassCost = oPotentialUnit[AiBotUnitInfo.refiUnitMassCost]
                            end
                        end
                        if oUnitToManuallyAttack then
                            bGivenManualAttack = true
                            AiBotOrders.IssueTrackedAttack(oUnit, oUnitToManuallyAttack, false, sOrderBaseDesc..'mA', false)
                        end
                    end
                    if not(bGivenManualAttack) then
                        AiBotOrders.IssueTrackedAttackMove(oUnit, tAttackMovePosition, iOrderDistanceReassess, false, sOrderBaseDesc..'m'..iLandZone, false)
                    end
                end

                function ProtectFriendlyACUInTroubleIfRelevant(tUnitsToConsiderAndUpdate)
                    --If have an ACU in trouble then sends non-skrimisher DF units in tUnitsToConsiderAndUpdate to protect the ACU
                    local toFriendlyACUsNearby = {}
                    if bDebugMessages == true then LOG(sFunctionRef..': ProtectFriendlyACUInTroubleIfRelevant: bHaveACUInTroubleAndRecentlyInCombat==nil='..tostring(bHaveACUInTroubleAndRecentlyInCombat==nil)..'; bHaveACUInTroubleAndRecentlyInCombat == true='..tostring(bHaveACUInTroubleAndRecentlyInCombat or false)..'; oNearestEnemyToFriendlyBase='..(oNearestEnemyToFriendlyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase) or 'nil')) end
                    if oNearestEnemyToFriendlyBase and (bHaveACUInTroubleAndRecentlyInCombat == nil or bHaveACUInTroubleAndRecentlyInCombat) then --we havent considered properly if there are ACUs in danger if this is nil
                        --Check this and adjacent zones for if ACU in trouble, and if so then populate
                        if tLZTeamData[AiBotMap.refbACUInTrouble] and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) == false then
                            bHaveACUInTroubleAndRecentlyInCombat = true
                            for iACU, oACU in tLZTeamData[AiBotMap.subrefAlliedACU] do
                                if not(oACU.Dead) then table.insert(toFriendlyACUsNearby, oACU) end
                            end
                        end
                        --Consider adjacent zones
                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then --and AiBotUtilities.IsTableEmpty(toFriendlyACUsNearby) then
                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                if tAdjLZTeamData[AiBotMap.refbACUInTrouble] and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefAlliedACU]) == false then
                                    bHaveACUInTroubleAndRecentlyInCombat = true
                                    for iACU, oACU in tAdjLZTeamData[AiBotMap.subrefAlliedACU] do
                                        if not(oACU.Dead) then table.insert(toFriendlyACUsNearby, oACU) end
                                    end
                                end
                            end
                        end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': ProtectFriendlyACUInTroubleIfRelevant: Is table of ACUs in this LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]))..'; Is bACUInCombatButProbablySafe nil='..tostring(bACUInCombatButProbablySafe == nil)..'; bACUInCombatButProbablySafe='..tostring(bACUInCombatButProbablySafe or false)) end
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) == false then
                            for iACU, oACU in tLZTeamData[AiBotMap.subrefAlliedACU] do
                                if bDebugMessages == true then LOG(sFunctionRef..': Time since ACU owned by '..oACU:GetAIBrain().Nickname..' time since fired weapon='..GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; Health%='..AiBotUnitInfo.GetUnitHealthPercent(oACU)) end
                                if GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= 2 and AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.95 then
                                    bACUInCombatButProbablySafe = true
                                    table.insert(toFriendlyACUsNearby, oACU)
                                end
                            end
                        end
                        if (bACUInCombatButProbablySafe == nil or bACUInCombatButProbablySafe) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                if bDebugMessages == true then LOG(sFunctionRef..': Is ACUs in iAdjLZ='..iAdjLZ..'empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefAlliedACU]))) end
                                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefAlliedACU]) == false then
                                    for iACU, oACU in tAdjLZTeamData[AiBotMap.subrefAlliedACU] do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Adj zone ACU, owned by '..oACU:GetAIBrain().Nickname..' time since fired weapon='..GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; Health%='..AiBotUnitInfo.GetUnitHealthPercent(oACU)) end
                                        if not(oACU.Dead) and GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= 2 and AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.95 then
                                            table.insert(toFriendlyACUsNearby, oACU)
                                            bACUInCombatButProbablySafe = true
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': bHaveACUInTroubleAndRecentlyInCombat='..tostring(bHaveACUInTroubleAndRecentlyInCombat)..'; Is table of friendly ACUs nearby='..tostring(AiBotUtilities.IsTableEmpty(toFriendlyACUsNearby))..'; bACUInCombatButProbablySafe='..tostring(bACUInCombatButProbablySafe)) end
                    local oACUToProtect
                    local oOptionalEnemyToBeCloserTo
                    local iACUDistToEnemy
                    if bHaveACUInTroubleAndRecentlyInCombat and AiBotUtilities.IsTableEmpty(toFriendlyACUsNearby) == false then
                        local iLowestHealthACU = 100000
                        for iACU, oACU in toFriendlyACUsNearby do
                            --Get lowest health ACU in this or adj zone that we can path to
                            if oACU:GetHealth() < iLowestHealthACU and oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau and  AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZIslandRef] == tLZData[AiBotMap.subrefLZIslandRef] then
                                iLowestHealthACU = oACU:GetHealth()
                                oACUToProtect = oACU
                            end
                        end
                    elseif bACUInCombatButProbablySafe and AiBotUtilities.IsTableEmpty(toFriendlyACUsNearby) == false then
                        --Get closest DF enemy to the ACU; if it's relatively close to being in range of the ACU then attack-move with units that are a bit further away
                        local oNearestACUToEnemy
                        local iCurDist
                        local iClosestACUToEnemy = 10000
                        for iACU, oACU in toFriendlyACUsNearby do
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())
                            if iCurDist < iClosestACUToEnemy then
                                iClosestACUToEnemy = iCurDist
                                oNearestACUToEnemy = oACU
                            end
                        end
                        local oEnemyNearACU
                        --Get the closest DF enemy to enemy ACU
                        if iClosestACUToEnemy < (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) + 1 then
                            oEnemyNearACU = oNearestEnemyToFriendlyBase
                        elseif AiBotUtilities.IsTableEmpty(tSkirmisherDFEnemies) == false then
                            local iClosestDFEnemyDistLessRange = 1 --i.e. attack if enemy is within 1 of being in range of our ACU                            for iEnemy, oEnemy in tSkirmisherDFEnemies do
                            for iEnemy, oEnemy in tSkirmisherDFEnemies do
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oNearestACUToEnemy:GetPosition(), oEnemy:GetPosition()) - (oEnemy[AiBotUnitInfo.refiDFRange] or 0)
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..' with DF range='..(oEnemy[AiBotUnitInfo.refiDFRange] or 0)..'; Dist to ACU='..AiBotUtilities.GetDistanceBetweenPositions(oNearestACUToEnemy:GetPosition(), oEnemy:GetPosition())) end
                                if iCurDist < iClosestDFEnemyDistLessRange then
                                    iClosestDFEnemyDistLessRange = iCurDist
                                    oEnemyNearACU = oEnemy
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': oNearestACUToEnemy owner='..oNearestACUToEnemy:GetAIBrain().Nickname..'; oEnemyNearACU='..(oEnemyNearACU.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEnemyNearACU) or 'nil')) end
                        if oEnemyNearACU then
                            oACUToProtect = oNearestACUToEnemy
                            oOptionalEnemyToBeCloserTo = oEnemyNearACU

                            if bDebugMessages == true then LOG(sFunctionRef..': Will send DF units to attack as our ACU is in combat and not on full health, but will attack-move and try and stay behind our ACU, oACUToProtect owner='..oACUToProtect:GetAIBrain().Nickname..'; oOptionalEnemyToBeCloserTo='..oOptionalEnemyToBeCloserTo.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOptionalEnemyToBeCloserTo)) end
                        end
                    end
                    if oACUToProtect then
                        local iCombatUnitsTableSize = table.getn(tUnitsToConsiderAndUpdate)
                        local iDistInfrontOfACUWanted
                        local tProtectiveMovePoint
                        local iOptionalMinDistToNearestEnemy
                        if oOptionalEnemyToBeCloserTo then
                            iACUDistToEnemy = AiBotUtilities.GetDistanceBetweenPositions(oACUToProtect:GetPosition(), oOptionalEnemyToBeCloserTo:GetPosition())
                            iOptionalMinDistToNearestEnemy = iACUDistToEnemy + 4
                            iDistInfrontOfACUWanted = math.max(5, iACUDistToEnemy - 5)
                            tProtectiveMovePoint = AiBotUtilities.MoveInDirection(oACUToProtect:GetPosition(), AiBotUtilities.GetAngleFromAToB(oACUToProtect:GetPosition(), oOptionalEnemyToBeCloserTo:GetPosition()), iDistInfrontOfACUWanted, true, false, AiBotMap.bIsCampaignMap)
                        else
                            iDistInfrontOfACUWanted = math.min(20, 5 + iCombatUnitsTableSize * 0.25)
                            tProtectiveMovePoint = AiBotUtilities.MoveInDirection(oACUToProtect:GetPosition(), AiBotUtilities.GetAngleFromAToB(tLZTeamData[AiBotMap.reftClosestFriendlyBase], oACUToProtect:GetPosition()), iDistInfrontOfACUWanted, true, false, AiBotMap.bIsCampaignMap)
                        end
                        local iAltPlateau, iAltLandZone
                        if tProtectiveMovePoint then iAltPlateau, iAltLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tProtectiveMovePoint) end
                        if not(iAltPlateau == iPlateau) then
                            --GetPositionAtOrNearTargetInPathingGroup(tStartPos,                 tTargetPos,            iDistanceFromTargetToStart, iAngleAdjust, oPathingUnit, bMoveCloserBeforeFurtherIfBlocked, bCheckIfExistingTargetIsBetter, iMinDistanceFromExistingCommandTarget)
                            tProtectiveMovePoint = AiBotMap.GetPositionAtOrNearTargetInPathingGroup(tProtectiveMovePoint,         oACUToProtect:GetPosition(),        iDistInfrontOfACUWanted,  0,    oACUToProtect,       true,                              false,                           nil)
                            if not(tProtectiveMovePoint) then tProtectiveMovePoint = oACUToProtect:GetPosition() end
                        end
                        local iACUDistToAlliedBase = AiBotUtilities.GetDistanceBetweenPositions(oACUToProtect:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to try and protect ACU owned by brain '..oACUToProtect:GetAIBrain().Nickname..', iACUDistToAlliedBase='..iACUDistToAlliedBase..'; tProtectiveMovePoint='..repru(tProtectiveMovePoint)..'; ACU position='..repru(oACUToProtect:GetPosition())) end
                        bGivenCombatUnitsOrders = true
                        for iCurUnit = iCombatUnitsTableSize, 1, -1 do
                            local oUnit = tUnitsToConsiderAndUpdate[iCurUnit]
                            if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher, oUnit.UnitId)) and (bHaveACUInTroubleAndRecentlyInCombat or (oOptionalEnemyToBeCloserTo and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oOptionalEnemyToBeCloserTo:GetPosition()) >= iOptionalMinDistToNearestEnemy)) then
                                --If further from allied base than ACU then move to the move point, otherwise attack-move
                                if bHaveACUInTroubleAndRecentlyInCombat and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) > iACUDistToAlliedBase then
                                    oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                    AiBotOrders.IssueTrackedMove(oUnit, tProtectiveMovePoint, 3, false, 'RetPrACUM', false)
                                else
                                    if bHaveACUInTroubleAndRecentlyInCombat then oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime end
                                    AiBotOrders.IssueTrackedAttackMove(oUnit, tProtectiveMovePoint, 3, false, 'RetPrACUA', false)
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': sending unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to protect our ACU, bHaveACUInTroubleAndRecentlyInCombat='..tostring(bHaveACUInTroubleAndRecentlyInCombat)) end
                                table.remove(tUnitsToConsiderAndUpdate, iCurUnit)
                            end
                        end
                    elseif bHaveACUInTroubleAndRecentlyInCombat then
                        AiBotUtilities.ErrorHandler('Thought we would be protecting an ACU but no ACU to protect, will clear flag as might be the ACU died')
                        tLZTeamData[AiBotMap.refbACUInTrouble] = false
                    end
                end

                if bDebugMessages == true then LOG(sFunctionRef..': Finished checking if should move blocked units, bMoveBlockedNotAttackMove='..tostring(bMoveBlockedNotAttackMove)..'; iFriendlyBestMobileIndirectRange='..(iFriendlyBestMobileIndirectRange or 'nil')..';  tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; Enemy DF structure='..(tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0)..'; Enemy DF mobile='..(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)..'; tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]='..(tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 'nil')..'; iFriendlyBestMobileDFRange='..(iFriendlyBestMobileDFRange or 'nil')..'; Enemy best DF range='..iEnemyBestDFRange..'; iFriendlyBestMobileIndirectRange='..(iFriendlyBestMobileIndirectRange or 'nil')..'; iEnemyBestStructureDFRange='..(iEnemyBestStructureDFRange or 'nil')..'; Enemy structure threat indirect='..(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureIndirect] or 'nil')..'; bEnemyHasNoDFUnits='..tostring(bEnemyHasNoDFUnits or false)..'; iEnemyBestDFRange='..(iEnemyBestDFRange or 'nil')..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]='..(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] or 'nil')..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal]='..(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 'nil')..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; subrefiNearbyEnemyLongRangeDFThreat='..(tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0)..'; bAreInScenario1='..tostring(bAreInScenario1)) end
                local iShorterRangeThreat --used for fatboys to be less cautious if we have a large SR threat
                --SCENARIO 1 - We outrange enemy DF units (mobile and fix), or have equal range but with either significantly more threat at that range, or nearest enemy lacks that range
                if bAreInScenario1 then
                    --ARE IN SCENARIO 1
                    if oNearestEnemyToFriendlyBase then --In one scenario above there is a nearby naval unit that we cant reach by land so we clear nearest enemy value, and keep us in scenario 1, so we want to flag we havent given orders so units will then look for a zone to reinforce

                        if bDebugMessages == true then LOG(sFunctionRef..': In scenario 1, so we either outrange enemy, or we have significantly more threat at their best range - i.e. equal range, bAttackWithSameRange='..tostring(bAttackWithSameRange)) end
                        local tOutrangedCombatUnits = {}
                        local tUnitsToSupport = {}
                        local tFriendlyT2Arti --keep as nil, as will update if we think it is relevant
                        local bAttackWithOutrangedDFUnits = false
                        local iAngleThresholdForRally --i.e. what angle dif need between us and nearest enemy to just retreat in opposite direction instead of going to rally
                        local iSkirmisherDistToNearestEnemy
                        local bNearestEnemyIsACU = false
                        local bConsiderAttackingAdjacentZoneEnemyWithOutrangedUnits --if we have outranged IF like t1 arti and they outrange enemy in adjacent zone (but not this zone) then consider having them attack that zone; nil if not considered yet, otherwise true or false
                        local oAdjacentZoneEnemyToAttackWithOutrangedIF
                        if EntityCategoryContains(categories.COMMAND, oNearestEnemyToFriendlyBase.UnitId) then
                            bNearestEnemyIsACU = true
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': About to consider whether to attack with outranged units, is this core base='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase])..'; are there dangerous enemies in this LZ='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])..'; Our mobile DF threat='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]..'; Enemy combat total for this zone='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; Enemy threat in adj zones='..GetEnemyCombatThreatInAdjacentZones()) end
                        if tLZTeamData[AiBotMap.subrefLZbCoreBase] and tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] then
                            if bDebugMessages == true then LOG(sFunctionRef..': Are in core base so want to attack with outranged units if enemy is in this zone, subrefbDangerousEnemiesInThisLZ='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])) end
                            bAttackWithOutrangedDFUnits = true
                        else
                            local iLikelyTargetZone = oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                            local iAdjMobileDFThreat
                            iAdjMobileDFThreat = GetAdjacentNearbyMobileDFThreatWithSameZoneTarget(iLikelyTargetZone)

                            if bDebugMessages == true then LOG(sFunctionRef..': iAdjMobileDFThreat='..iAdjMobileDFThreat..'; see above log for other info') end
                            if (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] + iAdjMobileDFThreat > 1.3 * math.max(20, tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 0.5, tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] + tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]) and iAvailableCombatUnitThreat + iAdjMobileDFThreat > GetEnemyCombatThreatInAdjacentZones() * 1.1) then
                                bAttackWithOutrangedDFUnits = true

                                --Change to false if we are likeyl to have outranged DF units and enemy has significant nearby threat
                                local bExpectToHaveOutrangedDF = false
                                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange]) == false then
                                    for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] do
                                        if iThreat > 0 and iRange <= iEnemyBestDFRange then
                                            bExpectToHaveOutrangedDF = true
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Our DF Threat '..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]..' exceeds enemy total combat threat '..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..' so want to attack with outranged DF units if this is also the case factoring in adjacent enemy zone threat, bExpectToHaveOutrangedDF='..tostring(bExpectToHaveOutrangedDF)) end
                                CalculateNearbyEnemyCombatThreatFriendlyDFAndIfFriendlyACUInCombat() --Updates iEnemyCombatThreat to reflect this zone, and also includes adjacent zones where enemis are close enough to join combat

                                if not(iOurDFAndT1ArtiCombatThreat) then CalculateNearbyEnemyCombatThreatFriendlyDFAndIfFriendlyACUInCombat()
                                    if not( iOurDFAndT1ArtiCombatThreat) then iOurDFAndT1ArtiCombatThreat = 0 end
                                end
                                if iEnemyCombatThreat > iOurDFAndT1ArtiCombatThreat + iAdjMobileDFThreat or (iEnemyCombatThreat * 1.25 > iOurDFAndT1ArtiCombatThreat + iAdjMobileDFThreat and (iEnemyCombatThreat > GetEnemyCombatThreatInAdjacentZones() * 0.8 or iOurDFAndT1ArtiCombatThreat + iAdjMobileDFThreat <= 5000 or (iFriendlyBestMobileDFRange >= 60 and iEnemyBestDFRange < 60) or (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] >= (iOurDFAndT1ArtiCombatThreat + iAdjMobileDFThreat) * 0.3 and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] >= tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] * 0.75))) then
                                    bAttackWithOutrangedDFUnits = false
                                    --Dont charge into PD unless have overwhelming force
                                elseif iEnemyBestStructureDFRange > 0 and iOurDFAndT1ArtiCombatThreat + iAdjMobileDFThreat < 5000 and (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] > iEnemyCombatThreat * 0.15 or (iEnemyBestStructureDFRange < 50 and iOurDFAndT1ArtiCombatThreat + iAdjMobileDFThreat <= 2000 and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] > 0)) and iEnemyCombatThreat * 3 > iOurDFAndT1ArtiCombatThreat + iAdjMobileDFThreat then
                                    bAttackWithOutrangedDFUnits = false
                                    if bDebugMessages == true then LOG(sFunctionRef..': Dont ahve overwhelming mobile DF threat and have some indirect fire forces so wont launch all out attack just yet') end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iEnemyCombatThreat after factoring in nearby zones='..iEnemyCombatThreat..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]..'; bAttackWithOutrangedDFUnits='..tostring(bAttackWithOutrangedDFUnits)..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]..'; iEnemyBestStructureDFRange='..iEnemyBestStructureDFRange) end
                            end
                        end
                        --Want to avoid scenarios where e.g. lots of t3 mobile arti all fire at an enemy t1 engineer - if closest enemy is a non-combat unit or LAB and we have more threat generally then consider engaging logic
                        local bIFAttackNearestSignificantEnemy = false
                        if tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] >= 3000 and oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiUnitMassCost] <= 150 then
                            CalculateNearbyEnemyCombatThreatFriendlyDFAndIfFriendlyACUInCombat() --in case not already calculated
                            if (bAttackWithOutrangedDFUnits or (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] >= 8000 and iOurDFAndT1ArtiCombatThreat >= 1000) or (iOurDFAndT1ArtiCombatThreat >= iEnemyCombatThreat * 0.8 and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] >= iEnemyCombatThreat) and (EntityCategoryContains(categories.MOBILE - AiBotUnitInfo.refCategoryLandCombat, oNearestEnemyToFriendlyBase.UnitId) or (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refCategoryLandCombat] <= 42 and not(EntityCategoryContains(categories.MOBILE, oNearestEnemyToFriendlyBase.UnitId)))))  then
                                bIFAttackNearestSignificantEnemy = true
                            end
                        end

                        local toAdjacentEnemyMexes = GetMexesInThisOrAdjacentLandZone(tLZData, tLZTeamData, iTeam, iPlateau)--mexes in this or adjacent zones (so we can consider if one of these is closer to our unit than the nearest enemy)

                        if bDebugMessages == true then LOG(sFunctionRef..' Finished deciding if IF units should attack nearest significant enemy, bIFAttackNearestSignificantEnemy='..tostring(bIFAttackNearestSignificantEnemy)..'; Indirect total for this zone='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]..'; iOurDFAndT1ArtiCombatThreat='..(iOurDFAndT1ArtiCombatThreat or 'nil')..'; iEnemyCombatThreat if calculated='..(iEnemyCombatThreat or 'nil')..'; Nearest enemy mass value='..oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiUnitMassCost]..'; UnitId='..oNearestEnemyToFriendlyBase.UnitId..'; oNearestEnemyToFriendlyBase DF range='..(oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 'nil')..'; Combat range='..(oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] or 'nil')..'; Is toAdjacentEnemyMexes empty='..tostring(AiBotUtilities.IsTableEmpty(toAdjacentEnemyMexes))) end


                        local bUpdateNearestUnit = false
                        local bCheckIfNearestUnitVisible = false
                        if AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) >= 10 then bCheckIfNearestUnitVisible = true end
                        if oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] >= 10 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding nearest enemy unit '..oNearestEnemyToFriendlyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase)..' to skirmisher enemies') end
                            table.insert(tSkirmisherDFEnemies, oNearestEnemyToFriendlyBase)
                            if oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiIndirectRange] > 60 and oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiIndirectRange] < 130 and EntityCategoryContains(AiBotUnitInfo.refCategoryT3MobileArtillery, oNearestEnemyToFriendlyBase.UnitId) then
                                table.insert(tSkirmisherEnemyT3MobileArti, oNearestEnemyToFriendlyBase)
                                if bDebugMessages == true then LOG(sFunctionRef..': Also adding enemy against tSkirmisherEnemyT3MobileArti') end
                            end
                        end
                        local bMoveToStopPDConstruction = false
                        local bMoveTowardsEngineers = false
                        if bDebugMessages == true then LOG(sFunctionRef..': In scenario 1, checking if enemy engineers, Is table of enemy engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyEngineers))..'; enemy combat='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat) end
                        if AiBotUtilities.IsTableEmpty(tEnemyEngineers) == false and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 100 and (iAvailableCombatUnitThreat or 0) >= math.min(40, tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 3) and iAvailableCombatUnitThreat <= 1500 and GetEnemyCombatThreatInAdjacentZones() <= 500  then
                            local tEnemyPD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy PD empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyPD))) end
                            if AiBotUtilities.IsTableEmpty(tEnemyPD) == false then
                                bMoveToStopPDConstruction = true
                                for iPD, oPD in tEnemyPD do
                                    if oPD:GetFractionComplete() == 1 then
                                        bMoveToStopPDConstruction = false
                                        break
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': bMoveToStopPDConstruction before doublechecking threats='..tostring(bMoveToStopPDConstruction)) end
                                if bMoveToStopPDConstruction then
                                    --Check we have significantly more threat if excluding under-construction PD
                                    bMoveToStopPDConstruction = false
                                    local iPDThreat = AiBotUnitInfo.GetCombatThreatRating(tEnemyPD, true)
                                    if bDebugMessages == true then LOG(sFunctionRef..': iPDThreat='..iPDThreat) end
                                    if (iAvailableCombatUnitThreat or 0) > 2 * tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] - iPDThreat and iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() then
                                        bMoveToStopPDConstruction = true
                                    end
                                end
                            else
                                --do we have engineers to attack instead?
                                if iAvailableCombatUnitThreat <= 400 and iAvailableCombatUnitThreat <= 300 then
                                    bMoveTowardsEngineers = true
                                end
                            end
                        end

                        local iDistFromNearestEnemyToFriendlyBase = 10000 --used in some niche scenarios so we attack nearest unit e.g. mex instead of further away one
                        if oNearestEnemyToFriendlyBase then iDistFromNearestEnemyToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], tLZTeamData[AiBotMap.reftClosestFriendlyBase]) end

                        function GivenIndirectAdjacentZoneKitingOrder(oUnit)
                            local bGivenOrder = false
                            if oAdjacentZoneEnemyToAttackWithOutrangedIF then
                                if bDebugMessages == true then LOG(sFunctionRef..': GivenIndirectAdjacentZoneKitingOrder is the unit close to reftoNearestDFEnemies='..tostring(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], 25, iTeam, true, nil, nil, oUnit, 15, false))) end
                                if not(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], 25, iTeam, true, nil, nil, oUnit, 15, false)) then
                                    --Get the zone the enemy unit is in
                                    local tTargetZoneTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][oAdjacentZoneEnemyToAttackWithOutrangedIF[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZTeamData][iTeam]
                                    if bDebugMessages == true then LOG(sFunctionRef..': GivenIndirectAdjacentZoneKitingOrder is the unit close to the target zone reftoNearestDFEnemies='..tostring(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tTargetZoneTeamData[AiBotMap.reftoNearestDFEnemies], 5, iTeam, true, nil, nil, oUnit, 3, false))) end
                                    if oAdjacentZoneEnemyToAttackWithOutrangedIF[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone or AiBotUtilities.IsTableEmpty(tTargetZoneTeamData[AiBotMap.reftoNearestDFEnemies]) or not(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tTargetZoneTeamData[AiBotMap.reftoNearestDFEnemies], 5, iTeam, true, nil, nil, oUnit, 3, false)) then
                                        --We can advance
                                        AiBotOrders.IssueTrackedAttackMove(oUnit, oAdjacentZoneEnemyToAttackWithOutrangedIF:GetPosition(), 3, false, 'SRIFAdjZ', false)
                                        bGivenOrder = true
                                    end
                                end
