                                --if bCheckIfNearLocationToAvoid and EntityCategoryContains(categories.TECH1 + categories.TECH2 - categories.COMMAND, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) and AiBotConditions.HaveSentOrderToRunAwayFromLocationToAvoid(oUnit, tLZTeamData[AiBotMap.reftiLocationsToAvoid], 4) then
                                --if bDebugMessages == true then LOG(sFunctionRef..': Told unit to avoid a location to avoid') end
                                if oUnit[AiBotUnitInfo.refiDFRange] > iEnemyBestDFRange or (bAttackWithSameRange and oUnit[AiBotUnitInfo.refiDFRange] >= iEnemyBestDFRange) or (iDFRangeOverrideForScenario1 and (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= iDFRangeOverrideForScenario1)
                                        --Experimental exception - even if enemy threat in adjacent zones such we dont want to attack with everything, still consider attacking with experimental units
                                        --HaveSignificantEnemyThreatWithinRange(tLZData, tLZTeamData, iPlateau, iTeam, iSearchDistance,                                                                                             tStartPoint,                                iEnemyMassTotalThreshold,                                                                                  iOptionalSearchCategory, tOptionalAdditionalUnits, bOnlyIncludeDFUnits, bIncludeEnemyCombatRange, iOptionalSpeedThreshold, iOptionalMinEnemyMassRequiredUnlessInRange)
                                        or ((oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 10000 and not(bAttackWithOutrangedDFUnits) and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < oUnit[AiBotUnitInfo.refiUnitMassCost] and not(AiBotConditions.HaveSignificantEnemyThreatWithinRange(tLZData, tLZTeamData, iPlateau, iTeam, AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) + 15, oNearestEnemyToFriendlyBase:GetPosition(), math.min(oUnit[AiBotUnitInfo.refiUnitMassCost] * 0.75, AiBotUnitInfo.GetCombatThreatRating({ oUnit }) * 0.8), nil,                       nil,                    true,               true,                           oUnit:GetBlueprint().Physics.MaxSpeed, math.min(150, 0.05 * (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))))))
                                then
