                                                    if bDebugMessages == true then LOG(sFunctionRef..': Checking AiBotEasy fatboy kiting exception, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; DFRange='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; is tSkirmisherDFEnemies empty='..tostring(AiBotUtilities.IsTableEmpty(tSkirmisherDFEnemies))..'; refbLastShotBlocked='..tostring(oUnit[AiBotUnitInfo.refbLastShotBlocked] or false)..'; Close to enemy based on -25 to range='..tostring(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tSkirmisherDFEnemies, oUnit[AiBotUnitInfo.refiDFRange] - 25, iTeam, false, nil, nil, nil, nil, nil, nil, nil))) end
                                                    if (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 80 and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(tSkirmisherDFEnemies) == false and ((not(oUnit[AiBotUnitInfo.refbLastShotBlocked]) and AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tSkirmisherDFEnemies, oUnit[AiBotUnitInfo.refiDFRange] - 25, iTeam, false, nil, nil, nil, nil, nil, nil, nil)) or (oUnit[AiBotUnitInfo.refbLastShotBlocked] and AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tSkirmisherDFEnemies, oUnit[AiBotUnitInfo.refiDFRange] - 35, iTeam, false, nil, nil, nil, nil, nil, nil, nil))) then
                                                        --Do a kiting retreat of fatboy
