                                            else
                                                --Experimental specific - attack ACU if in-range
                                                local bUseNormalLogic = true
                                                if bDebugMessages == true and oClosestFatboyOrACUInIslandToSuicideInto then LOG(sFunctionRef..': bConsiderAttackingACU='..tostring(bConsiderAttackingACU)..'; Dist to oClosestFatboyOrACUInIslandToSuicideInto='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFatboyOrACUInIslandToSuicideInto:GetPosition())..'; Unit combat range='..oUnit[AiBotUnitInfo.refiCombatRange]) end
                                                if bConsiderAttackingACU and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental - AiBotUnitInfo.refCategorySkirmisher - AiBotUnitInfo.refCategoryFatboy - AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride]) and AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), toEnemyACUsNearZone, 6 + oUnit[AiBotUnitInfo.refiDFRange], iTeam, false, nil, nil, nil, nil, nil) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to attack ACU with our experimental') end
