                                                elseif bSuicideIntoFatboyOrACU and oClosestFatboyOrACUInIslandToSuicideInto and not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher, oUnit.UnitId)) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFatboyOrACUInIslandToSuicideInto:GetPosition()) <= oUnit[AiBotUnitInfo.refiCombatRange] + 8 then
