                                                            if bDebugMessages == true then LOG(sFunctionRef..': Assing if enemy has negligible threat, iFriendlyExpFactor='..iFriendlyExpFactor..'; iMassThresholdForNegligibleThreat='..iMassThresholdForNegligibleThreat..'; iShorterRangeThreat='..(iShorterRangeThreat or 'nil')) end
                                                            --_________________________________________________________________HaveSignificantEnemyThreatWithinRange(tLZData, tLZTeamData, iPlateau, iTeam, iSearchDistance,                     tStartPoint,        iEnemyMassTotalThreshold,           iOptionalSearchCategory,                                                                                                                                                                                                                             tOptionalAdditionalUnits,           bOnlyIncludeDFUnits, bIncludeEnemyCombatRange, iOptionalSpeedThreshold,                    iOptionalMinEnemyMassRequiredUnlessInRange)
                                                            bFiringAtNegligibleThreatInLRExperimentalRange = not(AiBotConditions.HaveSignificantEnemyThreatWithinRange(tLZData, tLZTeamData, iPlateau, iTeam, oUnit[AiBotUnitInfo.refiDFRange] - 0.5, oUnit:GetPosition(), iMassThresholdForNegligibleThreat, AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryT2PlusPD + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryNavalSurface - categories.TECH1 + categories.COMMAND, tUnitsNearFatboyInFurtherAwayZones, nil,                   nil,                        oUnit:GetBlueprint().Physics.MaxSpeed, math.min(150, 0.05 * (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)))))
                                                        end
                                                        if bDebugMessages == true then LOG(sFunctionRef..': bFiringAtNegligibleThreatInLRExperimentalRange='..tostring(bFiringAtNegligibleThreatInLRExperimentalRange)..'; Time since we last fired weapon='..(GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0))..'; Have significant enemy threat within range='..tostring(AiBotConditions.HaveSignificantEnemyThreatWithinRange(tLZData, tLZTeamData, iPlateau, iTeam, oUnit[AiBotUnitInfo.refiDFRange] - 0.5, oUnit:GetPosition(), iMassThresholdForNegligibleThreat, AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryT2PlusPD + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryNavalSurface - categories.TECH1 + categories.COMMAND, tUnitsNearFatboyInFurtherAwayZones, nil,                   nil,                        oUnit:GetBlueprint().Physics.MaxSpeed, math.min(150, 0.05 * (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)))))..'; tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]='..tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]) end
                                                    end

                                                    --Are we in range of any enemy or cant kite?
                                                    --CloseToEnemyUnit(tStartPosition,      tUnitsToCheck,         iDistThreshold,             iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure)                                                                                                                                                                                     CloseToEnemyUnit(tStartPosition,      tUnitsToCheck,                                        iDistThreshold,             iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': About to check if we are about to be in range of the enemy and so want to do a kiting retreat, our DF range='..oUnit[AiBotUnitInfo.refiDFRange]..'; iEnemyBestDFRange='..iEnemyBestDFRange..'; Expected threshold for close to enemy='..math.min(oUnit[AiBotUnitInfo.refiDFRange], math.max(oUnit[AiBotUnitInfo.refiDFRange] - 3,  iEnemyBestDFRange + oUnit:GetBlueprint().Physics.MaxSpeed + 2))..'; bUseNormalLogic before fatboy adj='..tostring(bUseNormalLogic)..'; iVisibleLandCombatMassInFatboyRange='..(iVisibleLandCombatMassInFatboyRange or 'nil')..'; Dist to nearest enemy to friendly base='..AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition())..'; DF Enemies within 7 of our range='..tostring(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], oUnit[AiBotUnitInfo.refiCombatRange] - 7, iTeam, false, nil, nil, oUnit, nil, false))..'; bFiringAtNegligibleThreatInLRExperimentalRange='..tostring(bFiringAtNegligibleThreatInLRExperimentalRange)) end
                                                    --Fatboy special logic if fatboy not in water - although default logic works fori t, want to do a more detailed check that looks into further away zones for nearby enemies
                                                    if (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 100 and not(bFiringAtNegligibleThreatInLRExperimentalRange) and oUnit[AiBotUnitInfo.refbCanKite] and (GetEnemyCombatThreatInAdjacentZones() >= 8000 or iVisibleLandCombatMassInFatboyRange >= 3000) then
                                                        --First make sure the fatboy is closer to enemy base than the closest friendly base is (otherwise we risk 'retreating' to a base that takes us closer to the enemy)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Checking if fatboy is closer to enemy base than our closest friendly base, and significant visible mass, iVisibleLandCombatMassInFatboyRange='..iVisibleLandCombatMassInFatboyRange..'; Is table of nearby enemy t2 arti empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]))..'; Mod dist%='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Dist to oNearestEnemyToFriendlyBase='..AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition()))
                                                            if AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) then LOG(sFunctionRef..'; [AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]='..oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])..'; Dist to this='..AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition())..'; Can see this unit='..tostring(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck], false))) end
