                                                                        elseif iSkirmisherDistToNearestEnemy <= (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 0) + 11 and (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 0) >= (oUnit[AiBotUnitInfo.refiDFRange] or 0) - 11 and (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:IsUnitState('Moving') or oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:IsUnitState('Attacking')) and (iSkirmisherDistToNearestEnemy <= (oUnit[AiBotUnitInfo.refiDFRange] or 0) - 1 and AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()), AiBotUnitInfo.GetUnitFacingAngle(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])) <= 60 or AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()), AiBotUnitInfo.GetUnitFacingAngle(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])) <= 32.5) then
