                                                                    end
                                                                    --Attackmove (unless we have far more threat in this zone and arent a megalith); note that oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] is false if we havent done a close to check yet
                                                                    if bUseNormalLogic then
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will attack move unless we have significantly more threat, bFiringAtNegligibleThreatInLRExperimentalRange='..tostring(bFiringAtNegligibleThreatInLRExperimentalRange)..'; bMoveToStopPDConstruction='..tostring(bMoveToStopPDConstruction)..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; GetEnemyCombatThreatInAdjacentZones='..GetEnemyCombatThreatInAdjacentZones()..'; DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]='..(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) or 'nil')..'; iVisibleLandCombatMassInFatboyRange='..(iVisibleLandCombatMassInFatboyRange or 'nil')..'; (oUnit[AiBotUnitInfo.refiDFMinRange]='..(oUnit[AiBotUnitInfo.refiDFMinRange] or 0)..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]..'; oUnit[AiBotUnitInfo.refiDFRange]='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; Is unit a fatboy='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId))..'; Ignore due to being stuck='..tostring(IgnoreOrderDueToStuckUnit(oUnit) or false)..'; Is unit a skirmisher='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher, oUnit.UnitId))..'; Is available threat more tahn 4x enemy='..tostring(iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 4)..'; Main condition requirements='..tostring((iAvailableCombatUnitThreat > 1000 and iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 4 and (not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId)) or (iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 20 and (not(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) or EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride]))))))..'; Sub2 condition='..tostring((EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) and EntityCategoryContains(categories.TECH1 + categories.TECH2, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId) and AiBotUnitInfo.GetCombatThreatRating(oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryStructure, oUnit:GetPosition(), oUnit[AiBotUnitInfo.refiDFRange], 'Enemy'), true, true) <= 2000))..'; Sub3 condition='..tostring((AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) or not(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], oUnit[AiBotUnitInfo.refiDFRange] + 4, iTeam, false,               nil,                    nil,                                  oUnit,                              math.min(oUnit[AiBotUnitInfo.refiDFRange], math.max(oUnit[AiBotUnitInfo.refiDFRange] - 3,  iEnemyBestDFRange + oUnit:GetBlueprint().Physics.MaxSpeed + 5))))))..'; Dist to nearest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition())) end
                                                                        if bFiringAtNegligibleThreatInLRExperimentalRange or
                                                                                (oUnit[AiBotUnitInfo.refiDFRange] <= 120 and (oUnit[AiBotUnitInfo.refiDFMinRange] or 0) <= 30 and
                                                                                        (bMoveToStopPDConstruction or
                                                                                                --Fatboy - if negligible threat in its range then consider moving (however for QUIET+LOUD be less likely to move due to issue with weapon cycling)
                                                                                                ((oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 90 and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId) and iVisibleLandCombatMassInFatboyRange <= 2000 and tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] <= 4000 and (AiBotUtilities.bFAFActive or AiBotUtilities.bSteamActive or not(oNearestEnemyToFriendlyBase) or AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition()) > oUnit[AiBotUnitInfo.refiCombatRange] - 20)) or
                                                                                                --Main condition: Consider various sub conditions where we have more than 4 times the enemy threat in adjacent zones, and aren't dealing with a skirmisher unit (with rare exceptions):
                                                                                                (iAvailableCombatUnitThreat > 1000 and iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 4 and (not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId)) or (iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 20 and (not(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) or EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride])))) and
