                                                                                                        (EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) and EntityCategoryContains(categories.TECH1 + categories.TECH2, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId) and AiBotUnitInfo.GetCombatThreatRating(oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryStructure, oUnit:GetPosition(), oUnit[AiBotUnitInfo.refiDFRange], 'Enemy'), true, true) <= 2000) or
