                                                                                elseif(((oNearestEnemyToConsider[AiBotUnitInfo.refiCombatRange] or 0) == 0 and iDistToNearestEnemy <= oUnit[AiBotUnitInfo.refiCombatRange] - 4 and ((oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) <= 250 or (oNearestEnemyToConsider[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oNearestEnemyToConsider)) > 1000 or iDistToNearestEnemy <= math.min(30, oUnit[AiBotUnitInfo.refiCombatRange] * 0.5))) or (iDistToNearestEnemy <= 12 and (oUnit[AiBotUnitInfo.refiCombatRange] >= 15 or iDistToNearestEnemy <= oUnit[AiBotUnitInfo.refiCombatRange] - 5))) then
