                               , math.min(oUnit[AiBotUnitInfo.refiDFRange] * 0.94, math.max(oUnit[AiBotUnitInfo.refiDFRange] * 0.94 - 4,  iEnemyBestDFRange + 4))))))..'; Line7Cond='..tostring((iDFRangeOverrideForScenario1 and oUnit[AiBotUnitInfo.refiDFRange] <= iEnemyBestDFRange and not(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], math.max(oUnit[AiBotUnitInfo.refiDFRange] * 0.94,6, iDFRangeOverrideForScenario1 - (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0)), iTeam, true,                   nil,                    nil,                                oUnit                                       , nil))))..'; bSuicideIntoFatboyOrACU='..tostring(bSuicideIntoFatboyOrACU or false)) end

                                                            if oUnit[AiBotUnitInfo.refiDFRange] > oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] and AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and ((not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId)) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride])) or not(oUnit[AiBotUnitInfo.refiLastWeaponEvent]) or GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiLastWeaponEvent] >= (oUnit[AiBotUnitInfo.refiTimeBetweenDFShots]or 0) - 0.4) then
                                                                local iDistToClosestEnemy = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())
                                                                if iDistToClosestEnemy - oUnit[AiBotUnitInfo.refiDFRange] >= -1.5 and iDistToClosestEnemy - oUnit[AiBotUnitInfo.refiDFRange] <= 2 then
                                                                    --Get where enemy will move towards
                                                                    local iVelocityX, iVelocityY, iVelocityZ = oUnit:GetVelocity()
