                                    if ProceedWithUnitOrder(oUnit) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': We dont outrange enemy, will consider if we want to be a SR support unit') end
                                        if oUnit[AiBotUnitInfo.refiDFRange] > 0 and ((oUnit[AiBotUnitInfo.refiIndirectRange] or 0) <= (oUnit[AiBotUnitInfo.refiDFRange] or 0) or bAttackWithOutrangedDFUnits) then
                                            --We dont outrange the enemy, but we do have other units that do

                                            --Skirmishers - Still retreat if are in range of enemy, even if we dont outraneg them, as may e.g. be other units that we do outrange
                                            if (EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId) or oUnit[AiBotUnitInfo.refbScoutCombatOverride]) and not(oUnit[AiBotUnitInfo.refbEasyBrain]) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we are in range of an enemy unit for a skirmisher as it doesnt have enough DF to outrange enemy DF; bEnemyHasNoDFUnits='..tostring(bEnemyHasNoDFUnits)..'; Is close to enemy='..tostring(not(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], oUnit[AiBotUnitInfo.refiDFRange] - math.max(2, math.min(8, oUnit[AiBotUnitInfo.refiDFRange] * 0.1)), iTeam, false)))..'; bAttackWithOutrangedDFUnits='..tostring(bAttackWithOutrangedDFUnits)..'; Close to nearest DF enemies based on enemy range='..tostring(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], 6, iTeam, true))..'; Close to skirmisher enemies based on their range='..tostring(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tSkirmisherDFEnemies, 6, iTeam, true))..'; Close to LR enemy IF units='..tostring(AiBotConditions.IsUnitInRangeOfLRIndirectFireUnits(oUnit, tLZTeamData, 5) or false)) end
                                                if bAttackWithOutrangedDFUnits then
                                                    --Check we arent in range of enemy indirect fire units including t2 arti

                                                    --CloseToEnemyUnit(tStartPosition, tUnitsToCheck,                                       iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure, bIncludeEnemyAntiNavyRange)
                                                    if (bEnemyHasNoDFUnits or not(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tSkirmisherDFEnemies, 6, iTeam, true))) and not(AiBotConditions.IsUnitInRangeOfLRIndirectFireUnits(oUnit, tLZTeamData, 5)) then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Not in range of enemy yet, and we outrange enemy; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; DF range='..oUnit[AiBotUnitInfo.refiDFRange]..'; oNearestEnemyToFriendlyBase='..oNearestEnemyToFriendlyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase)..' owned by '..oNearestEnemyToFriendlyBase:GetAIBrain().Nickname..'; oNearestEnemyToFriendlyBase DF range='..(oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 'nil')..'; Distance to the nearest enemy to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oUnit:GetPosition())..'; Enemy unit actual position='..repru(oNearestEnemyToFriendlyBase:GetPosition())..'; Enemy last recorded position='..repru(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; Our unit position='..repru(oUnit:GetPosition())..'; LZ midpoint position='..repru(tLZData[AiBotMap.subrefMidpoint])) end
                                                        --Not in range yet, so attack move to the nearest enemy
                                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, false, 'SK1AMve'..iLandZone)
                                                    else
                                                        local tRetreatLocationToUse
                                                        if AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) then
                                                            local iAngleToNearestEnemy = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())
                                                            local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tAmphibiousRallyPoint)
                                                            if AiBotUtilities.GetAngleDifference(iAngleToNearestEnemy, iAngleToRally) <= 65 then
                                                                local tPotentialRetreatLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleToNearestEnemy - 180, 15, true, nil, AiBotMap.bIsCampaignMap)
                                                                if AiBotUtilities.IsTableEmpty(tPotentialRetreatLocation) == false and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPotentialRetreatLocation) == iPlateau then
                                                                    tRetreatLocationToUse = {tPotentialRetreatLocation[1], tPotentialRetreatLocation[2], tPotentialRetreatLocation[3]}
                                                                end
                                                            end
                                                        end
                                                        if not(tRetreatLocationToUse) then
                                                            --Enemy has DF units and they are already in our range so retreat
                                                            if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                                                                tRetreatLocationToUse = {tAmphibiousRallyPoint[1], tAmphibiousRallyPoint[2], tAmphibiousRallyPoint[3]}
                                                            else
                                                                tRetreatLocationToUse = {tRallyPoint[1], tRallyPoint[2], tRallyPoint[3]}
                                                            end
                                                        end
                                                        oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                        AiBotOrders.IssueTrackedMove(oUnit, tRetreatLocationToUse, 6, false, 'SKRetr'..iLandZone)
                                                    end
                                                else
                                                    --Only attack with skirmishers if wont get in range of enemy unit
                                                    --CloseToEnemyUnit(tStartPosition, tUnitsToCheck, iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure, bIncludeEnemyAntiNavyRange)
                                                    if bEnemyHasNoDFUnits or not(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tSkirmisherDFEnemies, 8, iTeam, true,                        nil,                    nil,                                oUnit)) and not(AiBotConditions.IsUnitInRangeOfLRIndirectFireUnits(oUnit, tLZTeamData, 5)) then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Not in range of enemy yet, and we outrange enemy; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; DF range='..oUnit[AiBotUnitInfo.refiDFRange]..'; oNearestEnemyToFriendlyBase='..oNearestEnemyToFriendlyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase)..'; oNearestEnemyToFriendlyBase DF range='..(oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 'nil')..'; Distance to the nearest enemy to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oUnit:GetPosition())..'; Enemy unit actual position='..repru(oNearestEnemyToFriendlyBase:GetPosition())..'; Enemy last recorded position='..repru(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; Our unit position='..repru(oUnit:GetPosition())..'; LZ midpoint position='..repru(tLZData[AiBotMap.subrefMidpoint])) end
                                                        --Not in range yet, so attack move to the nearest enemy
                                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, false, 'SK2AMve'..iLandZone)
                                                    else
                                                        if bDebugMessages == true then
                                                            LOG(sFunctionRef..': Enemy has DF units in our range so will retreat to the rally point, unless closest enemy unit is close enough and at such an angle that we shoudl try running away from it, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]='..(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) or 'nil')..'; DF range='..(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 'nil'))
                                                        end
