                                                        local tRetreatLocationToUse
                                                        if AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] > 0 then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Dist to last known position='..AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oUnit:GetPosition())..'; Our unit DF range='.. oUnit[AiBotUnitInfo.refiDFRange]..'; Actual dist to our unit='..AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition())) end
                                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oUnit:GetPosition()) <= oUnit[AiBotUnitInfo.refiDFRange] + 8 then
                                                                local iAngleToNearestEnemy = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())
                                                                local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tAmphibiousRallyPoint)
                                                                if AiBotUtilities.GetAngleDifference(iAngleToNearestEnemy, iAngleToRally) <= 65 then
                                                                    local tPotentialRetreatLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleToNearestEnemy - 180, 15, true, nil, AiBotMap.bIsCampaignMap)
                                                                    if AiBotUtilities.IsTableEmpty(tPotentialRetreatLocation) == false and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPotentialRetreatLocation) == iPlateau then
                                                                        tRetreatLocationToUse = {tPotentialRetreatLocation[1], tPotentialRetreatLocation[2], tPotentialRetreatLocation[3]}
                                                                    end
                                                                end
                                                                if bDebugMessages == true then LOG(sFunctionRef..': tRetreatLocationToUse after considering whether to run in opposite direction to nearest enemy='..repru(tRetreatLocationToUse)..'; iAngleToNearestEnemy='..iAngleToNearestEnemy..'; iAngleToRally='..iAngleToRally) end
                                                            end
                                                        end
                                                        if not(tRetreatLocationToUse) then
                                                            if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                                                                tRetreatLocationToUse = {tAmphibiousRallyPoint[1], tAmphibiousRallyPoint[2], tAmphibiousRallyPoint[3]}
                                                            else
                                                                tRetreatLocationToUse = {tRallyPoint[1], tRallyPoint[2], tRallyPoint[3]}
                                                            end
                                                        end

                                                        oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                        AiBotOrders.IssueTrackedMove(oUnit, tRetreatLocationToUse, 6, false, 'SK2Retr'..iLandZone)


                                                    end
                                                end
                                            else
                                                if bDebugMessages == true then LOG(sFunctionRef..': DF unit is outranged so adding to tOutrangedCombatUnits') end
                                                table.insert(tOutrangedCombatUnits, oUnit)
                                                --Consider whether to include experimentals in SR units to support as well as SR units
                                                if (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 9000 and AiBotUtilities.IsTableEmpty(tSkirmisherDFEnemies) == false then
                                                    --Is the unit both almost in range of enemy, and it wouldnt take long before it is in range of enemy? (as dont want to suicide army just because fatboy starts firing)
                                                    local bInRangeOfDangerousEnemy = false
                                                    if (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 0) > 10 and (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])) >= 400 and AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition()) - oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] <= 6 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange] <= 25 then
                                                        bInRangeOfDangerousEnemy = true
                                                    else
                                                        --Do detailed check of all DF enemy units
                                                        for iEnemyUnit, oEnemyUnit in tSkirmisherDFEnemies do
                                                            if (oEnemyUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oEnemyUnit)) >= 400 then --roughly equiv to t3 land
                                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemyUnit:GetPosition(), oUnit:GetPosition())
                                                                if iCurDist - (oEnemyUnit[AiBotUnitInfo.refiDFRange] or 0) <= 6 and iCurDist - oUnit[AiBotUnitInfo.refiCombatRange] <= 25 then
                                                                    bInRangeOfDangerousEnemy = true
                                                                    break
                                                                end
                                                            end
                                                        end

                                                    end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to include SR exp in units to support, bInRangeOfDangerousEnemy='..tostring(bInRangeOfDangerousEnemy)..'; Time since last tried retreating='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] or 0)..'; CanKite='..tostring(oUnit[AiBotUnitInfo.refbCanKite])) end
                                                    if bInRangeOfDangerousEnemy then
                                                        if oUnit[AiBotUnitInfo.refiUnitMassCost] >= 16000 and (not(oUnit[AiBotUnitInfo.refbCanKite]) or GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] or 0) >= 1 + iTicksPerLandCycle * 0.1) then bHaveSRExperimentalsInCombat = true end
                                                        table.insert(tUnitsToSupport, oUnit)
                                                    end
                                                end
                                            end
                                        elseif oUnit[AiBotUnitInfo.refiIndirectRange] > 0 then
