                                                table.insert(tUnitsToSupport, oUnit)
                                                if bDebugMessages == true then LOG(sFunctionRef..': We exceed DF range override for this IF so adding to tUnitsToSupport') end
                                                if oUnit[AiBotUnitInfo.refbEasyBrain] then
