                                                    end
                                                else
                                                    if (bConsiderSpecialMMLLogic or bEnemyHasFixedShieldsInThisOrAdjacentZone) and EntityCategoryContains(AiBotUnitInfo.refCategoryMML, oUnit.UnitId) then
                                                        table.insert(tMMLForSynchronisation, oUnit)
                                                        --T1 arti drops - suicide into enemy buildings
                                                    elseif oUnit[AiBotAir.refiTimeLastDropped] and GetGameTimeSeconds() - oUnit[AiBotAir.refiTimeLastDropped] <= 60 and oNearestEnemyStructureToMidpoint then
                                                        SuicideUnitIntoEnemyStructure(oUnit)
                                                    else
                                                        iIndirectDistanceInsideRangeThreshold = iIndirectRunFigureNormal
                                                        if oUnit[AiBotUnitInfo.refbWeaponUnpacks] then iIndirectDistanceInsideRangeThreshold = iIndirectDistanceInsideRangeThreshold + iIndirectRunFigureDeployedAdjust end
                                                        if bOnlyRetreatIndirectIfEnemyDFAlmostInRange then iIndirectDistanceInsideRangeThreshold = math.max(iIndirectDistanceInsideRangeThreshold + 10, ((oUnit[AiBotUnitInfo.refiIndirectRange] or 0) - iEnemyBestDFRange)) end


                                                        if bDebugMessages == true then
                                                            LOG(sFunctionRef..': Have Indirect unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' that outranges the enemy (our IF range='..oUnit[AiBotUnitInfo.refiIndirectRange]..'; Enemy best DF range='..iEnemyBestDFRange..'), WIll list every unit in the nearest DF enemies and their distance to us; our position='..repru(oUnit:GetPosition())..'; Do we have a valid shield assigned='..tostring(oUnit[refoAssignedMobileShield] or false))
                                                            for iEnemy, oEnemy in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                                LOG(sFunctionRef..': oEnemy '..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..' is '..AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition())..'; distance based on last known position='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oUnit:GetPosition())..'; oEnemy DF range='..(oEnemy[AiBotUnitInfo.refiDFRange] or 'nil')..'; Enemy Indirect range='..(oEnemy[AiBotUnitInfo.refiIndirectRange] or 'nil')..'; bOnlyRetreatIndirectIfEnemyDFAlmostInRange='..tostring(bOnlyRetreatIndirectIfEnemyDFAlmostInRange or false))
                                                            end
                                                        end
                                                        local iDistThreshold
                                                        if bOnlyRetreatIndirectIfEnemyDFAlmostInRange then
                                                            iDistThreshold = math.max(oUnit[AiBotUnitInfo.refiIndirectRange] - iIndirectDistanceInsideRangeThreshold, math.min(iEnemyBestDFRange + 5, oUnit[AiBotUnitInfo.refiIndirectRange] - 2))
                                                            if AiBotUnitInfo.IsUnitValid(oUnit[refoAssignedMobileShield]) then iDistThreshold = iDistThreshold - 5 end
