                                                            if (oNearestEnemyStructureToMidpoint and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyStructureToMidpoint[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) < oUnit[AiBotUnitInfo.refiIndirectRange]) then
                                                                --If have nearby T2 arti almost in range then switch to attck this
                                                                local oAlternativeUnitToAttack, iClosestAlternativeUnitDist
                                                                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false and not(EntityCategoryContains(AiBotUnitInfo.refCategoryTMD + AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryIndirectT2Plus + AiBotUnitInfo.refCategoryRadar + AiBotUnitInfo.refCategoryPD, oNearestEnemyStructureToMidpoint.UnitId)) and (not(AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])) or AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()) - oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] >= 16) then
                                                                    oAlternativeUnitToAttack, iClosestAlternativeUnitDist = AiBotUtilities.GetNearestUnit(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits], oUnit:GetPosition(), false, nil, true)
                                                                    if iClosestAlternativeUnitDist > (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) + 10 then
                                                                        oAlternativeUnitToAttack = nil
                                                                    end
                                                                end
                                                                if oAlternativeUnitToAttack then
                                                                    AiBotOrders.IssueTrackedAttack(oUnit, oAlternativeUnitToAttack, false, 'IST2ArtA'..iLandZone, false)
                                                                else
                                                                    AiBotOrders.IssueTrackedAttack(oUnit, oNearestEnemyStructureToMidpoint, false, 'ISAtc'..iLandZone, false)
                                                                end
                                                            elseif bNearestEnemyIsACU and oNearestEnemyToFriendlyBase:IsUnitState('Upgrading') and (AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oNearestEnemyToFriendlyBase, false) or AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 2) then
                                                                --Attack
                                                                AiBotOrders.IssueTrackedAttack(oUnit, oNearestEnemyToFriendlyBase, false, 'InEnACUU'..iLandZone, false)
                                                            elseif AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition()) < oUnit[AiBotUnitInfo.refiIndirectRange] then
                                                                AiBotOrders.IssueTrackedAttack(oUnit, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck], false, 'INSAtc'..iLandZone, false)
                                                            else
                                                                --Consider attacking an enemy further away if closest enemy is insignificant
                                                                local iDistToNearestEnemy = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition())
                                                                local oMexToConsiderTargetetingInstead
                                                                if iDistToNearestEnemy > (oUnit[AiBotUnitInfo.refiIndirectRange] + 10) and AiBotUtilities.IsTableEmpty(toAdjacentEnemyMexes) == false then
                                                                    for iMex, oMex in toAdjacentEnemyMexes do
                                                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oMex:GetPosition(), oUnit:GetPosition())
                                                                        if iCurDist < iDistToNearestEnemy then
                                                                            iDistToNearestEnemy = iCurDist
