                                                                    end
                                                                end

                                                                if bDebugMessages == true then LOG(sFunctionRef..': Will consider switching to a snigifcant enemy target if relevant, is closest enemy from last check valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]))..'; Mass cost of closest enemy='..(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiUnitMassCost] or 'nil')..'; oMexToConsiderTargetetingInstead='..(oMexToConsiderTargetetingInstead.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oMexToConsiderTargetetingInstead) or 'nil')) end
                                                                if bIFAttackNearestSignificantEnemy and (not(AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])) or oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiUnitMassCost] <= 45 or not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryIndirect + AiBotUnitInfo.refCategoryStructure, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId)) or iDistToNearestEnemy > oUnit[AiBotUnitInfo.refiIndirectRange] + 3) then
                                                                    --If enemy has a building then focus on this
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to attack nearest significant enemy, oNearestEnemyStructureToMidpoint='..(oNearestEnemyStructureToMidpoint.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyStructureToMidpoint) or 'nil')) end
                                                                    if oNearestEnemyStructureToMidpoint and AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oNearestEnemyStructureToMidpoint) then
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': will target closest enemy structure') end
                                                                        AiBotOrders.IssueTrackedAttack(oUnit, oNearestEnemyStructureToMidpoint, false, 'ISNglSA'..iLandZone, false)
                                                                    else
                                                                        local oEnemyToConsiderAttacking
                                                                        local iClosestEnemyToIndirect = 1000
                                                                        if AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiUnitMassCost] >= 45 and EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryIndirect + AiBotUnitInfo.refCategoryStructure, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId) then
                                                                            if bDebugMessages == true then LOG(sFunctionRef..': Will target closest enemy from last close to enemy check') end
                                                                            oEnemyToConsiderAttacking = oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]
                                                                        else
                                                                            for iEnemy, oEnemy in tLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                                                                if oEnemy[AiBotUnitInfo.refiUnitMassCost] >= 45 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oEnemy.UnitId)) then
                                                                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
                                                                                    if iCurDist < iClosestEnemyToIndirect then
                                                                                        oEnemyToConsiderAttacking = oEnemy
                                                                                        iClosestEnemyToIndirect = iCurDist
                                                                                    end
                                                                                end
                                                                            end
                                                                            if not(oEnemyToConsiderAttacking) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                                                --Just get the closest enemy unit
                                                                                for iEnemy, oEnemy in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do

                                                                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
                                                                                    if iCurDist < iClosestEnemyToIndirect and not(oEnemy.Dead) then
                                                                                        oEnemyToConsiderAttacking = oEnemy
                                                                                        iClosestEnemyToIndirect = iCurDist
                                                                                    end
                                                                                end
                                                                            end
                                                                        end
                                                                        if not(iClosestEnemyToIndirect) then --redundancy
                                                                            if AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) then oEnemyToConsiderAttacking = oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] else oEnemyToConsiderAttacking = oNearestEnemyToFriendlyBase end
                                                                            iClosestEnemyToIndirect = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEnemyToConsiderAttacking[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
                                                                        end
                                                                        if bDebugMessages == true then
                                                                            if not(AiBotUnitInfo.IsUnitValid(oEnemyToConsiderAttacking)) then LOG(sFunctionRef..': oEnemyToConsiderAttacking is dead so will attack closest enemy base as a redundancy')
                                                                            else
                                                                                LOG(sFunctionRef..': oEnemyToConsiderAttacking='..oEnemyToConsiderAttacking.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToConsiderAttacking)..'; Can see this unit='..tostring(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemyToConsiderAttacking)))
                                                                            end
                                                                        end
                                                                        if not(AiBotUnitInfo.IsUnitValid(oEnemyToConsiderAttacking)) then --redundancy
                                                                            AiBotOrders.IssueTrackedAggressiveMove(oUnit, tLZTeamData[AiBotMap.reftClosestEnemyBase], 5, false, 'IKADead'..iLandZone)
                                                                            --AOE ground attack option similar to below logic for hidden attackers we know are there and which arent moving
                                                                        elseif iClosestEnemyToIndirect <= oUnit[AiBotUnitInfo.refiIndirectRange] and (oUnit[AiBotUnitInfo.refiIndirectAOE] or 0) > 0 and oUnit[AiBotUnitInfo.refiTimeBetweenIFShots] and not(oEnemyToConsiderAttacking:IsUnitState('Moving')) and not(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemyToConsiderAttacking)) and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or -1) > 1 + oUnit[AiBotUnitInfo.refiTimeBetweenIFShots] * 1.2 and AiBotUtilities.GetDistanceBetweenPositions(oEnemyToConsiderAttacking:GetPosition(), oUnit:GetPosition()) <= (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) then
                                                                            AiBotOrders.IssueTrackedGroundAttack(oUnit, oEnemyToConsiderAttacking:GetPosition(), math.min(1, oUnit[AiBotUnitInfo.refiIndirectAOE] * 0.5), false, 'INglHidA', false)
                                                                        elseif not(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemyToConsiderAttacking)) then
                                                                            --Just attack move as normal since we dont know enemy unit is there
                                                                            AiBotOrders.IssueTrackedAggressiveMove(oUnit, oEnemyToConsiderAttacking:GetPosition(), math.max(15, iIndirectDistanceInsideRangeThreshold), false, 'IKANgM'..iLandZone)
                                                                        else
                                                                            --We can see the enemy, so manual attack
                                                                            AiBotOrders.IssueTrackedAttack(oUnit, oEnemyToConsiderAttacking, false, 'IFNglAE'..iLandZone, false)
                                                                        end
                                                                    end

                                                                    --If have aoe attack and nearest enemy is in range and we havent fired recently and the nearest enemy isnt moving, but we have temporarily lost intel of it, then ground fire it
                                                                elseif (oUnit[AiBotUnitInfo.refiIndirectAOE] or 0) > 0 and oUnit[AiBotUnitInfo.refiTimeBetweenIFShots] and AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and not(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:IsUnitState('Moving')) and not(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])) and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or -1) > 1 + oUnit[AiBotUnitInfo.refiTimeBetweenIFShots] * 1.2 and AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()) <= (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) then
                                                                    AiBotOrders.IssueTrackedGroundAttack(oUnit, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), math.min(1, oUnit[AiBotUnitInfo.refiIndirectAOE] * 0.5), false, 'IHidAtc', false)
                                                                elseif oMexToConsiderTargetetingInstead then
                                                                    if not(IgnoreOrderDueToStuckUnit(oUnit, oMexToConsiderTargetetingInstead:GetPosition())) then
                                                                        if iDistToNearestEnemy <= oUnit[AiBotUnitInfo.refiCombatRange] + 3 then
                                                                            AiBotOrders.IssueTrackedAttack(oUnit, oMexToConsiderTargetetingInstead, false, 'IAtMx'..iLandZone, false)
                                                                        else
                                                                            AiBotOrders.IssueTrackedAggressiveMove(oUnit, oMexToConsiderTargetetingInstead:GetPosition(), 5, false, 'IAmMx'..iLandZone)
                                                                        end
                                                                    end
                                                                else
                                                                    if not(IgnoreOrderDueToStuckUnit(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])) then
                                                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], math.max(15, iIndirectDistanceInsideRangeThreshold), false, 'IKAMve'..iLandZone)
                                                                    end
                                                                end
                                                            end
                                                        else
                                                            --Retreat IF units (will only have IF units if are at this point) temporarily from enemy units, unless we are a T1-T2 indirect fire unit that hasnt fired for a while and enemy isn't in our range yet
                                                            local iCurDistToDFEnemy = 1000
                                                            if oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] then
                                                                iCurDistToDFEnemy = AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition())
                                                                if bDebugMessages == true then LOG(sFunctionRef..': refoClosestEnemyFromLastCloseToEnemyUnitCheck='..oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])..'; DFRange='..(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 'nil')..'; iCurDistToDFEnemy='..iCurDistToDFEnemy..'; Unit speed='..AiBotUnitInfo.GetUnitSpeed(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])) end
                                                            end
                                                            local bTemporaryKiting = false

                                                            if (oUnit[AiBotUnitInfo.refiIndirectAOE] or 0) > 0 and oUnit[AiBotUnitInfo.refiTimeBetweenIFShots] and AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or -1) > 1 + oUnit[AiBotUnitInfo.refiTimeBetweenIFShots] * 1.2 and iCurDistToDFEnemy > (oUnit[AiBotUnitInfo.refiIndirectRange] or 0)
                                                                    --exception - if up against a DF unit that outranges us, or almost outranges us and is moving
                                                                    and (not(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) or (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 0) + 4 < oUnit[AiBotUnitInfo.refiCombatRange] or (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] < oUnit[AiBotUnitInfo.refiCombatRange] and AiBotUnitInfo.GetUnitSpeed(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) < 0.2)) then

                                                                --Ground fire near the enemy unit
                                                                --MoveInDirection(tStart, iAngle, iDistance, bKeepInMapBounds, bTravelUnderwater, bKeepInCampaignPlayableArea)
                                                                local tGroundFireLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition()), oUnit[AiBotUnitInfo.refiIndirectRange] - 2, true, false, AiBotMap.bIsCampaignMap)
                                                                AiBotOrders.IssueTrackedGroundAttack(oUnit, tGroundFireLocation, 2, false, 'IFKiAG'..iLandZone, false, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])
                                                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                                                                oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                                if (oUnit[AiBotUnitInfo.refbWeaponUnpacks] or not(oUnit[AiBotUnitInfo.refbCanKite])) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tAmphibiousRallyPoint) <= 13 then
                                                                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tAmphibiousRallyPoint, 6, false, 'AIKRetr'..iLandZone)
                                                                else
                                                                    AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'AIKRetr'..iLandZone)
                                                                end
                                                            else
                                                                if iCurDistToDFEnemy <= math.max((oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] or 0) + 8, (oUnit[AiBotUnitInfo.refiCombatRange] or 0) - 10) then
                                                                    local tTemporaryRetreatLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()), 8, true, false, AiBotMap.bIsCampaignMap)
                                                                    if tTemporaryRetreatLocation and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tTemporaryRetreatLocation) == tLZData[AiBotMap.subrefLZIslandRef] then
                                                                        bTemporaryKiting = true
                                                                        oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                                        AiBotOrders.IssueTrackedMove(oUnit, tTemporaryRetreatLocation, 6, false, 'IKEnRetr'..iLandZone)
                                                                    end
                                                                end
                                                                if not(bTemporaryKiting) then
                                                                    if (oUnit[AiBotUnitInfo.refbWeaponUnpacks] or not(oUnit[AiBotUnitInfo.refbCanKite])) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint) <= 13 then
                                                                        oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, tRallyPoint, 6, false, 'IKRetr'..iLandZone)
                                                                    else
                                                                        oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                                        AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'IKRetr'..iLandZone)
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            else
                                                --Consider if there are enemies in other adjacent zones that we do outrange
                                                if bDebugMessages == true and bConsiderAttackingAdjacentZoneEnemyWithOutrangedUnits == nil then LOG(sFunctionRef..': Considering if enemy has units in adj zone that we outrange even if we dont outrange cur zone, subrefLZThreatEnemyBestMobileDFRange='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange]..'; refiIndirectRange='..oUnit[AiBotUnitInfo.refiIndirectRange]) end
                                                if bConsiderAttackingAdjacentZoneEnemyWithOutrangedUnits == nil then
                                                    if tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > 0 then
                                                        bConsiderAttackingAdjacentZoneEnemyWithOutrangedUnits = false
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy has nearby LR DF threat so wont consider') end
                                                    elseif tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] < oUnit[AiBotUnitInfo.refiIndirectRange] or tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] < 50 then
                                                        bConsiderAttackingAdjacentZoneEnemyWithOutrangedUnits = false

                                                        --Is there an adjacent zone we could target? only consider if enemy mobile DF threat is outranged by us
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will check for vulnerable enemy units we outrange in adjacent zones, is subrefLZAdjacentLandZones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]))) end
                                                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                            local toEnemiesThatOutrangeUs = {}
                                                            for iRecordedEnemy, oRecordedEnemy in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                                if oRecordedEnemy[AiBotUnitInfo.refiCombatRange] >= oUnit[AiBotUnitInfo.refiIndirectRange] then
                                                                    table.insert(toEnemiesThatOutrangeUs, oRecordedEnemy)
                                                                end
                                                            end
                                                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                                local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                                                local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; subrefLZThreatEnemyBestMobileDFRange='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange]..'; subrefLZThreatEnemyBestStructureDFRange (which factors in nearest adj zone)='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange]..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                                                                if tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] < oUnit[AiBotUnitInfo.refiIndirectRange] and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                                                    --Get closest enemy unit in this zone
                                                                    local oClosestAdjacentPotentialEnemy
                                                                    local iClosestAdjacentPotentialEnemy = 200
                                                                    for iAdjacentEnemy, oAdjacentEnemy in tAdjLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oAdjacentEnemy:GetPosition())
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Checking for vulnerable targets we outrange in adj zone, oAdjacentEnemy='..oAdjacentEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAdjacentEnemy)..'; iCurDist='..iCurDist) end
                                                                        if iCurDist < iClosestAdjacentPotentialEnemy then
                                                                            iClosestAdjacentPotentialEnemy = iCurDist
                                                                            oClosestAdjacentPotentialEnemy = oAdjacentEnemy
                                                                        end
                                                                    end
                                                                    if oClosestAdjacentPotentialEnemy then
                                                                        --Is this near any of the enemies that outrange us?
                                                                        local bNearToLongerRangedEnemies = false
                                                                        if AiBotUtilities.IsTableEmpty(toEnemiesThatOutrangeUs) == false then
                                                                            local iAngleToPotentialEnemy = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oClosestAdjacentPotentialEnemy:GetPosition())
                                                                            if bDebugMessages == true then LOG(sFunctionRef..': oClosestAdjacentPotentialEnemy='..oClosestAdjacentPotentialEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestAdjacentPotentialEnemy)..'; iAngleToPotentialEnemy='..iAngleToPotentialEnemy) end
                                                                            for iEnemyToAvoid, oEnemyToAvoid in toEnemiesThatOutrangeUs do
                                                                                if bDebugMessages == true then LOG(sFunctionRef..': oEnemyToAvoid='..oEnemyToAvoid.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToAvoid)..'; Dist to oClosestAdjacentPotentialEnemy='..AiBotUtilities.GetDistanceBetweenPositions(oEnemyToAvoid:GetPosition(), oClosestAdjacentPotentialEnemy:GetPosition())..' Combat range='..oEnemyToAvoid[AiBotUnitInfo.refiCombatRange]..'; Angle from oUnit to oEnemyToAvoid='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemyToAvoid:GetPosition())..'; Angle Dif='..AiBotUtilities.GetAngleDifference(iAngleToPotentialEnemy, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemyToAvoid:GetPosition()))) end
                                                                                if AiBotUtilities.GetDistanceBetweenPositions(oEnemyToAvoid:GetPosition(), oClosestAdjacentPotentialEnemy:GetPosition()) <= 35 + oEnemyToAvoid[AiBotUnitInfo.refiCombatRange] then
                                                                                    bNearToLongerRangedEnemies = true
                                                                                    break
                                                                                elseif AiBotUtilities.GetAngleDifference(iAngleToPotentialEnemy, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemyToAvoid:GetPosition())) <= 20 then
                                                                                    bNearToLongerRangedEnemies = true
                                                                                    break
                                                                                end
                                                                            end
                                                                        end
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': bNearToLongerRangedEnemies='..tostring(bNearToLongerRangedEnemies)) end
                                                                        if not(bNearToLongerRangedEnemies) then
                                                                            oAdjacentZoneEnemyToAttackWithOutrangedIF = oClosestAdjacentPotentialEnemy
                                                                            bConsiderAttackingAdjacentZoneEnemyWithOutrangedUnits = true
                                                                            break
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                                if bConsiderAttackingAdjacentZoneEnemyWithOutrangedUnits and GivenIndirectAdjacentZoneKitingOrder(oUnit) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will try attacking enemy unit in adjacent zone that this unit outranges') end
                                                else
                                                    --Treat the same as outranged DF units
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding IF unit to outranged combat units') end
                                                    table.insert(tOutrangedCombatUnits, oUnit)
                                                end
                                            end
                                        else
                                            AiBotUtilities.ErrorHandler('Have a unit without DF or indirect range, so will retreat with it')
                                            if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                                                oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'AUnkRetr'..iLandZone)
                                            else
                                                oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'UnkRetr'..iLandZone)
                                            end
                                        end
                                    elseif (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > iEnemyBestDFRange then
                                        table.insert(tUnitsToSupport, oUnit)
                                    end
                                end
                                if not(bAreInScenario1) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have decided part-way through loop we arent in scenario1 afterall so aborting loop') end
                                    break
                                end
                            end

                            if AiBotUtilities.IsTableEmpty(tOutrangedCombatUnits) == false then
                                if bDebugMessages == true then LOG(sFunctionRef..': Have outranged combat units, bAttackWithOutrangedDFUnits='..tostring(bAttackWithOutrangedDFUnits or false)..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; GetEnemyCombatThreatInAdjacentZones()='..GetEnemyCombatThreatInAdjacentZones()..'; bHaveSRExperimentalsInCombat='..tostring(bHaveSRExperimentalsInCombat)..'; bAreInScenario1='..tostring(bAreInScenario1)) end
                                if bHaveSRExperimentalsInCombat then bAttackWithOutrangedDFUnits = true end
                                ProtectFriendlyACUInTroubleIfRelevant(tOutrangedCombatUnits)
                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of outranged units empty after checking for supporting ACU in trouble='..tostring(AiBotUtilities.IsTableEmpty(tOutrangedCombatUnits))) end
                                if not(bHaveACUInTroubleAndRecentlyInCombat) or AiBotUtilities.IsTableEmpty(tOutrangedCombatUnits) == false then
                                    --Consider still attacking if we have a large threat for our outranged combat units
                                    local iOutrangedThreat
                                    if not(bAttackWithOutrangedDFUnits) then
                                        if bSuicideIntoFatboyOrACU and oClosestFatboyOrACUInIslandToSuicideInto then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to suicide into fatboy or ACU so will attack with outranged DF units after all') end
                                            bAttackWithOutrangedDFUnits = true
                                        else
                                            CalculateNearbyEnemyCombatThreatFriendlyDFAndIfFriendlyACUInCombat(tOutrangedCombatUnits)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Deciding if want to attack with outranged units, iOurDFAndT1ArtiCombatThreat using only SR units='..(iOurDFAndT1ArtiCombatThreat or 'nil')..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; Enemy combat in adj zones='..GetEnemyCombatThreatInAdjacentZones()..'; iOutrangedThreat='..AiBotUnitInfo.GetCombatThreatRating(tOutrangedCombatUnits, false, false)..'; iEnemyCombatThreat='..(iEnemyCombatThreat or 'nil')) end
                                            if iOurDFAndT1ArtiCombatThreat > iEnemyCombatThreat then
                                                if iOurDFAndT1ArtiCombatThreat > iEnemyCombatThreat * 5 or (iOurDFAndT1ArtiCombatThreat >= 16000 and iOurDFAndT1ArtiCombatThreat > iEnemyCombatThreat * 1.5) then
                                                    bAttackWithOutrangedDFUnits = true
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering only enemy units nearby, we have enough to attack, iEnemyCombatThreat='..iEnemyCombatThreat..'; iOurDFAndT1ArtiCombatThreat='..iOurDFAndT1ArtiCombatThreat) end
                                                else
                                                    iOutrangedThreat = AiBotUnitInfo.GetCombatThreatRating(tOutrangedCombatUnits, false, false)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Our iOutrangedThreat='..iOutrangedThreat..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; iEnemyBestDFRange='..iEnemyBestDFRange..'; iFriendlyBestMobileDFRange='..iFriendlyBestMobileDFRange..'; iEnemyBestStructureDFRange='..(iEnemyBestStructureDFRange or 'nil')..'; iFirebaseThreatAdjust='..iFirebaseThreatAdjust..'; oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange]='..(oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 'nil')) end
                                                    if iOutrangedThreat / iAvailableCombatUnitThreat >= 0.8 then
                                                        bAttackWithOutrangedDFUnits = true
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Our long ranged threat is only a small proportion of our total combat threat so we will attack with everything') end
                                                    elseif iEnemyBestDFRange <= 26 and iFriendlyBestMobileDFRange <= 33 and iOutrangedThreat / iAvailableCombatUnitThreat >= 0.25 and (iEnemyBestStructureDFRange or 0) == 0 and iFirebaseThreatAdjust == 0 and (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) <= 26 then
                                                        bAttackWithOutrangedDFUnits = true
                                                        if bDebugMessages == true then LOG(sFunctionRef..': our and enemy ranges suggest may still be at the t1 stage so will attack as a significant part of our force is SR units, and overall we think we have enough threat to handle enemy') end
                                                    elseif iOutrangedThreat > iEnemyCombatThreat * 1.5 then
                                                        if iOutrangedThreat > iEnemyCombatThreat * 3 or (iOutrangedThreat > iEnemyCombatThreat * 2.5 and iOutrangedThreat / iAvailableCombatUnitThreat >= 0.5) then
                                                            bAttackWithOutrangedDFUnits = true
                                                        else
                                                            --Get threat of SR units near the nearest enemy unit - if we have enough of a force with SR units alone then press attack
                                                            local oClosestSRUnitToEnemy
                                                            local iClosestSRUnitToEnemy = 100000
                                                            for iSRUnit, oSRUnit in tOutrangedCombatUnits do
                                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oSRUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - oSRUnit[AiBotUnitInfo.refiCombatRange]
                                                                if iCurDist < iClosestSRUnitToEnemy then
                                                                    iClosestSRUnitToEnemy =  iCurDist
                                                                    oClosestSRUnitToEnemy = oSRUnit
                                                                end
                                                            end
                                                            local iSRThreatNearFront = 0
                                                            for iCurSRUnit = table.getn(tOutrangedCombatUnits), 1, -1 do
                                                                local oSRUnit = tOutrangedCombatUnits[iCurSRUnit]
                                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oSRUnit:GetPosition(), oClosestSRUnitToEnemy:GetPosition()) + oClosestSRUnitToEnemy[AiBotUnitInfo.refiCombatRange] - oSRUnit[AiBotUnitInfo.refiCombatRange]
                                                                if iCurDist <= 40 then
                                                                    iSRThreatNearFront = iSRThreatNearFront + (oSRUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oSRUnit))
                                                                else
                                                                    --Consolidate further away SR Units
                                                                    AiBotOrders.IssueTrackedMove(oSRUnit, oClosestSRUnitToEnemy:GetPosition(), 5, false, 'SRConsol', false)
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will consoliate further away SRUnit='..oSRUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSRUnit)) end
                                                                    table.remove(tOutrangedCombatUnits, iCurSRUnit)
                                                                end
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': iSRThreatNearFront='..iSRThreatNearFront..'; iEnemyCombatThreat='..iEnemyCombatThreat..'; iOutrangedThreat / iAvailableCombatUnitThreat='..iOutrangedThreat / iAvailableCombatUnitThreat) end
                                                            if iSRThreatNearFront > iEnemyCombatThreat and (iSRThreatNearFront > iEnemyCombatThreat * 1.5 or (iSRThreatNearFront > iEnemyCombatThreat * 1.2 and iOutrangedThreat / iAvailableCombatUnitThreat >= 0.55)) then
                                                                bAttackWithOutrangedDFUnits = true
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    --Override for if enemy ACU nearby
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering adjustment if want to attack with outranged DF units but enemy has ACU nearby, bAttackWithOutrangedDFUnits before adjust='..tostring(bAttackWithOutrangedDFUnits)..'; Is table of ACUs in zone empty='..tostring(AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone))..'; bConsiderAttackingACU='..tostring(bConsiderAttackingACU)) end
                                    if bAttackWithOutrangedDFUnits and iAvailableCombatUnitThreat < 12000 and AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone) == false and not(bConsiderAttackingACU) then
                                        --If enemy ACU is within 30 of the closest enemy unit then dont attack with outranged DF units
                                        local iDistThresholdForACU = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) - 30
                                        local iDistToNearestEnemyThreshold = 30
                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oNearestEnemyToFriendlyBase.UnitId) and (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) <= 10 then
                                            iDistThresholdForACU = iDistThresholdForACU + 7
                                            iDistToNearestEnemyThreshold = iDistToNearestEnemyThreshold - 7
                                        end
                                        for iACU, oACU in toEnemyACUsNearZone do
                                            if bDebugMessages == true then LOG(sFunctionRef..': Dist between ACU and nearest enemy to friendly base='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())) end
                                            if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) <= iDistToNearestEnemyThreshold or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= iDistThresholdForACU then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy ACU is too close to nearest enemy unit so wont have our SR DF units attack') end
                                                bAttackWithOutrangedDFUnits = false
                                                break
                                            end
                                        end
                                    end
                                    if bAttackWithOutrangedDFUnits then
                                        local bDelaySRInfrontIfNotInRange = false
                                        local oNearestFriendlyUnitToNearestEnemyIfConsolidating
                                        local oEnemyToConsiderForLRUnit
                                        local bCurUnitWantsToConsolidate = false
                                        local iDistFromLRUnitToEnemy --Only used if bDelaySRInfrontIfNotInRange is true
                                        if not(bHaveACUInTroubleAndRecentlyInCombat) and  AiBotUtilities.IsTableEmpty(tUnitsToSupport) == false then
                                            if not(iOutrangedThreat) then iOutrangedThreat = AiBotUnitInfo.GetCombatThreatRating(tOutrangedCombatUnits, false, false) end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to consolidate SR units rather than attack, iOutrangedThreat='..iOutrangedThreat..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat) end
                                            if iOutrangedThreat < 0.5 * iAvailableCombatUnitThreat then
                                                if not(iEnemyCombatThreat) then CalculateNearbyEnemyCombatThreatFriendlyDFAndIfFriendlyACUInCombat(tOutrangedCombatUnits) end
                                                if bDebugMessages == true then LOG(sFunctionRef..': iEnemyCombatThreat='..iEnemyCombatThreat) end
                                                if iOutrangedThreat < iEnemyCombatThreat then
                                                    bDelaySRInfrontIfNotInRange = true
                                                    --are units to support in combat? if not get closest one
                                                    local iClosestUnitToSupportDist = 10000
                                                    for iUnit, oUnit in tUnitsToSupport do
                                                        if AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and not(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] == oNearestEnemyToFriendlyBase) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) <= math.max((oUnit[AiBotUnitInfo.refiCombatRange] or 0), (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] or 0), 20) then
                                                            bDelaySRInfrontIfNotInRange = false
                                                            break
                                                        else
                                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())
                                                            if iCurDist < iClosestUnitToSupportDist then
                                                                iClosestUnitToSupportDist = iCurDist
                                                                oNearestFriendlyUnitToNearestEnemyIfConsolidating = oUnit
                                                                if iCurDist < math.max((oUnit[AiBotUnitInfo.refiCombatRange] or 0), 20, (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] or 0)) then
                                                                    break
                                                                end
                                                            end
                                                        end
                                                    end
                                                    if not(oNearestFriendlyUnitToNearestEnemyIfConsolidating) then bDelaySRInfrontIfNotInRange = false end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': iClosestUnitToSupportDist='..iClosestUnitToSupportDist..'; oNearestFriendlyUnitToNearestEnemyIfConsolidating='..(oNearestFriendlyUnitToNearestEnemyIfConsolidating.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestFriendlyUnitToNearestEnemyIfConsolidating) or 'nil')..'; bDelaySRInfrontIfNotInRange='..tostring(bDelaySRInfrontIfNotInRange)) end
                                                    if bDelaySRInfrontIfNotInRange then
                                                        iDistFromLRUnitToEnemy = AiBotUtilities.GetDistanceBetweenPositions(oNearestFriendlyUnitToNearestEnemyIfConsolidating:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())
                                                        if AiBotUnitInfo.IsUnitValid(oNearestFriendlyUnitToNearestEnemyIfConsolidating[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and not(oNearestFriendlyUnitToNearestEnemyIfConsolidating[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] == oNearestEnemyToFriendlyBase) then
                                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oNearestFriendlyUnitToNearestEnemyIfConsolidating:GetPosition(), oNearestFriendlyUnitToNearestEnemyIfConsolidating[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())

                                                            if iCurDist - (oNearestFriendlyUnitToNearestEnemyIfConsolidating[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] or 0) < iDistFromLRUnitToEnemy - (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] or 0) then
                                                                oEnemyToConsiderForLRUnit = oNearestFriendlyUnitToNearestEnemyIfConsolidating[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]
                                                                iDistFromLRUnitToEnemy = iCurDist
                                                            else
                                                                oEnemyToConsiderForLRUnit = oNearestEnemyToFriendlyBase
                                                            end
                                                        else
                                                            oEnemyToConsiderForLRUnit = oNearestEnemyToFriendlyBase
                                                        end
                                                        --Check we dont have any SR units in range of this enemy
                                                        for iUnit, oUnit in tOutrangedCombatUnits do
                                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEnemyToConsiderForLRUnit:GetPosition()) <= 1 + math.max(oUnit[AiBotUnitInfo.refiCombatRange], (oEnemyToConsiderForLRUnit[AiBotUnitInfo.refiCombatRange] or 0)) then
                                                                if bDebugMessages == true then LOG(sFunctionRef..': We have SR unit oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' in range of oEnemyToConsiderForLRUnit='..oEnemyToConsiderForLRUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToConsiderForLRUnit)..'; Dist between them='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEnemyToConsiderForLRUnit:GetPosition())) end
                                                                bDelaySRInfrontIfNotInRange = false
                                                                break
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Finsihed considering bDelaySRInfrontIfNotInRange='..tostring(bDelaySRInfrontIfNotInRange)) end
                                        end
                                        if oNearestEnemyToFriendlyBase and oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] then AiBotNavy.RecordWaterZoneTarget(tLZTeamData, iLandZone, iTeam, false, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam], AiBotMap.subrefiLZOrWZTAttackingUnit, true) end
                                        for iUnit, oUnit in tOutrangedCombatUnits do
                                            if bCheckIfNearestUnitVisible and not(bUpdateNearestUnit) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 18 then bUpdateNearestUnit = true end

                                            if bMoveBlockedNotAttackMove and (oUnit[AiBotUnitInfo.refbLastShotBlocked] or AiBotUnitInfo.IsUnitUnderwater(oUnit)) and not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId)) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride]) then
                                                AiBotOrders.IssueTrackedMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], 6, false, 'OBlckM'..iLandZone)
                                                --If we are close to the last known position such that we will be able to see there is no longer a unit there, then update this unit's position for next cycle
                                            else
                                                if oUnit[AiBotUnitInfo.refbEasyBrain] then
                                                    if not(IgnoreOrderDueToStuckUnit(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])) then
                                                        AiBotOrders.IssueTrackedAttackMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], 6, false, 'EsySRAM'..iLandZone)
                                                    end
                                                else
                                                    if bConsiderAttackingACU and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental - AiBotUnitInfo.refCategorySkirmisher - AiBotUnitInfo.refCategoryFatboy - AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride]) and AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), toEnemyACUsNearZone, 6 + oUnit[AiBotUnitInfo.refiDFRange], iTeam, false, nil, nil, nil, nil, nil) then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Want to attack ACU with experimental') end
                                                        GetUnitToAttackNearestACUOrOverrideUnit(oUnit)
                                                        --Attackmove (unless we have far more threat in this zone)

                                                    elseif oUnit[AiBotAir.refiTimeLastDropped] and oUnit[AiBotUnitInfo.refiIndirectRange] > 0 and GetGameTimeSeconds() - oUnit[AiBotAir.refiTimeLastDropped] <= 60 and oNearestEnemyStructureToMidpoint then
                                                        SuicideUnitIntoEnemyStructure(oUnit)
                                                    else

                                                        --First check if we want to support LR unit that isnt in combat yet
                                                        bCurUnitWantsToConsolidate = false
                                                        if bDelaySRInfrontIfNotInRange then
                                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEnemyToConsiderForLRUnit:GetPosition())
                                                            if iCurDist < iDistFromLRUnitToEnemy and iCurDist < iDistFromLRUnitToEnemy + 4 then
                                                                bCurUnitWantsToConsolidate = true
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': iCurDist from oEnemyToConsiderForLRUnit='..iCurDist..'; bCurUnitWantsToConsolidate='..tostring(bCurUnitWantsToConsolidate)) end
                                                        end
                                                        if bCurUnitWantsToConsolidate then
                                                            --Move towards the LR unit to support
                                                            --if not(IgnoreOrderDueToStuckUnit(oUnit)) then - decided not to add this in here as we are following LR unit
                                                            local tPositionToMoveTo = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oNearestFriendlyUnitToNearestEnemyIfConsolidating:GetPosition()), 6, false, false, false)
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Will attack move towards LR unit to support as we are closer to the enemy than they are') end
                                                            AiBotOrders.IssueTrackedAggressiveMove(oUnit, (tPositionToMoveTo or oNearestFriendlyUnitToNearestEnemyIfConsolidating:GetPosition()), 3, false, 'SRCons'..iLandZone)

                                                        else
                                                            local oTargetToManuallyAttack, bMoveNotManualAttack = GetManualAttackTargetIfWantManualAttack(oUnit)
                                                            oUnit[refoSREnemyTarget] = oTargetToManuallyAttack
                                                            if not(oTargetToManuallyAttack) then oUnit[refoSREnemyTarget] = oNearestEnemyToFriendlyBase end
                                                            oUnit[refiTimeOfSREnemyTarget] = GetGameTimeSeconds()
                                                            if oTargetToManuallyAttack then
                                                                if bMoveNotManualAttack then AiBotOrders.IssueTrackedMove(oUnit, oTargetToManuallyAttack:GetPosition(), 2, false, 'SRManM', false)
                                                                else
                                                                    DoManualAttack(oUnit, oTargetToManuallyAttack, 'SRManA')
                                                                end
                                                                --AiBotOrders.IssueTrackedAttack(oUnit, oTargetToManuallyAttack, false, 'SRManA', false)
                                                            elseif iAvailableCombatUnitThreat > 5000 and iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 8 and not((oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 64 or EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryFatboy + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId) or oUnit[AiBotUnitInfo.refbScoutCombatOverride]) then
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Want to move unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to SREnemy target='..(oUnit[refoSREnemyTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit[refoSREnemyTarget]) or 'nil')) end
                                                                if not(IgnoreOrderDueToStuckUnit(oUnit, oUnit[refoSREnemyTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])) then
                                                                    AiBotOrders.IssueTrackedMove(oUnit, oUnit[refoSREnemyTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, false, 'SRDFM'..iLandZone, false)
                                                                end
                                                            else
                                                                --Exception - experimentals that are in range of enemy PD
                                                                if EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryStructure * categories.TECH2 + categories.TECH3 + categories.COMMAND - AiBotUnitInfo.refCategoryEngineer, oNearestEnemyToFriendlyBase.UnitId)) and GetEnemyCombatThreatInAdjacentZones() >= 5000 then
                                                                    --Want to try and find nearby enemy high value units
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Dealing with experimental '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' so will look for high value enemuy threats nearby to target') end
                                                                    if EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryStructure * categories.TECH2 + categories.TECH3 + categories.COMMAND - AiBotUnitInfo.refCategoryEngineer, oNearestEnemyToFriendlyBase.UnitId)) and GetEnemyCombatThreatInAdjacentZones() >= 5000 then
                                                                        local tNearbyHighValueUnits = oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryExperimentalLevel + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryStructure * categories.TECH3 - AiBotUnitInfo.refCategoryFatboy - AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryPD + categories.COMMAND, oUnit:GetPosition(), (oUnit[AiBotUnitInfo.refiDFRange] or 20) + 15, 'Enemy')
                                                                        local bMoveNotAttack = false
                                                                        if AiBotUtilities.IsTableEmpty(tNearbyHighValueUnits) == false then
                                                                            local tACUsInNearbyHighValueUnits = EntityCategoryFilterDown(categories.COMMAND, tNearbyHighValueUnits)
                                                                            oTargetToManuallyAttack = nil
                                                                            if AiBotUtilities.IsTableEmpty( tACUsInNearbyHighValueUnits) == false then
                                                                                oTargetToManuallyAttack, bMoveNotAttack = GetManualAttackTargetIfWantManualAttack(oUnit)
                                                                            end
                                                                            if not(oTargetToManuallyAttack) then
                                                                                oTargetToManuallyAttack = AiBotUtilities.GetNearestUnit(tNearbyHighValueUnits, oUnit:GetPosition())
                                                                            end
                                                                        end
                                                                        if oTargetToManuallyAttack and not(oTargetToManuallyAttack:IsUnitState('Attached')) and not(AiBotUnitInfo.IsUnitUnderwater(oTargetToManuallyAttack)) then
                                                                            if not(bMoveNotAttack) and AiBotUtilities.GetDistanceBetweenPositions(oTargetToManuallyAttack:GetPosition(), oUnit:GetPosition()) <= (oUnit[AiBotUnitInfo.refiDFRange] or 0) + 1 then
                                                                                DoManualAttack(oUnit, oTargetToManuallyAttack, 'SRManX')
                                                                                --AiBotOrders.IssueTrackedAttack(oUnit, oTargetToManuallyAttack, false, 'SRManA', false)
                                                                            else
                                                                                AiBotOrders.IssueTrackedMove(oUnit, oTargetToManuallyAttack:GetPosition(), 10, 'SRxpTO', false)
                                                                            end
                                                                            if bDebugMessages == true then LOG(sFunctionRef..': Targeting oTargetToManuallyAttack='..oTargetToManuallyAttack.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTargetToManuallyAttack)) end
                                                                        else
                                                                            if not(IgnoreOrderDueToStuckUnit(oUnit, oUnit[refoSREnemyTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])) then
                                                                                if oUnit[AiBotUnitInfo.refiWeaponScanRange] and oUnit[AiBotUnitInfo.refiWeaponScanRange] + 5 < oUnit[AiBotUnitInfo.refiCombatRange] then
                                                                                    ConsiderManualAttackInsteadOfAttackMove(oUnit, oUnit[refoSREnemyTarget], oUnit[refoSREnemyTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, 'SRDFEA')
                                                                                else
                                                                                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, oUnit[refoSREnemyTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, false, 'SRDFEA'..iLandZone)
                                                                                end
                                                                            end
                                                                        end
                                                                    else
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Targeting nearest SR enemy target via attack move, target='..oUnit[refoSREnemyTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[refoSREnemyTarget])) end
                                                                        if not(IgnoreOrderDueToStuckUnit(oUnit, oUnit[refoSREnemyTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])) then
                                                                            if oUnit[AiBotUnitInfo.refiWeaponScanRange] and oUnit[AiBotUnitInfo.refiWeaponScanRange] + 5 < oUnit[AiBotUnitInfo.refiCombatRange] then
                                                                                ConsiderManualAttackInsteadOfAttackMove(oUnit, oUnit[refoSREnemyTarget], oUnit[refoSREnemyTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, 'SRDFExA')
                                                                            else
                                                                                AiBotOrders.IssueTrackedAggressiveMove(oUnit, oUnit[refoSREnemyTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, false, 'SRDFExA'..iLandZone)
                                                                            end
                                                                        end
                                                                    end
                                                                else
                                                                    if not(IgnoreOrderDueToStuckUnit(oUnit, oUnit[refoSREnemyTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])) then
                                                                        if oUnit[AiBotUnitInfo.refiWeaponScanRange] and oUnit[AiBotUnitInfo.refiWeaponScanRange] + 5 < oUnit[AiBotUnitInfo.refiCombatRange] then
                                                                            ConsiderManualAttackInsteadOfAttackMove(oUnit, oUnit[refoSREnemyTarget], oUnit[refoSREnemyTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, 'SRDFA')
                                                                        else
                                                                            AiBotOrders.IssueTrackedAggressiveMove(oUnit, oUnit[refoSREnemyTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, false, 'SRDFA'..iLandZone)
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    else
                                        --Arent attacking enemy with SR units so just want to be nearby to be ready to support
                                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of units to support empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToSupport))) end
                                        if bAreInScenario1 and AiBotUtilities.IsTableEmpty(tUnitsToSupport) == false then
                                            --Short range DF units can stay back and provide support - stay inbetween our long range DF units and the rally point

                                            local iCurDist
                                            local iClosestDist = 100000
                                            local oClosestUnit
                                            local iDistToRetreat = 10
                                            local bNearestEnemyIsExperimental = false
                                            if EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oNearestEnemyToFriendlyBase.UnitId) then
                                                bNearestEnemyIsExperimental = true
                                            end

                                            local tNearbyEnemyDFExperimentals = {}
                                            local bEnemyHasNearbyExperimentals = false
                                            if oNearestEnemyToFriendlyBase and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                tNearbyEnemyDFExperimentals = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental, tLZTeamData[AiBotMap.reftoNearestDFEnemies])
                                                if AiBotUtilities.IsTableEmpty(tNearbyEnemyDFExperimentals) == false then
                                                    bEnemyHasNearbyExperimentals = true
                                                end
                                            end

                                            local tSRRallyOverride --Used if nearest enemy is a similar angle as our closest friendly base
                                            if oNearestEnemyToFriendlyBase then
                                                local oClosestLRToRally
                                                local iClosestLRToRally = 100000
                                                for iLRUnit, oLRUnit in tUnitsToSupport do
                                                    iCurDist = AiBotUtilities.GetRoughDistanceBetweenPositions(oLRUnit:GetPosition(), tAmphibiousRallyPoint)
                                                    if iCurDist < iClosestLRToRally then
                                                        iClosestLRToRally = iCurDist
                                                        oClosestLRToRally = oLRUnit
                                                    end
                                                end
                                                local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oClosestLRToRally:GetPosition(), tAmphibiousRallyPoint)
                                                local iAngleToNearestEnemy = AiBotUtilities.GetAngleFromAToB(oClosestLRToRally:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())
                                                if bDebugMessages == true then LOG(sFunctionRef..': oClosestLRToRally='..oClosestLRToRally.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestLRToRally)..'; iAngleToRally='..iAngleToRally..'; iAngleToNearestEnemy='..iAngleToNearestEnemy..'; Angle dif='..AiBotUtilities.GetAngleDifference(iAngleToRally, iAngleToNearestEnemy)) end
                                                if AiBotUtilities.GetAngleDifference(iAngleToRally, iAngleToNearestEnemy) <= 90 then
                                                    tSRRallyOverride = AiBotUtilities.MoveInDirection(oClosestLRToRally:GetPosition(), iAngleToNearestEnemy + 180, 20, true, nil, not(AiBotMap.bIsCampaignMap))
                                                    if bDebugMessages == true then
                                                        LOG(sFunctionRef..': Land label of tSRRallyOverride='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tSRRallyOverride) or 'nil')..'; Island ref of this LZ='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil'))
                                                        --AiBotUtilities.DrawLocation(tSRRallyOverride)
                                                    end
                                                    if tSRRallyOverride and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tSRRallyOverride) == tLZData[AiBotMap.subrefLZIslandRef] then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Setting SR rally override so we go away from the nearest enemy to our base due to risk otherwise that we move closer to that enemy by moving towards the rally') end
                                                    else
                                                        tSRRallyOverride = nil
                                                    end
                                                end
                                            end

                                            --Expand units to support to include friendly units in an adjacent zone if that zone has mobile DF units that outrange our SR threshold (as long ranged units and skirmishers are assigned to the zone they are in)
                                            local iAdjacentRangeThreshold = iDFRangeOverrideForScenario1 or iEnemyBestDFRange
                                            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                local iDistToClosestEnemyFromMidpointThreshold = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oNearestEnemyToFriendlyBase:GetPosition()) + 10
                                                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                    --Is this zone closer to the nearest enemy than our current zone?
                                                    local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                                    if AiBotUtilities.GetDistanceBetweenPositions(tAdjLZData[AiBotMap.subrefMidpoint], oNearestEnemyToFriendlyBase:GetPosition()) <= iDistToClosestEnemyFromMidpointThreshold then
                                                        local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                                        local bHaveLRUnit = false
                                                        if tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] > 0 and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits]) == false and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange]) == false then
                                                            for iRange, iThreat in tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] do
                                                                if iRange >= iAdjacentRangeThreshold and iThreat > 0 then
                                                                    bHaveLRUnit = true
                                                                    break
                                                                end
                                                            end
                                                        end
                                                        if bHaveLRUnit then
                                                            for iAdjUnit, oAdjUnit in tAdjLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits] do
                                                                if oAdjUnit[AiBotUnitInfo.refiDFRange] and oAdjUnit[AiBotUnitInfo.refiDFRange] > iAdjacentRangeThreshold and not(oAdjUnit[refiCurrentAssignmentPlateauAndLZ][2] == iLandZone) and not(oAdjUnit.Dead) then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding unit in adjacent zone to units to support, oAdjUnit='..oAdjUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAdjUnit)..' with range='..oAdjUnit[AiBotUnitInfo.refiDFRange]) end
                                                                    table.insert(tUnitsToSupport, oAdjUnit)
                                                                end
                                                            end
                                                        end
                                                        if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefAlliedACU]) == false then
                                                            if not(tAdjLZTeamData[AiBotMap.subrefLZbCoreBase]) or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]) then --no point supporting an ACU hiding in our base
                                                                for iAdjACU, oAdjACU in tAdjLZTeamData[AiBotMap.subrefAlliedACU] do
                                                                    --If ACU isnt the longest range it wont be included as a unit to support, but we still want to cover it
                                                                    if not(oAdjACU[AiBotACU.refiTimeLastWantedToRun]) or GetGameTimeSeconds() - oAdjACU[AiBotACU.refiTimeLastWantedToRun] >= 10 or (oAdjACU[AiBotUnitInfo.refiLastWeaponEvent] and GetGameTimeSeconds() - oAdjACU[AiBotUnitInfo.refiLastWeaponEvent] <= 10) or tAdjLZTeamData[AiBotMap.refbACUInTrouble] then
                                                                        table.insert(tUnitsToSupport, oAdjACU)
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) == false then
                                                if not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) or tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > 0 or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]) then --no point supporting an ACU hiding in our base
                                                    for iACU, oACU in tLZTeamData[AiBotMap.subrefAlliedACU] do
                                                        --If ACU isnt the longest range it wont be included as a unit to support, but we still want to cover it
                                                        if not(oACU[AiBotACU.refiTimeLastWantedToRun]) or GetGameTimeSeconds() - oACU[AiBotACU.refiTimeLastWantedToRun] >= 10 or (oACU[AiBotUnitInfo.refiLastWeaponEvent] and GetGameTimeSeconds() - oACU[AiBotUnitInfo.refiLastWeaponEvent] <= 10) or tLZTeamData[AiBotMap.refbACUInTrouble] then
                                                            table.insert(tUnitsToSupport, oACU)
                                                        end
                                                    end
                                                end
                                            end

                                            for iSRUnit, oSRUnit in tOutrangedCombatUnits do
                                                --If we are close to the last known position such that we will be able to see there is no longer a unit there, then update this unit's position for next cycle
                                                if bCheckIfNearestUnitVisible and not(bUpdateNearestUnit) and AiBotUtilities.GetDistanceBetweenPositions(oSRUnit:GetPosition(), oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 18 then bUpdateNearestUnit = true end
                                                iClosestDist = 100000
                                                for iLRUnit, oLRUnit in tUnitsToSupport do
                                                    iCurDist = AiBotUtilities.GetRoughDistanceBetweenPositions(oSRUnit:GetPosition(), oLRUnit:GetPosition())
                                                    if iCurDist < iClosestDist then
                                                        iClosestDist = iCurDist
                                                        oClosestUnit = oLRUnit
                                                    end
                                                end
                                                if bNearestEnemyIsACU then iDistToRetreat = 20
                                                elseif bNearestEnemyIsExperimental and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oSRUnit.UnitId)) then iDistToRetreat = 18
                                                elseif tSRRallyOverride then iDistToRetreat = 15
                                                else iDistToRetreat = 10
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': oSRUnit='..oSRUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSRUnit)..'; oSRUnit[AiBotUnitInfo.refbCanKite]='..tostring(oSRUnit[AiBotUnitInfo.refbCanKite] or false)..'; iClosestDist='..iClosestDist..'; oClosestUnit='..(oClosestUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnit))..'; do we have an amphibious oSRUnit='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oSRUnit.UnitId))..'; iDistToRetreat='..iDistToRetreat..'; Is special micro active for SR unit='..tostring(oSRUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Time since micro started='..GetGameTimeSeconds() - (oSRUnit[AiBotUnitInfo.refiGameTimeMicroStarted] or 0)) end
                                                if oSRUnit[AiBotUnitInfo.refbEasyBrain] then
                                                    oSRUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                    AiBotOrders.IssueTrackedAttackMove(oSRUnit, AiBotUtilities.MoveInDirection(oClosestUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oClosestUnit:GetPosition(), (tSRRallyOverride or tRallyPoint)), iDistToRetreat, true, false, true), 4, false, 'SReASup'..iLandZone)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': AiBotEasy so will just attackmove to support oClosestUnit') end
                                                elseif oSRUnit[AiBotAir.refiTimeLastDropped] and oSRUnit[AiBotUnitInfo.refiIndirectRange] > 0 and GetGameTimeSeconds() - oSRUnit[AiBotAir.refiTimeLastDropped] <= 60 and oNearestEnemyStructureToMidpoint then
                                                    SuicideUnitIntoEnemyStructure(oSRUnit)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will suicide into enemy structure') end
                                                else
                                                    if (bConsiderAttackingACU or oSRUnit[AiBotUnitInfo.refiUnitMassCost] >= 17000 and oSRUnit[AiBotUnitInfo.refiDFRange] <= 64 and AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone) == false) and not(oSRUnit[AiBotUnitInfo.refbLastShotBlocked]) and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental - AiBotUnitInfo.refCategorySkirmisher - AiBotUnitInfo.refCategoryFatboy - AiBotUnitInfo.refCategoryAbsolver, oSRUnit.UnitId) and not(oSRUnit[AiBotUnitInfo.refbScoutCombatOverride]) and AiBotConditions.CloseToEnemyUnit(oSRUnit:GetPosition(), toEnemyACUsNearZone, 6 + oSRUnit[AiBotUnitInfo.refiDFRange], iTeam, false, nil, nil, nil, nil, nil) then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Have an experimental we want to attack enemy ACU with') end
                                                        GetUnitToAttackNearestACUOrOverrideUnit(oSRUnit)
                                                        --Non-fatboy experimental - if we are almost in range of enemy experimental unit then attack
                                                    elseif bEnemyHasNearbyExperimentals and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 - AiBotUnitInfo.refCategorySkirmisher - AiBotUnitInfo.refCategoryFatboy - AiBotUnitInfo.refCategoryAbsolver, oSRUnit.UnitId) and not(oSRUnit[AiBotUnitInfo.refbScoutCombatOverride]) and AiBotConditions.CloseToEnemyUnit(oSRUnit:GetPosition(), tNearbyEnemyDFExperimentals, 5, iTeam, true, math.min(oSRUnit[AiBotUnitInfo.refiDFRange] or 20) - 5, oSRUnit, oSRUnit) then

                                                        --Consider manual attack target
                                                        local oTargetToManuallyAttack, bMoveNotManualAttack = GetManualAttackTargetIfWantManualAttack(oSRUnit, oSRUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) or oNearestEnemyToFriendlyBase
                                                        if bMoveNotManualAttack == nil and oTargetToManuallyAttack == oNearestEnemyToFriendlyBase and oNearestEnemyToFriendlyBase then bMoveNotManualAttack = true end

                                                        --Consider moving instead of attacking if not well within range
                                                        if bDebugMessages == true then LOG(sFunctionRef..': SR unit Want to attack or move towards enemy manual attack target, dist to target='..AiBotUtilities.GetDistanceBetweenPositions(oTargetToManuallyAttack:GetPosition(), oSRUnit:GetPosition())..'; Our DF range='..oSRUnit[AiBotUnitInfo.refiDFRange]..'; oTargetToManuallyAttack='..(oTargetToManuallyAttack.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTargetToManuallyAttack) or 'nil')..'; bMoveNotManualAttack='..tostring(bMoveNotManualAttack)) end
                                                        if not(oTargetToManuallyAttack) or bMoveNotManualAttack or AiBotUtilities.GetDistanceBetweenPositions(oTargetToManuallyAttack:GetPosition(), oSRUnit:GetPosition()) > oSRUnit[AiBotUnitInfo.refiDFRange] - 5 then
                                                            AiBotOrders.IssueTrackedMove(oSRUnit, (oTargetToManuallyAttack or oNearestEnemyToFriendlyBase)[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], 6, false, 'ExpSRM'..iLandZone)
                                                        else
                                                            DoManualAttack(oSRUnit, oTargetToManuallyAttack, 'ExpSRA')
                                                        end
                                                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oSRUnit.UnitId) then
                                                        if oSRUnit[AiBotUnitInfo.refbCanKite] then
                                                            if bDebugMessages == true then
                                                                LOG(sFunctionRef..': Want unit to move towards tAmphibiousRallyPoint, position to move to towards this='..repru(AiBotUtilities.MoveInDirection(oClosestUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oClosestUnit:GetPosition(), (tSRRallyOverride or tAmphibiousRallyPoint)), 5, true, false, true))..'; cur position='..repru(oSRUnit:GetPosition())..'; Last orders='..reprs(oSRUnit[AiBotOrders.reftiLastOrders])..'; Angle from cur position to new position='..AiBotUtilities.GetAngleFromAToB(oSRUnit:GetPosition(), tAmphibiousRallyPoint)..'; IgnoreOrderDueToStuckUnit(oSRUnit)='..tostring(IgnoreOrderDueToStuckUnit(oSRUnit) or false))
                                                            end
                                                            --if not(IgnoreOrderDueToStuckUnit(oSRUnit)) then --(removed in v129 as was having cases of SR units suiciding into enemy due to this, and since we are here we want the SR unit to run from enemy and dont have enough threat to overwhelm enemy
                                                            AiBotOrders.IssueTrackedMove(oSRUnit, AiBotUtilities.MoveInDirection(oClosestUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oClosestUnit:GetPosition(), (tSRRallyOverride or tAmphibiousRallyPoint)), iDistToRetreat, true, false, true), 5, false, 'ASRSup'..iLandZone)
                                                            --end
                                                        else
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Will do attackmove to support our unit with longer range') end
                                                            --if not(IgnoreOrderDueToStuckUnit(oSRUnit)) then
                                                            AiBotOrders.IssueTrackedAttackMove(oSRUnit, AiBotUtilities.MoveInDirection(oClosestUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oClosestUnit:GetPosition(), (tSRRallyOverride or tAmphibiousRallyPoint)), iDistToRetreat, true, false, true), 5, false, 'AASRSup'..iLandZone)
                                                            --end
                                                        end

                                                    else
                                                        if oSRUnit[AiBotUnitInfo.refbCanKite] then
                                                            --if not(IgnoreOrderDueToStuckUnit(oSRUnit)) then --(removed in v129 as was having cases of SR units suiciding into enemy due to this, and since we are here we want the SR unit to run from enemy and dont have enough threat to overwhelm enemy
                                                            AiBotOrders.IssueTrackedMove(oSRUnit, AiBotUtilities.MoveInDirection(oClosestUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oClosestUnit:GetPosition(), (tSRRallyOverride or tRallyPoint)), iDistToRetreat, true, false, true), 4, false, 'SRSup'..iLandZone)
                                                            --end
                                                        else
                                                            --if not(IgnoreOrderDueToStuckUnit(oSRUnit)) then
                                                            AiBotOrders.IssueTrackedAttackMove(oSRUnit, AiBotUtilities.MoveInDirection(oClosestUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oClosestUnit:GetPosition(), (tSRRallyOverride or tRallyPoint)), iDistToRetreat, true, false, true), 4, false, 'SRASup'..iLandZone)
                                                            --end
                                                        end
                                                    end
                                                end
                                            end
                                            if not(bAreInScenario1) then --redundancy in case this could happen
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will ignore the decision to cancel scenario 1 as already given our main units who outrange enemy their orders, and was just doing SR unit orders that we changed our mind') end
                                                bAreInScenario1 = true
                                            end
                                        else
                                            --Maybe the units have micro active so arent being included? or we have same range as enemy? havent traced back the code to confirm; however bAttackWithOutrangedDFUnits will be false if have got to here
                                            AiBotUtilities.ErrorHandler('We dont want to attack with outranged SR units, but somehow think we outrange the enemy with DF units, but have no DF units with a long range, so will cancel scenario1 status, P'..iPlateau..'Z'..iLandZone, true)
                                            bAreInScenario1 = false
                                            if bDebugMessages == true then LOG(sFunctionRef..': we dont want to attack with outranged SR units so cancellign scenario1') end
                                        end
                                    end
                                end
                            end

                            if math.max(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]* 0.7,tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] + tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal])  * 1.5 > iAvailableCombatUnitThreat then
                                bWantReinforcements = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Want reinforcements as enemy combat DF exceeds our combat rating, tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; Our combat units rating='..iAvailableCombatUnitThreat) end
                            end

                            if bUpdateNearestUnit and aiBrain then
                                --[[if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
                                    local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                                    if aiBrain then--]]
                                AiBotTeam.UpdateUnitLastKnownPosition(aiBrain, oNearestEnemyToFriendlyBase, true)
                                --[[end
                            else
                                AiBotUtilities.ErrorHandler('No active AiBot brain')
                            end--]]
                            end
                        end
                    end
                end
                if not(bAreInScenario1) then
                    --SCENARIO 2 - we dont outrange enemy with DF, but have slightly more threat than them, or have nowhere left to run
                    local bAttackWithEverything = false
                    if bSuicideIntoFatboyOrACU and oClosestFatboyOrACUInIslandToSuicideInto then
                        if bDebugMessages == true then LOG(sFunctionRef..': We want to suicide into enemy fatboy or ACU') end
                        bAttackWithEverything = true
                    elseif tLZTeamData[AiBotMap.subrefLZbCoreBase] and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false or AiBotUnitInfo.GetCombatThreatRating(tAvailableCombatUnits) >= 2500) and ((tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0) == 0 or (GetGameTimeSeconds() >= 600 or (GetGameTimeSeconds() >= 300 / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] and not(AiBotMap.bIsCampaignMap)))) then
                        --Attack with everything if enemy has any units in core zone, or close to core zone
                        if bDebugMessages == true then LOG(sFunctionRef..': Core base, so attack if enemies here, is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                            bAttackWithEverything = true
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': No enemies in this zone, distance of nearest enemy to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), tLZData[AiBotMap.subrefMidpoint])..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]..'; Is nearest structure to midpoint valid='..tostring(AiBotUnitInfo.IsUnitValid(oNearestEnemyStructureToMidpoint))..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange]='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange]) end

                            if oNearestEnemyToFriendlyBase then
                                local iDistToNearestEnemy
                                iDistToNearestEnemy = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                if iDistToNearestEnemy <= 80 or (iDistToNearestEnemy <= 120 and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] <= 300) or (iDistToNearestEnemy <= 130 and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oNearestEnemyToFriendlyBase.UnitId)) then
                                    --Attack with everything unless nearest enemy unit is a structure and we have indirect threat in this zone or that zone that outranges it

                                    bAttackWithEverything = true
                                elseif oNearestEnemyStructureToMidpoint and AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyStructureToMidpoint:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= 160 and iFriendlyBestMobileIndirectRange >= 50 then
                                    bAttackWithEverything = true
                                end
                                if bDebugMessages == true and oNearestEnemyStructureToMidpoint then LOG(sFunctionRef..': oNearestEnemyStructureToMidpoint='..oNearestEnemyStructureToMidpoint.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyStructureToMidpoint)..'; Distance to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyStructureToMidpoint:GetPosition(), tLZData[AiBotMap.subrefMidpoint])..'; IF range='..iFriendlyBestMobileIndirectRange..'; bAttackWithEverything='..tostring(bAttackWithEverything)) end
                            end
                            if not(bAttackWithEverything) then
                                --Still attack if we have significant threat
                                if table.getn(tAvailableCombatUnits) >= 60 then bAttackWithEverything = true end
                            end
                        end
                    else
                        --Are we close to a core zone and enemy has a structure threat in this zone and we haev indirect fire?
                        if bDebugMessages == true and oNearestEnemyStructureToMidpoint then LOG(sFunctionRef..': Non core zone, oNearestEnemyStructureToMidpoint'..oNearestEnemyStructureToMidpoint.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyStructureToMidpoint)..'; Dist to closest friendly base from this zone midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestFriendlyBase])..'; Enemy structure value='..tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] >= 100) end
                        if oNearestEnemyStructureToMidpoint and iFriendlyBestMobileIndirectRange >= 50 and tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] >= 100 and AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 175 then
                            bAttackWithEverything = true
                        end
                    end
                    local bConsolidateAtMidpoint = false
                    local bOnlyAttackWithUnitsInThisZone = false
                    local bAttackWithLowerThreatRatio = true
                    CalculateNearbyEnemyCombatThreatFriendlyDFAndIfFriendlyACUInCombat()
                    if iOurDFAndT1ArtiCombatThreat > 0 and AiBotUtilities.IsTableEmpty(tOurDFAndT1ArtiUnits) == false then
                        local iOurDFAndT1ArtiUnits = table.getn(tOurDFAndT1ArtiUnits)
                        if not(bAttackWithEverything) and iOurDFAndT1ArtiUnits >= 125 and iOurDFAndT1ArtiUnits - table.getn(tLZTeamData[AiBotMap.subrefTEnemyUnits]) >= 50 and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) or table.getn(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) < iOurDFAndT1ArtiUnits * 0.25) then bAttackWithEverything = true end
                        if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to attack with everything - pre firebase and beachhead adjust bAttackWithEverything='..tostring(bAttackWithEverything)..'; iOurDFAndT1ArtiCombatThreat='..iOurDFAndT1ArtiCombatThreat..'; iEnemyCombatThreat='..iEnemyCombatThreat..'; iFirebaseThreatAdjust='..iFirebaseThreatAdjust..'; bHaveSignificantCombatCloserToFirebase='..tostring(bHaveSignificantCombatCloserToFirebase)..'; tLZTeamData[AiBotMap.subrefLZTValue]='..tLZTeamData[AiBotMap.subrefLZTValue]..'; Have enough threat to attack (ignoring lower modifier for if nearby ACU or if this zone has PD)='..tostring(AiBotConditions.HaveEnoughThreatToAttack(iPlateau, iLandZone, tLZData, tLZTeamData, iOurDFAndT1ArtiCombatThreat, iEnemyCombatThreat, math.max(iFirebaseThreatAdjust, (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0)), bHaveSignificantCombatCloserToFirebase, iTeam))..'; oNearestEnemyToFriendlyBase='..oNearestEnemyToFriendlyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase)..'; Is brain civilian='..tostring(AiBotConditions.IsCivilianBrain(oNearestEnemyToFriendlyBase:GetAIBrain()))..'; iClosestFriendlyUnitToAnEnemyFirebase='..(iClosestFriendlyUnitToAnEnemyFirebase or 'nil')..'; iFirebaseThreatAdjust='..(iFirebaseThreatAdjust or 'nil')) end
                        if not(bAttackWithEverything) and (not(EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oNearestEnemyToFriendlyBase.UnitId)) or not(AiBotConditions.IsCivilianBrain(oNearestEnemyToFriendlyBase:GetAIBrain()))) then
                            if AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone) == false then bAttackWithLowerThreatRatio = false
                            elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures]) == false then bAttackWithLowerThreatRatio = false
                            end
                            --HaveEnoughThreatToAttack(iPlateau, iLandZone, tLZData, tLZTeamData, iOurCombatThreat,             iEnemyCombatThreat, iFirebaseThreatAdjust,                                                                       bHaveSignificantCombatCloserToFirebase, iTeam, iOptionalOverrideDefaultThreatRatioWanted, bOptionalUseSlightlyLowerThreatRatio)
                            if AiBotConditions.HaveEnoughThreatToAttack(iPlateau, iLandZone, tLZData, tLZTeamData, iOurDFAndT1ArtiCombatThreat, iEnemyCombatThreat, math.max(iFirebaseThreatAdjust, (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0)), bHaveSignificantCombatCloserToFirebase, iTeam, nil,                                        bAttackWithLowerThreatRatio) then
                                --Extra check if have a firebase - only want to include friendly units that are near our closest unit to enemy firebase
                                if iClosestFriendlyUnitToAnEnemyFirebase <= 170 and iFirebaseThreatAdjust > 0 then
                                    --Get new combat threat based on allied mobile DF and indirect fire units around this unit
                                    local iSearchRange = math.max(40, math.min(140, 15 + table.getn(tOurDFAndT1ArtiUnits)))

                                    local iNearbyCombatThreat = math.min(iOurDFAndT1ArtiCombatThreat, AiBotUnitInfo.GetCombatThreatRating(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains][1]:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat, oClosestFriendlyUnitToAnEnemyFirebase:GetPosition(), iSearchRange, 'Ally'), false))
                                    if bDebugMessages == true then LOG(sFunctionRef..': Nearby combat threat='..iNearbyCombatThreat..'; iEnemyCombatThreat='..iEnemyCombatThreat) end
                                    if iNearbyCombatThreat > iEnemyCombatThreat * 1.5 or (iNearbyCombatThreat > iEnemyCombatThreat * 1.15 and iNearbyCombatThreat >= 20000) or (iNearbyCombatThreat > iEnemyCombatThreat and bHaveSignificantCombatCloserToFirebase) then
                                        bAttackWithEverything = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Nearby combat threat is greater than enemy, so will attack with everything') end
                                    else
                                        bAttackWithEverything = false
                                        bConsolidateAtMidpoint = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want to consolidate at midpoint instead of attacking with everything') end
                                    end
                                else
                                    bAttackWithEverything = true
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have enough threat to attack, and non earby enemy firebase, so will attack with everything') end
                                end
                                --Extra check if enemy has ACU, to avoid feeding it mass if we only have a slight combat advantage
                                if bAttackWithEverything and not(bConsiderAttackingACU) and AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone) == false and iOurDFAndT1ArtiCombatThreat < math.max(iEnemyCombatThreat * 2, iEnemyCombatThreat + 600) and iFirebaseThreatAdjust == 0 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': enemy has ACU so want to be more cautious, is the closest enemy an ACU='..tostring(EntityCategoryContains(categories.COMMAND, oNearestEnemyToFriendlyBase.UnitId))) end
                                    if EntityCategoryContains(categories.COMMAND, oNearestEnemyToFriendlyBase.UnitId) then
                                        if AiBotUnitInfo.GetUnitHealthPercent(oNearestEnemyToFriendlyBase) >= 0.3 and ((oNearestEnemyToFriendlyBase[AiBotACU.refiUpgradeCount] or 0) >= 2 or AiBotUnitInfo.GetUnitHealthPercent(oNearestEnemyToFriendlyBase) >= 0.5) then
                                            bAttackWithEverything = false
                                        end
                                    else
                                        --Exception - enemy ACU isnt the closest enemy unit, and is far enough away from the closest enemy unit that we can potentially attack to do some damage to it
                                        local iDistThresholdForACU = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) - 30
                                        local iDistToNearestEnemyThreshold = 30
                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oNearestEnemyToFriendlyBase.UnitId) and (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) <= 10 then
                                            iDistThresholdForACU = iDistThresholdForACU + 7
                                            iDistToNearestEnemyThreshold = iDistToNearestEnemyThreshold - 7
                                        end
                                        for iACU, oACU in toEnemyACUsNearZone do
                                            if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= iDistThresholdForACU or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) <= iDistToNearestEnemyThreshold and (AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.3 and ((oACU[AiBotACU.refiUpgradeCount] or 0) >= 2 or AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.5)) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy ACU is too close to nearest enemy unit so wont have our units attack') end
                                                bAttackWithEverything = false
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                            --NOTE: We have "suicide into mex logic" later on; however htis also does a similar thing but is intended to mean units like microbots will be more aggressive early on to target engis and mexes
                            if bDebugMessages == true then LOG(sFunctionRef..': Deciding if we want to try attacking exposed enemy unit, iOurDFAndT1ArtiCombatThreat='..iOurDFAndT1ArtiCombatThreat..'; iEnemyCombatThreat='..iEnemyCombatThreat..'; iFirebaseThreatAdjust='..iFirebaseThreatAdjust..'; oNearestEnemyToFriendlyBase='..oNearestEnemyToFriendlyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase)..'; is table of shields covering empty='..tostring(AiBotUtilities.IsTableEmpty(oNearestEnemyToFriendlyBase[AiBotBuilding.reftoShieldsProvidingCoverage]))) end
                            if not(bAttackWithEverything) and iOurDFAndT1ArtiCombatThreat > 0 and iOurDFAndT1ArtiCombatThreat <= 3500 and iEnemyCombatThreat + (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) <= 5000 and (iFirebaseThreatAdjust == 0 or (EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oNearestEnemyToFriendlyBase.UnitId) and AiBotUtilities.IsTableEmpty(oNearestEnemyToFriendlyBase[AiBotBuilding.reftoShieldsProvidingCoverage])) and (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) == 0 and oNearestEnemyToFriendlyBase and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryStructure - categories.DIRECTFIRE, oNearestEnemyToFriendlyBase.UnitId)) then
                                local iDistToNearestEnemyDFUnitLessRange = 10000
                                local oClosestDFEnemy
                                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                    local iCurDistLessRange
                                    for iEnemy, oEnemy in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                        iCurDistLessRange = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) - (oEnemy[AiBotUnitInfo.refiDFRange] or 0)
                                        if iCurDistLessRange < iDistToNearestEnemyDFUnitLessRange then
                                            iDistToNearestEnemyDFUnitLessRange = iCurDistLessRange
                                            oClosestDFEnemy = oEnemy
                                        end
                                    end
                                end
                                local iDistToNearestEnemy = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oNearestEnemyToFriendlyBase:GetPosition())
                                if bDebugMessages == true then LOG(sFunctionRef..': iDistToNearestEnemy='..iDistToNearestEnemy..'; iDistToNearestEnemyDFUnitLessRange='..iDistToNearestEnemyDFUnitLessRange..'; oClosestDFEnemy='..(oClosestDFEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestDFEnemy) or 'nil')) end
                                if iDistToNearestEnemyDFUnitLessRange > iDistToNearestEnemy + 25 then
                                    --Good chance we can attack the enemy engi/mex before we die
                                    bAttackWithEverything = true
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will try and attack nearest enemy unit') end
                                    --LABs - if closest enemy is at a significantly different angle, then we can potentially still raid (will only c onsider if we have low combat threat for cpu performance reasons and also to avoid a big mass donation)
                                elseif iDistToNearestEnemyDFUnitLessRange >= 50 and iOurDFAndT1ArtiCombatThreat <= 200 and oClosestDFEnemy then
                                    --Get the closet friendly unit to the midpoint
                                    local iClosestFriendlyDist = 1000
                                    local oClosestFriendlyCombat
                                    for iUnit, oUnit in tAvailableCombatUnits do
                                        if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 or ((oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 0 and EntityCategoryContains(categories.TECH1, oUnit.UnitId)) then
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                            if iCurDist < iClosestFriendlyDist then
                                                iClosestFriendlyDist = iCurDist
                                                oClosestFriendlyCombat = oUnit
                                            end
                                        end
                                    end
                                    local iAngleFromFriendlyToDFEnemy = AiBotUtilities.GetAngleFromAToB(oClosestFriendlyCombat:GetPosition(), oClosestDFEnemy:GetPosition())
                                    local iAngleFromFriendlyToNearestEnemy = AiBotUtilities.GetAngleFromAToB(oClosestFriendlyCombat:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())
                                    local iAngleDif = AiBotUtilities.GetAngleDifference(iAngleFromFriendlyToDFEnemy, iAngleFromFriendlyToNearestEnemy)
                                    if bDebugMessages == true then LOG(sFunctionRef..':iAngleFromFriendlyToDFEnemy='..iAngleFromFriendlyToDFEnemy..'; iAngleFromFriendlyToNearestEnemy='..iAngleFromFriendlyToNearestEnemy..'; Dist from friendly unit to closest df enemy='..AiBotUtilities.GetDistanceBetweenPositions(oClosestFriendlyCombat:GetPosition(), oClosestDFEnemy:GetPosition())..'; Dist from closest DF enemy to nearest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oClosestDFEnemy:GetPosition())..'; oClosestDFEnemy DF range='..oClosestDFEnemy[AiBotUnitInfo.refiDFRange]..'; oClosestFriendlyCombat='..oClosestFriendlyCombat.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestFriendlyCombat)..'; Dist from DF enemy to nearest enemy, less DF range='..AiBotUtilities.GetDistanceBetweenPositions(oClosestDFEnemy:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())) end
                                    if AiBotUtilities.GetDistanceBetweenPositions(oClosestDFEnemy:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - oClosestDFEnemy[AiBotUnitInfo.refiDFRange] + oClosestDFEnemy[AiBotUnitInfo.refiDFRange] >= 20 and AiBotUtilities.GetDistanceBetweenPositions(oClosestFriendlyCombat:GetPosition(), oClosestDFEnemy:GetPosition()) - oClosestDFEnemy[AiBotUnitInfo.refiDFRange] >= 10 then
                                        if iAngleDif >= 70 or iAngleDif <= 30 then --if angle dif <=20 then enemy DF unit is likely behind the nearest enemy unit (so we are ok to attack); if angle is >=45 then hopefully it is at too far of an angle to be able to easily assist if we advance?
                                            if bDebugMessages == true then LOG(sFunctionRef..': Closest DF seems too far out of position to help so will attack') end
                                            bAttackWithEverything = true
                                        end
                                    end
                                end
                            end
                        end

                        --Enemy in a nearby zone - include that zone threat when deciding whether to attack
                        if bAttackWithEverything and not(bSuicideIntoFatboyOrACU) then
                            if oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] and not(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) and oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau then
                                if bDebugMessages == true then LOG(sFunctionRef..': Nearest enemy is in a different zone but the same plateau, so will check threat of that zone and revert the attack with everything flag if it is too much, iEnemyCombatThreat before update='..iEnemyCombatThreat) end
                                local tNearestEnemyLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]]
                                local tNearestEnemyLZTeamData = tNearestEnemyLZData[AiBotMap.subrefLZTeamData][iTeam]
                                iEnemyCombatThreat = math.max(iEnemyCombatThreat, tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] + tNearestEnemyLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal])
                                if bDebugMessages == true then LOG(sFunctionRef..': iEnemyCombatThreat after update='..iEnemyCombatThreat..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; iFirebaseThreatAdjust='..iFirebaseThreatAdjust..'; threat of tSkirmisherDFEnemies='..AiBotUnitInfo.GetCombatThreatRating(tSkirmisherDFEnemies, true, false)..'; Mass value of skirmisher enemies='..AiBotUnitInfo.GetMassCostOfUnits(tSkirmisherDFEnemies, true)) end
                                if iEnemyCombatThreat * 1.4 >= iAvailableCombatUnitThreat and (iFirebaseThreatAdjust == 0 or iEnemyCombatThreat >= iAvailableCombatUnitThreat) and not(bConsiderAttackingACU and oNearestEnemyToFriendlyBase.UnitId and EntityCategoryContains(categories.COMMAND, oNearestEnemyToFriendlyBase.UnitId) and AiBotUnitInfo.GetUnitHealthPercent(oNearestEnemyToFriendlyBase) <= 0.75) then
                                    bAttackWithEverything = false
                                    if bDebugMessages == true then LOG(sFunctionRef..': Changing flag back to false due to enemy unit in a dif zone that has a significant threat in it') end
                                end
                            end
                            --Extra check - if take threat of skirmisher enemies, is it higher than our available combat threat? (but ignore if we are attacking ACU)
                            if bAttackWithEverything and not(bConsiderAttackingACU and oNearestEnemyToFriendlyBase.UnitId and EntityCategoryContains(categories.COMMAND, oNearestEnemyToFriendlyBase.UnitId) and AiBotUnitInfo.GetUnitHealthPercent(oNearestEnemyToFriendlyBase) <= 0.75) then
                                local iEnemyThreatBasedOnSkirmisherEnemies = AiBotUnitInfo.GetCombatThreatRating(tSkirmisherDFEnemies, true, false)
                                if iEnemyThreatBasedOnSkirmisherEnemies * 1.5 > iAvailableCombatUnitThreat then
                                    --Do a detailed check based on skirmisher enemies that are close to being in range of the closest enemy unit
                                    local iMassOfNearbySkirmisherEnemies = 0
                                    for iEnemy, oEnemy in tSkirmisherDFEnemies do
                                        if not(oEnemy.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - (oEnemy[AiBotUnitInfo.refiCombatRange] or 0) <= 30 then
                                            iMassOfNearbySkirmisherEnemies = iMassOfNearbySkirmisherEnemies + (oEnemy[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oEnemy))
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Inconsistent enemy threat values so will play it safe and not attack if mass of enemy DF units near the nearest enemy is high enough, iMassOfNearbySkirmisherEnemies='..iMassOfNearbySkirmisherEnemies..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; iEnemyThreatBasedOnSkirmisherEnemies='..iEnemyThreatBasedOnSkirmisherEnemies) end
                                    if iMassOfNearbySkirmisherEnemies * 1.3 >= iAvailableCombatUnitThreat then
                                        bAttackWithEverything = false
                                        if bDebugMessages == true then LOG(sFunctionRef..': Wont attack with everything afterall') end
                                    elseif iMassOfNearbySkirmisherEnemies * 2 >= iAvailableCombatUnitThreat then
                                        --Calculate our threat more precisely, based on the short ranged directfire units we have
                                        local toTempSRDFUnits = {}
                                        for iUnit, oUnit in tAvailableCombatUnits do
                                            if (oUnit[AiBotUnitInfo.refiDFRange] or 0) < iEnemyBestDFRange or (oUnit[AiBotUnitInfo.refiDFRange] == iEnemyBestDFRange and not(bAttackWithSameRange)) then
                                                table.insert(toTempSRDFUnits, oUnit)
                                            end
                                        end
                                        local iOurDFThreatWithWorseRange = 0
                                        if AiBotUtilities.IsTableEmpty(toTempSRDFUnits) == false then
                                            iOurDFThreatWithWorseRange = AiBotUnitInfo.GetCombatThreatRating(toTempSRDFUnits, false)
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': iOurDFThreatWithWorseRange='..iOurDFThreatWithWorseRange..'; iMassOfNearbySkirmisherEnemies='..iMassOfNearbySkirmisherEnemies) end
                                        if iMassOfNearbySkirmisherEnemies * 1.2 > iOurDFThreatWithWorseRange then
                                            bAttackWithEverything = false
                                            if bDebugMessages == true then LOG(sFunctionRef..': Wont attack with everything as our units that outrange enemy arent strong enough yet') end
                                        elseif iEnemyThreatBasedOnSkirmisherEnemies > iOurDFThreatWithWorseRange and iOurDFThreatWithWorseRange > 50 then
                                            --Check how much nearby DF threat we have - get oru closest SR unit to the nearest enemy unit, and then get units within 30 of that
                                            local oClosestSRFriendlyToEnemy
                                            local iClosestSRFriendlyDistLessRange = 10000
                                            local iCurDist
                                            for iUnit, oUnit in toTempSRDFUnits do
                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - (oUnit[AiBotUnitInfo.refiDFRange] or 0)
                                                if iCurDist < iClosestSRFriendlyDistLessRange then
                                                    iClosestSRFriendlyDistLessRange = iCurDist
                                                    oClosestSRFriendlyToEnemy = oUnit
                                                end
                                            end
                                            local toNearbySRDFUnits = {}
                                            for iUnit, oUnit in toTempSRDFUnits do
                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestSRFriendlyToEnemy:GetPosition())
                                                if iCurDist < 30 then
                                                    table.insert(toNearbySRDFUnits, oUnit)
                                                end
                                            end
                                            local iThreatOfNearbyFriendlySR = AiBotUnitInfo.GetCombatThreatRating(toNearbySRDFUnits, false)
                                            if bDebugMessages == true then LOG(sFunctionRef..': iThreatOfNearbyFriendlySR='..iThreatOfNearbyFriendlySR..'; oClosestSRFriendlyToEnemy='..(oClosestSRFriendlyToEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestSRFriendlyToEnemy) or 'nil')..'; iClosestSRFriendlyDistLessRange='..iClosestSRFriendlyDistLessRange) end
                                            if iMassOfNearbySkirmisherEnemies * 1.2 > iThreatOfNearbyFriendlySR and (iClosestSRFriendlyDistLessRange >= 5 or iMassOfNearbySkirmisherEnemies > iThreatOfNearbyFriendlySR) then
                                                bAttackWithEverything = false
                                                if bDebugMessages == true then LOG(sFunctionRef..': Wont attack with everything as our shorter ranged units are spread out too much') end
                                            end
                                        end
                                    end
                                end
                            end
                        end


                        --Enemy close to our base, with a firebase, and we have experimental level threat that has a lifetime count of 1 - do a more detailed assessment
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to be aggressive with 1st experimental if relevant, iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; iEnemyCombatThreat='..iEnemyCombatThreat..'; oNearestEnemyToFriendlyBase='..(oNearestEnemyToFriendlyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase) or 'nil')..'; This zone mod dist='..tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.25..'; Constructed exp count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]) end
                        if not(bAttackWithEverything) and iAvailableCombatUnitThreat >= 5000 and iEnemyCombatThreat <= 40000 and oNearestEnemyToFriendlyBase and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.25 and iAvailableCombatUnitThreat > iEnemyCombatThreat * 0.5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 then
                            local toFriendlySRExperimentals = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental - AiBotUnitInfo.refCategoryFatboy - AiBotUnitInfo.refCategoryMegalith, tAvailableCombatUnits)
                            if bDebugMessages == true then LOG(sFunctionRef..': is table of SR exp empty='..tostring(AiBotUtilities.IsTableEmpty(toFriendlySRExperimentals))) end
                            if AiBotUtilities.IsTableEmpty(toFriendlySRExperimentals) == false then
                                --Do we have an EXP with LC = 1 (want to be more aggressive with the first exp)?
                                local oClosestSRExpToEnemy
                                local iClosestSRExpToEnemy = 1000
                                for iExp, oExp in toFriendlySRExperimentals do
                                    if AiBotUnitInfo.GetUnitLifetimeCount(oExp) == 1 and (oExp[AiBotUnitInfo.refiDFRange] or 0) <= 60 and ((oExp[AiBotUnitInfo.refiDFRange] or 0) > 0 or oExp[AiBotUnitInfo.refiCombatRange] <= 60) then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oExp:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())
                                        if iCurDist <= iClosestSRExpToEnemy then
                                            oClosestSRExpToEnemy = oExp
                                            iClosestSRExpToEnemy = iCurDist
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': oClosestSRExpToEnemy='..oClosestSRExpToEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestSRExpToEnemy)..'; iClosestSRExpToEnemy='..iClosestSRExpToEnemy..'; oClosestSRExpToEnemy[AiBotUnitInfo.refiDFRange]='..oClosestSRExpToEnemy[AiBotUnitInfo.refiDFRange]) end
                                if oClosestSRExpToEnemy and iClosestSRExpToEnemy - (oClosestSRExpToEnemy[AiBotUnitInfo.refiDFRange] or oClosestSRExpToEnemy[AiBotUnitInfo.refiCombatRange]) <= 40 then --we are within 40 of being in range of an enemy
                                    --Get precise threat calc - assume we get into range of the closest enemy, and then consider all DF enemies around the closest enemy who are within 10 of being in range of that position - do we expect to win the fight with this unit alone?
                                    local tInRangeOfEnemyPosition
                                    if iClosestSRExpToEnemy - oClosestSRExpToEnemy[AiBotUnitInfo.refiDFRange] <= 1 then
                                        tInRangeOfEnemyPosition = oClosestSRExpToEnemy:GetPosition()
                                    else
                                        local iAngleToEnemy = AiBotUtilities.GetAngleFromAToB(oClosestSRExpToEnemy:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())
                                        tInRangeOfEnemyPosition = AiBotUtilities.MoveInDirection(oClosestSRExpToEnemy:GetPosition(), iAngleToEnemy, iClosestSRExpToEnemy - oClosestSRExpToEnemy[AiBotUnitInfo.refiDFRange], true, true, AiBotMap.bIsCampaignMap)
                                        if tInRangeOfEnemyPosition and not(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tInRangeOfEnemyPosition) == tLZData[AiBotMap.subrefLZIslandRef]) then tInRangeOfEnemyPosition= nil end
                                    end
                                    if tInRangeOfEnemyPosition then
                                        local tTargetPositionLZData, tTargetPositionLZTeamData = AiBotMap.GetLandOrWaterZoneData(tInRangeOfEnemyPosition, true, iTeam)
                                        if tTargetPositionLZTeamData then
                                            local tEnemyDFUnitsNearTarget = {}
                                            local tbEntityIDIncluded = {}
                                            if AiBotUtilities.IsTableEmpty(tTargetPositionLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                for iUnit, oUnit in tTargetPositionLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                    if not(oUnit.Dead) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 10 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tInRangeOfEnemyPosition) - oUnit[AiBotUnitInfo.refiDFRange] <= 15 then --Within 15 of being in range
                                                        table.insert(tEnemyDFUnitsNearTarget, oUnit)
                                                        tbEntityIDIncluded[oUnit.EntityId] = true
                                                    end
                                                end
                                            end
                                            if AiBotUtilities.IsTableEmpty(tTargetPositionLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                for _, iAdjLZ in tTargetPositionLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                        for iUnit, oUnit in tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                            if not(oUnit.Dead) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 10 and not(tbEntityIDIncluded[oUnit.EntityId]) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tInRangeOfEnemyPosition) - oUnit[AiBotUnitInfo.refiDFRange] <= 10 then --Within 10 of being in range
                                                                table.insert(tEnemyDFUnitsNearTarget, oUnit)
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                            local iEnemyThreatWithinRange = AiBotUnitInfo.GetCombatThreatRating(tEnemyDFUnitsNearTarget, true, false)
                                            local iOurExpThreat = AiBotUnitInfo.GetCombatThreatRating({oClosestSRExpToEnemy}, false, false)
                                            if bDebugMessages == true then LOG(sFunctionRef..': oClosestSRExpToEnemy='..oClosestSRExpToEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestSRExpToEnemy)..'; iEnemyThreatWithinRange='..iEnemyThreatWithinRange..'; iOurExpThreat='..iOurExpThreat..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; Mod dist of this zone='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Mod dist of target zone='..tTargetPositionLZTeamData[AiBotMap.refiModDistancePercent]..'; iClosestSRExpToEnemy='..iClosestSRExpToEnemy..'; oClosestSRExpToEnemy[AiBotUnitInfo.refiDFRange]='..oClosestSRExpToEnemy[AiBotUnitInfo.refiDFRange]) end
                                            if (iOurExpThreat > iEnemyThreatWithinRange or iOurExpThreat + (iAvailableCombatUnitThreat - iOurExpThreat) * 0.4 > iEnemyThreatWithinRange * 1.1
                                                    --Monkeylord further exception as we might be able to close in distance on enemy without being seen; and similarly ythotha who deathball might damage enemy; but only consider if mod dist low enough that we are desparate
                                                    or (tTargetPositionLZTeamData[AiBotMap.refiModDistancePercent] <= 0.2 and EntityCategoryContains(AiBotUnitInfo.refCategoryMonkeylord + AiBotUnitInfo.refCategoryYthotha, oClosestSRExpToEnemy.UnitId) and iOurExpThreat > iEnemyThreatWithinRange * 0.8 and (iOurExpThreat > iEnemyThreatWithinRange * (0.8 + (0.95 - 0.8) * math.max(0, (iClosestSRExpToEnemy - oClosestSRExpToEnemy[AiBotUnitInfo.refiDFRange])) / 40))))
                                                    and (iEnemyThreatWithinRange <= 2000 or AiBotUtilities.IsTableEmpty(AiBotUnitInfo.refCategoryLandExperimental - AiBotUnitInfo.refCategoryFatboy, tEnemyDFUnitsNearTarget))

                                            then
                                                if bDebugMessages == true then LOG(sFunctionRef..': will try attacking with everything afterall') end
                                                bAttackWithEverything = true
                                            end
                                        end
                                    end
                                end
                            end
                        end

                        --Include threat of friendly zones attacking the same target - if this is enough to change our decision on whether to attack, then
                        if bDebugMessages == true then LOG(sFunctionRef..': Decision before including other zones with same target='..tostring(bAttackWithEverything)..'; iLandZone='..iLandZone..'; oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam]=P'..(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or 'nil')..'Z'..(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or 'nil')) end
                        if not(bAttackWithEverything) and oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau then
                            local iLikelyTargetZone = oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                            local iAdjMobileDFThreat = GetAdjacentNearbyMobileDFThreatWithSameZoneTarget(iLikelyTargetZone)


                            if bDebugMessages == true then LOG(sFunctionRef..': iAdjMobileDFThreat='..(iAdjMobileDFThreat or 'nil')) end
                            if iAdjMobileDFThreat > 40 then
                                --AiBotConditions.HaveEnoughThreatToAttack(iPlateau, iLandZone, tLZData, tLZTeamData, iOurCombatThreat,                                     iEnemyCombatThreat, iFirebaseThreatAdjust,                                                                              bHaveSignificantCombatCloserToFirebase, iTeam, iOptionalOverrideDefaultThreatRatioWanted, bOptionalUseSlightlyLowerThreatRatio)
                                bAttackWithEverything = AiBotConditions.HaveEnoughThreatToAttack(iPlateau, iLandZone, tLZData, tLZTeamData, iOurDFAndT1ArtiCombatThreat + iAdjMobileDFThreat, iEnemyCombatThreat, math.max(iFirebaseThreatAdjust, (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0)), bHaveSignificantCombatCloserToFirebase, iTeam,    nil,                                        bAttackWithLowerThreatRatio)
                                if bDebugMessages == true then LOG(sFunctionRef..': bAttackWithEverything after including adjacent zones iwth same target='..tostring(bAttackWithEverything or false)) end
                            end
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': bAttackWithEverything after initial assessment='..tostring(bAttackWithEverything)..'; tLZTeamData[AiBotMap.refbIslandBeachhead]='..tostring(tLZTeamData[AiBotMap.refbIslandBeachhead] or false)) end
                        if not(bAttackWithEverything) and tLZTeamData[AiBotMap.refbIslandBeachhead] then
                            --May have units nearby underwater that want to include
                            local iSearchRange = math.max(40, math.min(140, 15 + table.getn(tOurDFAndT1ArtiUnits)))

                            local oClosestFriendlyToEnemy
                            local iCurDist
                            local iClosestDist = 100000
                            for iUnit, oUnit in tAvailableCombatUnits do
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                if iCurDist < iClosestDist then
                                    iClosestDist = iCurDist
                                    oClosestFriendlyToEnemy = oUnit
                                end
                            end
                            local iNearbyCombatThreat = math.max(iOurDFAndT1ArtiCombatThreat, AiBotUnitInfo.GetCombatThreatRating(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains][1]:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat, oClosestFriendlyToEnemy:GetPosition(), iSearchRange, 'Ally'), false))
                            --Are there significant units left out of the normal threat calculation e.g. due to an amphibious assault with friendly units nearby in the water? If so then consider attacking
                            if iOurDFAndT1ArtiCombatThreat < iNearbyCombatThreat * 1.25 then
                                if iNearbyCombatThreat > iEnemyCombatThreat then
                                    bAttackWithEverything = true
                                elseif iNearbyCombatThreat > 1.2 * math.max(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 0.5, tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] + tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]) and tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] then
                                    bAttackWithEverything = true
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Island beachhead Nearby combat threat='..iNearbyCombatThreat..'; iEnemyCombatThreat='..iEnemyCombatThreat..'; tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures]='..tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures]..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]..'; bAttackWithEverythign='..tostring(bAttackWithEverything)..'; tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])) end
                        end
                        --Dont have a massive army - consider staying if enemy has mexes in this zone and we have more threat than enemy threat that is just in this zone
                        if not(bAttackWithEverything) and iOurDFAndT1ArtiCombatThreat < 10000 and iOurDFAndT1ArtiCombatThreat > (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) and tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 and tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] > 10 then
                            local bCouldDoSomeDamage = false
                            local tEnemyBuildings = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure - AiBotUnitInfo.refCategoryPD - AiBotUnitInfo.refCategoryStructureAA - AiBotUnitInfo.refCategoryFactory, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                            if AiBotUtilities.IsTableEmpty(tEnemyBuildings) == false then
                                for iUnit, oUnit in tEnemyBuildings do
                                    if oUnit:GetFractionComplete() == 1 then
                                        bCouldDoSomeDamage = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will consider being more aggressive as enemy has buildings we could try and kill even if overall we might be outnumbered soon') end
                                        break
                                    end
                                end
                            end
                            if bCouldDoSomeDamage then
                                --Would our retreat path take us somewhere dangerous? in which case stay and attack
                                local tAdjacentZoneRally = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 1, false)
                                if AiBotUtilities.IsTableEmpty(tAdjacentZoneRally) then
                                    bAttackWithEverything = true
                                    if bDebugMessages == true then LOG(sFunctionRef..': Nowhere to retreat so will attack to try and do some damage') end
                                else
                                    local tAdjacentRallyData, tAdjacentRallyTeamData = AiBotMap.GetLandOrWaterZoneData(tAdjacentZoneRally, true, iTeam)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy combat in adj rally point zone='..tAdjacentRallyTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; iOurDFAndT1ArtiCombatThreat='..iOurDFAndT1ArtiCombatThreat) end
                                    if tAdjacentRallyTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 0.4 * iOurDFAndT1ArtiCombatThreat then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Is dangerous to retreat so might as well attack and try and do some damage') end
                                        bAttackWithEverything = true
                                    end
                                end
                                if bAttackWithEverything then bOnlyAttackWithUnitsInThisZone = true end --This is needed to e.g. stop fatboy from suiciding into enemy mexes despite facing a major enemy threat in an adjacent zone (happened in v118)
                            end
                        end

                        if iOurDFAndT1ArtiCombatThreat < iEnemyCombatThreat * 1.4 or not(bAttackWithEverything) or (iEnemyCombatThreat >= 5000 and iOurDFAndT1ArtiCombatThreat < 7000 + math.max(0, (iEnemyCombatThreat - 15000)) * 3.5 + math.min(10000, iEnemyCombatThreat - 5000) * 2.5) then
                            bWantReinforcements = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Want reinforcements as iOurDFAndT1ArtiCombatThreat='..iOurDFAndT1ArtiCombatThreat..'; iEnemyCombatThreat='..iEnemyCombatThreat) end
                        end

                        --Attack with everythign if ACU is in trouble and in combat
                        if bHaveACUInTroubleAndRecentlyInCombat then
                            bAttackWithEverything = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Will attack with everything as ACU is in trouble') end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': We dont outrange enemy, considering if we have much more threat than them, iEnemyCombatThreat='..iEnemyCombatThreat..'; iOurDFAndT1ArtiCombatThreat='..iOurDFAndT1ArtiCombatThreat..'; bWantReinforcements='..tostring(bWantReinforcements)..'; bAttackWithEverything='..tostring(bAttackWithEverything)..'; iClosestFriendlyUnitToAnEnemyFirebase='..iClosestFriendlyUnitToAnEnemyFirebase..'; iFirebaseThreatAdjust='..iFirebaseThreatAdjust..'; bHaveACUInTroubleAndRecentlyInCombat='..tostring(bHaveACUInTroubleAndRecentlyInCombat or false)..'; tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]='..tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]..'; bAttackWithEverything='..tostring(bAttackWithEverything)) end
                        --Early game where enemy might outrange us slightly e.g. unupgraded ACU vs t1 tanks
                        if not(bAttackWithEverything) and iEnemyBestDFRange <= 22 and (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0) == 0 and iOurDFAndT1ArtiCombatThreat > math.max(900, iEnemyCombatThreat * 1.2) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy still is relatively short range so press attack') end
                            bAttackWithEverything = true
                        end

                        --More precise check in earlier-mid stages of game to avoid retreating from most of map due e.g. to enemy ACU that is nearby, but not near enough to stop us attacking the nearest enemy
                        if not(bAttackWithEverything) and (AiBotMap.iMapSize <= 512 or (GetGameTimeSeconds() <= 1200 and not(AiBotUtilities.bCPUPerformanceMode))) and (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) == 0 and iOurDFAndT1ArtiCombatThreat <= 5000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 and AiBotUtilities.IsTableEmpty(tSkirmisherDFEnemies) == false and oNearestEnemyToFriendlyBase and (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oNearestEnemyToFriendlyBase)) < 0.5 * iOurDFAndT1ArtiCombatThreat then
                            --Get threat within 20 of being in range of the closest enemy unit
                            local toEnemiesNearNearestEnemy = {}
                            local iDistThreshold = 16 + math.max(0, math.min(14, iEnemyBestDFRange - 20))
                            local iCurCombatUnits = table.getn(tAvailableCombatUnits)
                            if iCurCombatUnits >= 10 then iDistThreshold = iDistThreshold + iCurCombatUnits / 10 end

                            for iUnit, oUnit in tSkirmisherDFEnemies do
                                if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange] <= iDistThreshold then
                                    table.insert(toEnemiesNearNearestEnemy, oUnit)
                                end
                            end
                            local iThreatOfEnemiesNearestClosestEnemy = AiBotUnitInfo.GetCombatThreatRating(toEnemiesNearNearestEnemy, true)
                            if bDebugMessages == true then LOG(sFunctionRef..': iThreatOfEnemiesNearestClosestEnemy='..iThreatOfEnemiesNearestClosestEnemy..'; iOurDFAndT1ArtiCombatThreat='..iOurDFAndT1ArtiCombatThreat..'; iDistThreshold='..iDistThreshold) end
                            if iThreatOfEnemiesNearestClosestEnemy < 0.5 * iOurDFAndT1ArtiCombatThreat then
                                --Get our closest unit to the enemy, and get all friendly units within a similar distance to the nearest enemy
                                local oClosestFriendlyDFToEnemy
                                local iClosestToEnemyDist = 10000
                                local iCurDist
                                for iUnit, oUnit in tAvailableCombatUnits do
                                    if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange]
                                        if iCurDist < iClosestToEnemyDist then
                                            iClosestToEnemyDist = iCurDist
                                            oClosestFriendlyDFToEnemy = oUnit
                                        end
                                    end
                                end
                                if oClosestFriendlyDFToEnemy then
                                    if iDistThreshold < 40 then iDistThreshold = math.min(40, iDistThreshold + 10) end --We arent including range for friendly units so icnrease the distance
                                    local toFriendlyUnitsNearOurClosestUnit = {}
                                    for iUnit, oUnit in tAvailableCombatUnits do
                                        if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFriendlyDFToEnemy:GetPosition())
                                            if iCurDist < iDistThreshold then
                                                table.insert(toFriendlyUnitsNearOurClosestUnit, oUnit)
                                            end
                                        end
                                    end
                                    local iFriendlyDFThreatNearFriendlyUnit = AiBotUnitInfo.GetCombatThreatRating(toFriendlyUnitsNearOurClosestUnit, false)
                                    if bDebugMessages == true then LOG(sFunctionRef..': iFriendlyDFThreatNearFriendlyUnit='..iFriendlyDFThreatNearFriendlyUnit..'; iThreatOfEnemiesNearestClosestEnemy='..iThreatOfEnemiesNearestClosestEnemy) end
                                    if iFriendlyDFThreatNearFriendlyUnit * 0.5 > iThreatOfEnemiesNearestClosestEnemy then
                                        bAttackWithEverything = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': If we attack the nearest enemy units we should be able to overwhelm them despite enemy having stronger overall force nearby') end
                                    end
                                end
                            end
                        end
                    else
                        if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                            bWantReinforcements = true
                            if bDebugMessages == true then LOG(sFunctionRef..': We have no friendly units in this LZ but enemy has units here or adjacent LZ so want reinforcements. iFriendlyBestMobileIndirectRange='..iFriendlyBestMobileIndirectRange..'; Is there a valid enemy structure to midpoint='..tostring(AiBotUnitInfo.IsUnitValid(oNearestEnemyStructureToMidpoint))) end
                        end
                        if iFriendlyBestMobileIndirectRange == 0 or not(oNearestEnemyStructureToMidpoint) then
                            bAttackWithEverything = false
                        end
                    end
                    local bSuicideUnitsNearAMex = false
                    local tNearbyMexes
                    if not(bAttackWithEverything) and oNearestEnemyToFriendlyBase then
                        if tLZTeamData[AiBotMap.subrefLZSValue] > 10 and (tLZTeamData[AiBotMap.subrefLZbCoreBase] or (tLZTeamData[AiBotMap.subrefLZCoreExpansion] and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or iOurDFAndT1ArtiCombatThreat > iEnemyCombatThreat * 0.9 or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][1] > math.max(1, tLZData[AiBotMap.subrefLZOrWZMexCount] or 0))))) then
                            --Is enemy almost in range of the midpoint for this zone such that we want to attack even though we will probably lose?
                            if AiBotUtilities.GetDistanceBetweenPositions(       tLZData[AiBotMap.subrefMidpoint], oNearestEnemyToFriendlyBase:GetPosition()) <= 15 + math.max((oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiIndirectRange] or 0), (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0)) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Nearest enemy unit is almost in range of our midpoint and this is a high value location to defend') end
                                bAttackWithEverything = true
                                --CloseToEnemyUnit(tStartPosition,                  tUnitsToCheck,                              iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure)
                            elseif AiBotConditions.CloseToEnemyUnit(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftoNearestDFEnemies],    10,             iTeam, true                  , nil,                  nil,                                nil,                                       nil) then
                                bAttackWithEverything = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy DF units are almost in range of our midpoint and this is a high value location to defend') end
                            end
                        end
                        --Suicide into mex logic
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to suicide mex, iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; EnemyMobileDFTotal='..(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)..'; Ally mobile DF total='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]..'; Ally mobile IF total='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]..'; Enemy best structure DF range='..(tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0)..'; Mex count='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; Enemy structure mass='..(tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0)..'; Is table of enemy mexes empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tLZTeamData[AiBotMap.subrefTEnemyUnits])))) end
                        if not(bAttackWithEverything) then
                            if tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 and iAvailableCombatUnitThreat >= math.min(100, (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)) and (tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                tNearbyMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                                if AiBotUtilities.IsTableEmpty(tNearbyMexes) == false then
                                    if (iAvailableCombatUnitThreat >= iEnemyCombatThreat or EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oNearestEnemyToFriendlyBase.UnitId)) and (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] + tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] > (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) and (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0) == 0 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will try attacking with everything as we may be able to kill some mexes as weh ave more threat than enemy in this zone specifically') end
                                        bAttackWithEverything = true
                                    elseif (tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) <= 10000 then --dont want to consider suiciding where we have large armies or experimentals
                                        --Do we have units close enough to mexes that they could probably try and kill it even if enemy has a stronger force overall?
                                        bSuicideUnitsNearAMex = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': when retreating we will consider still attacking with units that are near a mex') end
                                    end
                                end
                            end
                        end
                        --Support attacking experimental
                        if not(bAttackWithEverything) then
                            if HaveAttackingExperimentalToSupport(tLZTeamData) then
                                bAttackWithEverything = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to support a friendly attacking experimental') end
                            end
                        end
                    end

                    --Adjustment of nearest enemy unit is in water - dont attack with everything
                    if bAttackWithEverything and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false and EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oNearestEnemyToFriendlyBase.UnitId) then
                        local iUnitSegmentX, iUnitSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oNearestEnemyToFriendlyBase:GetPosition())
                        if AiBotMap.tWaterZoneBySegment[iUnitSegmentX][iUnitSegmentZ] then
                            --Nearest enemy is in a water zone, will reassess if we want to attack with everything - include enemy threat in that zone and adjacent water zones, but also factor in our threat

                            local tOurAvailableHoverAndAntiNavyUnits = EntityCategoryFilterDown(categories.HOVER + AiBotUnitInfo.refCategoryAntiNavy, tAvailableCombatUnits)
                            local iOurAvailableHoverAndAntiNavyCombatThreat = 0
                            if AiBotUtilities.IsTableEmpty(tOurAvailableHoverAndAntiNavyUnits) == false then
                                iOurAvailableHoverAndAntiNavyCombatThreat = AiBotUnitInfo.GetCombatThreatRating(tOurAvailableHoverAndAntiNavyUnits, false, false, false, false, true, false, false)
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Nearest enemy is in water zone, iOurAvailableHoverAndAntiNavyCombatThreat='..iOurAvailableHoverAndAntiNavyCombatThreat) end
                            if iOurAvailableHoverAndAntiNavyCombatThreat <= 10 then
                                bAttackWithEverything = false
                            else
                                local iWaterZone = AiBotMap.tWaterZoneBySegment[iUnitSegmentX][iUnitSegmentZ]
                                local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
                                local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                                local iAdjacentAlliedSubmersibleThreat = 0
                                local iAdjacentEnemyAntiNavyThreat = 0
                                local iAdjacentAlliedCombatThreat = iOurAvailableHoverAndAntiNavyCombatThreat
                                local iAdjacentEnemyCombatThreat = 0

                                if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                                    for _, iAdjWZ in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do --Include enemy threats in adjacent water zones, including 100% of the threat (vs WZ which normally includes only 20%)
                                        local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                                        iAdjacentAlliedSubmersibleThreat, iAdjacentEnemyAntiNavyThreat, iAdjacentAlliedCombatThreat, iAdjacentEnemyCombatThreat = AiBotNavy.IncludeThreatOfAdjacentZone(iAdjacentAlliedSubmersibleThreat, iAdjacentEnemyAntiNavyThreat, iAdjacentAlliedCombatThreat, iAdjacentEnemyCombatThreat, tWZData, tAdjWZTeamData, iAdjWZ, true, true, true, true, 1)
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iAdjacentAlliedSubmersibleThreat='..iAdjacentAlliedSubmersibleThreat..'; iAdjacentEnemyAntiNavyThreat='..iAdjacentEnemyAntiNavyThreat..'; iAdjacentAlliedCombatThreat='..iAdjacentAlliedCombatThreat..'; iAdjacentEnemyCombatThreat='..iAdjacentEnemyCombatThreat..'; Do we want to attack using WZ logic='..tostring(AiBotConditions.WantToAttackWithNavyEvenIfOutranged(tWZData, tWZTeamData, iTeam, tWZTeamData[AiBotMap.subrefWZThreatAlliedSubmersible], iAdjacentAlliedSubmersibleThreat, iAdjacentEnemyAntiNavyThreat, iAdjacentAlliedCombatThreat, iAdjacentEnemyCombatThreat, true ))) end
                                if not(AiBotConditions.WantToAttackWithNavyEvenIfOutranged(tWZData, tWZTeamData, iTeam, tWZTeamData[AiBotMap.subrefWZThreatAlliedSubmersible], iAdjacentAlliedSubmersibleThreat, iAdjacentEnemyAntiNavyThreat, iAdjacentAlliedCombatThreat, iAdjacentEnemyCombatThreat, true )) then
                                    bAttackWithEverything = false
                                end
                            end
                        end
                    end

                    if bDebugMessages == true then LOG(sFunctionRef..': Dont outrange enemy, bAttackWithEverything='..tostring(bAttackWithEverything)..'; Is table of ACUs in the LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]))) end
                    local bUpdateNearestUnit = false
                    local bCheckIfNearestUnitVisible = bUpdateNearestUnit
                    if not(bUpdateNearestUnit) and AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) >= 10 then
                        bCheckIfNearestUnitVisible = true
                    end

                    if bAttackWithEverything then
                        if not(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) and oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau then
                            RecordDFLandZoneTarget(tLZTeamData, iPlateau, iLandZone, iTeam, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2], AiBotMap.subrefiLZOrWZTAttackingUnit)
                        elseif oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] then AiBotNavy.RecordWaterZoneTarget(tLZTeamData, iLandZone, iTeam, false, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam], AiBotMap.subrefiLZOrWZTAttackingUnit, true)
                        end
                        local bMoveToStopPDConstruction = false
                        if bDebugMessages == true then LOG(sFunctionRef..': Seeing if we have enough threat to try and stop PD being built, tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; iAvailableCombatUnitThreat='..(iAvailableCombatUnitThreat or 'nil')) end
                        if AiBotUtilities.IsTableEmpty(tEnemyEngineers) == false and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 100 and (iAvailableCombatUnitThreat or 0) >= math.min(40, tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 3) and GetEnemyCombatThreatInAdjacentZones() <= 500  then
                            local tEnemyPD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy PD empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyPD))) end
                            if AiBotUtilities.IsTableEmpty(tEnemyPD) == false then
                                bMoveToStopPDConstruction = true
                                for iPD, oPD in tEnemyPD do
                                    if oPD:GetFractionComplete() == 1 then
                                        bMoveToStopPDConstruction = false
                                        break
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': bMoveToStopPDConstruction before doublechecking threats='..tostring(bMoveToStopPDConstruction)) end
                                if bMoveToStopPDConstruction then
                                    --Check we have significantly more threat if excluding under-construction PD
                                    bMoveToStopPDConstruction = false
                                    local iPDThreat = AiBotUnitInfo.GetCombatThreatRating(tEnemyPD, true)
                                    if bDebugMessages == true then LOG(sFunctionRef..': iPDThreat='..iPDThreat) end
                                    if (iAvailableCombatUnitThreat or 0) > 2 * tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] - iPDThreat and (iAvailableCombatUnitThreat or 0) >= GetEnemyCombatThreatInAdjacentZones() then
                                        bMoveToStopPDConstruction = true
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Will attack with everything, oNearestEnemyToFriendlyBase='..oNearestEnemyToFriendlyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oNearestEnemyToFriendlyBase))..'; oNearestEnemyToFriendlyBase position='..repru(oNearestEnemyToFriendlyBase:GetPosition())..'; Last known position='..repru(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; bMoveToStopPDConstruction='..tostring(bMoveToStopPDConstruction or false)) end
                        local bMoveTowardsEngineers = false
                        if AiBotUtilities.IsTableEmpty(tEnemyEngineers) == false and iAvailableCombatUnitThreat <= 400 and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 100 and (iAvailableCombatUnitThreat or 0) >= math.min(40, tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 3) and GetEnemyCombatThreatInAdjacentZones() <= 500 then
                            bMoveTowardsEngineers = true
                        end
                        local bFiringAtNegligibleThreatInLRExperimentalRange = false
                        --local bCheckIfNearLocationToAvoid = not(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftiLocationsToAvoid]))

                        bGivenCombatUnitsOrders = true
                        local bMoveWithDFUnitsForAiBotEasy = nil
                        for iUnit, oUnit in tAvailableCombatUnits do
                            --If we are close to the last known position such that we will be able to see there is no longer a unit there, then update this unit's position for next cycle
                            if bCheckIfNearestUnitVisible and not(bUpdateNearestUnit) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 18 then bUpdateNearestUnit = true end
                            if bDebugMessages == true then LOG(sFunctionRef..': Attacking with everything, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Special micro active='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; bOnlyAttackWithUnitsInThisZone='..tostring(bOnlyAttackWithUnitsInThisZone)) end
                            if bOnlyAttackWithUnitsInThisZone and oUnit[refiCurrentAssignmentPlateauAndLZ][2] == iLandZone and oUnit[refiCurrentAssignmentPlateauAndLZ][1] == iPlateau then
                                if bDebugMessages == true then LOG(sFunctionRef..': Wont attack with this unit as were doing a suicide attack with units from the cur zone only') end
                                oUnit[refiCurrentAssignmentValue] = 0
                            elseif ProceedWithUnitOrder(oUnit) then
                                if oUnit[AiBotUnitInfo.refbEasyBrain] then
                                    if bMoveWithDFUnitsForAiBotEasy == nil then
                                        --Consider if we want to move to attack
                                        bMoveWithDFUnitsForAiBotEasy = false
                                        --Does enemy have signific indirect threat?
                                        local iEnemyIndirectInThisAndAdjacentZones = tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal]
                                        local iEnemyDFInThisAndAdjacentZones = tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] + tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures]
                                        if AiBotUtilities.IsTableEmpty(tNearbyAdjacentEnemies) == false then
                                            local tEnemyIndirect = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryIndirect, tNearbyAdjacentEnemies)
                                            if AiBotUtilities.IsTableEmpty(tEnemyIndirect) == false then
                                                iEnemyIndirectInThisAndAdjacentZones = iEnemyIndirectInThisAndAdjacentZones + AiBotUnitInfo.GetCombatThreatRating(tEnemyIndirect, true, false, true, false, false, false, false)
                                            end
                                            local tEnemyNonSkirmisherDirect = EntityCategoryFilterDown(categories.DIRECTFIRE - AiBotUnitInfo.refCategorySkirmisher, tNearbyAdjacentEnemies)
                                            iEnemyDFInThisAndAdjacentZones = iEnemyDFInThisAndAdjacentZones + AiBotUnitInfo.GetCombatThreatRating(tEnemyNonSkirmisherDirect, true, false, false)
                                        end
                                        if iOurDFAndT1ArtiCombatThreat > iEnemyDFInThisAndAdjacentZones and iEnemyIndirectInThisAndAdjacentZones > 0 and (iOurDFAndT1ArtiCombatThreat > 2.5 * iEnemyDFInThisAndAdjacentZones or (iEnemyIndirectInThisAndAdjacentZones > math.min(iEnemyDFInThisAndAdjacentZones * 0.2, iOurDFAndT1ArtiCombatThreat * 0.15))) then
                                            bMoveWithDFUnitsForAiBotEasy = true
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Finished considering whether to move instead of attackmove for normal AiBotEasy units in LZ='..iLandZone..', bMoveWithDFUnitsForAiBotEasy='..tostring(bMoveWithDFUnitsForAiBotEasy)..'; iOurDFAndT1ArtiCombatThreat='..iOurDFAndT1ArtiCombatThreat..'; iEnemyDFInThisAndAdjacentZones='..iEnemyDFInThisAndAdjacentZones) end
                                    end
                                    if (bMoveWithDFUnitsForAiBotEasy or (bMoveBlockedNotAttackMove and (oUnit[AiBotUnitInfo.refbLastShotBlocked] or AiBotUnitInfo.IsUnitUnderwater(oUnit)))) and not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId)) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride]) then
                                        AiBotOrders.IssueTrackedMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], 6, false, 'BAesWE'..iLandZone)
                                    else
                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], 6, false, 'AWes'..iLandZone)
                                    end
                                else
                                    --if bCheckIfNearLocationToAvoid and EntityCategoryContains(categories.TECH1 + categories.TECH2 - categories.COMMAND, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) and AiBotConditions.HaveSentOrderToRunAwayFromLocationToAvoid(oUnit, tLZTeamData[AiBotMap.reftiLocationsToAvoid], 4) then
                                    --if bDebugMessages == true then LOG(sFunctionRef..': Unit will run away from location to avoid') end
                                    if oUnit[AiBotUnitInfo.refiIndirectRange] > 0 then
                                        if oUnit[AiBotAir.refiTimeLastDropped] and oUnit[AiBotUnitInfo.refiIndirectRange] > 0 and GetGameTimeSeconds() - oUnit[AiBotAir.refiTimeLastDropped] <= 60 and oNearestEnemyStructureToMidpoint then
                                            SuicideUnitIntoEnemyStructure(oUnit)
                                        elseif oUnit[AiBotUnitInfo.refiIndirectRange] >= iEnemyBestDFRange then
                                            if bConsiderSpecialMMLLogic and EntityCategoryContains(AiBotUnitInfo.refCategoryMML, oUnit.UnitId) then table.insert(tMMLForSynchronisation, oUnit)
                                            else
                                                iIndirectDistanceInsideRangeThreshold = iIndirectRunFigureNormal
                                                if oUnit[AiBotUnitInfo.refbWeaponUnpacks] then iIndirectDistanceInsideRangeThreshold = iIndirectDistanceInsideRangeThreshold + iIndirectRunFigureDeployedAdjust end
                                                if bOnlyRetreatIndirectIfEnemyDFAlmostInRange then iIndirectDistanceInsideRangeThreshold = math.max(iIndirectDistanceInsideRangeThreshold + 10, ((oUnit[AiBotUnitInfo.refiIndirectRange] or 0) - iEnemyBestDFRange)) end

                                                local iDistThreshold
                                                if bOnlyRetreatIndirectIfEnemyDFAlmostInRange then
                                                    iDistThreshold = math.max(oUnit[AiBotUnitInfo.refiIndirectRange] - iIndirectDistanceInsideRangeThreshold, math.min(iEnemyBestDFRange + 5, oUnit[AiBotUnitInfo.refiIndirectRange] - 2))
                                                    if AiBotUnitInfo.IsUnitValid(oUnit[refoAssignedMobileShield]) then iDistThreshold = iDistThreshold - 5 end
                                                else
                                                    iDistThreshold = math.max(oUnit[AiBotUnitInfo.refiIndirectRange] - iIndirectDistanceInsideRangeThreshold, math.min(iEnemyBestDFRange + 10, oUnit[AiBotUnitInfo.refiIndirectRange] - 2))
                                                    if AiBotUnitInfo.IsUnitValid(oUnit[refoAssignedMobileShield]) then iDistThreshold = iDistThreshold - 5 end
                                                end

                                                if not(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], iDistThreshold, iTeam, false)) then
                                                    if not(IgnoreOrderDueToStuckUnit(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])) then
                                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], math.max(15, iIndirectDistanceInsideRangeThreshold), false, 'I2KAMve'..iLandZone)
                                                    end
                                                else
                                                    --Retreat temporarily from enemy units
                                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                                                        oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                        AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'AI2KRetr'..iLandZone)
                                                    else
                                                        oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                        AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'I2KRetr'..iLandZone)
                                                    end
                                                end
                                            end
                                        else
                                            --Treat the same as outranged DF units
                                            if not(IgnoreOrderDueToStuckUnit(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])) then
                                                AiBotOrders.IssueTrackedAggressiveMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], 6, false, 'I2AWE'..iLandZone)
                                            end
                                        end
                                    elseif EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId) or oUnit[AiBotUnitInfo.refbScoutCombatOverride] then
                                        --Still retreat if are in range of enemy, even if we dont outraneg them, as may e.g. be other units that we do outrange
                                        if bEnemyHasNoDFUnits or not(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], oUnit[AiBotUnitInfo.refiDFRange] - math.max(2, oUnit[AiBotUnitInfo.refiDFRange] * 0.06), iTeam, false)) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Not in range of enemy yet, and we outrange enemy; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; DF range='..oUnit[AiBotUnitInfo.refiDFRange]..'; oNearestEnemyToFriendlyBase='..oNearestEnemyToFriendlyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase)..'; oNearestEnemyToFriendlyBase DF range='..(oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 'nil')..'; Distance to the nearest enemy to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oUnit:GetPosition())..'; Enemy unit actual position='..repru(oNearestEnemyToFriendlyBase:GetPosition())..'; Enemy last recorded position='..repru(oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; Our unit position='..repru(oUnit:GetPosition())..'; LZ midpoint position='..repru(tLZData[AiBotMap.subrefMidpoint])) end
                                            --Not in range yet, so attack move to the nearest enemy
                                            AiBotOrders.IssueTrackedAggressiveMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, false, 'SKAMve'..iLandZone)
                                        else
                                            --Enemy has DF units and they are already in our range so retreat
                                            if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                                                oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'ASKRetr'..iLandZone)
                                            else
                                                oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                                AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'SKRetr'..iLandZone)
                                            end

                                        end
                                    else
                                        if bSuicideIntoFatboyOrACU and oClosestFatboyOrACUInIslandToSuicideInto then
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFatboyOrACUInIslandToSuicideInto:GetPosition())
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will move to nearest fatboy='..oClosestFatboyOrACUInIslandToSuicideInto.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestFatboyOrACUInIslandToSuicideInto)..' with unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist between them='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFatboyOrACUInIslandToSuicideInto:GetPosition())..'; SpecialMicroActive='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; refiGameTimeToResetMicroActive='..(oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 'nil')..'; Cur time='..GetGameTimeSeconds()) end
                                            if (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 2000 and iCurDist <= 5 then
                                                AiBotOrders.IssueTrackedAttack(oUnit, oClosestFatboyOrACUInIslandToSuicideInto, false, 'SuicFBA'..iLandZone, false)
                                                --AiBotOrders.IssueTrackedAggressiveMove(oUnit, oClosestFatboyOrACUInIslandToSuicideInto:GetPosition(), 6, false, 'SuicFBA'..iLandZone)
                                            elseif not(oUnit[AiBotUnitInfo.refbLastShotBlocked]) and (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 200 and iCurDist <= 15 and (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 20 and (iCurDist <= 8 or oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Are close to enemy fatboy so will do manual attack') end
                                                AiBotOrders.IssueTrackedAttack(oUnit, oClosestFatboyOrACUInIslandToSuicideInto, false, 'SuicFBAt'..iLandZone, false)
                                            else
                                                --Special micro to close in the gap
                                                if oUnit[AiBotUnitInfo.refiUnitMassCost] >= 10000 and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oClosestFatboyOrACUInIslandToSuicideInto.UnitId) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestFatboyOrACUInIslandToSuicideInto:GetPosition()) > math.max(50, oUnit[AiBotUnitInfo.refiDFRange] or 5) and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oClosestFatboyOrACUInIslandToSuicideInto:GetPosition()) == tLZData[AiBotMap.subrefLZIslandRef] then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will run special micro to suicide experimental into fatboy unless micro is already active') end
                                                    if not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
                                                        ForkThread(AiBotMicro.SuicideExperimentalIntoFatboy, oUnit, oClosestFatboyOrACUInIslandToSuicideInto, iTeam, iPlateau)
                                                    end
                                                else
                                                    AiBotOrders.IssueTrackedMove(oUnit, oClosestFatboyOrACUInIslandToSuicideInto:GetPosition(), 6, false, 'SuicFBM'..iLandZone)
                                                end
                                            end
                                        elseif bMoveBlockedNotAttackMove and (oUnit[AiBotUnitInfo.refbLastShotBlocked] or AiBotUnitInfo.IsUnitUnderwater(oUnit)) and not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride])) then
                                            AiBotOrders.IssueTrackedMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], 6, false, 'BAWE'..iLandZone)
                                        else
                                            if bConsiderAttackingACU and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental - AiBotUnitInfo.refCategorySkirmisher - AiBotUnitInfo.refCategoryFatboy - AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride]) and AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), toEnemyACUsNearZone, 6 + oUnit[AiBotUnitInfo.refiDFRange], iTeam, false, nil, nil, nil, nil, nil) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will attack ACU with experimental') end
                                                GetUnitToAttackNearestACUOrOverrideUnit(oUnit)

                                                --Fatboy and megalith - want to be more cautious than normal units but less so than skirmishers
                                            elseif (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 64 and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy + AiBotUnitInfo.refCategoryMegalith, oUnit.UnitId) then
                                                --Attackmove unless enemy threat is minimal in this zone and dont have notable neemies in range using getunitsaroundpoint
                                                bFiringAtNegligibleThreatInLRExperimentalRange = false
                                                --Note - iVisibleLandCombatMassInFatboyRange uses getunitsaroundpoint so wont factor in memory; therefore want to use more accurate method to avoid fatboy charging towards a monkeylord that recently fired at us
                                                if (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 60 and EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) and (iVisibleLandCombatMassInFatboyRange <= 3000 or not(EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId))) then
                                                    --Only consider if we have fired in the last 10s (otherwise it doesnt matter)
                                                    local iMassThresholdForNegligibleThreat = 1600
                                                    if oUnit[AiBotUnitInfo.refiLastWeaponEvent] and GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiLastWeaponEvent] <= 10 then
                                                        --Get accurate measure of enemy threat within our range
                                                        local iFriendlyExpFactor = 1 --If we have lots of fatboys nearby want to be much more aggressive
                                                        if not(tFriendlyNearbyExperimentals) then tFriendlyNearbyExperimentals = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental, tAvailableCombatUnits) end
                                                        if AiBotUtilities.IsTableEmpty(tFriendlyNearbyExperimentals) == false then
                                                            for iExp, oExp in tFriendlyNearbyExperimentals do
                                                                if not(oExp == oUnit) and AiBotUnitInfo.GetUnitHealthAndShieldPercent(oUnit) >= 0.75 then
                                                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oExp:GetPosition(), oUnit:GetPosition())
                                                                    if iCurDist <= 60 and (iCurDist <= 30 or oUnit[AiBotUnitInfo.refiDFRange] >= 90 or (iCurDist <= 45 and oUnit[AiBotUnitInfo.refiDFRange] >= 60)) then
                                                                        iFriendlyExpFactor = iFriendlyExpFactor + 1
