                                                                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] do
                                                                    if iRange < 60 then
                                                                        iShorterRangeThreat = iShorterRangeThreat+ iThreat
                                                                    else
                                                                        break
                                                                    end
                                                                end
                                                            end
                                                        end

                                                        iMassThresholdForNegligibleThreat = iMassThresholdForNegligibleThreat * iFriendlyExpFactor + math.min(5000, iShorterRangeThreat * 0.4)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Scen 2 Assing if enemy has negligible threat, iFriendlyExpFactor='..iFriendlyExpFactor..'; iMassThresholdForNegligibleThreat='..iMassThresholdForNegligibleThreat..'; iShorterRangeThreat='..(iShorterRangeThreat or 'nil')) end
                                                        --_________________________________________________________________HaveSignificantEnemyThreatWithinRange(tLZData, tLZTeamData, iPlateau, iTeam, iSearchDistance,                     tStartPoint,            iEnemyMassTotalThreshold,       iOptionalSearchCategory,                                                                                                                                                                                                                                tOptionalAdditionalUnits, bOnlyIncludeDFUnits, bIncludeEnemyCombatRange, iOptionalSpeedThreshold,                           iOptionalMinEnemyMassRequiredUnlessInRange)
                                                        bFiringAtNegligibleThreatInLRExperimentalRange = not(AiBotConditions.HaveSignificantEnemyThreatWithinRange(tLZData, tLZTeamData, iPlateau, iTeam, oUnit[AiBotUnitInfo.refiDFRange] -0.5, oUnit:GetPosition(), iMassThresholdForNegligibleThreat, AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryT2PlusPD + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryNavalSurface - categories.TECH1 + categories.COMMAND, tUnitsNearFatboyInFurtherAwayZones, nil,               nil,                    oUnit:GetBlueprint().Physics.MaxSpeed, math.min(150, 0.05 * (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)))))
                                                    end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Scen2 bFiringAtNegligibleThreatInLRExperimentalRange='..tostring(bFiringAtNegligibleThreatInLRExperimentalRange or false)..'; Time since we last fired weapon='..(GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0))..'; Have significant enemy threat within range='..tostring(AiBotConditions.HaveSignificantEnemyThreatWithinRange(tLZData, tLZTeamData, iPlateau, iTeam, oUnit[AiBotUnitInfo.refiDFRange] - 0.5, oUnit:GetPosition(), iMassThresholdForNegligibleThreat, AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryT2PlusPD + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryNavalSurface - categories.TECH1 + categories.COMMAND, tUnitsNearFatboyInFurtherAwayZones, nil,               nil,                    oUnit:GetBlueprint().Physics.MaxSpeed, math.min(150, 0.05 * (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)))))) end
                                                end

                                                if bFiringAtNegligibleThreatInLRExperimentalRange or (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 1500 and GetEnemyCombatThreatInAdjacentZones() <= 6000 and AiBotUtilities.IsTableEmpty(oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryNavalSurface - categories.TECH1 - categories.TECH2 * categories.MOBILE * categories.LAND + categories.COMMAND, oUnit:GetPosition(), (oUnit[AiBotUnitInfo.refiDFRange] or 0), 'Enemy'))) then
                                                    if not(IgnoreOrderDueToStuckUnit(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])) then
                                                        if (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 2000 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 7 then
                                                            AiBotOrders.IssueTrackedAggressiveMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, false, 'FBMAWE'..iLandZone, false)
                                                        else
                                                            AiBotOrders.IssueTrackedMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], (oUnit[AiBotUnitInfo.refiDFRange] or oUnit[AiBotUnitInfo.refiIndirectRange]) * 0.5, false, 'FBMWE'..iLandZone, false)
                                                        end
                                                    end
                                                else
