                                                end
                                                if bUseNormalLogic then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to move or attack move to target (or in some cases do manuyal attack), iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; GetEnemyCombatThreatInAdjacentZones='..GetEnemyCombatThreatInAdjacentZones()..'; Enemy indirect threat='..(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 'nil')..'; oNearestEnemyToFriendlyBase='..(oNearestEnemyToFriendlyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase))..'; tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]='..(tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 'nil')..'; Unit DF threat='..(oUnit[AiBotUnitInfo.refiDFRange] or 0)..'; Can unit kite='..tostring(oUnit[AiBotUnitInfo.refbCanKite])..'; oNearestEnemyToFriendlyBase='..(oNearestEnemyToFriendlyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase) or 'nil')..'; Dist from this unit to last known position for the enemy='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), (oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam] or {0,0,0}))..'; Can we see this unit='..tostring(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), (oNearestEnemyToFriendlyBase or oUnit), false))) end
                                                    if  ((bMoveToStopPDConstruction and not(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tEnemyEngineers, math.min(15, oUnit[AiBotUnitInfo.refiDFRange] - 4.5), iTeam, false, nil, nil))) or ((iAvailableCombatUnitThreat > 5000 or EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental - AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId)) and not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId)) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride]))) and
                                                            ((iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 5) or
                                                                    --If lots of T1 arti want to keep moving with experimentals/other units or theyll get slaughtered; similarly if lots of low order spam and nothing significant in range then keep moving; also keep moving if we have more threat than all enemy nearby units
                                                                    (iAvailableCombatUnitThreat > math.max(800, GetEnemyCombatThreatInAdjacentZones() * 0.8) and tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > 500 and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0) or
                                                                    (iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() and EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) and (iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 1.4 or tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > 0 or EntityCategoryContains(AiBotUnitInfo.refCategoryIndirect + AiBotUnitInfo.refCategorySkirmisher, oNearestEnemyToFriendlyBase.UnitId) or AiBotUtilities.IsTableEmpty(oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryExperimentalLevel + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryStructure * categories.TECH3 - AiBotUnitInfo.refCategoryFatboy - AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryPD, oUnit:GetPosition(), (oUnit[AiBotUnitInfo.refiDFRange] or 20), 'Enemy')))) or
                                                                    --Below to try and e.g. stop megalith attack-moving when enemy has nearby ravagers
                                                                    (not(oUnit[AiBotUnitInfo.refbCanKite]) and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental - AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId)) and tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > 500) then

                                                        --If have experimental unit and closest enemy unit to midpoint isn't a priority then consider alternative targets
                                                        local oTargetToManuallyAttack, bMoveNotManualAttack = GetManualAttackTargetIfWantManualAttack(oUnit, oNearestEnemyToFriendlyBase)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will move instead of attack move subject to manual attack overrides, Do we have a target to manually attack? oTargetToManuallyAttack='..(oTargetToManuallyAttack.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTargetToManuallyAttack) or 'nil')..'; oNearestEnemyToFriendlyBase='..(oNearestEnemyToFriendlyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase) or 'nil')) end
                                                        if oTargetToManuallyAttack and not(oTargetToManuallyAttack == oNearestEnemyToFriendlyBase) then
                                                            if bMoveNotManualAttack then AiBotOrders.IssueTrackedMove(oUnit, oTargetToManuallyAttack:GetPosition(), 2, false, 'Sc3ManM', false)
                                                            else
