                                                    elseif bConsiderAttackingACU and oUnit[AiBotUnitInfo.refiDFRange] and oUnit[AiBotUnitInfo.refiDFRange] <= (oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiDFRange] or 0) and oNearestEnemyToFriendlyBase.UnitId and oUnit[AiBotUnitInfo.refiDFRange] - AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) < 6 then

