                    else
                        --SCENARIO 3 - Enemy outranges us and we dont ahve enough threat / high enough priority location to defend so want to retreat; exception to this if enemy has an experimental unit and it is in the same LZ as us, in which case want to attack with any units that are within 10 of being in range of it
                        --Also exceptio nif we have an experimental unit that cant kite, in which case it will attack-move to the rally point
                        local tNearbyEnemyExperimentals
                        local bConsiderAttackingExperimental = false
                        local iThresholdDistUntilInRangeToAttackExp = 10 --If dist to enemy exp less our range is less than this value, then will attack instead of retreating
                        local oClosestEnemyExpToBase
                        local oClosestEnemyExpToMidpoint
                        if oNearestEnemyToFriendlyBase then
                            tNearbyEnemyExperimentals = EntityCategoryFilterDown(categories.EXPERIMENTAL, tLZTeamData[AiBotMap.reftoNearestDFEnemies])
                            if AiBotUtilities.IsTableEmpty(tNearbyEnemyExperimentals) == false then
                                bConsiderAttackingExperimental = true
                                local iCurDist
                                local iClosestExpToBaseDist = 100000
                                local iClosestExpToMidpointDist = 100000
                                local iBestEnemyExpRange = 0
                                for iExp, oExp in tNearbyEnemyExperimentals do
                                    iBestEnemyExpRange = math.max(iBestEnemyExpRange, (oExp[AiBotUnitInfo.refiCombatRange] or 0))
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oExp:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                    if iCurDist < iClosestExpToBaseDist then
                                        iClosestExpToBaseDist = iCurDist
                                        oClosestEnemyExpToBase = oExp
                                    end
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oExp:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) - (oExp[AiBotUnitInfo.refiDFRange] or 0)
                                    if iCurDist < iClosestExpToMidpointDist then
                                        oClosestEnemyExpToMidpoint = oExp
                                        iClosestExpToMidpointDist = iCurDist
                                    end
                                end
                                --Are we against an enemy fatboy and we have nearby T2 arti? If so then only attack experimental if our unit is already in range of it/near to it depending on if enemy in range of firebase
                                local bNearbyFriendlyFirebaseVsFatboy = false
                                if iBestEnemyExpRange >= 80 and oClosestEnemyExpToBase then
                                    local iDistUntilInRangeOfArti = 100000
                                    local oClosestT2ArtiToEnemyExp
                                    local iClosestT2ArtiToEnemyDist = 100000
                                    function ConsiderClosestT2ArtiForZone(tCurLZTeamData)
                                        if tCurLZTeamData[AiBotMap.subrefLZThreatAllyStructureIndirect] >= 3000 then
                                            local tT2Arti = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedT2Arti, tCurLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                            if AiBotUtilities.IsTableEmpty(tT2Arti) == false then
                                                for iArti, oArti in tT2Arti do
                                                    if AiBotUnitInfo.IsUnitValid(oArti) and (oArti[AiBotUnitInfo.refiCombatRange] or 0) >= iBestEnemyExpRange then
                                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oArti:GetPosition(), oClosestEnemyExpToBase:GetPosition())
                                                        if not(oClosestEnemyExpToBase == oClosestEnemyExpToMidpoint) and oClosestEnemyExpToMidpoint and oClosestEnemyExpToMidpoint[AiBotUnitInfo.refiCombatRange] > 62 then iCurDist = math.min(iCurDist, AiBotUtilities.GetDistanceBetweenPositions(oArti:GetPosition(), oClosestEnemyExpToMidpoint:GetPosition())) end
                                                        if iCurDist < iClosestT2ArtiToEnemyDist then
                                                            iClosestT2ArtiToEnemyDist = iCurDist
                                                            oClosestT2ArtiToEnemyExp = oArti
                                                            iDistUntilInRangeOfArti = math.min(iDistUntilInRangeOfArti, iCurDist - oArti[AiBotUnitInfo.refiCombatRange])
                                                            if iDistUntilInRangeOfArti <= 3 then
                                                                break
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    ConsiderClosestT2ArtiForZone(tLZTeamData)
                                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false and iDistUntilInRangeOfArti > 3 then
                                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                            ConsiderClosestT2ArtiForZone(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
                                            if iDistUntilInRangeOfArti <= 3 then break end
                                        end
                                    end
                                    if oClosestT2ArtiToEnemyExp and iDistUntilInRangeOfArti > 3 then
                                        bNearbyFriendlyFirebaseVsFatboy = true
                                    end
                                end
                                if bNearbyFriendlyFirebaseVsFatboy then
                                    --Wnat to retreat as we have nearby t2 arti that could support us, so only engage if are almost in range
                                    iThresholdDistUntilInRangeToAttackExp = 10 --i.e. attack if withi n10 of being in range
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have firebase so will rely on firebase to help us and retreat unless almost in range') end
                                else
                                    --Pre-v235 this was  iThresholdDistUntilInRangeToAttackExp =  iBestEnemyExpRange + 15, presumably to stop experimentals idling while taking fatboy fire; however it'd also result in them suiciding into enemy fatboy, so have changed in v235 to below, may need to adjust further though
                                    if tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] <= 20 then
                                        iThresholdDistUntilInRangeToAttackExp = math.min(iBestEnemyExpRange + 20, 50)
                                    else
                                        iThresholdDistUntilInRangeToAttackExp = math.min(iBestEnemyExpRange + 15, 40)
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Time since t2 arti last fired='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] or 0)..'; iThresholdDistUntilInRangeToAttackExp='..iThresholdDistUntilInRangeToAttackExp..'; iBestEnemyExpRange='..iBestEnemyExpRange) end
                                end
                            end
                        end

                        local sRetreatMessage = 'GenRetr'

                        --Rescue ACU - move slightly infront of ACU relative to our closest base instead of retreating
                        ProtectFriendlyACUInTroubleIfRelevant(tAvailableCombatUnits)
                        if AiBotUtilities.IsTableEmpty(tAvailableCombatUnits) == false then
                            if bConsolidateAtMidpoint then
                                if oClosestFriendlyUnitToAnEnemyFirebase then
                                    tRallyPoint = AiBotUtilities.MoveInDirection(oClosestFriendlyUnitToAnEnemyFirebase:GetPosition(), AiBotUtilities.GetAngleFromAToB(oClosestFriendlyUnitToAnEnemyFirebase:GetPosition(), tLZData[AiBotMap.subrefMidpoint]), math.min(AiBotUtilities.GetDistanceBetweenPositions(oClosestFriendlyUnitToAnEnemyFirebase:GetPosition(), tRallyPoint), 15), true, false, true)
                                    local iAltPlateau, iAltLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tRallyPoint)
                                    if not(iAltPlateau == iPlateau) then
                                        tRallyPoint = AiBotMap.GetPositionAtOrNearTargetInPathingGroup(oClosestFriendlyUnitToAnEnemyFirebase:GetPosition(), tRallyPoint, 0, 0, oClosestFriendlyUnitToAnEnemyFirebase, false, false, nil)
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will try and consolidate based on the closest unit to enemy firebase, tRallyPoint adjusted for this='..repru(tRallyPoint)) end
                                else
                                    tRallyPoint = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]}
                                end
                                sRetreatMessage = 'ConsRP'
                            end
                            if AiBotMap.bIsCampaignMap and not(AiBotConditions.IsLocationInPlayableArea(tRallyPoint)) then
                                --If closest friendly base is in playable area go here
                                if AiBotConditions.IsLocationInPlayableArea(tLZTeamData[AiBotMap.reftClosestFriendlyBase]) then
                                    tRallyPoint = {tLZTeamData[AiBotMap.reftClosestFriendlyBase][1], tLZTeamData[AiBotMap.reftClosestFriendlyBase][2], tLZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
                                else
                                    local tMoveTowardsBase = AiBotUtilities.MoveInDirection(tLZData[AiBotMap.subrefMidpoint], AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestFriendlyBase]), 60, true, false, true)
                                    if tMoveTowardsBase then
                                        tRallyPoint = tMoveTowardsBase
                                    elseif AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) then
                                        tRallyPoint = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]}
                                    elseif oNearestEnemyToFriendlyBase then
                                        --Just go to the closest enemy unit
                                        tRallyPoint = oNearestEnemyToFriendlyBase:GetPosition()
                                    end
                                end
                            end
                            local bUnitIsSuicidingIntoMex = false
                            local bConsiderAttackMoveIfClose = false
                            local bMonkeylordSpecialMicro
                            local iCurDistToRally
                            if AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, tLZData[AiBotMap.subrefMidpoint]) <= 20 then bConsiderAttackMoveIfClose = true end

                            if bDebugMessages == true then LOG(sFunctionRef..': We are outranged by enemy and dont have enough threat to press the attack, will either retreat to prev LZ, or this LZ midpoint; bConsolidateAtMidpoint='..tostring(bConsolidateAtMidpoint)..'; bConsiderAttackingExperimental='..tostring(bConsiderAttackingExperimental)..'; tRallyPoint='..repru(tRallyPoint)..'; bSuicideUnitsNearAMex='..tostring(bSuicideUnitsNearAMex)..'; Is table of nearby mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyMexes))) end

                            --local bCheckIfNearLocationToAvoid = not(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftiLocationsToAvoid]))
                            bGivenCombatUnitsOrders = true
                            for iUnit, oUnit in tAvailableCombatUnits do
                                --If we are close to the last known position such that we will be able to see there is no longer a unit there, then update this unit's position for next cycle
                                if bCheckIfNearestUnitVisible and not(bUpdateNearestUnit) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 18 then bUpdateNearestUnit = true end

                                --Only retreat units from this LZ
                                if bDebugMessages == true then
                                    LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; will only retreat with unit if it is from this LZ, iLandZone='..iLandZone..'; Unit assigned zone='..(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or 'nil')..'; Is special micro active='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive])..'; oClosestEnemyExpToBase='..(oClosestEnemyExpToBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemyExpToBase) or 'nil')..'; iThresholdDistUntilInRangeToAttackExp='..(iThresholdDistUntilInRangeToAttackExp or 'nil')..'; oClosestEnemyExpToMidpoint='..(oClosestEnemyExpToMidpoint.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemyExpToMidpoint) or 'nil'))
                                    if oClosestEnemyExpToBase.UnitId and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oClosestEnemyExpToBase.UnitId) then
                                        LOG(sFunctionRef..': Dist until reach enemy fatboy='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestEnemyExpToBase:GetPosition())..'; our DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; CloseToEnemy check re fatboy='..tostring(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tNearbyEnemyExperimentals, 5, iTeam, true,                    nil,                    oUnit,                              oUnit))..'; Unit is assigned to this LZ and should proceed='..tostring(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone and ProceedWithUnitOrder(oUnit)))
                                    end
                                end

                                if oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone and ProceedWithUnitOrder(oUnit) then

                                    --if bCheckIfNearLocationToAvoid and EntityCategoryContains(categories.TECH1 + categories.TECH2 - categories.COMMAND, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) and AiBotConditions.HaveSentOrderToRunAwayFromLocationToAvoid(oUnit, tLZTeamData[AiBotMap.reftiLocationsToAvoid], 4) then
                                    --if bDebugMessages == true then LOG(sFunctionRef..': Unit will run away from location to avoid') end

                                    --Shot not blocked - consider attackign ACU with experimentals
                                    if bConsiderAttackingACU and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental - AiBotUnitInfo.refCategorySkirmisher - AiBotUnitInfo.refCategoryFatboy - AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride]) and AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), toEnemyACUsNearZone, 6 + (oUnit[AiBotUnitInfo.refiCombatRange] or 0), iTeam, false, nil, nil, nil, nil, nil) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Experimental - attack nearest ACU') end
                                        GetUnitToAttackNearestACUOrOverrideUnit(oUnit)
                                        --CloseToEnemyUnit(tStartPosition,       tUnitsToCheck, iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure, bIncludeEnemyAntiNavyRange)
                                    elseif bConsiderAttackingExperimental and
                                            (((oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 or ((oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oClosestEnemyExpToBase.UnitId))) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestEnemyExpToBase:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange] <= iThresholdDistUntilInRangeToAttackExp and AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tNearbyEnemyExperimentals, 5, iTeam, true,                    nil,                    oUnit,                              oUnit) and (not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryIndirect, oUnit.UnitId)) or ((oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 0 and (oUnit[AiBotUnitInfo.refiIndirectRange] < oClosestEnemyExpToBase[AiBotUnitInfo.refiCombatRange] or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestEnemyExpToBase:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange] >= 10)) or (tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] <= 10 and oClosestEnemyExpToBase[AiBotUnitInfo.refiCombatRange] >= math.max(60, oUnit[AiBotUnitInfo.refiCombatRange])))
                                                    or (not(oClosestEnemyExpToMidpoint == oClosestEnemyExpToBase) and oClosestEnemyExpToMidpoint and ((oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 or ((oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oClosestEnemyExpToMidpoint.UnitId))) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestEnemyExpToMidpoint:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange] <= iThresholdDistUntilInRangeToAttackExp and AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tNearbyEnemyExperimentals, 5, iTeam, true,                    nil,                    oUnit,                              oUnit) and (not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryIndirect, oUnit.UnitId)) or ((oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 0 and (oUnit[AiBotUnitInfo.refiIndirectRange] < oClosestEnemyExpToMidpoint[AiBotUnitInfo.refiCombatRange] or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestEnemyExpToMidpoint:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange] >= 10)) or (tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] <= 10 and oClosestEnemyExpToMidpoint[AiBotUnitInfo.refiCombatRange] >= math.max(60, oUnit[AiBotUnitInfo.refiCombatRange]))))) then
                                        --move to nearest enemy experimental if we arent in range of it yet but a friendly unit is, and we are an experimental level unit or it is a fatboy
                                        local bMoveTowardsExperimental = false
                                        --Want to move instead of attackmove if we are an experimental (or up against a fatboy) and aren't already in range (by a reasonable margin if against a fatboy)
                                        local oTargetToManuallyAttack, bMoveNotManualAttack = GetManualAttackTargetIfWantManualAttack(oUnit)
                                        if oTargetToManuallyAttack then
                                            --Consider moving instead of attacking if not well within range
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to attack or move towards enemy manual attack target, dist to target='..AiBotUtilities.GetDistanceBetweenPositions(oTargetToManuallyAttack:GetPosition(), oUnit:GetPosition())..'; Our DF range='..oUnit[AiBotUnitInfo.refiDFRange]..'; bMoveNotManualAttack='..tostring(bMoveNotManualAttack)) end
                                            if bMoveNotManualAttack then
                                                AiBotOrders.IssueTrackedMove(oUnit, oTargetToManuallyAttack:GetPosition(), 6, false, 'ExpMM'..iLandZone)
                                            else
                                                local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oTargetToManuallyAttack:GetPosition(), oUnit:GetPosition())
                                                if iDistToTarget > oUnit[AiBotUnitInfo.refiDFRange] - 3 or (iDistToTarget > oUnit[AiBotUnitInfo.refiDFRange] - 8 and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId)) then
                                                    AiBotOrders.IssueTrackedMove(oUnit, oTargetToManuallyAttack:GetPosition(), 6, false, 'ExpoM'..iLandZone)
                                                else
                                                    DoManualAttack(oUnit, oTargetToManuallyAttack, 'ExpMA')
                                                    --AiBotOrders.IssueTrackedAttack(oUnit, oTargetToManuallyAttack, false, 'ExpMA', false)
                                                end
                                            end
                                        else
                                            local tTargetToMoveTowards

                                            if EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oUnit.UnitId) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFatboy, tNearbyEnemyExperimentals)) == false then
                                                local oNearestEnemyExp
                                                local iClosestEnemyExpDist = 100000
                                                local iCurExpDist
                                                for iExperimental, oExperimental in tNearbyEnemyExperimentals do
                                                    iCurExpDist = AiBotUtilities.GetDistanceBetweenPositions(oExperimental:GetPosition(), oUnit:GetPosition())
                                                    if iCurExpDist < iClosestEnemyExpDist then
                                                        iClosestEnemyExpDist = iCurExpDist
                                                        oNearestEnemyExp = oExperimental
                                                    end
                                                end
                                                if iClosestEnemyExpDist > (oUnit[AiBotUnitInfo.refiCombatRange] or 0) - 3 then
                                                    bMoveTowardsExperimental = true
                                                end
                                                tTargetToMoveTowards = oNearestEnemyExp:GetPosition()
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will advance towards closest experimental='..(oNearestEnemyExp.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyExp) or 'nil')..'; iClosestEnemyExpDist='..iClosestEnemyExpDist..'; tTargetToMoveTowards='..repru(tTargetToMoveTowards)) end
                                            end
                                            if not(tTargetToMoveTowards) then tTargetToMoveTowards = {oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam][1], oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam][2], oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam][3]} end
                                            --If shot is blocked then move instad of attack move
                                            if oUnit[AiBotUnitInfo.refbLastShotBlocked] and not(bMoveTowardsExperimental) then
                                                if not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId)) or (iFriendlyBestMobileIndirectRange == 0 or tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] < tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] * 0.2 or iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 3) and (iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 1.75 or tLZTeamData[AiBotMap.refbIslandBeachhead] or (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) and iAvailableCombatUnitThreat > GetEnemyCombatThreatInAdjacentZones() * 0.9)) then
                                                    bMoveTowardsExperimental = true
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Shot is blocked so will mov towards the experimental') end
                                                else
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Shot is blocked but not sure we want to move closer') end
                                                end
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to advance to enemy experimental, bMoveTowardsExperimental='..tostring(bMoveTowardsExperimental)..'; oUnit[AiBotUnitInfo.refbLastShotBlocked]='..tostring(oUnit[AiBotUnitInfo.refbLastShotBlocked])) end
                                            if bMoveTowardsExperimental then
                                                AiBotOrders.IssueTrackedMove(oUnit, tTargetToMoveTowards, 6, false, 'ExpM'..iLandZone)
                                            else
                                                --Attackmove towards the experimental
                                                AiBotOrders.IssueTrackedAggressiveMove(oUnit, tTargetToMoveTowards, 6, false, 'ExpA'..iLandZone)
                                            end
                                        end
                                    elseif oUnit[AiBotAir.refiTimeLastDropped] and oUnit[AiBotUnitInfo.refiIndirectRange] > 0 and GetGameTimeSeconds() - oUnit[AiBotAir.refiTimeLastDropped] <= 60 and oNearestEnemyStructureToMidpoint then
                                        SuicideUnitIntoEnemyStructure(oUnit)
                                    else
                                        if bSuicideUnitsNearAMex and AiBotUtilities.IsTableEmpty(tNearbyMexes) == false then
                                            bUnitIsSuicidingIntoMex = false
                                            if not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryT3MobileArtillery + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId)) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride]) then
                                                local iClosestMex = math.max(25, (oUnit[AiBotUnitInfo.refiCombatRange] or 0) + 15)
                                                local oClosestMex
                                                local iCurMexDist
                                                for iMex, oMex in tNearbyMexes do
                                                    iCurMexDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oMex:GetPosition())
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Dist of oMex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)..' to unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'='..iCurMexDist) end
                                                    if iCurMexDist < iClosestMex then
                                                        oClosestMex = oMex
                                                        iClosestMex = iCurMexDist
                                                    end
                                                end
                                                if oClosestMex then
                                                    --Have a mex that is close; if the closest distance is almost in our range then attack it; but dont attack if we arent in range of enemy units yet and narest enemy unit is further from our rally than we are
                                                    if iClosestMex <= (oUnit[AiBotUnitInfo.refiCombatRange] + 3) then
                                                        bUnitIsSuicidingIntoMex = true
                                                    else
                                                        local bInRangeOfEnemy = AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], 4, iTeam, true, nil, nil, oUnit)
                                                        if not(bInRangeOfEnemy) then
                                                            if not(AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])) then
                                                                bUnitIsSuicidingIntoMex = true
                                                            else
                                                                --We arent in range of the enemy; but if we move to be in range of the mex will we be in range of them?
                                                                local iDistToClosestEnemyLessRange = AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()) - (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 0)
                                                                if iDistToClosestEnemyLessRange > (iClosestMex - (oUnit[AiBotUnitInfo.refiCombatRange] or 0)) then
                                                                    bUnitIsSuicidingIntoMex = true
                                                                    --Is the enemy closer to our rally point? if so then also want to suicide
                                                                elseif AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), tRallyPoint) < AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint) then
                                                                    bUnitIsSuicidingIntoMex = true
                                                                end
                                                            end
                                                        else
                                                            --We are in range of the enemy already; if enemy is closer to our rally point than us then still suicide
                                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), tRallyPoint) < AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint) then
                                                                bUnitIsSuicidingIntoMex = true
                                                            end
                                                        end
                                                    end
                                                    if bUnitIsSuicidingIntoMex then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will suicide unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' into oClosestMex='..oClosestMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestMex)) end
                                                        if iClosestMex <= oUnit[AiBotUnitInfo.refiCombatRange] + 2 then
                                                            AiBotOrders.IssueTrackedAttack(oUnit, oClosestMex, false, 'SuicMxAt')
                                                        else
                                                            if not(IgnoreOrderDueToStuckUnit(oUnit, oClosestMex:GetPosition())) then
                                                                AiBotOrders.IssueTrackedMove(oUnit, oClosestMex:GetPosition(), 2, false, 'SuicMxM')
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                        if not(bUnitIsSuicidingIntoMex) then

                                            oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
                                            --Monkkeylord - special micro retreat logic
                                            if oUnit.UnitId == 'url0402' then
                                                --Do we want to advance on enemy? I.e. if we outrange the enemy or the nearest enemy unit if we use our longer range of 64? Dont consider this if enemy has air to ground threat here though
                                                local bEnemyAlmostInRangeOfUs = AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tSkirmisherDFEnemies, 11, iTeam, true, nil, nil, oUnit, 6, false)
                                                local bWantToKiteTowardsEnemy = false
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to advance towards enemy, bEnemyAlmostInRangeOfUs='..tostring(bEnemyAlmostInRangeOfUs)..'; tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; Monkey oUnit health%='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)) end
                                                if not(bEnemyAlmostInRangeOfUs) and (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) <= 250 and AiBotUnitInfo.GetUnitHealthPercent(oUnit) >= 0.2 then
                                                    local oEnemyToConsiderAdvancingTowards
                                                    --Do we want to advance towards the nearest enmey?
                                                    if not(AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])) then
                                                        if AiBotUnitInfo.IsUnitValid(oNearestEnemyToFriendlyBase) then
                                                            oEnemyToConsiderAdvancingTowards = oNearestEnemyToFriendlyBase
                                                        end
                                                    else
                                                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()) < AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition()) then
                                                            oEnemyToConsiderAdvancingTowards = oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]
                                                        else
                                                            oEnemyToConsiderAdvancingTowards = oNearestEnemyToFriendlyBase
                                                        end
                                                    end
                                                    if oEnemyToConsiderAdvancingTowards and (oEnemyToConsiderAdvancingTowards[AiBotUnitInfo.refiDFRange] or 0) < 60 then
                                                        local iDistToNearestEnemy = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEnemyToConsiderAdvancingTowards:GetPosition())
                                                        --Are we far enough from the enemy that if we start microing back we will still fire?
                                                        if iDistToNearestEnemy > 58 then
                                                            if not(AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEnemyToConsiderAdvancingTowards, false)) then
                                                                if tLZTeamData[AiBotMap.refiRadarCoverage] < iIntelThresholdForPriorityScout then
                                                                    tLZTeamData[AiBotMap.refiTimeLastFailedToKiteDueToScoutIntel] = GetGameTimeSeconds()
                                                                end
                                                            else
                                                                --If we move to be in range of the enemy will the closest enemy combat unit be able to reach us?
                                                                bWantToKiteTowardsEnemy = true
                                                                if iDistToNearestEnemy > 70 and (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 0) >= 60 and not(oEnemyToConsiderAdvancingTowards == oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and AiBotUnitInfo.IsUnitValid( oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) then
                                                                    local iDistFromDangerousEnemyToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oEnemyToConsiderAdvancingTowards:GetPosition())
                                                                    if iDistFromDangerousEnemyToTarget < iDistToNearestEnemy + 10 then
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': The enemy unit closest to being able to attack us has a similar or better range than us, and is similar or closer to the enemy we want to attack, so wont attack and will just do gneeral retreat') end
                                                                        bWantToKiteTowardsEnemy = false
                                                                    end
                                                                end
                                                                if bWantToKiteTowardsEnemy then
                                                                    bMonkeylordSpecialMicro = true
                                                                    --Advance towards the enemy
                                                                    AiBotOrders.IssueTrackedMove(oUnit, oEnemyToConsiderAdvancingTowards:GetPosition(), 6, false, 'MonkAdv', false)
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Instead of retreating we will try kiting with this unit') end
                                                                end
                                                            end
                                                        end
                                                    end
                                                end

                                                if bEnemyAlmostInRangeOfUs or not(bWantToKiteTowardsEnemy) then
                                                    bMonkeylordSpecialMicro = AiBotMicro.MonkeylordRetreatMicro(oUnit, tAmphibiousRallyPoint, tLZTeamData[AiBotMap.reftClosestFriendlyBase], oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will do monkeylord retreat micro, bMonkeylordSpecialMicro='..tostring(bMonkeylordSpecialMicro or false)) end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Finished considering whether to do monkeylord retreat micro, bEnemyAlmostInRangeOfUs='..tostring(bEnemyAlmostInRangeOfUs or false)..'; bWantToKiteTowardsEnemy='..tostring(bWantToKiteTowardsEnemy or false)..'; bMonkeylordSpecialMicro='..tostring(bMonkeylordSpecialMicro or false)) end
                                            end
                                            if bMonkeylordSpecialMicro then
                                                --Reset for next unit
                                                bMonkeylordSpecialMicro = nil
                                            else
                                                if not(bConsolidateAtMidpoint) and EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                                                    --If moving to the rally point would take us closer to the enemy than moving towards our base then move towards base instead
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Amphibious unit and we dont want to consolidate at midpoint, CanKite='..tostring(oUnit[AiBotUnitInfo.refbCanKite] or false)) end
                                                    if not(oUnit[AiBotUnitInfo.refbCanKite]) and EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) then
                                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, tAmphibiousRallyPoint, 6, false, 'ExKA'..sRetreatMessage..iLandZone)
                                                    else
                                                        local bMoveTowardsBaseInstead = false
                                                        local iAngleToBase
                                                        if tMoveTowardsBaseRetreatPoint then --If this is not nil then it means the rally point will take us a different angle to the nearest friendly base, which might cause us to move closer/within range of enemy units
                                                            local iAngleToNearestEnemy = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())
                                                            iAngleToBase = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])

                                                            if 180 - AiBotUtilities.GetAngleDifference(iAngleToNearestEnemy, iAngleToBase) <= 45 then
                                                                bMoveTowardsBaseInstead = true
                                                                if AiBotMap.bIsCampaignMap and not(AiBotConditions.IsLocationInPlayableArea(tLZTeamData[AiBotMap.reftClosestFriendlyBase])) then bMoveTowardsBaseInstead = false end
                                                            end
                                                        end
                                                        if bMoveTowardsBaseInstead then --see below for similar code if making changes here
                                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tMoveTowardsBaseRetreatPoint) <= 12 or AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tMoveTowardsBaseRetreatPoint), iAngleToBase) >= 45 then
                                                                if (oUnit[AiBotUnitInfo.refbWeaponUnpacks] or not(oUnit[AiBotUnitInfo.refbCanKite])) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 13 then
                                                                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tLZTeamData[AiBotMap.reftClosestFriendlyBase], 6, false, 'MTBBA'..sRetreatMessage..iLandZone)
                                                                else
                                                                    if bConsiderAttackMoveIfClose and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 20 then
                                                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, tLZTeamData[AiBotMap.reftClosestFriendlyBase], 6, false, 'MTBABA'..iLandZone)
                                                                    else
                                                                        AiBotOrders.IssueTrackedMove(oUnit, tLZTeamData[AiBotMap.reftClosestFriendlyBase], 6, false, 'MTBBA'..sRetreatMessage..iLandZone)
                                                                    end
                                                                end

                                                            else
                                                                if (oUnit[AiBotUnitInfo.refbWeaponUnpacks] or not(oUnit[AiBotUnitInfo.refbCanKite])) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tMoveTowardsBaseRetreatPoint) <= 13 then
                                                                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tMoveTowardsBaseRetreatPoint, 6, false, 'MTBNA'..sRetreatMessage..iLandZone)
                                                                else
                                                                    if bConsiderAttackMoveIfClose and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tMoveTowardsBaseRetreatPoint) <= 20 then
                                                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, tMoveTowardsBaseRetreatPoint, 6, false, 'MTBABA'..iLandZone)
                                                                    else
                                                                        AiBotOrders.IssueTrackedMove(oUnit, tMoveTowardsBaseRetreatPoint, 6, false, 'MTBNA'..sRetreatMessage..iLandZone)
                                                                    end
                                                                end
                                                            end
                                                        else
                                                            local bAttackMove = false
                                                            if (oUnit[AiBotUnitInfo.refbWeaponUnpacks] or not(oUnit[AiBotUnitInfo.refbCanKite])) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tAmphibiousRallyPoint) <= 13 then
                                                                bAttackMove = true
                                                            else
                                                                if bConsiderAttackMoveIfClose and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tAmphibiousRallyPoint) <= 20 then
                                                                    bAttackMove = true
                                                                end
                                                            end
                                                            iCurDistToRally = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tAmphibiousRallyPoint)
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Will go to amphibious rally point, bAttackMove='..tostring(bAttackMove)..'; bConsiderAttackMoveIfClose='..tostring(bConsiderAttackMoveIfClose)..'; iCurDistToRally='..iCurDistToRally..'; Angle to rally='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tAmphibiousRallyPoint)) end
                                                            if iCurDistToRally >= 200 then
                                                                --Had issue where monkeylord got stuck when 251 dist from rally point
                                                                local iAngleToRallyPoint = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tAmphibiousRallyPoint)
                                                                local tMoveTowardsBaseRetreatPoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleToRallyPoint, 200, true, true, AiBotMap.bIsCampaignMap)
                                                                if AiBotUtilities.IsTableEmpty(tMoveTowardsBaseRetreatPoint) == false then
                                                                    if not(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tMoveTowardsBaseRetreatPoint) == tLZData[AiBotMap.subrefLZIslandRef]) then
                                                                        tMoveTowardsBaseRetreatPoint = nil

                                                                    end
                                                                end
                                                                if bDebugMessages == true then LOG(sFunctionRef..': tMoveTowardsBaseRetreatPoint='..repru(tMoveTowardsBaseRetreatPoint)..'; bAttackMove='..tostring(bAttackMove or false)) end
                                                                if tMoveTowardsBaseRetreatPoint then
                                                                    if bAttackMove then
                                                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, tMoveTowardsBaseRetreatPoint, 6, false, 'RAInt'..sRetreatMessage..iLandZone)
                                                                    else
                                                                        AiBotOrders.IssueTrackedMove(oUnit, tMoveTowardsBaseRetreatPoint, 6, false, 'MInt'..sRetreatMessage..iLandZone)
                                                                    end
                                                                else
                                                                    if bAttackMove then
                                                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, tAmphibiousRallyPoint, 6, false, 'RAXInt'..sRetreatMessage..iLandZone)
                                                                    else
                                                                        AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'MXInt'..sRetreatMessage..iLandZone)
                                                                    end
                                                                end
                                                            else
                                                                if bAttackMove then
                                                                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tAmphibiousRallyPoint, 6, false, 'RA'..sRetreatMessage..iLandZone)
                                                                else
                                                                    AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'M'..sRetreatMessage..iLandZone)
                                                                end
                                                            end
                                                        end

                                                    end
                                                else
                                                    if not(oUnit[AiBotUnitInfo.refbCanKite]) and EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) then
                                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, tRallyPoint, 6, false, 'ExKG'..sRetreatMessage..iLandZone)
                                                    else
                                                        local bMoveTowardsBaseInstead = false
                                                        local iAngleToBase
                                                        local iAngleToNearestEnemy
                                                        if tMoveTowardsBaseRetreatPoint then --If this is not nil then it means the rally point will take us a different angle to the nearest friendly base, which might cause us to move closer/within range of enemy units
                                                            iAngleToNearestEnemy = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition())
                                                            iAngleToBase = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                                            if 180 - AiBotUtilities.GetAngleDifference(iAngleToNearestEnemy, iAngleToBase) <= 45 then
                                                                bMoveTowardsBaseInstead = true
                                                                if AiBotMap.bIsCampaignMap and not(AiBotConditions.IsLocationInPlayableArea(tLZTeamData[AiBotMap.reftClosestFriendlyBase])) then bMoveTowardsBaseInstead = false end
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': iAngleToNearestEnemy='..iAngleToNearestEnemy..'; iAngleToBase='..iAngleToBase..'; Angle dif between angle to nearest enemy and angle to base='..AiBotUtilities.GetAngleDifference(iAngleToNearestEnemy, iAngleToBase)..'; bMoveTowardsBaseInstead='..tostring(bMoveTowardsBaseInstead)) end
                                                        end
                                                        if bDebugMessages == true then LOG(sFunctionRef..': bMoveTowardsBaseInstead='..tostring(bMoveTowardsBaseInstead)) end
                                                        if bMoveTowardsBaseInstead then --see above for similar code if making changes here
                                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tMoveTowardsBaseRetreatPoint) <= 12 or AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tMoveTowardsBaseRetreatPoint), iAngleToBase) >= 45 then
                                                                if (oUnit[AiBotUnitInfo.refbWeaponUnpacks] or not(oUnit[AiBotUnitInfo.refbCanKite])) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 13 then
                                                                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tLZTeamData[AiBotMap.reftClosestFriendlyBase], 6, false, 'MTBB'..sRetreatMessage..iLandZone)
                                                                else
                                                                    AiBotOrders.IssueTrackedMove(oUnit, tLZTeamData[AiBotMap.reftClosestFriendlyBase], 6, false, 'MTBB'..sRetreatMessage..iLandZone)
                                                                end
                                                            else
                                                                if (oUnit[AiBotUnitInfo.refbWeaponUnpacks] or not(oUnit[AiBotUnitInfo.refbCanKite])) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tMoveTowardsBaseRetreatPoint) <= 13 then
                                                                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tMoveTowardsBaseRetreatPoint, 6, false, 'MTBN'..sRetreatMessage..iLandZone)
                                                                else
                                                                    AiBotOrders.IssueTrackedMove(oUnit, tMoveTowardsBaseRetreatPoint, 6, false, 'MTBN'..sRetreatMessage..iLandZone)
                                                                end
                                                            end
                                                        else
                                                            if not(iAngleToNearestEnemy) and oNearestEnemyToFriendlyBase then iAngleToNearestEnemy = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oNearestEnemyToFriendlyBase:GetPosition()) end
                                                            local bRunFromNearestEnemy = false
                                                            if iAngleToNearestEnemy then
                                                                local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tRallyPoint)
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Will retreat towards rally point unless takes us towards nearest enemy, iAngleToNearestEnemy='..(iAngleToNearestEnemy or 'nil')..'; iAngleToRally='..iAngleToRally) end
                                                                if AiBotUtilities.GetAngleDifference(iAngleToRally, iAngleToNearestEnemy) <= 90 then
                                                                    bRunFromNearestEnemy = true
                                                                    RunFromEnemy(oUnit, oNearestEnemyToFriendlyBase, iTeam, iPlateau, 10)
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will run from the enemy closest to our base') end
                                                                end
                                                            end
                                                            if not(bRunFromNearestEnemy) then
                                                                if bDebugMessages == true then
                                                                    LOG(sFunctionRef..': Will retreat towards rally point, tRallyPoint='..repru(tRallyPoint)..'; Unit position='..repru(oUnit:GetPosition())..'; Unit special micro='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; last order position='..repru(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition]))
                                                                    --AiBotUtilities.DrawLocation(tRallyPoint)
                                                                end
                                                                if (oUnit[AiBotUnitInfo.refbWeaponUnpacks] or not(oUnit[AiBotUnitInfo.refbCanKite])) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint) <= 13 then
                                                                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tRallyPoint, 6, false, sRetreatMessage..iLandZone)
                                                                else
                                                                    AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, sRetreatMessage..iLandZone)
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                else
                                    --Unit is from a different zone - need to change the value of its assignment so it is considered for orders by the zone that it is part of
                                    oUnit[refiCurrentAssignmentValue] = 0
                                end
                            end
                        end
                    end

                    if bUpdateNearestUnit then
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
                            local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                            if aiBrain then
                                AiBotTeam.UpdateUnitLastKnownPosition(aiBrain, oNearestEnemyToFriendlyBase, true)
                            end
                        else
                            AiBotUtilities.ErrorHandler('No active AiBot brain')
                        end
                    end
                end
                --MML synchronisation logic
                if (bConsiderSpecialMMLLogic or bEnemyHasFixedShieldsInThisOrAdjacentZone) and AiBotUtilities.IsTableEmpty(tMMLForSynchronisation) == false then
                    --Get table of enemy shields and TMD to consider targeting
                    local tPriorityMMLTargets = {}
                    local bConsiderMultipleTargets = false
                    function IncludeTMDAndShieldsInZone(iAdjLZ, iOverridePlateau, iSearchCategory)
                        local tAdjLZTeamData
                        if iAdjLZ == iLandZone and not(iOverridePlateau) then tAdjLZTeamData = tLZTeamData else tAdjLZTeamData = AiBotMap.tAllPlateaus[(iOverridePlateau or iPlateau)][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam] end
                        if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                            local tZoneTMDAndShields = EntityCategoryFilterDown(iSearchCategory, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                            if AiBotUtilities.IsTableEmpty(tZoneTMDAndShields) == false then
                                for iTMDOrShield, oTMDOrShield in tZoneTMDAndShields do
                                    if oTMDOrShield:GetFractionComplete() >= 0.3 and AiBotUnitInfo.IsUnitValid(oTMDOrShield) and not(oTMDOrShield:IsUnitState('Attached')) and (oTMDOrShield:GetFractionComplete() >= 0.5 or ((oTMDOrShield[AiBotUnitInfo.refiUnitMassCost] or 0) >= 300 and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryTMD, oTMDOrShield.UnitId))) and (not(EntityCategoryContains(categories.MOBILE, oTMDOrShield.UnitId)) or (not(oTMDOrShield:IsUnitState('Moving')) and AiBotUnitInfo.GetUnitSpeed(oTMDOrShield) <= 0.1)) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Including unit '..oTMDOrShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMDOrShield)..' in tPriorityMMLTargets') end
                                        table.insert(tPriorityMMLTargets, oTMDOrShield)
                                    end
                                end
                            end
                        end
                    end

                    local iPrioritySearchCategory = AiBotUnitInfo.refCategoryTMD + AiBotUnitInfo.refCategoryFixedShield
                    local iMMLMassValue = AiBotUnitInfo.GetMassCostOfUnits(tMMLForSynchronisation)
                    local bIncludedT2ArtiInSearchCategory = false
                    --if iMMLMassValue >= 1000 then --removed as want our mml to target stationery enemy mmls even when we only have 1-2 of them
                    iPrioritySearchCategory = iPrioritySearchCategory + (AiBotUnitInfo.refCategoryIndirect * categories.MOBILE - categories.TECH1)
                    if iMMLMassValue >= 2000 then --have 10+ T2 MML equivalent so include t2 arti when searching
                        bConsiderMultipleTargets = true
                        iPrioritySearchCategory = iPrioritySearchCategory + AiBotUnitInfo.refCategoryFixedT2Arti
                        if bDebugMessages == true then LOG(sFunctionRef..': Including fixed t2 arti in priority search category') end
                        bIncludedT2ArtiInSearchCategory = true
                        if iMMLMassValue >= 4000 then --Include T2 and T3 PD as well
                            iPrioritySearchCategory = iPrioritySearchCategory + AiBotUnitInfo.refCategoryT2PlusPD
                            if bDebugMessages == true then LOG(sFunctionRef..': Including T2Plus PD in priority search category') end
                        end
                    end
                    --end
                    IncludeTMDAndShieldsInZone(iLandZone, nil, iPrioritySearchCategory)
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            IncludeTMDAndShieldsInZone(iAdjLZ, nil, iPrioritySearchCategory)
                        end
                    end
                    if tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] then
                        for iEntry, tPlateauAndZone in tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] do
                            IncludeTMDAndShieldsInZone(tPlateauAndZone[2], tPlateauAndZone[1], iPrioritySearchCategory)
                        end
                    end
                    --Add upgrading enemy ACUs that are near this zone midpoint (except in LOUD where ACUs have TMD) - (will also have a check later on based on ACUs in this specific zone; benefit of below though is it covers adjacent zones)
                    if not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (AiBotUtilities.IsTableEmpty(tPriorityMMLTargets) or table.getn(tPriorityMMLTargets) <= iMMLMassValue / 1200) then
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
                            for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                                if AiBotUnitInfo.IsUnitValid(oACU) and oACU:IsUnitState('Upgrading') and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= 120 then
                                    table.insert(tPriorityMMLTargets, oACU)
                                end
                            end
                        end
                    end

                    --Add T2 arti as priority targets if we have no shields or TMD
                    local bCheckForT2ArtiInRange = false
                    if not(bIncludedT2ArtiInSearchCategory) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                        bCheckForT2ArtiInRange = true --will check either generally (if no TMD/Shields in the priority units), or just on an inndividaul unit basis where the neares TMD/Shield is significantly out of our range
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Potential extra check for t2 arti if no normal priority targets, iMMLMassValue='..iMMLMassValue..'; bIncludedT2ArtiInSearchCategory='..tostring(bIncludedT2ArtiInSearchCategory)..'; is tPriorityMMLTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tPriorityMMLTargets))..'; is subreftoAllNearbyEnemyT2ArtiUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]))) end
                    if bCheckForT2ArtiInRange and (AiBotUtilities.IsTableEmpty(tPriorityMMLTargets) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryTMD + AiBotUnitInfo.refCategoryFixedShield, tPriorityMMLTargets))) then
                        bCheckForT2ArtiInRange = false --we are checking by adding t2 arti below so dont need this enabled
                        IncludeTMDAndShieldsInZone(iLandZone, nil, AiBotUnitInfo.refCategoryFixedT2Arti)
                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                            for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                IncludeTMDAndShieldsInZone(iAdjLZ, nil, AiBotUnitInfo.refCategoryFixedT2Arti)
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished searching just for t2 arti, is tPriorityMMLTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tPriorityMMLTargets))) end
                    end



                    --Consider orders for each MML
                    local oClosestPotentialTarget
                    local iClosestPotentialTarget
                    local iCurTargetDist
                    local tMMLWithNearbyTargets = {}
                    local toAlreadyCoveredTargets = {}
                    local tiAssignedInRangeThreatByEntity = {}
                    local iDistThresholdForInRange = 5


                    if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through each MML for synchronisation and get a target for it, is tPriorityMMLTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tPriorityMMLTargets))) end
                    local iDistThresholdFurtherAdjust
                    local tPriorityEnemyScoutTargets = {}
                    local bOnlyConsiderFailedShieldsInRange
                    if AiBotUtilities.IsTableEmpty(tEnemyEngineers) then tEnemyEngineers = nil end
                    for iUnit, oUnit in tMMLForSynchronisation do
                        iDistThresholdFurtherAdjust = 0
                        if oUnit[AiBotUnitInfo.refiIndirectRange] - iEnemyBestDFRange >= 40 and oUnit[AiBotUnitInfo.refiIndirectRange] >= 55 then iDistThresholdFurtherAdjust = math.max(8, 20 - iIndirectRunFigureSynchronisation)
                        elseif iEnemyBestDFRange > 30 and oUnit[AiBotUnitInfo.refiIndirectRange] >= 55 then iDistThresholdFurtherAdjust = math.min(4, 20 - iIndirectRunFigureSynchronisation)
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Is MML '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at position '..repru(oUnit:GetPosition())..' close to enemy DF units='..tostring(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], iIndirectRunFigureSynchronisation + iDistThresholdFurtherAdjust, iTeam, true, math.min(30, oUnit[AiBotUnitInfo.refiIndirectRange] - iIndirectRunFigureSynchronisation * 2, math.max(25, iEnemyBestDFRange + 5)), nil,                        oUnit))..'; iDistThresholdFurtherAdjust='..iDistThresholdFurtherAdjust..'; CloseToEnemy based on tSkirmisherDFENemies='..tostring(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tSkirmisherDFEnemies, iIndirectRunFigureSynchronisation + iDistThresholdFurtherAdjust, iTeam, true, math.min(30, oUnit[AiBotUnitInfo.refiIndirectRange] - iIndirectRunFigureSynchronisation * 2, math.max(25, iEnemyBestDFRange + 5)), nil,                        oUnit))) end
                        --Are we about to be in reclaim range of enemy engineer? then retreat; T3 engis have a ubild range of 7, so will use 8 (since want to retreat before are actually in r ange anyway, so just means retreating with 3 threshold for t1)
                        if tEnemyEngineers and AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tEnemyEngineers,                  8,                                                         iTeam, false,                       nil,                                                                                                        nil,                            oUnit) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy engineer about to get into reclaim range, want to temporairly run to rally point') end
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                                AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'MMLEngRetr'..iLandZone)
                            else
                                AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'MMLEngetr'..iLandZone)
                            end
                            --CloseToEnemyUnit(tStartPosition,      tUnitsToCheck,                                                   iDistThreshold,                                                iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange,                                                                                        oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure, bIncludeEnemyAntiNavyRange)
                        elseif not(AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tSkirmisherDFEnemies, iIndirectRunFigureSynchronisation + iDistThresholdFurtherAdjust, iTeam, true, math.min(30, oUnit[AiBotUnitInfo.refiIndirectRange] - iIndirectRunFigureSynchronisation * 2, math.max(25, iEnemyBestDFRange + 5)), nil,                        oUnit)) then
                            if AiBotUtilities.IsTableEmpty(tPriorityMMLTargets) then --redundancy - hopefully only scenario we get here is if there is 1 part-complete TMD/shield that is <30% complete
                                AiBotOrders.IssueTrackedAggressiveMove(oUnit, (oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam] or oNearestEnemyToFriendlyBase:GetPosition()), math.max(15, (iIndirectDistanceInsideRangeThreshold or 15)), false, 'I2KAMve'..iLandZone)
                                if bDebugMessages == true then LOG(sFunctionRef..': Redundancy will just attackmove as no priority MML targets') end
                            else
                                --Get the closest TMD/shield to this MML, and then decide whether to attack it or not (for performance reasons stop as soon as we have a target within TML range
                                iClosestPotentialTarget = 100000
                                bOnlyConsiderFailedShieldsInRange = false
                                for iTarget, oTarget in tPriorityMMLTargets do
                                    iCurTargetDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oTarget:GetPosition())
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering priority target oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..'; Fraction complete='..oTarget:GetFractionComplete()..'; iCurTargetDist='..iCurTargetDist..'; iClosestPotentialTarget='..iClosestPotentialTarget) end
                                    if (iCurTargetDist < iClosestPotentialTarget and not(bOnlyConsiderFailedShieldsInRange)) or (bOnlyConsiderFailedShieldsInRange and iCurTargetDist < oUnit[AiBotUnitInfo.refiIndirectRange] and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oTarget.UnitId) and oTarget.MyShield.GetHealth and oTarget.MyShield:GetHealth() < 400) then
                                        iClosestPotentialTarget = iCurTargetDist
                                        oClosestPotentialTarget = oTarget
                                        if iClosestPotentialTarget < oUnit[AiBotUnitInfo.refiIndirectRange] then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Target is in range so wont look for more targets unless dealing with a shield that still has health') end
                                            if (EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oClosestPotentialTarget.UnitId) and oClosestPotentialTarget.MyShield.GetHealth and oClosestPotentialTarget:GetFractionComplete() == 1 and oClosestPotentialTarget.MyShield:GetHealth() >= 400) or (not(EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oTarget.UnitId) and AiBotUtilities.IsTableEmpty(oTarget[AiBotBuilding.reftoShieldsProvidingCoverage]) == false and AiBotLogic.IsTargetUnderShield(aiBrain, oTarget, 400, false, true, true, false, false))) then
                                                bOnlyConsiderFailedShieldsInRange = true
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will continue searching to see if any shields whose shield has failed') end
                                            else
                                                break
                                            end
                                        end
                                    end
                                end
                                if bCheckForT2ArtiInRange and not(bOnlyConsiderFailedShieldsInRange) and iClosestPotentialTarget > oUnit[AiBotUnitInfo.refiIndirectRange] + 5 and (iClosestPotentialTarget > oUnit[AiBotUnitInfo.refiIndirectRange] + 15 or not(EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryTMD, oClosestPotentialTarget.UnitId))) then
                                    for iTarget, oTarget in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
                                        if not(oTarget.Dead) and oTarget:GetFractionComplete() >= 0.3 then
                                            iCurTargetDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oTarget:GetPosition())
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering switching to enemy t2 arti, iCurTargetDist='..iCurTargetDist..'; oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)) end
                                            if iCurTargetDist < oUnit[AiBotUnitInfo.refiIndirectRange] + 5 then
                                                iClosestPotentialTarget = iCurTargetDist
                                                oClosestPotentialTarget = oTarget
                                            end
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': oClosestPotentialTarget after checking PriorityMMLTargets='..(oClosestPotentialTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestPotentialTarget) or 'nil')) end
                                if not(oClosestPotentialTarget) and AiBotUtilities.IsTableEmpty(toAlreadyCoveredTargets) == false then
                                    for iTarget, oTarget in toAlreadyCoveredTargets do
                                        iCurTargetDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oTarget:GetPosition())
                                        if iCurTargetDist < iClosestPotentialTarget then
                                            iClosestPotentialTarget = iCurTargetDist
                                            oClosestPotentialTarget = oTarget
                                            if iClosestPotentialTarget < oUnit[AiBotUnitInfo.refiIndirectRange] then break end
                                        end
                                    end
                                end
                                if not(oClosestPotentialTarget) then
                                    AiBotUtilities.ErrorHandler('Somehow dont have a target for MML')
                                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, oNearestEnemyToFriendlyBase[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], math.max(15, iIndirectDistanceInsideRangeThreshold), false, 'I2KAMve'..iLandZone)
                                else
                                    if iClosestPotentialTarget - iDistThresholdForInRange > oUnit[AiBotUnitInfo.refiIndirectRange] then
                                        --Still a bit of distance until we are in range; attack move if we are far away, but do a normal move if we are almost in range
                                        --First check if another target (e.g. upgrading ACU) we should focus fire on first though, if it's significnatly closer than the nearest shield or TMD
                                        local oInRangeUpgradingACU
                                        if AiBotUtilities.IsTableEmpty(toEnemyACUsNearZone) == false and iClosestPotentialTarget - 10 > oUnit[AiBotUnitInfo.refiIndirectRange] then
                                            for iACU, oACU in toEnemyACUsNearZone do
                                                if oACU:IsUnitState('Upgrading') and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition()) <= oUnit[AiBotUnitInfo.refiIndirectRange] then
                                                    oInRangeUpgradingACU = oACU
                                                    break
                                                end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': oInRangeUpgradingACU='..(oInRangeUpgradingACU.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oInRangeUpgradingACU) or 'nil')..'; iClosestPotentialTarget='..iClosestPotentialTarget..'; oUnit[AiBotUnitInfo.refiIndirectRange]='..oUnit[AiBotUnitInfo.refiIndirectRange]..'; oClosestPotentialTarget='..(oClosestPotentialTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestPotentialTarget) or 'nil')) end
                                        if oInRangeUpgradingACU then
                                            AiBotOrders.IssueTrackedGroundAttack(oUnit, oInRangeUpgradingACU:GetPosition(), (oUnit[AiBotUnitInfo.refiIndirectAOE] or 0), false, 'MMLSchACU', false)
                                            table.insert(tMMLWithNearbyTargets, oUnit)
                                        elseif iClosestPotentialTarget - 35 > oUnit[AiBotUnitInfo.refiIndirectRange] then
                                            AiBotOrders.IssueTrackedAggressiveMove(oUnit, oClosestPotentialTarget:GetPosition(), (oUnit[AiBotUnitInfo.refiIndirectAOE] or 0), false, 'MMLSchAM'..iLandZone)
                                        else
                                            AiBotOrders.IssueTrackedMove(oUnit, oClosestPotentialTarget:GetPosition(), (oUnit[AiBotUnitInfo.refiIndirectAOE] or 0), false, 'MMLSchM'..iLandZone)
                                        end
                                    else
                                        if oClosestPotentialTarget[AiBotUnitInfo.refbHaveSeenUnitByTeam][iTeam] or not(EntityCategoryContains(AiBotUnitInfo.refCategoryTMD + AiBotUnitInfo.refCategoryStealthGenerator, oClosestPotentialTarget.UnitId)) then
                                            --Can attack the unit itself as either in range or almost in range
                                            AiBotOrders.IssueTrackedGroundAttack(oUnit, oClosestPotentialTarget:GetPosition(), (oUnit[AiBotUnitInfo.refiIndirectAOE] or 0), false, 'MMLSchGA', false)
                                        else
                                            --Enemy TMD that we dont have intel of
                                            tPriorityEnemyScoutTargets[oClosestPotentialTarget.EntityId] = oClosestPotentialTarget
                                            AiBotOrders.IssueTrackedAggressiveMove(oUnit, oClosestPotentialTarget:GetPosition(), (oUnit[AiBotUnitInfo.refiIndirectAOE] or 10) - 5, 'MMLNoVis')
                                        end
                                        table.insert(tMMLWithNearbyTargets, oUnit)
                                        if bConsiderMultipleTargets then
                                            tiAssignedInRangeThreatByEntity[oClosestPotentialTarget.EntityId] = (tiAssignedInRangeThreatByEntity[oClosestPotentialTarget.EntityId] or 0) + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have enough threat assigned to this unit, oClosestPotentialTarget='..oClosestPotentialTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestPotentialTarget)..'; tiAssignedInRangeThreatByEntity[oClosestPotentialTarget.EntityId]='..(tiAssignedInRangeThreatByEntity[oClosestPotentialTarget.EntityId] or 'nil')..'; after increasing for Unit mass cost='..(oUnit[AiBotUnitInfo.refiUnitMassCost] or 'nil')..'; target max health='..AiBotUnitInfo.GetUnitMaxHealthIncludingShield(tiAssignedInRangeThreatByEntity[oClosestPotentialTarget.EntityId])) end
                                            if tiAssignedInRangeThreatByEntity[oClosestPotentialTarget.EntityId] >= math.max(1000, AiBotUnitInfo.GetUnitMaxHealthIncludingShield(oUnit) * oUnit:GetFractionComplete() * 0.4) then
                                                --Remove unit from the priority target table and add to the 'other' table
                                                for iEntry, oEntry in  tPriorityMMLTargets do
                                                    if oEntry == oClosestPotentialTarget then
                                                        table.insert(toAlreadyCoveredTargets, oEntry)
                                                        table.remove(tPriorityMMLTargets, iEntry)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Recording unit in toAlreadyCoveredTargets and removing from priorityMMLTargets, oEntry='..(oEntry.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEntry) or 'nil')) end
                                                        break
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            --If we would be running from an enemy PD (which cant chase us) and we aren't yet in range of it, then switch to attacking that PD instead; do +3 as if we get too close we might trigger dodge shot micro, and/or might move into range of the pd due to dodge shot micro
                        elseif oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId) and AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()) > (oUnit[AiBotUnitInfo.refiDFRange] or 0) + 3 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Normally would retreat but there is an enemy PD that is the closest to being in our range and we can attack it without getting in range') end
                            AiBotOrders.IssueTrackedAttack(oUnit, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck], false, 'MMLAtckNtR', false)
                        else
                            local bTemporaryKiting = false
                            if oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] and AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()) <= math.max(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] + 8, oUnit[AiBotUnitInfo.refiCombatRange] - 10) then
                                local tTemporaryRetreatLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()), 8, true, false, AiBotMap.bIsCampaignMap)
                                if tTemporaryRetreatLocation and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tTemporaryRetreatLocation) == tLZData[AiBotMap.subrefLZIslandRef] then
                                    bTemporaryKiting = true
                                    AiBotOrders.IssueTrackedMove(oUnit, tTemporaryRetreatLocation, 6, false, 'MMLOpERetr'..iLandZone)
                                end
                            end

                            if bDebugMessages == true then
                                if oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] then
                                    LOG(sFunctionRef..': Retreating MML, dist to closest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())..'; oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]='..oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])..' with DF range='..(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 'nil'))
                                else
                                    LOG(sFunctionRef..': Will retreat MML') end
                            end
                            --Retreat temporarily from enemy units
                            if not(bTemporaryKiting) then
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                                    AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'MMLASKRetr'..iLandZone)
                                else
                                    AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'MMLSKRetr'..iLandZone)
                                end
                            end
                        end
                    end

                    if AiBotUtilities.IsTableEmpty(tPriorityEnemyScoutTargets) == false then
                        local iAirSubteam = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].AiBotAirSubteam
                        for iEnemy, oEnemy in tPriorityEnemyScoutTargets do
                            AiBotAir.AddUnitWantingPriorityScout(oEnemy, false, iAirSubteam)
                        end
                    end

                    --Do we have any MML that have targets in-range or almost in range? If so then consider synchronising their weapons (dont do this though if we only want to prioritise TMD and shields and dont want to synchronise)
                    if bDebugMessages == true then LOG(sFunctionRef..': Is tMMLWithNearbyTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tMMLWithNearbyTargets))) end
                    if bConsiderSpecialMMLLogic and AiBotUtilities.IsTableEmpty(tMMLWithNearbyTargets) == false then
                        local iMMLWithTargets = table.getn(tMMLWithNearbyTargets)
                        if bDebugMessages == true then LOG(sFunctionRef..': iMMLWithTargets='..iMMLWithTargets) end
                        if iMMLWithTargets >= 4 then
                            local iMMLJustFiredOrReadyToFire = 0
                            local iMMLNotFiredForAges = 0
                            local iMMLReloading = 0

                            local iTimeUntilReadyToFire
                            local iTotalTimeUntilReadyToFire = 0
                            local iMinTimeUntilReady = 100000
                            local iMaxTimeUntilReady = -100000
                            local tiTimeUntilReadyToFire = {}
                            for iUnit, oUnit in tMMLWithNearbyTargets do
                                iTimeUntilReadyToFire = oUnit[AiBotUnitInfo.refiTimeBetweenIFShots] - (GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or -100))
                                if iTimeUntilReadyToFire <= math.min(-7, -oUnit[AiBotUnitInfo.refiTimeBetweenIFShots] - 1.5) then
                                    iMMLNotFiredForAges = iMMLNotFiredForAges + 1
                                elseif iTimeUntilReadyToFire >= 1.01 then
                                    iMMLReloading = iMMLReloading + 1
                                else
                                    iMMLJustFiredOrReadyToFire = iMMLJustFiredOrReadyToFire + 1
                                end
                                if iTimeUntilReadyToFire < iMinTimeUntilReady then iMinTimeUntilReady = iTimeUntilReadyToFire end
                                if iTimeUntilReadyToFire > iMaxTimeUntilReady then iMaxTimeUntilReady = iTimeUntilReadyToFire end
                                iTotalTimeUntilReadyToFire = iTotalTimeUntilReadyToFire + iTimeUntilReadyToFire
                                table.insert(tiTimeUntilReadyToFire, iTimeUntilReadyToFire)
                                if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iTimeUntilReadyToFire='..iTimeUntilReadyToFire..'; oUnit[AiBotUnitInfo.refiTimeBetweenIFShots]='..oUnit[AiBotUnitInfo.refiTimeBetweenIFShots]..'; oUnit[AiBotUnitInfo.refiLastWeaponEvent]='..(oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 'nil')..'; Cur time='..GetGameTimeSeconds()) end
                            end
                            local iAverageTimeUntilReadyToFire = iTotalTimeUntilReadyToFire / iMMLWithTargets
                            local iMMLWithin1OfAverage = 0
                            for iEntry, iTime in tiTimeUntilReadyToFire do
                                if math.abs(iTime - iAverageTimeUntilReadyToFire) < 1 then
                                    iMMLWithin1OfAverage = iMMLWithin1OfAverage + 1
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iMMLJustFiredOrReadyToFire='..iMMLJustFiredOrReadyToFire..'; iMMLNotFiredForAges='..iMMLNotFiredForAges..'; iMMLWithTargets='..iMMLWithTargets..'; iMMLReloading='..iMMLReloading..'; iMMLWithin1OfAverage='..iMMLWithin1OfAverage..'; iAverageTimeUntilReadyToFire='..iAverageTimeUntilReadyToFire..'; iMaxTimeUntilReady='..iMaxTimeUntilReady..'; iMinTimeUntilReady='..iMinTimeUntilReady) end
                            if iMMLJustFiredOrReadyToFire + iMMLNotFiredForAges >= iMMLWithTargets * 0.75 or iMMLNotFiredForAges >= iMMLWithTargets * 0.25 or iMMLWithin1OfAverage >= iMMLWithTargets * 0.8 or (iMaxTimeUntilReady - iMinTimeUntilReady) <= 1.4 then
                                --Dont want to synchronise as either already synchronised or have lots of MML that havent fired in a while
                                if bDebugMessages == true then LOG(sFunctionRef..': Will enable all MML weapons') end
                                for iUnit, oUnit in tMMLWithNearbyTargets do
                                    AiBotUnitInfo.EnableUnitWeapon(oUnit) --In addition to separate logic that will enable, as want to enable asap once we decide we want to fire)
                                end
                            else
                                --Want to synchronise shots, disable the weapons (they shoudl be reenabled each cycle)
                                if bDebugMessages == true then LOG(sFunctionRef..': Will disable all MML weapons until they are better synchronised, time='..GetGameTimeSeconds()) end
                                for iUnit, oUnit in tMMLWithNearbyTargets do
                                    AiBotUnitInfo.DisableUnitWeapon(oUnit)
                                end
                            end
                        end
                    end
                end
            else
                --We dont have a nearest enemy to midpoint - if this is because we are ignoring low threat enemies, then send a small number of our available combat units to deal with them
                if not(bGivenCombatUnitsOrders) and bIgnoreEnemiesInThisZone and not(bConsiderEnemiesInAtLeastOneAdjacentZone) then
                    local oEnemyToFocusOn
                    local iClosestEnemyToFocusOn = 100000
                    local iCurEnemyToFocusOnDist
                    local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap) or (AiBotMap.rMapPotentialPlayableArea[3] <= AiBotMap.rMapPlayableArea[3] and AiBotMap.rMapPotentialPlayableArea[4] <= AiBotMap.rMapPlayableArea[4] and AiBotMap.rMapPotentialPlayableArea[1] >= AiBotMap.rMapPlayableArea[1] and AiBotMap.rMapPotentialPlayableArea[2] >= AiBotMap.rMapPlayableArea[2])

                    local iMaxThreatToAssign =(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 6 + (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 3
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                        for iEnemy, oEnemy in tLZTeamData[AiBotMap.subrefTEnemyUnits] do
                            iCurEnemyToFocusOnDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                            if iCurEnemyToFocusOnDist < iClosestEnemyToFocusOn and (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(oEnemy:GetPosition())) then
                                iClosestEnemyToFocusOn = iCurEnemyToFocusOnDist
                                oEnemyToFocusOn = oEnemy
                            end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            iMaxThreatToAssign = iMaxThreatToAssign + (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 6 + (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 3
                            if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                for iEnemy, oEnemy in tAdjLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                    if AiBotUnitInfo.IsUnitValid(oEnemy) then
                                        iCurEnemyToFocusOnDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                        if iCurEnemyToFocusOnDist < iClosestEnemyToFocusOn and (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(oEnemy:GetPosition())) then
                                            iClosestEnemyToFocusOn = iCurEnemyToFocusOnDist
                                            oEnemyToFocusOn = oEnemy
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if iMaxThreatToAssign > 0 then iMaxThreatToAssign = math.max(iMaxThreatToAssign, 60) end
                    --T2+ indirect fire units - focus on nearby enemy T2 arti if there is any
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                        for iCurUnit = table.getn(tAvailableCombatUnits), 1, -1 do
                            local oCurUnit = tAvailableCombatUnits[iCurUnit]
                            if (oCurUnit[AiBotUnitInfo.refiIndirectRange] or 0) >= 45 then
                                local oNearestT2Arti, iCurArtiDist
                                local iNearestT2Arti = 160 --Ignore T2 arti further away than this
                                for iT2Arti, oT2Arti in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
                                    iCurArtiDist = AiBotUtilities.GetDistanceBetweenPositions(oT2Arti:GetPosition(), oCurUnit:GetPosition())
                                    if iCurArtiDist <= iNearestT2Arti then
                                        iNearestT2Arti = iCurArtiDist
                                        oNearestT2Arti = oT2Arti
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Negligible enemy threat in this and adjacent zones but enemy has nearby t2 arti, oNearestT2Arti='..(oNearestT2Arti.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestT2Arti) or 'nil')..'; iNearestT2Arti='..iNearestT2Arti..'; IF unit='..oCurUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(iNearestT2Arti)..'; IF range='..(oCurUnit[AiBotUnitInfo.refiIndirectRange] or 0)) end
                                if oNearestT2Arti then
                                    if iNearestT2Arti <= (oCurUnit[AiBotUnitInfo.refiIndirectRange] or 0) + 5 then
                                        AiBotOrders.IssueTrackedGroundAttack(oCurUnit, oNearestT2Arti:GetPosition(), 0.5, false, 'NegT2ArtAG', false, oNearestT2Arti)
                                    else
                                        AiBotOrders.IssueTrackedAggressiveMove(oCurUnit, oNearestT2Arti:GetPosition(), 0.5, false, 'NegT2ArtAM', false)
                                    end
                                    table.remove(tAvailableCombatUnits, iCurUnit)
                                end
                            end
                        end
                    end

                    if oEnemyToFocusOn then
                        local iCurAssignedThreat = 0
                        for iCurUnit = table.getn(tAvailableCombatUnits), 1, -1 do
                            if tAvailableCombatUnits[iCurUnit][AiBotUnitInfo.refiUnitMassCost] <= iMaxThreatToAssign or ((tAvailableCombatUnits[iCurUnit][AiBotUnitInfo.refiDFRange] or 0) > 0 and (EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat - categories.EXPERIMENTAL, tAvailableCombatUnits[iCurUnit].UnitId) and AiBotUnitInfo.GetUnitLifetimeCount(tAvailableCombatUnits[iCurUnit]) > 3)) then
                                iCurAssignedThreat = iCurAssignedThreat + tAvailableCombatUnits[iCurUnit][AiBotUnitInfo.refiUnitMassCost]
                                --Issue where ythotha stuck not firing at mex, dist away was 4, so do a dist of 8 to be safe
                                if bDebugMessages == true then LOG(sFunctionRef..': dist to oEnemyToFocusOn='..AiBotUtilities.GetDistanceBetweenPositions(tAvailableCombatUnits[iCurUnit]:GetPosition(),oEnemyToFocusOn:GetPosition())) end
                                if AiBotUtilities.GetDistanceBetweenPositions(tAvailableCombatUnits[iCurUnit]:GetPosition(),oEnemyToFocusOn:GetPosition()) <= 8 and (not(tAvailableCombatUnits[iCurUnit][AiBotUnitInfo.refbLastShotBlocked]) or GetGameTimeSeconds() - (tAvailableCombatUnits[iCurUnit][AiBotUnitInfo.refiLastWeaponEvent] or 0) > math.max(2, (tAvailableCombatUnits[iCurUnit][AiBotUnitInfo.refiTimeBetweenDFShots] or 2))) then
                                    AiBotOrders.IssueTrackedAggressiveMove(tAvailableCombatUnits[iCurUnit], oEnemyToFocusOn:GetPosition(), 5, false, 'NegMZAM'..iLandZone, false)
                                else
                                    AiBotOrders.IssueTrackedMove(tAvailableCombatUnits[iCurUnit], oEnemyToFocusOn:GetPosition(), 5, false, 'NegMZAC'..iLandZone, false)
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Assigned available combat unit '..tAvailableCombatUnits[iCurUnit].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tAvailableCombatUnits[iCurUnit])..' to deal with threats in this and adjacent zones, iCurAssignedThreat='..iCurAssignedThreat..'; iMaxThreatToAssign='..iMaxThreatToAssign..'; oEnemyToFocusOn='..oEnemyToFocusOn.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToFocusOn)) end
                                table.remove(tAvailableCombatUnits, iCurUnit)
                                if iCurAssignedThreat >= iMaxThreatToAssign then break end
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to run from firebase or long range enemy threat, bRunFromFirebase='..tostring(bRunFromFirebase)..'; Nearby enemy long range threat='..(tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0)..'; Zone combat total='..(tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)..'; iAvailableCombatUnitThreat='..iAvailableCombatUnitThreat..'; bGivenCombatUnitsOrders='..tostring(bGivenCombatUnitsOrders)) end
    if not(bGivenCombatUnitsOrders) and AiBotUtilities.IsTableEmpty(tAvailableCombatUnits) == false then
        if (not(bSuicideIntoFatboyOrACU) or not(oClosestFatboyOrACUInIslandToSuicideInto)) and (bRunFromFirebase or bRunFromEnemyAir or ((tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > math.max(100, tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]) and tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > iAvailableCombatUnitThreat * 2 and not(bIgnoreEnemiesInThisZone and not(bConsiderEnemiesInAtLeastOneAdjacentZone))))) then
            local bConsiderAttackMoveIfClose = false
            local bContinue
            local iLongRangeAlliedThreshold = 50 --units with a combat range of at least this should still consider being aggressive
            local toEnemiesWithSimilarCombatRange = {}
            local toShorterRangeEnemies = {}
            local iDistUntilInRangeOfEnemyToConsiderAttacking
            local iCurDistUntilEnemyInRange, iCurDist
            local iMobileAdjust = 15 --Mobile units are assumed to be this much closer
            local toAdjacentEnemyMexes
            if tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange] >= 50 then
                local iNearbyEnemyRangeThreshold = 44
                function UpdateForLongerRangeEnemiesInZone(tCurLZTeamData, bUpdateShorterRangeEnemies)
                    if bUpdateShorterRangeEnemies or tCurLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] > iNearbyEnemyRangeThreshold or tCurLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] > iNearbyEnemyRangeThreshold or tCurLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] > iNearbyEnemyRangeThreshold then
                        for iUnit, oUnit in tCurLZTeamData[AiBotMap.subrefTEnemyUnits] do
                            if not(oUnit.Dead) then
                                if oUnit[AiBotUnitInfo.refiCombatRange] >= iNearbyEnemyRangeThreshold then
                                    table.insert(toEnemiesWithSimilarCombatRange, oUnit)
                                elseif bUpdateShorterRangeEnemies and (oUnit[AiBotUnitInfo.refiCombatRange] or 0) >= 6 then
                                    table.insert(toShorterRangeEnemies, oUnit)
                                end
                            end
                        end
                    end
                end
                UpdateForLongerRangeEnemiesInZone(tLZTeamData, true)
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                    for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                        UpdateForLongerRangeEnemiesInZone(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
                    end
                end
                --Also include long rnage threats
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false then
                    for iUnit, oUnit in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
                        table.insert(toEnemiesWithSimilarCombatRange, oUnit)
                    end
                end
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeIFThreats]) == false then
                    for iUnit, oUnit in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeIFThreats] do
                        table.insert(toEnemiesWithSimilarCombatRange, oUnit)
                    end
                end
                toAdjacentEnemyMexes = GetMexesInThisOrAdjacentLandZone(tLZData, tLZTeamData, iTeam, iPlateau) --only includes mexes in this zone and adjcaent if we have intel of them (so that we know we can hit them from far away)
            end

            if AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, tLZData[AiBotMap.subrefMidpoint]) <= 30 then bConsiderAttackMoveIfClose = true end
            for iUnit, oUnit in tAvailableCombatUnits do --Only retreat units from this LZ
                if oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone then
                    --Experimental units who are in range of an enemy experimental unit - dont retreat
                    bContinue = true
                    if (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 10000 then
                        if bDebugMessages == true then LOG(sFunctionRef..': About to check for manual attack target, oNearestEnemyToFriendlyBase='..(oNearestEnemyToFriendlyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase) or 'nil')) end
                        if not(oNearestEnemyToFriendlyBase) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                            oNearestEnemyToFriendlyBase = AiBotUtilities.GetNearestUnit(tLZTeamData[AiBotMap.reftoNearestDFEnemies], oUnit:GetPosition(), false, nil)
                        end
                        if oNearestEnemyToFriendlyBase then
                            local oTargetToManuallyAttack, bMoveNotManualAttack = GetManualAttackTargetIfWantManualAttack(oUnit)
                            if bDebugMessages == true then LOG(sFunctionRef..': Dealing with an experimental unit, will see if we want to do manual attack isntead of retreating, oTargetToManuallyAttack='..(oTargetToManuallyAttack.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTargetToManuallyAttack) or 'nil')..'; Target combaty range='..(oTargetToManuallyAttack[AiBotUnitInfo.refiCombatRange] or 'nil')..'; Our combat range='..(oUnit[AiBotUnitInfo.refiCombatRange] or 'nil')) end
                            if oTargetToManuallyAttack and (not(oUnit[AiBotUnitInfo.refbCanKite]) or (oTargetToManuallyAttack[AiBotUnitInfo.refiCombatRange] or 0) >= (oUnit[AiBotUnitInfo.refiCombatRange] or 0)) then
                                bContinue = false
                                if bMoveNotManualAttack then
                                    AiBotOrders.IssueTrackedMove(oUnit, oTargetToManuallyAttack:GetPosition(), 3, false, 'ExpRetrSuicM')
                                else
                                    AiBotOrders.IssueTrackedAttack(oUnit, oTargetToManuallyAttack, false, 'ExpRetrSuicA')
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering relevance of longer ranged logic to attack nearest enemy instead of treating, unit combat range='..oUnit[AiBotUnitInfo.refiCombatRange]..'; Is oNearestEnemyToFriendlyBase nil='..tostring(oNearestEnemyToFriendlyBase == nil)..'; Time since last weapon event='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; Time between DF shots='..( oUnit[AiBotUnitInfo.refiTimeBetweenDFShots] or 'nil')..'; Time between IF shots='..(oUnit[AiBotUnitInfo.refiTimeBetweenIFShots] or 'nil')) end
                    if oUnit[AiBotUnitInfo.refiCombatRange] > iLongRangeAlliedThreshold and bContinue and (not(oUnit[AiBotUnitInfo.refiLastWeaponEvent]) or ((oUnit[AiBotUnitInfo.refiDFRange] or 0) > iLongRangeAlliedThreshold and GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiLastWeaponEvent] >= oUnit[AiBotUnitInfo.refiTimeBetweenDFShots] * 0.7) or ((oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > iLongRangeAlliedThreshold and GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiLastWeaponEvent] >= oUnit[AiBotUnitInfo.refiTimeBetweenIFShots] * 0.7)) then
                        --Determine nearest enemy to friendly base if havent already
                        if not(oNearestEnemyToFriendlyBase) then
                            local iClosestDistToFriendlyBase = 1000
                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                for iEnemy, oEnemy in tLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                    if iCurDist < iClosestDistToFriendlyBase then
                                        oNearestEnemyToFriendlyBase = oEnemy
                                        iClosestDistToFriendlyBase = iCurDist
                                    end
                                end
                            elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                for iEnemy, oEnemy in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                    if iCurDist < iClosestDistToFriendlyBase then
                                        oNearestEnemyToFriendlyBase = oEnemy
                                        iClosestDistToFriendlyBase = iCurDist
                                    end
                                end
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Cant find nearby enemy, so strange we want to run') end
                            end
                        end
                        if oNearestEnemyToFriendlyBase then
                            --Long ranged units - if we think we can attack the nearest enemy to us without getting close to being in range of the enemy firebase or fatboy then also attack
                            --Check we have intel of nearest enemy, or if not that we are closer to an enemy mex than the nearest enemy
                            if bDebugMessages == true then LOG(sFunctionRef..': Checking to see if we outrange nearest enemy to ignore retreat order, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oNearestEnemyToFriendlyBase='..oNearestEnemyToFriendlyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase)) end
                            local bHaveVisibilityOfEnemy = AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oNearestEnemyToFriendlyBase)
                            local oEnemyToConsiderOverride
                            --Dont use closetoenemy check as are doing combatrange not df range
                            iDistUntilInRangeOfEnemyToConsiderAttacking = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyToFriendlyBase:GetPosition(), oUnit:GetPosition())

                            if not(bHaveVisibilityOfEnemy) and AiBotUtilities.IsTableEmpty(toAdjacentEnemyMexes) == false then
                                local iAdjustForMexDist = oUnit[AiBotUnitInfo.refiCombatRange] - oNearestEnemyToFriendlyBase[AiBotUnitInfo.refiCombatRange] - 5
                                for iMex, oMex in toAdjacentEnemyMexes do
                                    if AiBotUtilities.GetDistanceBetweenPositions(oMex:GetPosition(), oUnit:GetPosition()) + iAdjustForMexDist <= iDistUntilInRangeOfEnemyToConsiderAttacking then
                                        iAdjustForMexDist = 0
                                        oEnemyToConsiderOverride = oMex
                                        iDistUntilInRangeOfEnemyToConsiderAttacking = AiBotUtilities.GetDistanceBetweenPositions(oMex:GetPosition(), oUnit:GetPosition())
                                        bHaveVisibilityOfEnemy = true
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': bHaveVisibilityOfEnemy='..tostring(bHaveVisibilityOfEnemy or false)..'; oEnemyToConsiderOverride='..(oEnemyToConsiderOverride.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToConsiderOverride) or 'nil')) end
                            if bHaveVisibilityOfEnemy then
                                iDistUntilInRangeOfEnemyToConsiderAttacking = iDistUntilInRangeOfEnemyToConsiderAttacking - oUnit[AiBotUnitInfo.refiCombatRange]
                                if bDebugMessages == true then LOG(sFunctionRef..': iDistUntilInRangeOfEnemyToConsiderAttacking='..iDistUntilInRangeOfEnemyToConsiderAttacking) end
                                if iDistUntilInRangeOfEnemyToConsiderAttacking > -3 then
                                    --We arent in range of an enemy that we outrange yet, so check who the closest enemy is, and if htey will get in range of us before we get in range of the enemy to consider attacking
                                    local iDistUntilInRangeOfGoodRangedEnemyWithMobileAdjustment = 1000
                                    if AiBotUtilities.IsTableEmpty(toEnemiesWithSimilarCombatRange) == false then
                                        for iEnemy, oEnemy in toEnemiesWithSimilarCombatRange do
                                            iCurDistUntilEnemyInRange = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oEnemy[AiBotUnitInfo.refiCombatRange]
                                            if EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then iCurDistUntilEnemyInRange = iCurDistUntilEnemyInRange - iMobileAdjust end
                                            if iCurDistUntilEnemyInRange < iDistUntilInRangeOfGoodRangedEnemyWithMobileAdjustment then
                                                iDistUntilInRangeOfGoodRangedEnemyWithMobileAdjustment = iCurDistUntilEnemyInRange
                                                if iDistUntilInRangeOfGoodRangedEnemyWithMobileAdjustment < iDistUntilInRangeOfEnemyToConsiderAttacking then break end
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iDistUntilInRangeOfGoodRangedEnemyWithMobileAdjustment='..iDistUntilInRangeOfGoodRangedEnemyWithMobileAdjustment) end
                                    if iDistUntilInRangeOfGoodRangedEnemyWithMobileAdjustment > 4 and iDistUntilInRangeOfGoodRangedEnemyWithMobileAdjustment > iDistUntilInRangeOfEnemyToConsiderAttacking + 4 then
                                        --We arent in range of enemy combat units; Check if there are any enemy combat units that are close to being in our range
                                        local bInRangeOfShorterRangedEnemy = false
                                        if AiBotUtilities.IsTableEmpty(toShorterRangeEnemies) == false then
                                            for iEnemy, oEnemy in toShorterRangeEnemies do
                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition())
                                                iCurDistUntilEnemyInRange = iCurDist - oEnemy[AiBotUnitInfo.refiCombatRange]
                                                if iCurDistUntilEnemyInRange <= 12 then
                                                    bInRangeOfShorterRangedEnemy = true
                                                    break
                                                elseif iCurDist - oUnit[AiBotUnitInfo.refiCombatRange] < iDistUntilInRangeOfEnemyToConsiderAttacking then
                                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oEnemy.UnitId) or iCurDist - oUnit[AiBotUnitInfo.refiCombatRange] < iDistUntilInRangeOfEnemyToConsiderAttacking - 5 then
                                                        oEnemyToConsiderOverride = oEnemy
                                                        iDistUntilInRangeOfEnemyToConsiderAttacking = iCurDist - oUnit[AiBotUnitInfo.refiCombatRange]
                                                    end
                                                end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': bInRangeOfShorterRangedEnemy='..tostring(bInRangeOfShorterRangedEnemy or false)) end
                                        if not(bInRangeOfShorterRangedEnemy) then
                                            --We want to attack the nearest enemy
                                            bContinue = false
                                            if iDistUntilInRangeOfEnemyToConsiderAttacking <= 3 then
                                                AiBotOrders.IssueTrackedAttack(oUnit, (oEnemyToConsiderOverride or oNearestEnemyToFriendlyBase), false, 'RetrAtck', false)
                                            else
                                                AiBotOrders.IssueTrackedAggressiveMove(oUnit, (oEnemyToConsiderOverride or oNearestEnemyToFriendlyBase)[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], 5, false, 'RetrAtM', false)
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Normally woudl retreat but we want to try and attack the nearest enemy instead, iDistUntilInRangeOfEnemyToConsiderAttacking='..iDistUntilInRangeOfEnemyToConsiderAttacking..'; oEnemyToConsiderOverride='..(oEnemyToConsiderOverride.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToConsiderOverride) or 'nil')) end
                                        end
                                    end
                                end
                            end
                        end
                    end

                    --If we have recently been given a short range target, or are almost in range of the target, then we may have moved into this zone temporarily, in which case continue with attacking the target
                    if bDebugMessages == true then LOG(sFunctionRef..': is oUnit[refoSREnemyTarget] valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit[refoSREnemyTarget]))..'; refiTimeOfSREnemyTarget='..(oUnit[refiTimeOfSREnemyTarget] or 'nil')..'; unit df range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; time='..GetGameTimeSeconds()..'; bContinue='..tostring(bContinue)..'; oNearestEnemyToFriendlyBase='..(oNearestEnemyToFriendlyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyToFriendlyBase) or 'nil')) end
                    if bContinue then
                        if AiBotUnitInfo.IsUnitValid(oUnit[refoSREnemyTarget]) and oUnit[refiTimeOfSREnemyTarget] and not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId)) and not(oUnit[AiBotUnitInfo.refbScoutCombatOverride]) and (GetGameTimeSeconds() - oUnit[refiTimeOfSREnemyTarget] <= 20 or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[refoSREnemyTarget]:GetPosition()) <= (oUnit[AiBotUnitInfo.refiDFRange] or 0) + 10) then
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.refbLastShotBlocked]) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[refoSREnemyTarget]:GetPosition()) <= (oUnit[AiBotUnitInfo.refiDFRange] or 0) - 10 then
                                AiBotOrders.IssueTrackedAggressiveMove(oUnit, oUnit[refoSREnemyTarget]:GetPosition(), 6, false, 'SRHistAT'..iLandZone)
                            else
                                AiBotOrders.IssueTrackedMove(oUnit, oUnit[refoSREnemyTarget]:GetPosition(), 6, false, 'SRHistMT'..iLandZone)
                            end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                            if bConsiderAttackMoveIfClose and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tAmphibiousRallyPoint) <= 30 then
                                AiBotOrders.IssueTrackedAggressiveMove(oUnit, tAmphibiousRallyPoint, 6, false, 'AFBARetr'..iLandZone)
                            else
                                AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 6, false, 'AFBMRetr'..iLandZone)
                            end
                        else
                            if bConsiderAttackMoveIfClose and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint) <= 30 then
                                AiBotOrders.IssueTrackedAggressiveMove(oUnit, tRallyPoint, 6, false, 'FBARetr'..iLandZone)
                            else
                                AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 6, false, 'FBRetr'..iLandZone)
                            end
                        end
                    end
                else
                    --Clear unit assignment value so it is used by other zones
                    oUnit[refiCurrentAssignmentValue] = 0
                end
            end
        else --if not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) then --Done via separate if condition instead of else as we might set this to false if we couldnt find a nearest enemy in the above logic
            --Split units available to reinforce into DF and indirect fire units
            local tDFUnits = {}
            local tIndirectUnits = {}
            for iUnit, oUnit in tAvailableCombatUnits do
                if oUnit[AiBotUnitInfo.refiDFRange] > 0 then
                    table.insert(tDFUnits, oUnit)
                elseif oUnit[AiBotUnitInfo.refiIndirectRange] > 0 then
                    table.insert(tIndirectUnits, oUnit)
                else
                    AiBotUtilities.ErrorHandler('Combat unit with no DF or indirect range')
                end
            end

            --DF units - suicide into fatboy if was one
            if AiBotUtilities.IsTableEmpty(tDFUnits) == false and bSuicideIntoFatboyOrACU and oClosestFatboyOrACUInIslandToSuicideInto then
                RecordDFLandZoneTarget(tLZTeamData, iPlateau, iLandZone, iTeam, oClosestFatboyOrACUInIslandToSuicideInto[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2], AiBotMap.subrefiLZOrWZTAttackingUnit)
                for iUnit, oUnit in tDFUnits do
                    AiBotOrders.IssueTrackedMove(oUnit, oClosestFatboyOrACUInIslandToSuicideInto:GetPosition(), 6, false, 'LRFBSuic'..iLandZone)
                end
                tDFUnits = {}
            end

            --Indirect special 'bombardment' type logic against nearby different plateaus
            if AiBotUtilities.IsTableEmpty(tIndirectUnits) == false then
                if AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere]) then
                    local tOrderPosition = tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere]:GetPosition()
                    for iUnit, oUnit in tIndirectUnits do
                        --Note - issue on maps like air wars - the range factors in height so if the target plateau is very far away it can lead to strange results
                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOrderPosition) > oUnit[AiBotUnitInfo.refiIndirectRange] - 1 then
                            AiBotOrders.IssueTrackedAggressiveMove(oUnit, tOrderPosition, 3, false, 'InPlBom', false)
                        else
                            AiBotOrders.IssueTrackedGroundAttack(oUnit, tOrderPosition, 3, false, 'InPlAGBm', false, tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere])
                        end
                    end
                    tIndirectUnits = {}
                elseif tLZTeamData[AiBotMap.refbEnemiesInNearbyPlateau] and iFriendlyBestMobileIndirectRange > 0 then
                    --Check for mobile units within range
                    local oNearestEnemyMobileUnit = GetNearestEnemyInOtherPlateau(iPlateau, tLZData, iTeam)
                    if oNearestEnemyMobileUnit then
                        --Is this unit likely to be reachable by our best indirect fire range unit?
                        local tOrderPosition = oNearestEnemyMobileUnit:GetPosition()
                        local tPotentialFireFromPosition = AiBotUtilities.MoveInDirection(tOrderPosition, AiBotUtilities.GetAngleFromAToB(tOrderPosition, tLZData[AiBotMap.subrefMidpoint]), math.min(iFriendlyBestMobileIndirectRange, AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, tLZData[AiBotMap.subrefMidpoint])), true, false, true)
                        if bDebugMessages == true then LOG(sFunctionRef..': Have enemy unit in nearby plateau, oNearestEnemyMobileUnit='..oNearestEnemyMobileUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyMobileUnit)..'; iOurBestIndirectRange='..iFriendlyBestMobileIndirectRange..'; tPotentialFireFromPosition='..repru(tPotentialFireFromPosition)..'; Island ref='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tPotentialFireFromPosition) or 'nil')..'; This LZ island ref='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')) end
                        if AiBotUtilities.IsTableEmpty(tPotentialFireFromPosition) == false and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tPotentialFireFromPosition) == (tLZData[AiBotMap.subrefLZIslandRef] or NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZData[AiBotMap.subrefMidpoint])) then

                            for iUnit, oUnit in tIndirectUnits do
                                --Note - issue on maps like air wars - the range factors in height so if the target plateau is very far away it can lead to strange results
                                AiBotOrders.IssueTrackedAggressiveMove(oUnit, tOrderPosition, 3, false, 'InPlMBom', false)
                            end
                            tIndirectUnits = {}
                        end
                    end
                end
            end


            --Do we have adjacent zones wanting reinforcements?
            local iIndirectLZToSupport
            local iDFLZToSupport
            local tbUnpathableLZ
            local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)
            if not(bDontCheckPlayableArea) then tbUnpathableLZ = {} end
            --if AiBotUtilities.IsTableEmpty(tDFUnits) then iDFLZToSupport = -1 end --set to -1 so not nil so we can ignore checking the threat for indirect/direct respectively
            --(dont set the DFLZ to -1 yet, as we want to support a zone wanting DF units iwth indirect if we have spare indirect
            if AiBotUtilities.IsTableEmpty(tIndirectUnits) then iIndirectLZToSupport = -1 end

            if bDebugMessages == true then LOG(sFunctionRef..': Dont have any enemy units in this LZ or adjacent LZ, so will consider supporting other land zones, is tDFUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tDFUnits))..'; Is adjacent LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]))..'; subrefiNearbyEnemyLongRangeDFThreat='..tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]) end
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                --If have T2 arti nearby then adjust iIndirectLZToSupport for the closest zone which has units flagging they had shots intercepted, if closer to the firebase than this zone
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false or oNearestFirebaseUnit then
                    if not(oNearestFirebaseUnit) then
                        local iClosestUnit = 10000
                        local iCurDist
                        for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
                            if AiBotUnitInfo.IsUnitValid(oUnit) then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                if iCurDist < iClosestUnit then
                                    iClosestUnit = iCurDist
                                    oNearestFirebaseUnit = oUnit
                                end
                            end
                        end
                        if oNearestFirebaseUnit then
                            if iClosestUnit >= 10000 then iClosestUnit = AiBotUtilities.GetDistanceBetweenPositions(oNearestFirebaseUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) end
                            local iClosestZoneWithNoMMLIntercepts
                            local iClosestZoneWithMMLIntercepts
                            local iDistOfClosestNoMMLIntercept = iClosestUnit - 10 --no point moving to an adjacent zone unless it is noticeably closer to the firebase than this zone
                            local iDistOfClosestWithMMLIntercept = iClosestUnit - 10 --no point moving to an adjacent zone unless it is noticeably closer to the firebase than this zone
                            for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                if not(AiBotOverseer.bPacifistModeActive) or not(AiBotConditions.IsZoneAPacifistZone(iPlateau, iAdjLZ)) then
                                    local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oNearestFirebaseUnit:GetPosition(), tAdjLZData[AiBotMap.subrefMidpoint])
                                    if iCurDist <= iDistOfClosestNoMMLIntercept or iCurDist <= iDistOfClosestWithMMLIntercept then
                                        local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                        if GetGameTimeSeconds() - (tAdjLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -100) <= 30 then
                                            iDistOfClosestWithMMLIntercept = iCurDist
                                            iClosestZoneWithMMLIntercepts = iAdjLZ
                                        elseif iCurDist <= iDistOfClosestNoMMLIntercept and tLZTeamData[AiBotMap.subrefbLZWantsIndirectSupport] then
                                            iDistOfClosestNoMMLIntercept = iCurDist
                                            iClosestZoneWithNoMMLIntercepts = iAdjLZ
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': IF support will prioritise zones nearer to the enemy firebase or t2 arti, iClosestUnit='..iClosestUnit..'; iClosestZoneWithMMLIntercepts='..(iClosestZoneWithMMLIntercepts or 'nil')..'; iClosestZoneWithNoMMLIntercepts='..(iClosestZoneWithNoMMLIntercepts or 'nil')..'; iDistOfClosestWithMMLIntercept='..iDistOfClosestWithMMLIntercept..'; iDistOfClosestNoMMLIntercept='..iDistOfClosestNoMMLIntercept) end
                            if iClosestZoneWithMMLIntercepts then iIndirectLZToSupport = iClosestZoneWithMMLIntercepts
                            elseif iClosestZoneWithNoMMLIntercepts then iIndirectLZToSupport = iClosestZoneWithNoMMLIntercepts  end
                        end
                    end
                end

                local iEnemyStructureThresholdForNegligibleEnemies
                if bIgnoreEnemiesInThisZone and not(bConsiderEnemiesInAtLeastOneAdjacentZone) then
                    iEnemyStructureThresholdForNegligibleEnemies = math.min(1500, AiBotUnitInfo.GetMassCostOfUnits(tIndirectUnits) * 0.1)
                end
                for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether iLandZone '..iLandZone..' wants to support adjacent LZ iAdjLZ='..iAdjLZ..'; Does it want DF support='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsDFSupport])..'; Does it want indirect support='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsIndirectSupport])..'; tbAdjacentZoneEnemiesToIgnoreByZone[iAdjLZ]='..tostring(tbAdjacentZoneEnemiesToIgnoreByZone[iAdjLZ] or false)) end
                    if (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefMidpoint])) then
                        if not(AiBotOverseer.bPacifistModeActive) or not(AiBotConditions.IsZoneAPacifistZone(iPlateau, iAdjLZ)) then
                            if not(iIndirectLZToSupport) and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsIndirectSupport] then
                                if tbAdjacentZoneEnemiesToIgnoreByZone[iAdjLZ] and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefThreatEnemyStructureTotalMass] < iEnemyStructureThresholdForNegligibleEnemies then
                                    --Do nothing - dont want to support as we shouldve already sent units to deal with any enemies as part of above logic
                                else
                                    iIndirectLZToSupport = iAdjLZ
                                    if iDFLZToSupport or AiBotUtilities.IsTableEmpty(tDFUnits) then break end
                                end
                            end
                            if not(iDFLZToSupport) and (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsDFSupport]) then
                                if tbAdjacentZoneEnemiesToIgnoreByZone[iAdjLZ] then
                                    --Do nothing - dont want to support as we shouldve already sent units to deal with any enemies as part of above logic
                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to ignore this zone as shouldve already sent enough units to deal with the threat') end
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': iAdjLZ '..iAdjLZ..' wants DF support so will support here') end
                                    iDFLZToSupport = iAdjLZ
                                    if  iIndirectLZToSupport then break end
                                end
                            end
                        else
                            tbUnpathableLZ[iAdjLZ] = true
                        end
                    else
                        tbUnpathableLZ[iAdjLZ] = true
                    end
                end
            end

            if iIndirectLZToSupport and not(iDFLZToSupport) and AiBotUtilities.IsTableEmpty(tDFUnits) then iDFLZToSupport = -1 end
            if bDebugMessages == true then LOG(sFunctionRef..': iDFLZToSupport after initial check='..(iDFLZToSupport or 'nil')..'; iIndirectLZToSupport after initial check='..(iIndirectLZToSupport or 'nil')) end
            local tAmphibiousDFUnits --used later when looking for islands to support, and hten much later for redundancy
            local bHaveAmphibious --nil if we havent checked yet
            if not(iIndirectLZToSupport) or not(iDFLZToSupport) then
                --Are there any further away LZs on this plateau that want support?
                local iClosestLZDFDist = 100000
                local iCurDist
                local iClosestLZIndirectDist = 100000
                local iClosestDFLZRef
                local iClosestIndirectLZRef
                local iMinEnemyValueToAttack = iAvailableCombatUnitThreat * 0.1
                local tiIndirectLZWithNegligibleEnemies = {}
                local tiDFLZWithNegligibleEnemies = {}

                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLandZonesWantingSupportByPlateau][iPlateau] then
                    local iIslandWanted = tLZData[AiBotMap.subrefLZIslandRef]
                    for iOtherLZ, bWantsSupport in AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLandZonesWantingSupportByPlateau][iPlateau] do
                        if bWantsSupport and not(iOtherLZ == iLandZone) and not(tbAdjacentZoneEnemiesToIgnoreByZone[iOtherLZ]) then
                            local tOtherLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ]
                            if (bDontCheckPlayableArea or (not(tbUnpathableLZ[iOtherLZ]) and AiBotConditions.IsLocationInPlayableArea(tOtherLZData[AiBotMap.subrefMidpoint]))) then
                                if iIslandWanted == tOtherLZData[AiBotMap.subrefLZIslandRef] then --If in dif island then want to leave for the amphibious logic later
                                    --Check we can actually path here taking into account travel path (we have already checked midpoint just above)
                                    if bDontCheckPlayableArea or (AiBotConditions.CanTravelToDestinationWithinMapBounds(tLZData[AiBotMap.subrefMidpoint], tOtherLZData[AiBotMap.subrefMidpoint], AiBotMap.refPathingTypeLand)) then
                                        --Check not negligible value
                                        if (tOtherLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) + (tOtherLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= iMinEnemyValueToAttack then
                                            if not(iDFLZToSupport) and tOtherLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsDFSupport] then
                                                --Redundancy - if we cant path using land units then treat distance as 10k + straight line distance, so we prioritise locations that are land pathable (although ideally wouldnt have any such zones anyway?)
                                                iCurDist = (AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iLandZone, iOtherLZ) or 10000) --AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ][AiBotMap.subrefMidpoint])
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to support iOtherLZ '..iOtherLZ..'; iCurDist='..iCurDist..'; iClosestLZDFDist='..iClosestLZDFDist..'; straight line dist from our start='..AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.reftClosestFriendlyBase], AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ][AiBotMap.subrefMidpoint])) end
                                                if iCurDist >= 10000 and iCurDist < iClosestLZDFDist then iCurDist = iCurDist + AiBotUtilities.GetDistanceBetweenPositions(tOtherLZData[AiBotMap.subrefMidpoint], tLZData[AiBotMap.subrefMidpoint]) end
                                                if iCurDist and iCurDist < iClosestLZDFDist then
                                                    iClosestLZDFDist = iCurDist
                                                    iClosestDFLZRef = iOtherLZ
                                                end
                                                if not(iIndirectLZToSupport) and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsIndirectSupport] then
                                                    if iCurDist and iCurDist < iClosestLZIndirectDist then
                                                        iClosestLZIndirectDist = iCurDist
                                                        iClosestIndirectLZRef = iOtherLZ
                                                    end
                                                end
                                            elseif not(iIndirectLZToSupport) and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsIndirectSupport] then
                                                iCurDist = AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iLandZone, iOtherLZ) --AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ][AiBotMap.subrefMidpoint])
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to support witih indirect iOtherLZ '..iOtherLZ..'; iLandZone='..iLandZone..'; iCurDist='..repru(iCurDist)..'; iClosestLZIndirectDist='..repru(iClosestLZIndirectDist)..'; straight line dist from our start='..AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.reftClosestFriendlyBase], AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ][AiBotMap.subrefMidpoint])) end
                                                if iCurDist and iCurDist < iClosestLZIndirectDist then
                                                    iClosestLZIndirectDist = iCurDist
                                                    iClosestIndirectLZRef = iOtherLZ
                                                end
                                            end
                                        else
                                            if not(iDFLZToSupport) and tOtherLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsDFSupport] then
                                                table.insert(tiDFLZWithNegligibleEnemies, iOtherLZ)
                                            end
                                            if not(iIndirectLZToSupport) and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsIndirectSupport] then
                                                table.insert(tiIndirectLZWithNegligibleEnemies, iOtherLZ)
                                            end

                                        end
                                    else
                                        if bDebugMessages == true then LOG(sFunctionRef..': Cant actually path to the zone taking into account travel path') end
                                        tbUnpathableLZ[iOtherLZ] = true
                                    end
                                end
                            else
                                tbUnpathableLZ[iOtherLZ] = true
                            end
                        end
                    end
                end

                if not(iDFLZToSupport) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have no DFLZToSupport, so will set it to iClosestDFLZRef in case that isnt nil, iClosestDFLZRef='..(iClosestDFLZRef or 'nil')) end
                    iDFLZToSupport = iClosestDFLZRef
                end

                --If we have any negligible zones, then send some units to these first and remove them from the table of DF or IF units
                if AiBotUtilities.IsTableEmpty(tiDFLZWithNegligibleEnemies) == false and AiBotUtilities.IsTableEmpty(tDFUnits) == false then
                    --Cycle through each zone and assign DF units
                    local iMaxThreatToAssign, iCurAssignedThreat, iMaxExistingAssignedDFThreatToConsider
                    for iEntry, iOtherLZ in tiDFLZWithNegligibleEnemies do
                        --Calc threat to assign
                        local tOtherLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ]
                        local tOtherLZTeamData = tOtherLZData[AiBotMap.subrefLZTeamData][iTeam]
                        iCurAssignedThreat = 0
                        iMaxThreatToAssign = ((tOtherLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 6 + (tOtherLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0)) * 3
                        iMaxExistingAssignedDFThreatToConsider = math.max(iMaxThreatToAssign * 2, 1300)
                        --First assign any units last assigned to this zone
                        for iCurDFUnit = table.getn(tDFUnits), 1, -1 do
                            if tDFUnits[iCurDFUnit][refiLastNegLZAssignment] == iOtherLZ and tDFUnits[iCurDFUnit][AiBotUnitInfo.refiUnitMassCost] < iMaxExistingAssignedDFThreatToConsider then
                                iCurAssignedThreat = iCurAssignedThreat + tDFUnits[iCurDFUnit][AiBotUnitInfo.refiUnitMassCost]
                                AiBotOrders.IssueTrackedMove(tDFUnits[iCurDFUnit], tOtherLZData[AiBotMap.subrefMidpoint], 5, false, 'NegZDFX'..iLandZone..'To'..iOtherLZ, false)
                                if bDebugMessages == true then LOG(sFunctionRef..': Already Assigned DF unit '..tDFUnits[iCurDFUnit].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tDFUnits[iCurDFUnit])..' to the negligible threat zone '..iOtherLZ..'; iCurAssignedThreat='..iCurAssignedThreat..'; iMaxThreatToAssign='..iMaxThreatToAssign) end
                                table.remove(tDFUnits, iCurDFUnit)
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iCurAssignedThreat='..iCurAssignedThreat..'; iMaxThreatToAssign='..iMaxThreatToAssign..'; iMaxExistingAssignedDFThreatToConsider='..iMaxExistingAssignedDFThreatToConsider) end
                        if iCurAssignedThreat < iMaxThreatToAssign then
                            for iCurDFUnit = table.getn(tDFUnits), 1, -1 do
                                if tDFUnits[iCurDFUnit][AiBotUnitInfo.refiUnitMassCost] < iMaxThreatToAssign or (EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat - categories.EXPERIMENTAL, tDFUnits[iCurDFUnit].UnitId) and AiBotUnitInfo.GetUnitLifetimeCount(tDFUnits[iCurDFUnit]) > 3) then
                                    iCurAssignedThreat = iCurAssignedThreat + tDFUnits[iCurDFUnit][AiBotUnitInfo.refiUnitMassCost]
                                    AiBotOrders.IssueTrackedMove(tDFUnits[iCurDFUnit], tOtherLZData[AiBotMap.subrefMidpoint], 5, false, 'NegZDFN'..iLandZone..'To'..iOtherLZ, false)
                                    tDFUnits[iCurDFUnit][refiLastNegLZAssignment] = iOtherLZ
                                    if bDebugMessages == true then LOG(sFunctionRef..': Assigned DF unit '..tDFUnits[iCurDFUnit].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tDFUnits[iCurDFUnit])..' to the negligible threat zone '..iOtherLZ..'; iCurAssignedThreat='..iCurAssignedThreat..'; iMaxThreatToAssign='..iMaxThreatToAssign) end
                                    table.remove(tDFUnits, iCurDFUnit)
                                    if iCurAssignedThreat >= iMaxThreatToAssign then break end
                                end
                            end
                        end
                    end
                end

                if AiBotUtilities.IsTableEmpty(tiIndirectLZWithNegligibleEnemies) == false and AiBotUtilities.IsTableEmpty(tIndirectUnits) == false then
                    --Cycle through each zone and assign DF units
                    local iMaxThreatToAssign, iCurAssignedThreat
                    local bOnlyIncludeStructureThreat = not(AiBotUtilities.IsTableEmpty(tDFUnits)) --if we still have DF units available then we have already assigned enough DF units to handle the zone by themselves
                    for iEntry, iOtherLZ in tiIndirectLZWithNegligibleEnemies do
                        --Calc threat to assign
                        local tOtherLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iOtherLZ]
                        local tOtherLZTeamData = tOtherLZData[AiBotMap.subrefLZTeamData][iTeam]
                        iCurAssignedThreat = 0
                        if bOnlyIncludeStructureThreat then
                            iMaxThreatToAssign = (tOtherLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) * 5
                        else
                            iMaxThreatToAssign = ((tOtherLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 2 + (tOtherLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0)) * 5
                        end
                        --First assign any units last assigned to this zone
                        for iCurUnit = table.getn(tIndirectUnits), 1, -1 do
                            if tIndirectUnits[iCurUnit][refiLastNegLZAssignment] == iOtherLZ then
                                iCurAssignedThreat = iCurAssignedThreat + tIndirectUnits[iCurUnit][AiBotUnitInfo.refiUnitMassCost]
                                AiBotOrders.IssueTrackedMove(tIndirectUnits[iCurUnit], tOtherLZData[AiBotMap.subrefMidpoint], 5, false, 'NegZIF'..iLandZone..'To'..iOtherLZ, false)
                                if bDebugMessages == true then LOG(sFunctionRef..': Already Assigned IF unit '..tIndirectUnits[iCurUnit].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tIndirectUnits[iCurUnit])..' to the negligible threat zone '..iOtherLZ..'; iCurAssignedThreat='..iCurAssignedThreat..'; iMaxThreatToAssign='..iMaxThreatToAssign) end
                                table.remove(tIndirectUnits, iCurUnit)
                            end
                        end
                        if iCurAssignedThreat < iMaxThreatToAssign then
                            for iCurUnit = table.getn(tIndirectUnits), 1, -1 do
                                if tIndirectUnits[iCurUnit][AiBotUnitInfo.refiUnitMassCost] < iMaxThreatToAssign then
                                    iCurAssignedThreat = iCurAssignedThreat + tIndirectUnits[iCurUnit][AiBotUnitInfo.refiUnitMassCost]
                                    AiBotOrders.IssueTrackedMove(tIndirectUnits[iCurUnit], tOtherLZData[AiBotMap.subrefMidpoint], 5, false, 'NegZIF'..iLandZone..'To'..iOtherLZ, false)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Assigned IF unit '..tIndirectUnits[iCurUnit].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tIndirectUnits[iCurUnit])..' to the negligible threat zone '..iOtherLZ..'; iCurAssignedThreat='..iCurAssignedThreat..'; iMaxThreatToAssign='..iMaxThreatToAssign) end
                                    tIndirectUnits[iCurUnit][refiLastNegLZAssignment] = iOtherLZ
                                    table.remove(tIndirectUnits, iCurUnit)
                                    if iCurAssignedThreat >= iMaxThreatToAssign then break end
                                end
                            end
                        end
                    end
                end


                --If still not found somewhere to support, check for nearby islands wanting support
                if bDebugMessages == true then LOG(sFunctionRef..': Checking for LZs to send DF units to support at time '..GetGameTimeSeconds()..' for LZ '..(iLandZone or 'nil')..' on island '..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..', pre island iDFLZToSupport='..(iDFLZToSupport or 'nil')..'; is pathing to other islands empty='..tostring(tLZData[AiBotMap.subrefLZPathingToOtherIslands] or false)) end
                if not(iDFLZToSupport) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]) == false and AiBotUtilities.IsTableEmpty(tDFUnits) == false then
                    --Do we have amphibious or hover units in our available units?
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of amphib combat empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAmphibiousCombat, tDFUnits)))) end
                    tAmphibiousDFUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAmphibiousCombat, tDFUnits)
                    bHaveAmphibious = not(AiBotUtilities.IsTableEmpty(tAmphibiousDFUnits))
                    if bHaveAmphibious then
                        local bConsiderAttackingEnemyBase = false
                        --If enemy has long range threat then consider sending experimentals to attack their base
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure]) == false then
                            local iAmphibiousCombatThreat = AiBotUnitInfo.GetCombatThreatRating(tAmphibiousDFUnits, false, false)
                            if bDebugMessages == true then LOG(sFunctionRef..': iAmphibiousCombatThreat='..iAmphibiousCombatThreat) end
                            if iAmphibiousCombatThreat >= 19000 then --Monkeylord is 20k
                                --Do we have at least as many land experimentals as the enemy? (otherwise we risk suiciding into their base)
                                local iEnemyExperimentalCount = 0
                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
                                    iEnemyExperimentalCount = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals])
                                end
                                if iEnemyExperimentalCount > 0 then
                                    local iFriendlyExperimentalCount = 0
                                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                        iFriendlyExperimentalCount = iFriendlyExperimentalCount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandExperimental)
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iFriendlyExperimentalCount='..iFriendlyExperimentalCount..'; iEnemyExperimentalCount='..iEnemyExperimentalCount) end
                                    if iFriendlyExperimentalCount > iEnemyExperimentalCount then
                                        bConsiderAttackingEnemyBase = true
                                    end
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy has no land experimentals so will attack') end
                                    bConsiderAttackingEnemyBase = true
                                end

                            end
                        end
                        local iDistanceThreshold
                        if bConsiderAttackingEnemyBase then
                            iDistanceThreshold = math.max(400, AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZData[AiBotMap.subrefMidpoint]) * 1.25)
                        else
                            iDistanceThreshold = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZData[AiBotMap.subrefMidpoint]) * 0.75
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': bConsiderAttackingEnemyBase='..tostring(bConsiderAttackingEnemyBase)..'; iDistanceThreshold='..iDistanceThreshold) end

                        for iEntry, tPathingData in tLZData[AiBotMap.subrefLZPathingToOtherIslands] do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering island '..tPathingData[AiBotMap.subrefIslandNumber]..'; tPathingData[AiBotMap.subrefIslandTravelDist]='..tPathingData[AiBotMap.subrefIslandTravelDist]..'; iDistanceThreshold='..iDistanceThreshold..'; Does LZ want support='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsSupport])..'; tPathingData[AiBotMap.subrefIslandClosestLZRef]='..tPathingData[AiBotMap.subrefIslandClosestLZRef]) end
                            if tPathingData[AiBotMap.subrefIslandTravelDist] > iDistanceThreshold then break end

                            if AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsSupport] then
                                if (bDontCheckPlayableArea or (not(tbUnpathableLZ[tPathingData[AiBotMap.subrefIslandClosestLZRef]]) and AiBotConditions.IsLocationInPlayableArea( AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefMidpoint]))) then
                                    iDFLZToSupport = tPathingData[AiBotMap.subrefIslandClosestLZRef]
                                    AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refbIslandBeachhead] = true
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will support the closeest LZ ref, iDFLZToSupport='..iDFLZToSupport) end
                                    break
                                end
                            end
                        end
                    end
                end

                if not(iIndirectLZToSupport) then
                    iIndirectLZToSupport = (iClosestIndirectLZRef or iDFLZToSupport)
                end
            end

            if iDFLZToSupport > 0 and AiBotUtilities.IsTableEmpty(tDFUnits) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Want to support LZ '..iDFLZToSupport..'; Will adjust DF to get via point if it is far away; midpoint of iDFToSupport='..repru(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iDFLZToSupport][AiBotMap.subrefMidpoint])..'; Midpoint of this LZ='..repru(tLZData[AiBotMap.subrefMidpoint])) end
                iDFLZToSupport = ReviseTargetLZIfFarAway(tLZData, iTeam, iPlateau, iLandZone, iDFLZToSupport, 2)
                RecordDFLandZoneTarget(tLZTeamData, iPlateau, iLandZone, iTeam, iDFLZToSupport, AiBotMap.subrefiLZOrWZTMovingToOtherZone)
                if bDebugMessages == true then LOG(sFunctionRef..': iDFLZToSupport after revising target for far away LZ='..iDFLZToSupport..'; Midpoint of this zone='..repru(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iDFLZToSupport][AiBotMap.subrefMidpoint])) end

                for iUnit, oUnit in tDFUnits do
                    --Remove assignment value if the unit isnt part of this zone
                    if not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                        oUnit[refiCurrentAssignmentValue] = 0
                    else
                        --Attack-move if very long range (unless negligible nearby enemy threat)
                        if (oUnit[AiBotUnitInfo.refiDFRange] >= 60 and (not(oUnit[AiBotUnitInfo.refbLastShotBlocked]) or oUnit[AiBotUnitInfo.refiDFRange] >= 130)) or (oUnit[AiBotUnitInfo.refiDFMinRange] or 0) >= 20 then
                            --jericho - workaround for attackmove not working
                            if not(oUnit.UnitId == 'xnl0403') or DontHaveJerichoAttackTarget(oUnit) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will send unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' towards iDFLZToSupport='..iDFLZToSupport..' (unless ignoring due to being stuck)') end
                                --______________________________________________________________________________________________HaveSignificantEnemyThreatWithinRange(tLZData, tLZTeamData, iPlateau, iTeam, iSearchDistance,                   tStartPoint, iEnemyMassTotalThreshold, iOptionalSearchCategory,                                                                                                                                                                                                                 tOptionalAdditionalUnits, bOnlyIncludeDFUnits, bIncludeEnemyCombatRange, iOptionalSpeedThreshold, iOptionalMinEnemyMassRequiredUnlessInRange)
                                if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= 10 and AiBotConditions.HaveSignificantEnemyThreatWithinRange(tLZData, tLZTeamData, iPlateau, iTeam, oUnit[AiBotUnitInfo.refiDFRange], oUnit:GetPosition(), 1500, AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryT2PlusPD + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryNavalSurface - categories.TECH1 + categories.COMMAND, tUnitsNearFatboyInFurtherAwayZones,    nil,        nil,                    oUnit:GetBlueprint().Physics.MaxSpeed, math.min(150, 0.05 * (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)))) then
                                    if not(IgnoreOrderDueToStuckUnit(oUnit)) then
                                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iDFLZToSupport][AiBotMap.subrefMidpoint], 6, false, 'DFAMvLZ'..iDFLZToSupport..';'..iLandZone)
                                    end
                                else
                                    --Negligible enemy threat so just move
                                    if not(IgnoreOrderDueToStuckUnit(oUnit)) then
                                        AiBotOrders.IssueTrackedMove(oUnit, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iDFLZToSupport][AiBotMap.subrefMidpoint], 6, false, 'DFXMvLZ'..iDFLZToSupport..';'..iLandZone)
                                    end
                                end
                            end
                        else
                            if not(IgnoreOrderDueToStuckUnit(oUnit)) then
                                if bDebugMessages == true then LOG('About to issue tracked moved to unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Special micro active='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) end
                                AiBotOrders.IssueTrackedMove(oUnit, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iDFLZToSupport][AiBotMap.subrefMidpoint], 6, false, 'DFMovLZ'..iDFLZToSupport..';'..iLandZone)
                            end
                        end
                    end
                end
                tDFUnits = nil
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Deciding where to send IF units, iIndirectLZToSupport='..(iIndirectLZToSupport or 'nil')..'; is table of IF units empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotUtilities.IsTableEmpty(tIndirectUnits)))) end
            if iIndirectLZToSupport > 0 and AiBotUtilities.IsTableEmpty(tIndirectUnits) == false then
                iIndirectLZToSupport = ReviseTargetLZIfFarAway(tLZData, iTeam, iPlateau, iLandZone, iIndirectLZToSupport, 2)
                --Attack-move if nearby enemy T2 arti (as had scenario where longer ranged IF unit moved towards enemy T2 arti when the arti was in its range)
                local bConsiderAttackMoveForNearbyUnits = not(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits])) or not(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]))
                local oLRUnitToAttackInstead
                local iLRRangeThreshold, iDistUntilInRangeOfClosestLREnemy, iCurDistUntilInRange
                if bConsiderAttackMoveForNearbyUnits then iLRRangeThreshold = 8 end

                function UpdateLongRangeUnitToAttackInstead(oUnit)
                    oLRUnitToAttackInstead = nil
                    if oUnit[AiBotUnitInfo.refiCombatRange] > 0 then --redundancy
                        iDistUntilInRangeOfClosestLREnemy = iLRRangeThreshold
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                            for iEnemy, oEnemy in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
                                iCurDistUntilInRange = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange]
                                if bDebugMessages == true then LOG(sFunctionRef..': dist until oUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is in range of oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'is iCurDistUntilInRange='..iCurDistUntilInRange) end
                                if  iCurDistUntilInRange < iDistUntilInRangeOfClosestLREnemy then
                                    iDistUntilInRangeOfClosestLREnemy = iCurDistUntilInRange
                                    oLRUnitToAttackInstead = oEnemy
                                end
                            end
                        end
                        if iDistUntilInRangeOfClosestLREnemy > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false then
                            for iEnemy, oEnemy in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
                                iCurDistUntilInRange = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange]
                                if bDebugMessages == true then LOG(sFunctionRef..': dist until oUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is in range of oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'is iCurDistUntilInRange='..iCurDistUntilInRange) end
                                if  iCurDistUntilInRange < iDistUntilInRangeOfClosestLREnemy then
                                    iDistUntilInRangeOfClosestLREnemy = iCurDistUntilInRange
                                    oLRUnitToAttackInstead = oEnemy
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': oLRUnitToAttackInstead after check='..(oLRUnitToAttackInstead.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oLRUnitToAttackInstead) or 'nil')) end
                end
                for iUnit, oUnit in tIndirectUnits do
                    if not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is in a different zone to this so will set its asisgnment value to 0 so it can be assigned by that zone') end
                        oUnit[refiCurrentAssignmentValue] = 0
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Do we want to ignore orders due to having a stuck unit? oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Ignore due to stuck unit='..tostring(IgnoreOrderDueToStuckUnit(oUnit) or false)) end
                        if not(IgnoreOrderDueToStuckUnit(oUnit)) then
                            if bConsiderAttackMoveForNearbyUnits then UpdateLongRangeUnitToAttackInstead(oUnit) end
                            if oLRUnitToAttackInstead then
                                AiBotOrders.IssueTrackedAggressiveMove(oUnit, oLRUnitToAttackInstead:GetPosition(), 6, false, 'IFMvAtLR'..iLandZone)
                            else
                                AiBotOrders.IssueTrackedMove(oUnit, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iIndirectLZToSupport][AiBotMap.subrefMidpoint], 6, false, 'IFMovLZ'..iIndirectLZToSupport..';'..iLandZone)
                            end
                        end
                    end
                end
                tIndirectUnits = nil
            end
            local tRemainingLandUnits = {}
            if AiBotUtilities.IsTableEmpty(tDFUnits) == false then
                for iUnit, oUnit in tDFUnits do
                    table.insert(tRemainingLandUnits, oUnit)
                end
            end
            if AiBotUtilities.IsTableEmpty(tIndirectUnits) == false then
                for iUnit, oUnit in tIndirectUnits do
                    table.insert(tRemainingLandUnits, oUnit)
                end
            end
            if AiBotUtilities.IsTableEmpty(tRemainingLandUnits) == false then
                --Search for a zone with enemy units and attack it, if there is one
                if bDebugMessages == true then LOG(sFunctionRef..': Searching for other zones with enemy units, is subrefLZPathingToOtherLandZones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]))) end
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                    local bDontCheckPathability = not(AiBotMap.bIsCampaignMap) or (AiBotMap.rMapPotentialPlayableArea[3] <= AiBotMap.rMapPlayableArea[3] and AiBotMap.rMapPotentialPlayableArea[4] <= AiBotMap.rMapPlayableArea[4] and AiBotMap.rMapPotentialPlayableArea[1] >= AiBotMap.rMapPlayableArea[1] and AiBotMap.rMapPotentialPlayableArea[2] >= AiBotMap.rMapPlayableArea[2])
                    if bDebugMessages and not(bDontCheckPathability) then
                        LOG(sFunctionRef..': LZData midpoint='..repru(tLZData[AiBotMap.subrefMidpoint])..'; IsLocationInPlayableArea='..tostring(AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]))..'; Island ref='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tLZData[AiBotMap.subrefMidpoint]) or 'nil')..'; Can travel from midpoint to first available combat unit='..tostring(AiBotConditions.CanTravelToDestinationWithinMapBounds(tLZData[AiBotMap.subrefMidpoint], tAvailableCombatUnits[1]:GetPosition()) or false, AiBotMap.refPathingTypeLand))
                        if not(AiBotConditions.CanTravelToDestinationWithinMapBounds(tLZData[AiBotMap.subrefMidpoint], tAvailableCombatUnits[1]:GetPosition(), AiBotMap.refPathingTypeLand)) then
                            AiBotConditions.CanTravelToDestinationWithinMapBounds(tLZData[AiBotMap.subrefMidpoint], tAvailableCombatUnits[1]:GetPosition(), AiBotMap.refPathingTypeLand, true)
                        end
                    end
                    for iEntry, tSubtable in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                        local tCurLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefLZNumber]]
                        if not(AiBotOverseer.bPacifistModeActive) or not(AiBotConditions.IsZoneAPacifistZone(iPlateau, tSubtable[AiBotMap.subrefLZNumber])) then
                            local tCurZoneTeamData =tCurLZData[AiBotMap.subrefLZTeamData][iTeam]
                            if AiBotUtilities.IsTableEmpty(tCurZoneTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering sending remaining land units to LZ='..tSubtable[AiBotMap.subrefLZNumber]..'; travel path in playable area='..tostring((AiBotConditions.IsLocationInPlayableArea(tCurLZData[AiBotMap.subrefMidpoint]) and AiBotConditions.CanTravelToDestinationWithinMapBounds(tLZData[AiBotMap.subrefMidpoint], tCurLZData[AiBotMap.subrefMidpoint], AiBotMap.refPathingTypeLand)))..'; tCurLZData[AiBotMap.subrefMidpoint]='..repru(tCurLZData[AiBotMap.subrefMidpoint])..'; rMapPlayableArea='..repru(AiBotMap.rMapPlayableArea)..'; Land pathing (island ref) of target LZ='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tCurLZData[AiBotMap.subrefMidpoint]) or 'nil')..'; Can first available combat unit travel to target midpoint='..tostring(AiBotConditions.CanTravelToDestinationWithinMapBounds(tAvailableCombatUnits[1]:GetPosition(), tCurLZData[AiBotMap.subrefMidpoint], AiBotMap.refPathingTypeLand) or false)) end
                                if bDontCheckPathability or (AiBotConditions.IsLocationInPlayableArea(tCurLZData[AiBotMap.subrefMidpoint]) and AiBotConditions.CanTravelToDestinationWithinMapBounds(tLZData[AiBotMap.subrefMidpoint], tCurLZData[AiBotMap.subrefMidpoint], AiBotMap.refPathingTypeLand)) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will record this zone as a target unless we have already recorded a zone to target, subreftiLandZoneTargetedByOurCombat='..(tLZTeamData[AiBotMap.subreftiLandZoneTargetedByOurCombat] or 'nil')) end
                                    if not(tLZTeamData[AiBotMap.subreftiLandZoneTargetedByOurCombat]) then --Only record if we havent already recorded above (or else we will end up overriding cur zone target); not sure if such a scenario could arise but best to be safe
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will record target LZ='..tSubtable[AiBotMap.subrefLZNumber]..' as a target') end
                                        RecordDFLandZoneTarget(tLZTeamData, iPlateau, iLandZone, iTeam, tSubtable[AiBotMap.subrefLZNumber], AiBotMap.subrefiLZOrWZTMovingToOtherZone)
                                    end
                                    for iUnit, oUnit in tRemainingLandUnits do
                                        if not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                                            oUnit[refiCurrentAssignmentValue] = 0
                                        else
                                            if bDebugMessages == true then LOG(sFunctionRef..'; Will send unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to target LZ '..tSubtable[AiBotMap.subrefLZNumber]..' unless unit is stuck') end
                                            if not(IgnoreOrderDueToStuckUnit(oUnit)) then
                                                AiBotOrders.IssueTrackedMove(oUnit, tCurLZData[AiBotMap.subrefMidpoint], 6, false, 'BkMvLZ'..tSubtable[AiBotMap.subrefLZNumber]..';'..iLandZone)
                                            end
                                        end
                                    end
                                    tRemainingLandUnits = nil
                                    break
                                else
                                    tbUnpathableLZ[tSubtable[AiBotMap.subrefLZNumber]] = true
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for other zones to target, is tRemainingLandUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tRemainingLandUnits))) end
            if AiBotUtilities.IsTableEmpty(tRemainingLandUnits) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Checking if can path to closest enemy base by land, Cur subrefLZIslandRef='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; ClosestEnemyBase land ref='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) or 'nil')..'; In playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tLZTeamData[AiBotMap.reftClosestEnemyBase]))) end
                if NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) == tLZData[AiBotMap.subrefLZIslandRef] then
                    if (bDontCheckPlayableArea or (AiBotConditions.IsLocationInPlayableArea(tLZTeamData[AiBotMap.reftClosestEnemyBase]) and not(tbUnpathableLZ[AiBotMap.GetLandZoneFromPosition(tLZTeamData[AiBotMap.reftClosestEnemyBase])]))) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will send all land units to closest enemy base') end
                        for iUnit, oUnit in tRemainingLandUnits do
                            if not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                                oUnit[refiCurrentAssignmentValue] = 0
                            else
                                if not(IgnoreOrderDueToStuckUnit(oUnit)) then
                                    AiBotOrders.IssueTrackedMove(oUnit, tLZTeamData[AiBotMap.reftClosestEnemyBase], 6, false, 'MTDEnB'..iLandZone)
                                end
                            end
                        end
                    end
                end
                if AiBotUtilities.IsTableEmpty(tRemainingLandUnits) == false then
                    --If have amphibious or hover combat units then look for WZs that want support - primarily for campaign where islands are outside playable area
                    if bHaveAmphibious == nil and AiBotUtilities.IsTableEmpty(AiBotMap.tPondDetails) == false then

                        if AiBotUtilities.IsTableEmpty(tDFUnits) == false then
                            tAmphibiousDFUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAmphibiousCombat, tDFUnits)
                        end
                        bHaveAmphibious = not(AiBotUtilities.IsTableEmpty(tAmphibiousDFUnits))
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': bHaveAmphibious='..tostring(bHaveAmphibious)..'; is table of ponds empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tPondDetails))) end
                    if bHaveAmphibious and AiBotUtilities.IsTableEmpty(AiBotMap.tPondDetails) == false then
                        --Cycle through every pond, and if plateau is the same then consider moving here
                        local iAmphibiousLabelWanted = NavUtils.GetLabel(AiBotMap.refPathingTypeAmphibious, tLZData[AiBotMap.subrefMidpoint])
                        if iAmphibiousLabelWanted then
                            --Get amphbious antinavy and hover DF units
                            local bHaveAntiNavy = false
                            local bHaveHover = false
                            for iUnit, oUnit in tAmphibiousDFUnits do
                                if not(bHaveAntiNavy) and (oUnit[AiBotUnitInfo.refiAntiNavyRange] or 0) > 0 then
                                    bHaveAntiNavy = true
                                    if bHaveHover then break end
                                end
                                if not(bHaveHover) and EntityCategoryContains(categories.HOVER, oUnit.UnitId) then
                                    bHaveHover = true
                                    if bHaveAntiNavy then break end
                                end
                            end

                            local iWZToSupport
                            local iClosestWZToSupport = 10000
                            local iCurWZDist
                            if bDebugMessages == true then LOG(sFunctionRef..': bHaveHover='..tostring(bHaveHover)..'; bHaveAntiNavy='..tostring(bHaveAntiNavy)) end
                            for iPond, tPondSubtable in AiBotMap.tPondDetails do
                                --Ignore really small ponds
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering iPond='..iPond..'; subrefiSegmentCount='..(tPondSubtable[AiBotMap.subrefiSegmentCount] or 'nil')..'; Pond amphibious midpoint label='..(NavUtils.GetLabel(AiBotMap.refPathingTypeAmphibious, tPondSubtable[AiBotMap.subrefPondMidpoint]) or 'nil')..'; iAmphibiousLabelWanted='..iAmphibiousLabelWanted) end
                                if tPondSubtable[AiBotMap.subrefiSegmentCount] >= 200 and NavUtils.GetLabel(AiBotMap.refPathingTypeAmphibious, tPondSubtable[AiBotMap.subrefPondMidpoint]) == iAmphibiousLabelWanted then
                                    --Is there a WZ in this pond wanting support?

                                    for iWZ, tWZData in tPondSubtable[AiBotMap.subrefPondWaterZones] do
                                        local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iWZ='..iWZ..'; subrefbWZWantsSupport='..tostring(tWZTeamData[AiBotMap.subrefbWZWantsSupport])..'; Is midpoint in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tWZData[AiBotMap.subrefMidpoint]))..'; bHaveAntiNavy='..tostring(bHaveAntiNavy)..'; bHaveHover='..tostring(bHaveAntiNavy)..'; Amphibious label='..(NavUtils.GetLabel(AiBotMap.refPathingTypeAmphibious, tWZData[AiBotMap.subrefMidpoint]) or 'nil')..'; iAmphibiousLabelWanted='..(iAmphibiousLabelWanted or 'nil')..'; subrefbWZOnlySubmersibleEnemies='..tostring(tWZTeamData[AiBotMap.subrefbWZOnlySubmersibleEnemies] or false)..'; subrefbWZOnlyHoverEnemies='..tostring(tWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies] or false)) end
                                        if tWZTeamData[AiBotMap.subrefbWZWantsSupport] and (bHaveAntiNavy or not(tWZTeamData[AiBotMap.subrefbWZOnlySubmersibleEnemies])) and (bHaveHover or not(tWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies])) and NavUtils.GetLabel(AiBotMap.refPathingTypeAmphibious, tWZData[AiBotMap.subrefMidpoint]) == iAmphibiousLabelWanted then
                                            --Check in playable area
                                            if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tWZData[AiBotMap.subrefMidpoint]) then
                                                if not(AiBotOverseer.bPacifistModeActive) or not(AiBotConditions.IsZoneAPacifistZone(0, iWZ)) then
                                                    iCurWZDist = AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], tLZData[AiBotMap.subrefMidpoint])
                                                    if bDebugMessages == true then
                                                        LOG(sFunctionRef..': iCurWZDist='..iCurWZDist..'; iClosestWZToSupport='..iClosestWZToSupport..'; CanTravelToDestinationWithinMapBounds='..tostring(AiBotConditions.CanTravelToDestinationWithinMapBounds(tLZData[AiBotMap.subrefMidpoint], tWZData[AiBotMap.subrefMidpoint], AiBotMap.refPathingTypeAmphibious) or false)..'; tLZData[AiBotMap.subrefMidpoint]='..repru(tLZData[AiBotMap.subrefMidpoint])..'; tWZData[AiBotMap.subrefMidpoint]='..repru(tWZData[AiBotMap.subrefMidpoint]))
                                                    end
                                                    if iCurWZDist < iClosestWZToSupport then
                                                        if bDontCheckPlayableArea or AiBotConditions.CanTravelToDestinationWithinMapBounds(tLZData[AiBotMap.subrefMidpoint], tWZData[AiBotMap.subrefMidpoint], AiBotMap.refPathingTypeAmphibious) then
                                                            iClosestWZToSupport = iCurWZDist
                                                            iWZToSupport = iWZ
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iWZToSupport after searching all ponds='..(iWZToSupport or 'nil')) end
                            if iWZToSupport then
                                local tTargetDestination = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWZToSupport]][AiBotMap.subrefPondWaterZones][iWZToSupport][AiBotMap.subrefMidpoint]
                                local tbAmphibiousDFByEntityID = {}
                                for iUnit, oUnit in tAmphibiousDFUnits do
                                    tbAmphibiousDFByEntityID[oUnit.EntityId] = true
                                    if not(oUnit[AiBotUnitInfo.refbTreatAmphibiousUnitAsSubmarine]) and (oUnit[AiBotUnitInfo.refiAntiNavyRange] or 0) > 0 then
                                        oUnit[AiBotUnitInfo.refbTreatAmphibiousUnitAsSubmarine] = true
                                        AiBotUtilities.DelayChangeVariable(oUnit, AiBotUnitInfo.refbTreatAmphibiousUnitAsSubmarine, false, 120)
                                    end
                                    if not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                                        oUnit[refiCurrentAssignmentValue] = 0
                                    else
                                        if not(IgnoreOrderDueToStuckUnit(oUnit)) then
                                            AiBotOrders.IssueTrackedMove(oUnit, tTargetDestination, 6, false, 'AmpFWZ'..iWZToSupport)
                                        end
                                    end
                                end
                                --Remove entries from remaining land units
                                for iCurUnit = table.getn(tRemainingLandUnits), 1, -1 do
                                    if tbAmphibiousDFByEntityID[tRemainingLandUnits[iCurUnit].EntityId] then
                                        table.remove(tRemainingLandUnits, iCurUnit)
                                    end
                                end
                            end
                        end
                    end

                    --Campaign specific - send to main enemy campaign base
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to send to campaign base, is tRemainingLandUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tRemainingLandUnits))..'; GetEnemyMainCampaignBase='..repru(AiBotUtilities.IsTableEmpty(AiBotTeam.GetEnemyMainCampaignBase(iTeam)))) end
                    if AiBotUtilities.IsTableEmpty(tRemainingLandUnits) == false then
                        if AiBotMap.bIsCampaignMap and AiBotUtilities.IsTableEmpty(AiBotTeam.GetEnemyMainCampaignBase(iTeam)) == false and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, AiBotTeam.GetEnemyMainCampaignBase(iTeam)) == iPlateau then
                            if NavUtils.GetLabel(AiBotMap.refPathingTypeLand, AiBotTeam.GetEnemyMainCampaignBase(iTeam)) == tLZData[AiBotMap.subrefLZIslandRef] then
                                for iUnit, oUnit in tRemainingLandUnits do
                                    if not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                                        oUnit[refiCurrentAssignmentValue] = 0
                                    else
                                        if not(IgnoreOrderDueToStuckUnit(oUnit)) then
                                            AiBotOrders.IssueTrackedMove(oUnit, AiBotTeam.GetEnemyMainCampaignBase(iTeam), 6, false, 'CmpEnB'..iLandZone)
                                        end
                                    end
                                end
                            else
                                --Do we have any amphibious or hover units?
                                if bDebugMessages == true then LOG(sFunctionRef..': Will send any hover and amphibious units we have to the enemy base') end
                                local tbGivenIndexUnitOrder = {}
                                for iUnit, oUnit in tRemainingLandUnits do
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAmphibious + categories.HOVER, oUnit.UnitId) then
                                        if not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                                            oUnit[refiCurrentAssignmentValue] = 0
                                        else
                                            tbGivenIndexUnitOrder[iUnit] = true
                                            if not(IgnoreOrderDueToStuckUnit(oUnit)) then
                                                AiBotOrders.IssueTrackedMove(oUnit, AiBotTeam.GetEnemyMainCampaignBase(iTeam), 6, false, 'CmpHEnB'..iLandZone)
                                            end
                                        end
                                    end
                                end
                                if AiBotUtilities.IsTableEmpty(tbGivenIndexUnitOrder) == false then
                                    for iCurUnit = table.getn(tRemainingLandUnits), 1, -1 do
                                        if tbGivenIndexUnitOrder[iCurUnit] then table.remove(tRemainingLandUnits, iCurUnit) end
                                    end
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tRemainingLandUnits) == false then
                            --Cant go to enemy base, so just follow land scouting path
                            if bDebugMessages == true then LOG(sFunctionRef..': Follow land scouting path if we have one, is patrol path empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subreftPatrolPath]))) end
                            if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subreftPatrolPath]) == false then
                                --Patrol the land zone
                                for iUnit, oUnit in tRemainingLandUnits do
                                    if not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                                        oUnit[refiCurrentAssignmentValue] = 0
                                    else
                                        AiBotOrders.PatrolPath(oUnit, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subreftPatrolPath], false, 'SP', false, true)
                                    end
                                end
                            else
                                --Do nothing
                            end
                            --Consider ctrlking t1-T2 non-amphibious non-hover if have lots
                            if tRemainingLandUnits[1]:GetAIBrain()[AiBotOverseer.refbCloseToUnitCap] and not(tRemainingLandUnits[1]:GetAIBrain()[AiBotOverseer.refbRecentlyKilledIdleIslandUnit]) and table.getn(tRemainingLandUnits) >= 12 then
                                for iCurTech = 1, 2 do
                                    local toUnitsToKill = EntityCategoryFilterDown(AiBotUnitInfo.ConvertTechLevelToCategory(iCurTech) - AiBotUnitInfo.refCategoryAmphibious - categories.HOVER, tRemainingLandUnits)
                                    if AiBotUtilities.IsTableEmpty(toUnitsToKill) == false then
                                        tRemainingLandUnits[1]:GetAIBrain()[AiBotOverseer.refbRecentlyKilledIdleIslandUnit] = true
                                        AiBotUtilities.DelayChangeVariable(tRemainingLandUnits[1]:GetAIBrain(), AiBotOverseer.refbRecentlyKilledIdleIslandUnit, false, 5)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will kill unit rather than having it patrol due to unit cap, toUnitsToKill[1]='..toUnitsToKill[1].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(toUnitsToKill[1])..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; TIme='..GetGameTimeSeconds()) end
                                        AiBotOrders.IssueTrackedKillUnit(toUnitsToKill[1])
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': End of code for iLandZOne '..iLandZone..', bWantReinforcements='..tostring(bWantReinforcements)..'; bWantIndirectReinforcements='..tostring(bWantIndirectReinforcements)) end
    local bWantDFReinforcements = bWantReinforcements
    if bWantReinforcements then
        --Do we want to get indirect fire instead of direct fire as an override?
        if tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] >= 400 then
            local iEnemyStructureThreatTotal = 0
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                    iEnemyStructureThreatTotal = iEnemyStructureThreatTotal + iThreat
                end
            end
            if tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] < tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] * 1.3 then
                --We have enough DF threat, if we want more indirect threat then no longer flag as wanting DF support and instead flag that we want indirect support
                if iEnemyStructureThreatTotal * 1.4 > math.max(50, tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]) then
                    local iDFRatio = tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] / math.max(1, tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal])
                    local iIndirectRatio = math.max(50, tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]) / math.max(iEnemyStructureThreatTotal, 1)
                    if iIndirectRatio < iDFRatio then
                        if bDebugMessages == true then LOG(sFunctionRef..': Want more indirect units due to the ratio of indirect to DF units, iIndirectRatio='..iIndirectRatio..'; iDFRatio='..iDFRatio) end
                        bWantIndirectReinforcements = true
                        --Dont disable requesting DF reinforcements if we may be able to overwhelm with land experimentals
                        if tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] > 5000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will still request DF reinforcements as well though') end
                        else
                            bWantDFReinforcements = false
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished checking override for reinforcement type, bWantDFReinforcements='..tostring(bWantDFReinforcements)..'; bWantIndirectReinforcements='..tostring(bWantIndirectReinforcements)..'; iEnemyStructureThreatTotal='..iEnemyStructureThreatTotal..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]) end
        end
    end
    if not(bWantIndirectReinforcements) and GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -100) <= 30 then
        if bDebugMessages == true then LOG(sFunctionRef..': It has been '..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -100)..' since MML were firing near TMD so want more indirect fire so get more MML') end
        bWantIndirectReinforcements = true
    end
    if bWantDFReinforcements and not(bWantIndirectReinforcements) then
        --If we already have higher DF threat than enemy DF threat in this zone, then consider adjacent zones and whether we want some indirect fire threat here
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to change to requesting indirect units, tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]) end
        if tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] > tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] > tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] then
            local iNearbyEnemyMobileDFThreat = (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)
            local iNearbyEnemyStructureThreat = 0
            if tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                    iNearbyEnemyStructureThreat = iNearbyEnemyStructureThreat + iThreat
                end
            end
            local iNearbyAllyMobileDFThreat = (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0)
            local iNearbyAllyMobileIndirectThreat = (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] or 0)
            function UpdateForAdjacentLZ(tAdjLZTeamData)
                iNearbyEnemyMobileDFThreat = iNearbyEnemyMobileDFThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)
                if tAdjLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] > 0 and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
                    for iRange, iThreat in tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                        iNearbyEnemyStructureThreat = iNearbyEnemyStructureThreat + iThreat
                    end
                end
                iNearbyAllyMobileDFThreat = iNearbyAllyMobileDFThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0)
                iNearbyAllyMobileIndirectThreat = iNearbyAllyMobileIndirectThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] or 0)
            end
            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                UpdateForAdjacentLZ(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
            end
            if tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] then
                for iEntry, tPlateauAndZone in tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] do
                    UpdateForAdjacentLZ(AiBotMap.tAllPlateaus[tPlateauAndZone[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndZone[2]][AiBotMap.subrefLZTeamData][iTeam])
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': iNearbyEnemyMobileDFThreat='..iNearbyEnemyMobileDFThreat..'; iNearbyEnemyStructureThreat='..iNearbyEnemyStructureThreat..'; iNearbyAllyMobileDFThreat='..iNearbyAllyMobileDFThreat..'; iNearbyAllyMobileIndirectThreat='..iNearbyAllyMobileIndirectThreat) end
            if iNearbyEnemyMobileDFThreat < iNearbyAllyMobileDFThreat and iNearbyAllyMobileIndirectThreat < iNearbyEnemyStructureThreat then
                bWantIndirectReinforcements = true
            end
        end
    end

    --Enemy structure in nearby plateau that we can probably reach

    if bDebugMessages == true then LOG(sFunctionRef..': Checking if want to request indirect reinforcements for dif plateau threat, iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; enemies in this or adjacent='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; bWantIndirectReinforcements='..tostring(bWantIndirectReinforcements)..'; Valid structure in other plateau='..tostring(tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere])..'; Highest friendly land fac tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]) end
    if not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and not(bWantIndirectReinforcements) and AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 3 then
        bWantIndirectReinforcements = AiBotConditions.IsNearbyStructureThatWeCanReachWithIndirect(tLZData, tLZTeamData, iTeam)
    end
    if not(bWantIndirectReinforcements) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and (tLZTeamData[AiBotMap.subrefLZbCoreBase] or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 3) then
        bWantIndirectReinforcements = true
    end

    UpdateIfLandZoneWantsSupport(tLZTeamData, iPlateau, iLandZone, iTeam, bWantDFReinforcements, bWantIndirectReinforcements)

    if bDebugMessages == true then
        LOG(sFunctionRef..': Just recorded if this LZ wants support, bWantDFReinforcements='..tostring(bWantDFReinforcements)..'; bWantIndirectReinforcements='..tostring(bWantIndirectReinforcements)..'; tLZTeamData[AiBotMap.subrefbLZWantsSupport] = '..tostring(tLZTeamData[AiBotMap.subrefbLZWantsSupport])..'; tLZTeamData[AiBotMap.subrefbLZWantsDFSupport]='..tostring(tLZTeamData[AiBotMap.subrefbLZWantsDFSupport])..'; subreftiLandZoneTargetedByOurCombat='..(tLZTeamData[AiBotMap.subreftiLandZoneTargetedByOurCombat] or 'nil')..'; refiTimeLastFailedToKiteDueToScoutIntel='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeLastFailedToKiteDueToScoutIntel] or 0)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RetreatOtherUnits(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tOtherUnitsToRetreat)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RetreatOtherUnits'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2)
    local tAmphibiousRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 2, true)
    local iCurTime = math.floor(GetGameTimeSeconds())
    local bConsiderKitingRetreat = tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]
    local oNearestEnemyCombatToRallyPoint
    for iUnit, oUnit in tOtherUnitsToRetreat do
        oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] = iCurTime
        --Fatboy (and megalith although wouldnt expect megalith to use this function) - consider retreating slowly instead of running around, and also retreating in opposite direction to the nearest enemy (instead of going to the rally point)
        if bDebugMessages == true then LOG(sFunctionRef..': Considering retreating unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bConsiderKitingRetreat='..tostring(bConsiderKitingRetreat or false)..'; Combat range='..(oUnit[AiBotUnitInfo.refiCombatRange] or 0)..'; Is a fatboy/mega='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy + AiBotUnitInfo.refCategoryMegalith, oUnit.UnitId))) end
        if bConsiderKitingRetreat and (oUnit[AiBotUnitInfo.refiCombatRange] or 0) > 30 and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy + AiBotUnitInfo.refCategoryMegalith, oUnit.UnitId) then
            if not(oNearestEnemyCombatToRallyPoint) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                oNearestEnemyCombatToRallyPoint = AiBotUtilities.GetNearestUnit(tLZTeamData[AiBotMap.reftoNearestDFEnemies], tAmphibiousRallyPoint)
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oNearestEnemyCombatToRallyPoint='..(oNearestEnemyCombatToRallyPoint.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyCombatToRallyPoint) or 'nil')) end
            local bDoneKitingRetreat = false
            if oNearestEnemyCombatToRallyPoint then
                local iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyCombatToRallyPoint:GetPosition(), oUnit:GetPosition())
                if iCurDist <= oUnit[AiBotUnitInfo.refiCombatRange] and iCurDist >= math.max(10, (oUnit[AiBotUnitInfo.refiCombatRange] or 0) - 5) then
                    --Want to consider retreating
                    local iBackupDist = (oUnit:GetBlueprint().Physics.BackUpDistance or 0)
                    if iBackupDist > 3 then
                        local iAngleToNearestEnemy = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oNearestEnemyCombatToRallyPoint:GetPosition())
                        local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tAmphibiousRallyPoint)
                        local tRetreatLocationToUse
                        if AiBotUtilities.GetAngleDifference(iAngleToNearestEnemy, iAngleToRally) >= 145 then --i.e. 70 degree section where will go with rally point instead of opposite direction
                            tRetreatLocationToUse = {tAmphibiousRallyPoint[1], tAmphibiousRallyPoint[2], tAmphibiousRallyPoint[3]}
                        else
                            local tPotentialRetreatLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleToNearestEnemy - 180, iBackupDist - 3, true, nil, AiBotMap.bIsCampaignMap)
                            if AiBotUtilities.IsTableEmpty(tPotentialRetreatLocation) == false and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPotentialRetreatLocation) == iPlateau then
                                tRetreatLocationToUse = {tPotentialRetreatLocation[1], tPotentialRetreatLocation[2], tPotentialRetreatLocation[3]}
                            else
                                tRetreatLocationToUse = {tAmphibiousRallyPoint[1], tAmphibiousRallyPoint[2], tAmphibiousRallyPoint[3]}
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try backing up for fatboy or similar unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; tRetreatLocationToUse='..repru(tRetreatLocationToUse)..'; oNearestEnemyCombatToRallyPoint='..oNearestEnemyCombatToRallyPoint.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemyCombatToRallyPoint)) end
                        bDoneKitingRetreat = true
                        ForkThread(BackupUnitTowardsRallyIfAvailable, oUnit, tRetreatLocationToUse, iPlateau, 'SpFBlsRetr', true, math.min(9, iBackupDist))
                        --AiBotOrders.IssueTrackedMove(oUnit, tRetreatLocationToUse, 3, false, 'SpFBlsRetr')
                    end
                end
            end
            if not(bDoneKitingRetreat) then
                AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 10, false, 'FMNoERetr')
            end
        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
            AiBotOrders.IssueTrackedMove(oUnit, tAmphibiousRallyPoint, 10, false, 'AOtRet')
        else
            AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 10, false, 'OtRet', false)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordUnitAsReceivingLandZoneAssignment(oUnit, iPlateau, iLandZone, iCurLZValue)
    oUnit[refiCurrentAssignmentValue] = iCurLZValue --This is also updated for units that are part of a separate zone
    oUnit[refiCurrentAssignmentPlateauAndLZ] = {iPlateau, iLandZone}
    oUnit[refiTimeOfLastAssignment] = GetGameTimeSeconds()
    if oUnit[AiBotNavy.refiCurrentWZAssignmentValue] then
        oUnit[AiBotNavy.refiCurrentWZAssignmentValue] = nil
        oUnit[AiBotNavy.refiCurrentAssignmentWaterZone] = nil
    end
end

function ManageSpecificLandZone(aiBrain, iTeam, iPlateau, iLandZone)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageSpecificLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bContinue = true
    if not(aiBrain) or aiBrain.AiBotIsDefeated then
        --if Brain hasn't died in the last couple of ticks then give error message
        if GetGameTimeSeconds() - (AiBotOverseer.iTimeLastPlayerDefeat or 0) >= 0.3 then AiBotUtilities.ErrorHandler('Trying to run AiBot logic on a defeated brain') end
        aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
        if not(aiBrain) or aiBrain.AiBotIsDefeated then
            bContinue = false
        end
    end
    if bContinue then

        local bHaveCalledLogicForCombatUnits = false

        --Record enemy threat
        local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
        local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]

        --Omni vision AIx - record we have visual of this LZ
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision] then
            tLZTeamData[AiBotMap.refiTimeLastHadVisual] = GetGameTimeSeconds()
        end

        --Update unit positions and if still valid
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
            --UpdateUnitPositionsAndLandZone(aiBrain, tUnits,                               iTeam, iRecordedPlateau, iRecordedLandZone, bUseLastKnownPosition, bAreAirUnits, tLZTeamData, bUpdateTimeOfLastEnemyPositionCheck, bAreEnemyUnits)
            UpdateUnitPositionsAndLandZone(aiBrain, tLZTeamData[AiBotMap.subrefTEnemyUnits], iTeam, iPlateau,             iLandZone,          true, false, tLZTeamData,  false,                      true)
            if bDebugMessages == true then LOG(sFunctionRef..': Just ran updateunitpositions for enemy units in this zone') end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Will update enemy air units if there are any, is reftLZEnemyAirUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]))..'; Time since refiTimeOfLastAirUpdate='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeOfLastAirUpdate] or -100)) end
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false then
            --Update air positions if we have units in the zone or has been a while to approximate a player being able to tell if enemy air force is still there
            local bAlwaysUpdateEnemyAirUnitPositions = AiBotMap.bIsCampaignMap --campaign map players are more likely to know when air attacks iwll attack and from where
            if bAlwaysUpdateEnemyAirUnitPositions or (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false or GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeOfLastAirUpdate] or -100) >= 12 or (AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.reftLZEnemyAirUnits][1]) and AiBotUnitInfo.CanSeeUnit(aiBrain, tLZTeamData[AiBotMap.reftLZEnemyAirUnits][1])) or (tLZTeamData[AiBotMap.refiRadarCoverage] or 0) > 0) then
                if bDebugMessages == true then LOG(sFunctionRef..': Updating air unit positions in the zone') end
                tLZTeamData[AiBotMap.refiTimeOfLastAirUpdate] = GetGameTimeSeconds()
                --UpdateUnitPositionsAndLandZone(aiBrain, tUnits,                       iTeam, iRecordedPlateau, iRecordedLandZone, bUseLastKnownPosition, bAreAirUnits, tLZTeamData, bUpdateTimeOfLastEnemyPositionCheck, bAreEnemyUnits)
                UpdateUnitPositionsAndLandZone(aiBrain, tLZTeamData[AiBotMap.reftLZEnemyAirUnits], iTeam, iPlateau, iLandZone, false, true, tLZTeamData, false,                               true)
            else
                --UpdateUnitPositionsAndLandZone(aiBrain, tUnits,                           iTeam, iRecordedPlateau, iRecordedLandZone, bUseLastKnownPosition, bAreAirUnits, tLZTeamData, bUpdateTimeOfLastEnemyPositionCheck, bAreEnemyUnits)
                --if bDebugMessages == true then LOG(sFunctionRef..': Will just update based on last known positoin') end
                UpdateUnitPositionsAndLandZone(aiBrain, tLZTeamData[AiBotMap.reftLZEnemyAirUnits], iTeam, iPlateau, iLandZone,        AiBotMap.bIsCampaignMap, true, tLZTeamData,   false,                                  true)
            end
        end
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            UpdateUnitPositionsAndLandZone(aiBrain, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits], iTeam, iPlateau, iLandZone, false, false, tLZTeamData)
        end

        if bDebugMessages == true then LOG(sFunctionRef..': About to update threat for iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iTeam='..iTeam..'; Is LZTeamData empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData))..'; Time='..GetGameTimeSeconds()) end
        RecordGroundThreatForLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone)
        RecordAirThreatForLandZone(tLZTeamData, iTeam, iPlateau, iLandZone)

        tLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits] = {}
        tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield] = {}
        tLZTeamData[AiBotMap.refbLZWantsMobileShield] = false --will change later
        tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileStealth] = {}
        tLZTeamData[AiBotMap.refbLZWantsMobileStealth] = false --will change later
        tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts] = nil --will change later
        tLZTeamData[AiBotMap.refiSpareLandScouts] = 0

        --Build location tracker
        tLZData[AiBotMap.subrefSegmentsConsideredThisTick] = 0

        local tEngineers, tScouts, tMobileShields, tMobileStealths, tOtherUnitsToRetreat, tSACUs, tSACUsToGoToWaterZone
        local iCurShield, iMaxShield
        local bLandZoneOrAdjHasUnitsWantingScout = false
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of allied units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) end
        local bUpdateEnemyDataHere = true --Will handle this logic in logic for managing land zone units if htis is false

        local bAlliedUnitsHereOrInAdjacentZone = not(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))
        local bHaveCombatUnitsFromAdjZone = false
        if not(bAlliedUnitsHereOrInAdjacentZone) then
            for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                local tAltLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                bAlliedUnitsHereOrInAdjacentZone = AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if bAlliedUnitsHereOrInAdjacentZone then break end

            end
        end
        if bAlliedUnitsHereOrInAdjacentZone then
            --Decide on what to do with units in this LZ
            tEngineers = {}
            tScouts = {}
            tMobileShields = {}
            tMobileStealths = {}
            tSACUs = {}
            tOtherUnitsToRetreat = {} --Intended for e.g. fatboys and units with personal shield
            local bUseRASInCombat = false
            if tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > 0 then bUseRASInCombat = true end
            local tAvailableCombatUnits = {}
            local tUnavailableUnitsInThisLZ = {}
            local tTempOtherUnits = {}
            local tAvailableMAA = {}
            local iCurLZValue = tLZTeamData[AiBotMap.subrefLZTValue]

            local iOurBestDFRange = 0
            local iOurBestIndirectRange = 0
            local bIncludeUnit
            local iAvailableCombatCount = 0 --used to decide whether to only issue orders to hover units every 6s

            local iEnemyOmniCoverage = AiBotConditions.GetEnemyOmniCoverageOfZone(iPlateau, iLandZone, iTeam)

            local iMobileShieldMassThreshold = 150 --When assigning mobile shields will also restrict further so e.g. seraphim mobile shields will have a higher threshold
            --Shield overflow mechanic doesnt exist outside faf so consider shielding weaker units
            if not(AiBotUtilities.bFAFActive) and tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 300 then iMobileShieldMassThreshold = 40 end --want to consider shielding t1 units in the zone if we potentially have a decent t1 force
            local iMobileShieldHigherMAAMassThreshold = 400 --for if we have MAA and enemy doesnt have much air threat
            local iMobileStealthMassThreshold = 200 --will get adjusted further
            local iMobileStealthHigherMassThreshold = 500 --i.e. wont stealth loyalists and titans
            local iUnitMassCost, iShieldPercentageAdjust, iCurHealthPercent
            local iMobileStealthLowerThresholdCount = 0 --Used to avoid assigning too many mobile stealth at once to units not exceeding the higher mass threshold
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > 600 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 2000 or tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0) then iMobileShieldHigherMAAMassThreshold = iMobileShieldMassThreshold end
            local bConsiderMobileShieldsForT2Arti = false
            local bConsiderMobileShieldsForT2PD = false
            local tRaiders
            if tLZTeamData[AiBotMap.subrefLZbCoreBase] then
                if (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false or (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) > 0) then
                    bConsiderMobileShieldsForT2Arti = true
                    bConsiderMobileShieldsForT2PD = true
                elseif tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                    bConsiderMobileShieldsForT2PD = true
                end

            end

            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                local bConsiderMobileShieldsForBuildingsDueToNovax = false
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] > 0 and tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] <= 2 then bConsiderMobileShieldsForBuildingsDueToNovax = true end
                local bConsiderMobileShieldForGETemplate
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasTeleport] and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates]) == false then
                    if not(tLZTeamData[AiBotMap.subrefbGEShieldSACU]) then
                        bConsiderMobileShieldForGETemplate = true
                    else
                        for _, tSubtable in tLZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
                            if AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subreftoGEShieldSACUs]) == false then
                                bConsiderMobileShieldForGETemplate = true
                                break
                            end
                        end
                    end
                end
                local bConsiderPreemptiveMAADefence --nil if not considered yet, false if dont want to, true if want MAA to go infront of ACU/fatboy that they are covering instead of behind
                local oClosestEnemyT1ToT3Bomber, tPreferredPositionToProtectFromBomber     --Used for preemptiveMAADefence
                local bCurUnitWantsMobileShield
                local iSACUCategory = categories.SUBCOMMANDER --[[AiBotUnitInfo.refCategoryRASSACU
                if (tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] or tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD]) and not(bUseRASInCombat) then iSACUCategory = iSACUCategory + categories.SUBCOMMANDER end--]]
                for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] do

                    if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with fraction complete '..oUnit:GetFractionComplete()..' owned by brain '..oUnit:GetAIBrain().Nickname..'; Special micro active='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Time until micro stopped='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 0)..'; Unit combat range='..(oUnit[AiBotUnitInfo.refiCombatRange] or 'nil')..'; Is unit amphibious='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryAmphibious, oUnit.UnitId))..'; Is unit mobile non-air amphibious='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryAmphibious * categories.MOBILE - categories.AIR, oUnit.UnitId))..'; is reftArtiTemplateRefs nil='..tostring(oUnit[AiBotBuilding.reftArtiTemplateRefs] == nil)) end
                    bCurUnitWantsMobileShield = false
                    if oUnit[refbFlaggedForPriorityScout] then
                        local bRecorded = false
                        if not(tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts]) then
                            tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts] = {}
                        else
                            for iRecorded, oRecorded in tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts] do
                                if oRecorded == oUnit then bRecorded = true break end
                            end
                        end
                        if not(bRecorded) then
                            table.insert(tLZTeamData[AiBotMap.reftoUnitsWantingPriorityScouts], oUnit)
                        end
                    end
                    if oUnit:GetFractionComplete() >= 1 then
                        if EntityCategoryContains(categories.MOBILE - AiBotUnitInfo.refCategoryScathis, oUnit.UnitId) then
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) then
                                table.insert(tEngineers, oUnit)
                                bLandZoneOrAdjHasUnitsWantingScout = true
                            elseif EntityCategoryContains(categories.COMMAND, oUnit.UnitId) or oUnit[AiBotACU.refbTreatingAsACU] then
                                --ACU logic - handled via AiBotACU file, as amy not want to kite with it; acu is still stored in list of allied units for a land zone though
                                if bDebugMessages == true then LOG(sFunctionRef..': ACU is in list of allied units for iPlateau'..iPlateau..'; iLandZone='..iLandZone..'; Does ACU have valid mobile shield assigned='..tostring(AiBotUnitInfo.IsUnitValid(oUnit[refoAssignedMobileShield]))..'; Assigned shield='..(oUnit[refoAssignedMobileShield].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit[refoAssignedMobileShield]) or 'nil')) end
                                bLandZoneOrAdjHasUnitsWantingScout = true
                                bCurUnitWantsMobileShield = true
                                if not(oUnit[refoAssignedMobileShield]) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding ACU to table of units wanting mobile shield for this zone') end
                                    table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                                elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] > 0 then --when assigning a mobile shield, we should do it to this table first, and to refoAssignedMobileShield last; that way, the below should only be relevant if previously assigned mobile shields have died or retreated; although not perfect since it means a smaller number assigned, hopefully it will be close enough and avoids the risk of inconsistent conditions leading to an infinite cycle of shield assignment (if changing then need to do an AiBotConditions function)
                                    --If ACU is under fixed shield at core base then dont require mobile shields
                                    if tLZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotLogic.IsTargetUnderShield(aiBrain, oUnit, 10000, false, true, false, false, false) then
                                        if AiBotConditions.IsTableOfUnitsStillValid(oUnit[reftoAdditionalAssignedMobileShields]) then
                                            --Remove all extra assigned mobile shields if have ACU under fixed shield
                                            for iCurMobileShield = table.getn(oUnit[reftoAdditionalAssignedMobileShields]), 1, -1 do
                                                ClearCurrentShieldTarget(oUnit[reftoAdditionalAssignedMobileShields][iCurMobileShield])
                                            end
                                        end
                                    elseif not(AiBotConditions.IsTableOfUnitsStillValid(oUnit[reftoAdditionalAssignedMobileShields])) then
                                        table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                                    end
                                end
                                if iEnemyOmniCoverage <= 20 and (not(oUnit.HasEnhancement) or (oUnit[AiBotACU.refiUpgradeCount] or 0) == 0 or not((oUnit:HasEnhancement('StealthGenerator') or oUnit:HasEnhancement('CloakingGenerator') or oUnit:HasEnhancement('FAF_SelfRepairSystem')))) then
                                    if not(oUnit[refoAssignedMobileStealth]) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Adding ACU to table of units wanting mobile stealth, UpgradeCount='..(oUnit[AiBotACU.refiUpgradeCount] or 0)..'; oUnit.HasEnhancement == nil='..tostring(oUnit.HasEnhancement == nil)..'; Has stealthgen enhancement='..tostring(oUnit:HasEnhancement('StealthGenerator'))..'; Has cloaking enhancement='..tostring(oUnit:HasEnhancement('CloakingGenerator'))..'; Has self repair system='..tostring(oUnit:HasEnhancement('FAF_SelfRepairSystem'))) end
                                        table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileStealth], oUnit)
                                    end
                                end

                                if not(oUnit[AiBotACU.refbTreatingAsACU]) and oUnit:GetAIBrain().AiBotAI then ForkThread(AiBotACU.ManageACU, oUnit:GetAIBrain(), oUnit) end --redundancy, wouldnt expect this to normally trigger
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout, oUnit.UnitId) then
                                if not(oUnit[AiBotUnitInfo.refbLurkerMode]) then
                                    if oUnit[AiBotUnitInfo.refbScoutCombatOverride] then
                                        bIncludeUnit = true
                                        table.insert(tAvailableCombatUnits, oUnit)
                                        if oUnit[AiBotUnitInfo.refiDFRange] > iOurBestDFRange then
                                            iOurBestDFRange = oUnit[AiBotUnitInfo.refiDFRange]
                                        end
                                    else
                                        table.insert(tScouts, oUnit)
                                    end
                                elseif bDebugMessages == true then LOG(sFunctionRef..': Scout is in lurker mode so ignoring as handled by separate logic')
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMobileLandShield, oUnit.UnitId) then
                                table.insert(tMobileShields, oUnit)
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMobileLandStealth, oUnit.UnitId) then
                                table.insert(tMobileStealths, oUnit)
                            elseif EntityCategoryContains(iSACUCategory, oUnit.UnitId) and not(bUseRASInCombat) then
                                --Only include for new orders if not already building something; otherwise do nothing with the unit (as hopefully we already have logic applying to it)
                                if not(oUnit:IsUnitState('Building') or oUnit:IsUnitState('Repairing')) and AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftArtiTemplateRefs]) then
                                    if oUnit[AiBotUnitInfo.refiSACUWaterZoneTarget] then
                                        if not(tSACUsToGoToWaterZone) then tSACUsToGoToWaterZone = {} end
                                        table.insert(tSACUsToGoToWaterZone, oUnit)
                                    else
                                        table.insert(tSACUs, oUnit)
                                    end
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMAA + AiBotUnitInfo.refCategoryMobileLand - categories.COMMAND, oUnit.UnitId) or (oUnit[AiBotUnitInfo.refiCombatRange] > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryAmphibious * categories.MOBILE - categories.AIR, oUnit.UnitId)) then
                                --Tanks, skirmishers, and indirect fire units - handled by main combat unit manager
                                bIncludeUnit = false
                                bLandZoneOrAdjHasUnitsWantingScout = true
                                --Is the unit available for use by this land zone?
                                if oUnit:GetFractionComplete() == 1 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Does unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' have a valid guard? Guard='..(oUnit[refoAssignedUnitToGuard].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit[refoAssignedUnitToGuard]) or 'nil')..'; refiRaidingTargetZone='..(oUnit[refiRaidingTargetZone] or 'nil')) end
                                    if oUnit[refiRaidingTargetZone] then
                                        if not(tRaiders) then tRaiders = {} end
                                        table.insert(tRaiders, oUnit)
                                    elseif oUnit[refoAssignedUnitToGuard] and AiBotUnitInfo.IsUnitValid(oUnit[refoAssignedUnitToGuard]) and (EntityCategoryContains(AiBotUnitInfo.refCategoryAmphibious + categories.HOVER, oUnit.UnitId) or not(AiBotUnitInfo.IsUnitUnderwater(oUnit[refoAssignedUnitToGuard]))) then

                                        --Guard actually causes MAA to move a bit too far away so will just move towards the unit; currently are just using this for MAA covering a fatboy so moving directly to the unit means it works out well since they wont block the fatboy and will rotate instead to be to the fatboy's rear at all times
                                        --Temporarily run if we are in range of enemy units in the zone
                                        --CloseToEnemyUnit(tStartPosition, tUnitsToCheck,                       iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure, bIncludeEnemyAntiNavyRange)
                                        if (oUnit[AiBotUnitInfo.refiAARange] or 0) > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and AiBotConditions.CloseToEnemyUnit(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], 4,    iTeam, true,                    nil,                    nil,                                oUnit,                                  nil,                                false) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Have MAA assigned to guard a unit but enemy DF are close so want to retreat to rally point') end
                                            table.insert(tOtherUnitsToRetreat, oUnit)
                                        else
                                            --Consider having MAA go infront of our unit if worried about enemy bomber snipe threat (if dealing with fatboy or ACU outside of core base), provided not close to being in range
                                            if bConsiderPreemptiveMAADefence == nil then
                                                bConsiderPreemptiveMAADefence = false
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to preemptively move to defend against air snipe, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; Core base='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase] or false)) end
                                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 4000 and not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) then
                                                    --Does enemy ahve any nearby bombers to us and we lack fixed AA in this zone?
                                                    local tEnemyBombers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryBomber - categories.EXPERIMENTAL, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAllEnemyAir])
                                                    local iMaxDistance = 300
                                                    local iClosestBomberDist = iMaxDistance --Ignore if bomber further than this
                                                    local iCurDist
                                                    local iMaxCount = 80
                                                    if AiBotUtilities.bCPUPerformanceMode then iMaxCount = 40 end
                                                    local tComparisonPosition
                                                    if (oUnit[refoAssignedUnitToGuard][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone and oUnit[refoAssignedUnitToGuard][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau) or AiBotUtilities.GetDistanceBetweenPositions(oUnit[refoAssignedUnitToGuard]:GetPosition(), oUnit:GetPosition()) <= 20 then
                                                        tComparisonPosition = oUnit[refoAssignedUnitToGuard]:GetPosition()
                                                    else
                                                        tComparisonPosition = tLZData[AiBotMap.subrefMidpoint]
                                                    end
                                                    if AiBotUtilities.IsTableEmpty(tEnemyBombers) == false then
                                                        local iEnemyBomberMassNearby = 0
                                                        local bEnemyDoesntHaveBigEnoughBomberThreat = true
                                                        local bCustomThreat = AiBotUnitInfo.bCustomThreatFactor
                                                        for iBomber, oBomber in tEnemyBombers do
                                                            if not(oBomber.Dead) then
                                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(),tComparisonPosition)
                                                                if iCurDist < iClosestBomberDist then
                                                                    iClosestBomberDist = iCurDist
                                                                    oClosestEnemyT1ToT3Bomber = oBomber
                                                                end
                                                                if bEnemyDoesntHaveBigEnoughBomberThreat and iCurDist < iMaxDistance then
                                                                    if bCustomThreat then
                                                                        iEnemyBomberMassNearby = iEnemyBomberMassNearby + (oBomber[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * AiBotUnitInfo.iThreatFactor
                                                                    else
                                                                        iEnemyBomberMassNearby = iEnemyBomberMassNearby + (oBomber[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
                                                                    end
                                                                    if iEnemyBomberMassNearby >= 1500 and (iEnemyBomberMassNearby >= 4000 or (iCurDist < 200 and (iCurDist < 120 or iEnemyBomberMassNearby >= 2500))) then
                                                                        bEnemyDoesntHaveBigEnoughBomberThreat = false
                                                                    end
                                                                end
                                                                if bDebugMessages == true then LOG(sFunctionRef..': oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; iCurDist='..iCurDist..'; iClosestBomberDist='..iClosestBomberDist..'; iEnemyBomberMassNearby='..iEnemyBomberMassNearby..'; iBomber='..iBomber) end
                                                                if iBomber > iMaxCount and ((bEnemyDoesntHaveBigEnoughBomberThreat and not(oClosestEnemyT1ToT3Bomber)) or iBomber > iMaxCount + 50) then break end
                                                            end
                                                        end
                                                        if bEnemyDoesntHaveBigEnoughBomberThreat then oClosestEnemyT1ToT3Bomber = nil end
                                                    end
                                                    if oClosestEnemyT1ToT3Bomber and iClosestBomberDist >= 35 then bConsiderPreemptiveMAADefence = true end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': bConsiderPreemptiveMAADefence='..tostring(bConsiderPreemptiveMAADefence)) end
                                                end

                                            end
                                            if bConsiderPreemptiveMAADefence then
                                                --Check covering fatboy or ACU and dont have enemy threat that can target our MAA
                                                if bDebugMessages == true then
                                                    if AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) then
                                                        LOG(sFunctionRef..': refoClosestEnemyFromLastCloseToEnemyUnitCheck is valid='..oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])..'; Dist to it='..AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition())..'; refiCombatRange of it='..oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange]..'; oUnit[refoAssignedUnitToGuard]='..oUnit[refoAssignedUnitToGuard].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[refoAssignedUnitToGuard])..'; Is this a fatboy or acu='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy + categories.COMMAND, oUnit[refoAssignedUnitToGuard].UnitId)))
                                                    else
                                                        LOG(sFunctionRef..': refoClosestEnemyFromLastCloseToEnemyUnitCheck is not valid, oUnit[refoAssignedUnitToGuard]='..oUnit[refoAssignedUnitToGuard].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[refoAssignedUnitToGuard]))
                                                    end
                                                end
                                                if (not(AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])) or AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oUnit:GetPosition()) - oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] >= 15) and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy + categories.COMMAND, oUnit[refoAssignedUnitToGuard].UnitId) then
                                                    if not(tPreferredPositionToProtectFromBomber) then
                                                        --Move between fatboy/ACU and closest bomber
                                                        local iAngleToBomber = AiBotUtilities.GetAngleFromAToB(oUnit[refoAssignedUnitToGuard]:GetPosition(), oClosestEnemyT1ToT3Bomber:GetPosition())
                                                        local iStartingDistToMove
                                                        if AiBotUtilities.GetDistanceBetweenPositions( oClosestEnemyT1ToT3Bomber:GetPosition(), oUnit[refoAssignedUnitToGuard]:GetPosition()) <= 120 then
                                                            iStartingDistToMove = 40
                                                        else
                                                            iStartingDistToMove = 30
                                                        end
                                                        for iDistToMove = iStartingDistToMove, 10, -10 do
                                                            tPreferredPositionToProtectFromBomber = AiBotUtilities.MoveInDirection(oUnit[refoAssignedUnitToGuard]:GetPosition(), iAngleToBomber, iDistToMove, true, false, AiBotMap.bIsCampaignMap)
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iDistToMove='..iDistToMove..'; iAngleToBomber='..iAngleToBomber..'; tPreferredPositionToProtectFromBomber='..repru(tPreferredPositionToProtectFromBomber)..'; Land label='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tPreferredPositionToProtectFromBomber) or 'nil')..'; tLZData[AiBotMap.subrefLZIslandRef]='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')) end
                                                            if AiBotUtilities.IsTableEmpty(tPreferredPositionToProtectFromBomber) == false and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tPreferredPositionToProtectFromBomber) == tLZData[AiBotMap.subrefLZIslandRef] then
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Have valid intercept location so will use this') end
                                                                break
                                                            else tPreferredPositionToProtectFromBomber = nil
                                                            end
                                                        end
                                                        if not(tPreferredPositionToProtectFromBomber) then tPreferredPositionToProtectFromBomber = oUnit[refoAssignedUnitToGuard]:GetPosition() end --redundancy
                                                    end
                                                    AiBotOrders.IssueTrackedMove(oUnit, tPreferredPositionToProtectFromBomber, 3, false, 'SpecPreAA', false)
                                                else
                                                    AiBotOrders.IssueTrackedMove(oUnit, oUnit[refoAssignedUnitToGuard]:GetPosition(), 3, false, 'SpecH', false)
                                                end
                                            else
                                                AiBotOrders.IssueTrackedMove(oUnit, oUnit[refoAssignedUnitToGuard]:GetPosition(), 3, false, 'SpecG', false)
                                            end
                                        end
                                    elseif oUnit[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionLoadOntoTransport or oUnit:IsUnitState('Attached') then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Unit is either attached or abut to load into a transport so will ignore') end
                                        --AiBotOrders.IssueTrackedGuard(oUnit, oUnit[refoAssignedUnitToGuard], false, 'SpecG', false)
                                    else
                                        --NOTE: If making changes to below line condition, then update simialr line in AiBotTeam
                                        if oUnit[AiBotUnitInfo.refiCombatRange] > 0 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryMAA, oUnit.UnitId)) then table.insert(tLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits], oUnit) end
                                        --Is the unit's priority lower than this?
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if have available combat unit, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oUnit[refiCurrentAssignmentValue]='..(oUnit[refiCurrentAssignmentValue] or 'nil')..'; oUnit[refiCurrentAssignmentPlateauAndLZ]='..repru(oUnit[refiCurrentAssignmentPlateauAndLZ])..'; iCurLZValue='..iCurLZValue..'; Unit mass cost='..(oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))..'; iMobileShieldMassThreshold='..iMobileShieldMassThreshold) end
                                        if (oUnit[refiCurrentAssignmentValue] or 0) <= iCurLZValue or (oUnit[refiCurrentAssignmentPlateauAndLZ][1] == iPlateau and (oUnit[refiCurrentAssignmentPlateauAndLZ][2] == iLandZone or (GetGameTimeSeconds() - (oUnit[refiTimeOfLastAssignment] or 0) >= 5))) then
                                            --Is it a unit with a shield that wants to retreat so its shield can regen?
                                            iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, true)
                                            iShieldPercentageAdjust = 0
                                            if iCurShield > 0 then
                                                iCurHealthPercent = AiBotUnitInfo.GetUnitHealthPercent(oUnit)
                                                if iCurHealthPercent < 0.7 and (iCurHealthPercent < 0.5 or EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId)) then
                                                    if AiBotUnitInfo.GetUnitHealthPercent(oUnit) < 0.2 then iShieldPercentageAdjust = 0.25
                                                    else iShieldPercentageAdjust = 0.15
                                                    end
                                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                                                    iShieldPercentageAdjust = 0.075
                                                end
                                            end

                                            if bDebugMessages == true then LOG(sFunctionRef..': iCurShield='..iCurShield..'; iMaxShield='..iMaxShield..'; Unit max health='..oUnit:GetMaxHealth()..'; Is team stalling energy='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; Team AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount]..'; Is unit paused='..tostring(oUnit[AiBotUnitInfo.refbPaused] or false)..'; Is shield enabled='..tostring(AiBotUnitInfo.IsUnitShieldEnabled(oUnit))..'; is oUnit[refbShieldIsDisabled] nil='..tostring(oUnit[AiBotUnitInfo.refbShieldIsDisabled] == nil)) end
                                            --Units with a personal shield that represent a high % of their health should retreat if theyre paused due to E stall
                                            if not(oUnit[AiBotUnitInfo.refbEasyBrain]) and iMaxShield > 0 and (oUnit[AiBotUnitInfo.refbPaused] or iCurShield < iMaxShield * (0.35 + iShieldPercentageAdjust)) and (iCurShield == 0 or iMaxShield > oUnit:GetMaxHealth() * 0.8 or iCurShield < iMaxShield * (iShieldPercentageAdjust + 0.05)) then --Fatboy and in theory SACUs retreat when shield is low; titans etc. retreat when shield is almost gone
                                                if bDebugMessages == true then LOG(sFunctionRef..': Added unit to table of units to retreat') end
                                                table.insert(tOtherUnitsToRetreat, oUnit)
                                                RecordUnitAsReceivingLandZoneAssignment(oUnit, iPlateau, iLandZone, 100000)
                                                --Redundancy for rare cases where a units shield can be disabled from a transfer
                                                if iCurShield == 0 and oUnit[AiBotUnitInfo.refbTransferredUnit] and not(oUnit[AiBotUnitInfo.refbPaused]) and (not(AiBotUnitInfo.IsUnitShieldEnabled(oUnit)) or oUnit[AiBotUnitInfo.refbShieldIsDisabled] == nil) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will enable shield for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                                                    AiBotUnitInfo.EnableUnitShield(oUnit)
                                                end
                                            else
                                                if EntityCategoryContains(AiBotUnitInfo.refCategoryMAA, oUnit.UnitId) then
                                                    table.insert(tAvailableMAA, oUnit)
                                                    bIncludeUnit =  true
                                                elseif ((oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 or (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 0) then
                                                    table.insert(tAvailableCombatUnits, oUnit)
                                                    iAvailableCombatCount = iAvailableCombatCount + 1
                                                    if oUnit[AiBotUnitInfo.refiDFRange] > iOurBestDFRange and not(EntityCategoryContains(AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId)) then iOurBestDFRange = oUnit[AiBotUnitInfo.refiDFRange] end
                                                    if oUnit[AiBotUnitInfo.refiIndirectRange] > iOurBestIndirectRange then iOurBestIndirectRange = oUnit[AiBotUnitInfo.refiIndirectRange] end
                                                    bIncludeUnit = true
                                                end
                                                if bIncludeUnit then
                                                    RecordUnitAsReceivingLandZoneAssignment(oUnit, iPlateau, iLandZone, iCurLZValue)
                                                end
                                            end
                                        else
                                            table.insert(tUnavailableUnitsInThisLZ, oUnit)
                                        end
                                        iUnitMassCost = (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
                                        if iUnitMassCost >= iMobileShieldMassThreshold and (iUnitMassCost >= iMobileShieldHigherMAAMassThreshold or iMobileShieldHigherMAAMassThreshold == iMobileShieldMassThreshold or not(EntityCategoryContains(AiBotUnitInfo.refCategoryMAA, oUnit.UnitId))) then
                                            bCurUnitWantsMobileShield = true
                                            if not(oUnit[refoAssignedMobileShield]) then
                                                table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Wnat mobile shield for unit') end
                                            elseif iUnitMassCost > 2000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId) then
                                                --Fatboys - have +1 mobile shield per enemy novax (max of 5 incl base)
                                                if not(AiBotConditions.IsTableOfUnitsStillValid(oUnit[reftoAdditionalAssignedMobileShields])) or table.getn(oUnit[reftoAdditionalAssignedMobileShields]) < math.min(4, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount]) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Want extra mobile shield for fatboy due to enemy novax') end
                                                    table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                                                end
                                            end
                                        end
                                        if iEnemyOmniCoverage <= 20 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryStealth, oUnit.UnitId)) then
                                            if iUnitMassCost >= iMobileStealthHigherMassThreshold then
                                                if not(oUnit[refoAssignedMobileStealth]) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Want mobile stealth for unit') end
                                                    table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileStealth], oUnit)
                                                end
                                            elseif iUnitMassCost >= iMobileStealthMassThreshold and EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryIndirect + AiBotUnitInfo.refCategoryAbsolver - categories.TECH1, oUnit.UnitId) then
                                                --Only say we want a mobile stealth if the unit doesnt have one assigned
                                                iMobileStealthLowerThresholdCount = iMobileStealthLowerThresholdCount + 1

                                                if iMobileStealthLowerThresholdCount >= 3 or oUnit[refoAssignedMobileStealth] then
                                                    iMobileStealthLowerThresholdCount = 0
                                                    if not(oUnit[refoAssignedMobileStealth]) then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Want mobile stealth for lower threshold unit') end
                                                        table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileStealth], oUnit)
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            elseif EntityCategoryContains(categories.STRUCTURE, oUnit.UnitId) then
                                --Structure logic - handled separately e.g. via AiBotFactory for factories
                            else
                                --Unexpected unit type - could e.g. be a naval unit on a location thought to be a land zone; only flag as error if unit has no orders
                                table.insert(tTempOtherUnits, oUnit)
                                bLandZoneOrAdjHasUnitsWantingScout = true
                            end
                        else
                            if bConsiderMobileShieldForGETemplate and oUnit[AiBotBuilding.reftArtiTemplateRefs] and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oUnit.UnitId) then
                                bCurUnitWantsMobileShield = true
                                if not(oUnit[refoAssignedMobileShield]) then
                                    table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                                end
                            elseif bConsiderMobileShieldsForBuildingsDueToNovax and AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) and EntityCategoryContains(AiBotUnitInfo.refCategoryPower - categories.TECH1 + AiBotUnitInfo.refCategoryEnergyStorage, oUnit.UnitId) then
                                bCurUnitWantsMobileShield = true
                                if not(oUnit[refoAssignedMobileShield]) then
                                    table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                                end
                            elseif bConsiderMobileShieldsForT2Arti and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) then
                                bCurUnitWantsMobileShield = true
                                if not(oUnit[refoAssignedMobileShield]) then
                                    table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                                end
                            elseif bConsiderMobileShieldsForT2PD and EntityCategoryContains(AiBotUnitInfo.refCategoryT2PlusPD, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) then
                                bCurUnitWantsMobileShield = true
                                if not(oUnit[refoAssignedMobileShield]) then
                                    table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                                end
                            end

                        end
                    else
                        --Under construction unit
                        if bConsiderMobileShieldForGETemplate and oUnit[AiBotBuilding.reftArtiTemplateRefs] and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oUnit.UnitId) then
                            bCurUnitWantsMobileShield = true
                            if not(oUnit[refoAssignedMobileShield]) then
                                table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                            end
                        elseif bConsiderMobileShieldsForBuildingsDueToNovax and AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryStructure * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryScathis, oUnit.UnitId) then
                            bCurUnitWantsMobileShield = true
                            if not(oUnit[refoAssignedMobileShield]) then
                                table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                            end
                        elseif (bConsiderMobileShieldsForT2PD or bConsiderMobileShieldsForT2Arti) and oUnit:GetFractionComplete() >= 0.2 then
                            if bConsiderMobileShieldsForT2Arti then
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) then
                                    bCurUnitWantsMobileShield = true
                                    if not(oUnit[refoAssignedMobileShield]) then
                                        table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                                    end
                                end
                            end
                            if bConsiderMobileShieldsForT2PD then
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryT2PlusPD, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) then
                                    bCurUnitWantsMobileShield = true
                                    if not(oUnit[refoAssignedMobileShield]) then
                                        table.insert(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield], oUnit)
                                    end
                                end
                            end
                        end
                    end
                    if oUnit[refoAssignedMobileShield] and not(bCurUnitWantsMobileShield) and oUnit[refoAssignedMobileShield][refoMobileShieldTarget] == oUnit then
                        ClearCurrentShieldTarget(oUnit[refoAssignedMobileShield])
                    end
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': Is table of engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tEngineers))..'; Is table of combat units just for this zone empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableCombatUnits))) end

            --Mobile shield data:
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield]) == false then
                for iUnit, oUnit in tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileShield] do
                    if oUnit[refoAssignedMobileShield] then
                        if not(AiBotUnitInfo.IsUnitValid(oUnit[refoAssignedMobileShield])) then
                            oUnit[refoAssignedMobileShield] = nil
                            tLZTeamData[AiBotMap.refbLZWantsMobileShield] = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Recording that the land zone '..iLandZone..' wants mobile shields as a unit that had a mobile shield no longerh as a valid one') end
                        end
                    else
                        tLZTeamData[AiBotMap.refbLZWantsMobileShield] = true
                        if bDebugMessages == true then LOG(sFunctionRef..': Recording that the land zone '..iLandZone..' wants mobile shields as it has a unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' that doesnt have an assigned mobile shield yet') end
                    end
                end
            end
            tLZTeamData[AiBotMap.subrefiAvailableMobileShieldThreat] = 0
            if AiBotUtilities.IsTableEmpty(tMobileShields) == false then
                tLZTeamData[AiBotMap.subrefiAvailableMobileShieldThreat] = AiBotUnitInfo.GetMassCostOfUnits(tMobileShields)
                ManageMobileShieldsInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tMobileShields)
            end
            --Mobile stealth data:
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileStealth]) == false then

                for iUnit, oUnit in tLZTeamData[AiBotMap.reftoLZUnitsWantingMobileStealth] do
                    if iEnemyOmniCoverage > 20 then
                        if AiBotUnitInfo.IsUnitValid(oUnit[refoAssignedMobileStealth]) then
                            oUnit[refoAssignedMobileStealth][refoMobileStealthTarget] = nil
                            oUnit[refoAssignedMobileStealth] = nil
                        end
                    elseif oUnit[refoAssignedMobileStealth] then
                        if not(AiBotUnitInfo.IsUnitValid(oUnit[refoAssignedMobileStealth])) then
                            oUnit[refoAssignedMobileStealth] = nil
                            tLZTeamData[AiBotMap.refbLZWantsMobileStealth] = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Recording that the land zone '..iLandZone..' wants mobile Stealths as a unit that had a mobile Stealth no longerh as a valid one') end
                        end
                    else
                        tLZTeamData[AiBotMap.refbLZWantsMobileStealth] = true
                        if bDebugMessages == true then LOG(sFunctionRef..': Recording that the land zone '..iLandZone..' wants mobile Stealths as it has a unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' that doesnt have an assigned mobile Stealth yet') end
                    end
                end
                if iEnemyOmniCoverage > 20 then tLZTeamData[AiBotMap.refbLZWantsMobileStealth] = false end
            end

            if AiBotUtilities.IsTableEmpty(tMobileStealths) == false then
                ManageMobileStealthsInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tMobileStealths, iEnemyOmniCoverage)
            end

            local iCurDFThreat = 0
            local iCurIndirectThreat = 0
            local iCurMAAThreat = tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]
            local iMinIndirectRangeNeededForThreat = tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] + 1
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange]) == false then
                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange] do
                    if iRange >= iMinIndirectRangeNeededForThreat then
                        iCurIndirectThreat = iCurIndirectThreat + iThreat
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange]) == false then
                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] do
                    iCurDFThreat = iCurDFThreat + iThreat
                end
            end


            local bConsiderAdjacentDF = false
            local bConsiderAdjacentIndirect = false
            local bConsiderAdjacentMAA = false
            if bDebugMessages == true then LOG(sFunctionRef..': Setting whether we want to consider indirect threat, iCurIndirectThreat='..(iCurIndirectThreat or 'nil')..'; tLZTeamData[AiBotMap.subrefLZIndirectThreatWanted]='..(tLZTeamData[AiBotMap.subrefLZIndirectThreatWanted] or 'nil')) end
            if iCurIndirectThreat < tLZTeamData[AiBotMap.subrefLZIndirectThreatWanted] then bConsiderAdjacentIndirect = true end
            if iCurDFThreat < tLZTeamData[AiBotMap.subrefLZDFThreatWanted] then bConsiderAdjacentDF = true end
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false and iCurMAAThreat < tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] and tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 and (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] == 0 or (tLZTeamData[AiBotMap.subrefLZSValue] or 0) > 0 or tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] > (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 0.7) then bConsiderAdjacentMAA = true end




            --Add adjacent combat units if the land zone is lower priority than us and the adjacent LZ doesnt have DF units of a significant threat in it
            local iCurUnitThreat
            if bDebugMessages == true then LOG(sFunctionRef..': Will consider including adjacent combat units for LZ '..iLandZone..' with iCurLZValue='..iCurLZValue..'; is table of adjacent LZs empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]))..'; bConsiderAdjacentIndirect='..tostring(bConsiderAdjacentIndirect)..'; bConsiderAdjacentDF='..tostring(bConsiderAdjacentDF)..'; bConsiderAdjacentMAA='..tostring(bConsiderAdjacentMAA or false)) end
            local bConsiderGivingOrdersToUnits
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false and not(tLZData[AiBotMap.subrefbPacifistArea]) then
                for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    local tAltLZTeam = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                    if bDebugMessages == true then LOG(sFunctionRef..': iPlateau='..iPlateau..'; Base LZ='..iLandZone..'; iAdjLZ='..iAdjLZ..'; LZTValue='..repru(tAltLZTeam[AiBotMap.subrefLZTValue])..'; Is table of allied units empty='..tostring(AiBotUtilities.IsTableEmpty(tAltLZTeam[AiBotMap.subreftoLZOrWZAlliedUnits]))) end
                    if not(bLandZoneOrAdjHasUnitsWantingScout) and AiBotUtilities.IsTableEmpty(tAltLZTeam[AiBotMap.subrefLZTAlliedCombatUnits]) == false then bLandZoneOrAdjHasUnitsWantingScout = true end
                    --if (bConsiderAdjacentIndirect or bConsiderAdjacentDF) then
                    bConsiderGivingOrdersToUnits = false
                    if tAltLZTeam[AiBotMap.subrefLZTValue] < iCurLZValue and tAltLZTeam[AiBotMap.subrefLZThreatEnemyMobileDFTotal] <= 50 then bConsiderGivingOrdersToUnits = true end-- and AiBotUtilities.IsTableEmpty(tAltLZTeam[AiBotMap.subrefLZTAlliedCombatUnits]) == false then
                    if AiBotUtilities.IsTableEmpty(tAltLZTeam[AiBotMap.subrefLZTAlliedCombatUnits]) == false then
                        for iUnit, oUnit in tAltLZTeam[AiBotMap.subrefLZTAlliedCombatUnits] do

                            if bDebugMessages == true then LOG(sFunctionRef..': Deciding if we want to add adjacent oUnit '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..' with cur assignment value '..(oUnit[refiCurrentAssignmentValue] or 0)..' and cur assignemnt LZ='..(oUnit[refiCurrentAssignmentPlateauAndLZ][2] or 'nil')..'; DFRange='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; Is this a LAB='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryLightAttackBot, oUnit.UnitId))) end
                            if not(oUnit.Dead) and oUnit:GetFractionComplete() == 1 and ((oUnit[refiCurrentAssignmentValue] or 0) < iCurLZValue or (oUnit[refiCurrentAssignmentPlateauAndLZ][1] == iPlateau and oUnit[refiCurrentAssignmentPlateauAndLZ][2] == iLandZone)) and not(oUnit[refiRaidingTargetZone]) then
                                --Combat unit related
                                if not(bConsiderGivingOrdersToUnits) then
                                    if oUnit[refiCurrentAssignmentPlateauAndLZ][2] == iLandZone then
                                        oUnit[refiCurrentAssignmentValue] = -1
                                    end
                                    --Units to not consider from adjacent zones - SACUs, skirmishers, combat scouts, and long ranged units
                                elseif oUnit[AiBotUnitInfo.refiSACUWaterZoneTarget] or ((oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 10 and (oUnit[AiBotUnitInfo.refiDFRange] >= 64 or oUnit[AiBotUnitInfo.refbScoutCombatOverride] or (oUnit[AiBotUnitInfo.refiDFRange] >= 34 and EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher, oUnit.UnitId)) or (AiBotUnitInfo.GetUnitLifetimeCount(oUnit) <= 5 and EntityCategoryContains(AiBotUnitInfo.refCategoryLightAttackBot, oUnit.UnitId)))) then
                                    --Dont want long ranged DF units to receive orders from an adjacent zone as we risk them not taking into account all nearby enemies
                                    if bDebugMessages == true then LOG(sFunctionRef..': Skirmisher, combat scout or LR DF unit so only want it assigned to the zone it is in, Cur LZ assigned='..(oUnit[refiCurrentAssignmentPlateauAndLZ][2] or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; if are the same will clear assignment value') end
                                    if oUnit[refiCurrentAssignmentPlateauAndLZ][2] == iLandZone then
                                        oUnit[refiCurrentAssignmentValue] = -1
                                    end
                                else
                                    if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and not(bConsiderAdjacentDF) and oUnit[refiCurrentAssignmentPlateauAndLZ][2] == iLandZone then
                                        oUnit[refiCurrentAssignmentValue] = -1
                                    elseif (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 0 and not(bConsiderAdjacentIndirect) and oUnit[refiCurrentAssignmentPlateauAndLZ][2] == iLandZone then
                                        oUnit[refiCurrentAssignmentValue] = -1
                                    elseif (bConsiderAdjacentDF and oUnit[AiBotUnitInfo.refiDFRange] > 0) or (bConsiderAdjacentIndirect and oUnit[AiBotUnitInfo.refiIndirectRange] > 0) then
                                        bHaveCombatUnitsFromAdjZone = true
                                        table.insert(tAvailableCombatUnits, oUnit)
                                        iAvailableCombatCount = iAvailableCombatCount + 1
                                        RecordUnitAsReceivingLandZoneAssignment(oUnit, iPlateau, iLandZone, iCurLZValue)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Recording this unit from the adjacent zone '..iAdjLZ..' as being available for zone '..iLandZone) end

                                        iCurUnitThreat = nil
                                        if oUnit[AiBotUnitInfo.refiDFRange] > 0 then
                                            if oUnit[AiBotUnitInfo.refiDFRange] > iOurBestDFRange and not(EntityCategoryContains(AiBotUnitInfo.refCategoryAbsolver, oUnit.UnitId)) then iOurBestDFRange = oUnit[AiBotUnitInfo.refiDFRange] end
                                            iCurUnitThreat = AiBotUnitInfo.GetCombatThreatRating({ oUnit })
                                            iCurDFThreat = iCurDFThreat + iCurUnitThreat
                                            if iCurDFThreat > tLZTeamData[AiBotMap.subrefLZDFThreatWanted] then
                                                bConsiderAdjacentDF = false
                                                --if not(bConsiderAdjacentIndirect) and not(bConsiderAdjacentMAA) then break end
                                            end
                                        end
                                        if oUnit[AiBotUnitInfo.refiIndirectRange] > 0 then
                                            if oUnit[AiBotUnitInfo.refiIndirectRange] > iOurBestIndirectRange then iOurBestIndirectRange = oUnit[AiBotUnitInfo.refiIndirectRange] end
                                            if oUnit[AiBotUnitInfo.refiIndirectRange] > iMinIndirectRangeNeededForThreat then
                                                if not(iCurUnitThreat) then iCurUnitThreat = AiBotUnitInfo.GetCombatThreatRating({ oUnit }) end
                                                iCurIndirectThreat = iCurIndirectThreat + iCurUnitThreat
                                                if iCurIndirectThreat > tLZTeamData[AiBotMap.subrefLZIndirectThreatWanted] then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Just increased our indirect threat for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurUnitThreat='..iCurUnitThreat..'; iCurIndirectThreat after increase='..iCurIndirectThreat..'; tLZTeamData[AiBotMap.subrefLZIndirectThreatWanted]='..(tLZTeamData[AiBotMap.subrefLZIndirectThreatWanted] or 'nil')) end
                                                    bConsiderAdjacentIndirect = false
                                                    --if not(bConsiderAdjacentDF) and not(bConsiderAdjacentMAA) then break end
                                                end
                                            end
                                        end
                                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMAA, oUnit.UnitId) then
                                        if bConsiderAdjacentMAA then
                                            table.insert(tAvailableMAA, oUnit)
                                            RecordUnitAsReceivingLandZoneAssignment(oUnit, iPlateau, iLandZone, iCurLZValue)

                                            iCurUnitThreat = AiBotUnitInfo.GetAirThreatLevel({ oUnit }, false, false, true)
                                            iCurMAAThreat = iCurMAAThreat + iCurUnitThreat
                                            if iCurMAAThreat > tLZTeamData[AiBotMap.subrefLZMAAThreatWanted] then
                                                bConsiderAdjacentMAA = false
                                                --if not(bConsiderAdjacentIndirect) and not(bConsiderAdjacentDF) then break end
                                            end
                                        elseif oUnit[refiCurrentAssignmentPlateauAndLZ][2] == iLandZone then
                                            oUnit[refiCurrentAssignmentValue] = -1
                                        end
                                    end
                                end
                            end
                        end
                    end
                    --if not(bConsiderAdjacentDF) and not(bConsiderAdjacentIndirect) and not(bConsiderAdjacentMAA) then break end
                end
                --end
            end

            if AiBotUtilities.IsTableEmpty(tAvailableCombatUnits) == false then
                if tLZData[AiBotMap.subrefbPacifistArea] then
                    RetreatOtherUnits(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tAvailableCombatUnits)
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': About to manage combat units in the LZ, iOurBestIndirectRange='..(iOurBestIndirectRange or 'nil')..'; bConsiderAdjacentIndirect='..tostring(bConsiderAdjacentIndirect or false)..'; iAvailableCombatCount='..iAvailableCombatCount) end
                    --ManageCombatUnitsInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tAvailableCombatUnits, iFriendlyBestMobileDFRange, iFriendlyBestMobileIndirectRange, bWantIndirectReinforcements, tUnavailableUnitsInThisLZ, bDelayOrdersForHover, bHaveCombatUnitsFromAdjZone)
                    ManageCombatUnitsInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tAvailableCombatUnits, iOurBestDFRange, iOurBestIndirectRange, bConsiderAdjacentIndirect, tUnavailableUnitsInThisLZ, iAvailableCombatCount >= 30, bHaveCombatUnitsFromAdjZone)
                    bHaveCalledLogicForCombatUnits = true
                    bUpdateEnemyDataHere = false
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is tAvailableCombatUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableCombatUnits))..'; table of MAA empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableMAA))..'; Is table of entity filtered dow nto MAA empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMAA, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))) end
            if AiBotUtilities.IsTableEmpty(tAvailableMAA) == false then
                if tLZData[AiBotMap.subrefbPacifistArea] then
                    RetreatOtherUnits(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tAvailableMAA)
                else
                    ManageMAAInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tAvailableMAA)
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will retreat other units if any, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tOtherUnitsToRetreat))) end
            if AiBotUtilities.IsTableEmpty(tOtherUnitsToRetreat) == false then
                RetreatOtherUnits(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tOtherUnitsToRetreat)
            end
            if AiBotUtilities.IsTableEmpty(tSACUs) == false then
                ManageRASSACUsInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tSACUs)
            end
            if tSACUsToGoToWaterZone then
                SendSACUsToWaterZone(tSACUsToGoToWaterZone, tLZTeamData)
            end
            if tRaiders then
                ManageRaidersInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tRaiders)
            end

            if AiBotUtilities.IsTableEmpty(tTempOtherUnits) == false then
                --If have temp other units then manage these
                local tNearestWZ
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                    for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                        local iNearestWZRef = tSubtable[AiBotMap.subrefAWZRef]
                        tNearestWZ = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iNearestWZRef]][AiBotMap.subrefPondWaterZones][iNearestWZRef][AiBotMap.subrefMidpoint]
                        break
                    end
                end
                for iUnit, oUnit in tTempOtherUnits do
                    AiBotOrders.UpdateRecordedOrders(oUnit)
                    if oUnit[AiBotOrders.refiOrderCount] == 0 then
                        --Is this a naval unit?
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryAllNavy, oUnit.UnitId) then
                            if not(tNearestWZ) then
                                AiBotUtilities.ErrorHandler('Have naval unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' in land zone with no orders and no adjacent WZ, will move randomly')

                                local tRandomTarget = oUnit:GetPosition()
                                local iRandX = math.random(10, 30)
                                if math.random(0,1) == 0 then iRandX = iRandX * -1 end
                                local iRandZ = math.random(10, 30)
                                if math.random(0,1) == 0 then iRandZ = iRandZ * -1 end
                                tRandomTarget[1] = tRandomTarget[1] + iRandX
                                tRandomTarget[3] = tRandomTarget[3] + iRandZ
                                tRandomTarget[2] = GetSurfaceHeight(tRandomTarget[1], tRandomTarget[3])

                                AiBotOrders.IssueTrackedMove(oUnit, tRandomTarget, 5, false, 'RandNM', false)
                            else
                                AiBotOrders.IssueTrackedMove(oUnit, tNearestWZ, 5, false, 'NavInLZBckup', false)
                            end
                        else
                            AiBotUtilities.ErrorHandler('Have non naval unit with no orders that is of an unrecognised category in LZ, Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; will move randomly')
                            local tRandomTarget = oUnit:GetPosition()
                            local iRandX = math.random(10, 30)
                            if math.random(0,1) == 0 then iRandX = iRandX * -1 end
                            local iRandZ = math.random(10, 30)
                            if math.random(0,1) == 0 then iRandZ = iRandZ * -1 end
                            tRandomTarget[1] = tRandomTarget[1] + iRandX
                            tRandomTarget[3] = tRandomTarget[3] + iRandZ
                            tRandomTarget[2] = GetSurfaceHeight(tRandomTarget[1], tRandomTarget[3])
                            AiBotOrders.IssueTrackedMove(oUnit, tRandomTarget, 5, false, 'RandLM', false)
                        end
                    end
                end
            end
        else
            --No allied units - if this was flagged as an expansion LZ then clear the flag
            if tLZTeamData[AiBotMap.subrefLZCoreExpansion] then tLZTeamData[AiBotMap.subrefLZCoreExpansion] = nil end
        end
        --Update enemy ranges for this LZ and decide if this LZ still wants support, if we havent run our main combat management logic
        if bDebugMessages == true then LOG(sFunctionRef..': Will update enemy data for this LZ if are enemies in this LZ. bUpdateEnemyDataHere='..tostring(bUpdateEnemyDataHere or false)) end
        if bUpdateEnemyDataHere then
            UpdateBestEnemyRangesForThisLandZone(tLZData, tLZTeamData, iPlateau, iTeam)
            RecordClosestAdjacentEnemiesAndGetBestEnemyRange(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam)
            if bDebugMessages == true then LOG(sFunctionRef..': Updating if we want more DF or indirect units for this LZ, tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false)..'; tLZTeamData[AiBotMap.subrefLZTValue]='..(tLZTeamData[AiBotMap.subrefLZTValue] or 'nil')..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal]='..tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal]) end
            local bWantDFSupport = false
            function UpdateDFSupportForEarlyGameEngineers()
                if not(bWantDFSupport) and GetGameTimeSeconds() <= 360 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefMexUnbuiltLocations]) == false and AiBotUtilities.IsTableEmpty(tEngineers) == false and AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZData[AiBotMap.subrefMidpoint]) < AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZTeamData[AiBotMap.reftClosestFriendlyBase]) * 0.9 then
                    bWantDFSupport = true
                end
            end
            if (tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and tLZTeamData[AiBotMap.subrefLZTValue] >= 200) or tLZData[AiBotMap.subrefbPacifistArea] then
                local bWantIndirectSupport = false
                if not(tLZData[AiBotMap.subrefbPacifistArea]) then
                    if tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] > 0 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy has a structure with a DF range so want indirect fire support') end
                        bWantIndirectSupport = true
                    end
                    if tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] > 0 or tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] > 0 then bWantDFSupport = true end
                    --If havent flagged for any support but enemy has units in this LZ (presumably non-combat) and we have no combat units, then flag for support
                    if not(bWantIndirectSupport) and not(bWantDFSupport) and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] == 0 and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] == 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                        if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.MOBILE * categories.LAND, tLZTeamData[AiBotMap.subrefTEnemyUnits])) == false then
                            bWantDFSupport = true
                        elseif AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.STRUCTURE, tLZTeamData[AiBotMap.subrefTEnemyUnits])) == false then
                            if bDebugMessages == true then
                                local tEnemyBuildings = EntityCategoryFilterDown(categories.STRUCTURE, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                                for iBuilding, oBuilding in tEnemyBuildings do
                                    LOG(sFunctionRef..': Flagging we want indirect due to enemy having buildings in this zone, enemy building iBuilding='..iBuilding..'; oBuilding='..oBuilding.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBuilding))
                                end
                            end
                            bWantIndirectSupport = true
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': bWantIndirectSupport after initial checks based on enemy units in the zone='..tostring(bWantIndirectSupport)) end
                    --If enemy has PD in this or adjacent zone then flag we want indirect support
                    if not(bWantIndirectSupport) then
                        if bDebugMessages == true then LOG(sFunctionRef..': We wouldnt normally want indirect fire support for this zone, but if MML have been firing near TMD or shield then will flag we want indirect support, time since last firing near TMD or shield='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -100)) end
                        if GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -100) <= 30 then bWantIndirectSupport = true end
                        if not(bWantIndirectSupport) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Not fired near TMD recently, checking we dont have too much IF in the zone before considering adjacent zone PD, tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]='.. tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal]..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]) end
                            if tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] <= math.min(2000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech], tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] * 3) then
                                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                    local iAdjacentMobileDFThreat = 0
                                    local iAdjacentPDOrStructureThreat = 0
                                    for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                        local tAltLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                        iAdjacentMobileDFThreat = iAdjacentMobileDFThreat + (tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)
                                        if tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] > 0 then
                                            iAdjacentPDOrStructureThreat = iAdjacentPDOrStructureThreat + math.max((tAltLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0), tAltLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy has a DF building in an adjacent zone so want IF support, iAdjacentMobileDFThreat cumulative='..iAdjacentMobileDFThreat..'; Enemy PD threat='..tAltLZTeamData[AiBotMap.subrefThreatEnemyDFStructures]..'; iAdjacentPDOrStructureThreat='..iAdjacentPDOrStructureThreat..'; Enemy structure mass='..tAltLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]) end
                                            if iAdjacentMobileDFThreat >= 1000 and iAdjacentMobileDFThreat >= iAdjacentPDOrStructureThreat * 4 then
                                                --Dont build indirect fire just because of the PD Threat
                                            else
                                                bWantIndirectSupport = true break
                                            end
                                        end
                                    end
                                    if iAdjacentPDOrStructureThreat > 0 and iAdjacentPDOrStructureThreat > iAdjacentMobileDFThreat / 4 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Overall we want indirect fire due to level of PD threat') end
                                        bWantIndirectSupport = true
                                    end
                                end
                            end
                            if not(bWantIndirectSupport) then
                                if tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] then
                                    for iEntry, tPlateauAndZone in tLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] do
                                        local tAdjLZTeamData = AiBotMap.tAllPlateaus[tPlateauAndZone[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndZone[2]][AiBotMap.subrefLZTeamData][iTeam]
                                        if tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] > 0 then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy has a nearby firebase type zone so want IF support') end
                                            bWantIndirectSupport = true break
                                        end
                                    end
                                end
                            end
                        end
                    end

                    --Early game - flag that we want support if we have engineers and unclaimed mexes
                    UpdateDFSupportForEarlyGameEngineers()
                end
                UpdateIfLandZoneWantsSupport(tLZTeamData, iPlateau, iLandZone, iTeam, bWantDFSupport, bWantIndirectSupport)
                if bDebugMessages == true then LOG(sFunctionRef..': Will update if this land zone wants some DF support='..tostring(bWantDFSupport)..'; bWantIndirectSupport='..tostring(bWantIndirectSupport)) end
            else
                local bWantIndirectSupport = false
                if bDebugMessages == true then LOG(sFunctionRef..': Are there enemis in this or adjacent LZ, for iPlateau='..iPlateau..'; iLandZone='..iLandZone..'='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Do we have a valid nearby structure in other plateau='..tostring( AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere]))..'; Our highest land tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]..'; bWantDFSupport='..tostring(bWantDFSupport)) end
                if GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -100) <= 30 and not(tLZData[AiBotMap.subrefbPacifistArea]) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have had MML firing recently near TMD so want more indirect fire support') end
                    bWantIndirectSupport = true
                elseif not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and not(bWantIndirectSupport) and AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 3 then
                    bWantIndirectSupport = AiBotConditions.IsNearbyStructureThatWeCanReachWithIndirect(tLZData, tLZTeamData, iTeam)
                    if bDebugMessages == true then LOG(sFunctionRef..': bWantIndirectSupport after checking if nearby structure we can reach with indirect='..tostring(bWantIndirectSupport)) end
                end
                UpdateDFSupportForEarlyGameEngineers()
                UpdateIfLandZoneWantsSupport(tLZTeamData, iPlateau, iLandZone, iTeam, bWantDFSupport, bWantIndirectSupport)
            end
        else
            --Make sure we dont flag we want support if not called combat logic
            if not(bHaveCalledLogicForCombatUnits) then
                UpdateIfLandZoneWantsSupport(tLZTeamData, iPlateau, iLandZone, iTeam, false, false)
            end
        end
        --Handle engineers and even if no engineers still decide what engineers we would want for hte LZ
        AiBotEngineer.ConsiderLandOrWaterZoneEngineerAssignment(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tEngineers) --Should update the land zone engineer requirements, even if tEngineers itself is empty

        ManageLandZoneScouts(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tScouts, bLandZoneOrAdjHasUnitsWantingScout)

        --Update ACU in trouble incase ACU moved zones
        if tLZTeamData[AiBotMap.refbACUInTrouble] and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) then tLZTeamData[AiBotMap.refbACUInTrouble] = false end
        --Update visual based on omni
        if tLZTeamData[AiBotMap.refiOmniCoverage] > 30 then tLZTeamData[AiBotMap.refiTimeLastHadVisual] = GetGameTimeSeconds() end

        if bDebugMessages == true then LOG(sFunctionRef..': End of code, iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Is unbuild locations empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMexUnbuiltLocations]))) end

        --Update BP wanted for adjacent zones - will just have a flag in the engineer assignment that sets subrefTbWantBP to true/false so commented out the below
        --[[tLZTeamData[AiBotMap.subrefLZTAdjacentBPByTechWanted] = {[1]=0, [2]=0,[3]=0}
        tLZTeamData[AiBotMap.subrefTbWantBP] = false
        if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[AiBotMap.iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZAdjacentLandZones]) == false then
            for _, iAdjLZ in AiBotMap.tAllPlateaus[AiBotMap.iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZAdjacentLandZones] do
                for iTech = 1, 3, 1 do
                    tLZTeamData[AiBotMap.subrefLZTAdjacentBPByTechWanted] = math.max(tLZTeamData[AiBotMap.subrefLZTAdjacentBPByTechWanted][iTech], (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTBuildPowerByTechWanted][iTech] or 0))
                end
            end
        end
        for iTech = 1, 3, 1 do
            if tLZTeamData[AiBotMap.subrefLZTAdjacentBPByTechWanted][iTech] > 0 or tLZTeamData[AiBotMap.subrefLZTAdjacentBPByTechWanted][iTech] > 0 then
                tLZTeamData[AiBotMap.subrefTbWantBP] = true
            end
        end--]]
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AssignValuesToLandZones(iTeam)
    --Periodically cycles through every land zone and refreshes the unit details
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssignValuesToLandZones'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
    if aiBrain then

        if bDebugMessages == true then
            LOG(sFunctionRef..': About to start the main loop for assigning values to land zones provided we have friendly AiBot brains in the team '..iTeam..'; is table empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]))..'; will list out the plateau and LZ for each member of the team')
            local iStartPlateau, iStartLZ
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                iStartPlateau, iStartLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()])
                LOG(sFunctionRef..': Brain '..oBrain.Nickname..' has start position '..repru(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()])..' with iStartPlateau='..(iStartPlateau or 'nil')..' and iStartLZ='..(iStartLZ or 'nil'))
            end
        end
        local iCurValue
        local tFriendlyNonPDBuildings
        local bAdjacentToCoreFactory
        local iFriendlyBuildingValue
        local iCurCycleCount = 0
        local iZonesSinceWait = 0
        local iTotalLandZones = 0
        for iPlateau, tPlateauData in AiBotMap.tAllPlateaus do
            iTotalLandZones = iTotalLandZones + (tPlateauData[AiBotMap.subrefLandZoneCount] or 0)
        end
        local iZonesPerTick = math.max(1, math.floor(iTotalLandZones / 20))
        while AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false do
            iCurCycleCount = iCurCycleCount + 1 --used so we dont wait the first time, so we have recorded which zones are core zones
            local tiPlateauAndLZWithFriendlyStartPosition = {}
            local iBaseCategory
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()])
                if iPlateau and iLandZone then
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iBrain='..iBrain..'; oBrain='..oBrain.Nickname..'; Army index='..oBrain:GetArmyIndex()..'; Player start point='..repru(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()])..'; Plateau and LZ of this start point='..iPlateau..'-'..iLandZone) end
                    if not(tiPlateauAndLZWithFriendlyStartPosition[iPlateau]) then tiPlateauAndLZWithFriendlyStartPosition[iPlateau] = {} end
                    if (iLandZone or 0) > 0 then
                        tiPlateauAndLZWithFriendlyStartPosition[iPlateau][iLandZone] = true
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished recording the friendly start positions for each brain, tiPlateauAndLZWithFriendlyStartPosition='..repru(tiPlateauAndLZWithFriendlyStartPosition)) end
            iBaseCategory = categories.TECH3 * AiBotUnitInfo.refCategoryAllHQFactories + AiBotUnitInfo.refCategoryAirHQ * categories.TECH2
            --[[if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then iBaseCategory = categories.TECH3 * AiBotUnitInfo.refCategoryAllHQFactories + AiBotUnitInfo.refCategoryAirHQ * categories.TECH2
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 then iBaseCategory = AiBotUnitInfo.refCategoryAllHQFactories - categories.TECH1
            else iBaseCategory = AiBotUnitInfo.refCategoryAirFactory --Dont want to include t1 land facs since might be in a minor zone
            end--]]

            for iPlateau, tPlateauData in AiBotMap.tAllPlateaus do
                if AiBotUtilities.IsTableEmpty(tPlateauData[AiBotMap.subrefPlateauLandZones]) == false then

                    --tAllPlateaus[iPlateau][subrefPlateauLandZones][iLandZone]
                    for iLandZone, tLandZoneData in tPlateauData[AiBotMap.subrefPlateauLandZones] do
                        iZonesSinceWait = iZonesSinceWait + 1
                        local tLZTeamData = tLandZoneData[AiBotMap.subrefLZTeamData][iTeam]
                        if bDebugMessages == true then LOG(sFunctionRef..': About to refresh value of iPlateau='..iPlateau..'; iLandZone='..iLandZone..' for team '..iTeam) end
                        --Decide on value of the land zone ignoring distance:
                        --Treat each mex position as being worth 250 mass, value reclaim at 25% of the total value, and reflect the value of all non-PD in the area
                        iCurValue = tLandZoneData[AiBotMap.subrefLZOrWZMexCount] * 250 + (tLandZoneData[AiBotMap.subrefTotalMassReclaim] or 0) * 0.25
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                            tFriendlyNonPDBuildings = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure - AiBotUnitInfo.refCategoryPD, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                            iFriendlyBuildingValue = AiBotUnitInfo.GetMassCostOfUnits(tFriendlyNonPDBuildings)
                            iCurValue = iCurValue + iFriendlyBuildingValue
                        else
                            iFriendlyBuildingValue = 0
                        end

                        --Increase for value of enemy mexes if moddist >=25%
                        if tLandZoneData[AiBotMap.refiModDistancePercent] >= 0.25 and tLandZoneData[AiBotMap.subrefLZOrWZMexCount] > 0 then
                            iCurValue = iCurValue + math.min(0, (tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) - (tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0) * 3)
                        end

                        if tLZTeamData[AiBotMap.refbACUInTrouble] then
                            iCurValue = iCurValue + AiBotACU.GetValueIncreaseForACUInTrouble(iTeam)
                        end

                        --Record the value
                        tLZTeamData[AiBotMap.subrefLZTValue] = iCurValue
                        tLZTeamData[AiBotMap.subrefLZSValue] = iFriendlyBuildingValue
                        tLZTeamData[AiBotMap.subrefLZbCoreBase] = nil

                        --Is this a core base land zone?
                        if bDebugMessages == true then LOG(sFunctionRef..': iCurValue based on this zone='..iCurValue..'; iFriendlyBuildingValue='..iFriendlyBuildingValue..'; Checking if we are a friendly land zone - tiPlateauAndLZWithFriendlyStartPosition='..repru(tiPlateauAndLZWithFriendlyStartPosition)..'; Is table of allied units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))..'; tLZTeamData[AiBotMap.subrefLZSValue] (if nil will ignore core zone)='..(tLZTeamData[AiBotMap.subrefLZSValue] or 0)) end
                        if (tiPlateauAndLZWithFriendlyStartPosition[iPlateau][iLandZone] or tLZTeamData[AiBotMap.subrefbCoreBaseOverride]) and ((tLZTeamData[AiBotMap.subrefLZSValue] or 0) > 0 or GetGameTimeSeconds() <= 300 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] <= 1) then
                            tLZTeamData[AiBotMap.subrefLZbCoreBase] = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Core LZ='..iLandZone..' for plateau '..iPlateau..'; All adjacent zones='..repru(tLandZoneData[AiBotMap.subrefLZAdjacentLandZones])..'; tiPlateauAndLZWithFriendlyStartPosition[iPlateau][iLandZone]=nil='..tostring(tiPlateauAndLZWithFriendlyStartPosition[iPlateau][iLandZone] == nil)..'; tLZTeamData[AiBotMap.subrefbCoreBaseOverride]='..tostring(tLZTeamData[AiBotMap.subrefbCoreBaseOverride] or false)..'; Island ref='..(tLandZoneData[AiBotMap.subrefLZIslandRef] or 'nil')) end
                            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateau]) then
                                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau] = {} end
                                AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateau] = {}
                            end
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateau][iLandZone] = true
                            --adjacent zones iwth lots of mexes in them and high mex count - consider treating as a core base
                        elseif tLandZoneData[AiBotMap.subrefLZOrWZMexCount] >= 4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                            --Are we adjacent to a core zone and we contain a factory or high value unit? If so then treat us as a core LZ
                            bAdjacentToCoreFactory = false
                            if AiBotUtilities.IsTableEmpty(tLandZoneData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for iEntry, iAdjLZ in tLandZoneData[AiBotMap.subrefLZAdjacentLandZones] do
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we are adjacent to a core LZ, iAdjLZ='..iAdjLZ..'; Is AdjLZ a core LZ='..tostring(tPlateauData[AiBotMap.subrefPlateauLandZones][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase])) end
                                    if AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase] then
                                        bAdjacentToCoreFactory = true
                                        break
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': bAdjacentToCoreFactory='..tostring(bAdjacentToCoreFactory)..'; Is table of factory HQs empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(iBaseCategory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))) end
                                if bAdjacentToCoreFactory and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(iBaseCategory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Are adjacent to a core factory, and have iBaseCategory units in this zone, iLandZone='..iLandZone..'; iPlateau='..iPlateau) end
                                    tLZTeamData[AiBotMap.subrefLZbCoreBase] = true
                                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateau]) then
                                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau] = {} end
                                        AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateau] = {}
                                    end
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateau][iLandZone] = true
                                end
                            end
                        end
                        --'Rebuild former core base of a dead teammate' logic - handle this via separate function that rechecks every 30s if we want to reflag as a core base, ReviewTreatingOldBaseAsCoreBase


                        if iZonesSinceWait >= iZonesPerTick and iCurCycleCount > 1 then --dont want to wait the first time, as on large maps can mean a delay in the ACU building
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            WaitTicks(1)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                            iZonesSinceWait = 0
                        end
                    end
                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(1) --Needed to avoid infinite loop if are no LZs (e.g. on a water map)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
    else
        AiBotUtilities.ErrorHandler('No active AiBot brain')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageAllLandZones(aiBrain, iTeam, bIgnoreMinorPlateaus, iCurMinorPlateauCycleRef)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageAllLandZones'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iLastRefreshCount = (tLZRefreshCountByTeam[iTeam] or 1)
    local iCurRefreshCount = 0
    local iTicksToSpreadOver = iTicksPerLandCycle --Default is 10, i.e. 1 second
    local iRefreshThreshold = math.max(2, math.ceil(iLastRefreshCount * 0.95 / iTicksToSpreadOver))
    local iCurCycleRefreshCount = 0
    local iCurTicksWaited = 0

    if bDebugMessages == true then
        LOG(sFunctionRef..': Start of code, Time='..GetGameTimeSeconds()..'; iTeam='..iTeam..'; If have an ACU will list its plateau and land zone. iRefreshThreshold='..iRefreshThreshold..'; iLastRefreshCount='..iLastRefreshCount..'; iTicksToSpreadOver='..iTicksToSpreadOver)
        local tOurACU = aiBrain:GetListOfUnits(categories.COMMAND, false, true)
        if AiBotUtilities.IsTableEmpty(tOurACU) == false then
            local iACUPlateau, iACULZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tOurACU[1]:GetPosition(), true, tOurACU[1])
            LOG(sFunctionRef..': ACU is at plateau '..iACUPlateau..'; LZ='..iACULZ)
        end
    end

    --Cycle through land zones
    local bAbort = false
    for iPlateau, tPlateauData in AiBotMap.tAllPlateaus do
        if bIgnoreMinorPlateaus or not(tPlateauData[AiBotMap.subrefiMinorCycleRef]) or tPlateauData[AiBotMap.subrefiMinorCycleRef] == iCurMinorPlateauCycleRef then
            RefreshLandRallyPoints(iTeam, iPlateau)

            if AiBotUtilities.IsTableEmpty(tPlateauData[AiBotMap.subrefPlateauLandZones]) == false then
                if bDebugMessages == true then
                    LOG(sFunctionRef..': About to cycle through every land zone in plateau '..iPlateau..'; subrefLandZoneCount='..tPlateauData[AiBotMap.subrefLandZoneCount])
                end
                for iLandZone, tLandZoneDataByTeam in tPlateauData[AiBotMap.subrefPlateauLandZones] do
                    local tLZTeamData = tLandZoneDataByTeam[AiBotMap.subrefLZTeamData][iTeam]

                    if bDebugMessages == true then
                        LOG(sFunctionRef..': iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Is table of enemey units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Is table of friendly units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))..'; GameTime='..GetGameTimeSeconds()..'; Is table of enemy air units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]))..'; iTeam='..iTeam)
                    end
                    --First check all units in here are alive
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                        iCurCycleRefreshCount = iCurCycleRefreshCount + 1
                        --UpdateUnitPositionsAndLandZone(aiBrain, tUnits,                               iTeam, iRecordedPlateau, iRecordedLandZone, bUseLastKnownPosition, bAreAirUnits, tLZTeamData, bUpdateTimeOfLastEnemyPositionCheck, bAreEnemyUnits)
                        if bDebugMessages == true then LOG(sFunctionRef..': Just ran updateunitpositions for enemy units in this zone') end
                    end
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false then
                        iCurCycleRefreshCount = iCurCycleRefreshCount + 1
                    end
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        iCurCycleRefreshCount = iCurCycleRefreshCount + 1
                    end

                    ForkThread(ManageSpecificLandZone, aiBrain, iTeam, iPlateau, iLandZone)
                    iCurCycleRefreshCount = iCurCycleRefreshCount + 1

                    if iCurCycleRefreshCount >= iRefreshThreshold then
                        iCurRefreshCount = iCurRefreshCount + iCurCycleRefreshCount
                        iCurCycleRefreshCount = 0
                        if iCurTicksWaited < iTicksToSpreadOver then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            WaitTicks(1)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                            iCurTicksWaited = iCurTicksWaited + 1
                            if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting 1 tick as reached iCurCycleRefreshCount='..iCurCycleRefreshCount..'; aiBrain.AiBotIsDefeated='..tostring(aiBrain.AiBotIsDefeated or false)..'; aiBrain='..(aiBrain.Nickname or 'nil')) end
                            if aiBrain.AiBotIsDefeated or not(aiBrain) then
                                aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                                if not(aiBrain) or aiBrain.AiBotIsDefeated then
                                    bAbort = true
                                    break
                                end
                            end
                        end
                    end
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Warning - no land zones found for plateau '..iPlateau) end
            end
        end
        if bAbort then break end
    end
    iCurRefreshCount = iCurRefreshCount + iCurCycleRefreshCount
    if bDebugMessages == true then LOG(sFunctionRef..': About to update refresh count now that completed loop, iCurRefreshCount='..(iCurRefreshCount or 'nil')..'; tLZRefreshCountByTeam[iTeam] before updating to reflect this='..(tLZRefreshCountByTeam[iTeam] or 'nil')) end
    tLZRefreshCountByTeam[iTeam] = iCurRefreshCount

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function LandZoneOverseer(iTeam)
    --Periodically cycles through every land zone and refreshes the unit details
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'LandZoneOverseer'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
    if aiBrain then
        if aiBrain.HostileCampaignAI and tonumber(ScenarioInfo.Options.CmpAIDelay) > GetGameTimeSeconds() + 1.1 then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(tonumber(ScenarioInfo.Options.CmpAIDelay) - GetGameTimeSeconds() -1.1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end

        if bDebugMessages == true then LOG(sFunctionRef..': About to start the main loop for land zones provided we have friendly AiBot brains in the team '..iTeam..'; is table empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]))) end
        ForkThread(AssignValuesToLandZones, iTeam)

        local iWaitCount = 0
        while not(AiBotMap.bMapLandSetupComplete) or GetGameTimeSeconds() <= 5.1 or ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or AiBotUtilities.bSteamActive) and GetGameTimeSeconds() <= 6) do
            iWaitCount = iWaitCount + 1
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if iWaitCount >= 200 then AiBotUtilities.ErrorHandler('Have waited more than '..iWaitCount..' and map setup not complete, will proceed but likely AI wont work') break end
        end

        local iMinorCycleCount = 0
        while AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false do
            if ScenarioInfo.OpEnded and AiBotMap.bIsCampaignMap and GetGameTimeSeconds() <= 120 then
                while ScenarioInfo.OpEnded do
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitTicks(1)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                end
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) then break end
            end
            iMinorCycleCount = iMinorCycleCount + 1
            if iMinorCycleCount > 10 then iMinorCycleCount = 1 end
            if bDebugMessages == true then LOG(sFunctionRef..': Will call logic to refresh every unit in a land zone, iMinorCycleCount='..iMinorCycleCount) end
            ForkThread(ManageAllLandZones, aiBrain, iTeam, (GetGameTimeSeconds() <= 10 or AiBotMap.iPlateauCount <= 2000), iMinorCycleCount)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(iTicksPerLandCycle)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if aiBrain.AiBotIsDefeated and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
                aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
            end
            if bDebugMessages == true then LOG(sFunctionRef..': About to restart the loop for team '..iTeam..'; aiBrain referred to='..(aiBrain.Nickname or 'nil')..'; Is table of active aibot brains='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]))) end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetLandZoneToRunTo(iTeam, iPlateau, iCurLandZone, sPathing, tOptionalStartPosition, tOptionalEnemyPositionToRunFrom)
    --Returns cur LZ if no LZ to run to, otherwise returns the land zone we think is best to run to from iCurLandZone
    --tOptionalStartPosition - if nil then will use midpoint of iCurLandZone
    --tOptionalEnemyPositionToRunFrom - if this is specified, then will pick al ocation based on angle from the start position to the location vs the start position angle to the enemy position to run to (so we run in the opposite direction to the enemy position if the opposite direction LZ is safe)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetLandZoneToRunTo'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': iTeam='..iTeam..'; iPlateau='..iPlateau..'; iCurLandZone='..iCurLandZone..'; sPathing='..sPathing..'; tOptionalStartPosition='..repru(tOptionalStartPosition)..'; tOptionalEnemyPositionToRunFrom='..repru(tOptionalEnemyPositionToRunFrom)) end

    local tLZShortlist = {}
    --See if we have any adjacent LZs with no enemy combat units in them - if so, then run here
    if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iCurLandZone][AiBotMap.subrefLZAdjacentLandZones]) == false then
        for _, iAdjacentLZ in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iCurLandZone][AiBotMap.subrefLZAdjacentLandZones] do
            if AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjacentLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal] == 0 then
                table.insert(tLZShortlist, iAdjacentLZ)
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(tLZShortlist) then
        --Add each team start point on the same plateau
        local iPotentialPlateau, iPotentialLZ
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                iPotentialPlateau, iPotentialLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()])
                if iPotentialPlateau == iPlateau and not(iPotentialLZ == iCurLandZone) then
                    table.insert(tLZShortlist, iPotentialLZ)
                end
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Getting LZ to run to from, iTeam='..iTeam..'; iPlateau='..iPlateau..'; iCurLandZone='..iCurLandZone..'; sPathing='..sPathing..'; tLZShortlist='..repru(tLZShortlist)) end
    if AiBotUtilities.IsTableEmpty(tLZShortlist) then
        --Nowhere to run to
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return iCurLandZone
    else
        local tStartPoint = (tOptionalStartPosition or AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iCurLandZone][AiBotMap.subrefMidpoint])
        local iPreferredLZRef
        if tOptionalEnemyPositionToRunFrom then
            --Go to the angle furthest in angle away from the nearest enemy
            local iAngleToEnemy = AiBotUtilities.GetAngleFromAToB(tStartPoint, tOptionalEnemyPositionToRunFrom)
            local iCurAngleDif
            local iHighestAngleDif = 0
            for _, iPossibleLZ in tLZShortlist do
                iCurAngleDif = AiBotUtilities.GetAngleDifference(iAngleToEnemy, AiBotUtilities.GetAngleFromAToB(tStartPoint, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iPossibleLZ][AiBotMap.subrefMidpoint]))
                if iCurAngleDif > iHighestAngleDif then
                    iHighestAngleDif = iCurAngleDif
                    iPreferredLZRef = iPossibleLZ
                end
            end
        else
            --dont have angle to nearest enemy so just pick the closest land zone

            local iClosestLZDistance = 100000
            local iClosestLZRef
            local iCurDist
            for _, iPossibleLZ in tLZShortlist do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering distance from tStartPoint to iPossibleLZ '..(iPossibleLZ or 'nil')..'; Midpoint of that LZ='..repru(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iPossibleLZ][AiBotMap.subrefMidpoint])..'; iCurDist='..(AiBotUtilities.GetTravelDistanceBetweenPositions(tStartPoint, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iPossibleLZ][AiBotMap.subrefMidpoint], sPathing) or 'nil')) end
                iCurDist = AiBotUtilities.GetTravelDistanceBetweenPositions(tStartPoint, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iPossibleLZ][AiBotMap.subrefMidpoint], sPathing)
                --Backup - if the built in pathfinding doesnt htink we can path there (e.g. we are by a cliff) then use straight line distance
                if not(iCurDist) then iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tStartPoint, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iPossibleLZ][AiBotMap.subrefMidpoint]) + 30 end

                if iCurDist < iClosestLZDistance then
                    iClosestLZDistance = iCurDist
                    iPreferredLZRef = iPossibleLZ
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return iPreferredLZRef
    end
end

function IsLandZonePathSafe(iPlateau, tLZData, iTeam, iPathingRef, bIslandPathing)
    --More performant version of IsItSafeToPathBetweenLandZones, to check if safe to path from the tLZData land zone to the tAltLZ land zone, based on iPathingRef for tLZData
    --bIslandPathing shoudl be true if are trying to path to an island (i.e. that a land unit cant get to), so the correct table references are used
    if bIslandPathing then
        for _, iLandZoneRef in tLZData[AiBotMap.subrefLZPathingToOtherIslands][iPathingRef][AiBotMap.subrefIslandLZPath] do
            --Are there any units in this LZ that are dangerous?
            if AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZoneRef][iTeam][AiBotMap.subrefbDangerousEnemiesInThisLZ] then
                return false
            end
        end
    else
        if tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iPathingRef][AiBotMap.subrefLZPath] then
            for _, iLandZoneRef in tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iPathingRef][AiBotMap.subrefLZPath] do
                --Are there any units in this LZ that are dangerous?
                if AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZoneRef][iTeam][AiBotMap.subrefbDangerousEnemiesInThisLZ] then
                    return false
                end
            end
        end
    end
    return true
end

