function DrawReclaimSegmentsInLandZone(iPlateau, iLandZone, bIncludeMassValues)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DrawReclaimSegmentsInLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
    local rCurRect
    if bDebugMessages == true then LOG(sFunctionRef..': About to draw reclaim segnemtns for iPlateau '..iPlateau..' iLandZone '..iLandZone..'; Table of reclaim segments='..repru(tLZData[AiBotMap.subrefReclaimSegments])) end

    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefReclaimSegments]) == false then
        for iCount, tSegmentXZ in tLZData[AiBotMap.subrefReclaimSegments] do
            rCurRect = AiBotUtilities.GetRectAroundLocation(AiBotMap.tReclaimAreas[tSegmentXZ[1]][tSegmentXZ[2]][AiBotMap.refReclaimSegmentMidpoint], AiBotMap.iReclaimSegmentSizeX * 0.5)
            AiBotUtilities.DrawRectangle(rCurRect)
            if bIncludeMassValues then LOG(sFunctionRef..': Considering segment '..reprs(tSegmentXZ)..'; Total mass reclaim='..AiBotMap.tReclaimAreas[tSegmentXZ[1]][tSegmentXZ[2]][AiBotMap.refReclaimTotalMass]..'; Signif mass reclaim='..AiBotMap.tReclaimAreas[tSegmentXZ[1]][tSegmentXZ[2]][AiBotMap.refReclaimTotalSignificantMass]) end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function UpdateRecordedAllPlayerOmni(oRadar, bDestroyed)
    local oBP = oRadar:GetBlueprint()
    local iRadarOmni =  (oBP.Intel.OmniRadius or 0)

    if iRadarOmni > 0 then
        local iMaxZoneDistance = iRadarOmni + 50

        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oRadar:GetPosition())
        if iPlateau and iLandZone then
            local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
            if tLZData then
                function UpdateOmniCoverageForZone(iCurPlateauOrPond, iCurLZOrWZ, bIsWaterZone)
                    local tCurLZOrWZData
                    if bIsWaterZone then
                        tCurLZOrWZData = AiBotMap.tPondDetails[iCurPlateauOrPond][AiBotMap.subrefPondWaterZones][iCurLZOrWZ]
                    else tCurLZOrWZData = AiBotMap.tAllPlateaus[iCurPlateauOrPond][AiBotMap.subrefPlateauLandZones][iCurLZOrWZ]
                    end

                    --Remove oRadar from the table of omni in this zone
                    if bDestroyed then
                        if AiBotUtilities.IsTableEmpty(tCurLZOrWZData[AiBotMap.reftoAllOmniRadar]) == false then
                            --Update the table
                            local iEntryCount = table.getn(tCurLZOrWZData[AiBotMap.reftoAllOmniRadar])
                            for iCurEntry = iEntryCount, 1, -1 do
                                local oUnit = tCurLZOrWZData[AiBotMap.reftoAllOmniRadar][iCurEntry]
                                if not(AiBotUnitInfo.IsUnitValid(oUnit)) or oUnit == oRadar then
                                    table.remove(tCurLZOrWZData[AiBotMap.reftoAllOmniRadar], iCurEntry)
                                end
                            end
                        end
                    else
                        local bAddToTable = true
                        if not(tCurLZOrWZData[AiBotMap.reftoAllOmniRadar]) then tCurLZOrWZData[AiBotMap.reftoAllOmniRadar] = {}
                        else
                            for iUnit, oUnit in tCurLZOrWZData[AiBotMap.reftoAllOmniRadar] do
                                if oUnit == oRadar then bAddToTable = false break end
                            end
                        end
                        if bAddToTable and iRadarOmni - AiBotUtilities.GetDistanceBetweenPositions(oRadar:GetPosition(), tCurLZOrWZData[AiBotMap.subrefMidpoint]) > 0 then
                            table.insert(tCurLZOrWZData[AiBotMap.reftoAllOmniRadar], oRadar)
                        end
                    end

                    local iBestOmniCoverage = 0
                    if AiBotUtilities.IsTableEmpty(tCurLZOrWZData[AiBotMap.reftoAllOmniRadar]) == false then
                        local iCurOmniCoverage
                        for iUnit, oUnit in tCurLZOrWZData[AiBotMap.reftoAllOmniRadar] do
                            iCurOmniCoverage = (oUnit:GetBlueprint().Intel.OmniRadius or 0)
                            if iCurOmniCoverage > iBestOmniCoverage  then
                                iCurOmniCoverage = math.max(0, iCurOmniCoverage - AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tCurLZOrWZData[AiBotMap.subrefMidpoint]))
                                if iCurOmniCoverage > iBestOmniCoverage then
                                    iBestOmniCoverage = iCurOmniCoverage
                                end
                            end
                        end

                    end
                    tCurLZOrWZData[AiBotMap.refiAllOmniCoverage] = iBestOmniCoverage
                end

                UpdateOmniCoverageForZone(iPlateau, iLandZone, false)
                AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData)
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                    for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                        if tSubtable[AiBotMap.subrefiDistance] > iMaxZoneDistance then break end
                        UpdateOmniCoverageForZone(tSubtable[AiBotMap.subrefiPlateauOrPond], tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], tSubtable[AiBotMap.subrefbIsWaterZone])
                    end
                end
            end
        end
    end
end

function UpdateRadarCoverageForDestroyedRadar(oRadar, iOptionalTeamOverride)

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateRadarCoverageForDestroyedRadar'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --iOptionalTeamOverride - if specified, will only update for this team


    --First update land zones
    if bDebugMessages == true then LOG(sFunctionRef..': oRadar has been destroyed, oRadar='..oRadar.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRadar)..'; Time='..GetGameTimeSeconds()..'; Is table of zones covered by team empty='..tostring(AiBotUtilities.IsTableEmpty(oRadar[reftiRadarPlateauAndLandZonesCoveredByTeam]))) end
    if AiBotUtilities.IsTableEmpty(oRadar[reftiRadarPlateauAndLandZonesCoveredByTeam]) == false then
        for iTeam, tRadarData in oRadar[reftiRadarPlateauAndLandZonesCoveredByTeam] do
            --local aiBrain = oRadar:GetAIBrain()
            --local iTeam = aiBrain.AiBotTeam
            if not(iOptionalTeamOverride) or iOptionalTeamOverride == iTeam then
                local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                if aiBrain then
                    for iEntry, tiPlateauAndLZ in tRadarData do
                        local tLZData = AiBotMap.tAllPlateaus[tiPlateauAndLZ[1]][AiBotMap.subrefPlateauLandZones][tiPlateauAndLZ[2]]
                        if tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar] == oRadar then
                            tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar] = nil
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision] then
                                tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiRadarCoverage] = 5000
                                tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiOmniCoverage] = 5000
                            else
                                tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiRadarCoverage] = 0
                                tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiOmniCoverage] = 0
                            end

                            local tNearbyRadar = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryRadar, tLZData[AiBotMap.subrefMidpoint], 600, 'Ally')
                            local iCurIntelRange
                            local iBestIntelRange = 0
                            local oBestRadar
                            local iCurDist
                            local oBP
                            local iCurOmniRange
                            local iBestOmniRange = 0
                            if AiBotUtilities.IsTableEmpty(tNearbyRadar) == false then
                                for iUnit, oUnit in tNearbyRadar do
                                    oBP = oUnit:GetBlueprint()
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                    iCurIntelRange = (oBP.Intel.RadarRadius or 0) - iCurDist
                                    iCurOmniRange = (oBP.Intel.OmniRadius or 0) - iCurDist
                                    if iCurIntelRange > iBestIntelRange then
                                        iBestIntelRange = iCurIntelRange
                                        oBestRadar = oUnit
                                    end
                                    if iCurOmniRange > iBestOmniRange then
                                        iBestOmniRange = iCurOmniRange
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering nearby radar units for P='..tiPlateauAndLZ[1]..'Z'..tiPlateauAndLZ[2]..'; Is table of nearby radar empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyRadar))..'; oBestRadar='..(oBestRadar.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBestRadar) or 'nil')) end
                            if oBestRadar then
                                tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar] = oBestRadar
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision] then
                                    tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiRadarCoverage] = 5000
                                    tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiOmniCoverage] = 5000
                                else
                                    tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiRadarCoverage] = iBestIntelRange
                                    tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiOmniCoverage] = iBestOmniRange
                                end
                                if not(oBestRadar[reftiRadarPlateauAndLandZonesCoveredByTeam]) then oBestRadar[reftiRadarPlateauAndLandZonesCoveredByTeam] = {} end
                                if not(oBestRadar[reftiRadarPlateauAndLandZonesCoveredByTeam][iTeam]) then oBestRadar[reftiRadarPlateauAndLandZonesCoveredByTeam][iTeam] = {} end
                                table.insert(oBestRadar[reftiRadarPlateauAndLandZonesCoveredByTeam][iTeam], {tiPlateauAndLZ[1], tiPlateauAndLZ[2]})
                            end
                        end
                    end
                end
            end
        end
    end
    --Then update water zones:
    if AiBotUtilities.IsTableEmpty(oRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam]) == false then
        for iTeam, tRadarData in oRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam] do
            --local aiBrain = oRadar:GetAIBrain()
            --local iTeam = aiBrain.AiBotTeam
            if not(iOptionalTeamOverride) or iOptionalTeamOverride == iTeam then
                local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                if aiBrain then
                    local iPond
                    for iEntry, iWaterZone in tRadarData do
                        iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
                        local tWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone]
                        local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                        if tWZTeamData[AiBotMap.refoBestRadar] == oRadar then
                            tWZTeamData[AiBotMap.refoBestRadar] = nil
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision] then
                                tWZTeamData[AiBotMap.refiRadarCoverage] = 5000
                                tWZTeamData[AiBotMap.refiOmniCoverage] = 5000
                            else
                                tWZTeamData[AiBotMap.refiRadarCoverage] = 0
                                tWZTeamData[AiBotMap.refiOmniCoverage] = 0
                            end
                            local tNearbyRadar = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryRadar, tWZData[AiBotMap.subrefMidpoint], 600, 'Ally')
                            local iCurIntelRange
                            local iBestIntelRange = 0
                            local oBestRadar
                            local iCurDist
                            local oBP
                            local iCurOmniRange
                            local iBestOmniRange = 0
                            if AiBotUtilities.IsTableEmpty(tNearbyRadar) == false then
                                for iUnit, oUnit in tNearbyRadar do
                                    oBP = oUnit:GetBlueprint()
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tWZData[AiBotMap.subrefMidpoint])
                                    iCurIntelRange = (oBP.Intel.RadarRadius or 0) - iCurDist
                                    if iCurIntelRange > iBestIntelRange then
                                        iBestIntelRange = iCurIntelRange
                                        oBestRadar = oUnit
                                    end
                                    iCurOmniRange = (oBP.Intel.OmniRadius or 0) - iCurDist
                                    if iCurOmniRange > iBestOmniRange then
                                        iBestOmniRange = iCurOmniRange
                                    end
                                end
                            end
                            if oBestRadar then
                                tWZTeamData[AiBotMap.refoBestRadar] = oBestRadar
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision] then
                                    tWZTeamData[AiBotMap.refiRadarCoverage] = 5000
                                    tWZTeamData[AiBotMap.refiOmniCoverage] = 5000
                                else
                                    tWZTeamData[AiBotMap.refiRadarCoverage] = iBestIntelRange
                                    tWZTeamData[AiBotMap.refiOmniCoverage] = iBestOmniRange
                                end
                                if not(oBestRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam]) then oBestRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam] = {} end
                                if not(oBestRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam][iTeam]) then oBestRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam][iTeam] = {} end
                                table.insert(oBestRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam][iTeam], iWaterZone)
                            end
                        end
                    end
                end
            end
        end
    end
    --Then update enemy recorded omni range
    UpdateRecordedAllPlayerOmni(oRadar, true)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateZoneIntelForRadar(oRadar)
    --If just built radar then want to update all land zones for the team to indicate the intel coverage
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateZoneIntelForRadar'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iTeam = oRadar:GetAIBrain().AiBotTeam
    if bDebugMessages == true then LOG(sFunctionRef..': Just built radar '..oRadar.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRadar)..' owned by '..oRadar:GetAIBrain().Nickname..' with AiBotTeam '..iTeam..'; is the table of active aibot brains for this team empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]))..'; Time='..GetGameTimeSeconds()) end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
        if not(oRadar['AiBotUpdatedIntel']) then
            oRadar['AiBotUpdatedIntel'] = true
            local oBP = oRadar:GetBlueprint()
            local iIntelRange = (oBP.Intel.RadarRadius or 0)
            local iCurIntelRange
            local iOmniRange = (oBP.Intel.OmniRadius or 0)
            if bDebugMessages == true then LOG(sFunctionRef..': Radar intel range='..iIntelRange) end
            if iIntelRange > 0 or iOmniRange > 0 then
                --Update land zones:
                local iBasePlateau, iBaseZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oRadar:GetPosition())
                local bImprovedIntelCoverageOfZone = false
                local tPotentiallyObsoleteRadar = {}
                for iPlateau, tPlateauSubtable in AiBotMap.tAllPlateaus do
                    for iLandZone, tLZData in tPlateauSubtable[AiBotMap.subrefPlateauLandZones] do
                        if tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiRadarCoverage] < iIntelRange then
                            iCurIntelRange = iIntelRange - AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oRadar:GetPosition())
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iPlateau '..iPlateau..' Land zone '..iLandZone..'; iCurIntelRange factoring in distance='..iCurIntelRange..'; Distance='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oRadar:GetPosition())..'; LZ current radar coverage='..tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiRadarCoverage]..'; tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar]='..(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar]) or 'nil')) end
                            if iCurIntelRange > tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiRadarCoverage] then
                                if iCurIntelRange > iIntelThresholdForPriorityScout then bImprovedIntelCoverageOfZone = true end
                                --First remove this plateau and LZ from the existing radar if there was one
                                if AiBotUnitInfo.IsUnitValid(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar]) then
                                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar][reftiRadarPlateauAndLandZonesCoveredByTeam][iTeam]) == false then
                                        for iEntry, tiPlateauAndLZ in tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar][reftiRadarPlateauAndLandZonesCoveredByTeam][iTeam] do
                                            if tiPlateauAndLZ[1] == iPlateau and tiPlateauAndLZ[2] == iLandZone then
                                                table.remove(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar][reftiRadarPlateauAndLandZonesCoveredByTeam][iTeam], iEntry)
                                                break
                                            end
                                        end
                                    end
                                    if not(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar]:IsUnitState('Upgrading')) then
                                        table.insert(tPotentiallyObsoleteRadar, tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar])
                                        if bDebugMessages == true then LOG(sFunctionRef..': Added radar '..tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar])..' to potentially obsolete table') end
                                    end
                                end
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision] then
                                    tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiRadarCoverage] = 5000
                                    tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiOmniCoverage] = 5000
                                else
                                    tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiRadarCoverage] = iCurIntelRange
                                    tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar] = oRadar
                                end
                                if not(oRadar[reftiRadarPlateauAndLandZonesCoveredByTeam]) then oRadar[reftiRadarPlateauAndLandZonesCoveredByTeam] = {} end
                                if not(oRadar[reftiRadarPlateauAndLandZonesCoveredByTeam][iTeam]) then oRadar[reftiRadarPlateauAndLandZonesCoveredByTeam][iTeam] = {} end
                                table.insert(oRadar[reftiRadarPlateauAndLandZonesCoveredByTeam][iTeam], {iPlateau, iLandZone})
                                if bDebugMessages == true then LOG(sFunctionRef..': Finished udpating for the new intel range, tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiRadarCoverage]='..tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiRadarCoverage]) end
                            end
                        end
                        if iOmniRange > (tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiOmniCoverage] or 0) then
                            tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiOmniCoverage] = math.max((tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiOmniCoverage] or 0), iOmniRange - AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oRadar:GetPosition()))
                        end
                    end
                end
                --Update any units wanting priority land scouts in cae they now have good enough coverage
                local tiLandSubteams = {}
                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                    tiLandSubteams[oBrain.AiBotLandSubteam] = true
                end

                for iLandSubteam, _ in tiLandSubteams do
                    if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout]) then
                        for iCurEntry = table.getn(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout]), 1, -1 do
                            local oRecorded =  AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout][iCurEntry]
                            if oRecorded[refiCurrentAssignmentPlateauAndLZ][2] then
                                local tCurLZTeamData = AiBotMap.tAllPlateaus[oRecorded[refiCurrentAssignmentPlateauAndLZ][1]][AiBotMap.subrefPlateauLandZones][oRecorded[refiCurrentAssignmentPlateauAndLZ][2]][AiBotMap.subrefLZTeamData][iTeam]
                                if tCurLZTeamData[AiBotMap.refiRadarCoverage] >= iIntelThresholdForPriorityScout then
                                    oRecorded[refbFlaggedForPriorityScout] = nil
                                    oRecorded[refiTimeLastBuiltLandScoutForUnit] = nil
                                    table.remove(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout], iCurEntry)
                                end
                            end
                        end
                    end
                end

                --Update water zones
                for iPond, tPondSubtable in AiBotMap.tPondDetails do
                    if AiBotUtilities.IsTableEmpty(tPondSubtable[AiBotMap.subrefPondWaterZones]) == false then
                        for iWaterZone, tWZData in tPondSubtable[AiBotMap.subrefPondWaterZones] do
                            local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                            if tWZTeamData[AiBotMap.refiRadarCoverage] < iIntelRange then
                                iCurIntelRange = iIntelRange - AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], oRadar:GetPosition())
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering iPond '..iPond..' Water zone '..iWaterZone..'; iCurIntelRange factoring in distance='..iCurIntelRange..'; Distance='..AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], oRadar:GetPosition())..'; WZ current radar coverage='..tWZData[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.refiRadarCoverage]) end
                                if iCurIntelRange > tWZData[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.refiRadarCoverage] then
                                    --First remove this WZ from the existing (worse) radar if there was one
                                    if AiBotUnitInfo.IsUnitValid(tWZTeamData[AiBotMap.refoBestRadar]) then
                                        if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.refoBestRadar][AiBotNavy.reftiRadarWaterZonesCoveredByTeam][iTeam]) == false then
                                            for iEntry, iRecordedWaterZone in tWZTeamData[AiBotMap.refoBestRadar][AiBotNavy.reftiRadarWaterZonesCoveredByTeam][iTeam] do
                                                if iRecordedWaterZone == iWaterZone then
                                                    table.remove(tWZTeamData[AiBotMap.refoBestRadar][AiBotNavy.reftiRadarWaterZonesCoveredByTeam][iTeam], iEntry)
                                                    break
                                                end
                                            end
                                        end
                                    end
                                    --Now assign this WZ to this radar as providing the best coverage
                                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision] then
                                        tWZTeamData[AiBotMap.refiRadarCoverage] = 5000
                                        tWZTeamData[AiBotMap.refiOmniCoverage] = 5000
                                    else
                                        tWZTeamData[AiBotMap.refiRadarCoverage] = iCurIntelRange
                                    end
                                    tWZTeamData[AiBotMap.refoBestRadar] = oRadar
                                    if not(oRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam]) then oRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam] = {} end
                                    if not(oRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam][iTeam]) then oRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam][iTeam] = {} end
                                    table.insert(oRadar[AiBotNavy.reftiRadarWaterZonesCoveredByTeam][iTeam], iWaterZone)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Finished udpating for the new intel range, iWaterZone='..iWaterZone..'; tWZTeamData[AiBotMap.refiRadarCoverage]='..tWZTeamData[AiBotMap.refiRadarCoverage]) end
                                    table.insert(tPotentiallyObsoleteRadar, tWZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refoBestRadar])
                                end
                            end
                            if iOmniRange > (tWZData[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.refiOmniCoverage] or 0) then
                                tWZData[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.refiOmniCoverage] = math.max((tWZData[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.refiOmniCoverage] or 0), iOmniRange - AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], oRadar:GetPosition()))
                            end
                        end
                    end
                end

                --Filter to obsolete radar and ctrl-K these (or record against the best radar if the best radar isn't constructed yet)
                if bDebugMessages == true then LOG(sFunctionRef..': Finished cycling through zones, is table of obsolete radar empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentiallyObsoleteRadar))) end
                oRadar[reftoUnitsToKillOnCompletion] = nil
                if AiBotUtilities.IsTableEmpty(tPotentiallyObsoleteRadar) == false then
                    local tUniqueList = {}
                    local iUnitRef
                    local oBrain
                    for iUnit, oUnit in tPotentiallyObsoleteRadar do
                        oBrain = oUnit:GetAIBrain()
                        if oBrain.AiBotAI then
                            iUnitRef = oBrain:GetArmyIndex()..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will add unit with ref incl ai index of '..iUnitRef..' to tUniqueList') end
                            if not(tUniqueList[iUnitRef]) then
                                tUniqueList[iUnitRef] = oUnit
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is tUniqueList empty='..tostring( AiBotUtilities.IsTableEmpty(tUniqueList))) end
                    if AiBotUtilities.IsTableEmpty(tUniqueList) == false then
                        local tUnitsToKill = {}
                        for iUnit, oUnit in tUniqueList do
                            local oBP = oUnit:GetBlueprint()
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with radar radius '..(oBP.Intel.RadarRadius or 0)..' vs iIntelRange='..iIntelRange..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)) end
                            if (oBP.Intel.RadarRadius or 0) < math.max(1, iIntelRange) and (oBP.Intel.OmniRadius or 0) < math.max(1, iOmniRange) then
                                if (not(oUnit[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap)) and (not(oUnit:IsUnitState('Upgrading')) or (AiBotUnitInfo.GetUnitTechLevel(oRadar) >= 3 and EntityCategoryContains(categories.TECH1, oUnit.UnitId))) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to list of units to kill on completeion') end
                                    table.insert(tUnitsToKill, oUnit)
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tUnitsToKill) == false then
                            if oRadar:GetFractionComplete() < 1 then
                                oRadar[reftoUnitsToKillOnCompletion] = tUnitsToKill
                            else
                                local iTotalCount = table.getn(tUnitsToKill)
                                for iEntry = iTotalCount, 1, -1 do
                                    if bDebugMessages == true then LOG(sFunctionRef..': Radar '..tUnitsToKill[iEntry].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tUnitsToKill[iEntry])..' has radar range of '..(tUnitsToKill[iEntry]:GetBlueprint().Intel.RadarRadius or 0)..' and is obsolete by oRadar '..oRadar.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRadar)..'; with iIntelRange='..iIntelRange) end
                                    AiBotOrders.IssueTrackedKillUnit(tUnitsToKill[iEntry])
                                end
                            end
                        end
                    end
                end
                local tBaseLZTeamData = AiBotMap.tAllPlateaus[iBasePlateau][AiBotMap.subrefPlateauLandZones][iBaseZone][AiBotMap.subrefLZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': iBasePlateau='..iBasePlateau..'; iBaseZone='..iBaseZone..'; tBaseLZTeamData radar coverage='..tBaseLZTeamData[AiBotMap.refiRadarCoverage]) end
                --Backup - have the zone the radar is in have a minimum level of coverage so we dont massively overbuild
                local iRadarThreshold = math.max(iIntelRange * 0.6, iIntelRange - 80)
                if tBaseLZTeamData[AiBotMap.refiRadarCoverage] < iRadarThreshold then
                    tBaseLZTeamData[AiBotMap.refiRadarCoverage] = iRadarThreshold
                    if bDebugMessages == true then LOG(sFunctionRef..': Setting radar range equal to 60% of the units, iRadarThreshold='..iRadarThreshold) end
                end

                --Remove priority land scout flag on any ACUs if we have just built omni
                if iIntelRange > AiBotUnitInfo.iT2RadarSize and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs]) then
                    for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs] do
                        RemoveUnitFromPriorityLandScoutFlagTable(oACU)
                    end
                end
            end
            UpdateRecordedAllPlayerOmni(oRadar, false)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function TrackWallSegment(oWall, bJustBuilt)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TrackWallSegment'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oWall:GetPosition())
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oWall='..(oWall.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oWall) or 'nil')..'; bJustBuilt='..tostring(bJustBuilt)..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if iLandZone > 0 then
        local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
        if bJustBuilt then
            local bAlreadyRecorded = false
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPlayerWallSegments]) == false then
                for iUnit, oUnit in tLZData[AiBotMap.subrefLZPlayerWallSegments] do
                    if oWall == oUnit then
                        bAlreadyRecorded = true
                        break
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished considering whether to add wall, bAlreadyRecorded='..tostring(bAlreadyRecorded)) end
            if not(bAlreadyRecorded) then
                table.insert(tLZData[AiBotMap.subrefLZPlayerWallSegments], oWall)
                --Consider adding to nearby zones incase wall is built inbetween two zones
                local iAltPlateau, iAltLandZone
                local tbZonesConsidered = {}
                tbZonesConsidered[iLandZone] = true
                for iCurAngle = 0, 315, 45 do
                    local tAltPosition = AiBotUtilities.MoveInDirection(oWall:GetPosition(), iCurAngle, 8, true, false, false)
                    if tAltPosition then
                        iAltPlateau, iAltLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tAltPosition)
                        if iAltLandZone and not(tbZonesConsidered[iAltLandZone]) and iAltPlateau == iPlateau then
                            tbZonesConsidered[iAltLandZone] = true
                            local tAltLZData = AiBotMap.tAllPlateaus[iAltPlateau][AiBotMap.subrefPlateauLandZones][iAltLandZone]
                            if not(tAltLZData[AiBotMap.subrefLZPlayerWallSegments]) then tAltLZData[AiBotMap.subrefLZPlayerWallSegments] = {} end
                            table.insert(tAltLZData[AiBotMap.subrefLZPlayerWallSegments], oWall)
                            if not(oWall[AiBotUnitInfo.reftiWallAdjacentLandZonesRecorded]) then oWall[AiBotUnitInfo.reftiWallAdjacentLandZonesRecorded] = {} end
                            table.insert(oWall[AiBotUnitInfo.reftiWallAdjacentLandZonesRecorded], iAltLandZone)
                        end
                    end
                end
            end
        else
            function RemoveWallFromLandZone(tCurLZData)
                if AiBotUtilities.IsTableEmpty(tCurLZData[AiBotMap.subrefLZPlayerWallSegments]) == false then
                    --Remove any old entries
                    local iRevisedIndex = 1
                    local iTableSize = table.getn(tCurLZData[AiBotMap.subrefLZPlayerWallSegments])
                    if bDebugMessages == true then LOG(sFunctionRef..': Will remove wall from table, iTableSize='..iTableSize) end
                    for iOrigIndex=1, iTableSize do
                        if tCurLZData[AiBotMap.subrefLZPlayerWallSegments][iOrigIndex] then
                            if not(tCurLZData[AiBotMap.subrefLZPlayerWallSegments][iOrigIndex] == oWall) and AiBotUnitInfo.IsUnitValid(tCurLZData[AiBotMap.subrefLZPlayerWallSegments][iOrigIndex]) then --I.e. this should run the logic to decide whether we want to keep this entry of the table or remove it
                                --We want to keep the entry; Move the original index to be the revised index number (so if e.g. a table of 1,2,3 removed 2, then this would've resulted in the revised index being 2 (i.e. it starts at 1, then icnreases by 1 for the first valid entry); this then means we change the table index for orig index 3 to be 2
                                if (iOrigIndex ~= iRevisedIndex) then
                                    tCurLZData[AiBotMap.subrefLZPlayerWallSegments][iRevisedIndex] = tCurLZData[AiBotMap.subrefLZPlayerWallSegments][iOrigIndex];
                                    tCurLZData[AiBotMap.subrefLZPlayerWallSegments][iOrigIndex] = nil;
                                end
                                iRevisedIndex = iRevisedIndex + 1; --i.e. this will be the position of where the next value that we keep will be located
                            else
                                tCurLZData[AiBotMap.subrefLZPlayerWallSegments][iOrigIndex] = nil;
                            end
                        end
                    end
                    if iRevisedIndex < iTableSize then
                        --table.setn(tCurLZData[AiBotMap.subrefLZPlayerWallSegments], iRevisedIndex - 1)
                        for iRemovalEntry = iTableSize, iRevisedIndex, -1 do
                            table.remove(tCurLZData[AiBotMap.subrefLZPlayerWallSegments], iRemovalEntry)
                        end
                    end
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': Finished removing, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tCurLZData[AiBotMap.subrefLZPlayerWallSegments])))
                        if AiBotUtilities.IsTableEmpty(tCurLZData[AiBotMap.subrefLZPlayerWallSegments]) == false then
                            LOG(sFunctionRef..': Table size after removing='..table.getn(tCurLZData[AiBotMap.subrefLZPlayerWallSegments]))
                        end
                    end
                end
            end
            RemoveWallFromLandZone(tLZData)

            if AiBotUtilities.IsTableEmpty(oWall[AiBotUnitInfo.reftiWallAdjacentLandZonesRecorded]) == false then
                for _, iAdjLZ in oWall[AiBotUnitInfo.reftiWallAdjacentLandZonesRecorded] do
                    local tAltLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                    RemoveWallFromLandZone(tAltLZData)
                end
                oWall[AiBotUnitInfo.reftiWallAdjacentLandZonesRecorded] = nil
            end
        end
    end
end

function RecordEnemyFirebase(iTeam, iPlateau, iLandZone)
    --Searches for all nearby land zones to iLandZone and flags that there is an enemy firebase nearby
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordEnemyFirebase'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..'; iTeam='..iTeam..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone) end

    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau] = {} end
    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone] = {[AiBotTeam.subrefiNearbyPlateauAndLandZones] = {}, [AiBotTeam.subrefbInRangeOfCoreLZ] = false, {}}
    --Record any land zones in range of here
    local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]

    AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData)
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
        local iLandLZThreshold = 163
        local iWaterLZThreshold = 200
        if AiBotMap.iMapSize >= 1000 then iLandLZThreshold = 190 iWaterLZThreshold = 230 end
        --Further increase threshold for if this is a large LZ
        local iBaseLZAverageSize = 0.5*((tLZData[AiBotMap.subrefLZMaxSegX] - tLZData[AiBotMap.subrefLZMinSegX])*AiBotMap.iLandZoneSegmentSize + (tLZData[AiBotMap.subrefLZMaxSegZ] - tLZData[AiBotMap.subrefLZMinSegZ])*AiBotMap.iLandZoneSegmentSize)

        iLandLZThreshold = math.max(iLandLZThreshold, iBaseLZAverageSize + 20, iBaseLZAverageSize * 0.5 + 125)
        iWaterLZThreshold = math.max(iWaterLZThreshold, iLandLZThreshold + 20)
        if bDebugMessages == true then LOG(sFunctionRef..': LZ X size='..(tLZData[AiBotMap.subrefLZMaxSegX] - tLZData[AiBotMap.subrefLZMinSegX])*AiBotMap.iLandZoneSegmentSize..'; LZ Z size='..(tLZData[AiBotMap.subrefLZMaxSegZ] - tLZData[AiBotMap.subrefLZMinSegZ])*AiBotMap.iLandZoneSegmentSize..'; iWaterLZThreshold='..iWaterLZThreshold..'; iLandLZThreshold='..iLandLZThreshold) end
        for iEntry, tPathingData in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering alt LZ entry='..tPathingData[AiBotMap.subrefiLandOrWaterZoneRef]..'; tPathingData[AiBotMap.subrefiDistance]='..tPathingData[AiBotMap.subrefiDistance]..'; Is water zone='..tostring(tPathingData[AiBotMap.subrefbIsWaterZone] or false)) end
            if tPathingData[AiBotMap.subrefiDistance] > iWaterLZThreshold then
                break
            end --163 used for land zones, 200 for water zones
            local tAltLZOrWZData
            local tAltLZOrWZTeamData
            if tPathingData[AiBotMap.subrefbIsWaterZone] then
                tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tPathingData[AiBotMap.subrefiLandOrWaterZoneRef]]][AiBotMap.subrefPondWaterZones][tPathingData[AiBotMap.subrefiLandOrWaterZoneRef]]
                tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
            elseif tPathingData[AiBotMap.subrefiDistance] <= 163 then
                tAltLZOrWZData = AiBotMap.tAllPlateaus[tPathingData[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefiLandOrWaterZoneRef]]
                tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
            end
            if tAltLZOrWZData then
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iAltLZ='..tPathingData[AiBotMap.subrefiLandOrWaterZoneRef]..'; Dist from that LZ midpoint to the firebase LZ midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tAltLZOrWZData[AiBotMap.subrefMidpoint])..'; tPathingData[AiBotMap.subrefiDistance]='..tPathingData[AiBotMap.subrefiDistance]) end
                --The LZ is potentially within range of this firebase so record against that LZ
                if not(tAltLZOrWZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then tAltLZOrWZTeamData[AiBotMap.subreftEnemyFirebasesInRange] = {} end
                table.insert(tAltLZOrWZTeamData[AiBotMap.subreftEnemyFirebasesInRange], {iPlateau, iLandZone})

                --Also record against the base plateau and LZ all the alt LZs that we have been recorded against
                if tPathingData[AiBotMap.subrefbIsWaterZone] then
                    --Water zone
                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone][AiBotTeam.subrefiNearbyWaterZones]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone][AiBotTeam.subrefiNearbyWaterZones] = {} end
                    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone][AiBotTeam.subrefiNearbyWaterZones], tPathingData[AiBotMap.subrefLZNumber])
                    if bDebugMessages == true then LOG(sFunctionRef..': Recorded enemy firebase against teh water zone '..tPathingData[AiBotMap.subrefiLandOrWaterZoneRef]) end
                else
                    --Land zone - shorter dist threhsold
                    if tPathingData[AiBotMap.subrefiDistance] > iLandLZThreshold + math.max(0, iBaseLZAverageSize - 0.5*((tAltLZOrWZData[AiBotMap.subrefLZMaxSegX] - tAltLZOrWZData[AiBotMap.subrefLZMinSegX])*AiBotMap.iLandZoneSegmentSize + (tAltLZOrWZData[AiBotMap.subrefLZMaxSegZ] - tAltLZOrWZData[AiBotMap.subrefLZMinSegZ])*AiBotMap.iLandZoneSegmentSize)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': LZ too far away so wont record against here') end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Recorded enemy firebase against land zone '..tPathingData[AiBotMap.subrefiLandOrWaterZoneRef]) end
                        table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone][AiBotTeam.subrefiNearbyPlateauAndLandZones], {iPlateau, tPathingData[AiBotMap.subrefLZNumber]})

                        --If it is a core LZ then record that (as will want to adjust our behaviour accordingly)
                        if tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase] then
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone][AiBotTeam.subrefbInRangeOfCoreLZ] = true
                        end
                    end
                end
            end
        end
    end
    --Also add to this LZ
    if not(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange] = {} end
    table.insert(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange], {iPlateau, iLandZone})
    --Also record against the base plateau and LZ all the alt LZs that we have been recorded against
    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone][AiBotTeam.subrefiNearbyPlateauAndLandZones], {iPlateau, iLandZone})


    if bDebugMessages == true then LOG(sFunctionRef..': Finished recording for all LZ likely in range of the firebase, reprs of reftEnemyFirebaseByPlateauAndLZ for this plateau and LZ='..reprs(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone])) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RemoveEnemyFirebase(iTeam, iPlateau, iLandZone)
    --Goes through all land zones that recirded iLandZone as having a firebase in range of them, and removes this entry
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone][AiBotTeam.subrefiNearbyPlateauAndLandZones]) == false then
        for iEntry, tPlateauAndLZ in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone][AiBotTeam.subrefiNearbyPlateauAndLandZones] do
            local tAltLZTeamData = AiBotMap.tAllPlateaus[tPlateauAndLZ[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndLZ[2]][AiBotMap.subrefLZTeamData][iTeam]
            if AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false then
                for iFirebase, tPlateauAndLZ in tAltLZTeamData[AiBotMap.subreftEnemyFirebasesInRange] do
                    if tPlateauAndLZ[1] == iPlateau and tPlateauAndLZ[2] == iLandZone then
                        table.remove(tAltLZTeamData[AiBotMap.subreftEnemyFirebasesInRange], iFirebase)
                        break
                    end
                end
            end
        end
    end
    --Do same for water zones
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone][AiBotTeam.subrefiNearbyWaterZones]) == false then
        for iEntry, iWaterZone in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone][AiBotTeam.subrefiNearbyWaterZones] do
            local tAltWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefWZTeamData][iTeam]
            if AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false then
                for iFirebase, tPlateauAndLZ in tAltWZTeamData[AiBotMap.subreftEnemyFirebasesInRange] do
                    if tPlateauAndLZ[1] == iPlateau and tPlateauAndLZ[2] == iLandZone then
                        table.remove(tAltWZTeamData[AiBotMap.subreftEnemyFirebasesInRange], iFirebase)
                        break
                    end
                end
            end
        end
    end
end

function ConsiderIfHaveEnemyFirebase(iTeam, oT2Arti)
    --Considers if hte land zone that oT2Arti is in has enough T2 arti threat to justify being a firebase
    --Idea is to only flag a firebase for something that MML are not expected to be able to break through - e.g. 3+ T2 arti; for smaller amounts the hope is that the arti can be overwhelmed
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderIfHaveEnemyFirebase'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oT2Arti:GetPosition())

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')) end
    if (iLandZone or 0) > 0 then
        local bHaveFirebase = false
        local tArtiLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
        local tAllT2Arti = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedT2Arti, tArtiLZTeamData[AiBotMap.subrefTEnemyUnits])
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of all T2 arti for this zone empty='..tostring(AiBotUtilities.IsTableEmpty(tAllT2Arti))) end
        if AiBotUtilities.IsTableEmpty(tAllT2Arti) == false then
            if bDebugMessages == true then LOG(sFunctionRef..': Table size='.. table.getn(tAllT2Arti)) end
            if (AiBotUtilities.bQuietModActive and table.getn(tAllT2Arti) >= 4) or (not(AiBotUtilities.bQuietModActive) and table.getn(tAllT2Arti) >= 3) then
                bHaveFirebase = true
            else
                local iConstructedT2Arti = 0
                local iShieldedT2Arti = 0
                for iArti, oArti in tAllT2Arti do
                    if AiBotUnitInfo.IsUnitValid(oArti) and oArti:GetFractionComplete() == 1 then
                        iConstructedT2Arti = iConstructedT2Arti + 1
                    end
                    if AiBotUtilities.IsTableEmpty(oArti[AiBotBuilding.reftoShieldsProvidingCoverage]) == false then
                        iShieldedT2Arti = iShieldedT2Arti + 1
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iConstructedT2Arti='..iConstructedT2Arti..'; iShieldedT2Arti='..iShieldedT2Arti) end
                if iConstructedT2Arti >= 1 and (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or (iConstructedT2Arti >= 2 and iShieldedT2Arti >= 1)) then
                    local iModDistThreshold = 0.5
                    if AiBotMap.iMapSize >= 1000 then iModDistThreshold = 0.45
                    elseif AiBotMap.iMapSize >= 512 then iModDistThreshold = 0.55
                    else
                        iModDistThreshold = 0.75
                    end
                    if tArtiLZTeamData[AiBotMap.refiModDistancePercent] >= iModDistThreshold then
                        bHaveFirebase = true
                    end
                end
                local iTotalKills = 0
                for iUnit, oUnit in tAllT2Arti do
                    iTotalKills = iTotalKills + (oUnit.VetExperience or oUnit.Sync.totalMassKilled or 0)
                end
                if iTotalKills >= 2500 or (iTotalKills >= 1500 and table.getn(tAllT2Arti) == 1) then
                    bHaveFirebase = true
                end
            end
        end
        if bHaveFirebase then
            --If we dont have a firebase recorded already then record one
            if bDebugMessages == true then LOG(sFunctionRef..': Will record firebase if havent already, is it nil for this plateau and zone='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone] == nil)) end
            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone]) then
                RecordEnemyFirebase(iTeam, iPlateau, iLandZone)
            end
        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau][iLandZone] then
            --If we have recorded a firebase for this LZ then need to remove it
            RemoveEnemyFirebase(iTeam, iPlateau, iLandZone)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderIfAnyEnemyTeamsStillHaveFirebaseOnT2ArtiDeath(oT2Arti)
    local iBaseTeam = oT2Arti:GetAIBrain().AiBotTeam
    for iTeam = 1, AiBotTeam.iTotalTeamCount do
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 and not(iTeam == iBaseTeam) then
            ConsiderIfHaveEnemyFirebase(iTeam, oT2Arti)
            --update tracking of t2 arti to reflect it is dead
            AiBotTeam.RecordEnemyT2ArtiAgainstNearbyZones(iTeam, oT2Arti, true)
        end
    end
end

function ConsiderAssigningMAABodyguardToFatboy(oMAA, oFatboy, bJustReturnIfWantMoreMAAOrNot)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderAssigningMAABodyguardToFatboy'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local aiBrain
    if bJustReturnIfWantMoreMAAOrNot then aiBrain = oFatboy:GetAIBrain() else aiBrain = oMAA:GetAIBrain() end
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oMAA='..(oMAA.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oMAA) or 'nil')..'; oFatboy='..oFatboy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFatboy)..'; Brain='..aiBrain.Nickname..'; Time='..GetGameTimeSeconds()) end
    local bWantToAssign = false
    if aiBrain.AiBotAI then
        local iExistingMAA = 0
        if not(AiBotConditions.IsTableOfUnitsStillValid(oFatboy[reftoAssignedMAAGuards])) then
            oFatboy[reftoAssignedMAAGuards] = {}
        else
            iExistingMAA = table.getn(oFatboy[reftoAssignedMAAGuards])
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iExistingMAA='..iExistingMAA) end
        if iExistingMAA < iFatboySafeMAACount then
            if iExistingMAA < iFatboyBaseMAACount then bWantToAssign = true
            elseif AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 7000 then
                if not(AiBotConditions.TeamHasAirControl(aiBrain.AiBotTeam)) or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 30000 then
                    bWantToAssign = true
                else
                    local tEnemyBombers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryBomber - categories.EXPERIMENTAL, AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftoAllEnemyAir])
                    if AiBotUtilities.IsTableEmpty(tEnemyBombers) == false then
                        local iBomberThreat = AiBotUnitInfo.GetMassCostOfUnits(tEnemyBombers, true)
                        if iBomberThreat >= 6000 then bWantToAssign = true end
                    end
                end
            end
        end
        if bWantToAssign and not(bJustReturnIfWantMoreMAAOrNot) then
            table.insert(oFatboy[reftoAssignedMAAGuards], oMAA)
            oMAA[refoAssignedUnitToGuard] = oFatboy
            if bDebugMessages == true then LOG(sFunctionRef..': Assigned MAA to guard the fatboy') end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if bJustReturnIfWantMoreMAAOrNot then return bWantToAssign end
end

function ConsiderAssigningMAABodyguardToACUOrLandExp(oMAA, bAlsoConsiderAssigningToLandExperimental, bDontAssignToACU)
    local aiBrain = oMAA:GetAIBrain()
    local oACU = aiBrain[AiBotACU.refoPrimaryACU]
    local iTeam = aiBrain.AiBotTeam

    if not(bDontAssignToACU) and AiBotUnitInfo.IsUnitValid(oACU) and not(AiBotConditions.IsTableOfUnitsStillValid(oACU[reftoAssignedMAAGuards])) then
        --if enemy has T2+ air or air to ground threat then assign
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 2 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] or 0) > 0 then
            --Want to assign
            if not(oACU[reftoAssignedMAAGuards]) then oACU[reftoAssignedMAAGuards] = {} end
            table.insert(oACU[reftoAssignedMAAGuards], oMAA)
            oMAA[refoAssignedUnitToGuard] = oACU
        end
    end
    if bAlsoConsiderAssigningToLandExperimental and not(oMAA[refoAssignedUnitToGuard]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoFriendlyLandExperimentals]) then
        local oClosestExp
        local iPlateauWanted = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oMAA:GetPosition())
        if iPlateauWanted then
            local iIslandWanted
            if not(EntityCategoryContains(AiBotUnitInfo.refCategoryAmphibious + categories.HOVER, oMAA.UnitId)) then iIslandWanted = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oMAA:GetPosition()) end
            oClosestExp = GetClosestExperimentalWantingMAAGuards(iPlateauWanted, iIslandWanted, iTeam, oMAA:GetPosition(), 200)

            if oClosestExp then
                if not(oClosestExp[reftoAssignedMAAGuards]) then oClosestExp[reftoAssignedMAAGuards] = {} end
                table.insert(oClosestExp[reftoAssignedMAAGuards], oMAA)
                oMAA[refoAssignedUnitToGuard] = oClosestExp
            end
        end
    end
end

function DontHaveJerichoAttackTarget(oJericho)
    if not(oJericho[AiBotUnitInfo.refbEasyBrain]) then
        local aiBrain = oJericho:GetAIBrain()
        local tEnemiesInRange = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryMobileLand * categories.TECH3 + AiBotUnitInfo.refCategoryNavalSurface - categories.TECH1, oJericho:GetPosition(), oJericho[AiBotUnitInfo.refiDFRange], 'Enemy')
        local oUnitToTarget
        if AiBotUtilities.IsTableEmpty(tEnemiesInRange) == false then
            local iHighestValue = 0
            local iCurValue
            local iMinRange = (oJericho[AiBotUnitInfo.refiDFMinRange] or -10) + 10
            for iUnit, oUnit in tEnemiesInRange do
                --Non-attached on land near-built unit that isnt inside minimum range?
                if not(oUnit:IsUnitState('Attached')) and oUnit:GetFractionComplete() >= 0.5 and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oJericho:GetPosition()) >= iMinRange then
                    iCurValue = (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * oUnit:GetFractionComplete()
                    if EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then iCurValue = iCurValue * 0.1 end
                    if iCurValue > iHighestValue then
                        if (AiBotUnitInfo.GetBuildingSize(oUnit.UnitId) or 0) <= 4 then iCurValue = iCurValue * 0.3 end
                        if iCurValue > iHighestValue then
                            iHighestValue = iCurValue
                            oUnitToTarget = oUnit
                        end
                    end
                end
            end
        end
        if oUnitToTarget then
            --consider target leading
            local tGroundTarget
            if (oJericho[AiBotUnitInfo.refiDFAOE] or 0) > 0 and EntityCategoryContains(categories.MOBILE, oUnitToTarget.UnitId) and oUnitToTarget:IsUnitState('Moving') then
                local iWeaponVelocity
                local oBP = oJericho:GetBlueprint()
                if oBP.Weapon and type(oBP.Weapon) == "table" then
                    for iCurWeapon, oCurWeapon in oBP.Weapon do
                        if oCurWeapon.DamageRadius == oJericho[AiBotUnitInfo.refiDFAOE] then
                            iWeaponVelocity = oCurWeapon.MuzzleVelocity
                            break
                        end
                    end
                end
                if (iWeaponVelocity or 0) > 0 then
                    local iDistToEnemy = AiBotUtilities.GetDistanceBetweenPositions(oUnitToTarget:GetPosition(), oJericho:GetPosition())
                    local iTimeToImpact = 0.5 + iDistToEnemy / iWeaponVelocity
                    local iCurFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oUnitToTarget)
                    local iDistToLead = iTimeToImpact * (oUnitToTarget:GetBlueprint().Physics.MaxSpeed or 0)
                    local tLeadingTarget = AiBotUtilities.MoveInDirection(oUnitToTarget:GetPosition(), iCurFacingDirection, iDistToLead, true, false, AiBotMap.bIsCampaignMap)
                    if tLeadingTarget and AiBotUtilities.GetDistanceBetweenPositions(tLeadingTarget, oJericho:GetPosition()) >= (oJericho[AiBotUnitInfo.refiDFMinRange] or 0) then
                        tGroundTarget = {tLeadingTarget[1], tLeadingTarget[2], tLeadingTarget[3]}
                    end
                end
            end

            if tGroundTarget then
                AiBotOrders.IssueTrackedGroundAttack(oJericho, tGroundTarget, 1, false, 'JerGrnd', false, oUnitToTarget)
            else
                AiBotOrders.IssueTrackedAttack(oJericho, oUnitToTarget, false, 'JetAtk', false)
            end
            return false
        end
    end
    return true
end

function GetFarAwayLandThreatOfLongRangeUnits(tStartPoint, iTeam, bMinorZoneAdjustment, bAdjustForNearbyTML)
    local iLongRangeFurtherAwayThreat = 0
    local iPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tStartPoint)
    if iPlateau and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoLongRangeEnemyDFUnits]) == false then
        local tMobileLandLRThreat = EntityCategoryFilterDown(categories.MOBILE * categories.LAND, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoLongRangeEnemyDFUnits])
        local iUnitBaseThreat, iDistToMidpoint, iUnitPlateau, iUnitLandZone
        if AiBotUtilities.IsTableEmpty(tMobileLandLRThreat) == false then
            local iDistThreshold = 750
            if bMinorZoneAdjustment then iDistThreshold = 625 end
            for iUnit, oUnit in tMobileLandLRThreat do
                if AiBotUnitInfo.IsUnitValid(oUnit) then
                    --Only consider powerful units - e.g. fatboy
                    iUnitBaseThreat = (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) --want mass value since fatboy could regain its shield at any point
                    if bMinorZoneAdjustment then iUnitBaseThreat = iUnitBaseThreat * oUnit:GetFractionComplete() end
                    if iUnitBaseThreat >= 1000 then
                        --Only include if it can path to this zone
                        if NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition()) == iPlateau then
                            iDistToMidpoint = AiBotUtilities.GetDistanceBetweenPositions(tStartPoint, oUnit:GetPosition())
                            if iDistToMidpoint <= iDistThreshold then
                                if iDistToMidpoint <= 150 and not(bMinorZoneAdjustment) then
                                    iLongRangeFurtherAwayThreat = iLongRangeFurtherAwayThreat + iUnitBaseThreat * 1.2
                                elseif iDistToMidpoint <= 200 then
                                    iLongRangeFurtherAwayThreat = iLongRangeFurtherAwayThreat + iUnitBaseThreat
                                elseif iDistToMidpoint <= 400 then
                                    iLongRangeFurtherAwayThreat = iLongRangeFurtherAwayThreat + iUnitBaseThreat * 0.75
                                elseif iDistToMidpoint <= 600 then
                                    iLongRangeFurtherAwayThreat = iLongRangeFurtherAwayThreat + iUnitBaseThreat * 0.5
                                else
                                    iLongRangeFurtherAwayThreat = iLongRangeFurtherAwayThreat + iUnitBaseThreat * 0.25
                                end
                            end
                        end
                    end
                end
            end
            --Halve threat if we have a nearby TML battery
            if bAdjustForNearbyTML and iLongRangeFurtherAwayThreat > 2000 then
                local iBasePlateau, iBaseLZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStartPoint)
                if iBasePlateau and iBaseLZ  then
                    local tLZTeamData = AiBotMap.tAllPlateaus[iBasePlateau][AiBotMap.subrefPlateauLandZones][iBaseLZ][AiBotMap.subrefLZTeamData][iTeam]
                    if tLZTeamData[AiBotMap.refbNearbyTMLBattery] or tLZTeamData[AiBotMap.refbGetTMLBattery] then
                        local tEnemyExperimental = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFatboy + AiBotUnitInfo.refCategoryMegalith, tMobileLandLRThreat)
                        if AiBotUtilities.IsTableEmpty(tEnemyExperimental) == false then
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbTMLBatteryMissedLots] then
                                --Only reduce threat slightly
                                iLongRangeFurtherAwayThreat = math.max(2000, iLongRangeFurtherAwayThreat * 0.8, iLongRangeFurtherAwayThreat - AiBotUnitInfo.GetMassCostOfUnits(tEnemyExperimental, true))
                            else
                                iLongRangeFurtherAwayThreat = math.max(2000, iLongRangeFurtherAwayThreat * 0.5, iLongRangeFurtherAwayThreat - AiBotUnitInfo.GetMassCostOfUnits(tEnemyExperimental, true))
                            end
                        end
                    end
                end
            end
        end
    end
    return iLongRangeFurtherAwayThreat
end

function RemoveUnitFromPriorityLandScoutFlagTable(oUnit)
    if oUnit[refbFlaggedForPriorityScout] then
        oUnit[refbFlaggedForPriorityScout] = nil
        local iLandSubteam = oUnit:GetAIBrain().AiBotLandSubteam
        if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout]) then
            for iRecorded, oRecorded in AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout] do
                if oRecorded == oUnit then
                    table.remove(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout], iRecorded)
                    break
                end
            end
        end
    end
end

function ConsiderPriorityLandScoutFlag(oUnit)
    if not(AiBotUnitInfo.IsUnitValid(oUnit[refoAssignedLandScout])) then
        local bInTable = false
        local iLandSubteam = oUnit:GetAIBrain().AiBotLandSubteam
        if oUnit[refbFlaggedForPriorityScout] == nil then
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout]) == false then
                for iRecorded, oRecorded in AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout] do
                    if oRecorded == oUnit then
                        bInTable = true
                        oUnit[refbFlaggedForPriorityScout] = true
                        break
                    end
                end
            end
        end

        if not(bInTable) then
            if not(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout]) then AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout] = {} end
            table.insert(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout], oUnit)
            oUnit[refbFlaggedForPriorityScout] = true
        end
    end
end


function LandSubteamOverseer(iLandSubteam)
    local iStartPlateau, iStartZone
    local oFirstBrain
    for iBrain, oBrain in AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
        oFirstBrain = oBrain
        break
    end
    iStartPlateau, iStartZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotMap.GetPlayerStartPosition(oFirstBrain))
    local iTeam = oFirstBrain.AiBotTeam
    --Wait ticks based on team to spread out between different seconds
    WaitTicks(iTeam)
    local tStartLZData = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iStartZone]
    local tStartLZTeamData = tStartLZData[AiBotMap.subrefLZTeamData][iTeam]

    while AiBotUtilities.IsTableEmpty(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains]) == false do
        ForkThread(CompareNearbyAlliedAndEnemyLandThreats, iTeam, iLandSubteam, iStartPlateau, tStartLZData, tStartLZTeamData)
        WaitSeconds(10)
    end
end

function CompareNearbyAlliedAndEnemyLandThreats(iTeam, iLandSubteam, iStartPlateau, tStartLZData, tStartLZTeamData)
    --Assesses enemy mobile land threat and MAA threat on same island as our start position
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CompareNearbyAlliedAndEnemyLandThreats'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iMaxModDistance = 0.6
    local iMaxTravelDist = AiBotMap.iMapSize * 0.75
    local bHaveTeammates = false
    if table.getn(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains]) > 1 then bHaveTeammates = true end
    local iOurMobileDFThreat = tStartLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]
    local iEnemyMobileDFThreat = tStartLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]
    local iEnemyGroundAAThreat = tStartLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]
    local iCurLZ
    local iEnemyNetMobileDFCloseToBase = 0
    if AiBotUtilities.IsTableEmpty(tStartLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
        for iEntry, tPathingData in tStartLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
            iCurLZ = tPathingData[AiBotMap.subrefLZNumber]
            local tCurLZData = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iCurLZ]
            local tCurLZTeamData = tCurLZData[AiBotMap.subrefLZTeamData][iTeam]
            if tCurLZTeamData[AiBotMap.refiModDistancePercent] <= iMaxModDistance then
                iOurMobileDFThreat = iOurMobileDFThreat + tCurLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]
                iEnemyMobileDFThreat = iEnemyMobileDFThreat + tCurLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]
                iEnemyGroundAAThreat = iEnemyGroundAAThreat + tCurLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]
                if (tCurLZTeamData[AiBotMap.refiModDistancePercent] or 1) <= 0.3 then iEnemyNetMobileDFCloseToBase = iEnemyNetMobileDFCloseToBase + math.max(0, (tCurLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) - (tCurLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0)) end
            else
                if not(bHaveTeammates) or tCurLZTeamData[AiBotMap.refiModDistancePercent] >= 0.9 or tPathingData[AiBotMap.subrefLZTravelDist] >= iMaxTravelDist then
                    break
                end
            end
        end
    end
    AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] = iOurMobileDFThreat
    if bDebugMessages == true then LOG(sFunctionRef..': iOurMobileDFThreat='..iOurMobileDFThreat..'; AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide]='..AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide]) end
    AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] = iEnemyMobileDFThreat
    if bDebugMessages == true then LOG(sFunctionRef..': AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] after doing enemy threat='..AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide]) end
    AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiEnemyGroundAAThreatNearOurSide] = iEnemyGroundAAThreat

    --Decide if we want to prioritise production over ecoing temporarily
    local bPrioritiseProduction = false
    if iEnemyNetMobileDFCloseToBase >= 800 and (iEnemyNetMobileDFCloseToBase * 4 >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] < iEnemyGroundAAThreat * 2) then bPrioritiseProduction = true
        bPrioritiseProduction = true
    elseif iOurMobileDFThreat < iEnemyMobileDFThreat and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] < math.max(iEnemyMobileDFThreat * 0.4, iEnemyGroundAAThreat * 2) then
        --Further restrictions if campaign map or low threat values
        local iEnemyPlayerCount = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains])
        if not(AiBotMap.bIsCampaignMap) and GetGameTimeSeconds() >= 600 / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] and (iEnemyMobileDFThreat > 2000 * iEnemyPlayerCount or iEnemyMobileDFThreat - iOurMobileDFThreat > 1000 + 1000*iEnemyPlayerCount) then
            bPrioritiseProduction = true
            if iEnemyMobileDFThreat <= 8000 + 2000 * iEnemyPlayerCount then
                if iEnemyMobileDFThreat < iOurMobileDFThreat + math.max(iOurMobileDFThreat * 0.25, 1500) then
                    bPrioritiseProduction = false
                end
            end
        end
    end

    local bPreviouslyPrioritising = AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refbPrioritiseProduction]
    AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refbPrioritiseProduction] = bPrioritiseProduction
    if bPrioritiseProduction and not(bPreviouslyPrioritising) then
        --Consider unpausing any paused land and air factories if are in a mass stall
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then
            for iBrain, oBrain in AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                local tFactoriesToUnpause = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory, false, true)
                if AiBotUtilities.IsTableEmpty(tFactoriesToUnpause) == false then
                    for iUnit, oUnit in tFactoriesToUnpause do
                        if oUnit[AiBotUnitInfo.refbPaused] then
                            AiBotUnitInfo.PauseOrUnpauseMassUsage(oUnit, false, iTeam)
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code for land subteam '..iLandSubteam..' on team '..iTeam..', iOurMobileDFThreat='..iOurMobileDFThreat..'; iEnemyMobileDFThreat='..iEnemyMobileDFThreat..'; ur gunship threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat]..'; iEnemyGroundAAThreat='..iEnemyGroundAAThreat..'; bPrioritiseProduction='..tostring(bPrioritiseProduction)..'; Gross mass inc on team='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; iEnemyNetMobileDFCloseToBase='..iEnemyNetMobileDFCloseToBase..'; AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide='..(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] or 'nil')..'; AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]='..AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]..'; Time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderAssigningScoutToLurkerLogic(oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderAssigningScoutToLurkerLogic'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
    if AiBotUnitInfo.IsUnitValid(oUnit) then
        local aiBrain = oUnit:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        --Only want to use lurker logic early game for now, or occasionally later game
        local iLifetimeCount = AiBotUnitInfo.GetUnitLifetimeCount(oUnit)
        --First selen - want to have normal attack logic
        if iLifetimeCount > 1 and (iLifetimeCount <= 6 or math.floor(iLifetimeCount / 4) == iLifetimeCount / 4) then
            --Are we in the same land zone as the closest friendly base?
            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
            if bDebugMessages == true then LOG(sFunctionRef..': iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')) end
            if iPlateauOrZero and iPlateauOrZero > 0 then
                local tLZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                local iIsland = tLZData[AiBotMap.subrefLZIslandRef]
                if bDebugMessages == true then LOG(sFunctionRef..': iIsland='..(iIsland or 'nil')..'; is AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauIslandLurkerZones][iIsland] nil='..tostring(AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauIslandLurkerZones][iIsland] == nil)) end
                if iIsland then
                    if not(AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauIslandLurkerZones][iIsland]) then
                        --Setup potential lurker zones
                        AiBotMap.RecordLurkerZonesForIsland(iPlateauOrZero, iIsland, iTeam)
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of zones for this island to lurk empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauIslandLurkerZones][iIsland]))) end
                    if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauIslandLurkerZones][iIsland]) == false then
                        local iClosestZoneDist = 10000
                        local iClosestZoneRef, iCurDist
                        local iLowestLurkCount = 2 --i.e. wont assign more than 3 selens to the same zone in the course of the game
                        for iEntry, iZone in AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauIslandLurkerZones][iIsland] do
                            local tPotentialZoneData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iZone]
                            local tPotentialZoneTeamData = tPotentialZoneData[AiBotMap.subrefLZTeamData][iTeam]
                            if tPotentialZoneTeamData and (tPotentialZoneTeamData[AiBotMap.refiAssignedLurkerCount] or 0) <= iLowestLurkCount then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tPotentialZoneData[AiBotMap.subrefMidpoint], tLZData[AiBotMap.subrefMidpoint])
                                if iCurDist < iClosestZoneDist then
                                    iClosestZoneDist = iCurDist
                                    iClosestZoneRef = iZone
                                    if (tPotentialZoneTeamData[AiBotMap.refiAssignedLurkerCount] or 0) < iLowestLurkCount then
                                        iLowestLurkCount = (tPotentialZoneTeamData[AiBotMap.refiAssignedLurkerCount] or 0)
                                    end
                                end
                            end
                        end
                        if iClosestZoneRef then
                            ForkThread(HaveScoutLurkAtZone, oUnit, iPlateauOrZero, iClosestZoneRef, iTeam)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function HaveScoutLurkAtZone(oScout, iPlateau, iZone, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'HaveScoutLurkAtZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    oScout[AiBotUnitInfo.refbLurkerMode] = true
    AiBotMicro.EnableUnitMicroUntilManuallyTurnOff(oScout, true)
    --oScout[AiBotUnitInfo.refbSpecialMicroActive] = true
    --oScout[AiBotUnitInfo.refbLowerPriorityMicroActive] = true
    local tTargetLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iZone]
    local tTargetLZTeamData = tTargetLZData[AiBotMap.subrefLZTeamData][iTeam]
    tTargetLZTeamData[AiBotMap.refiAssignedLurkerCount] = (tTargetLZTeamData[AiBotMap.refiAssignedLurkerCount] or 0) + 1

    --Manage land scout
    local bInCloakMode = false
    local iRadarRange = oScout:GetBlueprint().Intel.RadarRadius or 0
    local tEnemiesToRunFrom
    local tEnemiesToAttack
    local iCurDist, iClosestEnemyDist, oClosestEnemy, bGivenOrder
    local iAttackThresholdDist = oScout[AiBotUnitInfo.refiCombatRange] + 5
    local iCheckForAirThresholdDist = iAttackThresholdDist + 10 --if enemy to attack further away than this then will consider cloaking instead of attacking
    local iMinAttackDist = oScout[AiBotUnitInfo.refiCombatRange] - 10
    local aiBrain = oScout:GetAIBrain()
    if bDebugMessages == true then LOG(sFunctionRef..': About to start main lurker loop, oScout='..oScout.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout)..' for P'..iPlateau..'Z'..iZone..' on taem '..iTeam) end

    while AiBotUnitInfo.IsUnitValid(oScout) do
        --Decide whether want to move towards zone; stay still; run from enemies; or attack engineer
        --Choice is either to attack engineer, stay still, run (from ACU), or abort (because we have enough units in this zone that we should move on)
        if bDebugMessages == true then LOG(sFunctionRef..': Start of cycle for oScout='..(oScout.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oScout) or 'nil')..', target P='..(iPlateau or 'nil')..'Z'..(iZone or 'nil')..', scout team='..(iTeam or 'nil')..'; Target LZSValue='..(tTargetLZTeamData[AiBotMap.subrefLZSValue] or 'nil')..'; Scout assigned plateau and zone='..repru(oScout[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam])..'; iRadarRange='..(iRadarRange or 'nil')..'; Is table of enemies empty for target LZ='..tostring(AiBotUtilities.IsTableEmpty(tTargetLZTeamData[AiBotMap.subrefTEnemyUnits]))..'; tTargetLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..(tTargetLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; tTargetLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange]='..(tTargetLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 'nil')..'; bInCloakMode='..tostring(bInCloakMode)..'; oScout fraction complete='..oScout:GetFractionComplete()..'; Time='..GetGameTimeSeconds()) end
        if tTargetLZTeamData[AiBotMap.subrefLZSValue] >= 250 then --i.e. equiv to 1 t2 mex, also covers having pd or land facs then
            --Want to free up scout for something else
            if bDebugMessages == true then LOG(sFunctionRef..': we have enough buildings in here that we want scout to lurk somewhere else') end
            break
        else
            bGivenOrder = false
            tEnemiesToRunFrom = nil
            tEnemiesToAttack = nil
            local tCurLZData = AiBotMap.tAllPlateaus[oScout[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]][AiBotMap.subrefPlateauLandZones][oScout[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]]
            local tLCurZTeamData = tCurLZData[AiBotMap.subrefLZTeamData][iTeam]

            --If are in a different zone then check if we want to run from enemies
            if not(oScout[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iZone) or not(oScout[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau) then
                --Only check for enemies in scout intel range
                tEnemiesToRunFrom = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat, oScout:GetPosition(), iRadarRange, 'Enemy')
                if bDebugMessages == true then LOG(sFunctionRef..': Scout isnt in zone yet, is tEnemiesToRunFrom empty from getunitsaroundpoint='..tostring(AiBotUtilities.IsTableEmpty(tEnemiesToRunFrom))) end
                --Extra check - are there close DF enemies in cur zone?
                if AiBotUtilities.IsTableEmpty(tEnemiesToRunFrom) then
                    local tPotentiallyNearbyDFEnemies = {}
                    if AiBotUtilities.IsTableEmpty(tLCurZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                        for iEnemy, oEnemy in tLCurZTeamData[AiBotMap.reftoNearestDFEnemies] do
                            if not(oEnemy.Dead) and oEnemy:GetFractionComplete() >= 0.9 and (oEnemy[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Extra check for DF enemies in this zone, oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; Dist to our scout='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oScout:GetPosition())..'; DF range='..oEnemy[AiBotUnitInfo.refiDFRange]) end
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oScout:GetPosition())
                                if iCurDist <= 60 and (iCurDist <= iRadarRange or AiBotUnitInfo.CanSeeUnit(aiBrain, oEnemy, false) and iCurDist - (oEnemy[AiBotUnitInfo.refiDFRange] or 0) <= 8) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout, oEnemy.UnitId)) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding to table of enemies to run from') end
                                    if not(tEnemiesToRunFrom) then tEnemiesToRunFrom = {} end
                                    table.insert(tEnemiesToRunFrom, oEnemy)
                                elseif iCurDist <= iRadarRange + (oEnemy[AiBotUnitInfo.refiDFRange] or 0) + 10 then
                                    table.insert(tPotentiallyNearbyDFEnemies, oEnemy)
                                end
                            end
                        end
                    end
                    --If no enemies to run from, is there an enemy to attack?
                    if bDebugMessages == true then LOG(sFunctionRef..': Is tEnemiesToRunFrom empty (after checking zone scout is in)='..tostring(AiBotUtilities.IsTableEmpty(tEnemiesToRunFrom))..'; Is table of enemy units in zone empyt='..tostring(AiBotUtilities.IsTableEmpty(tLCurZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Scout cur assigned zone=P'..oScout[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]..'Z'..oScout[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]) end
                    if AiBotUtilities.IsTableEmpty(tEnemiesToRunFrom) and AiBotUtilities.IsTableEmpty(tLCurZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                        local tPotentialEnemiesToAttack = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryRadar, tLCurZTeamData[AiBotMap.subrefTEnemyUnits])
                        if bDebugMessages == true then LOG(sFunctionRef..': Is tPotentialEnemiesToAttack empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialEnemiesToAttack))) end
                        if AiBotUtilities.IsTableEmpty(tPotentialEnemiesToAttack) == false then
                            local bTargetNearDFEnemies = false
                            for iEnemy, oEnemy in tPotentialEnemiesToAttack do
                                if not(oEnemy.Dead) and oEnemy:GetFractionComplete() >= 0.9 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; Dist to oEnemy='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oScout:GetPosition())) end
                                    if AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oScout:GetPosition()) <= iRadarRange then
                                        bTargetNearDFEnemies = false
                                        if AiBotUtilities.IsTableEmpty(tPotentiallyNearbyDFEnemies) == false then
                                            for iDFEnemy, oDFEnemy in tPotentiallyNearbyDFEnemies do
                                                if bDebugMessages == true then LOG(sFunctionRef..': Dist between potential target enemy to attack and oDFEnemy '..oDFEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oDFEnemy)..'='..AiBotUtilities.GetDistanceBetweenPositions(oDFEnemy:GetPosition(), oEnemy:GetPosition())..'; Enemy DF range='..oDFEnemy[AiBotUnitInfo.refiDFRange]) end
                                                if AiBotUtilities.GetDistanceBetweenPositions(oDFEnemy:GetPosition(), oEnemy:GetPosition()) - (oDFEnemy[AiBotUnitInfo.refiDFRange] or 0) <= 6 then
                                                    bTargetNearDFEnemies = true
                                                    break
                                                end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': bTargetNearDFEnemies='..tostring(bTargetNearDFEnemies)) end
                                        if not(bTargetNearDFEnemies) then
                                            if not(tEnemiesToAttack) then tEnemiesToAttack = {} end
                                            table.insert(tEnemiesToAttack, oEnemy)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Adding to table of enemy units to attack') end
                                        end
                                    end

                                end
                            end
                        end
                    end
                else
                    --Check units are near-constructed
                    for iEnemy = table.getn(tEnemiesToRunFrom), 1, -1 do
                        if tEnemiesToRunFrom[iEnemy]:GetFractionComplete() < 0.7 then --tried with 90% threshold but PD could be built too soon and kill the selens
                            if bDebugMessages == true then LOG(sFunctionRef..': Removing enemy '..tEnemiesToRunFrom[iEnemy].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEnemiesToRunFrom[iEnemy])..' from enemies to run from as it isnt complete yet, fraction complete='..tEnemiesToRunFrom[iEnemy]:GetFractionComplete()) end
                            table.remove(tEnemiesToRunFrom, iEnemy)
                        end
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tEnemiesToRunFrom) then
                --Does enemy have ACU in zone? if so then run; otherwise if enemy has combat units then stay hidden
                if AiBotUtilities.IsTableEmpty(tTargetLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                    tEnemiesToRunFrom = EntityCategoryFilterDown(categories.COMMAND, tTargetLZTeamData[AiBotMap.reftoNearestDFEnemies])
                    local iDistUntilEnemyACUInRangeOfUs = 10000
                    if AiBotConditions.IsTableOfUnitsStillValid(tEnemiesToRunFrom) then
                        for iUnit, oUnit in tEnemiesToRunFrom do
                            iDistUntilEnemyACUInRangeOfUs = math.min(iDistUntilEnemyACUInRangeOfUs, AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oScout:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange])
                        end
                        --Want to run
                        if bDebugMessages == true then LOG(sFunctionRef..': ACU in target zone or near it so want to run if we will be in range of it soon, iDistUntilEnemyACUInRangeOfUs='..iDistUntilEnemyACUInRangeOfUs) end
                    end
                    if iDistUntilEnemyACUInRangeOfUs > 35 then
                        tEnemiesToRunFrom = nil
                        if tTargetLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 100 or tTargetLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] > 10 then
                            --Stay hidden if we are in cloak mode as enemy has combat units; if we arent in cloak mode then run
                            if bInCloakMode and GetGameTimeSeconds() - (oScout[AiBotUnitInfo.refiLastWeaponEvent] or 0) >= 2 then
                                bGivenOrder = true --i.e. order is to do nothing if in cloak mode
                            else
                                tEnemiesToRunFrom = EntityCategoryFilterDown(categories.DIRECTFIRE + categories.INDIRECTFIRE, tTargetLZTeamData[AiBotMap.subrefTEnemyUnits])
                                if bInCloakMode and AiBotUtilities.IsTableEmpty(tEnemiesToRunFrom) == false then bGivenOrder = true end
                            end
                            --Also stay hidden if enemies are in adjacent zone that are near to us
                        elseif bInCloakMode and AiBotUtilities.IsTableEmpty(tTargetLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                            --Check any nearby enemy DF units not assigned to this zone
                            for iEnemy, oEnemy in tTargetLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                if not(oEnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam] == iZone) and AiBotUtilities.GetDistanceBetweenPositions(oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], oScout:GetPosition()) - (oEnemy[AiBotUnitInfo.refiDFRange] or 0) <= 5 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to stay cloaked due to nearby enemy in adjacent zone') end
                                    bGivenOrder = true
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy combat total='..tTargetLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; Enemy DF range='..tTargetLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange]..'; bGivenOrder='..tostring(bGivenOrder)..'; Is tEnemiesToRunFrom empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemiesToRunFrom))) end
                        if not(bGivenOrder) and not(AiBotConditions.IsTableOfUnitsStillValid(tEnemiesToRunFrom)) then
                            tEnemiesToAttack = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryRadar, tTargetLZTeamData[AiBotMap.subrefTEnemyUnits])
                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy engineers and radar empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemiesToAttack))) end
                            if AiBotUtilities.IsTableEmpty(tEnemiesToAttack) then
                                --Does the enemy have mexes for us to attack?
                                tEnemiesToAttack = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tTargetLZTeamData[AiBotMap.subrefTEnemyUnits])
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Is tEnemiesToAttack empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemiesToAttack))) end
                        end
                    end
                else
                    --Enemy has no units, so do nothing and wait
                    if bInCloakMode then bGivenOrder = true end --i.e. order is to do nothing if are already cloaked
                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy has no units in the target zone') end
                end
            end


            --Process what we have decided to do
            if not(bGivenOrder) then
                if bDebugMessages == true then LOG(sFunctionRef..': Not given order yet so deciding whether to run or attack, is tEnemiesToRunFrom empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemiesToRunFrom))..'; is tEnemiesToAttack empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemiesToAttack))..'; refiEnemyAirToGroundThreat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] ) end
                --Consider if we want to cloak to hide from enemy gunships (but not bombers as we might manage to dodge their bombs)
                local bHideFromAir = false
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > 0 then
                    function ConsiderIfWantToCloakFromAir(tZoneTeamData, oScout)
                        if bDebugMessages == true then LOG(sFunctionRef..': Do we want to hide from air for cur zone being considered, refiEnemyAirToGroundThreat='..tZoneTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; Is table of enemy air units empty='..tostring(AiBotUtilities.IsTableEmpty(tZoneTeamData[AiBotMap.reftLZEnemyAirUnits]))) end
                        if tZoneTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 and AiBotUtilities.IsTableEmpty(tZoneTeamData[AiBotMap.reftLZEnemyAirUnits]) == false then
                            for iAir, oAir in tZoneTeamData[AiBotMap.reftLZEnemyAirUnits] do
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to cloak due to nearby gunship, oAir='..oAir.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAir)..'; Dist between scout and this='..AiBotUtilities.GetDistanceBetweenPositions(oAir:GetPosition(), oScout:GetPosition())) end
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryGunship, oAir.UnitId) and AiBotUtilities.GetDistanceBetweenPositions(oAir:GetPosition(), oScout:GetPosition()) <= 70 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to hide from air') end
                                    return true
                                end
                            end
                        end
                    end
                    bHideFromAir = ConsiderIfWantToCloakFromAir(tLCurZTeamData, oScout)
                    if not(bHideFromAir) and AiBotUtilities.IsTableEmpty(tCurLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tCurLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                            local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                            bHideFromAir = ConsiderIfWantToCloakFromAir(tAdjLZTeamData, oScout)
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iAjdLZ='..iAdjLZ..' for if want to run from gunships') end
                            if bHideFromAir then break end
                        end
                    end
                end
                if AiBotUtilities.IsTableEmpty(tEnemiesToRunFrom) == false then
                    if bHideFromAir then
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to try hiding from enemy air by cloaking instead of running from nearby land enemies, oScout='..oScout.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout)..'; bInCloakMode='..tostring(bInCloakMode)) end
                        bGivenOrder = true
                        if bInCloakMode then
                            --Do nothing
                        else
                            AiBotUnitInfo.CloakUnit(oScout)
                            bInCloakMode = true
                        end
                    else
                        --Get the closest and run from here in opposite direction, or towards rally point, unless we are really far away in which case consider just being assigned to a different zone
                        bInCloakMode = false
                        iClosestEnemyDist = 1000
                        oClosestEnemy = nil
                        for iUnit, oUnit in tEnemiesToRunFrom do
                            if AiBotUnitInfo.IsUnitValid(oUnit) then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oScout:GetPosition())
                                if iCurDist < iClosestEnemyDist then
                                    oClosestEnemy = oUnit
                                    iClosestEnemyDist = iCurDist
                                end
                            end

                        end
                        if oClosestEnemy then
                            bGivenOrder = true
                            bInCloakMode = false
                            RunFromEnemy(oScout, oClosestEnemy, iTeam, iPlateau, 10)
                            if bDebugMessages == true then LOG(sFunctionRef..': Running from oClosestEnemy='..oClosestEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy)..'; iClosestEnemyDist='..iClosestEnemyDist..'; tTargetLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..tTargetLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; will also abort lurker logic') end
                            if iClosestEnemyDist > 150 or tTargetLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 100 then
                                ForkThread(ConsiderAssigningScoutToLurkerLogic, oScout)
                                break
                            end
                        end
                    end
                elseif AiBotUtilities.IsTableEmpty(tEnemiesToAttack) == false then
                    iClosestEnemyDist = 100 --Dont want to go further away than this when hunting for targets
                    if bHideFromAir then iClosestEnemyDist = (oScout[AiBotUnitInfo.refiDFRange] or 19) + 5 end --If we arent already in range or almost in range then we wont manage to damage enemy before gunship kills us
                    oClosestEnemy = nil
                    for iUnit, oUnit in tEnemiesToAttack do
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oScout:GetPosition())
                            if iCurDist < iClosestEnemyDist then
                                oClosestEnemy = oUnit
                                iClosestEnemyDist = iCurDist
                            end
                        end

                    end
                    if oClosestEnemy then
                        bInCloakMode = false
                        --Attack
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to attack oClosestEnemy='..oClosestEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy)..'; iClosestEnemyDist='..iClosestEnemyDist..'; iMinAttackDist='..iMinAttackDist) end
                        if iClosestEnemyDist <= iAttackThresholdDist then
                            if iClosestEnemyDist <= iMinAttackDist and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oClosestEnemy.UnitId) then
                                --Dont want to be reclaimed by the engineer, so move back slightly
                                local tMovePoint, tPotentialMovePoint
                                local iAngleFromEngi = AiBotUtilities.GetAngleFromAToB(oClosestEnemy:GetPosition(), oScout:GetPosition())

                                for iAngleAdjust = 0, 90, 45 do
                                    for iFactor = -1, 1, 2 do
                                        tPotentialMovePoint = AiBotUtilities.MoveInDirection(oScout:GetPosition(), iAngleFromEngi + iAngleAdjust * iFactor, 5, true, false, true)
                                        if AiBotUtilities.IsTableEmpty(tPotentialMovePoint) == false and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tPotentialMovePoint) == tTargetLZData[AiBotMap.subrefLZIslandRef] then
                                            tMovePoint = tPotentialMovePoint
                                            break
                                        end
                                    end
                                end
                                if tMovePoint then
                                    bInCloakMode = false
                                    AiBotOrders.IssueTrackedMove(oScout, tMovePoint, 3, false, 'LurkMvEg', oScout[AiBotUnitInfo.refbLowerPriorityMicroActive])
                                    bGivenOrder = true
                                else
                                    --Attack as backup
                                    bInCloakMode = false
                                    AiBotOrders.IssueTrackedAttack(oScout, oClosestEnemy, false, 'LurkAtEg', oScout[AiBotUnitInfo.refbLowerPriorityMicroActive])
                                    bGivenOrder = true
                                end
                            else
                                --Attack enemy, unless it is an engineer that we are getting too close to
                                bInCloakMode = false
                                AiBotOrders.IssueTrackedAttack(oScout, oClosestEnemy, false, 'LurkAtEn', oScout[AiBotUnitInfo.refbLowerPriorityMicroActive])
                                bGivenOrder = true
                            end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': want to move to enemy to attack them') end
                            --Move to enemy
                            bInCloakMode = false
                            AiBotOrders.IssueTrackedMove(oScout, oClosestEnemy:GetPosition(), 3, false, 'LurkMvEn', oScout[AiBotUnitInfo.refbLowerPriorityMicroActive])
                            bGivenOrder = true
                        end
                    elseif bHideFromAir then
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to try hiding from enemy air by cloaking instead of attacking nearby land enemies, oScout='..oScout.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout)..'; bInCloakMode='..tostring(bInCloakMode)) end
                        bGivenOrder = true
                        if bInCloakMode then
                            --Do nothing
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Will give order for unit to try and cloak') end
                            AiBotUnitInfo.CloakUnit(oScout)
                            bInCloakMode = true
                        end
                    end
                    --Consider reassigning if we have multiple selens assigned here
                elseif bHideFromAir then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to try hiding from enemy air by cloaking, oScout='..oScout.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oScout)..'; bInCloakMode='..tostring(bInCloakMode)) end
                    bGivenOrder = true
                    if bInCloakMode then
                        --Do nothing
                    else
                        AiBotUnitInfo.CloakUnit(oScout)
                        bInCloakMode = true
                    end
                elseif not(bGivenOrder) and tTargetLZTeamData[AiBotMap.refiAssignedLurkerCount] >= 3 then
                    if oScout[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iZone and oScout[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau and AiBotUtilities.IsTableEmpty(tTargetLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        local iCurAssignedSelens = 1
                        local tScoutsInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryCombatScout, tTargetLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tScoutsInZone) == false then
                            for iPotentialLurker, oPotentialLurker in tScoutsInZone do
                                if not(oPotentialLurker == oScout) and oPotentialLurker[AiBotUnitInfo.refbLurkerMode] then
                                    iCurAssignedSelens = iCurAssignedSelens + 1
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have too many selens in a zone, iCurAssignedSelens='..iCurAssignedSelens) end
                        if iCurAssignedSelens >= 3 then
                            --Do we have adjacent land zones with mexes and no enemy combat threat?
                            local bReassign = false
                            for _, iAdjLZ in tTargetLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                if (tAdjLZData[AiBotMap.subrefLZOrWZMexCount] or 0) > 0 then
                                    local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 30 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have adjacent zone iAdjLZ='..iAdjLZ..' with insufficient combat threat and it has a mex, so will send this scout for reassignment') end
                                        bReassign = true
                                        break
                                    end
                                end
                            end
                            if bReassign then break end
                        end
                    end
                end
                if not(bGivenOrder) then
                    if bInCloakMode then
                        bGivenOrder = true
                        if bDebugMessages == true then LOG(sFunctionRef..': No actions, as are in cloak mode will remain in cloak mode') end
                    else
                        --We dont have enemies to run from or attack; do we want to move to target, or cloak?
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oScout:GetPosition(), tTargetLZData[AiBotMap.subrefMidpoint])
                        if bDebugMessages == true then LOG(sFunctionRef..': Not given an order, so will either move to target if far away, or clock, iCurDist='..iCurDist) end
                        if iCurDist <= 5 then
                            --Want to cloak
                            bInCloakMode = true
                            AiBotUnitInfo.CloakUnit(oScout)
                            bGivenOrder = true
                        else
                            --Want to move to target
                            bInCloakMode = false
                            AiBotOrders.IssueTrackedMove(oScout, tTargetLZData[AiBotMap.subrefMidpoint], 3, false, 'LurkMvMp', oScout[AiBotUnitInfo.refbLowerPriorityMicroActive])
                            bGivenOrder = true
                        end
                    end
                end
                if not(bGivenOrder) then AiBotUtilities.ErrorHandler('Missing code for an eventuality so selen has no order, bInCloakMode='..tostring(bInCloakMode), true) end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(iTicksPerLandCycle)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    --for if we aborted due to wanting to assign to a dif zone:
    oScout[AiBotUnitInfo.refbLurkerMode] = false
    if oScout[AiBotUnitInfo.refbLowerPriorityMicroActive] then --we might have overridden this with higher priority micro
        oScout[AiBotUnitInfo.refbSpecialMicroActive] = false
        oScout[AiBotUnitInfo.refbLowerPriorityMicroActive] = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedGetFirstEnhancementOnUnit(oUnit, iDelayInSeconds)
    WaitSeconds(iDelayInSeconds)
    local sFunctionRef = 'DelayedGetFirstEnhancementOnUnit'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oUnit) then
        local sFirstEnhancement
        local tEnhancements = oUnit:GetBlueprint().Enhancements
        if tEnhancements then
            if bDebugMessages == true then LOG(sFunctionRef..': tEnhancements='..repru(tEnhancements)) end
            for sEnhancement, tEnhancementData in tEnhancements do
                sFirstEnhancement = sEnhancement
                break
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': sFirstEnhancement='..(sFirstEnhancement or 'nil')..'; oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; oUnit[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Time='..GetGameTimeSeconds()) end
        if sFirstEnhancement and not(oUnit:HasEnhancement(sFirstEnhancement)) then
            while oUnit[AiBotUnitInfo.refbSpecialMicroActive] and AiBotUnitInfo.IsUnitValid(oUnit) do
                WaitSeconds(1)
            end
            if AiBotUnitInfo.IsUnitValid(oUnit) then
                local iTeam = oUnit:GetAIBrain().AiBotTeam
                local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                if bDebugMessages == true then LOG(sFunctionRef..': Is tLZTeamData nil='..tostring(tLZTeamData == nil)..'; tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] or false)..'; tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..(tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 'nil')) end
                if tLZTeamData and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 and (not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange])) then
                    AiBotOrders.IssueTrackedEnhancement(oUnit, sFirstEnhancement, false, 'GetUEnh')
                    --Flag as micro active so we dont abort
                    AiBotMicro.EnableUnitMicroUntilManuallyTurnOff(oUnit)
                    --oUnit[AiBotUnitInfo.refbSpecialMicroActive] = true
                    if oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive] then oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive] = nil end
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished trying to get enhancement for the unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time='..GetGameTimeSeconds()..'; oUnit[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                end
            end
        end
    end
end

function SendSACUsToWaterZone(tSACUs, tLZOrWZTeamData)
    local iWaterZone
    local tOrigRecordedSACUs = tLZOrWZTeamData[AiBotMap.subreftoSACUsTravelingToWaterZoneFromHere]
    local bRecorded
    for iSACU, oSACU in tSACUs do
        iWaterZone = oSACU[AiBotUnitInfo.refiSACUWaterZoneTarget]
        local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
        if tWZData[AiBotMap.subrefMidpoint] then
            AiBotOrders.IssueTrackedMove(oSACU, tWZData[AiBotMap.subrefMidpoint], 5, false, 'MvWZ'..iWaterZone, false)
            bRecorded = false
            if tOrigRecordedSACUs then
                for iRecorded, oRecorded in tOrigRecordedSACUs do
                    if oRecorded == oSACU then
                        bRecorded = true
                        break
                    end
                end
            end
            if not(bRecorded) then
                if not(tLZOrWZTeamData[AiBotMap.subreftoSACUsTravelingToWaterZoneFromHere]) then tLZOrWZTeamData[AiBotMap.subreftoSACUsTravelingToWaterZoneFromHere] = {} end
                table.insert(tLZOrWZTeamData[AiBotMap.subreftoSACUsTravelingToWaterZoneFromHere], oSACU)
            end
        else
            AiBotUtilities.ErrorHandler('SACU doesnt have valid WZ target so clearing')
            oSACU[AiBotUnitInfo.refiSACUWaterZoneTarget] = nil
        end
    end
end

function GetMexesInThisOrAdjacentLandZone(tLZData, tLZTeamData, iTeam, iPlateau, bRequireVisibilityOfMex)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetMexesInThisOrAdjacentLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local toAdjacentEnemyMexes
    local aiBrainForVisibilityCheck
    if bRequireVisibilityOfMex then aiBrainForVisibilityCheck = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]] end
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
            local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
            if bDebugMessages == true then LOG(sFunctionRef..': Checking if enemy has mexes in adjacent LZ, iAdjLZ='..iAdjLZ..'; tAdjLZData[AiBotMap.subrefLZOrWZMexCount]='..(tAdjLZData[AiBotMap.subrefLZOrWZMexCount] or 'nil')..'; Is tAdjLZData[AiBotMap.subrefMexUnbuiltLocations] empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZData[AiBotMap.subrefMexUnbuiltLocations]))) end
            if (tAdjLZData[AiBotMap.subrefLZOrWZMexCount] or 0) > 0 then
                if bDebugMessages == true and AiBotUtilities.IsTableEmpty(tAdjLZData[AiBotMap.subrefMexUnbuiltLocations]) == false then LOG(sFunctionRef..': Size of table of unbuilt locations='..table.getn(tAdjLZData[AiBotMap.subrefMexUnbuiltLocations])) end
                if AiBotUtilities.IsTableEmpty(tAdjLZData[AiBotMap.subrefMexUnbuiltLocations]) or table.getn(tAdjLZData[AiBotMap.subrefMexUnbuiltLocations]) < tAdjLZData[AiBotMap.subrefLZOrWZMexCount] then
                    local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                    if bDebugMessages == true then LOG(sFunctionRef..': subrefThreatEnemyStructureTotalMass='..(tAdjLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 'nil')..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                    if tAdjLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] > 0 and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then

                        local tEnemyMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                        if bDebugMessages == true then LOG(sFunctionRef..': Is tEnemyMexes empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyMexes))) end
                        if AiBotUtilities.IsTableEmpty(tEnemyMexes) == false then
                            for iMex, oMex in tEnemyMexes do
                                if AiBotUnitInfo.IsUnitValid(oMex) and (not(bRequireVisibilityOfMex) or AiBotUnitInfo.CanSeeUnit(aiBrainForVisibilityCheck, oMex)) then
                                    if not(toAdjacentEnemyMexes) then toAdjacentEnemyMexes = {} end
                                    table.insert(toAdjacentEnemyMexes, oMex)
                                    if bDebugMessages == true then LOG(sFunctionRef..': recording enemy oMex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)) end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] > 0 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefMexUnbuiltLocations]) or table.getn(tLZData[AiBotMap.subrefMexUnbuiltLocations]) < tLZData[AiBotMap.subrefLZOrWZMexCount] then
        local tEnemyMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tLZTeamData[AiBotMap.subrefTEnemyUnits])
        if AiBotUtilities.IsTableEmpty(tEnemyMexes) == false then
            for iMex, oMex in tEnemyMexes do
                if AiBotUnitInfo.IsUnitValid(oMex) then
                    if not(toAdjacentEnemyMexes) then toAdjacentEnemyMexes = {} end
                    table.insert(toAdjacentEnemyMexes, oMex)
                    if bDebugMessages == true then LOG(sFunctionRef..': recording enemy oMex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)) end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return toAdjacentEnemyMexes
end

function RecordAttackingExperimental(tLZTeamData, oExperimental)
    local bNotRecorded = true
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoAttackingFriendlyExperimentals]) == false then
        for iExistingExp, oExistingExp in tLZTeamData[AiBotMap.reftoAttackingFriendlyExperimentals] do
            if oExistingExp == oExperimental then
                bNotRecorded = false
                break
            end
        end
    end
    if bNotRecorded then
        if not(tLZTeamData[AiBotMap.reftoAttackingFriendlyExperimentals]) then tLZTeamData[AiBotMap.reftoAttackingFriendlyExperimentals] = {} end
        table.insert(tLZTeamData[AiBotMap.reftoAttackingFriendlyExperimentals], oExperimental)
    end
    oExperimental[AiBotUnitInfo.refiAttackingExperimentalTime] = GetGameTimeSeconds()
end

function HaveAttackingExperimentalToSupport(tLZTeamData)
    if AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.reftoAttackingFriendlyExperimentals]) and AiBotUtilities.IsTableEmpty( tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
        for iExp, oExp in tLZTeamData[AiBotMap.reftoAttackingFriendlyExperimentals] do
            if oExp[AiBotUnitInfo.refiAttackingExperimentalTime] and GetGameTimeSeconds() - oExp[AiBotUnitInfo.refiAttackingExperimentalTime] <= 30 and (oExp[AiBotUnitInfo.refbSpecialMicroActive] or GetGameTimeSeconds() - oExp[AiBotUnitInfo.refiAttackingExperimentalTime] <= 10) then
                --Is this experimental close to a DF enemy?
                local iDistanceThreshold = math.max(30, math.min((oExp[AiBotUnitInfo.refiDFRange] or 0) + 5, 50))
                for iEnemy, oEnemy in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                    if AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oExp:GetPosition()) <= iDistanceThreshold then return true end
                end
            end
        end
    end
end

function ConsiderAssigningRaider(oFactory, oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderAssigningRaider'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true and not(oUnit.Dead) then LOG(sFunctionRef..': Start of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' built by oFactory='..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..' and owned by '..oUnit:GetAIBrain().Nickname..'; considering whether will be a raider, combatrange='..( oUnit[AiBotUnitInfo.refiCombatRange] or 'nil')..'; oFactory[AiBotFactory.refiTotalBuildCount]='..(oFactory[AiBotFactory.refiTotalBuildCount] or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if oUnit[AiBotUnitInfo.refiCombatRange] >= 28 and ((oFactory[AiBotFactory.refiTotalBuildCount] or 0) >= 4 or not(EntityCategoryContains(categories.TECH1, oFactory.UnitId))) and AiBotUnitInfo.IsUnitValid(oUnit) and AiBotUnitInfo.IsUnitValid(oFactory) and AiBotUnitInfo.GetUnitLifetimeCount(oUnit)  >= 3 and GetGameTimeSeconds() >= 300 then
        local iTeam = oFactory:GetAIBrain().AiBotTeam
        local iBuildPlateau = oFactory[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
        if bDebugMessages == true then LOG(sFunctionRef..' iBuildPlateau='..(iBuildPlateau or 'nil')..'; iBuildZone='..(oFactory[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or 'nil')) end
        if iBuildPlateau and iBuildPlateau > 0 then
            local iBuildZone = oFactory[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
            if iBuildZone and iBuildZone > 0 then
                local tBuildLZData = AiBotMap.tAllPlateaus[iBuildPlateau][AiBotMap.subrefPlateauLandZones][iBuildZone]
                local tBuildLZTeamData = tBuildLZData[AiBotMap.subrefLZTeamData][iTeam]

                if not(tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget]) then
                    GetRaidingZoneTarget(iBuildPlateau, iBuildZone, iTeam, oUnit[AiBotUnitInfo.refiCombatRange] - 3)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': subrefiCurRaidingZoneTarget='..(tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget] or 'nil')) end
                if tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget] then
                    tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiPotentialRaiderUnitsSinceLastCreatedRaiderAssigned] = (tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiPotentialRaiderUnitsSinceLastCreatedRaiderAssigned] or 0) + 1
                    --Dont raid if nearby firebase/t2 arti
                    if (tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersCreatedByThisZone] or 0) < 4 and (tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiPotentialRaiderUnitsSinceLastCreatedRaiderAssigned] >= 4 or not(tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiTimeSinceLastConstructedRaiderAssignment])) and GetGameTimeSeconds() - (tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiTimeSinceLastConstructedRaiderAssignment] or 0) >= 30 and AiBotUtilities.IsTableEmpty(tBuildLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) and AiBotUtilities.IsTableEmpty(tBuildLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
                        GetRaidingZoneTarget(iBuildPlateau, iBuildZone, iTeam, oUnit[AiBotUnitInfo.refiCombatRange] - 3) --Will reassess if been a while since we last considered best zone to raid
                        local iTargetZone = tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget]
                        if iTargetZone then
                            local tTargetLZTeamData = AiBotMap.tAllPlateaus[iBuildPlateau][AiBotMap.subrefPlateauLandZones][iTargetZone][AiBotMap.subrefLZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': iTargetZone='..(iTargetZone or 'nil')..'; subrefiActiveRaidersTargetingThisZone='..((tTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersTargetingThisZone] or 'nil'))) end
                            if (tTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersTargetingThisZone] or 0) < 2 then
                                --Check we dont want t1 arti for a transport
                                local bWantT1ArtiForTransport = false
                                if AiBotUtilities.IsTableEmpty(tBuildLZTeamData[AiBotMap.reftoTransportsWaitingForUnits]) == false then
                                    for iTransport, oTransport in tBuildLZTeamData[AiBotMap.reftoTransportsWaitingForUnits] do
                                        if (oTransport[AiBotAir.refiEngisWanted] or 0) > 0 or not(oTransport[AiBotAir.refbCombatDrop]) then
                                            --Transport waiting for engis
                                        elseif (oTransport[AiBotAir.refiCombatUnitsWanted] or 0) > 0 then
                                            bWantT1ArtiForTransport = true
                                            break
                                        end
                                    end
                                end
                                if not(bWantT1ArtiForTransport) then
                                    AssignUnitAsRaiderForTargetZone(oUnit, iTargetZone, iBuildPlateau, iBuildZone)
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AssignUnitAsRaiderForTargetZone(oUnit, iTargetZone, iOptionalBuildPlateau, iOptionalBuildZone)
    --If iOptionalBuildPlateau and iOptionalBuildZone arent specified then unit should already have them recorded (otherwise have an error/issue)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssignUnitAsRaiderForTargetZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Starto f code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..'; iTargetZone='..iTargetZone..'; iOptionalBuildPlateau='..(iOptionalBuildPlateau or 'nil')..'; iOptionalBuildZone='..(iOptionalBuildZone or 'nil')..'; oUnit[refiRaidingBasePlateau]='..(oUnit[refiRaidingBasePlateau] or 'nil')..'; refiRaidingTargetZone='..(oUnit[refiRaidingTargetZone] or 'nil')) end
    local iTeam = oUnit:GetAIBrain().AiBotTeam
    local bFirstTimeAssigning = true
    if oUnit[refiRaidingBasePlateau] or oUnit[refiRaidingTargetZone] then bFirstTimeAssigning = false end

    if iOptionalBuildPlateau then oUnit[refiRaidingBasePlateau] = iOptionalBuildPlateau end
    if iOptionalBuildZone then oUnit[refiRaidingBaseZone] = iOptionalBuildZone end
    local tBuildLZData = AiBotMap.tAllPlateaus[oUnit[refiRaidingBasePlateau]][AiBotMap.subrefPlateauLandZones][oUnit[refiRaidingBaseZone]]
    local tBuildLZTeamData = tBuildLZData[AiBotMap.subrefLZTeamData][iTeam]
    if oUnit.Dead then ClearUnitRaiderStatus(oUnit, iTeam) --redundancy
    elseif tBuildLZTeamData then
        if not(bFirstTimeAssigning) then ClearUnitRaiderStatus(oUnit, iTeam, true) end
        oUnit[refiRaidingTargetZone] = iTargetZone
        oUnit[refbFlaggedForPriorityScout] = true
        local tTargetLZTeamData = AiBotMap.tAllPlateaus[oUnit[refiRaidingBasePlateau]][AiBotMap.subrefPlateauLandZones][iTargetZone][AiBotMap.subrefLZTeamData][iTeam]

        if tTargetLZTeamData then
            if not(tTargetLZTeamData[AiBotMap.reftRaiderSubtable]) then
                tTargetLZTeamData[AiBotMap.reftRaiderSubtable] = {}
            end
            tTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersTargetingThisZone] = (tTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersTargetingThisZone] or 0) + 1
            tTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiLifetimeRaidersTargetingThisZone] = (tTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiLifetimeRaidersTargetingThisZone] or 0) + 1
        else
            AiBotUtilities.ErrorHandler('Trying to assign raider to invalid zone, P'..(oUnit[refiRaidingBasePlateau] or 'nil')..'Z'..(iTargetZone or 'nil'))
        end
        if bFirstTimeAssigning then
            if not(tBuildLZTeamData[AiBotMap.reftRaiderSubtable]) then
                AiBotUtilities.ErrorHandler('Base raider zone lacks a subtable')
                if tBuildLZTeamData then tBuildLZTeamData[AiBotMap.reftRaiderSubtable] = {} end
            end
            tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersCreatedByThisZone] = (tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersCreatedByThisZone] or 0) + 1
            tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiTimeSinceLastConstructedRaiderAssignment] = GetGameTimeSeconds()
            tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiPotentialRaiderUnitsSinceLastCreatedRaiderAssigned] = 0
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetRaidingZoneTarget(iStartPlateau, iStartZone, iTeam, iRangeThreshold, iOptionalZoneToIgnore)
    --Updates subrefiCurRaidingZoneTarget to the zone to target (or nil if we didnt find any suitable ones)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetRaidingZoneTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tBuildLZData = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iStartZone]
    local tBuildLZTeamData = tBuildLZData[AiBotMap.subrefLZTeamData][iTeam]
    if bDebugMessages == true then LOG(sFunctionRef..': iStartPlateau='..(iStartPlateau or 'nil')..'; iStartZone='..(iStartZone or 'nil')..'; iTeam='..iTeam..'; iRangeThreshold='..iRangeThreshold..'; iOptionalZoneToIgnore='..(iOptionalZoneToIgnore or 'nil')..'; is tBuildLZTeamData nil='..tostring(tBuildLZTeamData == nil)) end
    if not(tBuildLZTeamData[AiBotMap.reftRaiderSubtable]) then
        if tBuildLZTeamData then
            tBuildLZTeamData[AiBotMap.reftRaiderSubtable] = {}
        else
            AiBotUtilities.ErrorHandler('Invalid plateau or zone reference, P'..(iStartPlateau or 'nil')..'Z'..(iStartZone or 'nil'))
        end
    end
    if tBuildLZTeamData and (tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget] or GetGameTimeSeconds() - (tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiTimeLastCheckedForZoneToTarget] or 0) >= 30) then
        tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiTimeLastCheckedForZoneToTarget] = math.floor(GetGameTimeSeconds())

        --Decide what zone to target
        local iFirstZoneNoRaiderLimit
        local iLifetimeAssignmentForFirstZone
        local iFirstZoneWithRaiderLimit
        local iFirstLRThreatZoneDist --the first zone we find that is unsuitable due to enemy having t2 arti/longer ranged DF units should be recorded here
        local iFirstZoneRaiderAndAngleLimit
        local iAngleThreshold = 60
        local iAngleToNearestBase = AiBotUtilities.GetAngleFromAToB(tBuildLZData[AiBotMap.subrefMidpoint], tBuildLZTeamData[AiBotMap.reftClosestFriendlyBase])
        local iCurAngle
        function ConsiderTargetingZone(iCurZone, iOptionalDist)
            if not(iCurZone == iOptionalZoneToIgnore) then
                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iCurZone][AiBotMap.subrefLZTeamData][iTeam]
                if (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] >= iRangeThreshold or tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] >= iRangeThreshold or AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false or tAdjLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > 0)
                        --Also look for enemies that have caused us to run that havent moved much
                        or (AiBotUnitInfo.IsUnitValid(tAdjLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefoLastEnemyDFLastRunFromWhenTryingToReachThisZone]) and tAdjLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefoLastEnemyDFLastRunFromWhenTryingToReachThisZone][AiBotUnitInfo.refiDFRange] >= iRangeThreshold and AiBotUtilities.GetDistanceBetweenPositions(tAdjLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefoLastEnemyDFLastRunFromWhenTryingToReachThisZone]:GetPosition(), tAdjLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subreftLastEnemyDFLastRunFromWhenTryingToReachThisZonePosition]) <= 80) then
                    if not(iFirstLRThreatZoneDist) then iFirstLRThreatZoneDist = iOptionalDist or AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iCurZone][AiBotMap.subrefMidpoint], tBuildLZData[AiBotMap.subrefMidpoint]) end
                else
                    if (tAdjLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) > 0 then
                        --We want to raid unless this zone already has raiders assigned or has mobile DF units already there that can attack
                        if not(iFirstZoneNoRaiderLimit) then
                            iFirstZoneNoRaiderLimit = iCurZone
                            iLifetimeAssignmentForFirstZone = (tAdjLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiLifetimeRaidersTargetingThisZone] or 0)
                        end
                        if (tAdjLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersTargetingThisZone] or 0) < 2 and tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] == 0 and (iLifetimeAssignmentForFirstZone < 2 or (tAdjLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiLifetimeRaidersTargetingThisZone] or 0) < iLifetimeAssignmentForFirstZone) then
                            if not(iFirstZoneWithRaiderLimit) then
                                iFirstZoneWithRaiderLimit = iCurZone
                            end
                            --Prefer targets far from angle to enemy base since more likely will raid targets less likely to be under attack from our normal land combat logic
                            iCurAngle = AiBotUtilities.GetAngleFromAToB(tBuildLZData[AiBotMap.subrefMidpoint], AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iCurZone][AiBotMap.subrefMidpoint])
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iCurZone='..iCurZone..'; iCurAngle='..iCurAngle..'; iAngleToNearestBase='..iAngleToNearestBase..'; ANgleDif='..AiBotUtilities.GetAngleDifference(iCurAngle, iAngleToNearestBase)..'; iOptionalDist='..(iOptionalDist or 'nil')..'; StraightlineDist='..AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iCurZone][AiBotMap.subrefMidpoint], tBuildLZData[AiBotMap.subrefMidpoint])) end
                            if AiBotUtilities.GetAngleDifference(iCurAngle, iAngleToNearestBase) > iAngleThreshold then
                                iFirstZoneRaiderAndAngleLimit = iCurZone
                            end
                        end
                    end
                end

                if not(tBuildLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iCurZone]) then
                    AiBotMap.ConsiderAddingTargetLandZoneToDistanceFromBaseTable(iStartPlateau, iStartZone, iCurZone, tBuildLZData[AiBotMap.subrefMidpoint])
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tBuildLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
            local iAdjLZ
            for iPathingRef, tPathingDetails in tBuildLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                if iFirstLRThreatZoneDist and tPathingDetails[AiBotMap.subrefLZTravelDist] - 200 > iFirstLRThreatZoneDist then break end
                iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
                ConsiderTargetingZone(iAdjLZ, tPathingDetails[AiBotMap.subrefLZTravelDist])
                if iFirstZoneRaiderAndAngleLimit then break end
            end
        else
            --Just look at adjacent zones (no need for distance check)
            if AiBotUtilities.IsTableEmpty(tBuildLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tBuildLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    ConsiderTargetingZone(iAdjLZ)
                    if iFirstZoneRaiderAndAngleLimit then break end
                end
            end
        end
        --Update current zone target tracking
        function RecordNewZoneTarget(iZoneBeingTargeted)
            if iZoneBeingTargeted then
                local tNewZoneTargetLZTeamData = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iZoneBeingTargeted][AiBotMap.subrefLZTeamData][iTeam]
                if tNewZoneTargetLZTeamData then
                    if not(tNewZoneTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subreftiZonesTargetingThisForRaids]) then
                        if not(tNewZoneTargetLZTeamData[AiBotMap.reftRaiderSubtable]) then tNewZoneTargetLZTeamData[AiBotMap.reftRaiderSubtable] = {} end
                        tNewZoneTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subreftiZonesTargetingThisForRaids] = {}
                    end
                    table.insert(tNewZoneTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subreftiZonesTargetingThisForRaids], iStartZone)
                end
            end
            tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget] = iZoneBeingTargeted
        end

        local iNewZoneTarget = (iFirstZoneRaiderAndAngleLimit or iFirstZoneWithRaiderLimit or iFirstZoneNoRaiderLimit)
        local iCurZoneTarget = tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget]
        if iCurZoneTarget then
            if iCurZoneTarget == iNewZoneTarget then
                --Already tracking
            else
                --Remove curzonetarget as it has changed
                local tCurZoneTargetLZTeamData = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iCurZoneTarget][AiBotMap.subrefLZTeamData][iTeam]
                if AiBotUtilities.IsTableEmpty(tCurZoneTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subreftiZonesTargetingThisForRaids]) == false then
                    for iEntry, iRecordedTargetZone in tCurZoneTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subreftiZonesTargetingThisForRaids] do
                        if iRecordedTargetZone == iCurZoneTarget then
                            table.remove(tCurZoneTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subreftiZonesTargetingThisForRaids], iEntry)
                            break
                        end
                    end
                end
                RecordNewZoneTarget(iNewZoneTarget)
            end
        elseif iNewZoneTarget then
            --Update tracking
            RecordNewZoneTarget(iNewZoneTarget)
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Updated subrefiCurRaidingZoneTarget, iFirstZoneRaiderAndAngleLimit='..(iFirstZoneRaiderAndAngleLimit or 'nil')..'; iFirstZoneWithRaiderLimit='..(iFirstZoneWithRaiderLimit or 'nil')..'; iFirstZoneNoRaiderLimit='..(iFirstZoneNoRaiderLimit or 'nil')..'; tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget]='..(tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget] or 'nil')) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageRaidersInLandZone(tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, tRaiders)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageRaidersInLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tEnemiesToConsiderRunningFrom = {}
    local tbUnitByEntityID = {}
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
        for iEnemy, oEnemy in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
            table.insert(tEnemiesToConsiderRunningFrom, oEnemy)
            tbUnitByEntityID[oEnemy.EntityId] = true
        end
    end
    --Consider adjacent zone DF enemies
    if GetGameTimeSeconds() - (tLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiTimeLastDoneDetailedEnemyCheck] or 0) >= 10.4 then
        if not(tLZTeamData[AiBotMap.reftRaiderSubtable]) then
            tLZTeamData[AiBotMap.reftRaiderSubtable] = {}
        end
        tLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiTimeLastDoneDetailedEnemyCheck] = math.floor(GetGameTimeSeconds())
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                    for iEnemy, oEnemy in tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                        if not(tbUnitByEntityID[oEnemy.EntityId]) then
                            table.insert(tEnemiesToConsiderRunningFrom, oEnemy)
                            tbUnitByEntityID[oEnemy.EntityId] = true
                        end
                    end
                end
            end
        end
    end
    --Add in closest enemy to run from recorded for each raider in the zone
    for iRaider, oRaider in tRaiders do
        if AiBotUnitInfo.IsUnitValid(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and (oRaider[AiBotUnitInfo.refiDFRange] or 0) > 0 then
            if not(tbUnitByEntityID[oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].EntityId]) then
                table.insert(tEnemiesToConsiderRunningFrom, oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])
                tbUnitByEntityID[oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].EntityId] = true
            end
        end
    end

    local bAllRaidersMovingOn = AiBotUtilities.IsTableEmpty(tEnemiesToConsiderRunningFrom)

    local bRaiderMovingOn, iCurDist, iClosestDist, oClosestImmobile, bRunning, tRallyPoint
    for iRaider, oRaider in tRaiders do
        if not(bAllRaidersMovingOn) and AiBotConditions.CloseToEnemyUnit(oRaider:GetPosition(), tEnemiesToConsiderRunningFrom, math.max(5, (oRaider[AiBotUnitInfo.refiCombatRange]-25) * 0.3), iTeam, true, 3, oRaider, oRaider, oRaider[AiBotUnitInfo.refiCombatRange] - 4, false) then
            --Run from enemy if it has an attack, or just do manual attack order (or attack ground if unit not visible but is immovable and isnt TMD)
            if bDebugMessages == true then LOG(sFunctionRef..': Raider is close to one of the enemies toconsider running from, oRaider='..oRaider.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRaider)..'; refoClosestEnemyFromLastCloseToEnemyUnitCheck]='..oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])..'; Dist to this unit='..AiBotUtilities.GetDistanceBetweenPositions(oRaider:GetPosition(), oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())..'; Dist to last known position of the enemy unit='..AiBotUtilities.GetDistanceBetweenPositions(oRaider:GetPosition(), oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; Enemy Units range='..oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange]..'; Raiders range='..(oRaider[AiBotUnitInfo.refiCombatRange] or 0)..'; CanSeeUnit='..tostring(AiBotUnitInfo.CanSeeUnit(oRaider:GetAIBrain(), oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck], false))..'; Row2Cond='..tostring(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] + 1 >= oRaider[AiBotUnitInfo.refiCombatRange])..'; Row3Cond='..tostring((not(AiBotUnitInfo.CanSeeUnit(oRaider:GetAIBrain(), oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck], false)) and not(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId == 'url0104') and oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] >= (oRaider:GetBlueprint().Intel.VisionRadius or 18)))..'; Row4Cond='..tostring(AiBotUtilities.GetDistanceBetweenPositions(oRaider:GetPosition(), oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) < oRaider[AiBotUnitInfo.refiCombatRange] - 2)..'; Row5Cond='..tostring((AiBotUnitInfo.GetUnitSpeed(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) > 0.1 and not(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId == 'url0104')))) end
            if ((oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] or 0) > 0 and
                    (oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] >= oRaider[AiBotUnitInfo.refiCombatRange]
                            or (not(AiBotUnitInfo.CanSeeUnit(oRaider:GetAIBrain(), oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck], false)) and not(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId == 'url0104') and oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] >= (oRaider:GetBlueprint().Intel.VisionRadius or 18))
                            or (AiBotUtilities.GetDistanceBetweenPositions(oRaider:GetPosition(), oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) < oRaider[AiBotUnitInfo.refiCombatRange] - 2 and (not(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId == 'url0104') or AiBotUnitInfo.GetUnitSpeed(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) > 0.1))
                            or (AiBotUnitInfo.GetUnitSpeed(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) > 0.1 and not(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId == 'url0104'))))
                    or EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId) then
                RunFromEnemy(oRaider, oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck], iTeam, iPlateau, 10)
                --If enemy outranges us then dont want to raid any more
                if (oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 0) >= oRaider[AiBotUnitInfo.refiCombatRange] then
                    ClearUnitRaiderStatus(oRaider, iTeam, true, oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])
                end
            else
                if AiBotUnitInfo.CanSeeUnit(oRaider:GetAIBrain(), oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck], false) or EntityCategoryContains(AiBotUnitInfo.refCategoryStructure - AiBotUnitInfo.refCategoryTMD, oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId) then
                    AiBotOrders.IssueTrackedAttack(oRaider, oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck], false, 'RaidAt')
                elseif oRaider[AiBotUnitInfo.refiCombatRange] > oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] + 1 and AiBotUnitInfo.GetUnitSpeed(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) < 0.1 and AiBotUtilities.GetDistanceBetweenPositions( oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 1 then
                    AiBotOrders.IssueTrackedGroundAttack(oRaider, oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam], 0.5, false, 'RaidAG', false, oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])
                else
                    AiBotOrders.IssueTrackedAttackMove(oRaider, oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), 3, false, 'RaidAM')
                end
            end
        else
            --Is there a unit in this zone we want to attack?
            bRaiderMovingOn = true
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                iClosestDist = 10000
                oClosestImmobile = nil
                for iEnemy, oEnemy in tLZTeamData[AiBotMap.subrefTEnemyUnits] do
                    --Check building or immobile unit (but ignore selens that might be cloaked)
                    if (EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oEnemy.UnitId) or AiBotUnitInfo.GetUnitSpeed(oEnemy) <= 0.1) and (oEnemy[AiBotUnitInfo.refiDFRange] or 0) < oRaider[AiBotUnitInfo.refiCombatRange] and (not(oEnemy.UnitId == 'xsl0101') or AiBotUnitInfo.CanSeeUnit(oRaider:GetAIBrain(), oEnemy)) then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oRaider:GetPosition(), oEnemy:GetPosition())
                        if iCurDist < iClosestDist then
                            iClosestDist = iCurDist
                            oClosestImmobile = oEnemy
                        end
                    end
                end
                if oClosestImmobile then
                    bRaiderMovingOn = false
                    bRunning = false
                    --Woudl we get near the closest enemy to run from if we target this unit?
                    if (oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 0) >= oRaider[AiBotUnitInfo.refiCombatRange] and AiBotUnitInfo.IsUnitValid(oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) then
                        local iAngleToNearestThreat = AiBotUtilities.GetAngleFromAToB(oRaider:GetPosition(), oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())
                        local iAngleToImmobileTarget = AiBotUtilities.GetAngleFromAToB(oRaider:GetPosition(), oClosestImmobile:GetPosition())
                        if AiBotUtilities.GetAngleDifference(iAngleToNearestThreat, iAngleToImmobileTarget) <= 50 and iClosestDist - oRaider[AiBotUnitInfo.refiCombatRange] <= math.max(0, AiBotUtilities.GetDistanceBetweenPositions(oRaider:GetPosition(), oRaider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition()) - (oRaider[AiBotUnitInfo.refiDFRange] or 0)) then
                            if oRaider[refiRaidingTargetZone] == iLandZone then
                                bRunning = true
                                if not(tRallyPoint) then tRallyPoint = GetNearestLandRallyPoint(tLZData, iTeam, iPlateau, iLandZone, 1, false) end
                                AiBotOrders.IssueTrackedAttackMove(oRaider, tRallyPoint, 3, false, 'RaidRetRal', false)
                            else
                                bRaiderMovingOn = true
                            end
                        end
                    end
                    if not(bRaiderMovingOn) then
                        if AiBotUnitInfo.CanSeeUnit(oRaider:GetAIBrain(), oClosestImmobile, false) or EntityCategoryContains(AiBotUnitInfo.refCategoryStructure - AiBotUnitInfo.refCategoryTMD, oClosestImmobile.UnitId) then
                            AiBotOrders.IssueTrackedAttack(oRaider, oClosestImmobile, false, 'RaidImAt')
                        else
                            AiBotOrders.IssueTrackedAttackMove(oRaider, oClosestImmobile:GetPosition(), 3, false, 'RaidIMAM')
                        end
                    end
                end
            end
            if bRaiderMovingOn then
                --Move to target zone unless we are already there
                if oRaider[refiRaidingTargetZone] == iLandZone then
                    --Reassess where to raid
                    GetRaidingZoneTarget(iPlateau, iLandZone, iTeam, oRaider[AiBotUnitInfo.refiCombatRange] - 3)
                    if (tLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget] or 0) > 0 then
                        --AssignUnitAsRaiderForTargetZone(oUnit, iTargetZone, iOptionalBuildPlateau, iOptionalBuildZone, bFirstTimeAssigning)
                        AssignUnitAsRaiderForTargetZone(oRaider, tLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget])
                    else
                        ClearUnitRaiderStatus(oRaider, iTeam)
                    end
                else
                    local tTargetZoneLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][oRaider[refiRaidingTargetZone]]
                    AiBotOrders.IssueTrackedAttackMove(oRaider, tTargetZoneLZData[AiBotMap.subrefMidpoint], 3, false, 'RaidMvLZ'..oRaider[refiRaidingTargetZone], false)
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ClearUnitRaiderStatus(oUnit, iTeam, bOnlyRemoveFromCurTargetZone, oOptionalEnemyCausingUsToRun)
    --set bOnlyRemoveFromCurTargetZone to true if raider is being reassigned (false if unit has died/is permantnly being removed as a raider)
    local iOldTargetZone = oUnit[refiRaidingTargetZone]
    local tOldTargetLZTeamData = AiBotMap.tAllPlateaus[oUnit[refiRaidingBasePlateau]][AiBotMap.subrefPlateauLandZones][iOldTargetZone][AiBotMap.subrefLZTeamData][iTeam]
    if tOldTargetLZTeamData then
        if oOptionalEnemyCausingUsToRun then
            --Dont want to send further raiders here unless they have a better range
            tOldTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiEnemyDFRangeLastRunFromWhenTryingToReachThisZone] = oOptionalEnemyCausingUsToRun[AiBotUnitInfo.refiDFRange]
            tOldTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefoLastEnemyDFLastRunFromWhenTryingToReachThisZone] = oOptionalEnemyCausingUsToRun
            tOldTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subreftLastEnemyDFLastRunFromWhenTryingToReachThisZonePosition] = {oOptionalEnemyCausingUsToRun:GetPosition()[1], oOptionalEnemyCausingUsToRun:GetPosition()[2], oOptionalEnemyCausingUsToRun:GetPosition()[3]}
        end
        --Remove existing tracking
        tOldTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersTargetingThisZone] = (tOldTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersTargetingThisZone] or 0) - 1
        tOldTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiLifetimeRaidersTargetingThisZone] = (tOldTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiLifetimeRaidersTargetingThisZone] or 0) - 1
    end
    local tBuildLZData = AiBotMap.tAllPlateaus[oUnit[refiRaidingBasePlateau]][AiBotMap.subrefPlateauLandZones][oUnit[refiRaidingBaseZone]]
    local tBuildLZTeamData = tBuildLZData[AiBotMap.subrefLZTeamData][iTeam]
    if tBuildLZTeamData then
        if bOnlyRemoveFromCurTargetZone then
            --Reassess what zone the original should target for raids if it is this
            if tOldTargetLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiCurRaidingZoneTarget] == iOldTargetZone then GetRaidingZoneTarget(oUnit[refiRaidingBasePlateau], oUnit[refiRaidingBaseZone], iTeam, oUnit[AiBotUnitInfo.refiCombatRange] - 3, iOldTargetZone) end
        else
            --Remove from base zone
            tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersCreatedByThisZone] = math.max(0, (tBuildLZTeamData[AiBotMap.reftRaiderSubtable][AiBotMap.subrefiActiveRaidersCreatedByThisZone] or 0) - 1)
        end
    end
    if not(bOnlyRemoveFromCurTargetZone) then oUnit[refbFlaggedForPriorityScout] = nil end
end

function GetClosestExperimentalWantingMAAGuards(iPlateauWanted, iIslandWanted, iTeam, tPosition, iMinPosition)
    local iClosestExp = iMinPosition
    local oClosestExp, iCurDist
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoFriendlyLandExperimentals]) == false then
        for iExp, oExp in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoFriendlyLandExperimentals] do
            if oExp[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateauWanted and (not(iIslandWanted) or NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oExp:GetPosition()) == iIslandWanted)
                    and not(EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oExp.UnitId)) then
                if not(AiBotConditions.IsTableOfUnitsStillValid(oExp[reftoAssignedMAAGuards])) or table.getn(oExp[reftoAssignedMAAGuards]) < 4 then
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oExp:GetPosition(), tPosition)
                    if iCurDist < iClosestExp then
                        iClosestExp = iCurDist
                        oClosestExp = oExp
                    end
                end
            end
        end
    end
    return oClosestExp
end

function GetNearbyEnemyBaseLocationToSuicideYthotha(oUnit, tClosestEnemyBase, iMaxDistFromBase, iTeam)
    --Returns the location to suicide ythotha into enemy base, if we want to
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetNearbyEnemyBaseLocationToSuicideYthotha'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist to tClosestEnemyBase='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tClosestEnemyBase)..'; iMaxDistFromBase='..iMaxDistFromBase) end
    if AiBotUnitInfo.IsUnitValid(oUnit) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tClosestEnemyBase) <= iMaxDistFromBase then
        --Check unit is in the same zone as enemy base (so can cehck for enemy experimentals nearby)
        local iBasePlateau, iBaseZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tClosestEnemyBase)
        if bDebugMessages == true then LOG(sFunctionRef..': Unit recorded against P'..(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or 'nil')..'Z'..(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or 'nil')..'; Enemy base is in iBasePlateau='..(iBasePlateau or 'nil')..'; iBaseZone='..(iBaseZone or 'nil')) end
        if iBasePlateau and iBaseZone and iBasePlateau > 0 and iBasePlateau == oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] and iBaseZone == oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] then
            --Check enemy has significant mass in buildings here
            local tBaseLZData = AiBotMap.tAllPlateaus[iBasePlateau][AiBotMap.subrefPlateauLandZones][iBaseZone]
            local tBaseLZTeamData = tBaseLZData[AiBotMap.subrefLZTeamData][iTeam]
            if bDebugMessages == true then LOG(sFunctionRef..': subrefThreatEnemyStructureTotalMass]'..(tBaseLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0)) end
            if (tBaseLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) >= 15000 then
                local aiBrain = oUnit:GetAIBrain()
                --Lightning storm has radius of 20, so go with 18 aoe since might be blocked by buildings
                --GetBestAOETarget(aiBrain, tBaseLocation, iAOE, iDamage, bOptionalCheckForSMD, tSMLLocationForSMDCheck, iOptionalTimeSMDNeedsToHaveBeenBuiltFor, iSMDRangeAdjust, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, iOptionalMaxDistanceCheckOptions, iMobileValueOverrideFactorWithin75Percent, iOptionalShieldReductionFactor, iOptionalReclaimFactor, bIncludePreviouslySeenEnemies)
                local tBestTarget, iDamage = AiBotLogic.GetBestAOETarget(aiBrain, tClosestEnemyBase, 18, 40000, false, nil, nil, nil, 0.5, 0.5, 6, 0.05, nil, nil, false)
                if bDebugMessages == true then LOG(sFunctionRef..': iDamage from best aoe target='..iDamage) end
                if iDamage >= 10000 and tBestTarget then
                    local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tBestTarget)
                    if bDebugMessages == true then LOG(sFunctionRef..': iDistToTarget='..iDistToTarget) end
                    if iDistToTarget <= 25 or iDamage >= 15000 or iDamage >= 10000+ 5000 * (iDistToTarget - 25) / (iMaxDistFromBase - 25) then
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return tBestTarget
                    end
                end
            end
        end
    end
end